Card Hand::removeCard(const Card& card)
{
  auto it = std::find(cards.begin(), cards.end(), card);
  if (it != cards.end())
  {
    Card copy = *it;
    cards.erase(it);
    return copy;
  }
  // Return a default-constructed card if the specified card is not found
  return Card{};
}
std::list<CardId> Hand::getIds(std::function<bool(const Card&)> predicate)
{
  std::list<CardId> ids;
  for (const auto& card : cards)
  {
    if (predicate(card))
    {
      ids.push_back(card.id);
    }
  }
  return ids;
}

