class MemoryBuffer {
private:
    char* address;
    size_t size;
public:
    MemoryBuffer(char* addr, size_t sz) : address(addr), size(sz) {}
    void memcpy(void* source, size_t offset, size_t size) {
        if (offset + size > this->size) {
            std::cerr << "Error: memcpy operation exceeds buffer size" << std::endl;
            return;
        }
        char* dataPtr = static_cast<char*>(source);
        std::memcpy(this->address + offset, dataPtr, size);
    }
};
int main() {
    char buffer[10];
    MemoryBuffer mem(buffer, 10);
    char source[] = "Hello";
    mem.memcpy(source, 2, 3); // Copies "llo" to buffer starting from index 2
    for (int i = 0; i < 10; i++) {
        std::cout << buffer[i];
    }
    return 0;
}

#include <Eigen/Dense>
#include <sstream>
#include <stdexcept>
template <std::size_t N>
Eigen::Matrix<double, N, 1> toVectorNd(const std::string& str) {
    Eigen::Matrix<double, N, 1> result;
    std::istringstream iss(str);
    double value;
    std::size_t count = 0;
    while (iss >> value) {
        if (count >= N) {
            throw std::invalid_argument("Input string contains more values than the specified vector size");
        }
        result(count, 0) = value;
        count++;
    }
    if (count != N) {
        throw std::invalid_argument("Input string does not contain enough values for the specified vector size");
    }
    if (!iss.eof()) {
        throw std::runtime_error("Error parsing input string");
    }
    return result;
}

