namespace {
bool validateCertificate(const net::x509_certificate& certificate, const net::x509_certificate& caCertificate) {
    // Check certificate expiration
    if (certificate.not_after() < net::x509_util::current_time()) {
        return false; // Certificate has expired
    }
    // Verify certificate signature against the trusted CA certificate
    net::ssl_info sslInfo;
    sslInfo.set_cert(&certificate);
    sslInfo.set_issuer(&caCertificate);
    return net::x509_util::VerifySignedBy(&sslInfo);
}
