    Cone(double r, double h) : radius(r), height(h) {}
    double calculateVolume() {
        return (1.0 / 3.0) * PI * radius * radius * height;
    }
    double calculateSurfaceArea() {
        return PI * radius * (radius + sqrt(radius * radius + height * height));
    }
};
