class InsertValue {
private:
    std::string columnName;
    Document jsonDocument;
public:
    InsertValue(const std::string& column, const Document& doc) : columnName(column), jsonDocument(doc) {}
    std::string toJSON() const {
        StringBuffer buffer;
        Writer<StringBuffer> writer(buffer);
