void writeReducedDataToNetCDF(const std::vector<double>& h_column_data, const std::string& colfile_name) {
    // Perform reduction operation
    amrex::ParallelDescriptor::ReduceRealSum(h_column_data.data(), h_column_data.size(), amrex::ParallelDescriptor::IOProcessorNumber());
    // Write data to NetCDF file (only executed by the I/O processor)
    if (amrex::ParallelDescriptor::IOProcessor()) {
        auto ncf = ncutils::NCFile::open(colfile_name, NC_WRITE | NC_NETCDF4);
        size_t putloc = ncf.dim("ntime").len();
        // Write cumulative time
        amrex::Real cumtime = erf.parent->cumTime();
        ncf.putVar("cumulative_time", &cumtime);
        // Write reduced data
        ncf.putVar("reduced_data", h_column_data.data(), h_column_data.size());
        // Close the NetCDF file
        ncf.close();
    }
}

