bool sameLine(int c1, int c2, int c3, int c4) {
    return (c1 == c3) || (c2 == c4);
}
bool sameDiagonal(int c1, int c2, int c3, int c4) {
    return (abs(c1 - c3) == abs(c2 - c4));
}
