    int c1, c2, c3, c4;
    std::cin >> c1 >> c2 >> c3 >> c4;
    if (c1 == c3 && c2 == c4) {
        std::cout << 0; // No moves required
    } else if (sameLine(c1, c2, c3, c4) || sameDiagonal(c1, c2, c3, c4)) {
        std::cout << 1; // One move required to transform the point
    } else {
        std::cout << 2; // Two moves required to transform the point
    }
    return 0;
}

