  struct DigitallySigned {
    enum HashAlgorithm {
      HASH_ALGO_SHA256,
      // Other hash algorithms may be defined here
    };
    enum SignatureAlgorithm {
      SIG_ALGO_ECDSA,
      // Other signature algorithms may be defined here
    };
    HashAlgorithm hash_algorithm;
    SignatureAlgorithm signature_algorithm;
    std::string signature_data;
  };
  bool EncodeDigitallySigned(const DigitallySigned& digitally_signed, std::string* encoded) {
    if (encoded == nullptr) {
      return false;  // Invalid pointer
    }
    // Encode hash algorithm
    char hash_char;
    switch (digitally_signed.hash_algorithm) {
      case DigitallySigned::HASH_ALGO_SHA256:
        hash_char = 'S';
        break;
      // Handle other hash algorithms if defined
      default:
        hash_char = 'M';  // Default representation for other hash algorithms
        break;
    }
    // Encode signature algorithm
    char sig_char;
    switch (digitally_signed.signature_algorithm) {
      case DigitallySigned::SIG_ALGO_ECDSA:
        sig_char = 'E';
        break;
      // Handle other signature algorithms if defined
      default:
        sig_char = 'O';  // Default representation for other signature algorithms
        break;
    }
    // Append encoded representation to the string
    *encoded = hash_char + sig_char + digitally_signed.signature_data;
    return true;  // Encoding successful
  }
