std::pair<std::string, std::shared_ptr<hyrise::storage::AbstractTable>> loadQueryAndReference(const std::string& numberString) {
    std::string query;
    std::shared_ptr<hyrise::storage::AbstractTable> refTable;
    // Load table file using storage manager
    auto* sm = io::StorageManager::getInstance();
    sm->loadTableFile("refTable", "tpcch/query" + numberString + "_result.tbl");
    // Load query from file
    std::ifstream file("test/tpcch/query" + numberString + ".json");
    if (file.is_open()) {
        std::string line;
        while (std::getline(file, line)) {
            query += line;
        }
        file.close();
    } else {
        std::cerr << "Error: Unable to open query file." << std::endl;
    }
    // Retrieve reference table from storage manager
    refTable = sm->getTable("refTable");
    return std::make_pair(query, refTable);
}

#include <iostream>
class Differentiator {
public:
    Differentiator() : uZ1(0), yZ1(0) {}
    // Computes the derivative using the backward difference method
    unsigned int Differentiate(unsigned int input) {
        unsigned int derivative = input - uZ1;
        uZ1 = input;
        yZ1 = derivative;
        return derivative;
    }
    // Resets the internal state variables to zero
    void ClearStateVars() {
        uZ1 = 0;
        yZ1 = 0;
    }
private:
    unsigned int uZ1;  // Previous input value
    unsigned int yZ1;  // Previous output value
};
int main() {
    Differentiator differentiator;
    std::cout << differentiator.Differentiate(5) << std::endl;  // Output: 5
    std::cout << differentiator.Differentiate(8) << std::endl;  // Output: 3
    differentiator.ClearStateVars();
    std::cout << differentiator.Differentiate(10) << std::endl;  // Output: 10
    return 0;
}

#include <iostream>
