int main(){
  std::vector<int> freqs(10, 0);
  std::cout << "Enter the number: ";
  long int num;
  std::cin >> num;
  // Handle negative numbers
  if (num < 0) {
    num = -num;
  }
  // Calculate the frequency of each digit
  while (num > 0) {
    int digit = num % 10;
    freqs[digit]++;
    num /= 10;
  }
  // Output the frequency of each digit
  for (int i = 0; i < 10; i++) {
    std::cout << i << ": " << freqs[i] << std::endl;
  }
  return 0;
}

