#include <catch2/catch_test_macros.hpp>
#include <yams/daemon/resource/plugin_content_extractor_adapter.h>
using namespace yams::daemon;
TEST_CASE("PluginContentExtractorAdapter supportsExternal cached only", "[daemon][extractor]") {
    SECTION("Matches MIME type from cache") {
        PluginContentExtractorAdapter adapter(
            nullptr, "test_plugin", {"application/x-executable", "application/octet-stream"},
            {".exe", ".bin"}, std::chrono::seconds{30});
        REQUIRE(adapter.supports("application/x-executable", ""));
        REQUIRE(adapter.supports("application/octet-stream", ""));
    }
    SECTION("Matches extension with dot") {
        PluginContentExtractorAdapter adapter(nullptr, "test_plugin", {"application/x-executable"},
                                              {".exe", ".bin"}, std::chrono::seconds{30});
        REQUIRE(adapter.supports("", ".exe"));
        REQUIRE(adapter.supports("", ".bin"));
    }
    SECTION("Matches extension without dot") {
        PluginContentExtractorAdapter adapter(nullptr, "test_plugin", {}, {".exe", ".bin"},
                                              std::chrono::seconds{30});
        REQUIRE(adapter.supports("", "exe"));
        REQUIRE(adapter.supports("", "bin"));
    }
    SECTION("Returns false for unsupported types without RPC") {
        PluginContentExtractorAdapter adapter(nullptr, "test_plugin", {"text/plain"}, {".txt"},
                                              std::chrono::seconds{30});
        REQUIRE_FALSE(adapter.supports("application/pdf", ""));
        REQUIRE_FALSE(adapter.supports("", ".pdf"));
        REQUIRE_FALSE(adapter.supports("image/png", ".png"));
    }
    SECTION("Empty inputs return false") {
        PluginContentExtractorAdapter adapter(nullptr, "test_plugin", {"text/plain"}, {".txt"},
                                              std::chrono::seconds{30});
        REQUIRE_FALSE(adapter.supports("", ""));
    }
    SECTION("isExternal returns true for external backend") {
        PluginContentExtractorAdapter adapter(nullptr, "test_plugin", {"text/plain"}, {".txt"},
                                              std::chrono::seconds{30});
        REQUIRE(adapter.isExternal());
    }
}

#define SOL_ALL_SAFETIES_ON 1
#define SOL_ENABLE_INTEROP \
	1 // MUST be defined to use interop features
#include <sol/sol.hpp>
#include <iostream>
// kaguya code lifted from README.md,
// written by satoren:
// https://github.com/satoren/kaguya
// Copyright [redacted]
// Distributed under the Boost Software License, Version 1.0.
// (See accompanying file LICENSE_1_0.txt or copy at
// http://www.boost.org/LICENSE_1_0.txt)
struct ABC {
	ABC() : v_(0) {
	}
	ABC(int value) : v_(value) {
	}
	int value() const {
		return v_;
	}
	void setValue(int v) {
		v_ = v;
	}
	void overload1() {
		std::cout << "call overload1" << std::endl;
	}
	void overload2(int) {
		std::cout << "call overload2" << std::endl;
	}
private:
	int v_;
};
template <typename T, typename Handler>
inline bool sol_lua_interop_check(sol::types<T>, lua_State* L,
     int relindex, sol::type index_type, Handler&& handler,
     sol::stack::record& tracking) {
	// just marking unused parameters for no compiler warnings
	(void)index_type;
	(void)handler;
	// using 1 element
	tracking.use(1);
	int index = lua_absindex(L, relindex);
	// use kaguya's own detail wrapper check to see if it's
	// correct
	bool is_correct_type
	     = kaguya::detail::object_wrapper_type_check(L, index);
	return is_correct_type;
}
template <typename T>
inline std::pair<bool, T*> sol_lua_interop_get(sol::types<T>,
     lua_State* L, int relindex, void* unadjusted_pointer,
     sol::stack::record& tracking) {
	// you may not need to specialize this method every time:
	// some libraries are compatible with sol2's layout
	// kaguya's storage of data is incompatible with sol's
	// it stores the data directly in the pointer, not a pointer
	// inside of the `void*` therefore, leave the raw userdata
	// pointer as-is, if it's of the right type
	int index = lua_absindex(L, relindex);
	if (!kaguya::detail::object_wrapper_type_check(L, index)) {
		return { false, nullptr };
	}
	// using 1 element
	tracking.use(1);
	kaguya::ObjectWrapperBase* base
	     = kaguya::object_wrapper(L, index);
	return { true, static_cast<T*>(base->get()) };
}
void register_sol_stuff(lua_State* L) {
	// grab raw state and put into state_view
	// state_view is cheap to construct
	sol::state_view lua(L);
	// bind and set up your things: everything is entirely
	// self-contained
	lua["f"] = sol::overload(
	     [](ABC& from_kaguya) {
		     std::cout << "calling 1-argument version with "
		                  "kaguya-created ABC { "
		               << from_kaguya.value() << " }"
		               << std::endl;
		     SOL_ASSERT(from_kaguya.value() == 24);
	     },
	     [](ABC& from_kaguya, int second_arg) {
		     std::cout << "calling 2-argument version with "
		                  "kaguya-created ABC { "
		               << from_kaguya.value()
		               << " } and integer argument of "
		               << second_arg << std::endl;
		     SOL_ASSERT(from_kaguya.value() == 24);
		     SOL_ASSERT(second_arg == 5);
	     });
}
void check_with_sol(lua_State* L) {
	sol::state_view lua(L);
	ABC& obj = lua["obj"];
	(void)obj;
	SOL_ASSERT(obj.value() == 24);
}
int main(int, char*[]) {
	std::cout << "=== interop example (kaguya) ==="
	          << std::endl;
	std::cout << "(code lifted from kaguya's README examples: "
	             "https://github.com/satoren/kaguya)"
	          << std::endl;
	kaguya::State state;
	state["ABC"].setClass(
	     kaguya::UserdataMetatable<ABC>()
	          .setConstructors<ABC(), ABC(int)>()
	          .addFunction("get_value", &ABC::value)
	          .addFunction("set_value", &ABC::setValue)
	          .addOverloadedFunctions(
	               "overload", &ABC::overload1, &ABC::overload2)
	          .addStaticFunction("nonmemberfun",
	               [](ABC* self, int) { return 1; }));
	register_sol_stuff(state.state());
	state.dostring(R"(
obj = ABC.new(24)
f(obj) -- call 1 argument version
f(obj, 5) -- call 2 argument version
)");
	check_with_sol(state.state());
	return 0;
}

#include "compiler/mir/constants.h"
#include "compiler/context.h"
#include <cstdint>
using namespace COMPILER;
MConstantInt *MConstantInt::get(CompileContext &Ctx, MType &Ty, APInt V) {
  // get an existing value or the insertion position
  MConstantInt *&Slot = Ctx.IntConstants[V];
  if (!Slot) {
    // Get the corresponding integer type for the bit width of the value.
    Slot = reinterpret_cast<MConstantInt *>(Ctx.ThreadMemPool.allocate(
        sizeof(MConstantInt), alignof(MConstantInt)));
    new (Slot) MConstantInt(Ty, V);
  }
  return Slot;
}
MConstantInt *MConstantInt::get(CompileContext &Ctx, MType &Ty, uint64_t V) {
  return MConstantInt::get(Ctx, Ty, APInt(Ty.getBitWidth(), V, Ty.isSigned()));
}
MConstantFloat *MConstantFloat::get(CompileContext &Ctx, MType &Ty, APFloat V) {
  // get an existing value or the insertion position
  MConstantFloat *&Slot = Ctx.FPConstants[V];
  if (!Slot) {
    // Get the corresponding integer type for the bit width of the value.
    Slot = reinterpret_cast<MConstantFloat *>(Ctx.ThreadMemPool.allocate(
        sizeof(MConstantFloat), alignof(MConstantFloat)));
    new (Slot) MConstantFloat(Ty, V);
  }
  return Slot;
}
MConstantFloat *MConstantFloat::get(CompileContext &Ctx, MType &Ty, float V) {
  return MConstantFloat::get(Ctx, Ty, APFloat(V));
}
MConstantFloat *MConstantFloat::get(CompileContext &Ctx, MType &Ty, double V) {
  return MConstantFloat::get(Ctx, Ty, APFloat(V));
}
void MConstant::print(llvm::raw_ostream &OS) const {
  if (Type.isInteger()) {
    const MConstantInt *ConstInt = cast<MConstantInt>(this);
    ConstInt->getValue().print(OS, ConstInt->getType().isSigned());
  } else if (Type.isFloat()) {
    const MConstantFloat *ConstFloat = cast<MConstantFloat>(this);
    const APFloat &APF = ConstFloat->getValue();
    SmallVector<char, 16> Buf;
    APF.toString(Buf);
    OS << Buf;
  } else {
    ZEN_UNREACHABLE();
  }
}
#if !defined(NDEBUG) || defined(LLVM_ENABLE_DUMP)
void MConstant::dump() const { print(llvm::dbgs()); }
#endif

