class Solution {
public:
    int firstBadVersion(int n) {
        int kk;
        for(int i=n;i>0;i--){
            if(isBadVersion(i)){
                kk=i;
            }
            else break;
        }
        return kk;

    }
};

class Solution {
public:
    bool searchMatrix(vector<vector<int>>& matrix, int target) {
        int n=matrix.size();
        int m=matrix[0].size();
        int i=0;
        int j=m-1;
        while(i<n && j>=0){
            int currNum=matrix[i][j];
            if(currNum>target){
                j--;
            }
            else if(currNum<target){
                i++;
            }
            else return true;
        }
        return false;
    }
};

class Solution {
public:
     int missingNumber(vector<int>& nums) {
        int n=nums.size();
        sort(nums.begin(),nums.end());
        for(int i=0;i<n;i++){
            if(nums[i]!=i){
                return i;
            }
        }
        return nums.size();
    }
};

