#include <Application.h>
#include <Bitmap.h>
#include <BitmapStream.h>
#include <File.h>
#include <TranslationUtils.h>
#include <TranslatorRoster.h>
#include <iostream>
#include <cstring>
class SaveImageApp : public BApplication
{
public:
	SaveImageApp(int argc, char** argv)
		:
		BApplication("application/x-vnd.demo-imageexporter"),
		fArgc(argc),
		fArgv(argv)
	{
	}
	void ReadyToRun() override
	{
		if (fArgc < 2) {
			std::cout << "Usage: " << fArgv[0] << " <input_image>" << std::endl;
			PostMessage(B_QUIT_REQUESTED);
			return;
		}
		const char* inputFile = fArgv[1];
		// Load the original image
		BBitmap* bmp = BTranslationUtils::GetBitmapFile(inputFile);
		if (!bmp) {
			std::cout << "Failed to load " << inputFile << std::endl;
			PostMessage(B_QUIT_REQUESTED);
			return;
		}
		// Prepare the bitmap stream
		BBitmapStream stream(bmp);
		// Get the system translator roster
		BTranslatorRoster* roster = BTranslatorRoster::Default();
		if (!roster) {
			std::cout << "Failed to get translator roster" << std::endl;
			delete bmp;
			PostMessage(B_QUIT_REQUESTED);
			return;
		}
		// Save as JPEG
		BFile outJPEG("exported_image.jpg",
			B_CREATE_FILE | B_ERASE_FILE | B_WRITE_ONLY);
		status_t status = roster->Translate(&stream, nullptr, nullptr, &outJPEG, B_JPEG_FORMAT);
		if (status != B_OK) {
			std::cout << "Failed to save JPEG: " << strerror(status) << std::endl;
		} else {
			std::cout << "Saved JPEG: exported_image.jpg" << std::endl;
		}
		// Reset the stream for PNG
		stream.Seek(0, SEEK_SET);
		// Save as PNG
		BFile outPNG("exported_image.png",
			B_CREATE_FILE | B_ERASE_FILE | B_WRITE_ONLY);
		status = roster->Translate(&stream, nullptr, nullptr, &outPNG, B_PNG_FORMAT);
		if (status != B_OK) {
			std::cout << "Failed to save PNG: " << strerror(status) << std::endl;
		} else {
			std::cout << "Saved PNG: exported_image.png" << std::endl;
		}
		delete bmp;
		PostMessage(B_QUIT_REQUESTED);	// Quit application
	}
private:
	int fArgc;
	char** fArgv;
};
int main(int argc, char** argv)
{
	SaveImageApp app(argc, argv);
	app.Run();
	return 0;
}

#include <iostream>
#include <vector>
using namespace std;
/*
Dutch National Flag Algorithm
The Dutch National Flag Algorithm is a well-known algorithm developed by Edsger Dijkstra, which efficiently sorts an array containing
only three distinct values. The idea is to partition the array into three sections, usually represented by three colors of the Dutch
national flag: red, white, and blue.
In the context of an array, you can think of these three colors as three distinct values, such as 0, 1, and 2, which are commonly used
in problems where you're asked to sort an array containing only these three values.
Problem: Given an array with elements 0, 1, and 2, sort the array using the Dutch National Flag algorithm.
Algorithm Explanation:
You use three pointers: low, mid, and high.
low keeps track of the boundary for elements less than 1 (0's).
mid is used to scan the array.
high keeps track of the boundary for elements greater than 1 (2's).
The idea is to traverse the array with the mid pointer, and swap elements to the appropriate sections:
If the element at mid is 0, it should go to the low section, so you swap it with the element at the low pointer and move both low and
 mid forward.
If the element at mid is 1, it's already in the correct position, so just move mid forward.
If the element at mid is 2, it should go to the high section, so you swap it with the element at the high pointer and move high backward.
*/
class Solution {
    public:
       void sortColors(vector<int>& nums) {  

        int low = 0, mid = 0, high = nums.size() - 1;
        while(mid <= high){
            if(nums[mid] == 0){
                swap(nums[mid], nums[low]);
                mid++;
                low++;
            }
            else if(nums[mid] == 1) mid++;
            else{
                swap(nums[mid], nums[high]);
                high--;
            }
        }

       }
};
