                std::cout << "         Line: " << line << std::endl;
                fail_count++;
            }
        }
    }
    if (fail_count > 0) {
        std::cout << "  Total failures: " << fail_count << std::endl;
    }
    ASSERT_TRUE(fail_count == 0);
}
