#include <iostream>
#include <vector>
#include <queue>
#include <list>
using namespace std;
// Only for Directed Acyclic Graphs (DAGs)
// Graph class definition for Kahn's Algorithm
class Graph {
    int V; // Number of vertices
    list<int>* adj; // Adjacency list representation
public:
    Graph(int V) {
        this->V = V;
        adj = new list<int>[V];
    }
    void addEdge(int u, int v) {
        adj[u].push_back(v); // Add edge from u to v
    }

    void topologicalSortKahn() {
        vector<int> inDegree(V, 0);
        // Calculate in-degrees of all vertices
        for (int u = 0; u < V; u++) {
            for (int v : adj[u]) {
                inDegree[v]++;
            }
        }
        queue<int> q;
        // Enqueue all vertices with in-degree 0
        for (int i = 0; i < V; i++) {
            if (inDegree[i] == 0) {
                q.push(i);
            }
        }
        vector<int> topoOrder;
        while (!q.empty()) {
            int u = q.front();
            q.pop();
            topoOrder.push_back(u);
            // Decrease in-degree of neighboring vertices
            for (int v : adj[u]) {
                inDegree[v]--;
                if (inDegree[v] == 0) {
                    q.push(v);
                }
            }
        }
        // Check if there was a cycle
        if (topoOrder.size() != V) {
            cout << "Graph has a cycle, topological sort not possible." << endl;
            return;
        }
        // Print topological order
        cout << "Topological Sort (Kahn's Algorithm): ";
        for (int v : topoOrder) {
            cout << v << " ";
        }
        cout << endl;
    }
    void printGraph() {
        for (int i = 0; i < V; i++) {
            cout << "Adjacency list of vertex " << i << ": ";
            for (int v : adj[i]) {
                cout << v << " ";
            }
            cout << endl;
        }
    }
    ~Graph() {
        delete[] adj;
    }
};
int main() {
    Graph g(6); // Create a graph with 6 vertices
    g.addEdge(5, 2);
    g.addEdge(5, 0);
    g.addEdge(4, 0);
    g.addEdge(4, 1);
    g.addEdge(2, 3);
    g.addEdge(3, 1);
    // Kahn's Algorithm implementation would go here to perform topological sort
    g.topologicalSortKahn();
    return 0;
}
// Kahn's Algorithm 
// We do not use visited array here with bfs and dfs because we are using in-degree array to keep track of visited nodes.
// Time Complexity: O(V + E) where V is the number of vertices and E is the number of edges.
// Space Complexity: O(V) for the in-degree array and the queue.
// steps
// 1. Calculate in-degrees of all vertices.
// 2. Enqueue all vertices with in-degree 0.
// 3. While the queue is not empty, dequeue a vertex, add it to the topological order, and decrease the in-degree of its neighbors.
// 4. If any neighbor's in-degree becomes 0, enqueue it.
// 5. If the size of the topological order is not equal to the number of vertices, the graph has a cycle.
// 6. Print the topological order.
// Example Output:
// Topological Sort (Kahn's Algorithm): 5 4 2 3 1 0

#include <iostream>
#include <vector>
#include <numeric>
#include <algorithm>
// Function to interact with the judge
int query(int l, int r) {
    if (l >= r) {
        // This case should be prevented by the main logic
        return -1;
    }
    std::cout << "? " << l << " " << r << std::endl;
    int result;
    std::cin >> result;
    return result;
}
// Main logic for a single test case
void solve() {
    int n;
    std::cin >> n;
    int l = 1, r = n;
    while (l < r) {
        // Base case for a range of size 2
        if (r - l == 1) {
            int s = query(l, r);
            if (s == l) {
                l = r;
            } else {
                r = l;
            }
            break;
        }
        // Query the current range to find the position of the second max
        int s = query(l, r);
        // Handle edge cases where the second max is at an endpoint
        if (s == l) {
            l = s + 1;
            continue;
        }
        if (s == r) {
            r = s - 1;
            continue;
        }

        // At this point, l < s < r. The max is either in [l, s-1] or [s+1, r].
        // We make a second query to determine which side.
        // To optimize, we query the smaller of the two potential ranges containing s.
        if (s - l < r - s) {
            int s2 = query(l, s);
            if (s2 == s) {
                // The max of p[l...s] is in [l, s-1]. Since p[s] is the second max
                // of the larger range [l, r], this element must be the overall max.
                // So, we narrow our search to [l, s-1].
                r = s - 1;
            } else {
                // The max of p[l...s] is at position s. This means the overall max
                // of p[l...r] cannot be in [l, s-1]. It must be in [s+1, r].
                l = s + 1;
            }
        } else {
            int s2 = query(s, r);
            if (s2 == s) {
                // Symmetrical to the case above. The max of p[s...r] is in [s+1, r].
                // This must be the overall max of p[l...r].
                l = s + 1;
            } else {
                // The max of p[s...r] is at position s. The overall max must be in [l, s-1].
                r = s - 1;
            }
        }
    }
    std::cout << "! " << l << std::endl;
}
int main() {
    // Fast I/O
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(NULL);
    int t;
    std::cin >> t;
    while (t--) {
        solve();
    }
    return 0;
}

