#define SOL_ALL_SAFETIES_ON 1
#include <sol/sol.hpp>
#include <iostream>
int my_exception_handler(lua_State* L,
     sol::optional<const std::exception&> maybe_exception,
     sol::string_view description) {
	// L is the lua state, which you can wrap in a state_view if
	// necessary maybe_exception will contain exception, if it
	// exists description will either be the what() of the
	// exception or a description saying that we hit the
	// general-case catch(...)
	std::cout << "An exception occurred in a function, here's "
	             "what it says ";
	if (maybe_exception) {
		std::cout << "(straight from the exception): ";
		const std::exception& ex = *maybe_exception;
		std::cout << ex.what() << std::endl;
	}
	else {
		std::cout << "(from the description parameter): ";
		std::cout.write(description.data(),
		     static_cast<std::streamsize>(description.size()));
		std::cout << std::endl;
	}
	// you must push 1 element onto the stack to be
	// transported through as the error object in Lua
	// note that Lua -- and 99.5% of all Lua users and libraries
	// -- expects a string so we push a single string (in our
	// case, the description of the error)
	return sol::stack::push(L, description);
}
void will_throw() {
	throw std::runtime_error("oh no not an exception!!!");
}
int main() {
	std::cout << "=== exception_handler ===" << std::endl;
	sol::state lua;
	lua.open_libraries(sol::lib::base);
	lua.set_exception_handler(&my_exception_handler);
	lua.set_function("will_throw", &will_throw);
	sol::protected_function_result pfr = lua.safe_script(
	     "will_throw()", &sol::script_pass_on_error);
	SOL_ASSERT(!pfr.valid());
	sol::error err = pfr;
	std::cout << err.what() << std::endl;
	std::cout << std::endl;
	return 0;
}

#include <iostream>
#include <vector>
#include <string>
// Helper function to perform a query and read the response.
char query(int c) {
    std::cout << "? " << c << std::endl;
    char response;
    std::cin >> response;
    return response;
}
// Helper function to perform a reset.
void reset() {
    std::cout << "R" << std::endl;
}
// Helper function to output the final answer.
void answer(int d) {
    std::cout << "! " << d << std::endl;
}
int main() {
    // Use fast I/O.
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(NULL);
    int n, k;
    std::cin >> n >> k;
    // is_first[i] is true if we haven't found a j < i with a_j = a_i.
    // We start by assuming all bakeries are unique.
    std::vector<bool> is_first(n + 1, true);
    int block_size = k;
    int num_blocks = n / block_size;
    // Iterate over all pairs of blocks (i, j) where i <= j.
    for (int i = 0; i < num_blocks; ++i) {
        for (int j = i; j < num_blocks; ++j) {
            reset();

            if (i == j) {
                // Handle intra-block duplicates.
                // For each potentially unique bakery, query it. A 'Y' means it's a
                // duplicate of a bakery previously queried within this same block.
                for (int u_idx = i * block_size + 1; u_idx <= (i + 1) * block_size; ++u_idx) {
                    if (is_first[u_idx]) {
                        if (query(u_idx) == 'Y') {
                            is_first[u_idx] = false;
                        }
                    }
                }
            } else {
                // Handle inter-block duplicates.
                // First, load potentially unique items from block i into memory.
                for (int u_idx = i * block_size + 1; u_idx <= (i + 1) * block_size; ++u_idx) {
                    if (is_first[u_idx]) {
                        query(u_idx);
                    }
                }
                // Then, check items from block j against memory.
                // A 'Y' means it's a duplicate of something in block i or an earlier
                // element in block j.
                for (int v_idx = j * block_size + 1; v_idx <= (j + 1) * block_size; ++v_idx) {
                    if (is_first[v_idx]) {
                        if (query(v_idx) == 'Y') {
                            is_first[v_idx] = false;
                        }
                    }
                }
            }
        }
    }
    // Count the number of bakeries that are the first of their cake type.
    int distinct_count = 0;
    for (int i = 1; i <= n; ++i) {
        if (is_first[i]) {
            distinct_count++;
        }
    }
    answer(distinct_count);
    return 0;
}

#include <iostream>
using namespace std;
// Function to implement Selection Sort
void selectionSort(int arr[], int n) {
    for (int i = 0; i < n - 1; i++) {
        int minIndex = i;  // Assume the current position is the smallest

        // Find the smallest element in the unsorted portion of the array
        for (int j = i + 1; j < n; j++) {
            if (arr[j] < arr[minIndex]) {
                minIndex = j;
            }
        }
        // Swap the found minimum element with the first element of the unsorted portion
        if (minIndex != i) {
            swap(arr[i], arr[minIndex]);
        }
    }
}
// Function to print the array
void printArray(int arr[], int n) {
    for (int i = 0; i < n; i++) {
        cout << arr[i] << " ";
    }
    cout << endl;
}
int main() {
    int arr[] = {64, 25, 12, 22, 11};
    int n = sizeof(arr) / sizeof(arr[0]);
    cout << "Original array: ";
    printArray(arr, n);
    selectionSort(arr, n);
    cout << "Sorted array: ";
    printArray(arr, n);
    return 0;
}

#include "ros2_medkit_gateway/type_introspection.hpp"
#include <sstream>
#include <stdexcept>
#include "ros2_medkit_serialization/json_serializer.hpp"
#include "ros2_medkit_serialization/serialization_error.hpp"
namespace ros2_medkit_gateway {
TypeIntrospection::TypeIntrospection(const std::string & /* scripts_path */)
  : serializer_(std::make_shared<ros2_medkit_serialization::JsonSerializer>()) {
  // scripts_path is deprecated and ignored - we use native serialization now
}
nlohmann::json TypeIntrospection::get_type_template(const std::string & type_name) {
  try {
    return serializer_->get_defaults(type_name);
  } catch (const ros2_medkit_serialization::TypeNotFoundError & e) {
    throw std::runtime_error("Unknown type: " + type_name + " (" + e.what() + ")");
  } catch (const std::exception & e) {
    throw std::runtime_error("Failed to get type template: " + std::string(e.what()));
  }
}
nlohmann::json TypeIntrospection::get_type_schema(const std::string & type_name) {
  try {
    return serializer_->get_schema(type_name);
  } catch (const ros2_medkit_serialization::TypeNotFoundError & e) {
    throw std::runtime_error("Unknown type: " + type_name + " (" + e.what() + ")");
  } catch (const std::exception & e) {
    throw std::runtime_error("Failed to get type schema: " + std::string(e.what()));
  }
}
TopicTypeInfo TypeIntrospection::get_type_info(const std::string & type_name) {
  // Check cache first
  {
    std::lock_guard<std::mutex> lock(cache_mutex_);
    auto it = type_cache_.find(type_name);
    if (it != type_cache_.end()) {
      return it->second;
    }
  }
  // Build type info using native serializer
  TopicTypeInfo info;
  info.name = type_name;
  // Get template (default values)
  try {
    info.default_value = get_type_template(type_name);
  } catch (const std::exception & e) {
    // If template fails, use empty object
    info.default_value = nlohmann::json::object();
  }
  // Get schema (type structure)
  try {
    info.schema = get_type_schema(type_name);
  } catch (const std::exception & e) {
    // If schema fails, use empty object
    info.schema = nlohmann::json::object();
  }
  // Cache it (use try_emplace to avoid overwriting if another thread added it first)
  {
    std::lock_guard<std::mutex> lock(cache_mutex_);
    auto [it, inserted] = type_cache_.try_emplace(type_name, info);
    return it->second;  // Return cached version (may be from another thread)
  }
}
}  // namespace ros2_medkit_gateway

#include "ELD/PluginAPI/PluginVersion.h"
