        if (pressed) {
            int          iCurrentBitmaskIndex = 0;
            unsigned int uiDebugBitmask       = 0L;
            for (int i = 0; i < m_iTotalCheckboxElements; i++) {
                uiDebugBitmask |= m_checkboxes[i].IsChecked()
                                    ? (1 << iCurrentBitmaskIndex)
                                    : 0;
                iCurrentBitmaskIndex++;
