            if (uiDebugBitmask != app.GetGameSettingsDebugMask(iPad)) {
                app.SetGameSettingsDebugMask(iPad, uiDebugBitmask);
                if (app.DebugSettingsOn()) {
                    app.ActionDebugMask(iPad);
