    const std::regex hfUrlPattern(
        R"(^https://huggingface\.co/[a-zA-Z0-9_-]+/[a-zA-Z0-9_-]+/resolve/main/.+\.onnx$)");
    for (const auto& model : EXPECTED_MODELS) {
        INFO("Checking model: " << model.name);
