#define ROCPROFSYS_PUBLIC_API   __attribute__((visibility("default")));
#define ROCPROFSYS_HIDDEN_API   __attribute__((visibility("hidden")));
#define ROCPROFSYS_INTERNAL_API __attribute__((visibility("internal")));
#include <dlfcn.h>
