using namespace sdb::options;
Section::Section(const std::string& name, const std::string& description,
                 const std::string& link, const std::string& alias, bool hidden,
                 bool obsolete)
  : name(name),
    description(description),
    link(link),
    alias(alias),
    hidden(hidden),
    obsolete(obsolete) {}
Section::~Section() = default;
std::string Section::displayName() const {
  return alias.empty() ? name : alias;
}
// whether or not the section has (displayable) options
bool Section::hasOptions() const {
  if (!hidden) {
    for (const auto& it : options) {
      if (!it.second.hasFlag(sdb::options::Flags::Uncommon)) {
        return true;
      }
    }
  }
  return false;
}
// print help for a section
// the special search string "." will show help for all sections, even if hidden
void Section::printHelp(const std::string& search, size_t tw, size_t ow,
                        bool colors) const {
  if (search != "." && (hidden || !hasOptions())) {
    return;
  }
  std::cout << "Section '" << (colors ? colors::kBright : "") << displayName()
            << (colors ? colors::kReset : "") << "' (configure " << description
            << ")";
  if (!link.empty()) {
    std::cout << " [";
    if (colors) {
      std::cout << colors::kLinkStart << link << colors::kLinkMiddle << link
                << colors::kLinkEnd;
    } else {
      std::cout << link;
    }
    std::cout << "]";
  }
  std::cout << std::endl;
  auto hl = headlines.begin();
  // propagate print command to options
  for (const auto& it : options) {
    if (hl != headlines.end() && it.first >= (*hl).first) {
      // must print a headline
      std::cout << " # " << (*hl).second << std::endl;
      ++hl;
    }
    if (it.second.hasFlag(sdb::options::Flags::Obsolete)) {
      // skip obsolete options
      continue;
    }
    // print help for option
    it.second.printHelp(search, tw, ow, colors);
  }
  std::cout << std::endl;
}
// determine display width for a section
size_t Section::optionsWidth() const {
  size_t width = 0;
  if (!hidden) {
    for (const auto& it : options) {
      width = std::max(width, it.second.optionsWidth());
    }
  }
  return width;
}

#include <iostream>
#include <csignal>
#include <atomic>
#include <lemon/cli_parser.h>
#include <lemon/server.h>
#include <lemon/single_instance.h>
#include <lemon/version.h>
#include <lemon/utils/aixlog.hpp>
#ifndef _WIN32
#include <unistd.h>
#endif
using namespace lemon;
// Global flag for signal handling
static std::atomic<bool> g_shutdown_requested(false);
static Server* g_server_instance = nullptr;
// Signal handler for Ctrl+C, SIGTERM, and SIGHUP
void signal_handler(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
#ifndef _WIN32
        const char* msg = "Shutdown signal received, exiting...\n";
        (void)write(STDOUT_FILENO, msg, 38);
#endif
        // Don't call server->stop() from signal handler - it can block/deadlock
        // Just set the flag and exit immediately. The OS will clean up resources.
        g_shutdown_requested = true;
        // Use _exit() for async-signal-safe immediate termination
        // The OS will handle cleanup of file descriptors, memory, and child processes
        _exit(0);
#ifdef SIGHUP
    } else if (signal == SIGHUP) {
        // Ignore SIGHUP to prevent termination when parent process exits
        // This allows the server to continue running as a daemon
        return;
#endif
    }
}
int main(int argc, char** argv) {
    // Check for single instance early (before parsing args for faster feedback)
    if (SingleInstance::IsAnotherInstanceRunning("Router")) {
        std::cerr << "Error: Another instance of lemonade-router is already running.\n"
                  << "Only one instance can run at a time." << std::endl;
        return 1;
    }
    try {
        CLIParser parser;
        parser.parse(argc, argv);
        // Check if we should continue (false for --help, --version, or errors)
        if (!parser.should_continue()) {
            return parser.get_exit_code();
        }
        // Get server configuration
        auto config = parser.get_config();
        // Initialize logging
        auto sink = std::make_shared<AixLog::SinkCout>(AixLog::Filter(AixLog::to_severity(config.log_level)), "%Y-%m-%d %H:%M:%S.#ms [#severity] (#tag_func) #message");
        AixLog::Log::init({sink});
        // Start the server
        LOG(INFO) << "Starting Lemonade Server..." << std::endl;
        LOG(INFO) << "  Version: " << LEMON_VERSION_STRING << std::endl;
        LOG(INFO) << "  Port: " << config.port << std::endl;
        LOG(INFO) << "  Host: " << config.host << std::endl;
        LOG(INFO) << "  Log level: " << config.log_level << std::endl;
        if (!config.extra_models_dir.empty()) {
            LOG(INFO) << "  Extra models dir: " << config.extra_models_dir << std::endl;
        }
        Server server(config.port, config.host, config.log_level,
                    config.recipe_options, config.max_loaded_models,
                    config.extra_models_dir, config.no_broadcast,
                    config.global_timeout);
        // Register signal handler for Ctrl+C
        g_server_instance = &server;
        std::signal(SIGINT, signal_handler);
        std::signal(SIGTERM, signal_handler);
        server.run();
        // Clean up
        g_server_instance = nullptr;
        return 0;
    } catch (const std::exception& e) {
        LOG(ERROR) << "Error: " << e.what() << std::endl;
        return 1;
    }
}

#include <asio.hpp>
#include <boost/bind.hpp>
#include <iostream>
#include <vector>
#include "connection.hpp" // Must come before boost/serialization headers.
#include <boost/serialization/vector.hpp>
#include "stock.hpp"
namespace s11n_example {
/// Downloads stock quote information from a server.
class client
{
public:
  /// Constructor starts the asynchronous connect operation.
  client(asio::io_context& io_context,
      const std::string& host, const std::string& service)
    : connection_(io_context)
  {
    // Resolve the host name into an IP address.
    asio::ip::tcp::resolver resolver(io_context);
    asio::ip::tcp::resolver::query query(host, service);
    asio::ip::tcp::resolver::iterator endpoint_iterator =
      resolver.resolve(query);
    // Start an asynchronous connect operation.
    asio::async_connect(connection_.socket(), endpoint_iterator,
        boost::bind(&client::handle_connect, this,
          asio::placeholders::error));
  }
  /// Handle completion of a connect operation.
  void handle_connect(const asio::error_code& e)
  {
    if (!e)
    {
      // Successfully established connection. Start operation to read the list
      // of stocks. The connection::async_read() function will automatically
      // decode the data that is read from the underlying socket.
      connection_.async_read(stocks_,
          boost::bind(&client::handle_read, this,
            asio::placeholders::error));
    }
    else
    {
      // An error occurred. Log it and return. Since we are not starting a new
      // operation the io_context will run out of work to do and the client will
      // exit.
      std::cerr << e.message() << std::endl;
    }
  }
  /// Handle completion of a read operation.
  void handle_read(const asio::error_code& e)
  {
    if (!e)
    {
      // Print out the data that was received.
      for (std::size_t i = 0; i < stocks_.size(); ++i)
      {
        std::cout << "Stock number " << i << "\n";
        std::cout << "  code: " << stocks_[i].code << "\n";
        std::cout << "  name: " << stocks_[i].name << "\n";
        std::cout << "  open_price: " << stocks_[i].open_price << "\n";
        std::cout << "  high_price: " << stocks_[i].high_price << "\n";
        std::cout << "  low_price: " << stocks_[i].low_price << "\n";
        std::cout << "  last_price: " << stocks_[i].last_price << "\n";
        std::cout << "  buy_price: " << stocks_[i].buy_price << "\n";
        std::cout << "  buy_quantity: " << stocks_[i].buy_quantity << "\n";
        std::cout << "  sell_price: " << stocks_[i].sell_price << "\n";
        std::cout << "  sell_quantity: " << stocks_[i].sell_quantity << "\n";
      }
    }
    else
    {
      // An error occurred.
      std::cerr << e.message() << std::endl;
    }
    // Since we are not starting a new operation the io_context will run out of
    // work to do and the client will exit.
  }
private:
  /// The connection to the server.
  connection connection_;
  /// The data received from the server.
  std::vector<stock> stocks_;
};
} // namespace s11n_example
int main(int argc, char* argv[])
{
  try
  {
    // Check command line arguments.
    if (argc != 3)
    {
      std::cerr << "Usage: client <host> <port>" << std::endl;
      return 1;
    }
    asio::io_context io_context;
    s11n_example::client client(io_context, argv[1], argv[2]);
    io_context.run();
  }
  catch (std::exception& e)
  {
    std::cerr << e.what() << std::endl;
  }
  return 0;
}

