{
public:
    GamepadExample() {}
    // setup dds model
    void InitDdsModel(const std::string &networkInterface = "")
    {
        ChannelFactory::Instance()->Init(0, networkInterface);
        joystick_subscriber.reset(new ChannelSubscriber<unitree_go::msg::dds_::WirelessController_>(TOPIC_JOYSTICK));
        joystick_subscriber->InitChannel(std::bind(&GamepadExample::MessageHandler, this, std::placeholders::_1), 1);
    }
    // set gamepad dead_zone parameter
    void SetGamepadDeadZone(float deadzone)
    {
        gamepad.dead_zone = deadzone;
    }
    // set gamepad smooth parameter
    void setGamepadSmooth(float smooth)
    {
        gamepad.smooth = smooth;
    }
    // callback function to save joystick message
    void MessageHandler(const void *message)
    {
        std::lock_guard<std::mutex> lock(joystick_mutex);
        joystick_msg = *(unitree_go::msg::dds_::WirelessController_ *)message;
    }
    // work thread
    void Step()
    {
        {
            std::lock_guard<std::mutex> lock(joystick_mutex);
            gamepad.Update(joystick_msg);
        }
        // some operations
        if (gamepad.A.on_press)
        {
            press_count += 1;
        }
        // print gamepad state
        std::cout << "lx: " << gamepad.lx << std::endl
                  << "A: pressed: " << gamepad.A.pressed
                  << "; on_press: " << gamepad.A.on_press
                  << "; on_release: " << gamepad.A.on_release
                  << std::endl << "press count: " << press_count
                  << std::endl << "===========================" << std::endl;
    }
    // start the work thread
    void Start()
    {
        control_thread_ptr = CreateRecurrentThreadEx("nn_ctrl", UT_CPU_ID_NONE, 40000, &GamepadExample::Step, this);
    }
protected:
    ChannelSubscriberPtr<unitree_go::msg::dds_::WirelessController_> joystick_subscriber;
    unitree_go::msg::dds_::WirelessController_ joystick_msg;
    Gamepad gamepad;
    ThreadPtr control_thread_ptr;
    std::mutex joystick_mutex;
    int press_count = 0;
};
int main()
{
    // create example object
    GamepadExample example;
    // set gamepad params
    example.setGamepadSmooth(0.2);
    example.SetGamepadDeadZone(0.5);
    // start program
    example.InitDdsModel();
    example.Start();
    while (1)
    {
        usleep(20000);
    }
    return 0;
}

#include <iostream>
#include <vector>
#include <numeric>
#include <algorithm>
#include <list>
// Function to perform a query
int query(const std::vector<int>& pepes) {
    std::cout << "?";
    for (int p : pepes) {
        std::cout << " " << p;
    }
    std::cout << std::endl;
    int winner;
    std::cin >> winner;
    if (winner == -1) {
        exit(0); // Exit on error signal from interactor
    }
    return winner;
}
void solve() {
    int n;
    std::cin >> n;
    // Use a list for efficient removal of elements by value
    std::list<int> remaining_pepes;
    for (int i = 1; i <= n * n; ++i) {
        remaining_pepes.push_back(i);
    }
    std::vector<int> sorted_pepes;
    int num_to_find = n * n - n + 1;
    // Find the fastest pepes one by one
    for (int k = 0; k < num_to_find; ++k) {
        // Find the maximum of the currently remaining pepes
        std::list<int> candidates = remaining_pepes;

        while (candidates.size() > 1) {
            // Form a race group with at most n pepes from the front of the candidates
            std::vector<int> race_group;
            auto it = candidates.begin();
            for(int i = 0; i < n && it != candidates.end(); ++i) {
                race_group.push_back(*it);
                it++;
            }

            int winner = query(race_group);
            // The losers of this race cannot be the fastest overall among candidates.
            // Remove them from the candidate list.
            // Using list::erase(iterator) is more efficient than rebuilding the list.
            auto it_cand = candidates.begin();
            while(it_cand != candidates.end()){
                bool is_loser = false;
                // Check if the current candidate was in the race and lost
                if (*it_cand != winner) {
                    for(int p_race : race_group){
                        if(*it_cand == p_race){
                            is_loser = true;
                            break;
                        }
                    }
                }
                if(is_loser){
                    it_cand = candidates.erase(it_cand);
                } else {
                    ++it_cand;
                }
            }
        }
        // The only remaining candidate is the fastest
        int next_fastest = candidates.front();
        sorted_pepes.push_back(next_fastest);
        remaining_pepes.remove(next_fastest);
    }
    // Output the final sorted list
    std::cout << "!";
    for (size_t i = 0; i < sorted_pepes.size(); ++i) {
        std::cout << " " << sorted_pepes[i];
    }
    std::cout << std::endl;
}
int main() {
    // Fast I/O
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(NULL);
    int t;
    std::cin >> t;
    while (t--) {
        solve();
    }
    return 0;
}

