namespace llvm_utils {
using namespace llvm;
/// @brief Run the default O0, O1, O2, or O3 optimization pass pipelines on the
/// given module.
///
/// This function applies LLVM's standard optimization pipeline to transform the
/// input module. The PassBuilder constructs an appropriate sequence of passes
/// based on the specified optimization level.
///
/// @param M Pointer to the LLVM module to optimize (must not be null)
/// @param OptLevel The optimization level to apply:
///   - OptimizationLevel::O0: No optimizations (useful for debugging)
///   - OptimizationLevel::O1: Basic optimizations
///   - OptimizationLevel::O2: Standard optimizations (default for release
///   builds)
///   - OptimizationLevel::O3: Aggressive optimizations (may increase code size)
///
/// @return PreservedAnalyses containing the set of analyses that were preserved
///         after running the optimization pipeline
///
/// @throws std::invalid_argument if M is a null pointer
auto optimiseModule(Module *M, OptimizationLevel OptLevel)
    -> PreservedAnalyses {
  if (!M)
    throw std::invalid_argument("Null ptr argument!");
  LoopAnalysisManager LAM;
  FunctionAnalysisManager FAM;
  CGSCCAnalysisManager CGAM;
  ModuleAnalysisManager MAM;
  PassBuilder PB;
  PB.registerModuleAnalyses(MAM);
  PB.registerCGSCCAnalyses(CGAM);
  PB.registerFunctionAnalyses(FAM);
  PB.registerLoopAnalyses(LAM);
  PB.crossRegisterProxies(LAM, FAM, CGAM, MAM);
  return PB.buildPerModuleDefaultPipeline(OptLevel).run(*M, MAM);
}
} // namespace llvm_utils

#include "ReduceInstructions.h"
#include "Utils.h"
#include "llvm/IR/Constants.h"
#include <set>
using namespace llvm;
/// Filter out cases where deleting the instruction will likely cause the
/// user/def of the instruction to fail the verifier.
//
// TODO: Technically the verifier only enforces preallocated token usage and
// there is a none token.
static bool shouldAlwaysKeep(const Instruction &I) {
  return I.isEHPad() || I.getType()->isTokenTy() || I.isSwiftError();
}
/// Removes out-of-chunk arguments from functions, and modifies their calls
/// accordingly. It also removes allocations of out-of-chunk arguments.
static void extractInstrFromModule(Oracle &O, ReducerWorkItem &WorkItem) {
  Module &Program = WorkItem.getModule();
  std::vector<Instruction *> InitInstToKeep;
  for (auto &F : Program)
    for (auto &BB : F) {
      // Removing the terminator would make the block invalid. Only iterate over
      // instructions before the terminator.
      InitInstToKeep.push_back(BB.getTerminator());
      for (auto &Inst : make_range(BB.begin(), std::prev(BB.end()))) {
        if (shouldAlwaysKeep(Inst) || O.shouldKeep())
          InitInstToKeep.push_back(&Inst);
      }
    }
  // We create a vector first, then convert it to a set, so that we don't have
  // to pay the cost of rebalancing the set frequently if the order we insert
  // the elements doesn't match the order they should appear inside the set.
  std::set<Instruction *> InstToKeep(InitInstToKeep.begin(),
                                     InitInstToKeep.end());
  std::vector<Instruction *> InstToDelete;
  for (auto &F : Program)
    for (auto &BB : F)
      for (auto &Inst : BB)
        if (!InstToKeep.count(&Inst)) {
          Inst.replaceAllUsesWith(getDefaultValue(Inst.getType()));
          InstToDelete.push_back(&Inst);
        }
  for (auto &I : InstToDelete)
    I->eraseFromParent();
}
void llvm::reduceInstructionsDeltaPass(TestRunner &Test) {
  runDeltaPass(Test, extractInstrFromModule, "Reducing Instructions");
}

#include <iostream>
#include <cmath>
// This function recursively generates the moves for the Tower of Hanoi problem.
// n: the number of balls to move
// from_basket: the source basket
// to_basket: the destination basket
// aux_basket: the auxiliary basket
void solve(int n, int from_basket, int to_basket, int aux_basket) {
    if (n == 0) {
        return;
    }
    // Step 1: Move n-1 balls from source to auxiliary, using destination as temporary.
    solve(n - 1, from_basket, aux_basket, to_basket);

    // Step 2: Move the nth ball from source to destination.
    std::cout << from_basket << " " << to_basket << "\n";

    // Step 3: Move the n-1 balls from auxiliary to destination, using source as temporary.
    solve(n - 1, aux_basket, to_basket, from_basket);
}
int main() {
    // Fast I/O
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(NULL);
    int N;
    std::cin >> N;
    // The total number of moves for N balls in the Tower of Hanoi is 2^N - 1.
    // We use 1LL to ensure the calculation is done with 64-bit integers
    // to prevent overflow for larger N, although for N <= 30, int is sufficient for N
    // but the result can exceed int's capacity.
    long long num_moves = (1LL << N) - 1;
    std::cout << num_moves << "\n";
    // We only proceed to print moves if there are any balls to move.
    if (N > 0) {
        solve(N, 1, 3, 2);
    }
    return 0;
}

