// Performs the nonlinear step operation
void nonlinear_step(
    std::shared_ptr<const DefaultExecutor> exec,
    int n,
    double nonlinear_scale,
    double potential_scale,
    double time_scale,
    const gko::matrix::Dense<double>* potential,
    gko::matrix::Dense<std::complex<double>>* ampl)
{
    using device_complex = device_type<std::complex<double>>;

    // Run the kernel for nonlinear step computation
    run_kernel(
        exec,
        GKO_KERNEL(auto i, auto j, auto n, auto nonlinear_scale,
                   auto potential_scale, auto time_scale, auto potential,
                   auto ampl) {
            // Compute the nonlinear step:
            // ampl[i][j] *= nonlinear_scale * potential_scale * time_scale * potential[i][j]
            ampl[i][j] = nonlinear_scale * potential_scale * time_scale *
                         potential[i][j] * ampl[i][j];
        });
}

