// Removes a specific card from the hand
Card Hand::removeCard(const Card& card)
{
    auto it = std::find(cards.begin(), cards.end(), card);
    if (it != cards.end())
    {
        Card copy = *it;
        cards.erase(it);
        return copy;
    }
    // Return a default-constructed card if not found
    return Card{};
}

// Gets IDs of cards matching a predicate
std::list<CardId> Hand::getIds(std::function<bool(const Card&)> predicate)
{
    std::list<CardId> ids;
    for (const auto& card : cards)
    {
        if (predicate(card))
        {
            ids.push_back(card.id);
        }
    }
    return ids;
}

