// Function to count elements less than each query value
vector<int> countElementsLessThanX(int a[], int n, int queries[], int q)
{
    vector<int> result;

    // Sort the array to enable binary search
    sort(a, a + n);

    // Process each query
    for(int i = 0; i < q; i++)
    {
        // Count elements strictly less than queries[i]
        int count = upper_bound(a, a + n, queries[i]) - a;
        result.push_back(count);
    }

    return result;
}

