// Class representing a point in 2D space
class Point
{
private:
    int x, y;

public:
    // Constructor
    Point(int x, int y) : x(x), y(y) {}

    // Calculate distance to another point
    double distanceTo(Point other)
    {
        return sqrt(pow(other.x - x, 2) + pow(other.y - y, 2));
    }

    // Calculate distance to origin (0,0)
    double distanceToOrigin()
    {
        return sqrt(pow(x, 2) + pow(y, 2));
    }

    // Move the point by given offsets
    void move(int offsetX, int offsetY)
    {
        x += offsetX;
        y += offsetY;
    }
};

int main()
{
    // Create point p(3,4)
    Point p(3, 4);
    std::cout << "Distance to origin: " << p.distanceToOrigin() << std::endl;

    // Create point q(6,8)
    Point q(6, 8);
    std::cout << "Distance between p and q: " << p.distanceTo(q) << std::endl;

    // Move point p
    p.move(1, 1);
    std::cout << "New coordinates of p: (" << p.x << ", " << p.y << ")" << std::endl;

    return 0;
}

