// Handles client requests
void handleClient(int clientSocket)
{
    // Predefined response message for the specific endpoint
    std::string response = "HTTP/1.1 200 OK\nContent-Type: text/plain\nContent-Length: 12\n\nHello, World!";

    // Send the response to the client
    send(clientSocket, response.c_str(), response.size(), 0);

    // Close the client socket
    close(clientSocket);
}

int main()
{
    // Create a socket
    int serverSocket = socket(AF_INET, SOCK_STREAM, 0);

    // Bind the socket to a port
    sockaddr_in serverAddress;
    serverAddress.sin_family = AF_INET;
    serverAddress.sin_port = htons(8080);
    serverAddress.sin_addr.s_addr = INADDR_ANY;
    bind(serverSocket, (struct sockaddr *)&serverAddress, sizeof(serverAddress));

    // Listen for incoming connections
    listen(serverSocket, 5);

    // Accept incoming connections and handle requests
    while(true)
    {
        int clientSocket = accept(serverSocket, NULL, NULL);
        handleClient(clientSocket);
    }

    // Close the server socket
    close(serverSocket);
    return 0;

}

#include "Components/Lights/LightInterface.hpp"
#include <vector>
#include <algorithm>

namespace Components::Lights {

    // Point light implementation
    class PointLight : public LightInterface {
    public:
        PointLight(const glm::vec3& position, const glm::vec3& color)
            : position_(position), color_(color) {}

        virtual glm::vec3 CalculateIllumination(const glm::vec3& point) const override {
            glm::vec3 direction = position_ - point;
            float distance = glm::length(direction);
            direction = glm::normalize(direction);
            float attenuation = 1.0f / (distance * distance);
            return color_ * attenuation * std::max(glm::dot(glm::vec3(0, 0, 1), direction), 0.0f);
        }

    private:
        glm::vec3 position_;
        glm::vec3 color_;
    };

    // Directional light implementation
    class DirectionalLight : public LightInterface {
    public:
        DirectionalLight(const glm::vec3& direction, const glm::vec3& color)
            : direction_(direction), color_(color) {}

        virtual glm::vec3 CalculateIllumination(const glm::vec3& point) const override {
            return color_ * std::max(glm::dot(glm::vec3(0, 0, 1), -direction_), 0.0f);
        }

    private:
        glm::vec3 direction_;
        glm::vec3 color_;
    };

    // Calculate total illumination from all lights at a given point
    glm::vec3 CalculateIllumination(const glm::vec3& point, const std::vector<std::shared_ptr<LightInterface>>& lights) {
        glm::vec3 totalIllumination(0.0f);
        for(const auto& light : lights)
        {
            totalIllumination += light->CalculateIllumination(point);
        }
        return totalIllumination;
    }

}

