// Signal class for managing slots
template <typename... Args>
class Signal {
public:
    using SlotFunction = std::function<void(Args...)>;

    // Connect a new slot
    void connect(SlotFunction slot) {
        slots_.push_back(slot);
    }

    // Emit signal to all connected slots
    void emit(Args... args) {
        for (const auto& slot : slots_) {
            slot(args...);
        }
    }

private:
    std::vector<SlotFunction> slots_;
};

// Slot wrapper class
template <typename... Args>
class Slot {
public:
    using SlotFunction = std::function<void(Args...)>;

    // Constructor
    Slot(SlotFunction function) : function_(function) {}

    // Call operator to invoke the stored function
    void operator()(Args... args) {
        function_(args...);
    }

private:
    SlotFunction function_;
};

