// Class to track the number of live instances
class LiveCount {
public:
    static int count;

    // Default constructor increments count
    LiveCount() {
        count++;
    }

    // Copy constructor increments count
    LiveCount(const LiveCount& other) {
        count++;
    }

    // Destructor decrements count
    ~LiveCount() {
        count--;
    }
};

// Initialize static member
int LiveCount::count = 0;

// Main function
int main()
{
    std::map<int, LiveCount> map;

    // Creating an instance of LiveCount
    LiveCount lc1;

    // Verifying count after creation
    assert(LiveCount::count == 1);

    // Adding an instance to the map
    map[12] = LiveCount();

    // Verifying count after adding to the map
    assert(LiveCount::count == 2);

    // Overwriting the instance in the map
    map[12] = LiveCount();

    // Verifying count after overwriting the instance in the map
    assert(LiveCount::count == 2);

    // Destroying instances
    // Verifying count after destruction
    {
        LiveCount lc2;
        LiveCount lc3;
    }
    assert(LiveCount::count == 2);

    // Removing an instance from the map
    map.erase(12);

    // Verifying count after removing from the map
    assert(LiveCount::count == 1);

    return 0;
}

