// Custom string view implementation
class CustomStringView {
public:
    // Constructors
    constexpr CustomStringView() noexcept : data_(nullptr), size_(0) {}
    constexpr CustomStringView(const char* str) noexcept : data_(str), size_(std::strlen(str)) {}
    constexpr CustomStringView(const char* str, size_t len) noexcept : data_(str), size_(len) {}

    // Accessors
    constexpr const char* data() const noexcept { return data_; }
    constexpr size_t size() const noexcept { return size_; }

    // Element access
    constexpr char operator[](size_t pos) const { return data_[pos]; }

    // Comparison
    constexpr bool operator==(CustomStringView other) const noexcept {
        return size_ == other.size_ && std::strncmp(data_, other.data_, size_) == 0;
    }

    // Subview
    constexpr CustomStringView substr(size_t pos, size_t count = npos) const {
        if (pos > size_) pos = size_;
        if (count > size_ - pos) count = size_ - pos;
        return CustomStringView(data_ + pos, count);
    }

    // Find
    constexpr size_t find(char c, size_t pos = 0) const noexcept {
        if (pos >= size_) return npos;
        const char* result = std::strchr(data_ + pos, c);
        return result ? static_cast<size_t>(result - data_) : npos;
    }

    static constexpr size_t npos = -1;

private:
    const char* data_;
    size_t size_;
};

#include <iostream>
#include <vector>
#include <algorithm>

// Node class definition
class Node {
public:
    // Constructor initializes children and position
    Node(std::vector<Node*> children, std::pair<int, int> position) : m_children(children), position(position) {}

    // Move node to new position and propagate to children
    void move(std::pair<int, int> newPosition) {
        // Calculate offset for movement
        int xOffset = newPosition.first - position.first;
        int yOffset = newPosition.second - position.second;

        // Update current position
        position = newPosition;

        // Recursively move all children by the same offset
        for (auto& child : m_children) {
            child->move(std::make_pair(child->position.first + xOffset, child->position.second + yOffset));
        }
    }

private:
    std::pair<int, int> position;
    std::vector<Node*> m_children;
};

// Main function demonstrating node hierarchy movement
int main() {
    // Create child nodes
    Node* child1 = new Node({}, std::make_pair(1, 1));
    Node* child2 = new Node({}, std::make_pair(2, 2));

    // Create parent node with children
    Node* parent = new Node({child1, child2}, std::make_pair(0, 0));

    // Move parent node to new position
    parent->move(std::make_pair(3, 3));

    // Clean up dynamically allocated memory
    delete child1;
    delete child2;
    delete parent;

    return 0;
}

