class UInt64Vector {
private:
    std::vector<uint64_t> m_Vector;

public:
    // Constructor to initialize the vector with a given value
    UInt64Vector(uint64_t value) : m_Vector(64, value) {}

    // Method to perform addition of two vectors
    UInt64Vector add(const UInt64Vector& other) const {
        UInt64Vector result(0);
        for(size_t i=0; i<64; ++i) {
            result.m_Vector[i] = m_Vector[i] + other.m_Vector[i];
        }
        return result;
    }

    // Method to perform subtraction of two vectors
    UInt64Vector subtract(const UInt64Vector& other) const {
        UInt64Vector result(0);
        for(size_t i=0; i<64; ++i) {
            result.m_Vector[i] = m_Vector[i] - other.m_Vector[i];
        }
        return result;
    }

    // Method to perform multiplication of two vectors
    UInt64Vector multiply(const UInt64Vector& other) const {
        UInt64Vector result(0);
        for(size_t i=0; i<64; ++i) {
            result.m_Vector[i] = m_Vector[i] * other.m_Vector[i];
        }
        return result;
    }

    // Method to perform division of two vectors
    UInt64Vector divide(const UInt64Vector& other) const {
        UInt64Vector result(0);
        for(size_t i=0; i<64; ++i) {
            if(other.m_Vector[i] != 0) {
                result.m_Vector[i] = m_Vector[i] / other.m_Vector[i];
            }
            // Handle division by zero
            else {
                // Set the result to the maximum value of uint64_t
                result.m_Vector[i] = std::numeric_limits<uint64_t>::max();
            }
        }
        return result;
    }

    // Method to retrieve the minimum value of the vector elements
    uint64_t getMinValue() const {
        return *std::min_element(m_Vector.begin(), m_Vector.end());
    }

    // Method to retrieve the maximum value of the vector elements
    uint64_t getMaxValue() const {
        return *std::max_element(m_Vector.begin(), m_Vector.end());
    }
};

int main()
{
    UInt64Vector vec1(5);
    UInt64Vector vec2(3);

    UInt64Vector sum = vec1.add(vec2);
    UInt64Vector diff = vec1.subtract(vec2);
    UInt64Vector product = vec1.multiply(vec2);
    UInt64Vector quotient = vec1.divide(vec2);

    // Output results
    std::cout << "Minimum value of sum: " << sum.getMinValue() << std::endl;
    std::cout << "Maximum value of sum: " << sum.getMaxValue() << std::endl;
    std::cout << "Minimum value of diff: " << diff.getMinValue() << std::endl;
    std::cout << "Maximum value of diff: " << diff.getMaxValue() << std::endl;
    std::cout << "Minimum value of product: " << product.getMinValue() << std::endl;
    std::cout << "Maximum value of product: " << product.getMaxValue() << std::endl;
    std::cout << "Minimum value of quotient: " << quotient.getMinValue() << std::endl;
    std::cout << "Maximum value of quotient: " << quotient.getMaxValue() << std::endl;

    return 0;
}

