// Custom memory manager class
class CustomMemoryManager {
    std::shared_ptr<void> storage;

    // Custom deleter function template
    template<typename T>
    static void funcDeleter(void* mPtr)
    {
        static_cast<T*>(mPtr)->~T();
        operator delete(mPtr);
    }

public:
    // Allocate and construct an object of type T
    template<typename T>
    T* allocate()
    {
        storage.reset(new T, funcDeleter<T>);
        return static_cast<T*>(storage.get());
    }

    // Deallocate the stored object if it matches the pointer
    template<typename T>
    void deallocate(T* ptr)
    {
        if (ptr == storage.get())
        {
            storage.reset();
        }
    }
};

