namespace pbrt {

// Quaternion Method Definitions
Transform Quaternion::ToTransform() const
{
    Float xx = v.x * v.x, yy = v.y * v.y, zz = v.z * v.z;
    Float xy = v.x * v.y, xz = v.x * v.z, yz = v.y * v.z;
    // Calculate the elements of the transformation matrix
    Float elements[16] = {
        1 - 2 * (yy + zz), 2 * (xy - v.z * w), 2 * (xz + v.y * w), 0,
        2 * (xy + v.z * w), 1 - 2 * (xx + zz), 2 * (yz - v.x * w), 0,
        2 * (xz - v.y * w), 2 * (yz + v.x * w), 1 - 2 * (xx + yy), 0,
        0, 0, 0, 1
    };
    // Create a Transform object from the calculated elements
    return Transform(elements);

}

