class TextureRenderer : public QThread {
private:
    QQuickWindow* m_quickWindow;
    QOpenGLFramebufferObject* m_framebufferObject;
    QSGSimpleTextureNode* m_textureNode;

public:
    // Initialize resources
    void initialize()
    {
        m_framebufferObject = new QOpenGLFramebufferObject(m_quickWindow->size());
        m_textureNode = new QSGSimpleTextureNode();
        // Additional initialization for the texture node
    }

    // Render content to framebuffer
    void render()
    {
        if (m_quickWindow && m_quickWindow->openglContext())
        {
            m_framebufferObject->bind();
            // Render the texture node content to the framebuffer object
            m_framebufferObject->release();
            m_quickWindow->setRenderTarget(m_framebufferObject);
            m_quickWindow->sceneGraphInvalidated();
        }
    }

    // Clean up allocated resources
    void cleanup()
    {
        delete m_framebufferObject;
        delete m_textureNode;
    }
};

