std::pair<std::vector<uint8_t>, std::unique_ptr<folly::IOBuf>> deriveKeys(
    const std::vector<uint8_t>& sharedSecret,
    const std::vector<uint8_t>& psk,
    const SuiteId& suiteId,
    const KeyScheduleContext& keyScheduleContext,
    const Cipher& cipher)
{
  // Assuming hkdf is an instance of the HKDF class
  // Generate hashes for cipher key
  std::vector<uint8_t> secret = hkdf->labeledExtract(
      folly::ByteRange(sharedSecret),
      folly::ByteRange(folly::StringPiece("secret")),
      folly::ByteRange(psk),
      suiteId.clone());

  // Generate additional values needed for constructing context
  std::unique_ptr<folly::IOBuf> key = hkdf->labeledExpand(
      secret,
      folly::ByteRange(folly::StringPiece("key")),
      keyScheduleContext.clone(),
      cipher.keyLength());

  // Return derived secret and key buffer
  return std::make_pair(secret, std::move(key));
}

