// Solution class for checking if two strings are permutations of each other
class Solution {
public:
    bool CheckPermutation(std::string s1, std::string s2)
    {
        // If lengths differ, they cannot be permutations
        if (s1.length() != s2.length())
        {
            return false;
        }
        // Sort both strings
        std::sort(s1.begin(), s1.end());
        std::sort(s2.begin(), s2.end());
        // Compare sorted strings
        return s1 == s2;
    }
};

