// Computes the sum of non-NaN elements along a given dimension, ignoring masked values
Variable nansum(const Variable &var, const Dim dim, const Masks &masks)
{
    // Compute irreducible mask for the given dimension
    if (const auto mask_union = irreducible_mask(masks, dim); mask_union.is_valid())
    {
        // Exclude masked elements and recursively call nansum
        return nansum(where(mask_union, zero_like(var), var), dim, masks);
    }
    else
    {
        // Sum non-NaN elements based on dimension
        switch (dim)
        {
            case Dim::ROW:
                return sum(where(isnan(var), 0, var), Dim::ROW);
            case Dim::COLUMN:
                return sum(where(isnan(var), 0, var), Dim::COLUMN);
            // Additional dimensions can be handled here as needed
            default:
                throw std::invalid_argument("Invalid dimension specified");
        }
    }
}

