// Thread job tracker class for monitoring completed jobs per thread
class ThreadJobTracker {
private:
    std::unordered_map<int, ThreadData> m_threadData;
    std::unordered_map<int, int> m_jobsCompleted;
    std::mutex m_mutex;

public:
    // Structure to hold thread-specific data
    struct ThreadData {
        // Define the structure of thread data
        // Example: int threadId;
        // Add any other relevant data fields
    };

    // Assigns thread data and initializes job count to zero
    void assignThreadData(int threadId, const ThreadData& data) {
        std::lock_guard<std::mutex> lock(m_mutex);
        m_threadData[threadId] = data;
        m_jobsCompleted[threadId] = 0; // Initialize the number of jobs completed to 0
    }

    // Increments the job count for a specific thread
    void incrementJobsCompleted(int threadId) {
        std::lock_guard<std::mutex> lock(m_mutex);
        if (m_jobsCompleted.find(threadId) != m_jobsCompleted.end()) {
            m_jobsCompleted[threadId]++;
        }
    }

    // Retrieves the number of jobs completed for a given thread
    int getJobsCompleted(int threadId) {
        std::lock_guard<std::mutex> lock(m_mutex);
        if (m_jobsCompleted.find(threadId) != m_jobsCompleted.end()) {
            return m_jobsCompleted[threadId];
        }
        return 0; // Return 0 if the thread ID is not found
    }
};

