// Function to find maximum number of elements from two arrays
// whose sum is less than or equal to X
int maxElementsSumLessThanX(int N, int M, int X, int A[], int B[])
{
    // Sort array A in descending order
    std::sort(A, A + N, std::greater<int>());
    // Sort array B in descending order
    std::sort(B, B + M, std::greater<int>());

    int maxElements = 0;
    int sum = 0;
    int i = 0, j = 0;

    // Process pairs from both arrays
    while (i < N && j < M)
    {
        if (A[i] + B[j] <= X)
        {
            sum += A[i] + B[j];
            i++;
            j++;
            maxElements += 2;
        }
        else if (A[i] <= X)
        {
            sum += A[i];
            i++;
            maxElements++;
        }
        else if (B[j] <= X)
        {
            sum += B[j];
            j++;
            maxElements++;
        }
        else
        {
            break;
        }

        // Check if sum exceeds X
        if (sum > X)
        {
            maxElements--;
            break;
        }
    }

    // Process remaining elements in A
    while (i < N && A[i] <= X)
    {
        sum += A[i];
        i++;
        maxElements++;
        if (sum > X)
        {
            maxElements--;
            break;
        }
    }

    // Process remaining elements in B
    while (j < M && B[j] <= X)
    {
        sum += B[j];
        j++;
        maxElements++;
        if (sum > X)
        {
            maxElements--;
            break;
        }
    }

    return maxElements;
}

