class CriticalSection {
public:
    void Lock() {
        mutex.lock();
    }
    void Unlock() {
        mutex.unlock();
    }
private:
    std::mutex mutex;
};

// RAII-style scoped lock for CriticalSection
class ScopedLock : private Uncopyable {
public:
    ScopedLock(CriticalSection& criticalSection)
        : cs(criticalSection) {
        REF_CHECK(criticalSection);
        cs.Lock();
    }
    ~ScopedLock() {
        cs.Unlock();
    }
private:
    CriticalSection& cs;
};

// Thread-safe stack implementation
template <typename T>
class ThreadSafeStack {
public:
    void Push(const T& value) {
        ScopedLock lock(cs);
        data.push(value);
    }
    bool Pop(T& value) {
        ScopedLock lock(cs);
        if (data.empty()) {
            return false;
        }
        value = data.top();
        data.pop();
        return true;
    }
    bool IsEmpty() {
        ScopedLock lock(cs);
        return data.empty();
    }
private:
    std::stack<T> data;
    CriticalSection cs;
};

