template <typename Policy, typename Iterator, typename T>
struct test_non_const_is_heap_until
{
    // Function call operator
    void operator()(Policy&& exec, Iterator iter)
    {
        std::invoke_if(std::forward<Policy>(exec), [&](auto&& policy) {
            // Call is_heap with the policy and iterator range
            std::is_heap(policy, iter, non_const(std::less<T>()));
        });
    }

private:
    // Helper function to return a copy of the comparator
    template <typename Compare>
    static Compare non_const(Compare comp)
    {
        return comp;
    }
};

