// Task 1: sleeps for a random delay then sets promise value
void task1(boost::promise<void>& p)
{
    std::random_device rd;
    std::mt19937 gen(rd());
    std::uniform_int_distribution<> delay(1000, 5000);
    std::this_thread::sleep_for(std::chrono::milliseconds(delay(gen)));
    p.set_value();
}

// Task 2: waits on future then sets its own promise value
void task2(boost::promise<void>& p, boost::future<void>& f)
{
    f.wait();
    p.set_value();
}

int main()
{
    // Initialize promises and futures
    boost::promise<void> p1;
    boost::promise<void> p2;
    boost::future<void> f1 = boost::make_ready_future();
    boost::future<void> f2 = p2.get_future();

    // Launch threads
    std::thread t1(task1, std::ref(p1));
    std::thread t2(task2, std::ref(p2), std::ref(f1));

    // Wait for threads to complete
    t1.join();
    t2.join();

    // Output completion message
    std::cout << "Tasks completed" << std::endl;
    return 0;

}

