// Class to manage a secret number guessing game
class SecretNumber {
private:
    int secret;
    std::pair<int, int> range;
    int guessCount;

public:
    // Constructor initializes the secret number and range
    SecretNumber(int min, int max) : range(std::make_pair(min, max)), guessCount(0)
    {
        srand(static_cast<unsigned int>(time(nullptr)));
        secret = rand() % (max - min + 1) + min;
    }

    // Process a guess and return whether it's correct
    bool makeGuess(int guess)
    {
        guessCount++;
        return guess == secret;
    }

    // Get the range of possible values
    std::pair<int, int> getRange()
    {
        return range;
    }

    // Get the number of guesses made so far
    int getGuessCount()
    {
        return guessCount;
    }
};

int main()
{
    SecretNumber secretNum(1, 100);
    int guess;
    std::pair<int, int> range = secretNum.getRange();

    // Prompt user for input
    std::cout << "Guess the secret number between " << range.first << " and " << range.second << std::endl;

    do {
        std::cin >> guess;
    } while (!secretNum.makeGuess(guess));

    // Success message with attempt count
    std::cout << "Congratulations! You guessed the secret number in " << secretNum.getGuessCount() << " attempts." << std::endl;

    return 0;
}

