namespace rw {
    // Namespace for mathematical operations
    namespace math {
        // Quaternion class template
        template <typename T>
        class Quaternion {
        public:
            T w, x, y, z;

            // Constructor
            Quaternion(T w, T x, T y, T z) : w(w), x(x), y(y), z(z) {}

            // Returns the conjugate of the quaternion
            Quaternion<T> conjugate() const {
                return Quaternion<T>(w, -x, -y, -z);
            }

            // Multiplies this quaternion with another
            Quaternion<T> multiply(const Quaternion<T>& other) const {
                T newW = w * other.w - x * other.x - y * other.y - z * other.z;
                T newX = w * other.x + x * other.w + y * other.z - z * other.y;
                T newY = w * other.y - x * other.z + y * other.w + z * other.x;
                T newZ = w * other.z + x * other.y - y * other.x + z * other.w;
                return Quaternion<T>(newW, newX, newY, newZ);
            }

            // Normalizes the quaternion to unit length
            void normalize() {
                T magnitude = std::sqrt(w * w + x * x + y * y + z * z);
                if (magnitude != 0) {
                    w /= magnitude;
                    x /= magnitude;
                    y /= magnitude;
                    z /= magnitude;
                }
            }
        };
    } // namespace math
} // namespace rw

