int main()
{
    int n, k;
    cin >> n;

    // Declare 2D array with size (n+1) x (n+1)
    int a[n+1][n+1];

    // Read matrix elements
    for(int i=1; i<=n; i++)
        for(int j=1; j<=n; j++)
            cin >> a[i][j];

    // Extract elements in specific pattern
    int x = 0;
    int v[n*n+1];

    // First loop: top-left quadrant
    for(int i=1; i<=n/2; i++) {
        x++;
        v[x] = a[i][n/2-i+1];
    }

    // Second loop: bottom-left quadrant
    for(int i=1; i<=n/2; i++) {
        x++;
        v[x] = a[n/2+i][i];
    }

    // Third loop: bottom-right quadrant
    for(int i=1; i<=n/2; i++) {
        x++;
        v[x] = a[n-i+1][n/2+i];
    }

    // Fourth loop: top-right quadrant
    for(int i=1; i<=n/2; i++) {
        x++;
        v[x] = a[n/2-i+1][n-i+1];
    }

    // Read rotation parameter
