#include <map>
#include <pb_decode.h>

// Template struct for decoding protocol buffer map entries
template <typename T>
struct codec_map {
    // Decode function to extract key-value pairs from a protobuf stream
    static bool decode(pb_istream_t *stream, const pb_field_t *field, void **arg)
    {
        // Cast the argument to a pointer to std::map
        auto *mapping = static_cast<std::map<typename T::KeyType, typename T::ValueType> *>(*arg);

        // Create a temporary entry to hold decoded data
        T map_entry;

        // Decode the protobuf message into map_entry
        if (!pb_decode(stream, field, &map_entry)) {
            return false; // Return false if decoding fails
        }

        // Insert the decoded key-value pair into the map
        mapping->insert(std::make_pair(map_entry.key, map_entry.value));

        return true; // Return true on success
    }
};

