class TextManager {
private:
    int w, h; // Width and height of the text manager
    std::vector<std::string> text_mgr; // Text content
    std::pair<float, float> cursor_position; // Cursor position (x, y)

public:
    // Constructor to initialize width, height, and text buffer
    TextManager(int width, int height) : w(width), h(height)
    {
        text_mgr.resize(w, std::string(h, ' '));
        cursor_position = std::make_pair(0.0f, 0.0f);
    }

    // Resize the text manager
    void resize(int width, int height)
    {
        w = width;
        h = height;
        text_mgr.resize(w, std::string(h, ' '));
    }

    // Update cursor position based on input coordinates
    void cursor_event(float x, float y)
    {
        // Update the cursor position based on the given coordinates
        cursor_position = std::make_pair(x, y);
    }

    // Display the current text content with cursor indicator
    void display_text_content()
    {
        for (int i = 0; i < h; i++)
        {
            for (int j = 0; j < w; j++)
            {
                if (j == static_cast<int>(cursor_position.first) && i == static_cast<int>(cursor_position.second))
                {
                    std::cout << "*"; // Display cursor position
                }
                else
                {
                    std::cout << text_mgr[j][i];
                }
            }
            std::cout << std::endl;
        }
    }
};

