// Template function to find maximum of two values
template <typename T>
__host__ __device__ T odin_max(T x, T y) {
  return x > y ? x : y;
}

// CPU function using odin_max
void cpuMaxDemo() {
  int a = 10, b = 20;
  int maxResult = odin_max(a, b);
  std::cout << "CPU Max Result: " << maxResult << std::endl;
}

// GPU kernel using odin_max
__global__ void gpuMaxDemo(int* arr1, int* arr2, int* result, int size) {
  int tid = blockIdx.x * blockDim.x + threadIdx.x;
  if (tid < size) {
    result[tid] = odin_max(arr1[tid], arr2[tid]);
  }
}

int main() {
  // CPU demo
  cpuMaxDemo();

  // GPU demo
  const int size = 5;
  int hostArr1[size] = {1, 5, 3, 7, 9};
  int hostArr2[size] = {4, 2, 8, 6, 0};
  int hostResult[size];

  int* devArr1, *devArr2, *devResult;

  cudaMalloc((void**)&devArr1, size * sizeof(int));
  cudaMalloc((void**)&devArr2, size * sizeof(int));
  cudaMalloc((void**)&devResult, size * sizeof(int));

  cudaMemcpy(devArr1, hostArr1, size * sizeof(int), cudaMemcpyHostToDevice);
  cudaMemcpy(devArr2, hostArr2, size * sizeof(int), cudaMemcpyHostToDevice);

  gpuMaxDemo<<<1, size>>>(devArr1, devArr2, devResult, size);

  cudaMemcpy(hostResult, devResult, size * sizeof(int), cudaMemcpyDeviceToHost);

  std::cout << "GPU Max Results: ";
  for (int i = 0; i < size; i++) {
    std::cout << hostResult[i] << " ";
  }
  std::cout << std::endl;

  cudaFree(devArr1);
  cudaFree(devArr2);
  cudaFree(devResult);

  return 0;
}

