// Computes Euclidean distance between two points
double euclideanDistance(const std::vector<double>& point1, const std::vector<double>& point2) {
    double sum = 0.0;
    for(size_t i=0; i<point1.size(); i++) {
        sum += std::pow(point1[i] - point2[i], 2);
    }
    return std::sqrt(sum);
}

