#include <stack>
#include <string>

// Checks if brackets in the input string are balanced
bool isBalanced(const std::string& input)
{
    std::stack<char> stack;
    for(char c : input)
    {
        if(c == '(' || c == '[' || c == '{')
        {
            stack.push(c);
        }
        else if(c == ')' || c == ']' || c == '}')
        {
            if(stack.empty())
            {
                return false;  // Unmatched closing symbol
            }
            char open = stack.top();
            stack.pop();
            if((c == ')' && open != '(') ||
               (c == ']' && open != '[') ||
               (c == '}' && open != '{'))
            {
                return false;  // Mismatched opening and closing symbols
            }
        }
    }
    // Return true if stack is empty, false otherwise
    return stack.empty();

}

