// Function to compute shortest path time using Dijkstra's algorithm
size_t getSegundos(const Graph<size_t>& graph, std::priority_queue<AristaDirigida<size_t>>& pq, size_t v, size_t destino) {
    std::vector<size_t> seconds(graph.adjacencyList.size(), -1); // Initialize all seconds to -1
    seconds[v] = 0; // Set the seconds for the starting vertex to 0

    while (!pq.empty()) {
        size_t currentVertex = pq.top().elem;
        pq.pop();

        if (currentVertex == destino) {
            return seconds[currentVertex]; // Return the seconds taken to reach the destination vertex
        }

        for (const AristaDirigida<size_t>& edge : graph.adj(currentVertex)) {
            size_t newSeconds = seconds[currentVertex] + edge.weight;

            if (seconds[edge.elem] == -1 || newSeconds < seconds[edge.elem]) {
                seconds[edge.elem] = newSeconds;
                pq.push({edge.elem, newSeconds});
            }
        }
    }

    return -1; // If the destination vertex is not reachable, return -1
}

int main() {
    // Example usage
    Graph<size_t> graph(5);
    graph.addEdge(0, 1, 2);
    graph.addEdge(0, 2, 5);
    graph.addEdge(1, 3, 3);
    graph.addEdge(2, 3, 1);
    graph.addEdge(3, 4, 4);

    std::priority_queue<AristaDirigida<size_t>> pq;
    pq.push({0, 0}); // Start from vertex 0

    size_t v = 0; // Current vertex
    size_t destino = 4; // Destination vertex

    size_t seconds = getSegundos(graph, pq, v, destino);
    std::cout << "Seconds taken to reach the destination: " << seconds << std::endl;

    return 0;
}

