        if (!PyArg_Parse(result, "T", &value))
        {
            PyErr_SetString(PyExc_TypeError, "Failed to parse Python object to C++ object");
            throw error_already_set();
        }

        Py_DECREF(result);
        return value;
    }

private:
    PyObject* base;
    T value;
};

