// Helper structure for high-level encoding
struct CBC_HighLevelEncoder {
  // Check if character is a digit
  static bool isDigit(wchar_t c) {
    return c >= L'0' && c <= L'9';
  }
};

// Encode two ASCII digits into a single character
std::optional<wchar_t> EncodeASCIIDigits(wchar_t digit1, wchar_t digit2)
{
    // Validate both digits
    if(!CBC_HighLevelEncoder::isDigit(digit1) ||
       !CBC_HighLevelEncoder::isDigit(digit2)) {
        return {};  // Return empty optional if either digit is invalid
    }

    // Convert ASCII digits to numeric values and encode
    wchar_t encodedChar = static_cast<wchar_t>((digit1 - L'0') * 10 + (digit2 - L'0') + 130);
    return encodedChar;
}
