// Function to manipulate vector
std::vector<std::pair<int, int>> manipulateVector(int M, int N)
{
    std::vector<std::pair<int, int>> ans;
    int L = 1;

    // Main loop
    while (M + 1 > 0)
    {
        --M;
        ans.push_back({ ++L, ++L });
    }

    // Add final pair
    ans.push_back({ 1, ++L });

    // Check size constraints
    if (ans.size() > N) return {};

    // Fill up to N elements
    while (ans.size() < N)
    {
        ans.push_back({ ++L, ++L });
    }

    return ans;
}

#include <vector>
using namespace std;

// Depth-first search to mark connected land cells
void dfs(vector<vector<char>>& grid, int i, int j)
{
    // Check boundaries and if current cell is land
    if(i < 0 || i >= grid.size() || j < 0 || j >= grid[0].size() || grid[i][j] != 'L')
    {
        return;
    }

    // Mark the cell as visited (convert to water)
    grid[i][j] = 'W';

    // Explore all 8 directions
    dfs(grid, i + 1, j);      // Below
    dfs(grid, i - 1, j);      // Above
    dfs(grid, i, j + 1);      // Right
    dfs(grid, i, j - 1);      // Left
    dfs(grid, i + 1, j + 1);  // Diagonally below-right
    dfs(grid, i - 1, j - 1);  // Diagonally above-left
    dfs(grid, i + 1, j - 1);  // Diagonally below-left
    dfs(grid, i - 1, j + 1);  // Diagonally above-right
}

// Count the number of connected land regions
int countConnectedLand(vector<vector<char>>& grid)
{
    int count = 0;

    // Traverse through each cell in the grid
    for(int i = 0; i < grid.size(); i++)
    {
        for(int j = 0; j < grid[0].size(); j++)
        {
            // If we find an unvisited land cell
            if(grid[i][j] == 'L')
            {
                count++;          // Increment region count
                dfs(grid, i, j);  // Mark all connected land cells
            }
        }
    }

    return count;
}

