enum class Type { None, Integer, Float, String, Boolean };

class TypeConverter {
public:
    // Converts a string to the corresponding Type enum value
    static Type fromString(const std::string& input)
    {
        static const std::unordered_map<std::string, Type> typeMap = {
            {"None", Type::None},
            {"Integer", Type::Integer},
            {"Float", Type::Float},
            {"String", Type::String},
            {"Boolean", Type::Boolean}
        };

        auto it = typeMap.find(input);
        if (it != typeMap.end())
        {
            return it->second;
        }
        else
        {
            return Type::None;
        }
    }
};

