// Exception for date parsing errors
class DateParsingException : public std::exception {
public:
    const char* what() const noexcept override {
        return "Date parsing exception";
    }
};

// Exception for date validation errors
class DateValidationException : public std::exception {
public:
    const char* what() const noexcept override {
        return "Date validation exception";
    }
};

// DateTime class for parsing and validating date-time strings
class DateTime {
private:
    int year, month, day, hour, minute, second;

public:
    // Constructor that parses a date-time string
    DateTime(const std::string& dateTimeStr) {
        std::regex dateTimeRegex(R"((\d{4})-(\d{2})-(\d{2}) (\d{2}):(\d{2}):(\d{2}))");
        std::smatch match;

        if (!std::regex_match(dateTimeStr, match, dateTimeRegex)) {
            throw DateParsingException();
        }

        year = std::stoi(match[1]);
        month = std::stoi(match[2]);
        day = std::stoi(match[3]);
        hour = std::stoi(match[4]);
        minute = std::stoi(match[5]);
        second = std::stoi(match[6]);

        if (!isValidDate(year, month, day) || !isValidTime(hour, minute, second)) {
            throw DateValidationException();
        }
    }

    // Validates the current date and time values
    void validateDateTime() {
        if (!isValidDate(year, month, day) || !isValidTime(hour, minute, second)) {
            throw DateValidationException();
        }
    }

private:
    // Checks if a year is a leap year
    bool isLeapYear(int year) {
        return (year % 4 == 0 && year % 100 != 0) || (year % 400 == 0);
    }

    // Validates if the given date is valid
    bool isValidDate(int year, int month, int day) {
        if (year < 1 || month < 1 || month > 12 || day < 1) {
            return false;
        }

        static const int daysInMonth[] = {0, 31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31};

        if (month == 2 && isLeapYear(year)) {
            return day <= 29;
        } else {
            return day <= daysInMonth[month];
        }
    }

    // Validates if the given time is valid
    bool isValidTime(int hour, int minute, int second) {
