enum class SymbolKind {
  Variable,
  Function,
  Class
};

enum class ContextType {
  Namespace,
  Class
};

struct SymbolInfo {
  std::string name;
  SymbolKind kind;
  std::string header;
  std::vector<std::pair<ContextType, std::string>> contexts;

  SymbolInfo(const std::string& name, SymbolKind kind, const std::string& header,
             std::vector<std::pair<ContextType, std::string>> contexts)
      : name(name), kind(kind), header(header), contexts(contexts) {}
};

class SymbolTracker {
private:
  std::unordered_map<std::string, std::unordered_map<std::string, bool>> seenMap;
  std::unordered_map<std::string, std::unordered_map<std::string, bool>> usedMap;

public:
  void seen(const SymbolInfo& symbol) {
    for (const auto& context : symbol.contexts) {
      seenMap[context.second][symbol.name] = true;
    }
  }

  void used(const SymbolInfo& symbol) {
    for (const auto& context : symbol.contexts) {
      usedMap[context.second][symbol.name] = true;
    }
  }

  bool isSeen(const std::string& context, const std::string& symbolName) {
    return seenMap[context][symbolName];
  }

  bool isUsed(const std::string& context, const std::string& symbolName) {
    return usedMap[context][symbolName];
  }
};

int main() {
  // Create tracker instance
  SymbolTracker tracker;

  // Define and track first symbol
  SymbolInfo symbol1("X2", SymbolKind::Variable, "HeaderName",
                    {{ContextType::Namespace, ""}});
  tracker.seen(symbol1);
  tracker.used(symbol1);

  // Define and track second symbol
  SymbolInfo symbol2("X3", SymbolKind::Variable, "HeaderName",
                    {{ContextType::Namespace, ""},
                     {ContextType::Namespace, ""}});
  tracker.seen(symbol2);
  tracker.used(symbol2);

  // Output verification results
  std::cout << "Symbol X2 seen and used in global namespace: "
            << tracker.isSeen("", "X2") << " " << tracker.isUsed("", "X2") << std::endl;
  std::cout << "Symbol X3 seen and used in global namespace: "
            << tracker.isSeen("", "X3") << " " << tracker.isUsed("", "X3") << std::endl;

  return 0;
}

