// Function to calculate the total memory consumption of a process
SIZE_T CalculateProcessMemoryUsage(DWORD processId)
{
    HANDLE hProcess = OpenProcess(PROCESS_QUERY_INFORMATION | PROCESS_VM_READ, FALSE, processId);
    if(hProcess == NULL)
    {
        // Handle error in opening the process
        return 0;
    }
    PROCESS_MEMORY_COUNTERS pmc;
    if(GetProcessMemoryInfo(hProcess, &pmc, sizeof(pmc)))
    {
        CloseHandle(hProcess);
        return pmc.WorkingSetSize;
    }
    else
    {
        // Handle error in getting process memory info
        CloseHandle(hProcess);
        return 0;
    }
}

