// Terrain types enumeration
enum TerrainType { GRASS, WATER, MOUNTAIN, DESERT };

// Generates a map with specified dimensions and terrain density
void map_gen(int width, int height, float density, int seed, int num_terrain_types)
{
    // Validate map dimensions
    if (width == 0 || height == 0)
    {
        throw std::invalid_argument("Map dimensions cannot be zero.");
    }

    // Validate density parameter
    if (density <= 0 || density > 1.0)
    {
        throw std::invalid_argument("Density must be in the range (0.0, 1.0].");
    }

    // Initialize random number generator
    std::mt19937 gen(seed);
    std::uniform_real_distribution<float> dis(0.0, 1.0);

    // Create map initialized with GRASS terrain
    std::vector<std::vector<TerrainType>> map(height, std::vector<TerrainType>(width, GRASS));

    // Populate map based on density
    for (int y = 0; y < height; ++y)
    {
        for (int x = 0; x < width; ++x)
        {
            float rand_val = dis(gen);
            if (rand_val < density)
            {
                int terrain_type = rand() % num_terrain_types;
                map[y][x] = static_cast<TerrainType>(terrain_type);
            }
        }
    }

    // Output the generated map
    for (int y = 0; y < height; ++y)
    {
        for (int x = 0; x < width; ++x)
        {
            std::cout << map[y][x] << " ";
        }
        std::cout << std::endl;
    }
}

// Main function
int main(int argc, char **argv)
{
    try
    {
        map_gen(30, 20, 1.0, 0, 4); // Example usage with error conditions
    }
    catch (const std::invalid_argument &e)
    {
        std::cerr << "Invalid argument: " << e.what() << std::endl;
    }
    return 0;
}

#include <cmath>

// Represents a 2D point
class Point {
private:
    double x, y;

public:
    // Constructor
    Point(double x, double y) : x(x), y(y) {}

    // Calculate distance to another point
    double distanceTo(const Point& other) {
        return sqrt(pow(other.x - x, 2) + pow(other.y - y, 2));
    }

    // Find midpoint with another point
    Point midpointWith(const Point& other) {
        double midX = (x + other.x) / 2;
        double midY = (y + other.y) / 2;
        return Point(midX, midY);
    }

    // Check if three points are collinear
    bool areCollinear(const Point& p2, const Point& p3) {
        return ((p2.y - y) * (p3.x - p2.x) == (p3.y - p2.y) * (p2.x - x));
    }
};

