// Checks if the corresponding ACK bit is set for a given sequence number
bool AckBitField::IsSetCorrespondingAckBit( PacketSN ackSN )
{
    uint32_t difference = 0;
    // Calculate the difference between latestAckSN_ and ackSN
    for( ; RealtimeSrvHelper::SNGreaterThan(latestAckSN_, ackSN++); ++difference );

    assert( difference );

    // Compute byte and bit offsets
    uint32_t byteOffset = ( difference - 1 ) >> 3;
    uint32_t bitOffset = ( difference - 1 ) & 0x7;

    // Check if the corresponding acknowledgment bit is set
    if( byteOffset < bitField.size() )
    {
        uint8_t byte = bitField[byteOffset];
        return ( byte & ( 1 << bitOffset ) ) != 0;
    }
    else
    {
        // Handle out-of-bounds access
        return false;
    }
}

