// Sets the error result for the task
void SetErrorResult(const Error& error)
{
    // Load current state and done flag atomically
    auto done = _done.load(std::memory_order_acquire);
    auto state = _state.load(std::memory_order_acquire);

    // Check if current state is Error
    if (state == util::ResultState::Error)
    {
        // Only set error if task is not yet marked as done
        if (!done)
        {
            Base::_core->SetResult({_error});
            _done.store(true, std::memory_order_release);  // Mark task as done
        }
    }
}

