// Finds the intersection of two string vectors
std::vector<std::string> findIntersection(const std::vector<std::string>& vec1, const std::vector<std::string>& vec2)
{
    std::unordered_map<std::string, int> countMap;
    std::vector<std::string> result;

    // Count occurrences of elements in vec1
    for(const auto& str : vec1)
    {
        countMap[str]++;
    }

    // Find intersection with vec2 and update result vector
    for(const auto& str : vec2)
    {
        if(countMap[str] > 0)
        {
            result.push_back(str);
            countMap[str]--;
        }
    }

    return result;
}

