// Calculates Euclidean distance between two points
double calculateDistance(const std::vector<double>& p1, const std::vector<double>& p2)
{
    double dist = 0;
    for(size_t i=0;i<p1.size();++i)
    {
        dist += pow(p1[i]-p2[i],2);
    }
    return sqrt(dist);
}

