// Class for computing derivative using backward difference
class Differentiator
{
public:
    // Constructor initializes state variables to zero
    Differentiator() : uZ1(0), yZ1(0) {}

    // Computes the derivative using the backward difference method
    unsigned int Differentiate(unsigned int input)
    {
        unsigned int derivative = input - uZ1;
        uZ1 = input;
        yZ1 = derivative;
        return derivative;
    }

    // Resets the internal state variables to zero
    void ClearStateVars()
    {
        uZ1 = 0;
        yZ1 = 0;
    }

private:
    unsigned int uZ1;  // Previous input value
    unsigned int yZ1;  // Previous output value
};

int main()
{
    Differentiator differentiator;

    // First differentiation: 5 - 0 = 5
    std::cout<<differentiator.Differentiate(5)<<std::endl;

    // Second differentiation: 8 - 5 = 3
    std::cout<<differentiator.Differentiate(8)<<std::endl;

    // Reset state and differentiate again
    differentiator.ClearStateVars();
    std::cout<<differentiator.Differentiate(10)<<std::endl;

    return 0;
}

