namespace Karm {

    /// Defer a computation until the end of the current scope.
    /// The computation is executed in the reverse order of the defer calls.
    export template <typename F>
    struct Defer : Meta::Pinned {
        F _f;

        always_inline Defer(F f) : _f(f) {}

        always_inline ~Defer() {
            _f();
        }
    };

    export template <typename F>
    Defer(F) -> Defer<F>;

    /// Defer a computation until the end of the current scope.
    /// The computation is executed in the reverse order of the defer calls.
    /// Can be disarm which will prevent the computation from being executed.
    export template <typename F>
    struct ArmedDefer : Meta::NoCopy {
        F _f;
        bool _armed = true;

        always_inline ArmedDefer(F f) : _f(f) {}

        always_inline ~ArmedDefer() {
            if (_armed)
                _f();
        }

        always_inline void disarm() {
            _armed = false;
        }

        always_inline void arm() {
            _armed = true;
        }

        always_inline void fire() {
            if (_armed)
                _f();
            disarm();
        }
    };

    export template <typename F>
    ArmedDefer(F) -> ArmedDefer<F>;

} // namespace Karm

#include <iostream>
#include <vector>
#include <numeric>
#include <algorithm>

// Function to perform a query and read the result.
// It's good practice to have this helper for interactive problems.
int query(int i, int j)
{
    std::cout << "? " << i << " " << j << std::endl;
    int result;
    std::cin >> result;
    // On receiving -1, it means an error occurred (e.g., invalid query or query limit exceeded).
    // The program should terminate immediately.
    if (result == -1) {
        exit(0);
    }
    return result;
}

int main()
{
    // Fast I/O
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(NULL);

    int n;
    std::cin >> n;

    std::vector<int> p(n + 1);
    std::vector<int> or_w_1(n + 1);

    // Step 1: Query p[1] with all other elements
    for (int i = 2; i <= n; ++i) {
        or_w_1[i] = query(1, i);
    }

    // Step 2: Determine p[1].
    // p[1] = (p[1]|p[2]) & (p[1]|p[3]) & ... & (p[1]|p[n])
    // This works because for n>=3, the bitwise AND of all numbers in {0..n-1} except any one value is 0.
    int p1_val = -1; // Represents all bits set
    for (int i = 2; i <= n; ++i) {
        if (p1_val == -1) {
            p1_val = or_w_1[i];
        } else {
            p1_val &= or_w_1[i];
        }
    }
    p[1] = p1_val;

    // Step 3: Determine p[2]...p[n].
    // For each i > 1, we know p[1] and p[1]|p[i].
    // Since p is a permutation of {0..n-1}, we can uniquely determine p[i].
    // A simple method that works is to recognize that one of p[j] must be 0.
    // If p[k] = 0, then p[1]|p[k] = p[1]. The set {p[1]|p[i] for i=2..n} will contain p[1].
    // The set {p[1], p[1]|p[2], ..., p[1]|p[n]} is in fact the set {p[1], ..., p[n]},
    // because for each p[i], there is a query result p[1]|p[i], and for p[1],
    // there is a p[k]=0, so p[1]|p[k]=p[1].
    // So the values of p[2] to p[n] are simply the results of the OR queries with p[1].
    for (int i = 2; i <= n; ++i) {
        p[i] = or_w_1[i];
    }

    // Output the final answer
    std::cout << "!";
    for (int i = 1; i <= n; ++i) {
        std::cout << " " << p[i];
    }
    std::cout << std::endl;

    return 0;
}

#include <cstdint>
#include <generic/arch.hpp>
#include <arch/riscv64/features.hpp>

namespace arch {

    // Disables interrupts by clearing the SIE bit in sstatus
    [[gnu::weak]] void disable_interrupts()
    {
        asm volatile("csrc sstatus, %0" : : "r"(1 << 1));
    }

    // Enables interrupts by setting the SIE bit in sstatus
    [[gnu::weak]] void enable_interrupts()
    {
        asm volatile("csrs sstatus, %0" : : "r"(1 << 1));
    }

    // Waits for an interrupt using the WFI instruction
    [[gnu::weak]] void wait_for_interrupt()
    {
        asm volatile("wfi");
    }

    // Halts the CPU by disabling interrupts and entering an infinite loop with WFI
    [[gnu::weak]] void hcf()
    {
        disable_interrupts();
        while(true)
        {
            wait_for_interrupt();
        }
    }

    // Provides a hint to the processor that performance can be improved by pausing
    [[gnu::weak]] void pause()
    {
#ifdef __riscv_zihintpause
        asm volatile("pause");
#else
        asm volatile("nop");
#endif
    }

    // Flushes TLB entries for a given memory range
    [[gnu::weak]] void tlb_flush(std::uintptr_t hint, std::uintptr_t len)
    {
        if (len / PAGE_SIZE > 256 || len == 0)
        {
            asm volatile("sfence.vma");
        }
        else
        {
            for (std::uintptr_t i = 0; i < len; i += PAGE_SIZE)
            {
                asm volatile("sfence.vma %0" : : "r"(hint + i) : "memory");
            }
        }
    }

    // Returns the architecture name
    [[gnu::weak]] const char* name()
    {
        return "riscv64";
    }

    // Returns the paging level used by the RISC-V implementation
    [[gnu::weak]] int level_paging()
    {
        return riscv64::get_paging_level();
    }

    // Initialization function (stage parameter unused)
    [[gnu::weak]] void init(int stage)
    {
        (void)stage;
    }

}

