class Solution {
public:
    // Returns the maximum number by changing at most one digit
    int maximum69Number (int num)
    {
        int i{1000};
        while(i != 0 && (num / i) % 10 != 6)
            i /= 10;
        // Add 3*i to change the first 6 to 9
        return num + 3*i;
    }
};

