MainWindow::MainWindow(QWidget *parent)
    : QMainWindow(parent)
    , ui(new Ui::MainWindow)
{
    ui->setupUi(this);

    // Initialize the visualization widget
    this->viswidget_init();

    // Set up initial HexGrid visual model
    this->setupHexGridVisual();

    // Timer for animation and data updates
    auto timer = new QTimer(parent);
    connect(timer, &QTimer::timeout, [this] {
        for (unsigned int hi = 0; hi < this->hg->num(); ++hi) {
            this->r[hi] = std::sqrt(hg->d_x[hi] * hg->d_x[hi] + hg->d_y[hi] * hg->d_y[hi]);
            this->data[hi] = std::sin(k * r[hi]) / k * r[hi];
        }
        this->k += 0.02f;
        if (this->k > 8.0f) {
            this->k = 1.0f;
        }

        // Signal that model 0 needs reinitialization
        static_cast<mplot::qt::viswidget<0>*>(this->p_vw)->set_model_needs_reinit(0);

        // Trigger OpenGL update
        this->p_vw->update();
    });
    timer->start();
}

MainWindow::~MainWindow()
{
    delete ui;
}

void MainWindow::setupHexGridVisual()
{
    // Create hexagonal grid
    this->hg = std::make_unique<sm::hexgrid>(0.02f, 15.0f, 0.0f);
    this->hg->setCircularBoundary(4.0f);

    // Prepare data arrays
    this->data.resize(this->hg->num(), 0.0f);
    this->r.resize(this->hg->num(), 0.0f);
    this->k = 1.0f;

    // Compute initial data values
    for (unsigned int hi = 0; hi < this->hg->num(); ++hi) {
        this->r[hi] = std::sqrt(hg->d_x[hi] * hg->d_x[hi] + hg->d_y[hi] * hg->d_y[hi]);
        this->data[hi] = std::sin(k * r[hi]) / k * r[hi];
    }

    // Create HexGridVisual with offset
    sm::vec<float, 3> offset = { 0.0f, -0.05f, 0.0f };
    auto hgv = std::make_unique<mplot::HexGridVisual<float, mplot::qt::gl_version>>(hg.get(), offset);

    // Bind model to shader programs
    static_cast<mplot::qt::viswidget<0>*>(this->p_vw)->v.bindmodel(hgv);

    // Attach scalar data
    hgv->setScalarData(&this->data);

    // Add to visual models list
    std::unique_ptr<mplot::VisualModel<mplot::qt::gl_version>> vmp = std::move(hgv);
    static_cast<mplot::qt::viswidget<0>*>(this->p_vw)->newvisualmodels.push_back(std::move(vmp));
}

void MainWindow::viswidget_init()
{
    // Create and configure visualization widget
    mplot::qt::viswidget<0>* vw = new mplot::qt::viswidget<0>(this->parentWidget());
    vw->v.lightingEffects();

    // Add to UI layout
    this->ui->verticalLayout->addWidget(vw);
    this->p_vw = vw;
}

void MainWindow::on_actionQuit_triggered()
{
    close();
}

