#include <iostream>
#include <vector>
#include <queue>
#include <cmath> // For std::abs

// This code solves LeetCode problem 1046: Last Stone Weight
// Problem: Simulate smashing stones until at most one remains.
// Equal weights destroy both; unequal weights leave their difference.
using namespace std;

class Solution {
public:
    int lastStoneWeight(std::vector<int>& stones)
    {
        // Create a max-heap to store stone weights
        // By default, std::priority_queue is a max-heap
        std::priority_queue<int> maxHeap;

        // Add all stones to the max-heap
        for(int ele : stones)
        {
            maxHeap.push(ele);
        }

        // Continue smashing stones while at least two remain
        while(maxHeap.size() > 1)
        {
            // Get the heaviest stone
            int s1 = maxHeap.top();
            maxHeap.pop();

            // Get the second heaviest stone
            int s2 = maxHeap.top();
            maxHeap.pop();

            // If stones have different weights, push their difference
            if(s1 != s2)
            {
                // s1 >= s2 due to max-heap properties
                maxHeap.push(std::abs(s1 - s2));
            }
            // If equal, both destroyed (nothing pushed back)
        }

        // Return remaining stone weight or 0 if none left
        if(maxHeap.empty())
        {
            return 0;
        }
        else
        {
            return maxHeap.top();
        }
    }
};

#include <vector>
#include <algorithm>

class Solution {
public:
    // Finds pairs with minimum absolute difference
    vector<vector<int>> minimumAbsDifference(vector<int>& arr) {
        int n = arr.size();
        sort(arr.begin(), arr.end());
        int diff = 0;

        if (n < 2) return {};

        int mindiff = arr[1] - arr[0];
        for (int i = 0; i < n - 1; i++) {
            diff = arr[i + 1] - arr[i];
            mindiff = min(diff, mindiff);
        }

        vector<vector<int>> result;
        for (int i = 0; i < n - 1; i++) {
            if (arr[i + 1] - arr[i] == mindiff) {
                result.push_back({arr[i], arr[i + 1]});
            }
        }
        return result;
    }
};

#include <iostream>
#include <unordered_map>
#include <queue>
using namespace std;

// Function to find the first unique character in a string
char firstUniqueChar(const string& str)
{
    unordered_map<char, int> charCount;
    queue<char> charQueue;

    // Count occurrences of each character and maintain their order
    for(char ch : str)
    {
        if(charCount.find(ch) == charCount.end())
        {
            charCount[ch] = 1;
            charQueue.push(ch);
        }
        else
        {
            charCount[ch]++;
        }

        // Remove characters from the front of the queue that are no longer unique
        while(!charQueue.empty() && charCount[charQueue.front()] > 1)
        {
            charQueue.pop();
        }
    }

    return charQueue.empty() ? '\0' : charQueue.front();
}

// Example usage
int main()
{
    string str = "level";
    char result = firstUniqueChar(str);

    if(result != '\0')
    {
        cout << "The first unique character is: " << result << endl;
    }
    else
    {
        cout << "No unique character found." << endl;
    }

    return 0;
}

