#include "llvm/IR/GCStrategy.h"
#include "llvm/ADT/Twine.h"
#include "llvm/IR/BuiltinGCs.h"

using namespace llvm;

// Instantiate the registry
LLVM_INSTANTIATE_REGISTRY(GCRegistry)

// Default constructor for GCStrategy
GCStrategy::GCStrategy() = default;

// Get a GC strategy by name
std::unique_ptr<GCStrategy> llvm::getGCStrategy(const StringRef Name) {
  // Search through registered strategies
  for (auto &S : GCRegistry::entries())
    if (S.getName() == Name)
      return S.instantiate();

  // Ensure builtin GCs are linked when using static library
  // This prevents linker from discarding registration code
  llvm::linkAllBuiltinGCs();

  // Check if registry is empty (likely missing initialization)
  if (GCRegistry::begin() == GCRegistry::end()) {
    const std::string error =
        std::string("unsupported GC: ") + Name.str() +
        " (did you remember to link and initialize the library?)";
    report_fatal_error(Twine(error));
  } else {
    // Registry has entries but requested GC not found
    report_fatal_error(Twine(std::string("unsupported GC: ") + Name.str()));
  }
}

