namespace Abc = Alembic::Abc;
namespace Mat = Alembic::AbcMaterial;

// Write material hierarchy to archive
void write()
{
    Abc::OArchive archive(
        Alembic::AbcCoreOgawa::WriteArchive(), "FlattenMaterial.abc" );
    Abc::OObject root(archive, Abc::kTop);

    // Make a dummy enclosing object
    Abc::OObject materials(root, "materials");
    Mat::OMaterial parentMaterial(materials, "parentMaterial");

    parentMaterial.getSchema().setShader("prman", "surface", "paintedplastic");
    parentMaterial.getSchema().setShader("prman", "displacement", "knobby");

    {
        Abc::OFloatProperty prop(
            parentMaterial.getSchema().getShaderParameters(
                "prman", "surface"),
            "Kd");
        prop.set(0.5);
    }

    {
        Abc::OStringProperty prop(
            parentMaterial.getSchema().getShaderParameters(
                "prman", "surface"), "texname");
        prop.set("taco");
    }

    {
        Abc::OFloatProperty prop(
            parentMaterial.getSchema().getShaderParameters(
                "prman", "displacement"),
            "height");
        prop.set(0.75);
    }

    Mat::OMaterial childMaterial(parentMaterial, "childMaterial");
    childMaterial.getSchema().setShader("prman", "surface",
        "betterpaintedplastic");

    {
        Abc::OStringProperty prop(
            childMaterial.getSchema().getShaderParameters(
                "prman", "surface"), "texname");
        prop.set("cheese");
    }
}

// Read and print material information
void read()
{
    Abc::IArchive archive(Alembic::AbcCoreOgawa::ReadArchive(),
        "FlattenMaterial.abc");
    Abc::IObject materialsObject(archive.getTop(), "materials");

    Mat::IMaterial parentMaterial(materialsObject, "parentMaterial");
    Mat::IMaterial childMaterial(parentMaterial, "childMaterial");

    std::cout << "----------------------------------------\n";
    std::cout << "LOCAL\n";
    std::cout << "---------------------------\n";
    std::cout << "Local parent material\n";
    std::cout << "---------------------------\n";
    printMaterialSchema(parentMaterial.getSchema());

    std::cout << "---------------------------\n";
    std::cout << "Local child material\n";
    std::cout << "---------------------------\n";
    printMaterialSchema(childMaterial.getSchema());

    std::cout << "----------------------------------------\n";
    std::cout << "FLATTENED\n";
    printFlattenedMaterial(parentMaterial);
    printFlattenedMaterial(childMaterial);
}

int main(int argc, char *argv[])
{
    write();
    read();
    return 0;
}

#include "app_state.hpp"
#include "curses_interface.hpp"

#include <boost/filesystem/operations.hpp>
#include <boost/filesystem/path.hpp>

#include <iostream>

// Main entry point
int main(int argc, char * argv[])
{
    // Check for required filename argument
    if (argc < 2) {
        std::cerr << "error: You must supply at least a filename.\n";
        return 1;
    }

    // Process the provided path
    boost::filesystem::path path(argv[1]);
    if (!exists(path)) {
        std::cerr << "error: Could not access filename " << argv[1] << ".\n";
        return 1;
    }

    // Requirement of libcurses.
    std::locale::global(std::locale(""));

    // Initialize curses interface
    curses_interface_t curses_interface;

    // Read the size, but just this once; resizing is not supported.
    auto const screen_size = curses_interface.screen_size();

    // Initialize application state
    app_state_t app_state = {
        // Initial state is the contents of the file from the command line.
        load_buffer(path, curses_interface.screen_size().col_),
        // Keybindings are simplified Emacs.
        emacs_lite()
    };

    // Initial render
    render(app_state.buffer_, screen_size);

    // Loop until the user says we're done.  Each iteration blocks for an
    // event from libcurses, then passes the current app state and the event
    // to update(), which returns the new app state.
    boost::optional<app_state_t> next_app_state;
    while (
        (next_app_state =
             update(std::move(app_state), curses_interface.next_event()))) {
        app_state = *next_app_state;
        render(app_state.buffer_, screen_size);
    }

    return 0;
}

