// Choose your OpenGL version for your app here
// Options defined in mplot/gl/version.h
constexpr int gl_version = mplot::gl::version_4_1;

// Your application-specific frame, deriving from mplot::wx::Frame
// In this frame, VisualModels are set up
class MyFrame : public mplot::wx::Frame<gl_version>
{
public:
    MyFrame(const wxString &title)
        : mplot::wx::Frame<gl_version>(title)
    {
        auto sizer = new wxBoxSizer(wxVERTICAL);

        // Adding the GL canvas, where all the mathplot stuff will be drawn
        sizer->Add(this->canvas, 1, wxEXPAND);

        auto bottomSizer = new wxBoxSizer(wxHORIZONTAL);

        auto colorButton = new wxButton(this, wxID_ANY, "Change Color");
        bottomSizer->Add(colorButton, 0, wxALL | wxALIGN_CENTER, FromDIP(15));
        bottomSizer->AddStretchSpacer(1);

        sizer->Add(bottomSizer, 0, wxEXPAND);

        SetSizerAndFit(sizer);

        // Bind button click to open color dialog and refresh canvas
        colorButton->Bind(wxEVT_BUTTON, [this]([[maybe_unused]] wxCommandEvent &event) {
            wxColourData colorData;
            wxColourDialog dialog(this, &colorData);
            if (dialog.ShowModal() == wxID_OK) {
                this->canvas->Refresh();
            }
        }); // end of lambda
    }

    // Data for the x axis. A vvec is like std::vector, but with built-in maths methods
    sm::vvec<double> x;

    // Member variable used to update GraphVisual
    double dx = 0.0;

    // A pointer to our GraphVisual
    mplot::GraphVisual<double, gl_version>* graph_ptr = nullptr;

    // A function to make a dynamic update to the model
    void updateModel()
    {
        this->dx += 0.01;
        this->graph_ptr->update(this->x, (this->x + this->dx).sin(), 0);

        // Now we mark that VisualModel 0 (the first and only VisualModel that we added in
        // setupVisualModels) needs to be reinitialized.
        this->canvas->needs_reinit = 0;
    }

    // To set up the VisualModels in the widget, the GL context must have been initialized.
    // So I'll have to have a callback in viswidget (soon to be viscanvas) which will call this function
    // after gl init has completed.
    void setupVisualModels()
    {
        if (this->canvas->ready()) {
            // We can now add VisualModels to the Visual inside the Widget.
            // Create a GraphVisual object (obtaining a unique_ptr to the object)
            // with a spatial offset within the scene of 0,0,0
            auto gv = std::make_unique<mplot::GraphVisual<double, gl_version>>(sm::vec<float>({0, 0, 0}));

            // This mandatory line of boilerplate code sets the parent pointer in GraphVisual and binds some functions
            this->canvas->v.bindmodel(gv);

            // Allow 3D rendering
            gv->twodimensional(false);

            // This works like numpy's linspace() (the 3 args are "start", "end" and "num"):
            this->x.linspace(-sm::mathconst<double>::pi, sm::mathconst<double>::pi, 100);

            // Set a graph up of y = sin(x + dx)
            gv->setdata(this->x, (this->x + this->dx).sin());

            // finalize() makes the GraphVisual compute the vertices of the OpenGL model
            gv->finalize(); // Requires opengl context

            // Add the GraphVisual OpenGL model to the Visual scene, transferring ownership of the unique_ptr
            std::cout << "add visualmodel to mplot::wx::Canvas" << std::endl;
            this->graph_ptr = this->canvas->v.addVisualModel(gv);
        } else {
            // Not ready
            throw std::runtime_error("Canvas is not ready (no gl context yet)");
        }
    }
};

