{
    if (!wxApp::OnInit()) { return false; }

    MyFrame *frame = new MyFrame("Hello OpenGL");
    frame->Show(true);

    // After calling Show(), initialize the visual models
    frame->setupVisualModels();

    // put updateModel() on a timer.
    return true;
}

