#include "Transform/LowerSelect.h"

#include <llvm/IR/Constants.h>
#include <llvm/IR/Instructions.h>
#include <llvm/IR/Verifier.h>
#include <llvm/Support/Debug.h>

#define DEBUG_TYPE "lower-select"

// Transform a select instruction into explicit if/else control flow.
// Creates two new basic blocks for the true and false cases, connected by
// a conditional branch from the original block.
static void transform(Instruction *Select)
{
    auto *Function = Select->getFunction();
    auto *BranchBB = Select->getParent();

    // Note that all instructions BEFORE the specified iterator
    // stay as part of the original basic block, an unconditional branch is added
    // to the original BB, and the rest of the instructions in the BB are moved
    // to the new BB, including the old terminator.  The newly formed basic block
    // is returned. This function invalidates the specified iterator.
    BasicBlock *PhiBB = Select->getParent()->splitBasicBlock(Select, "");

    auto *TrueBB = BasicBlock::Create(Select->getContext(), "", Function, PhiBB);
    BranchInst::Create(PhiBB, TrueBB);

    auto *FalseBB = BasicBlock::Create(Select->getContext(), "", Function, PhiBB);
    BranchInst::Create(PhiBB, FalseBB);

    BranchBB->getTerminator()->eraseFromParent();
    BranchInst::Create(TrueBB, FalseBB, Select->getOperand(0), BranchBB);

    auto *Phi = PHINode::Create(Select->getType(), 2, "", Select);
    Phi->addIncoming(Select->getOperand(1), TrueBB);
    Phi->addIncoming(Select->getOperand(2), FalseBB);

    Select->replaceAllUsesWith(Phi);
    Select->eraseFromParent();
}

// New Pass Manager entry point. Finds all select instructions (excluding
// pointer selects) and transforms them into explicit if/else control flow.
PreservedAnalyses LowerSelectPass::run(Module &M, ModuleAnalysisManager &)
{
    std::vector<SelectInst *> Selects;

    for (auto &F : M)
    {
        for (auto &B : F)
        {
            for (auto &I : B)
            {
                if (I.getType()->isPointerTy())
                    continue;

                if (auto *SI = dyn_cast<SelectInst>(&I))
                {
                    Selects.push_back(SI);
                }
            }
        }
    }

    if (Selects.empty())
        return PreservedAnalyses::all();

    for (auto *Select : Selects)
        transform(Select);

    if (verifyModule(M, &errs()))
    {
        llvm_unreachable("Error: Lowerselect fails...");
    }

    // CFG is modified, invalidate most analyses
    return PreservedAnalyses::none();
}

#include <iostream>
#include <vector>
#include <string>
#include <algorithm>

using namespace std;

int main()
{
    // Optimize standard I/O operations for performance
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n, m;
    // Check for successful input reading
    if (cin >> n >> m)
    {
        // Weights for each participant, initialized to 1.0.
        // We use the Multiplicative Weights Update algorithm.
        vector<double> w(n, 1.0);

        // The penalty factor (beta).
        // A value in the range [0.8, 0.95] is typically effective for such problems.
        // It determines how quickly we discard experts who make mistakes.
        // beta = 0.9 provides a good balance between stability and adaptability.
        double beta = 0.9;
        string s;
        // Reserve memory to avoid reallocations
        s.reserve(n);

        for (int t = 0; t < m; ++t)
        {
            cin >> s;

            double sum0 = 0.0;
            double sum1 = 0.0;

            // Calculate the weighted vote for '0' and '1'
            for (int i = 0; i < n; ++i)
            {
                if (s[i] == '0')
                {
                    sum0 += w[i];
                }
                else
                {
                    sum1 += w[i];
                }
            }

            // Predict the outcome with the higher weighted sum
            int prediction = (sum1 > sum0) ? 1 : 0;
            cout << prediction << endl; // endl flushes the output, required for interaction

            int outcome;
            cin >> outcome;

            // Update weights based on the actual outcome
            // Reduce the weight of participants who guessed incorrectly
            for (int i = 0; i < n; ++i)
            {
                int guess = s[i] - '0';
                if (guess != outcome)
                {
                    w[i] *= beta;
                }
            }

            // Renormalize weights to prevent floating-point underflow
            // We track the maximum weight and scale up if it becomes too small.
            double max_w = 0.0;
            for (double val : w)
            {
                if (val > max_w)
                    max_w = val;
            }

            // If the maximum weight is very small, multiply all weights by a large factor
            if (max_w < 1e-150)
            {
                for (int i = 0; i < n; ++i)
                {
                    w[i] *= 1e150;
                }
            }
        }
    }

    return 0;
}

#include <gtest/gtest.h>
#include <jonssonic/core/common/circular_audio_buffer.h>

using namespace jnsc;

// Test resize and basic write/read operations
TEST(CircularAudioBufferTest, ResizeAndWriteRead)
{
    CircularAudioBuffer<float> buffer;
    buffer.resize(2, 8);
    EXPECT_EQ(buffer.getNumChannels(), 2u);
    EXPECT_EQ(buffer.getBufferSize(), 8u);

    // Write and read
    buffer.write(0, 1.0f);
    buffer.write(1, 2.0f);
    EXPECT_FLOAT_EQ(buffer.read(0, 0), 1.0f);
    EXPECT_FLOAT_EQ(buffer.read(1, 0), 2.0f);
}

// Test circular behavior when writing beyond buffer size
TEST(CircularAudioBufferTest, WrapAround)
{
    CircularAudioBuffer<float> buffer;
    buffer.resize(1, 4);

    // Write more than buffer size to test wrap
    for(int i=0; i<6; ++i)
        buffer.write(0, float(i));

    // The most recent is 5, then 4, 3, 2
    EXPECT_FLOAT_EQ(buffer.read(0, 0), 5.0f);
    EXPECT_FLOAT_EQ(buffer.read(0, 1), 4.0f);
    EXPECT_FLOAT_EQ(buffer.read(0, 2), 3.0f);
    EXPECT_FLOAT_EQ(buffer.read(0, 3), 2.0f);
}

// Test clear functionality
TEST(CircularAudioBufferTest, Clear)
{
    CircularAudioBuffer<float> buffer;
    buffer.resize(1, 4);
    buffer.write(0, 1.0f);
    buffer.write(0, 2.0f);
    buffer.clear();
    buffer.write(0, 3.0f);
    EXPECT_FLOAT_EQ(buffer.read(0, 0), 3.0f);
}

// Test multi-channel buffer behavior
TEST(CircularAudioBufferTest, MultiChannel)
{
    CircularAudioBuffer<float> buffer;
    buffer.resize(2, 4);

    for(int i=0; i<4; ++i)
    {
        buffer.write(0, float(i));
        buffer.write(1, float(i + 10));
    }

    EXPECT_FLOAT_EQ(buffer.read(0, 0), 3.0f);
    EXPECT_FLOAT_EQ(buffer.read(1, 0), 13.0f);
    EXPECT_FLOAT_EQ(buffer.read(0, 3), 0.0f);
    EXPECT_FLOAT_EQ(buffer.read(1, 3), 10.0f);
}

