using asio::ip::tcp;

// HTTP client example using Boost.Asio
int main(int argc, char* argv[])
{
  try
  {
    // Check command line arguments
    if (argc != 3)
    {
      std::cout << "Usage: http_client <server> <path>\n";
      std::cout << "Example:\n";
      std::cout << "  http_client www.boost.org /LICENSE_1_0.txt\n";
      return 1;
    }

    // Create TCP stream for HTTP communication
    asio::ip::tcp::iostream s;

    // Set timeout for the entire sequence of I/O operations
    s.expires_after(std::chrono::seconds(60));

    // Establish connection to the server
    s.connect(argv[1], "http");

    // Verify connection was successful
    if (!s)
    {
      std::cout << "Unable to connect: " << s.error().message() << "\n";
      return 1;
    }

    // Send HTTP GET request
    s << "GET " << argv[2] << " HTTP/1.0\r\n";
    s << "Host: " << argv[1] << "\r\n";
    s << "Accept: */*\r\n";
    s << "Connection: close\r\n\r\n";

    // Read and validate HTTP response version
    std::string http_version;
    s >> http_version;

    // Read status code
    unsigned int status_code;
    s >> status_code;

    // Read status message
    std::string status_message;
    std::getline(s, status_message);

    // Validate HTTP response format
    if (!s || http_version.substr(0, 5) != "HTTP/")
    {
      std::cout << "Invalid response\n";
      return 1;
    }

    // Check status code is OK (200)
    if (status_code != 200)
    {
      std::cout << "Response returned with status code " << status_code << "\n";
      return 1;
    }

    // Print response headers until blank line
    std::string header;
    while (std::getline(s, header) && header != "\r")
      std::cout << header << "\n";

    std::cout << "\n";

    // Output the remaining content (response body)
    std::cout << s.rdbuf();
  }
  catch (std::exception& e)
  {
    std::cout << "Exception: " << e.what() << "\n";
  }

  return 0;
}

class Solution {
public:
    // Defangs an IP address by replacing '.' with '[.]'
    string defangIPaddr(string address)
    {
        string ans;
        for(int i=0;i<address.size();i++)
        {
            if(address[i]=='.')
            {
                ans = ans+"[.]";
            }
            else
            {
                ans.push_back(address[i]);
            }
        }
        return ans;
    }
};

