// Constructor for XmlFuseWriter
XmlFuseWriter::XmlFuseWriter(QFile &XFile) : XflXmlWriter(XFile)
{
}

// Writes the header section of the XML document
void XmlFuseWriter::writeHeader()
{
    writeDTD("<!DOCTYPE flow5>");
    writeStartElement("xflfuse");
    writeAttribute("version", "1.0");

    writeStartElement("Units");
    {
        // Write length unit conversion factor
        writeTextElement("length_unit_to_meter", QString("%1").arg(1./Units::mtoUnit()));
        // Write mass unit conversion factor
        writeTextElement("mass_unit_to_kg", QString("%1").arg(1./Units::kgtoUnit()));
    }
    writeEndElement();
}

// Writes the complete XML representation of a FuseXfl object
void XmlFuseWriter::writeXMLFuse(FuseXfl const *pFuse)
{
    writeStartDocument();
    writeHeader();

    writeStartElement("xflfuse");
    {
        // Write basic properties
        writeTextElement("Name", pFuse->name());
        writeTextElement("Description", pFuse->description());

        // Add comment about auto inertia behavior
        writeComment("If the field AUTOINERTIA is set to TRUE, the fields COG and COG_I** will be ignored");

        // Write inertia settings
        writeTextElement("AutoInertia", xfl::boolToString(pFuse->bAutoInertia()));
        writeInertia(pFuse->inertia());

        writeEndElement();
        writeXflFuse(*pFuse, Vector3d());
    }
    writeEndElement();
    writeEndDocument();
}

#include "layoutmanager.hpp"

// Constructor for Rect
Rect::Rect(float x, float y, float width, float height) : x(x), y(y), width(width), height(height) { }

// Constructor for LayoutManager
LayoutManager::LayoutManager(float x, float y, float width, float height) : m_current(x, y, width, height) {
}

// Returns the current rectangle
const Rect& LayoutManager::current() const {
    return m_current;
}

// Creates a copy of the LayoutManager
LayoutManager LayoutManager::copy() const {
    return LayoutManager(m_current.x, m_current.y, m_current.width, m_current.height);
}

// Pads with equal padding on all sides
void LayoutManager::pad(float padding) {
    pad(padding, padding);
}

// Pads with different vertical and horizontal padding
void LayoutManager::pad(float paddingY, float paddingX) {
    m_current.x += paddingX;
    m_current.y += paddingY;
    m_current.width -= paddingX * 2;
    m_current.height -= paddingY * 2;
}

// Pads only the left side
void LayoutManager::padLeft(float padding) {
    m_current.x += padding;
    m_current.width -= padding;
}

// Pads only the right side
void LayoutManager::padRight(float padding) {
    m_current.width -= padding;
}

// Pads only the top (up)
void LayoutManager::padUp(float padding) {
    m_current.y += padding;
    m_current.height -= padding;
}

// Pads only the bottom (down)
void LayoutManager::padDown(float padding) {
    m_current.height -= padding;
}

// Applies border inset
void LayoutManager::border(float border_size) {
    m_current.x += border_size;
    m_current.y += border_size;
    m_current.width -= border_size * 2;
    m_current.height -= border_size * 2;
}

// Adds horizontal gap
void LayoutManager::gapX(float gap_size) {
    m_current.x += gap_size;
    m_current.width -= gap_size;
}

// Adds vertical gap
void LayoutManager::gapY(float gap_size) {
    m_current.y += gap_size;
    m_current.height -= gap_size;
}

// Slices off the top portion
LayoutManager LayoutManager::sliceTop(float height) {
    LayoutManager slice(m_current.x, m_current.y, m_current.width, height);
    m_current.y += height;
    m_current.height -= height;
    return slice;
}

// Slices off the left portion
LayoutManager LayoutManager::sliceLeft(float width) {
    LayoutManager slice(m_current.x, m_current.y, width, m_current.height);
    m_current.x += width;
    m_current.width -= width;
    return slice;
}

#include <bits/stdc++.h>
using namespace std;

// This is the known constructive solution that produces a grid of size <= 300
// which yields exactly x paths from (1,1) to (n,n) moving only right/down on 1-cells.
//
// Construction adapted from the classic "Inverse Counting Path" approach using a 32-row snake,
// extended to support up to ~1e18 with <= 64 rows. This version uses 65 rows.

int main()
{
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long x;
    if (!(cin >> x)) return 0;

    // We'll construct a grid with n = 65. This is enough to represent up to 2^60 (~1e18) paths.
    // The construction follows the Codeforces 1100D-like "snake" approach.
    // Initialize all to 0.
    const int N = 65;
    vector<vector<int>> a(N, vector<int>(N, 0));

    // Build the snake triangle:
    // For each row i (1-indexed), we fill a contiguous block of 1's of length i.
    // For odd rows: block is on the left from column 1 to i.
    // For even rows: block is on the right from column N-i+1 to N.
    // This creates a "snake" ensuring dp values across rows represent all numbers up to 2^(i-1).
    for (int i = 1; i <= N; ++i)
    {
        if (i % 2 == 1)
        {
            for (int j = 1; j <= i; ++j) a[i-1][j-1] = 1;
        }
        else
        {
            for (int j = 0; j < i; ++j) a[i-1][N-1-j] = 1;
        }
    }

    // Now connect additional columns per row to encode x:
    // We process bits of x in LSB-to-MSB order, enabling a vertical path from the chosen column
    // in each row based on the current bit.
    // Start with rem = x - 1 (so that minimum x=1 uses the leftmost path).
    long long rem = x - 1;

    for (int i = 2; i <= N; ++i)
    {
        // For each row i starting from 2, we allow a drop in the column corresponding to the bit.
        // If bit (i-2) is set in rem, we open the entire tail of that row to the next rows to include those paths.
        if (i % 2 == 1)
        {
            // Odd row: left-to-right
            if (rem & 1LL)
            {
                for (int j = i+1; j <= N; ++j) a[i-1][j-1] = 1;
            }
        }
        else
        {
            // Even row: right-to-left
            if (rem & 1LL)
            {
                for (int j = 1; j <= N - i; ++j) a[i-1][j-1] = 1;
            }
        }
        rem >>= 1;
        if (rem == 0)
        {
            // No more bits; for remaining rows, do nothing.
            // But ensure path to the end remains possible:
            // already guaranteed by the snake base.
        }
    }

    cout << N << "\n";
    for (int i = 0; i < N; ++i)
    {
        for (int j = 0; j < N; ++j)
        {
            cout << a[i][j] << (j+1==N?'\n':' ');
        }
    }

    return 0;
}

