#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

class Solution {
    public:
        // Find next lexicographical permutation
        void nextPermutation(vector<int>& nums) {
            int n = nums.size();
            int piv = -1;

            // Step 1: Find the first element from the right that is smaller than the next one
            for (int i = n - 2; i >= 0; i--) {
                if (nums[i] < nums[i + 1]) {
                    piv = i;
                    break;
                }
            }

            if (piv == -1) {
                // If no such element is found, reverse the entire array
                reverse(nums.begin(), nums.end());
            } else {
                // Step 2: Find the smallest element in the suffix greater than nums[piv]
                for (int i = n - 1; i > piv; i--) {
                    if (nums[i] > nums[piv]) {
                        swap(nums[i], nums[piv]);
                        break;
                    }
                }

                // Step 3: Reverse the part of the array after the pivot
                reverse(nums.begin() + piv + 1, nums.end());
            }
        }
};

int main()
{
    Solution solution;
    vector<int> nums = {2, 3, 7, 6, 5, 1};
    solution.nextPermutation(nums);
    for(int i=0; i<nums.size(); i++) {
        cout<<nums[i]<<" ";
    }
    return 0;
}

#include <vector>
#include <string>
#include <algorithm>

class Solution {
public:
    int minCost(string colors, vector<int>& neededTime) {
        // Initialize the total time to 0
        int totalTime = 0;
        // Initialize two pointers i and j
        int i = 0, j = 0;

        // Loop until either pointer reaches the end of the 'neededTime' array
        while (i < neededTime.size() && j < neededTime.size()) {
            // Initialize variables to calculate current total and maximum time
            int currTotal = 0, currMax = 0;

            // Find all the balloons having the same color as the balloon indexed at i
            while (j < neededTime.size() && colors[i] == colors[j]) {
                // Accumulate total removal time for the same color group
                currTotal += neededTime[j];
                // Track maximum removal time within the group
                currMax = max(currMax, neededTime[j]);
                // Move the pointer to the next balloon
                j++;
            }

            // Once the end of the current color group is reached, add the cost of this group to totalTime
            // Deduct the maximum removal time from the total removal time
            totalTime += currTotal - currMax;

            // Move the starting pointer to the next color group
            i = j;
        }

        // Return the calculated total time
        return totalTime;
    }
};

#include <iostream>
#include <asio.hpp>
#include <boost/bind.hpp>

// Callback function for timer
void print(const asio::error_code& /*e*/,
    asio::steady_timer* t, int* count)
{
  if (*count < 5)
  {
    std::cout << *count << std::endl;
    ++(*count);
    t->expires_at(t->expiry() + asio::chrono::seconds(1));
    t->async_wait(boost::bind(print,
          asio::placeholders::error, t, count));
  }
}

int main()
{
  asio::io_context io;
  int count = 0;
  asio::steady_timer t(io, asio::chrono::seconds(1));
  t.async_wait(boost::bind(print,
        asio::placeholders::error, &t, &count));
  io.run();
  // Print final count
  std::cout << "Final count is " << count << std::endl;
  return 0;

}

#include <pangolin/pangolin.h>
#include <pangolin/log/packetstream_reader.h>
#include <pangolin/log/packetstream_writer.h>
#include <pangolin/video/video.h>

int main( int argc, char* argv[] )
{
    if( argc == 3) {
        const std::string filein = std::string(argv[1]);
        const std::string fileout = std::string(argv[2]);

        // Verify input and output files are different
        PANGO_ASSERT(filein != fileout);

        pangolin::PacketStreamReader reader(filein);
        pangolin::PacketStreamWriter writer(fileout);

        // Read new JSON from command line
        picojson::value all_properties;
        std::cout << "Reading JSON from input" << std::endl;
        std::cin >> all_properties;
        std::cout << "+ done" << std::endl;

        PANGO_ASSERT(all_properties.size() == reader.Sources().size());

        for(size_t i=0; i < reader.Sources().size(); ++i) {
            const picojson::value& src_json = all_properties[i];
            pangolin::PacketStreamSource src = reader.Sources()[i];

            PANGO_ASSERT(src_json.contains("frame_properties"));
            PANGO_ASSERT(src_json.contains("device_properties"));
            PANGO_ASSERT(src_json["frame_properties"].size() == src.index.size());

            // Ensure the index gets rewritten, and update the device properties.
            src.index.clear();
            src.info["device"] = src_json["device_properties"];
            writer.AddSource(src);
        }

        std::cout << "Writing video with new JSON to '" << fileout << "'" << std::endl;

        try{
            std::vector<char> buffer;
            while(true)
            {
                pangolin::Packet pkt = reader.NextFrame();
                buffer.resize(pkt.BytesRemaining());
                pkt.Stream().read(buffer.data(), buffer.size());

                const picojson::value& new_frame_json = all_properties[pkt.src]["frame_properties"][pkt.sequence_num];
                writer.WriteSourcePacket(pkt.src, buffer.data(), pkt.time, buffer.size(), new_frame_json);

                std::cout << "Frames complete: " << pkt.sequence_num << " / " << reader.Sources()[pkt.src].index.size() << '\r';
                std::cout.flush();
            }
        }catch(const std::runtime_error &e)
        {
            std::cout << "Runtime error: " << e.what() << std::endl;
            throw e;
        }

        std::cout << std::endl << "+ done" << std::endl;

    }else{
        std::cout << "Usage: \n\tPangolinVideoTransform file_in.pango file_out.pango" << std::endl;
    }
}

#ifndef __Pyx_CppExn2PyErr

#include <new>
#include <typeinfo>
#include <stdexcept>
#include <ios>

// Converts C++ exceptions to Python errors
static void __Pyx_CppExn2PyErr()
{
    // Catch a handful of different errors here and turn them into the
    // equivalent Python errors.
    try {
        if (PyErr_Occurred())
            ; // let the latest Python exn pass through and ignore the current one
        else
            throw;
    } catch (const std::bad_alloc& exn) {
        PyErr_SetString(PyExc_MemoryError, exn.what());
    } catch (const std::bad_cast& exn) {
        PyErr_SetString(PyExc_TypeError, exn.what());
    } catch (const std::bad_typeid& exn) {
        PyErr_SetString(PyExc_TypeError, exn.what());
    } catch (const std::domain_error& exn) {
        PyErr_SetString(PyExc_ValueError, exn.what());
    } catch (const std::invalid_argument& exn) {
        PyErr_SetString(PyExc_ValueError, exn.what());
    } catch (const std::ios_base::failure& exn) {
        // Unfortunately, in standard C++ we have no way of distinguishing EOF
        // from other errors here; be careful with the exception mask
        PyErr_SetString(PyExc_IOError, exn.what());
    } catch (const std::out_of_range& exn) {
        // Change out_of_range to IndexError
        PyErr_SetString(PyExc_IndexError, exn.what());
    } catch (const std::overflow_error& exn) {
        PyErr_SetString(PyExc_OverflowError, exn.what());
    } catch (const std::range_error& exn) {
        PyErr_SetString(PyExc_ArithmeticError, exn.what());
    } catch (const std::underflow_error& exn) {
        PyErr_SetString(PyExc_ArithmeticError, exn.what());
    } catch (const std::exception& exn) {
        PyErr_SetString(PyExc_RuntimeError, exn.what());
    }
    catch (...)
    {
        PyErr_SetString(PyExc_RuntimeError, "Unknown exception");
    }
}

#endif

