#include <vector>
#include <unordered_map>

// Solution class to find the center of a star graph
class Solution {
public:
    int findCenter(std::vector<std::vector<int>>& edges) {
        int m = edges.size();
        int n = edges[0].size();
        std::unordered_map<int, int> mp;

        // Count occurrences of each node in the adjacency list
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                int currEl = edges[i][j];
                mp[currEl]++;
            }
        }

        // Find the node that appears more than once (the center)
        for (auto it : mp) {
            if (it.second > 1) {
                return it.first;
            }
        }

        return 1;
    }
};

