// Solves a single test case
void solve()
{
    int n;
    std::cin >> n;

    // Initialize list of candidate pens
    std::list<int> candidates;
    for (int i = 0; i < n; ++i)
    {
        candidates.push_back(i);
    }

    // Eliminate candidates until at most 2 remain
    while (candidates.size() > 2)
    {
        std::list<int> next_candidates;

        // Query each remaining candidate
        for (int pen_idx : candidates)
        {
            std::cout << "0 " << pen_idx << std::endl;
            int response;
            std::cin >> response;

            if (response == 1)
            {
                next_candidates.push_back(pen_idx);
            }
        }

        // Update candidates for next round
        candidates = next_candidates;

        // Check if we've reduced to acceptable number
        if (candidates.size() <= 2)
        {
            break;
        }
    }

    // Handle edge cases where fewer than 2 candidates remain
    if (candidates.size() < 2)
    {
        if (candidates.empty())
        {
            std::cout << "1 0 1" << std::endl;
        }
        else
        {
            int p1 = candidates.front();
            int p2 = (p1 + 1) % n;
            std::cout << "1 " << p1 << " " << p2 << std::endl;
        }
        return;
    }

    // Output the final two candidates
    int pen1 = candidates.front();
    candidates.pop_front();
    int pen2 = candidates.front();
    std::cout << "1 " << pen1 << " " << pen2 << std::endl;
}

// Main function
int main()
{
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(NULL);

    int t;
    std::cin >> t;

    while (t--)
    {
        solve();
    }

    return 0;
}

