#include <vector>
#include <cmath>

// Solution class to find the first missing positive integer
class Solution {
public:
    int firstMissingPositive(std::vector<int>& nums) {
        int n = nums.size();

        // Mark non-positive and out-of-range numbers
        for(int i = 0; i < n; i++) {
            if(nums[i] <= 0 || nums[i] > n + 1) {
                nums[i] = n + 1;
            }
        }

        // Mark indices corresponding to present numbers
        for(int i = 0; i < n; i++) {
            int index = std::abs(nums[i]);
            if(index >= 1 && index <= n) {
                nums[index - 1] = -std::abs(nums[index - 1]);
            }
        }

        // Find first positive index (missing number)
        for(int i = 0; i < n; i++) {
            if(nums[i] > 0) {
                return i + 1;
            }
        }

        // If all positions are marked, return n+1
        return n + 1;
    }
};

