using namespace std;

// Solves the word discovery problem using exponential search per starting character
void solve()
{
    int N;
    if (!(cin >> N)) return;

    // Set to store unique words found so far (automatically sorted)
    set<string> found_words;

    // Iterate through each letter from 'a' to 'z'
    for (char c = 'a'; c <= 'z'; ++c)
    {
        // Early termination if we've already found all N words
        if (found_words.size() == N) break;

        string s(1, c);
        int local_found = 0;   // Words starting with current char found so far
        int limit = 1;         // Current query size target

        while (found_words.size() < N)
        {
            // Double limit if it's not greater than what we've already found
            if (limit <= local_found)
            {
                limit *= 2;
                continue;
            }

            // Calculate remaining possible words starting with current character
            int other_found = found_words.size() - local_found;
            int remaining_possible_local = N - other_found;

            // Determine actual K to query: min of limit and theoretical maximum
            int K = min(limit, remaining_possible_local);

            // Ensure K is strictly greater than what we've already found
            if (K <= local_found)
            {
                limit *= 2;
                continue;
            }

            // Perform the query
            cout << "query " << s << " " << K << endl;
            int k;
            cin >> k;

            // Read k words and insert into our set
            for (int i = 0; i < k; ++i)
            {
                string w;
                cin >> w;
                found_words.insert(w);
            }

            local_found = k;

            // If service returned fewer words than requested, no more words start with this character
            if (k < K) break;

            // Check global termination condition
            if (found_words.size() == N) break;

            // Otherwise, double the limit for next iteration
            limit *= 2;
        }
    }

    // Output the answer
    cout << "answer";
    for (const auto& w : found_words)
    {
        cout << " " << w;
    }
    cout << endl;
}

int main()
{
    // Handle multiple test cases
    int T;
    if (cin >> T)
    {
        while (T--)
        {
            solve();
        }
    }
    return 0;
}

#include <iostream>
#include <vector>
#include <string>
#include <cmath>

// A vector to store the sequence of moves.
std::vector<std::pair<int, int>> moves;

/**
 * @brief Recursive function to solve the ball-moving puzzle using a Tower of Hanoi approach.
 * 
 * @param n The number of balls to move.
 * @param from_basket The source basket.
 * @param to_basket The destination basket.
 * @param aux_basket The auxiliary basket.
 */
void solve(int n, int from_basket, int to_basket, int aux_basket)
{
    if(n == 0)
    {
        return;
    }
    // Move n-1 balls from the source to the auxiliary basket, using the destination as temporary.
    solve(n - 1, from_basket, aux_basket, to_basket);

    // Record the move of the n-th ball from the source to the destination.
    moves.push_back({from_basket, to_basket});

    // Move the n-1 balls from the auxiliary basket to the destination, using the source as temporary.
    solve(n - 1, aux_basket, to_basket, from_basket);
}

int main()
{
    // Optimize standard I/O for faster execution.
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(NULL);

    int n;
    std::cin >> n;

    // The initial call to solve the problem for N balls from basket 1 to 3, using 2 as auxiliary.
    solve(n, 1, 3, 2);

    // Output the total number of moves.
    std::cout << moves.size() << "\n";

    // Output each move in the sequence.
    for(const auto& move : moves)
    {
        std::cout << move.first << " " << move.second << "\n";
    }

    return 0;
}

