struct NullColumnFunc {
    // Reads bit-packed null flags from the frame into the result vector
    static void readValuesFromPageToVector(
        const uint8_t* frame,
        PageCursor& pageCursor,
        ValueVector* resultVector,
        uint32_t posInVector,
        uint32_t numValuesToRead,
        const CompressionMetadata& metadata) {

        if (metadata.isConstant()) {
            bool value = false;
            ConstantCompression::decompressValues(
                reinterpret_cast<uint8_t*>(&value),
                0 /*offset*/,
                1 /*numValues*/,
                PhysicalTypeID::BOOL,
                1 /*numBytesPerValue*/,
                metadata);
            resultVector->setNullRange(posInVector, numValuesToRead, value);
        } else {
            resultVector->setNullFromBits(
                reinterpret_cast<const uint64_t*>(frame),
                pageCursor.elemPosInPage,
                posInVector,
                numValuesToRead);
        }
    }
};

