// Creates a new subdirectory under the selected item
void InstallDialog::createDirectoryUnder(ArchiveTreeWidgetItem* item)
{
  // Should never happen if we customize the context menu depending
  // on the item:
  if (!item->entry()->isDir()) {
    reportError(tr("Cannot create directory under a file."));
    return;
  }

  // Retrieve the directory:
  auto fileTree = item->entry()->astree();
  bool ok       = false;
  QString result =
      QInputDialog::getText(this, tr("Enter a directory name"), tr("Name"),
                            QLineEdit::Normal, QString(), &ok);
  result = result.trimmed();

  if (ok && !result.isEmpty()) {
    // If a file with this name already exists:
    if (fileTree->exists(result)) {
      reportError(tr("A directory or file with that name already exists."));
      return;
    }

    item->setExpanded(true);
    auto* newItem = m_Tree->addDirectory(item, result);
    m_Tree->scrollToItem(newItem);
  }
}

// Handles custom context menu requests on the tree widget
void InstallDialog::on_treeContent_customContextMenuRequested(QPoint pos)
{
  ArchiveTreeWidgetItem* selectedItem =
      static_cast<ArchiveTreeWidgetItem*>(m_Tree->itemAt(pos));

  if (selectedItem == nullptr) {
    return;
  }

  QMenu menu;

  if (selectedItem != m_Tree->root() && selectedItem->entry()->isDir()) {
    menu.addAction(tr("Set as <%1> directory").arg(m_DataFolderName),
                   [this, selectedItem]() {
                     m_Tree->setDataRoot(selectedItem);
                   });
  }

  if (m_Tree->root()->entry() != m_TreeRoot->entry()) {
    menu.addAction(tr("Unset <%1> directory").arg(m_DataFolderName), [this]() {
      m_Tree->setDataRoot(m_TreeRoot);
    });
  }

  // Add a separator if not empty:
  if (!menu.isEmpty()) {
    menu.addSeparator();
  }

  if (selectedItem->entry()->isDir()) {
    menu.addAction(tr("Create directory..."), [this, selectedItem]() {
      createDirectoryUnder(selectedItem);
    });
  } else {
    menu.addAction(tr("&Open"), [this, selectedItem]() {
      emit openFile(selectedItem->entry().get());
    });
  }

  menu.exec(m_Tree->mapToGlobal(pos));
}

// Called when OK button is clicked
void InstallDialog::on_okButton_clicked()
{
  if (!testForProblem()) {
    if (QMessageBox::question(
            this, tr("Continue?"),
            tr("This mod was probably NOT set up correctly, most likely it will NOT "
               "work. "
               "You should first correct the directory layout using the content-tree."),
            QMessageBox::Ignore | QMessageBox::Cancel,
            QMessageBox::Cancel) == QMessageBox::Cancel) {
      return;
    }
  }

  this->accept();
}

// Called when Cancel button is clicked
void InstallDialog::on_cancelButton_clicked()
{
  this->reject();
}

#include <iostream>
#include <vector>
#include <numeric>
#include <algorithm>
#include <cmath>

std::vector<int> baskets[4];
std::vector<std::pair<int, int>> moves;

// Perform a move from one basket to another
void perform_move(int from, int to) {
    // Determine the center ball based on the rules.
    // In a sorted list of k balls (1-indexed), the position is (k+2)/2.
    int k = baskets[from].size();
    int center_1_based_idx = (k + 2) / 2;
    int ball_to_move = baskets[from][center_1_based_idx - 1];

    // Find and remove the ball from the 'from' basket.
    auto it = std::lower_bound(baskets[from].begin(), baskets[from].end(), ball_to_move);
    baskets[from].erase(it);

    // Add the ball to the 'to' basket and re-sort to maintain order.
    baskets[to].push_back(ball_to_move);
    std::sort(baskets[to].begin(), baskets[to].end());

    // Record the move.
    moves.push_back({from, to});
}

// Recursive Tower of Hanoi implementation
void hanoi(int n, int from, int to, int via) {
    if (n == 0) {
        return;
    }

    // The core Tower of Hanoi recursion.
    hanoi(n - 1, from, via, to);
    perform_move(from, to);
    hanoi(n - 1, via, to, from);
}

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(NULL);

    int N;
    std::cin >> N;

    // Initially, all N balls are in basket 1.
    baskets[1].resize(N);
    std::iota(baskets[1].begin(), baskets[1].end(), 1);

    // Start the process to move N balls from basket 1 to 3, using 2 as auxiliary.
    hanoi(N, 1, 3, 2);

    std::cout << moves.size() << "\n";
    for (const auto& move : moves) {
        std::cout << move.first << " " << move.second << "\n";
    }

    return 0;
}

#include "sax.h"

using namespace NConfig;

namespace {
    // SAX implementation for configuration traversal
    class TSax: public IConfig, public IConfig::IValue {
    public:
        inline TSax(const TConfig& cfg)
            : C_(cfg)
        {
        }

        void DoForEach(IFunc* func) override {
            if (C_.IsA<TArray>()) {
                const TArray& a = C_.Get<TArray>();
                for (size_t i = 0; i < a.size(); ++i) {
                    TSax slave(a[i]);
                    func->Consume(ToString(i), &slave);
                }
            } else if (C_.IsA<TDict>()) {
                const TDict& d = C_.Get<TDict>();
                for (const auto& it : d) {
                    TSax slave(it.second);
                    func->Consume(it.first, &slave);
                }
            }
        }

        TString AsString() override {
            if (C_.IsA<TArray>()) {
                TSax slave(C_.Get<TArray>()[0]);
                return slave.AsString();
            }
            return C_.As<TString>();
        }

        bool AsBool() override {
            return C_.As<bool>();
        }

        IConfig* AsSubConfig() override {
            return this;
        }

        bool IsContainer() const override {
            return C_.IsA<TArray>() || C_.IsA<TDict>();
        }

        void DumpJson(IOutputStream& stream) const override {
            C_.DumpJson(stream);
        }

        void DumpLua(IOutputStream& stream) const override {
            C_.DumpLua(stream);
        }

    private:
        TConfig C_;
    };
}

namespace NConfig {
    // Parser function that creates a TSax wrapper around parsed config
    THolder<IConfig> ConfigParser(IInputStream& in, const TGlobals& globals) {
        return MakeHolder<TSax>(TConfig::FromStream(in, globals));
    }
}

