// Class to represent distance in feet and inches
class dist {
private:
    int feet, inches;
public:
    void read();
    void show();
    dist add(dist d);
};

// Function to read distance from user
void dist::read()
{
    cout << "enter feet and inches";
    cin >> feet >> inches;
}

// Function to display the distance
void dist::show() {
    cout << feet << "feet" << inches << "inches" << endl;
}

// Function to add two distance objects
dist dist::add(dist d)
{
    dist t;
    t.feet = feet + d.feet;
    t.inches = inches + d.inches;
    if (t.inches >= 12) {
        t.feet = t.feet + t.inches / 12;
        t.inches = t.inches % 12;
    }
    return (t);
}

// Main function
int main()
{
    dist e1, e2, e3;
    e1.read(); e2.read();
    e1.show(); e2.show();
    e3 = e1.add(e2);
    e3.show();
    return 0;
}

