using namespace std;

// Main function to demonstrate vector operations
int main()
{
    // Initialize a vector with integers
    vector<int> v = {1, 2, 3, 4, 5};

    cout << "Original vector: ";
    // Iterate over the vector and print each element
    for(int i: v)
    {
        cout << i << " ";
    }
    cout << endl; // Print newline

    // Reverse the entire vector in place
    reverse(v.begin(), v.end());

    cout << "Reversed vector: ";
    // Iterate over the reversed vector and print elements
    for(int i: v)
    {
        cout << i << " ";
    }
    cout << endl; // Print newline

    // Create another vector for partial reversal demonstration
    vector<int> v1 = {1, 2, 3, 4, 5};

    // Reverse only the first 3 elements
    reverse(v1.begin(), v1.begin() + 3);

    cout << "Partially reversed vector: ";
    // Iterate over the partially reversed vector and print elements
    for(int i: v1)
    {
        cout << i << " ";
    }
    cout << endl; // Print newline

    return 0;
}

