// Fallback function for variadic arguments
sol::variadic_results fallback(
     sol::this_state ts, sol::variadic_args args) {
    sol::variadic_results r;
    // Check if exactly two arguments are provided
    if (args.size() == 2) {
        r.push_back({ ts,
             sol::in_place,
             args.get<int>(0) + args.get<int>(1) });
    }
    // Otherwise return default value 52
    else {
        r.push_back({ ts, sol::in_place, 52 });
    }
    return r;
}

// Main function demonstrating overload resolution with fallback
int main(int, char*[]) {
    std::cout << "=== overloading with fallback ==="
              << std::endl;

    sol::state lua;
    lua.open_libraries();

    // Register overloaded functions including fallback
    lua.set_function(
         "f", sol::overload(func_1, func_2, fallback));

    // Test different argument types to trigger different overloads
    lua.script("print(f(1))");      // Calls func_1
    lua.script("print(f('hi'))");   // Calls func_2
    lua.script("print(f(22, 11))"); // Calls fallback with sum
    lua.script("print(f({}))");     // Calls fallback with default

    return 0;
}

