    // remain throughout
    std::list<Text> argumentList;
    std::istringstream iss(TestArgs.val());
    Text arg;
    while (iss >> arg)
    {
        argumentList.push_front(arg);
        arguments.push_back(argumentList.front());
    }
    // Run the tests
    auto res = TestMain(arguments);
    LOG(Test, "Test returning code", res);
    engine::deinit();
    return res;
}

