#include <vector>
#include <climits>
#include <algorithm>

class Solution {
public:
    // Check if the range [left, right] is reachable within k steps from startPos
    bool isValid(int left, int right, int startPos, int k) {
        if (right <= startPos) {
            return startPos - left <= k;
        } else if (left >= startPos) {
            return right - startPos <= k;
        } else {
            int x = startPos - left;
            int y = right - startPos;
            return (2 * x + y) <= k || (2 * y + x) <= k;
        }
    }

    int maxTotalFruits(std::vector<std::vector<int>>& fruits, int startPos, int k) {
        int n = fruits.size();
        int ans = INT_MIN;
        int sum = 0;
        int left = 0;

        for (int right = 0; right < n; right++) {
            sum += fruits[right][1];
            while (left <= right && !isValid(fruits[left][0], fruits[right][0], startPos, k)) {
                sum -= fruits[left++][1];
            }
            ans = std::max(ans, sum);
        }

        return ans;
    }
};

#include <iostream>
#include <vector>
#include <string>
#include <numeric>
#include <algorithm>
#include <set>

// Main solving function
void solve()
{
    int n;
    std::cin >> n;

    // Handle special case when n is zero
    if (n == 0)
    {
        std::cout << "answer" << std::endl;
        std::cout.flush();
        return;
    }

    // Vector to store initial prefixes
    std::vector<std::string> initial_prefixes;
    // Set to track found words
    std::set<std::string> found_words;

    // Check all single-letter prefixes from 'a' to 'z'
    for (char c = 'a'; c <= 'z'; ++c)
    {
        std::string prefix(1, c);
        std::cout << "query " << prefix << " " << 1 << std::endl;
        std::cout.flush();

        int k;
        std::cin >> k;

        if (k > 0)
        {
            initial_prefixes.push_back(prefix);
            std::string word;
            std::cin >> word;
            found_words.insert(word);
        }
    }

    // Sort prefixes in reverse alphabetical order as heuristic
    std::sort(initial_prefixes.rbegin(), initial_prefixes.rend());
    int n_rem = n;

    // Process each prefix
    for (size_t i = 0; i < initial_prefixes.size(); ++i)
    {
        const std::string& prefix = initial_prefixes[i];

        // Count how many known words start with this prefix
        int known_for_prefix = 0;
        for (const auto& word : found_words)
        {
            if (word.rfind(prefix, 0) == 0)
            {
                known_for_prefix++;
            }
        }

        // Calculate query parameter
        int query_k = n - (found_words.size() - known_for_prefix);

        // Adjust for last prefix
        if (i == initial_prefixes.size() - 1)
        {
            query_k = n - found_words.size() + known_for_prefix;
        }

        // Skip if no need to query
        if (query_k <= 0) continue;

        std::cout << "query " << prefix << " " << query_k << std::endl;
        std::cout.flush();

        int k;
        std::cin >> k;

        // Read and store new words
        for (int j = 0; j < k; ++j)
        {
            std::string word;
            std::cin >> word;
            found_words.insert(word);
        }
    }

    // Output final answer
    std::cout << "answer";
    for (const auto& word : found_words)
    {
        std::cout << " " << word;
    }
    std::cout << std::endl;
    std::cout.flush();
}

// Main function
int main()
{
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(NULL);

    int t;
    std::cin >> t;

    while (t--)
    {
        solve();
    }

    return 0;
}

