#include "Abilities/Tasks/AbilityTask_NetworkSyncPoint.h"
#include "AbilitySystemComponent.h"

UAbilityTask_NetworkSyncPoint::UAbilityTask_NetworkSyncPoint(const FObjectInitializer& ObjectInitializer)
	: Super(ObjectInitializer)
{
	ReplicatedEventToListenFor = EAbilityGenericReplicatedEvent::MAX;
}

// Callback when network sync signal is received
void UAbilityTask_NetworkSyncPoint::OnSignalCallback()
{
	if (AbilitySystemComponent)
	{
		AbilitySystemComponent->ConsumeGenericReplicatedEvent(ReplicatedEventToListenFor, GetAbilitySpecHandle(), GetActivationPredictionKey());
	}
	SyncFinished();
}

// Factory method to create a wait net sync task
UAbilityTask_NetworkSyncPoint* UAbilityTask_NetworkSyncPoint::WaitNetSync(class UGameplayAbility* OwningAbility, EAbilityTaskNetSyncType InSyncType)
{
	UAbilityTask_NetworkSyncPoint* MyObj = NewAbilityTask<UAbilityTask_NetworkSyncPoint>(OwningAbility);
	MyObj->SyncType = InSyncType;
	return MyObj;
}

// Main activation logic for the network sync task
void UAbilityTask_NetworkSyncPoint::Activate()
{
	FScopedPredictionWindow ScopedPrediction(AbilitySystemComponent, IsPredictingClient());

	if (AbilitySystemComponent)
	{
		if (IsPredictingClient())
		{
			// Client-side waiting logic
			if (SyncType != EAbilityTaskNetSyncType::OnlyServerWait)
			{
				// Listen for server signal if not exclusively server-wait mode
				ReplicatedEventToListenFor = EAbilityGenericReplicatedEvent::GenericSignalFromServer;
			}

			if (SyncType != EAbilityTaskNetSyncType::OnlyClientWait)
			{
				// Notify server of client signal if not exclusively client-wait mode
				AbilitySystemComponent->ServerSetReplicatedEvent(
					EAbilityGenericReplicatedEvent::GenericSignalFromClient,
					GetAbilitySpecHandle(),
					GetActivationPredictionKey(),
					AbilitySystemComponent->ScopedPredictionKey
				);
			}
		}
		else if (IsForRemoteClient())
		{
			// Server-side waiting logic for remote client
			if (SyncType != EAbilityTaskNetSyncType::OnlyClientWait)
			{
				// Listen for client signal if not exclusively client-wait mode
				ReplicatedEventToListenFor = EAbilityGenericReplicatedEvent::GenericSignalFromClient;
			}

			if (SyncType != EAbilityTaskNetSyncType::OnlyServerWait)
			{
				// Notify client of server signal if not exclusively server-wait mode
				AbilitySystemComponent->ClientSetReplicatedEvent(
					EAbilityGenericReplicatedEvent::GenericSignalFromServer,
					GetAbilitySpecHandle(),
					GetActivationPredictionKey()
				);
			}
		}

		// Register delegate if we're waiting for a replicated event
		if (ReplicatedEventToListenFor != EAbilityGenericReplicatedEvent::MAX)
		{
			CallOrAddReplicatedDelegate(
				ReplicatedEventToListenFor,
				FSimpleMulticastDelegate::FDelegate::CreateUObject(this, &UAbilityTask_NetworkSyncPoint::OnSignalCallback)
			);
		}
		else
		{
			// No replication needed — sync complete immediately
			SyncFinished();
		}
	}
}

// Finalize and broadcast completion of sync
void UAbilityTask_NetworkSyncPoint::SyncFinished()
{
	if (!IsPendingKill())
	{
		if (ShouldBroadcastAbilityTaskDelegates())
		{
			OnSync.Broadcast();
		}
		EndTask();
	}
}

#include "test/jemalloc_test.h"

/*
 * GCC "-Walloc-size-larger-than" warning detects when one of the memory
 * allocation functions is called with a size larger than the maximum size that
 * they support. Here we want to explicitly test that the allocation functions
 * do indeed fail properly when this is the case, which triggers the warning.
 * Therefore we disable the warning for these tests.
 */
JEMALLOC_DIAGNOSTIC_PUSH
JEMALLOC_DIAGNOSTIC_IGNORE_ALLOC_SIZE_LARGER_THAN

TEST_BEGIN(test_overflow)
{
    unsigned nlextents;
    size_t mib[4];
    size_t sz, miblen, max_size_class;
    void *p;

    sz = sizeof(unsigned);
    expect_d_eq(mallctl("arenas.nlextents", (void *)&nlextents, &sz, NULL, 0), 0,
        "Unexpected mallctl() error");

    miblen = sizeof(mib) / sizeof(size_t);
    expect_d_eq(mallctlnametomib("arenas.lextent.0.size", mib, &miblen), 0,
        "Unexpected mallctlnametomib() error");

    mib[2] = nlextents - 1;
    sz = sizeof(size_t);
    expect_d_eq(mallctlbymib(mib, miblen, (void *)&max_size_class, &sz, NULL, 0), 0,
        "Unexpected mallctlbymib() error");

    // Test malloc with oversized sizes
    expect_ptr_null(malloc(max_size_class + 1),
        "Expected OOM due to over-sized allocation request");
    expect_ptr_null(malloc(SIZE_T_MAX),
        "Expected OOM due to over-sized allocation request");

    // Test calloc with oversized sizes
    expect_ptr_null(calloc(1, max_size_class + 1),
        "Expected OOM due to over-sized allocation request");
    expect_ptr_null(calloc(1, SIZE_T_MAX),
        "Expected OOM due to over-sized allocation request");

    // Test realloc with oversized sizes
    p = malloc(1);
    expect_ptr_not_null(p, "Unexpected malloc() OOM");
    expect_ptr_null(realloc(p, max_size_class + 1),
        "Expected OOM due to over-sized allocation request");
    expect_ptr_null(realloc(p, SIZE_T_MAX),
        "Expected OOM due to over-sized allocation request");

    free(p);
}
TEST_END

/* Re-enable the "-Walloc-size-larger-than=" warning */
JEMALLOC_DIAGNOSTIC_POP

int
main(void)
{
    return test(
        test_overflow);
}

