// MessageBus constructor
MessageBus::MessageBus()
{
    // Constructor - messages map is automatically initialized
}

// Send a message to the bus
void MessageBus::send(Message *message)
{
    // Store the message, replacing any existing message with the same address
    messages[message->get_address()] = message;
}

// Read a message by address
Message *MessageBus::read(uint64_t address)
{
    // Find the message with the given address
    auto it = messages.find(address);
    if(it != messages.end())
    {
        return it->second;
    }
    // No message found for this address
    return nullptr;
}

#include "urdf_parser/urdf_parser.h"
#include <fstream>
#include <iostream>

// Main function to parse URDF file
int main(int argc, char** argv)
{
    // Check command line arguments
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <urdf>\n", argv[0]);
        return 1;
    }

    // Infinite loop to continuously parse the URDF file
    while (true)
    {
        std::string xml_string;
        std::fstream xml_file(argv[1], std::fstream::in);

        // Read file content line by line
        while (xml_file.good())
        {
            std::string line;
            std::getline(xml_file, line);
            xml_string += (line + "\n");
        }

        xml_file.close();

        // Parse the URDF string
        urdf::parseURDF(xml_string);
    }

    return 0;
}

#include <iostream>
using namespace std;

/*
 Definition for singly-linked list.
*/
struct ListNode {
     int val;
     ListNode *next;
     ListNode() : val(0), next(nullptr) {}
     ListNode(int x) : val(x), next(nullptr) {}
     ListNode(int x, ListNode *next) : val(x), next(next) {}
 };

class Solution {
public:
    // Swap adjacent nodes in pairs
    ListNode* swapPairs(ListNode* head) {
        // Base case: If the list is empty or has only one node, no swap needed.
        if (head == NULL || head->next == NULL) {
            return head;
        }

        // Initialize a dummy node to help with head swapping
        ListNode* dummy = new ListNode(0);
        dummy->next = head;

        ListNode* prev = dummy;  // Pointer to the node before the pair to be swapped
        ListNode* temp = head;   // Pointer to the current node

        while (temp != NULL && temp->next != NULL) {
            ListNode* n1 = temp;          // First node of the pair
            ListNode* n2 = temp->next;    // Second node of the pair

            // Swap the pair
            prev->next = n2;              // Connect previous node to the second node
            n1->next = n2->next;          // Connect first node to the next node after the pair
            n2->next = n1;                // Connect second node to the first node

            // Move pointers forward for the next pair
            prev = n1;                    // Move prev to the first node of the current pair
            temp = n1->next;              // Move temp to the next pair's first node
        }

        return dummy->next;  // Return the new head of the list
    }
};

