// Implementation of assertion failure handler
void assert_fail_impl()
{
    Common::Log::Stop();
    std::fflush(stdout);
    Crash();
}

// Marks code as unreachable and terminates execution
[[noreturn]] void unreachable_impl()
{
    Common::Log::Stop();
    std::fflush(stdout);
    Crash();
    throw std::runtime_error("Unreachable code");
}

// Logs assertion failure with additional message
void assert_fail_debug_msg(const char* msg)
{
    LOG_CRITICAL(Debug, "Assertion Failed!\n{}", msg);
    assert_fail_impl();
}

