using namespace db;

// Constructor for StopCmd
StopCmd::StopCmd()
    : _argParser("stop")
{
}

// Destructor
StopCmd::~StopCmd() = default;

// Main execution logic for stopping the TuringDB server
int StopCmd::execute()
{
    // Initialize console logging only (no file logging since this process doesn't own the lock)
    LogSetup::setupLogConsole();

    // Load configuration
    TuringConfig config;
    if (!_turingDir.empty()) {
        config.setTuringDirectory(fs::Path {_turingDir});
    }
    _turingDir = config.getTuringDir().get();

    // Check if socket exists
    const fs::Path socketPath = config.getSocketPath();
    if (!socketPath.exists()) {
        spdlog::error("No TuringDB instance seems to be running at {}", _turingDir);
        return EXIT_FAILURE;
    }

    // Request server shutdown via Unix socket
    if (!SystemEventHandler::requestStop(socketPath)) {
        spdlog::error("Could not stop the TuringDB instance at {}", _turingDir);
        return EXIT_FAILURE;
    }

    // Wait for lock file release
    LockFile lockFile;
    lockFile.setPath(config.getLockFilePath());
    if (!lockFile.waitUnlock(_timeout)) {
        spdlog::error("TuringDB at {} did not stop within {} ms", _turingDir, _timeout);
        return EXIT_FAILURE;
    }

    // Success message
    spdlog::info("Stopped TuringDB instance at {}", _turingDir);
    return EXIT_SUCCESS;
}

// Factory method to create a StopCmd instance
std::unique_ptr<StopCmd> StopCmd::create()
{
    std::unique_ptr<StopCmd> cmd {new StopCmd()};
    cmd->initialize();
    return cmd;
}

// Initialize command-line arguments
void StopCmd::initialize()
{
    _argParser.add_description("Stops the TuringDB server");
    _argParser.add_argument("-turing-dir")
        .metavar("path")
        .help("Root Turing directory")
        .store_into(_turingDir);
    _argParser.add_argument("-timeout", "-t")
        .metavar("ms")
        .help("Milliseconds to wait for the process to release its lock (default: 3000)")
        .store_into(_timeout);
}

#include <array>
#include <iostream>
#include <string>
#include "asio.hpp"

// Multicast port constant
constexpr short multicast_port = 30001;

// Receiver class for multicast UDP communication
class receiver
{
public:
  // Constructor initializes socket and joins multicast group
  receiver(asio::io_context& io_context,
      const asio::ip::address& listen_address,
      const asio::ip::address& multicast_address)
    : socket_(io_context)
  {
    // Create the socket so that multiple may be bound to the same address.
    asio::ip::udp::endpoint listen_endpoint(
        listen_address, multicast_port);
    socket_.open(listen_endpoint.protocol());
    socket_.set_option(asio::ip::udp::socket::reuse_address(true));
    socket_.bind(listen_endpoint);

    // Join the multicast group.
    socket_.set_option(
        asio::ip::multicast::join_group(multicast_address));

    do_receive();
  }

private:
  // Asynchronously receive data
  void do_receive()
  {
    socket_.async_receive_from(
        asio::buffer(data_), sender_endpoint_,
        [this](std::error_code ec, std::size_t length)
        {
          if (!ec)
          {
            std::cout.write(data_.data(), length);
            std::cout << std::endl;
            do_receive();
          }
        });
  }

  // Member variables
  asio::ip::udp::socket socket_;
  asio::ip::udp::endpoint sender_endpoint_;
  std::array<char, 1024> data_;
};

// Main function
int main(int argc, char* argv[])
{
  try
  {
    // Check command line arguments
    if (argc != 3)
    {
      std::cerr << "Usage: receiver <listen_address> <multicast_address>\n";
      std::cerr << "  For IPv4, try:\n";
      std::cerr << "    receiver 0.0.0.0 239.255.0.1\n";
      std::cerr << "  For IPv6, try:\n";
      std::cerr << "    receiver 0::0 ff31::8000:1234\n";
      return 1;
    }

    asio::io_context io_context;
    receiver r(io_context,
        asio::ip::make_address(argv[1]),
        asio::ip::make_address(argv[2]));

    io_context.run();
  }
  catch (std::exception& e)
  {
    std::cerr << "Exception: " << e.what() << "\n";
  }

  return 0;
}

