class Solution {
public:
    // Calculates the number of rescue boats needed
    int numRescueBoats(vector<int>& people, int limit) {
        int n = people.size();
        int boats = 0;
        int addOns = 0;

        // Sort the people by weight
        sort(people.begin(), people.end());

        // Use two-pointer approach
        for(int right = n - 1; right >= addOns; right--) {
            boats++;
            // If lightest person can share boat with heaviest
            if(people[right] + people[addOns] <= limit) {
                addOns++;
            }
        }

        return boats;
    }
};

