using namespace sdb::options;

Section::Section(const std::string& name, const std::string& description,
                 const std::string& link, const std::string& alias, bool hidden,
                 bool obsolete)
  : name(name),
    description(description),
    link(link),
    alias(alias),
    hidden(hidden),
    obsolete(obsolete) {}

Section::~Section() = default;

std::string Section::displayName() const {
  return alias.empty() ? name : alias;
}

// whether or not the section has (displayable) options
bool Section::hasOptions() const {
  if (!hidden) {
    for (const auto& it : options) {
      if (!it.second.hasFlag(sdb::options::Flags::Uncommon)) {
        return true;
      }
    }
  }
  return false;
}

// print help for a section
// the special search string "." will show help for all sections, even if hidden
void Section::printHelp(const std::string& search, size_t tw, size_t ow,
                        bool colors) const {
  if (search != "." && (hidden || !hasOptions())) {
    return;
  }

  std::cout << "Section '" 
            << (colors ? colors::kBright : "") 
            << displayName()
            << (colors ? colors::kReset : "") 
            << "' (configure " 
            << description 
            << ")";

  if (!link.empty()) {
    std::cout << " [";
    if (colors) {
      std::cout << colors::kLinkStart << link 
                << colors::kLinkMiddle << link 
                << colors::kLinkEnd;
    } else {
      std::cout << link;
    }
    std::cout << "]";
  }

  std::cout << std::endl;

  auto hl = headlines.begin();

  // propagate print command to options
  for (const auto& it : options) {
    if (hl != headlines.end() && it.first >= (*hl).first) {
      // must print a headline
      std::cout << " # " << (*hl).second << std::endl;
      ++hl;
    }

    if (it.second.hasFlag(sdb::options::Flags::Obsolete)) {
      // skip obsolete options
      continue;
    }

    // print help for option
    it.second.printHelp(search, tw, ow, colors);
  }

  std::cout << std::endl;
}

// determine display width for a section
size_t Section::optionsWidth() const {
  size_t width = 0;
  if (!hidden) {
    for (const auto& it : options) {
      width = std::max(width, it.second.optionsWidth());
    }
  }
  return width;
}

