int a[200005];

/**
 * Recursive function to solve for range [l, r].
 * Uses a divide and conquer approach similar to building a Segment Tree.
 * Queries the current range for mode and frequency.
 * If the range is "pure" (consists of only one value), fill it and return.
 * Otherwise, split into left and right sub-ranges.
 */
void solve(int l, int r)
{
    if (l > r) return;

    // Perform query: "? l r"
    cout << "? " << l << " " << r << endl;

    // Read response: "x f"
    long long x_long;
    int f;

    // Input validation for robustness
    if (!(cin >> x_long >> f)) {
        exit(0);
    }

    // -1 indicates invalid query or error
    if (x_long == -1) {
        exit(0);
    }

    int x = (int)x_long;

    // If frequency equals the length of the range, all elements in [l, r] are equal to x.
    if (f == (r - l + 1)) {
        for (int i = l; i <= r; ++i) {
            a[i] = x;
        }
        return;
    }

    // Divide step: split the range into halves
    int mid = (l + r) / 2;
    solve(l, mid);
    solve(mid + 1, r);
}

int main()
{
    // Optimize I/O operations.
    // Note: interactive checking requires output flushing. 'endl' forces flush.
    // Untying cin from cout is safe here.
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n;

    // Read N
    if (cin >> n) {
        // Start the recursive solving process from the full array
        solve(1, n);

        // Output the final answer
        cout << "! ";
        for (int i = 1; i <= n; ++i) {
            cout << a[i] << (i == n ? "" : " ");
        }
        cout << endl;
    }

    return 0;
}

#include <iostream>
#include <vector>
#include <string>
#include <numeric>

// Performs a query to determine the next state transitions
void do_query(int m, const std::vector<int>& a, const std::vector<int>& b)
{
    std::cout << 1 << std::endl;
    std::cout << m << std::endl;

    // Output vector a
    for(int i = 0; i < m; ++i)
    {
        std::cout << a[i] << (i == m - 1 ? "" : " ");
    }
    std::cout << std::endl;

    // Output vector b
    for(int i = 0; i < m; ++i)
    {
        std::cout << b[i] << (i == m - 1 ? "" : " ");
    }
    std::cout << std::endl;

    std::cout.flush();
}

int main()
{
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(NULL);

    int n;
    std::cin >> n;
    std::string s(n, '0');

    // Determine each character S_k of the secret string
    for(int k = 0; k < n; ++k)
    {
        // To determine S_k, we design an automaton where the state before processing S_k
        // is k, regardless of the previous bits S_0, ..., S_{k-1}.
        // We use m = k + 2 states, labeled 0 to k+1.
        // States 0, ..., k-1 form a forced path.
        // State k is the decision state.
        // States k and k+1 are sink states to hold the result.

        int m = k + 2;

        std::vector<int> a(m);
        std::vector<int> b(m);

        // For the first k characters (S_0 to S_{k-1}), the automaton
        // transitions from state i to i+1.
        // After S_{i-1} is processed, the state is i.
        for(int i = 0; i < k; ++i)
        {
            a[i] = i + 1;
            b[i] = i + 1;
        }

        // Before processing S_k, the state is k.
        // The transition from state k depends on S_k.
        a[k] = k;      // If S_k is '0', transition to state k.
        b[k] = k + 1;  // If S_k is '1', transition to state k+1.

        // States k and k+1 are sink states. Once entered, the automaton stays.
        if(k + 1 < m)
        {
            a[k+1] = k+1;
            b[k+1] = k+1;
        }

        do_query(m, a, b);

        int result;
        std::cin >> result;
        if(result == k)
        {
            s[k] = '0';
        }
        else
        {
            s[k] = '1';
        }
    }

    std::cout << 0 << std::endl;
    std::cout << s << std::endl;
    std::cout.flush();
    return 0;
}

