using namespace llvm;
using namespace llvm::sys;

// Constructor: Initialize LLVM subsystems
InitLLVM::InitLLVM(int &Argc, const char **&Argv,
                   bool InstallPipeSignalExitHandler)
{
#ifndef NDEBUG
  static std::atomic<bool> Initialized{false};
  assert(!Initialized && "InitLLVM was already initialized!");
  Initialized = true;
#endif

#ifdef __MVS__
  // Ensure stdin/stdout/stderr are in a known state
  sys::AddSignalHandler(CleanupStdHandles, nullptr);
#endif

  if (InstallPipeSignalExitHandler)
    // Install pipe signal handler first to allow proper SIGPIPE handling on Unix
    sys::SetOneShotPipeSignalFunction(sys::DefaultOneShotPipeSignalHandler);

  // Initialize stack printer after installing the one-shot pipe signal handler
  StackPrinter.emplace(Argc, Argv);
  sys::PrintStackTraceOnErrorSignal(Argv[0]);
  install_out_of_memory_new_handler();

#ifdef __MVS__
  // Use UTF-8 internally; convert external output to EBCDIC for z/OS
  std::string Banner = std::string(Argv[0]) + ": ";
  ExitOnError ExitOnErr(Banner);

  // Enable auto-conversion for stderr and stdout (stderr first for error messages)
  ExitOnErr(errorCodeToError(llvm::enableAutoConversion(STDERR_FILENO)));
  ExitOnErr(errorCodeToError(llvm::enableAutoConversion(STDOUT_FILENO)));
#endif

#ifdef _WIN32
  // Handle Windows command line argument encoding conversion to UTF-8
  std::string Banner = std::string(Argv[0]) + ": ";
  ExitOnError ExitOnErr(Banner);

  ExitOnErr(errorCodeToError(windows::GetCommandLineArguments(Args, Alloc)));

  // Null-terminate Args vector to mimic real argv behavior
  Args.push_back(nullptr);
  Argc = Args.size() - 1;
  Argv = Args.data();
#endif
}

// Destructor: Clean up LLVM resources
InitLLVM::~InitLLVM()
{
#ifdef __MVS__
  CleanupStdHandles(nullptr);
#endif
  llvm_shutdown();
}

