int main()
{
    // Set up a mplot::Visual 'scene environment'.
    mplot::Visual v(1280, 575, "Made with mplot::GraphVisual");

    // Create a GraphVisual object (obtaining a unique_ptr to the object) with a spatial offset within the scene of 0,0,0
    auto gv = std::make_unique<mplot::GraphVisual<double>>(sm::vec<float>{0.0f, 0.0f, 0.0f});

    // This mandatory line of boilerplate code sets the parent pointer in GraphVisual and binds some functions
    v.bindmodel(gv);

    // Data for the x axis. A vvec is like std::vector, but with built-in maths methods
    sm::vvec<double> x;

    // This works like numpy's linspace() (the 3 args are "start", "end" and "num"):
    x.linspace(0, 10, 11);

    // Hand chosen numbers
    sm::vvec<double> y = {5, 8, 2, 9, 1, 2, 4, 5, 8, 3, 1};

    // Choose a line graph by creating a lines stylepolicy datasetstyle.
    mplot::DatasetStyle ds(mplot::stylepolicy::lines);
    ds.linecolour = mplot::colour::crimson;

    // For this graph, set manual y axis limits
    gv->setlimits_y(0, 10);

    // Now set the data
    gv->setdata(x, y, ds);

    // A second DatasetStyle is used to specify a colour and linewidth for a horizontal line at y=7.
    mplot::DatasetStyle ds_horz(mplot::stylepolicy::lines);
    ds_horz.linecolour = mplot::colour::grey68;
    ds_horz.linewidth = ds.linewidth * 0.6f;

#ifdef GRAPH_LINES_SIMPLE
    gv->add_y_crossing_lines(x, y, 7, ds);
#else
    // Find, and annotate with vertical lines, the locations where the graph crosses
    // y=7. The x values of the crossing points are returned.
    sm::vvec<double> xcross = gv->add_y_crossing_lines(x, y, 7, ds, ds_horz);

    // Use results in xcross to annotate the graph
    size_t n = xcross.size();
    std::stringstream ss;

    if (n > 0)
    {
        // Loop through the elements of xcross, formatting a string
        for (size_t i = 0; i < n; ++i)
        {
            ss << std::format("{}{}{:.2f}", ((i == 0 || i == n - 1) ? "" : ", "), (i == (n - 1) ? " and " : ""), xcross[i]);
        }
    }
    else
    {
        ss << "[no values]";
    }

    // Add a label at location {.05, .05, 0} with fontsize 0.03
    gv->addLabel(std::format("y=7 at x = {:s}", ss.str()), {0.05f, 0.05f, 0.0f}, mplot::TextFeatures(0.03f));
#endif

    // finalize() makes the GraphVisual compute the vertices of the OpenGL model
    gv->finalize();

    // Add the GraphVisual OpenGL model to the Visual scene, transferring ownership of the unique_ptr
    v.addVisualModel(gv);

    // Render the scene on the screen until user quits with 'Ctrl-q'
    v.keepOpen();

    // Because v owns the unique_ptr to the GraphVisual, its memory will be deallocated when v goes out of scope.
    return 0;

}

#include <iostream>
#include <vector>
#include <string>
#include <algorithm>
#include <cmath>

// Main function to generate the program
int main()
{
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(NULL);

    unsigned int k;
    std::cin >> k;

    if (k == 1)
    {
        std::cout << 1 << std::endl;
        std::cout << "HALT PUSH 1 GOTO 1" << std::endl;
        return 0;
    }

    unsigned int q = (k - 1) / 2;
    std::vector<int> bits;

    // Handle q=0 case explicitly (though k>=3 implies q>=1 in practice)
    if (q == 0)
    {
        // This case would be for k=1, which is handled above.
        // For q=0, m should be 0, but to have a bit representation,
        // we can consider it as a single 0 bit if needed.
        // However, the logic works for q > 0.
    }

    unsigned int temp_q = q;

    // Build the binary representation of q
    if (temp_q == 0)
    {
        // For k=3, q=1. For k=1, q=0.
        // let's just make sure bits is never empty for q>0
        if (q > 0)
        {
            while (temp_q > 0)
            {
                bits.push_back(temp_q % 2);
                temp_q /= 2;
            }
        }
    }
    else
    {
        while (temp_q > 0)
        {
            bits.push_back(temp_q % 2);
            temp_q /= 2;
        }
    }

    // Failsafe for very large numbers or edge cases
    if (bits.empty() && q > 0)
    {
        int num_bits = floor(log2(q)) + 1;
        temp_q = q;
        for(int i = 0; i < num_bits; ++i)
        {
            bits.push_back(temp_q % 2);
            temp_q /= 2;
        }
    }

    // Reverse to get MSB-first order
    std::reverse(bits.begin(), bits.end());

    // Ensure at least one bit exists when q > 0
    if (q > 0 && bits.empty())
    {
        bits.push_back(1);
    }

    int m = bits.size();
    if (q == 0) m = 0;
    int n = m + 3;

    std::cout << n << std::endl;

    // Instruction 1: Entry point, pushes the first token.
    std::cout << "POP 1 GOTO 2 PUSH 1 GOTO 2" << std::endl;

    // Instructions 2 to m+1: The chain for processing bits of q.
    for (int i = 0; i < m; ++i)
    {
        int instr_idx = i + 2;
        if (bits[i] == 1)
        {
            // For a '1' bit.
            std::cout << "HALT PUSH 1 GOTO " << instr_idx + 1 << std::endl;
        }
        else
        {
            // For a '0' bit.
            std::cout << "POP 1 GOTO " << m + 2 << " PUSH 2 GOTO " << instr_idx + 1 << std::endl;
        }
    }

    // Instruction m+2: The "return" mechanism.
    std::cout << "POP 1 GOTO 2 PUSH 2 GOTO " << m + 2 << std::endl;

    // Instruction m+3: The final halt point.
    std::cout << "HALT PUSH 99 GOTO " << m + 2 << std::endl;

    return 0;
}

#include "server.hpp"
#include <boost/bind.hpp>
#include <signal.h>

namespace http {
namespace server {

// Server constructor: initializes components and sets up signal handling and network listening
server::server(const std::string& address, const std::string& port,
    const std::string& doc_root)
  : io_context_(),
    signals_(io_context_),
    acceptor_(io_context_),
    connection_manager_(),
    new_connection_(),
    request_handler_(doc_root)
{
  // Register to handle the signals that indicate when the server should exit.
  // It is safe to register for the same signal multiple times in a program,
  // provided all registration for the specified signal is made through Asio.
  signals_.add(SIGINT);
  signals_.add(SIGTERM);
#if defined(SIGQUIT)
  signals_.add(SIGQUIT);
#endif // defined(SIGQUIT)

  // Set up async wait for stop signals
  signals_.async_wait(boost::bind(&server::handle_stop, this));

  // Open the acceptor with the option to reuse the address (i.e. SO_REUSEADDR).
  asio::ip::tcp::resolver resolver(io_context_);
  asio::ip::tcp::endpoint endpoint =
    *resolver.resolve(address, port).begin();

  acceptor_.open(endpoint.protocol());
  acceptor_.set_option(asio::ip::tcp::acceptor::reuse_address(true));
  acceptor_.bind(endpoint);
  acceptor_.listen();

  start_accept();
}

// Run the server's event loop
void server::run()
{
  // The io_context::run() call will block until all asynchronous operations
  // have finished. While the server is running, there is always at least one
  // asynchronous operation outstanding: the asynchronous accept call waiting
  // for new incoming connections.
  io_context_.run();
}

// Start an asynchronous accept operation
void server::start_accept()
{
  new_connection_.reset(new connection(io_context_,
        connection_manager_, request_handler_));
  acceptor_.async_accept(new_connection_->socket(),
      boost::bind(&server::handle_accept, this,
        asio::placeholders::error));
}

// Handle completion of an accept operation
void server::handle_accept(const asio::error_code& e)
{
  // Check whether the server was stopped by a signal before this completion
  // handler had a chance to run.
  if (!acceptor_.is_open())
  {
    return;
  }

  if (!e)
  {
    connection_manager_.start(new_connection_);
  }

  start_accept();
}

// Handle server stop signals
void server::handle_stop()
{
  // The server is stopped by cancelling all outstanding asynchronous
  // operations. Once all operations have finished the io_context::run() call
  // will exit.
  acceptor_.close();
  connection_manager_.stop_all();
}

} // namespace server
} // namespace http

