#include <vector>
using namespace std;

// Solution class to calculate maximum frequency elements
class Solution {
public:
    int maxFrequencyElements(vector<int>& nums) {
        // Frequency array, max frequency, and count of elements with max frequency
        int freq[101] = {0}, maxF = 0, f = 0;

        // Iterate through each number in the input vector
        for (int x : nums) {
            freq[x]++;

            // If current frequency equals max frequency, increment count
            f += (freq[x] == maxF);

            // If current frequency exceeds max frequency, update max and reset count
            if (freq[x] > maxF) {
                f = 1;
                maxF = freq[x];
            }
        }

        // Return total count of elements with maximum frequency
        return f * maxF;
    }
};

#include <iostream>
#include <string>
#include "asio.hpp"
#include "boost/bind.hpp"

// Multicast port definition
const short multicast_port = 30001;

class receiver
{
public:
  // Constructor for receiver class
  receiver(asio::io_context& io_context,
      const asio::ip::address& listen_address,
      const asio::ip::address& multicast_address)
    : socket_(io_context)
  {
    // Create the socket so that multiple may be bound to the same address.
    asio::ip::udp::endpoint listen_endpoint(
        listen_address, multicast_port);
    socket_.open(listen_endpoint.protocol());
    socket_.set_option(asio::ip::udp::socket::reuse_address(true));
    socket_.bind(listen_endpoint);

    // Join the multicast group.
    socket_.set_option(
        asio::ip::multicast::join_group(multicast_address));

    // Start asynchronous receive operation
    socket_.async_receive_from(
        asio::buffer(data_, max_length), sender_endpoint_,
        boost::bind(&receiver::handle_receive_from, this,
          asio::placeholders::error,
          asio::placeholders::bytes_transferred));
  }

  // Handle received data
  void handle_receive_from(const asio::error_code& error,
      size_t bytes_recvd)
  {
    if (!error)
    {
      std::cout.write(data_, bytes_recvd);
      std::cout << std::endl;

      // Continue receiving more data
      socket_.async_receive_from(
          asio::buffer(data_, max_length), sender_endpoint_,
          boost::bind(&receiver::handle_receive_from, this,
            asio::placeholders::error,
            asio::placeholders::bytes_transferred));
    }
  }

private:
  asio::ip::udp::socket socket_;
  asio::ip::udp::endpoint sender_endpoint_;
  enum { max_length = 1024 };
  char data_[max_length];
};

// Main function
int main(int argc, char* argv[])
{
  try
  {
    // Check command line arguments
    if (argc != 3)
    {
      std::cerr << "Usage: receiver <listen_address> <multicast_address>\n";
      std::cerr << "  For IPv4, try:\n";
      std::cerr << "    receiver 0.0.0.0 239.255.0.1\n";
      std::cerr << "  For IPv6, try:\n";
      std::cerr << "    receiver 0::0 ff31::8000:1234\n";
      return 1;
    }

    asio::io_context io_context;
    receiver r(io_context,
        asio::ip::make_address(argv[1]),
        asio::ip::make_address(argv[2]));

    // Run the I/O context to process asynchronous operations
    io_context.run();
  }
  catch (std::exception& e)
  {
    std::cerr << "Exception: " << e.what() << "\n";
  }

  return 0;
}

