Card Hand::removeCard(const Card& targetCard)
{
  auto iterator = std::find(cards.begin(), cards.end(), targetCard);
  if (iterator != cards.end())
  {
    Card duplicated = *iterator;
    cards.erase(iterator);
    return duplicated;
  }
