// Simple logger without timestamp
class MinimalLogger : public LogHandler {
public:
    void write(const std::string& severity, const std::string& content) override {
        std::cout << severity << ": " << content << std::endl;
    }
};

// Manager class that delegates logging to a handler
class LoggingManager {
private:
    LogHandler* handler;
public:
    LoggingManager(LogHandler* logger) : handler(logger) {}

    void Warning(const char* fmt, ...) {
        va_list arguments;
        va_start(arguments, fmt);
        char output_buffer[256];
        vsnprintf(output_buffer, sizeof(output_buffer), fmt, arguments);
        va_end(arguments);
        handler->write("WARNING", output_buffer);
    }
};

