#include <iostream>
#include <thread>
#include <vector>

// Define the thread function type
typedef void (*ThreadRoutine)(void*);

// Container for thread parameters
struct ThreadParameters {
    std::thread* activeThread;
    ThreadRoutine routine;
    void* data;
};

// Manager class for handling multiple threads
class ThreadPoolController {
public:
    // Add a new thread task to the queue
    void addTask(ThreadRoutine routine, void* data) {
        ThreadParameters params;
        params.routine = routine;
        params.data = data;
        pendingTasks.push_back(params);
    }

    // Launch the most recently added thread
    void launchTask() {
        if (!pendingTasks.empty()) {
            ThreadParameters& task = pendingTasks.back();
            task.activeThread = new std::thread(&ThreadPoolController::runTask, this, &task);
        }
    }

    // Synchronize and clean up the current thread
    void completeTask() {
        if (!pendingTasks.empty()) {
            ThreadParameters& task = pendingTasks.back();
            if (task.activeThread->joinable()) {
                task.activeThread->join();
            }
            delete task.activeThread;
            pendingTasks.pop_back();
        }
    }

private:
    std::vector<ThreadParameters> pendingTasks;

    // Internal method to run the user-provided function
    void runTask(ThreadParameters* taskParams) {
        taskParams->routine(taskParams->data);
    }
};

// Sample function that will be executed in a separate thread
void workerFunction(void* input) {
    int* number = static_cast<int*>(input);
    std::cout << "Worker thread processing value: " << *number << std::endl;
}

int main() {
    ThreadPoolController controller;
    int inputValue = 42;

    controller.addTask(workerFunction, &inputValue);
    controller.launchTask();
    controller.completeTask();

    return 0;
}

