public:
    DataBuffer(char* ptr, size_t len) : data(ptr), capacity(len) {}

    void copyData(void* src, size_t pos, size_t count) {
        if (pos + count > this->capacity) {
            std::cerr << "Warning: copy operation exceeds buffer limit" << std::endl;
