#include <Eigen/Dense>
#include <sstream>
#include <stdexcept>

template <std::size_t Dim>
Eigen::Matrix<double, Dim, 1> convertToVector(const std::string& input) {
    Eigen::Matrix<double, Dim, 1> output;
    std::istringstream stream(input);
    double element;
    std::size_t index = 0;

    while (stream >> element) {
        if (index >= Dim) {
            throw std::invalid_argument("Input string contains more values than the specified vector dimension");
        }
        output(index, 0) = element;
        index++;
    }

    if (index != Dim) {
        throw std::invalid_argument("Input string does not contain sufficient values for the specified vector dimension");
    }

    if (!stream.eof()) {
        throw std::runtime_error("Failed to parse input string correctly");
    }

    return output;
}

