// Compute the volume of a tetrahedron given its four vertices
double computeTetrahedronCapacity(const Coordinate3D& p1, const Coordinate3D& p2, 
                                  const Coordinate3D& p3, const Coordinate3D& p4) {
  // Calculate the determinant-based volume formula
  double result = std::abs((1.0 / 6.0) * ((p2.u - p1.u) * ((p3.v - p1.v) * (p4.w - p1.w) - (p3.w - p1.w) * (p4.v - p1.v)) +
                                           (p2.v - p1.v) * ((p3.w - p1.w) * (p4.u - p1.u) - (p3.u - p1.u) * (p4.w - p1.w)) +
                                           (p2.w - p1.w) * ((p3.u - p1.u) * (p4.v - p1.v) - (p3.v - p1.v) * (p4.u - p1.u))));
  return result;
}

