// Compute the squared Euclidean distance between two vectors
double computeVectorDistanceSquared(const std::vector<double>& inputA, const std::vector<double>& inputB) {
    // Verify that both input vectors have identical dimensions
    if (inputA.size() != inputB.size()) {
        throw std::invalid_argument("Vector dimensions must match");
    }
    // Map the standard vectors to Eigen vector objects for optimized operations
    Eigen::Map<const Eigen::VectorXd> eigenInputA(inputA.data(), inputA.size());
    Eigen::Map<const Eigen::VectorXd> eigenInputB(inputB.data(), inputB.size());
    // Calculate the squared distance via Eigen's squaredNorm method
    double result = (eigenInputA - eigenInputB).squaredNorm();
    return result;
}

