// Function to count elements less than each query value
vector<int> countElementsLessThanX(int arr[], int size, int queryValues[], int numQueries) {
    vector<int> output;

    // Sort the input array for efficient binary search operations
    sort(arr, arr + size);

    // Process each query to find count of elements smaller than the query value
    for (int index = 0; index < numQueries; ++index) {
        int elementCount = upper_bound(arr, arr + size, queryValues[index]) - arr;
        output.push_back(elementCount);
    }

    return output;
}

