// Initialize SDL and handle command-line arguments
void startup(int argCount, char* arguments[])
{
    // Initialize SDL video subsystem
    if (SDL_Init(SDL_INIT_VIDEO) < 0)
    {
        std::cerr << "Unable to initialize SDL Video:" << std::endl;
        std::cerr << "Issue: " << SDL_GetError() << std::endl;
        SDL_Quit();
        std::exit(EXIT_FAILURE);
    }

    // Handle different argument patterns
    if (argCount == 1)
    {
        std::cout << "Syntax: executable_name [parameters]" << std::endl;
    }
    else if (argCount == 2 && (std::string(arguments[1]) == "-h" || std::string(arguments[1]) == "--help"))
    {
        std::cout << "Assistance: Display usage guidelines for this application." << std::endl;
    }
    else if (argCount == 3 && (std::string(arguments[1]) == "-f" || std::string(arguments[1]) == "--file"))
    {
        std::ifstream input(arguments[2]);
        if (input.is_open())
        {
            std::string row;
            while (std::getline(input, row))
            {
                std::cout << row << std::endl;
            }
            input.close();
        }
        else
        {
            std::cerr << "Alert: Could not open file." << std::endl;
        }
    }
    else if (argCount == 4 && (std::string(arguments[1]) == "-s" || std::string(arguments[1]) == "--size"))
    {
        int screenWidth = std::stoi(arguments[2]);
        int screenHeight = std::stoi(arguments[3]);
        SDL_Window* displayWindow = SDL_CreateWindow("SDL Display", SDL_WINDOWPOS_UNDEFINED, SDL_WINDOWPOS_UNDEFINED, screenWidth, screenHeight, SDL_WINDOW_SHOWN);
        if (displayWindow == nullptr)
        {
            std::cerr << "Alert: Could not create SDL window." << std::endl;
        }
    }
    else
    {
        std::cerr << "Alert: Incorrect command-line parameters." << std::endl;
    }
}

