// Perform topological sorting of dependency graph using Kahn's algorithm
std::vector<Node::Ptr> topologicalSort(const std::vector<Node::Ptr>& inputNodes) {
    std::vector<Node::Ptr> resultList;
    std::queue<Node::Ptr> sourceQueue;
    std::unordered_map<Node::Ptr, int> dependencyCount;

    // Initialize dependency counts for all nodes
    for (const auto& currentNode : inputNodes) {
        dependencyCount[currentNode] = 0;
    }

    // Calculate dependencies (in-degree) for each node
    for (const auto& currentNode : inputNodes) {
        for (const auto& dependentNode : getNeighbors(currentNode)) {
            dependencyCount[dependentNode]++;
        }
    }

    // Find all nodes with no dependencies (in-degree zero)
    for (const auto& currentNode : inputNodes) {
        if (dependencyCount[currentNode] == 0) {
            sourceQueue.push(currentNode);
        }
    }

    // Process nodes in topological order
    while (!sourceQueue.empty()) {
        Node::Ptr current = sourceQueue.front();
        sourceQueue.pop();
        resultList.push_back(current);

        // Reduce dependency count for neighbors
        for (const auto& dependentNode : getNeighbors(current)) {
            dependencyCount[dependentNode]--;
            if (dependencyCount[dependentNode] == 0) {
                sourceQueue.push(dependentNode);
            }
        }
    }

    return resultList;
}

