class Coordinate {
private:
    int horizontal, vertical;
public:
    Coordinate(int h, int v) : horizontal(h), vertical(v) {}

    double distanceFromOrigin() {
        return std::sqrt(std::pow(horizontal, 2) + std::pow(vertical, 2));
    }

    double distanceTo(Coordinate other) {
        return std::sqrt(std::pow(other.horizontal - horizontal, 2) + 
                         std::pow(other.vertical - vertical, 2));
    }

    void translate(int deltaX, int deltaY) {
        horizontal += deltaX;
        vertical += deltaY;
    }
};

int main() {
    Coordinate pt1(3, 4);
    std::cout << "Distance from origin: " << pt1.distanceFromOrigin() << std::endl;

    Coordinate pt2(6, 8);
    std::cout << "Distance between pt1 and pt2: " << pt1.distanceTo(pt2) << std::endl;

    pt1.translate(1, 1);
    std::cout << "New coordinates of pt1: (" << pt1.horizontal << ", " << pt1.vertical << ")" << std::endl;

    return 0;
}

