// Perform binary search on a rotated sorted array 
int rotated_array_search(const std::vector<int>& arr, int target, int low, int high) {
    if (low > high) {
        std::cout << "Value " << target << " not located within bounds [" << low << ", " << high << "]." << std::endl;
        return -1;
    }

    int middle = (low + high) / 2;

    if (arr[middle] == target) {
        std::cout << "Value " << target << " discovered at position " << middle << "." << std::endl;
        return middle;
    }

    if (arr[low] <= arr[middle]) {
        if (target >= arr[low] && target < arr[middle]) {
            std::cout << "Proceeding search in left segment indices [" << low << ", " << middle - 1 << "]." << std::endl;
            return rotated_array_search(arr, target, low, middle - 1);
        } else {
            std::cout << "Proceeding search in right segment indices [" << middle + 1 << ", " << high << "]." << std::endl;
            return rotated_array_search(arr, target, middle + 1, high);
        }
    } else {
        if (target > arr[middle] && target <= arr[high]) {
            std::cout << "Proceeding search in right segment indices [" << middle + 1 << ", " << high << "]." << std::endl;
            return rotated_array_search(arr, target, middle + 1, high);
        } else {
            std::cout << "Proceeding search in left segment indices [" << low << ", " << middle - 1 << "]." << std::endl;
            return rotated_array_search(arr, target, low, middle - 1);
        }
    }
}

int main() {
    std::vector<int> arr = {6, 7, 8, 9, 10, 1, 2, 3, 4, 5};
    int pos = rotated_array_search(arr, 3, 0, static_cast<int>(arr.size()) - 1);

    if (pos != -1) {
        std::cout << "Target found at index: " << pos << std::endl;
    } else {
        std::cout << "Target missing from the collection." << std::endl;
    }

    return 0;
}

