class VideoRequestHandler {
public:
    void enqueueVideoRequest(const VideoRequest& request) {
        std::lock_guard<std::mutex> guard(mutexLock);
        pendingRequests[request.getRequestID()] = request;
    }

    void executePendingRequests() {
        std::vector<std::thread> workerThreads;
        for (const auto& pair : pendingRequests) {
            workerThreads.emplace_back(&VideoRequestHandler::handleRequest, this, pair.first);
        }
        for (auto& thread : workerThreads) {
            thread.join();
        }
    }

    void changeRequestState(int requestID, const QString& newState) {
        std::lock_guard<std::mutex> guard(mutexLock);
        auto it = pendingRequests.find(requestID);
        if (it != pendingRequests.end()) {
            it->second.setStatus(newState);
        }
    }

private:
    std::unordered_map<int, VideoRequest> pendingRequests;
    std::mutex mutexLock;

    void handleRequest(int requestID) {
        // Simulate network delay
        std::this_thread::sleep_for(std::chrono::milliseconds(1500));
        changeRequestState(requestID, "Completed");
        qDebug() << "Video request" << requestID << "has been handled";
    }
};

