template <typename T, typename KeyT>
class ContainerStorage {
public:
    using ValueType = T;
    using KeyType = KeyT;
private:
    std::unordered_map<KeyType, ValueType> storage;
public:
    // Inserts an item into the container and returns its identifier
    KeyType insert(const ValueType& value) {
        static KeyType currentId = 0;  // Assuming KeyT supports increment operations
        storage[currentId] = value;
        return currentId++;
    }
    // Fetches the value linked with the provided identifier
    ValueType fetch(const KeyType& id) const {
        auto iter = storage.find(id);
        if (iter != storage.end()) {
            return iter->second;
        } else {
            // Identifier not present, manage error appropriately
            throw std::out_of_range("Identifier not found");
        }
    }
    // Deletes the entry associated with the given identifier from the container
    void eraseEntry(const KeyType& id) {
        storage.erase(id);
    }
};

