// Process an incoming client connection
void processConnection(int connFd) {
    // Fixed HTTP response for the designated route
    std::string reply = "HTTP/1.1 200 OK\nContent-Type: text/plain\nContent-Length: 12\n\nHello, World!";
    // Transmit the reply to the connected client
    send(connFd, reply.c_str(), reply.length(), 0);
    // Terminate the client connection
    close(connFd);
}

int main() {
    // Initialize a TCP socket
    int listenFd = socket(AF_INET, SOCK_STREAM, 0);

    // Configure server address structure
    sockaddr_in localAddr;
    localAddr.sin_family = AF_INET;
    localAddr.sin_port = htons(8080);
    localAddr.sin_addr.s_addr = INADDR_ANY;

    // Bind the socket to the specified port and interface
    bind(listenFd, (struct sockaddr *)&localAddr, sizeof(localAddr));

    // Start listening for incoming connections with a backlog of 5
    listen(listenFd, 5);

    // Main loop to accept and handle client connections
    while (true) {
        int clientFd = accept(listenFd, NULL, NULL);
        processConnection(clientFd);
    }

    // Clean up: close the listening socket (unreachable in this infinite loop)
    close(listenFd);
    return 0;
}

#include "Components/Lights/LightInterface.hpp"
#include <vector>
#include <algorithm>

namespace Components::Lights {
    class PointLight : public LightInterface {
    public:
        PointLight(const glm::vec3& pos, const glm::vec3& col)
            : position_(pos), color_(col) {}
        virtual glm::vec3 CalculateIllumination(const glm::vec3& p) const override {
            glm::vec3 dir = position_ - p;
            float dist = glm::length(dir);
            dir = glm::normalize(dir);
            float atten = 1.0f / (dist * dist);
            return color_ * atten * std::max(glm::dot(glm::vec3(0, 0, 1), dir), 0.0f);
        }
    private:
        glm::vec3 position_;
        glm::vec3 color_;
    };

    class DirectionalLight : public LightInterface {
    public:
        DirectionalLight(const glm::vec3& dir, const glm::vec3& col)
            : direction_(dir), color_(col) {}
        virtual glm::vec3 CalculateIllumination(const glm::vec3& p) const override {
            return color_ * std::max(glm::dot(glm::vec3(0, 0, 1), -direction_), 0.0f);
        }
    private:
        glm::vec3 direction_;
        glm::vec3 color_;
    };

    glm::vec3 CalculateIllumination(const glm::vec3& point, const std::vector<std::shared_ptr<LightInterface>>& lightList) {
        glm::vec3 result(0.0f);
        for (const auto& light : lightList) {
            result += light->CalculateIllumination(point);
        }
        return result;
    }
}

