// Program to determine the day of the week for a given date using Zeller's congruence
int main(int argc, char* argv[]) {
    int currentDay, currentMonth, currentYear;

    // Get day from command line argument or user input
    if (argc > 1) {
        currentDay = std::atoi(argv[1]);
    } else { 
        std::cout << "Enter day: ";
        std::cin >> currentDay;
    }

    std::cout << "Enter month: ";
    std::cin >> currentMonth;
    std::cout << "Enter year: ";
    std::cin >> currentYear;

    // Adjust month and year for Zeller's formula
    if (currentMonth < 3) {
        currentMonth += 12;
        currentYear--;
    }

    int centuryValue = currentYear / 100;
    currentYear %= 100;

    // Calculate day of week using Zeller's congruence
    int weekday = (currentDay + 13 * (currentMonth + 1) / 5 + currentYear + currentYear / 4 + centuryValue / 4 - 2 * centuryValue) % 7;

    // Output the corresponding day name
    switch (weekday) {
        case 0:
            std::cout << "Saturday" << std::endl;
            break;
        case 1:
            std::cout << "Sunday" << std::endl;
            break;
        case 2:
            std::cout << "Monday" << std::endl;
            break;
        case 3:
            std::cout << "Tuesday" << std::endl;
            break;
        case 4:
            std::cout << "Wednesday" << std::endl;
            break;
        case 5:
            std::cout << "Thursday" << std::endl;
            break;
        case 6:
            std::cout << "Friday" << std::endl;
            break;
    }

    return 0;
}

