namespace cuda {
    // Kernel function to perform element-wise addition of two arrays
    __global__ void vectorAddition(const float* inputX, const float* inputY, float* output, size_t length) {
        size_t position = blockIdx.x * blockDim.x + threadIdx.x;
        if (position < length) {
            output[position] = inputX[position] + inputY[position];
        }
    }

    // Host function to manage memory and execute array addition on GPU
    void executeArraySum(const float* cpuA, const float* cpuB, float* cpuResult, size_t count) {
        float *gpuA, *gpuB, *gpuOutput;

        // Allocate device memory for input and output arrays
        cudaMalloc((void**)&gpuA, count * sizeof(float));
        cudaMalloc((void**)&gpuB, count * sizeof(float));
        cudaMalloc((void**)&gpuOutput, count * sizeof(float));

        // Copy input data from host to device
        cudaMemcpy(gpuA, cpuA, count * sizeof(float), cudaMemcpyHostToDevice);
        cudaMemcpy(gpuB, cpuB, count * sizeof(float), cudaMemcpyHostToDevice);

        // Launch kernel with appropriate grid and block dimensions
        vectorAddition<<<(count + 127) / 128, 128>>>(gpuA, gpuB, gpuOutput, count);

        // Copy result back from device to host
        cudaMemcpy(cpuResult, gpuOutput, count * sizeof(float), cudaMemcpyDeviceToHost);

        // Free device memory
        cudaFree(gpuA);
        cudaFree(gpuB);
        cudaFree(gpuOutput);
    }
}

