void Player::updatePosition() {
  int nextX = positionX;
  int nextY = positionY;
  // Adjust coordinates according to the current movement direction
  switch (currentDirection) {
    case Direction::UP:
      nextY = (positionY > 0) ? positionY - 1 : positionY;  // Ascend if not at upper edge
      break;
    case Direction::DOWN:
      nextY = (positionY < MAP_HEIGHT - 1) ? positionY + 1 : positionY;  // Descend if not at lower edge
      break;
    case Direction::LEFT:
      nextX = (positionX > 0) ? positionX - 1 : positionX;  // Move leftward if not at left edge
      break;
    case Direction::RIGHT:
      nextX = (positionX < MAP_WIDTH - 1) ? positionX + 1 : positionX;  // Move rightward if not at right edge
      break;
  }
  // Apply new coordinates only when actual movement occurred
  if (nextX != positionX || nextY != positionY) {
    positionX = nextX;
    positionY = nextY;
  }
}

