// Normalize the result of element-wise multiplication of two images to [0,1]
cv::Mat normalizeProduct(cv::Mat inputImg1, cv::Mat inputImg2) {
    // Compute element-wise product of input images
    cv::Mat result = inputImg1.mul(inputImg2);

    // Determine min and max values in the result matrix
    double minVal, maxVal;
    cv::minMaxLoc(result, &minVal, &maxVal);

    // Scale values to [0, 1] range using min-max normalization
    result = (result - minVal) / (maxVal - minVal);

    return result;
}

