// Verify if the given certificate is valid and signed by the specified CA
bool checkCertValidity(const net::x509_certificate& cert, const net::x509_certificate& issuerCert) {
    // Ensure the certificate hasn't expired yet
    if (cert.valid_expiry() <= net::x509_util::get_current_time()) {
        return false; // Certificate is no longer valid
    }

    // Perform signature verification using the CA certificate
    net::ssl_info connectionInfo;
    connectionInfo.set_certificate(&cert);
    connectionInfo.set_issuer_certificate(&issuerCert);
    return net::x509_util::check_signature_validity(&connectionInfo);
}
