// Compute the elapsed time in years between two dates
double computeYearDifference(const std::tm& startDate, const std::tm& endDate) {
    std::time_t startTimestamp = std::mktime(const_cast<std::tm*>(&startDate));
    std::time_t endTimestamp = std::mktime(const_cast<std::tm*>(&endDate));
    double secondsElapsed = std::difftime(endTimestamp, startTimestamp);
    const double secondsPerYear = 60.0 * 60.0 * 24.0 * 365.25; // accounts for leap years
    return secondsElapsed / secondsPerYear;
}

