void FilterArguments(ArgumentMap& args, const std::set<std::string>& allowedKeys) {
    // Make a copy of the original map to safely iterate while modifying the original
    ArgumentMap tempCopy = args;

    // Traverse the copy and remove disallowed entries from the original map
    for (auto iter = tempCopy.begin(); iter != tempCopy.end(); ) {
