class StringView {
public:
    // Constructors
    constexpr StringView() noexcept : ptr_(nullptr), length_(0) {}
    constexpr StringView(const char* str) noexcept : ptr_(str), length_(std::strlen(str)) {}
    constexpr StringView(const char* str, size_t len) noexcept : ptr_(str), length_(len) {}

    // Accessors
    constexpr const char* data() const noexcept { return ptr_; }
    constexpr size_t length() const noexcept { return length_; }

    // Element access
    constexpr char operator[](size_t index) const { return ptr_[index]; }

    // Comparison
    constexpr bool operator==(StringView other) const noexcept {
        return length_ == other.length_ && std::strncmp(ptr_, other.ptr_, length_) == 0;
    }

    // Substring extraction
    constexpr StringView substr(size_t start, size_t count = max_size) const {
        if (start > length_) start = length_;
        if (count > length_ - start) count = length_ - start;
        return StringView(ptr_ + start, count);
    }

    // Search for character
    constexpr size_t find(char ch, size_t start = 0) const noexcept {
        if (start >= length_) return max_size;
        const char* found = std::strchr(ptr_ + start, ch);
        return found ? static_cast<size_t>(found - ptr_) : max_size;
    }

    static constexpr size_t max_size = static_cast<size_t>(-1);

private:
    const char* ptr_;
    size_t length_;
};

