class TreeNode {
public:
    TreeNode(std::vector<TreeNode*> descendants, std::pair<int, int> coords) : m_descendants(descendants), coords(coords) {}

    void shift(std::pair<int, int> newCoords) {
        // Determine the displacement caused by the shift
        int dx = newCoords.first - coords.first;
        int dy = newCoords.second - coords.second;

        // Update current node's coordinates
        coords = newCoords;

        // Propagate the same displacement to all descendant nodes
        for (auto& descendant : m_descendants) {
            descendant->shift(std::make_pair(descendant->coords.first + dx, descendant->coords.second + dy));
        }
    }

private:
    std::pair<int, int> coords;
    std::vector<TreeNode*> m_descendants;
};

int main() {
    // Construct a tree structure of nodes
    TreeNode* leafA = new TreeNode({}, std::make_pair(2, 3));
    TreeNode* leafB = new TreeNode({}, std::make_pair(4, 5));
    TreeNode* root = new TreeNode({leafA, leafB}, std::make_pair(1, 1));

    // Shift the root node and observe how descendants follow
    root->shift(std::make_pair(6, 7));

    // Deallocate dynamically allocated memory
    delete leafA;
    delete leafB;
    delete root;

    return 0;
}

