class Uint64Array {
private:
    std::vector<uint64_t> m_Data;
public:
    // Constructor to initialize the array with a specified value
    Uint64Array(uint64_t val) : m_Data(64, val) {}

    // Method to add two arrays element-wise
    Uint64Array sum(const Uint64Array& rhs) const {
        Uint64Array output(0);
        for (size_t idx = 0; idx < 64; ++idx) {
            output.m_Data[idx] = m_Data[idx] + rhs.m_Data[idx];
        }
        return output;
    }

    // Method to subtract two arrays element-wise
    Uint64Array difference(const Uint64Array& rhs) const {
        Uint64Array output(0);
        for (size_t idx = 0; idx < 64; ++idx) {
            output.m_Data[idx] = m_Data[idx] - rhs.m_Data[idx];
        }
        return output;
    }

    // Method to multiply two arrays element-wise
    Uint64Array product(const Uint64Array& rhs) const {
        Uint64Array output(0);
        for (size_t idx = 0; idx < 64; ++idx) {
            output.m_Data[idx] = m_Data[idx] * rhs.m_Data[idx];
        }
        return output;
    }

    // Method to divide two arrays element-wise
    Uint64Array quotient(const Uint64Array& rhs) const {
        Uint64Array output(0);
        for (size_t idx = 0; idx < 64; ++idx) {
            if (rhs.m_Data[idx] != 0) {
                output.m_Data[idx] = m_Data[idx] / rhs.m_Data[idx];
            } else {
                // On division by zero, assign maximum uint64_t value
                output.m_Data[idx] = std::numeric_limits<uint64_t>::max();
            }
        }
        return output;
    }

    // Method to get the smallest element in the array
    uint64_t findMin() const {
        return *std::min_element(m_Data.begin(), m_Data.end());
    }

    // Method to get the largest element in the array
    uint64_t findMax() const {
        return *std::max_element(m_Data.begin(), m_Data.end());
    }
};

int main() {
    Uint64Array arr1(5);
    Uint64Array arr2(3);

    Uint64Array resultSum = arr1.sum(arr2);
    Uint64Array resultDiff = arr1.difference(arr2);
    Uint64Array resultProd = arr1.product(arr2);
    Uint64Array resultQuo = arr1.quotient(arr2);

    std::cout << "Minimum of sum: " << resultSum.findMin() << std::endl;
    std::cout << "Maximum of sum: " << resultSum.findMax() << std::endl;
    std::cout << "Minimum of difference: " << resultDiff.findMin() << std::endl;
    std::cout << "Maximum of difference: " << resultDiff.findMax() << std::endl;
    std::cout << "Minimum of product: " << resultProd.findMin() << std::endl;
    std::cout << "Maximum of product: " << resultProd.findMax() << std::endl;
    std::cout << "Minimum of quotient: " << resultQuo.findMin() << std::endl;
    std::cout << "Maximum of quotient: " << resultQuo.findMax() << std::endl;

    return 0;
}

