struct ScalaFpgaRawHeader {
    uint16_t m_minApdOffset;
    uint16_t m_maxApdOffset;
    uint16_t m_frequencyInteger;
    uint16_t m_frequencyFractional;
    uint16_t m_deviceId;
    uint16_t m_reservedHeader7;
};

bool extractHeader(const uint8_t* buffer, size_t bufferSize, ScalaFpgaRawHeader& output) {
    if (bufferSize < sizeof(ScalaFpgaRawHeader)) {
        return false;  // Not enough bytes to read the header
    }

    // Read and assemble the header fields from little-endian data
    output.m_minApdOffset = (buffer[1] << 8) | buffer[0];
    output.m_maxApdOffset = (buffer[3] << 8) | buffer[2];
    output.m_frequencyInteger = (buffer[5] << 8) | buffer[4];
    output.m_frequencyFractional = (buffer[7] << 8) | buffer[6];
    output.m_deviceId = (buffer[9] << 8) | buffer[8];
    output.m_reservedHeader7 = (buffer[11] << 8) | buffer[10];

    return true;  // Successfully parsed the header
}

