// Interpolate between two poses using linear interpolation in the Lie algebra
template <class Group, class Scalar>
Group lerp_transform(const Group& start, const Group& end, const Scalar& alpha) {
    // Compute the relative pose from start to end, scale by alpha, and apply to start
    Group relative = start.inverse() * end;
    Group log_relative = Group::log(relative);
    Group exp_scaled = Group::exp(log_relative * alpha);
    return start * exp_scaled;
}

