class EnergyController {
private:
    int max_energy_level_;
    int min_energy_level_;
public:
    // Constructor to initialize the energy controller
    EnergyController(int max_level, int min_level) : max_energy_level_(max_level), min_energy_level_(min_level) {}

    // Method to fully charge the energy system
    void fullChargeSystem(int& current_energy) const { current_energy = max_energy_level_; }

    // Method to partially reset the energy system
    void partialResetSystem(int& current_energy) const { current_energy = min_energy_level_; }

    // Method to completely discharge the energy system
    void fullDischargeSystem(int& current_energy) const { current_energy = 0; }

    // Method to check if the energy system is at maximum capacity
    bool isAtMaxCapacity(const int current_energy) const {
        return current_energy >= max_energy_level_;
    }

    // Method to check if the energy system has minimum required charge
    bool hasMinimumCharge(const int current_energy) const {
        return current_energy >= min_energy_level_;
    }
};

