    controller.partialResetSystem(energy_level);
    std::cout << "System has minimum charge: " << controller.hasMinimumCharge(energy_level) << std::endl;

    controller.fullDischargeSystem(energy_level);
    std::cout << "System at max capacity: " << controller.isAtMaxCapacity(energy_level) << std::endl;

