class ShaderProgram {
public:
    unsigned int createShader(const char* sourceCode, GLenum shaderType);
};

unsigned int ShaderProgram::createShader(const char* sourceCode, GLenum shaderType) {
    int compiled;
    char logBuffer[512];
    unsigned int shaderId = glCreateShader(shaderType);
    glShaderSource(shaderId, 1, &sourceCode, nullptr);
    glCompileShader(shaderId);
    glGetShaderiv(shaderId, GL_COMPILE_STATUS, &compiled);

    if (!compiled) {
        glGetShaderInfoLog(shaderId, 512, nullptr, logBuffer);
        std::cerr << "Shader compilation failed: " << logBuffer << std::endl;
        return 0;  // Indicate failure with zero return value
    }

    return shaderId;  // Return valid shader object identifier on success
}

