class PerformanceMonitor {
private:
    static std::map<std::string, std::chrono::high_resolution_clock::time_point> startTimeMap;
public:
    static void reset() {
        startTimeMap.clear();
    }

    static void beginMeasurement(const std::string& regionName) {
        startTimeMap[regionName] = std::chrono::high_resolution_clock::now();
    }

    static void endMeasurement(const std::string& regionName) {
        // Skip if the region was never started
        if (startTimeMap.find(regionName) != startTimeMap.end()) {
            auto finishTime = std::chrono::high_resolution_clock::now();
            auto beginTime = startTimeMap[regionName];
            double duration = std::chrono::duration_cast<std::chrono::milliseconds>(finishTime - beginTime).count();
            std::cerr << "Duration for '" << regionName << "': " << duration << " ms\n";
            startTimeMap.erase(regionName);
        }
    }

    static double elapsed(const std::string& regionName) {
        if (startTimeMap.find(regionName) != startTimeMap.end()) {
            auto finishTime = std::chrono::high_resolution_clock::now();
            auto beginTime = startTimeMap[regionName];
            return std::chrono::duration_cast<std::chrono::milliseconds>(finishTime - beginTime).count();
        }
        return 0.0;  // Return zero if region not active
    }

    static void showStats() {
        std::cerr << "Active Regions:\n";
        for (const auto& item : startTimeMap) {
            std::cerr << "Region '" << item.first << "': Active\n";
        }
    }
};

