// Apply rotations around Y and Z axes to a 3D position
glm::vec3 rotatePoint(const glm::vec3& point, float angleY, float angleZ) {
    glm::mat4 rotationY = glm::rotate(glm::mat4(1.0f), glm::radians(angleY), glm::vec3(0.0f, 1.0f, 0.0f));
    glm::mat4 rotationZ = glm::rotate(glm::mat4(1.0f), glm::radians(angleZ), glm::vec3(0.0f, 0.0f, 1.0f));

    glm::vec4 homogeneousPoint(point, 1.0f);  // Convert to homogeneous coordinates

    // Apply the rotation transformations
    homogeneousPoint = rotationZ * rotationY * homogeneousPoint;

    // Return the transformed 3D position
    return glm::vec3(homogeneousPoint);
}

