class CustomMemoryManager {
    std::shared_ptr<void> memoryBlock;

    template<typename U>
    static void cleanupHandler(void* rawPtr) {
        static_cast<U*>(rawPtr)->~U();
        ::operator delete(rawPtr);
    }

public:
    template<typename U>
    U* allocate() {
        memoryBlock.reset(static_cast<U*>(::operator new(sizeof(U))), cleanupHandler<U>);
        return static_cast<U*>(memoryBlock.get());
    }

    template<typename U>
    void deallocate(U* address) {
        if (address == memoryBlock.get()) {
            memoryBlock.reset();
        }
    }
};

