void processPerformance(const std::vector<int>& sourceData, std::vector<int>& targetBuffer, int segmentIndex, int blockSize) {
    if (segmentIndex > 0) {
        size_t offset = (segmentIndex - 1) * blockSize;
        switch (Settings::getPerformanceMode()) {
            case PerformanceType::NONE:
                // No operation required for NONE mode
                break;
            case PerformanceType::INDIVIDUAL:
                // Copy a segment from sourceData to targetBuffer
                std::copy(sourceData.begin() + offset, 
                          sourceData.begin() + offset + blockSize, 
                          targetBuffer.begin());
                break;
            case PerformanceType::GROUP:
                // Signal that group processing is not implemented
                assert(false);
                break;
        }
    }
}

