#include <vector>

// Helper function to get the next child node in a DIE tree traversal
TOptional<DwarfNode> NextChild() override
{
    Dwarf_Error error;
    int result;

    // Attempt to get the first child of the current DIE
    if (dwarf_child(mCurrentDie, &mCurrentDie, &error) == DW_DLV_OK) {
        // Save the current DIE as a parent before descending
        mParents.push_back(mCurrentDie);
        return TOptional<DwarfNode>(mCurrentDie);
    }

    // Backtrack through parent nodes to find siblings or cousins
    while (!mParents.empty()) {
        Dwarf_Off currentOffset = dwarf_dieoffset(mCurrentDie);
        Dwarf_Off parentOffset = dwarf_dieoffset(mParents.back());

        if (currentOffset == parentOffset) {
            // We've returned to a parent; try its next child
            mCurrentDie = mParents.back();
            mParents.pop_back();

            if (dwarf_child(mCurrentDie, &mCurrentDie, &error) == DW_DLV_OK) {
                mParents.push_back(mCurrentDie);
                return TOptional<DwarfNode>(mCurrentDie);
            }
        } else {
            // Continue backtracking up the tree
            mParents.pop_back();
        }
    }

    // All children have been processed
    return TOptional<DwarfNode>();
}

