// Convert quaternion to transformation matrix
Transform Quaternion::ToTransform() const {
    // Compute squared components and cross terms
    Float xx = v.x * v.x;
    Float yy = v.y * v.y;
    Float zz = v.z * v.z;
    Float xy = v.x * v.y;
    Float xz = v.x * v.z;
    Float yz = v.y * v.z;

    // Populate the 4x4 transformation matrix elements
    Float matrix[16] = {
        1 - 2 * (yy + zz), 2 * (xy - w * v.z), 2 * (xz + w * v.y), 0,
        2 * (xy + w * v.z), 1 - 2 * (xx + zz), 2 * (yz - w * v.x), 0,
        2 * (xz - w * v.y), 2 * (yz + w * v.x), 1 - 2 * (xx + yy), 0,
        0, 0, 0, 1
    };

    // Construct and return the transformation from the computed matrix
    return Transform(matrix);
}

