class MortonHashTable {
private:
    size_t itemCount; // Number of entries stored in the hash table
public:
    // Constructor and other methods are not shown for brevity
    size_t MemoryFootprint() const
    {
        // Estimate memory usage in bytes considering bucket structure and fingerprint storage
        // Morton3_8 uses 3-slot buckets with 8-bit fingerprints: 11.7 bits per item at load factor 0.95
        double bitsPerElement = 11.7;
        double occupancyRate = 0.95;
        double requiredBits = itemCount * bitsPerElement / occupancyRate;
        size_t requiredBytes = static_cast<size_t>(std::ceil(requiredBits / 8.0));
        return requiredBytes;
    }
};

