// Convert hexadecimal representation to GUID structure
GUID parseHexToGuid(const std::string& hexInput)
{
    const size_t expectedLength = 32;
    if (hexInput.length() != expectedLength) {
        throw std::invalid_argument("Invalid hexadecimal string length");
    }

    GUID guidValue;
    const int byteCount = 16;  // GUID consists of 16 bytes

    for (int index = 0; index < byteCount; ++index) {
        std::string twoChars = hexInput.substr(index * 2, 2);
        guidValue.Data4[index] = static_cast<unsigned char>(std::stoi(twoChars, nullptr, 16));
    }

    return guidValue;
}

