std::string foldAndReverse(const std::string& source, int chunkSize) {
    std::string temp = source;
    std::reverse(temp.begin(), temp.end());

    std::string result;
    for (size_t index = 0; index < temp.length(); index += chunkSize) {
        result += temp.substr(index, chunkSize);
        if (index + chunkSize < temp.length()) {
            result += ",";
        }
    }
    return result;
}

