class Solution {
public:
    bool isPermutation(std::string str1, std::string str2) {
        // First check if the strings have equal length - if not, they can't be permutations
        if (str1.size() != str2.size()) {
            return false;
        }

        // Sort both strings to normalize their character order
        std::sort(str1.begin(), str1.end());
        std::sort(str2.begin(), str2.end());

        // If the sorted versions are identical, the original strings are permutations
        return str1 == str2;
    }
};

