// Compute the sum of non-NaN values along a given dimension, considering masks
Variable nansum(const Variable &data, const Dim axis, const Masks &mask_set) {
  if (const auto combined_mask = irreducible_mask(mask_set, axis);
      combined_mask.is_valid()) {
    // Apply the mask to exclude invalid elements and recurse
    return nansum(where(combined_mask, zero_like(data), data), axis, mask_set);
  } else {
    // Perform sum over non-NaN entries for the specified axis
    switch (axis) {
      case Dim::ROW:
        return sum(where(isnan(data), 0, data), Dim::ROW);
      case Dim::COLUMN:
        return sum(where(isnan(data), 0, data), Dim::COLUMN);
      // Support more dimensions as required
      default:
        throw std::invalid_argument("Unsupported dimension provided");
    }
  }
}

