// Verify the normal derivative computation using finite differences
void compare_normal_derivative(double step_size, BicubicPatch* surface_patch, Vector3 reference_normal, int tolerance, Vector3 analytical_full_deriv) {
    // Preserve original data for later restoration
    double saved_f = surface_patch->n01->f;
    Vector3 saved_dx = surface_patch->n01->dx;

    // Compute approximate derivative via perturbation
    surface_patch->n01->f += step_size;
    Vector3 perturbed_result = surface_patch->calculateNormal();
    Vector3 finite_diff_deriv = (perturbed_result - reference_normal) / step_size;

    // Restore original state
    surface_patch->n01->f = saved_f;

    // Evaluate deviation between numerical and analytical results
    double discrepancy = (finite_diff_deriv - analytical_full_deriv).length();

    // Report outcome based on tolerance threshold
    if (discrepancy < tolerance) {
        std::cout << "Normal derivative validation succeeded with error: " << discrepancy << std::endl;
    } else {
        std::cout << "Normal derivative validation failed with error: " << discrepancy << std::endl;
    }

    // Restore dx component to initial condition
    surface_patch->n01->dx = saved_dx;
}

