// Function to find maximum count of elements from two arrays whose combined sum stays below threshold
int countMaxElementsUnderLimit(int sizeA, int sizeB, int limit, int arr1[], int arr2[]) {
    // Sort both arrays in descending sequence
    std::sort(arr1, arr1 + sizeA, std::greater<int>());
    std::sort(arr2, arr2 + sizeB, std::greater<int>());

    int elementCount = 0;
    int currentSum = 0;
    int idx1 = 0, idx2 = 0;

    // Process elements while both arrays have remaining items
    while (idx1 < sizeA && idx2 < sizeB) {
        if (arr1[idx1] + arr2[idx2] <= limit) {
            currentSum += arr1[idx1] + arr2[idx2];
            idx1++;
            idx2++;
            elementCount += 2;
        } else if (arr1[idx1] <= limit) {
            currentSum += arr1[idx1];
            idx1++;
            elementCount++;
        } else if (arr2[idx2] <= limit) {
            currentSum += arr2[idx2];
            idx2++;
            elementCount++;
        } else {
            break;
        }

        // Check if sum exceeded limit and adjust accordingly
        if (currentSum > limit) {
            elementCount--;
            break;
        }
    }

    // Process remaining elements from first array
    while (idx1 < sizeA && arr1[idx1] <= limit) {
        currentSum += arr1[idx1];
        idx1++;
        elementCount++;
        if (currentSum > limit) {
            elementCount--;
            break;
        }
    }

    // Process remaining elements from second array
    while (idx2 < sizeB && arr2[idx2] <= limit) {
        currentSum += arr2[idx2];
        idx2++;
        elementCount++;
        if (currentSum > limit) {
            elementCount--;
            break;
        }
    }

    return elementCount;
}

