class NonCopyable {
protected:
    NonCopyable() = default;
    ~NonCopyable() = default;
private:
    NonCopyable(const NonCopyable&) = delete;
    NonCopyable& operator=(const NonCopyable&) = delete;
};

class LockGuard {
public:
    void Acquire() {
        mtx.lock();
    }
    void Release() {
        mtx.unlock();
    }
private:
    std::mutex mtx;
};

class AutoLock : private NonCopyable {
public:
    explicit AutoLock(LockGuard& guard)
        : lg(guard) {
        lg.Acquire();
    }
    ~AutoLock() {
        lg.Release();
    }
private:
    LockGuard& lg;
};

template <typename Type>
class ConcurrentStack {
public:
    void Emplace(const Type& item) {
        AutoLock lock(lg);
        container.push(item);
    }

    bool Extract(Type& result) {
        AutoLock lock(lg);
        if (container.empty()) {
            return false;
        }
        result = container.top();
        container.pop();
        return true;
    }

    bool Empty() const {
        AutoLock lock(lg);
        return container.empty();
    }
private:
    std::stack<Type> container;
    LockGuard lg;
};

