// Function to process and modify the first Modbus request and response packets
void processFirstModbusRequestAndResponsePackets(PcapFileReaderDevice *inputReader, PcapFileWriterDevice *outputWriter) {
    bool requestFound = false;
    bool responseFound = false;

    // Loop through all packets in the input PCAP file
    while (true) {
        RawPacket currentPacket;
        if (!inputReader->getNextPacket(currentPacket)) {
            // End of packet stream reached
            break;
        }

        // Decode the raw packet into a Modbus packet structure
        ModbusPacket decodedPacket = parseModbusPacket(currentPacket);

        if (decodedPacket.type == ModbusPacketType::Request && !requestFound) {
            // Apply modifications to the first Modbus request encountered
            modifyModbusRequest(decodedPacket);
            requestFound = true;
        } else if (decodedPacket.type == ModbusPacketType::Response && !responseFound) {
            // Apply modifications to the first Modbus response encountered
            modifyModbusResponse(decodedPacket);
            responseFound = true;
        }

        // Save the (potentially modified) packet to the output file
        outputWriter->writePacket(currentPacket);
    }

    // Validate that both required packet types were found
    if (!requestFound || !responseFound) {
        // Report error if either packet type is missing
        EXIT_WITH_ERROR("Missing Modbus request or response packets");
    }
}

