struct Ray {
    Vector3 origin;
    Vector3 direction;
};

struct IntersectionTestResult {
    bool intersects = false;
    Vector3 intersectionPoint;
};

class Plane {
public:
    Vector3 point;
    Vector3 normal() const;
};

// Check for intersection between a ray and a plane
IntersectionTestResult checkRayPlaneIntersection(const Ray& rayData) {
    IntersectionTestResult intersectionResult;

    // Compute the denominator: dot product of ray direction and plane normal
    float directionDotNormal = dot(rayData.direction, rayData.normal());

    // Handle case where ray is parallel to plane (denominator near zero)
    const float TOLERANCE = 1e-6f;
    if (std::abs(directionDotNormal) < TOLERANCE) {
        intersectionResult.intersects = false;
        return intersectionResult;
    }

    // Calculate parametric distance from ray origin to plane
    float distanceToPlane = dot(plane.point - rayData.origin, plane.normal()) / directionDotNormal;

    // Reject if intersection occurs behind the ray origin
    if (distanceToPlane < 0.0f) {
        intersectionResult.intersects = false;
        return intersectionResult;
    }

    // Determine actual intersection point using parametric equation
    intersectionResult.intersectionPoint = rayData.origin + distanceToPlane * rayData.direction;
    intersectionResult.intersects = true;
    return intersectionResult;
}

