// Recursive helper to find all unique combinations that sum to the target value
void combinationSearchHelper(std::vector<int>& elements, int remaining, int index, 
                            std::vector<int>& path, std::vector<std::vector<int>>& solutions) {
    if (remaining == 0) {
        solutions.push_back(path);
        return;
    }

    for (int j = index; j < elements.size(); ++j) {
        // Skip duplicate elements to avoid redundant combinations
        if (j > index && elements[j] == elements[j - 1]) continue;

        // Early termination if current element exceeds remaining target
        if (elements[j] > remaining) break;

        path.push_back(elements[j]);
        combinationSearchHelper(elements, remaining - elements[j], j + 1, path, solutions);
        path.pop_back();
    }
}

std::vector<std::vector<int>> generateUniqueCombinations(std::vector<int>& input, int goal) {
    std::sort(input.begin(), input.end());
    std::vector<std::vector<int>> output;
    std::vector<int> temp;
    combinationSearchHelper(input, goal, 0, temp, output);
    return output;
}

