// Save point cloud data to a PLY file in binary little-endian format
void PointCloud::writePLY(std::string filePath, cv::Mat pointData) {
  std::ofstream outFile(filePath, std::ios::out | std::ios::binary);
  if (!outFile.is_open()) {
    std::cerr << "Error: Cannot open file for writing" << std::endl;
    return;
  }

  int totalPoints = pointData.rows;
  int channelsPerPoint = pointData.cols;

  // Write the standard PLY header
  outFile << "ply" << std::endl;
  outFile << "format binary_little_endian 1.0" << std::endl;
  outFile << "element vertex " << totalPoints << std::endl;
  outFile << "property float x" << std::endl;
  outFile << "property float y" << std::endl;
  outFile << "property float z" << std::endl;
  outFile << "end_header" << std::endl;

  // Serialize point coordinates into the file
  for (int idx = 0; idx < totalPoints; ++idx) {
    float px = pointData.at<float>(idx, 0);
    float py = pointData.at<float>(idx, 1);
    float pz = pointData.at<float>(idx, 2);

    outFile.write(reinterpret_cast<const char*>(&px), sizeof(float));
    outFile.write(reinterpret_cast<const char*>(&py), sizeof(float));
    outFile.write(reinterpret_cast<const char*>(&pz), sizeof(float));

    // Additional properties could be written here if needed
  }

  outFile.close();
}

