// First task: waits a random time then signals completion
void execute_first_task(boost::promise<void>& signal) {
    std::random_device entropy_source;
    std::mt19937 rng_engine(entropy_source());
    std::uniform_int_distribution<> wait_duration(1000, 5000);
    std::this_thread::sleep_for(std::chrono::milliseconds(wait_duration(rng_engine)));
    signal.set_value();
}

// Second task: waits for another future to complete, then signals
void execute_second_task(boost::promise<void>& signal, boost::future<void>& dependency) {
    dependency.wait();
    signal.set_value();
}

int main() {
    boost::promise<void> first_signal;
    boost::promise<void> second_signal;
    boost::future<void> ready_future = boost::make_ready_future();
    boost::future<void> dependent_future = second_signal.get_future();

    std::thread worker1(execute_first_task, std::ref(first_signal));
    std::thread worker2(execute_second_task, std::ref(second_signal), std::ref(ready_future));

    worker1.join();
    worker2.join();

    std::cout << "All operations finished" << std::endl;
    return 0;
}

