// GPIO pin types enumeration
enum class PinMode { DIGITAL_INPUT, DIGITAL_OUTPUT, PWM, SERVO };
enum class signalLevel { high, low };

class GpioController {
private:
    std::map<int, int> pinMap;
    std::function<void(int, int)> onPinChange;

public:
    void setPin(int pinNumber, int value, PinMode mode) {
        auto iter = this->pinMap.find(pinNumber);
        if (iter == this->pinMap.end()) return;

        switch (mode) {
            case PinMode::DIGITAL_INPUT:
            case PinMode::DIGITAL_OUTPUT:
                iter->second = (value != 0) ? static_cast<int>(signalLevel::high) : static_cast<int>(signalLevel::low);
                break;
            case PinMode::PWM:
            case PinMode::SERVO:
                iter->second = value;
                break;
            default:
                return;
        }

        if (this->onPinChange != nullptr) {
            this->onPinChange(pinNumber, iter->second);
        }
    }

    void setCallback(std::function<void(int, int)> callback) {
        this->onPinChange = callback;
    }
};

int main() {
    // Initialize GPIO controller and test different pin modes
    GpioController gpio;

    // Set digital output pin to high state
    gpio.setPin(3, 2, PinMode::DIGITAL_OUTPUT);

    // Configure PWM pin with intermediate value
    gpio.setPin(5, 128, PinMode::PWM);

    return 0;
}

