    std::pair<int, int> bounds;
    int attemptCount;
public:
    HiddenValue(int lower, int upper) : bounds(std::make_pair(lower, upper)), attemptCount(0) {
        srand(static_cast<unsigned int>(time(nullptr)));
        target = rand() % (upper - lower + 1) + lower;
    }

