// Maps a file into memory using Windows API calls
void* MapFileIntoMemory(HANDLE file_handle) {
  // Create a file mapping object that refers to the file.
  HANDLE file_mapping_object =
      CreateFileMappingA(file_handle, nullptr, PAGE_READONLY, 0, 0, nullptr);
  if (file_mapping_object == NULL) {
    const std::string system_error = GetLastSystemError();
    SAFTM_LOG(ERROR) << "Error while mmapping: " << system_error;
    return nullptr;  // Return nullptr to indicate failure.
  }
  Win32HandleCloser handle_closer(file_mapping_object);
  // Map the file mapping object into memory.
  void *mapped_address = MapViewOfFile(file_mapping_object, FILE_MAP_READ, 0, 0, 0);
  if (mapped_address == nullptr) {
    const std::string system_error = GetLastSystemError();
    SAFTM_LOG(ERROR) << "Error while mapping file into memory: " << system_error;
    return nullptr;  // Return nullptr to indicate failure.
  }
  return mapped_address;  // Return the pointer to the mapped memory.
}

