// Validates the input tensor for L2 normalization operation
arm_compute::Status ClL2NormalizationWorkloadValidate(const TensorInfo& tensor_info,
                                                      const DataLayout& layout)
{
    // Verify that the tensor can be resized and has correct layout
    if (!tensor_info.is_resizable() || tensor_info.data_layout() != DataLayout::NHWC)
    {
        return arm_compute::Status(arm_compute::ErrorCode::RUNTIME_ERROR, "Invalid input tensor configuration");
    }

    // Ensure the data type is supported (FP16 or FP32 only)
    if (tensor_info.data_type() != DataType::F16 && tensor_info.data_type() != DataType::F32)
    {
        return arm_compute::Status(arm_compute::ErrorCode::RUNTIME_ERROR, "Data type not supported for L2 normalization");
    }

    // Validate tensor shape requirements for L2 normalization
    const TensorShape& shape = tensor_info.tensor_shape();
    if (shape.num_dimensions() != 4 || shape[2] != 1 || shape[3] != 1)
    {
        return arm_compute::Status(arm_compute::ErrorCode::RUNTIME_ERROR, "Tensor dimensions incompatible with L2 normalization");
    }

    // All validation checks passed successfully
    return arm_compute::Status::Success;
}

