namespace rw {
    namespace math {
        template <typename T>
        class Quaternion {
        public:
            T real;
            T imagX;
            T imagY;
            T imagZ;

            Quaternion(T w, T x, T y, T z) 
                : real(w), imagX(x), imagY(y), imagZ(z) {}

            Quaternion<T> getConjugate() const {
                return Quaternion<T>(real, -imagX, -imagY, -imagZ);
            }

            Quaternion<T> multiplyWith(const Quaternion<T>& rhs) const {
                T resReal = real * rhs.real - imagX * rhs.imagX - imagY * rhs.imagY - imagZ * rhs.imagZ;
                T resIX   = real * rhs.imagX + imagX * rhs.real + imagY * rhs.imagZ - imagZ * rhs.imagY;
                T resIY   = real * rhs.imagY - imagX * rhs.imagZ + imagY * rhs.real + imagZ * rhs.imagX;
                T resIZ   = real * rhs.imagZ + imagX * rhs.imagY - imagY * rhs.imagX + imagZ * rhs.real;
                return Quaternion<T>(resReal, resIX, resIY, resIZ);
            }

            void scaleToUnit() {
                T len = std::sqrt(real * real + imagX * imagX + imagY * imagY + imagZ * imagZ);
                if (len != static_cast<T>(0)) {
                    real /= len;
                    imagX /= len;
                    imagY /= len;
                    imagZ /= len;
                }
            }
        };
    } // namespace math
} // namespace rw

