// Validate whether a given path conforms to the expected project directory structure
bool checkProjectPath(const std::string& path) {
    // Ensure the path string is not empty
    if (path.empty()) {
        return false;
    }

    // Verify that no whitespace characters are present in the path
    if (std::any_of(path.begin(), path.end(), ::isspace)) {
        return false;
    }

