template <typename T>
struct serializer_helper {
    static bool deserialize(pb_istream_t *input_stream, const pb_field_t *field_descriptor, void **user_data) {
        auto *container = static_cast<std::map<typename T::KeyType, typename T::ValueType> *>(*user_data);
        T entry;
        // Decode the incoming protobuf message from the stream
        if (!pb_decode(input_stream, field_descriptor, &entry)) {
            return false; // Indicate failure on decode error
        }
        // Insert the deserialized key-value pair into the map
        container->insert(std::make_pair(entry.key_field, entry.value_field));
        return true; // Confirm successful deserialization and insertion
    }
};

