class MemoryBlockAllocator {
private:
    int capacity;
    std::vector<bool> blockStatus;  // Tracks whether each memory slot is in use
public:
    MemoryBlockAllocator(int totalSlots) : capacity(totalSlots), blockStatus(totalSlots, false) {}

    int findAndReserve(int requiredBlocks) {
        for (int position = 0; position <= capacity - requiredBlocks; ++position) {
            if (std::all_of(blockStatus.begin() + position, 
                           blockStatus.begin() + position + requiredBlocks, 
                           [](bool status) { return !status; })) {
                for (int slot = position; slot < position + requiredBlocks; ++slot) {
                    blockStatus[slot] = true;  // Mark slots as occupied
                }
                return position;  // Return starting index of reserved area
            }
        }
        return -1;  // Insufficient contiguous space available
    }

    void release(int location) {
        if (location >= 0 && location < capacity) {
            blockStatus[location] = false;  // Mark slot as free again
        }
    }
};

