void exportAggregatedDataToNetCDF(const std::vector<double>& local_column_values, const std::string& output_filename) {
    // Perform global reduction (sum) across processors
    amrex::ParallelDescriptor::ReduceRealSum(local_column_values.data(), local_column_values.size(), amrex::ParallelDescriptor::IOProcessorNumber());

