// Structure to store parsed command-line configuration
struct ProgramArguments {
    std::string inputScript;
    std::vector<std::string> extraStrings;
    int testCaseId;
    bool isThreeDimensional;
    bool executeDifferenceTest;
    double differencePerturbationFactor;
};

// Function to process command-line inputs and populate the configuration structure
ProgramArguments parseInputParameters(int argumentCount, char* arguments[]) {
    ProgramArguments config;

    // Map option flags to their corresponding storage locations and descriptions
    std::unordered_map<std::string, std::pair<void*, std::string>> flagMap = {
        {"-script", {&config.inputScript, "Lua script file for initial data"}},
        {"-e", {&config.extraStrings, "Additional string to append to script"}},
        {"-testcase", {&config.testCaseId, "Identifier for test case (non-Lua)"}},
        {"--3d", {&config.isThreeDimensional, "Enable 3D mode (non-Lua)"}},
        {"--diff_test", {&config.executeDifferenceTest, "Execute difference test (non-Lua)"}},
        {"-dpf", {&config.differencePerturbationFactor, "Perturbation scale for diff test (non-Lua)"}}
    };

    // Process each command-line argument
    for (int index = 1; index < argumentCount; ++index) {
        std::string currentArg = arguments[index];
        if (flagMap.find(currentArg) != flagMap.end()) {
            auto& [storagePtr, description] = flagMap[currentArg];

            if (currentArg == "-e") {
                if (index + 1 < argumentCount && arguments[index + 1][0] != '-') {
                    static_cast<std::vector<std::string>*>(storagePtr)->push_back(arguments[index + 1]);
                    ++index;
                }
            } else if (currentArg == "--3d" || currentArg == "--diff_test") {
                *static_cast<bool*>(storagePtr) = true;
            } else {
                if (index + 1 < argumentCount && arguments[index + 1][0] != '-') {
                    if (currentArg == "-dpf") {
                        *static_cast<double*>(storagePtr) = std::stod(arguments[index + 1]);
                    } else {
                        *static_cast<std::string*>(storagePtr) = arguments[index + 1];
                    }
                    ++index;
                }
            }
        }
    }
    return config;
}

int main(int argc, char* argv[]) {
    ProgramArguments config = parseInputParameters(argc, argv);

    // Output the parsed configuration values
    std::cout << "Script File: " << config.inputScript << std::endl;
    std::cout << "Extra Strings: ";
    for (const auto& s : config.extraStrings) {
        std::cout << s << " ";
    }
    std::cout << std::endl;
    std::cout << "Test Case ID: " << config.testCaseId << std::endl;
    std::cout << "3D Mode: " << (config.isThreeDimensional ? "enabled" : "disabled") << std::endl;
    std::cout << "Difference Test: " << (config.executeDifferenceTest ? "yes" : "no") << std::endl;
    std::cout << "Perturbation Factor: " << config.differencePerturbationFactor << std::endl;

    return 0;
}

