namespace blmc_controllers
{
    class CentroidalPDController
    {
    public:
        CentroidalPDController(double proportional_gain, double derivative_gain)
            : kp_(proportional_gain), kd_(derivative_gain) {}

        void update(const RobotState& current_robot_state, ActuatorCommand& output_actuator_command)
        {
            // Retrieve current center of mass position and velocity from robot state
            Eigen::Vector3d com_position = current_robot_state.getCenterOfMassPosition();
            Eigen::Vector3d com_velocity = current_robot_state.getCenterOfMassVelocity();

            // Compute error between desired and actual center of mass position and velocity
            Eigen::Vector3d position_error = desired_com_position_ - com_position;
            Eigen::Vector3d velocity_error = desired_com_velocity_ - com_velocity;

            // Apply PD control law to compute control input
            Eigen::Vector3d control_output = kp_ * position_error + kd_ * velocity_error;

            // Assign the computed control command to the actuator command
            output_actuator_command.setControlCommand(control_output);
        }

        void setDesiredCenterOfMass(const Eigen::Vector3d& target_position, const Eigen::Vector3d& target_velocity)
        {
            desired_com_position_ = target_position;
            desired_com_velocity_ = target_velocity;
        }

    private:
        double kp_;  // Proportional gain
        double kd_;  // Derivative gain
        Eigen::Vector3d desired_com_position_;
        Eigen::Vector3d desired_com_velocity_;
    };
}  // namespace blmc_controllers

