class MeanSquaredError {
private:
    double error_value;
public:
    // Constructor and other methods are not shown for brevity
    // Calculate the gradient of the MSE cost function
    std::vector<double> gradient(const std::vector<double>& predicted_values, int8_t actual_class) const {
        // Convert the expected class to one-hot representation
        size_t num_classes = predicted_values.size();
        std::vector<double> target_vector(num_classes, 0.0);
        target_vector[actual_class] = 1.0;

        // Compute the gradient of the MSE cost function
        std::vector<double> grad_vector(num_classes, 0.0);
        for (size_t idx = 0; idx < num_classes; ++idx) {
            grad_vector[idx] = 2 * (predicted_values[idx] - target_vector[idx]) / num_classes;
        }
        return grad_vector;
    }
};

