    // Function to reverse a given string in-place
    std::string reverseString(const std::string& input) {
        std::string result = input;  // Duplicate the input string
        int start = 0;  // Index pointing to the front of the string
        int end = result.size() - 1;  // Index pointing to the back of the string
        while (start < end) {
            // Exchange characters at the start and end positions
            char buffer = result[start];
            result[start] = result[end];
            result[end] = buffer;
            // Advance the indices toward the center
