// Class to identify supported CPU instruction set extensions
class ProcessorFeatureChecker {
public:
    bool SSE2_ENABLED;
    bool AVX_ENABLED;
    bool AVX2_ENABLED;

    // Execute CPUID instruction to obtain processor information
    void executeCpuid(int registers[4], int leaf_id) {
        __asm__ __volatile__(
            "cpuid"
            : "=a" (registers[0]), "=b" (registers[1]), "=c" (registers[2]), "=d" (registers[3])
            : "a" (leaf_id)
        );
    }

    // Analyze CPU capabilities and update feature flags
    void analyzeFeatures() {
        int cpuRegs[4];
        executeCpuid(cpuRegs, 0);
        int maxLeaf = cpuRegs[0];

        if (maxLeaf >= 1) {
            executeCpuid(cpuRegs, 1);
            // Determine SSE2 availability (bit 26 in EDX)
            SSE2_ENABLED = (cpuRegs[3] & (1 << 26)) != 0;
            // Determine AVX availability (bit 28 in ECX)
            AVX_ENABLED = (cpuRegs[2] & (1 << 28)) != 0;
        }

        if (maxLeaf >= 7) {
            executeCpuid(cpuRegs, 7);
            // Determine AVX2 availability (bit 5 in EBX)
            AVX2_ENABLED = (cpuRegs[1] & (1 << 5)) != 0;
        }
    }
};

int main() {
    ProcessorFeatureChecker processorInfo;
    processorInfo.analyzeFeatures();

    std::cout << "SSE2 available: " << (processorInfo.SSE2_ENABLED ? "Yes" : "No") << std::endl;
    std::cout << "AVX available: " << (processorInfo.AVX_ENABLED ? "Yes" : "No") << std::endl;
    std::cout << "AVX2 available: " << (processorInfo.AVX2_ENABLED ? "Yes" : "No") << std::endl;

    return 0;
}

