#include <torch/extension.h>

std::vector<at::Tensor> attn_score_backward(
    const at::Tensor &grad_out,
    const at::Tensor &query,
    const at::Tensor &keys,
    const at::Tensor &bias_term,
    const at::Tensor &linear_attn) {
    // Compute gradients of input tensors using chain rule and grad_out
    at::Tensor grad_query = grad_out.matmul(linear_attn.t());
    at::Tensor grad_keys = grad_out.t().matmul(query).t();
    at::Tensor grad_bias = grad_out.sum(0, true);
    at::Tensor grad_linear = grad_out.t().matmul(query.t());
    return {grad_query, grad_keys, grad_bias, grad_linear};
}

