template <typename T>
__host__ __device__ T find_greatest(T val1, T val2) {
  return val1 > val2 ? val1 : val2;
}

// Host-side demonstration using find_greatest
void hostMaxExample() {
  int x = 15, y = 25;
  int maxValue = find_greatest(x, y);
  std::cout << "Host Max Value: " << maxValue << std::endl;
}

// Device kernel applying find_greatest element-wise
__global__ void deviceMaxExample(int* inputA, int* inputB, int* output, int length) {
  int index = blockIdx.x * blockDim.x + threadIdx.x;
  if (index < length) {
    output[index] = find_greatest(inputA[index], inputB[index]);
  }
}

int main() {
  // Host-side demonstration
  hostMaxExample();

  // Device-side demonstration
  const int N = 5;
  int hostInput1[N] = {2, 6, 4, 8, 10};
  int hostInput2[N] = {3, 1, 7, 5, 9};
  int hostOutput[N];

  int* deviceInput1, *deviceInput2, *deviceOutput;
  cudaMalloc((void**)&deviceInput1, N * sizeof(int));
  cudaMalloc((void**)&deviceInput2, N * sizeof(int));
  cudaMalloc((void**)&deviceOutput, N * sizeof(int));

  cudaMemcpy(deviceInput1, hostInput1, N * sizeof(int), cudaMemcpyHostToDevice);
  cudaMemcpy(deviceInput2, hostInput2, N * sizeof(int), cudaMemcpyHostToDevice);

  deviceMaxExample<<<1, N>>>(deviceInput1, deviceInput2, deviceOutput, N);

  cudaMemcpy(hostOutput, deviceOutput, N * sizeof(int), cudaMemcpyDeviceToHost);

  std::cout << "Device Max Results: ";
  for (int i = 0; i < N; ++i) {
    std::cout << hostOutput[i] << " ";
  }
  std::cout << std::endl;

  cudaFree(deviceInput1);
  cudaFree(deviceInput2);
  cudaFree(deviceOutput);

  return 0;
}

