class GridPaths {
private:
    vector<string> matrix;
    int result;
    void traverse(int row, int col, int moveRight, int moveDown) {
        if (row == matrix.size() - 1 && col == matrix[0].size() - 1) {
            result++;
            return;
        }
        if (moveRight < matrix.size() - 1) {
            traverse(row, col + 1, moveRight + 1, moveDown);
        }
        if (moveDown < matrix[0].size() - 1) {
            traverse(row + 1, col, moveRight, moveDown + 1);
        }
    }
public:
    int calculatePaths(int size) {
        matrix.clear();
        string line;
        line.push_back('.');
        for (int i = 0; i < size; i++)
            matrix.push_back(line);
        result = 0;
        traverse(0, 0, 0, 0);
        return result;
    }
};

