double computeEuclideanDistance(const std::vector<double>& pointA, const std::vector<double>& pointB) {
    double squaredSum = 0.0;
    for (size_t index = 0; index < pointA.size(); ++index) {
        double diff = pointA[index] - pointB[index];
        squaredSum += diff * diff;
    }
    return std::sqrt(squaredSum);
}

