    for (int sample_idx = 0; sample_idx < group_assignments.size(); ++sample_idx) {
        int assigned_group = group_assignments[sample_idx];
        if (assigned_group > 0 && assigned_group <= num_groups) {
            group_members[assigned_group - 1].push_back(sample_idx);
