// Determine if the second version is newer than the first
bool IsNewerVersion(const std::wstring& currentVersion, const std::wstring& targetVersion) {
    // Parse version components from the strings
    int curMajor, curMinor, tgtMajor, tgtMinor;
    wchar_t ch;
    std::wistringstream curStream(currentVersion), tgtStream(targetVersion);
    curStream >> ch >> curMajor >> ch >> curMinor;
    tgtStream >> ch >> tgtMajor >> ch >> tgtMinor;

    // Check if target version is greater
    if (tgtMajor > curMajor) {
        return true;
    } else if (tgtMajor == curMajor && tgtMinor > curMinor) {
        return true;
    }
    return false;
}

int main() {
    std::wstring wsz_CURRENT_VERSION = L"v 1.0";
    std::wstring wsz_TARGET_VERSION = L"v 5.00";

    if (IsNewerVersion(wsz_CURRENT_VERSION, wsz_TARGET_VERSION)) {
        std::wcout << L"The target version is newer than the current version." << std::endl;
    } else {
        std::wcout << L"The target version is not newer than the current version." << std::endl;
    }

    return 0;
}

