    // Special case for volume descriptor location
    if (position == 16 * SECTOR_SIZE) {
        // This corresponds to the volume descriptor area.
        // Note: Future enhancement could involve parsing directory structures,
        // but current implementation does not provide clear benefit.
        // Following the original logic and comments, we choose not to compress here.
        return false;
    }
    // Compress by default for all other cases
    return true;
}

#include <QTcpSocket>
#include <QByteArray>
#include <QDebug>

void Server::handleNewData()
{
    // Extract data from the network connection
    QByteArray buffer = connection->readAll();

    // Broadcast to all connected peers except originator
    for (QTcpSocket *peer : activeConnections) {
        if (peer != connection) {  // Skip the source client
            qint64 sentBytes = peer->write(buffer);
            if (sentBytes == -1) {
                // Log transmission failure
                qDebug() << "Failed to send data to client";
            }
        }
    }

    // Verify connection status after processing
    if (connection->state() == QAbstractSocket::UnconnectedState) {
        // Clean up disconnected client
        activeConnections.removeAll(connection);
        connection->deleteLater();
    }
}

