std::string transformString(const std::string& source) {
    std::string result = "START";
    for (char currentChar : source) {
        int currentIndex = &currentChar - &source[0];
        if (!((currentChar > 'A' && currentChar < 'Z') && 
              (currentIndex > 0 && source[currentIndex - 1] > 'A' && source[currentIndex - 1] < 'Z')) &&
            !((currentChar > 'a' && currentChar < 'z') && currentChar != ' ')) {
            result += currentChar;
        }
    }
    return result;
}

