// Check if a binary tree is symmetric around its center
bool checkSymmetry(TreeNode* node) {
    if (node == nullptr) {
        return true; // Empty tree is considered symmetric
    }
    return areIdenticalMirrors(node->left, node->right);
}

// Helper function to compare two subtrees for mirror symmetry
bool areIdenticalMirrors(TreeNode* leftBranch, TreeNode* rightBranch) {
    // Both branches are null - symmetric
    if (leftBranch == nullptr && rightBranch == nullptr) {
        return true;
    }

    // One branch is null while the other isn't - not symmetric
    if (leftBranch == nullptr || rightBranch == nullptr) {
        return false;
    }

    // Values don't match - not symmetric
    if (leftBranch->val != rightBranch->val) {
        return false;
    }

    // Recursively check: left's left with right's right AND left's right with right's left
    return areIdenticalMirrors(leftBranch->left, rightBranch->right) && 
           areIdenticalMirrors(leftBranch->right, rightBranch->left);
}

