// Compute the median value of a vector of integers
double calculateMedian(std::vector<int>& values) {
    std::sort(values.begin(), values.end());  // Arrange elements in ascending sequence
    int size = values.size();
    if (size % 2 == 0) {
        // When count is even, return mean of two central elements
        return (static_cast<double>(values[size / 2 - 1]) + static_cast<double>(values[size / 2])) / 2.0;
    } else {
        // When count is odd, return the central element
        return static_cast<double>(values[size / 2]);
    }
}

