namespace throwing {
    class AssignmentForbiddenException : public std::exception {
    public:
        const char* what() const noexcept override {
            return "Copy assignment from unique_ptr is prohibited";
        }
    };

    template <typename T>
    class unique_ptr {
    private:
        T* data;
    public:
        explicit unique_ptr(T* p) : data(p) {}

        ~unique_ptr() {
            delete[] data;
        }

        unique_ptr& operator=(const unique_ptr& other) {
            throw AssignmentForbiddenException();
        }
    };
}

