#include <stack>
#include <string>

// Check if parentheses, brackets, and braces in the string are balanced
bool isParenthesesBalanced(const std::string& text) {
    std::stack<char> buffer;
    for (char ch : text) {
        if (ch == '(' || ch == '[' || ch == '{') {
            buffer.push(ch);
        } else if (ch == ')' || ch == ']' || ch == '}') {
            if (buffer.empty()) {
                return false;  // No matching opening symbol
            }
            char opening = buffer.top();
            buffer.pop();
            if ((ch == ')' && opening != '(') ||
                (ch == ']' && opening != '[') ||
                (ch == '}' && opening != '{')) {
                return false;  // Opening and closing symbols do not match
            }
        }
    }
    return buffer.empty();  // True only if all symbols were matched
}

