int hpx_main(int argc, char** argv)
{
    // Set up HPX execution contexts for distributed operations
    hpx::parallel::execution::parallel_executor context1;
    hpx::parallel::execution::parallel_executor context2;

    // Allocate distributed vectors across localities
    hpx::parallel::vector<int> dataA(100, 0, context1);
    hpx::parallel::vector<int> dataB(100, 0, context2);
    hpx::parallel::vector<int> output(100, 0, context1);

    // Seed random number generator and fill vectors with pseudo-random values
    std::srand(static_cast<unsigned>(std::time(nullptr)));
    std::for_each(dataA.begin(), dataA.end(), [](int& element) { element = std::rand() % 100; });
    std::for_each(dataB.begin(), dataB.end(), [](int& element) { element = std::rand() % 100; });

    // Execute distributed vector addition using parallel transform
    hpx::parallel::transform(context1, dataA.begin(), dataA.end(), dataB.begin(), output.begin(),
        [](int lhs, int rhs) { return lhs + rhs; });

    // Output the resulting vector
    hpx::cout << "Sum of distributed vectors: ";
    for (int value : output)
    {
        hpx::cout << value << " ";
    }
    hpx::cout << hpx::endl;

    return hpx::finalize();
}

