class TicTacToeGame {
private:
    std::vector<std::vector<char>> grid;
    char active_player;
public:
    TicTacToeGame() : grid(3, std::vector<char>(3, ' ')), active_player('X') {}

    void place_mark(int pos) {
        int r = (pos - 1) / 3;
        int c = (pos - 1) % 3;
        if (grid[r][c] == ' ') {
            grid[r][c] = active_player;
            active_player = (active_player == 'X') ? 'O' : 'X';
        }
    }

    bool has_won(char player) {
        // Check rows
        for (int i = 0; i < 3; ++i) {
            if (grid[i][0] == player && grid[i][1] == player && grid[i][2] == player) {
                return true;
            }
            // Check columns
            if (grid[0][i] == player && grid[1][i] == player && grid[2][i] == player) {
                return true;
            }
        }
        // Check diagonals
        if ((grid[0][0] == player && grid[1][1] == player && grid[2][2] == player) ||
            (grid[0][2] == player && grid[1][1] == player && grid[2][0] == player)) {
            return true;
        }
        return false;
    }

    bool is_finished() {
        if (has_won('X') || has_won('O')) {
            return true;
        }
        for (int i = 0; i < 3; ++i) {
            for (int j = 0; j < 3; ++j) {
                if (grid[i][j] == ' ') {
                    return false;
                }
            }
        }
        return true;
    }
};

int main() {
    TicTacToeGame* match = new TicTacToeGame();
    match->place_mark(1);
    std::cout << "Match finished? " << (match->is_finished() ? "Yes" : "No") << std::endl;
    match->place_mark(2);
    std::cout << "Match finished? " << (match->is_finished() ? "Yes" : "No") << std::endl;
    match->place_mark(3);
    std::cout << "Match finished? " << (match->is_finished() ? "Yes" : "No") << std::endl;
    match->place_mark(4);
    std::cout << "Match finished? " << (match->is_finished() ? "Yes" : "No") << std::endl;
    match->place_mark(5);
    std::cout << "Match finished? " << (match->is_finished() ? "Yes" : "No") << std::endl;
    match->place_mark(7);
    std::cout << "Match finished? " << (match->is_finished() ? "Yes" : "No") << std::endl;
    delete match;
    return 0;
}

