// Extract nested identifiers from a given namespace string
std::vector<std::string> findNestedIdentifiers(const std::string& nsName) {
    std::vector<std::string> foundElements;

    // Construct regex pattern to capture identifiers after the namespace prefix
    std::regex pattern("\\b" + nsName + "::(\\w+)");

    // Code snippet containing namespace declarations with nested elements
    std::string sourceCode = R"(
        namespace osquery {
            namespace detail {
                class Logger {
                    // Class implementation
                };
            }
            class Table {
                // Class implementation
            };
            namespace util {
                class Converter {
                    // Class implementation
                };
            }
        }
    )";

    // Perform regex search for matches
    std::smatch resultMatch;
    std::string::const_iterator scanPosition(sourceCode.cbegin());

    while (std::regex_search(scanPosition, sourceCode.cend(), resultMatch, pattern)) {
        foundElements.push_back(resultMatch[1]);
        scanPosition = resultMatch.suffix().first;
    }

    return foundElements;
}

int main() {
    std::vector<std::string> extractedItems = findNestedIdentifiers("osquery");

    for (const auto& item : extractedItems) {
        std::cout << item << std::endl;
    }

