enum class Severity { TRACE, NOTICE, ALERT, CRITICAL };

class LoggingSystem {
public:
    void configureSeverity(Severity level) {
        threshold = level;
    }

    void registerStream(std::ostream& stream) {
        sinks.push_back(&stream);
    }

    void write(Severity level, const std::string& text) {
        if (level >= threshold) {
            for (auto sink : sinks) {
                (*sink) << "[" << severityName(level) << "] " << text << std::endl;
            }
        }
    }

    void trace(const std::string& text) {
        write(Severity::TRACE, text);
    }

    void notice(const std::string& text) {
        write(Severity::NOTICE, text);
    }

    void alert(const std::string& text) {
        write(Severity::ALERT, text);
    }

    void critical(const std::string& text) {
        write(Severity::CRITICAL, text);
    }

private:
    Severity threshold = Severity::TRACE;
    std::vector<std::ostream*> sinks;

    std::string severityName(Severity level) {
        switch (level) {
            case Severity::TRACE:  return "TRACE";
            case Severity::NOTICE: return "NOTICE";
            case Severity::ALERT:  return "ALERT";
            case Severity::CRITICAL: return "CRITICAL";
        }
    }
};

int main() {
    LoggingSystem logger;

    // Register console output
    logger.registerStream(std::cout);

    // Register file output
    std::ofstream logfile("application.log");
    logger.registerStream(logfile);

    // Set minimum severity to NOTICE
    logger.configureSeverity(Severity::NOTICE);

    // Write messages at various severities
    logger.trace("This is a trace message");
    logger.notice("This is a notice message");
    logger.alert("This is an alert message");
    logger.critical("This is a critical message");

    logfile.close();  // Close the file stream properly
    return 0;
}

