// Extract region of interest (ROI) data for a specific batch index
Eigen::MatrixXf select_batch_rois(int sample_id, Eigen::MatrixXf ground_truth, Eigen::MatrixXf proposals) {
    // Determine how many ground truth boxes belong to the specified sample
    auto sample_gt_count = (ground_truth.col(0).array() == static_cast<float>(sample_id)).count();

    // Allocate matrix for ground truth boxes corresponding to this sample
    Eigen::MatrixXf sample_gt_boxes(sample_gt_count, ground_truth.cols());
    for (Eigen::Index idx = 0, valid_idx = 0; idx < ground_truth.rows(); ++idx) {
        if (static_cast<int>(ground_truth(idx, 0)) == sample_id)
            sample_gt_boxes.row(valid_idx++) = ground_truth.row(idx);
    }

    // Determine how many proposals belong to the specified sample
    auto sample_proposal_count = (proposals.col(0).array() == static_cast<float>(sample_id)).count();

    // Allocate matrix for proposals corresponding to this sample (excluding batch index column)
    Eigen::MatrixXf sample_proposals(sample_proposal_count, proposals.cols() - 1);
    for (Eigen::Index idx = 0, valid_idx = 0; idx < proposals.rows(); ++idx) {
        if (static_cast<int>(proposals(idx, 0)) == sample_id)
            sample_proposals.row(valid_idx++) = proposals.row(idx).rightCols(4);
    }

    return sample_proposals;
}

