// Template class to convert Python callable results to C++ type T
template <typename U>
class python_converter {
public:
    python_converter(PyObject* input_obj)
        : py_obj(input_obj)
    {
        // Initialization logic
    }

    U execute_conversion() {
        if (!PyCallable_Check(py_obj)) {
            PyErr_SetString(PyExc_TypeError, "Input must be a callable object");
            throw error_already_set();
        }

        PyObject* call_result = PyObject_CallObject(py_obj, nullptr);
        if (call_result == nullptr) {
            throw error_already_set();
        }

        if (!PyArg_Parse(call_result, "U", &stored_value)) {
            PyErr_SetString(PyExc_TypeError, "Conversion from Python object to C++ object failed");
            throw error_already_set();
        }

        Py_DECREF(call_result);
        return stored_value;
    }

private:
    PyObject* py_obj;
    U stored_value;
};

