    char getCharAt(size_t pos) const {
        if (pos < getSize()) {
            return data_[pos];
        } else {
            // Handle invalid position
            return '\0';
        }
    }

    // Method to append another string to the current text and produce a new object
    TextWrapper append(const char* text) const {
        size_t combinedSize = getSize() + strlen(text);
        char* tempBuffer = new char[combinedSize + 1];
        strcpy(tempBuffer, data_);
        strcat(tempBuffer, text);
        TextWrapper output(tempBuffer);
        delete[] tempBuffer;
        return output;
    }
