// Compute the intersection point between a ray and a plane
Vector3 FindRayPlaneIntersection(const Ray& inputRay, const Vector3& planeAnchor, const Vector3& planeOrientation) {
    float denom = DotProduct(planeOrientation, inputRay.direction);

    // Determine if the ray is parallel to the plane
    if (std::abs(denom) < TOLERANCE) {
        // Ray runs parallel to the plane — no intersection occurs
        return NoIntersection; // Replace NoIntersection with appropriate representation
    }

    Vector3 originToPlane = planeAnchor - inputRay.startPoint;
    float param = DotProduct(originToPlane, planeOrientation) / denom;

    // Verify whether the intersection lies in the forward direction of the ray
    if (param < 0) {
        // Intersection occurs behind the ray's starting point — invalid
        return NoIntersection; // Replace NoIntersection with appropriate representation
    }

    // Derive the actual intersection coordinates
    Vector3 hitPoint = inputRay.startPoint + inputRay.direction * param;
    return hitPoint;
}

