// Function to add a new key-value pair to an SSTable at a specified level
void addToSSTable(int level, const std::string& dir, const std::string& key, const std::string& value, 
                  std::vector<std::vector<ssTable>>& levelArray, std::vector<int>& labelCounter, 
                  uint64_t& timestamp, uint64_t& sizeCounter, 
                  std::vector<std::pair<std::string, std::string>>& buffer) {
    // Construct the SSTable file path using the current label counter
    std::string filePath = dir + '/' + std::to_string(labelCounter[level]) + ".sst";

    // Create and add a new SSTable instance to the target level
    levelArray[level].emplace_back(ssTable::genTable(filePath, timestamp, buffer));

    // Increment the label counter for this level
    labelCounter[level]++;

    // Reset the temporary buffer and counters
    buffer.clear();
    timestamp = 0;
    sizeCounter = 0;

    // Insert the new key-value pair into the buffer
    buffer.emplace_back(key, value);

    // Update the size estimate: include value size plus metadata overhead per entry
    sizeCounter += value.size() + sizeof(uint64_t) + sizeof(uint32_t);

    // Set initial timestamp if not already set
    if (timestamp == 0) {
        timestamp = getCurrentTimeStamp();  // Retrieve current system timestamp
    }

    // Sort entries in the buffer lexicographically by key
    std::sort(buffer.begin(), buffer.end(), [](const std::pair<std::string, std::string>& x, 
                                                const std::pair<std::string, std::string>& y) {
        return x.first < y.first;
    });

    // Add all sorted entries to the most recently created SSTable
    for (const auto& entry : buffer) {
        levelArray[level].back().addKeyValuePair(entry.first, entry.second);
    }

    // Finalize the SSTable with updated timestamp and size metadata
    levelArray[level].back().updateMetadata(timestamp, sizeCounter);
}

