typedef RGBAColor<unsigned char> RGBA8; // Represents 8-bit RGBA color
using ColorRGBA = RGBA8;
constexpr ColorRGBA WHITE{255, 255, 255, 255}; // Represents white color
constexpr ColorRGBA BLUE{0, 0, 255, 255};       // Represents blue color

ColorRGBA interpolateColors(const ColorRGBA& first, const ColorRGBA& second, float ratio) {
    // Linear interpolation for RGB components
    unsigned char interpolated_r = static_cast<unsigned char>((1.0f - ratio) * first.r + ratio * second.r);
    unsigned char interpolated_g = static_cast<unsigned char>((1.0f - ratio) * first.g + ratio * second.g);
    unsigned char interpolated_b = static_cast<unsigned char>((1.0f - ratio) * first.b + ratio * second.b);

    // Preserve alpha from the first color
    return ColorRGBA(interpolated_r, interpolated_g, interpolated_b, first.a);
}

