// Generate a vector of integer pairs based on parameters A and B
std::vector<std::pair<int, int>> manipulateVector(int A, int B) {
    std::vector<std::pair<int, int>> result;
    int K = 1;

    // Process while A is non-negative
    while (A >= 0) {
        A--;
        result.push_back({ ++K, ++K });
    }

    // Add initial pair with first element as 1
    result.push_back({ 1, ++K });

    // Return empty if exceeds required size
    if (result.size() > B) return {};

    // Extend to desired size B
    while (result.size() < B) {
        result.push_back({ ++K, ++K });
    }

    return result;
}

#include <vector>
using namespace std;

// Recursively explore all connected land cells in 8 directions
void exploreRegion(vector<vector<char>>& matrix, int row, int col) {
    // Check boundaries and if current cell is unvisited land
    if (row < 0 || row >= matrix.size() || col < 0 || col >= matrix[0].size() || matrix[row][col] != 'X') {
        return;
    }

    matrix[row][col] = 'V';  // Mark as visited

    // Explore all 8 neighboring cells (including diagonals)
    exploreRegion(matrix, row + 1, col);     // Down
    exploreRegion(matrix, row - 1, col);     // Up
    exploreRegion(matrix, row, col + 1);     // Right
    exploreRegion(matrix, row, col - 1);     // Left
    exploreRegion(matrix, row + 1, col + 1); // Down-Right diagonal
    exploreRegion(matrix, row - 1, col - 1); // Up-Left diagonal
    exploreRegion(matrix, row + 1, col - 1); // Down-Left diagonal
    exploreRegion(matrix, row - 1, col + 1); // Up-Right diagonal
}

// Count the number of separate land regions in the grid
int countIslands(vector<vector<char>>& matrix) {
    int islands = 0;
    for (int row = 0; row < matrix.size(); row++) {
        for (int col = 0; col < matrix[0].size(); col++) {
            if (matrix[row][col] == 'X') {  // Found unvisited land
                islands++;
                exploreRegion(matrix, row, col);
            }
        }
    }
    return islands;
}

