// Determine if there's a valid path in the maze from top-left to bottom-right
bool checkPath(int rows, int cols, char grid[10][10]) {
    bool visited[10][10] = {false};  // Track reachable cells

    // Starting cell is reachable only if it's open ('0')
    visited[0][0] = (grid[0][0] == '0');

    // Fill the visited array using dynamic programming approach
    for (int i = 0; i < rows; i++) {
        for (int j = 0; j < cols; j++) {
            if (grid[i][j] == '0') {
                // Check if we can reach current cell from top
                if (i > 0) visited[i][j] = visited[i][j] || visited[i - 1][j];
                // Check if we can reach current cell from left
                if (j > 0) visited[i][j] = visited[i][j] || visited[i][j - 1];
            }
        }
    }

    return visited[rows - 1][cols - 1];  // Return whether destination is reachable
}

int main() {
    int m = 4, n = 4;
    char maze[10][10] = {
        "0000",
        "00X0",
        "0000",
        "0X00"
    };

    cout << (checkPath(m, n, maze) ? "Path exists" : "No path exists") << endl;
    return 0;
}

