enum class DataType { None, Int, Double, Text, Bool };

class Converter {
public:
    static DataType parse(const std::string& value) {
        static const std::unordered_map<std::string, DataType> mapping = {
            {"None", DataType::None},
            {"Int", DataType::Int},
            {"Double", DataType::Double},
            {"Text", DataType::Text},
            {"Bool", DataType::Bool}
        };
        auto iter = mapping.find(value);
        if (iter != mapping.end()) {
            return iter->second;
        } else {
            return DataType::None;
        }
    }
};

int main() {
    // Demonstrate the DataType::parse function
    std::cout << "DataType for 'Unknown': " << static_cast<int>(Converter::parse("Unknown")) << std::endl; // Output: 0 (DataType::None)
    std::cout << "DataType for 'Int': " << static_cast<int>(Converter::parse("Int")) << std::endl; // Output: 1 (DataType::Int)
    std::cout << "DataType for 'Double': " << static_cast<int>(Converter::parse("Double")) << std::endl; // Output: 2 (DataType::Double)
    std::cout << "DataType for 'Text': " << static_cast<int>(Converter::parse("Text")) << std::endl; // Output: 3 (DataType::Text)
    std::cout << "DataType for 'Bool': " << static_cast<int>(Converter::parse("Bool")) << std::endl; // Output: 4 (DataType::Bool)
    return 0;
}

