namespace internal {
    template <typename Callable, typename... Parameters>
    inline auto execute_invoke(Callable&& func, Parameters&&... params)
      -> std::enable_if_t<!std::is_member_pointer_v<std::decay_t<Callable>>,
                          decltype(std::forward<Callable>(func)(std::forward<Parameters>(params)...))> {
        return std::forward<Callable>(func)(std::forward<Parameters>(params)...);
    }
} // namespace internal

template <typename FunctionType, typename... ArgumentTypes>
std::result_of_t<FunctionType && (ArgumentTypes && ...)> custom_invoke(FunctionType&& func, ArgumentTypes&&... args) {
    return internal::execute_invoke(std::forward<FunctionType>(func), std::forward<ArgumentTypes>(args)...);
}

