void analyzeIR(const std::string& inputFile, const std::string& kernelName, bool includeIR) {
    llvm::LLVMContext llvmContext;
    llvm::SMDiagnostic diagnostic;
    std::unique_ptr<llvm::Module> module = llvm::parseIRFile(inputFile, diagnostic, llvmContext);
    if (!module) {
        diagnostic.print("irtoopencl", llvm::errs());
        throw std::runtime_error("failed to parse IR");
    }
    KernelDumper dumper(module.get(), kernelName);
    if (includeIR) {
        dumper.addIRToCl();
    }
}

