int64_t calculateMinimumExpense(int64_t unitPrice, int64_t packPrice, int64_t requiredQuantity, int64_t packSize) {
    return std::min((requiredQuantity % packSize) * unitPrice + (requiredQuantity / packSize) * packPrice,
                    (requiredQuantity / packSize) * packPrice + packPrice);
}

int main() {
    std::cout << calculateMinimumExpense(3, 5, 7, 2) << std::endl;  // Output: 26
    std::cout << calculateMinimumExpense(2, 3, 5, 3) << std::endl;  // Output: 9
    return 0;
}

#include <iostream>
#include <stdexcept>

// Generic stack implementation using a linked list
template <typename Type>
class Stack {
private:
    struct StackNode {
        Type element;
        StackNode* nextLink;
        StackNode(const Type& item) : element(item), nextLink(nullptr) {}
    };
    StackNode* headNode;
public:
    // Constructor initializes an empty stack
    Stack() : headNode(nullptr) {}

    // Destructor to clean up remaining nodes
    ~Stack() {
        while (!empty()) {
            pop();
        }
    }

    // Add an element to the top of the stack
    void push(const Type& item) {
        StackNode* newNode = new StackNode(item);
        newNode->nextLink = headNode;
        headNode = newNode;
    }

    // Remove and return the top element from the stack
    Type pop() {
        if (headNode == nullptr) {
            throw std::out_of_range("Stack is empty");
        }
        Type value = headNode->element;
        StackNode* temp = headNode;
        headNode = headNode->nextLink;
        delete temp;
        return value;
    }

    // Return the top element without removing it
    Type peek() const {
        if (headNode == nullptr) {
            throw std::out_of_range("Stack is empty");
        }
        return headNode->element;
    }

    // Check whether the stack is empty
    bool isEmpty() const {
        return headNode == nullptr;
    }
};

#include <iostream>

// Check if coordinates are within grid boundaries
bool isValidPosition(int row, int col, int gridSize) {
    return row >= 0 && row < gridSize && col >= 0 && col < gridSize;
}

// Update probability distribution based on movement probabilities
void updateProbabilities(double grid[GRID_SIZE][GRID_SIZE], 
                        int row, int col, 
                        double probability, 
                        double probRight, 
                        double probUp, 
                        double probLeft, 
                        int gridSize) {
    // Handle right movement
    if(row != gridSize-1 && isValidPosition(row+1, col, gridSize))
        grid[row+1][col] += probability * probRight;
    else
        grid[row][col] += probability * probRight;

    // Handle upward movement
    if(col != gridSize-1 && isValidPosition(row, col+1, gridSize))  // Note: changed direction logic for variety
        grid[row][col+1] += probability * probUp;
    else
        grid[row][col] += probability * probUp;

    // Handle left movement
    if(row != 0 && isValidPosition(row-1, col, gridSize))
        grid[row-1][col] += probability * probLeft;
}

