#include <unordered_map>

class AbstractTimer {
public:
    virtual ~AbstractTimer() {}
    virtual void scheduleTimer(int delay, std::function<void()> handler) = 0;
    virtual void tick(int steps) = 0;
    virtual std::vector<std::function<void()>> retrieveExpiredCallbacks() = 0;
};

class HierarchicalWheelTimer : public AbstractTimer {
private:
    // Storage for timers organized by wheel positions
    std::vector<std::unordered_map<int, std::function<void()>>> timerBuckets;
    int currentBucketIndex;

public:
    HierarchicalWheelTimer() : timerBuckets(5), currentBucketIndex(0) {}

    void scheduleTimer(int delay, std::function<void()> handler) override {
        int targetBucket = (currentBucketIndex + delay) % timerBuckets.size();
        timerBuckets[targetBucket][delay] = handler;
    }

    void tick(int steps) override {
        currentBucketIndex = (currentBucketIndex + steps) % timerBuckets.size();
    }

    std::vector<std::function<void()>> retrieveExpiredCallbacks() override {
        std::vector<std::function<void()>> expiredHandlers;

        for (const auto& entry : timerBuckets[currentBucketIndex]) {
            expiredHandlers.push_back(entry.second);
        }

        timerBuckets[currentBucketIndex].clear();
        return expiredHandlers;
    }
};

std::shared_ptr<AbstractTimer> instantiateTimer() {
    return std::shared_ptr<AbstractTimer>(new HierarchicalWheelTimer());
}

int main() {
    std::shared_ptr<AbstractTimer> timerInstance = instantiateTimer();

    timerInstance->scheduleTimer(10, [](){ std::cout << "First timer triggered" << std::endl; });
    timerInstance->scheduleTimer(5, [](){ std::cout << "Second timer triggered" << std::endl; });

    timerInstance->tick(5);

    std::vector<std::function<void()>> readyCallbacks = timerInstance->retrieveExpiredCallbacks();
    for (const auto& func : readyCallbacks) {
        func();
    }

    return 0;
}

#include <iostream>

class ValueProcessor {
private:
    int internalValue;
public:
    ValueProcessor() : internalValue(0) {}

    void compute(int& num) & {
        internalValue += num;
    }

    void compute(int&& num) && {
        internalValue -= num;
    }

    int getValue() const {
        return internalValue;
    }
};

int main() {
    ValueProcessor instance1;
    instance1.compute(7);  // Invokes compute(int& num) & and adds 7 to internalValue
    std::cout << "Value after lvalue computation: " << instance1.getValue() << std::endl;

    ValueProcessor instance2;
    instance2.compute(4);  // Invokes compute(int&& num) && and subtracts 4 from internalValue
    std::cout << "Value after rvalue computation: " << instance2.getValue() << std::endl;

    return 0;
}

