// Initialize a Unix socket address structure using provided family and path
void setupUnixSocketAddress(int domain, const std::string& path, struct sockaddr_storage& storage) {
    struct sockaddr_un unix_addr;
    unix_addr.sun_family = domain;
    // Zero out the path buffer before copying
    memset(unix_addr.sun_path, 0, sizeof(unix_addr.sun_path));
    // Safely copy the path string into the address structure
    strncpy(unix_addr.sun_path, path.c_str(), sizeof(unix_addr.sun_path) - 1);
    // Transfer the configured Unix socket address to the generic storage structure
    memmove(&storage, &unix_addr, sizeof(unix_addr));
}

#include <vector>
#include <string>
#include <algorithm>

class Solution
{
public:
    std::vector<int> shortestToChar(std::string &inputStr, char targetChar)
    {
        std::vector<int> distances(inputStr.length(), inputStr.length());  // Initialize with maximum possible distance
        int lastPosition = -inputStr.length();  // Track the most recent occurrence of targetChar

        // Left-to-right pass: compute distances from left occurrences
        for (int index = 0; index < inputStr.length(); ++index)
        {
            if (inputStr[index] == targetChar)
                lastPosition = index;  // Update position of latest target character
            distances[index] = std::min(distances[index], std::abs(index - lastPosition));
        }

        // Right-to-left pass: compute distances from right occurrences
        for (int index = inputStr.length() - 1; index >= 0; --index)
        {
            if (inputStr[index] == targetChar)
                lastPosition = index;  // Update position of latest target character
            distances[index] = std::min(distances[index], std::abs(index - lastPosition));
        }

        return distances;
    }
};

