// Compute the mean pixel intensity for a given image plane
double computeMeanIntensity(const misaxx::ome::misa_ome_tiff_cache &image_cache, int slice_id) {
    // Extract the planes location metadata from the cache
    misaxx::ome::misa_ome_planes_location plane_info = image_cache.get_attachment<misaxx::ome::misa_ome_planes_location>();

    // Validate the provided slice index
    if (slice_id < 0 || slice_id >= static_cast<int>(plane_info.size())) {
        throw std::out_of_range("Slice index out of bounds");
    }

    // Access the pixel matrix for the requested slice
    const cv::Mat &slice_pixels = plane_info[slice_id].get_plane();

    // Accumulate all pixel values
    double cumulative_intensity = 0.0;
    for (int y = 0; y < slice_pixels.rows; ++y) {
        for (int x = 0; x < slice_pixels.cols; ++x) {
            cumulative_intensity += slice_pixels.at<ushort>(y, x);  // Pixel data stored as unsigned short
        }
    }

    // Normalize by total number of pixels to obtain mean
    double pixel_count = static_cast<double>(slice_pixels.rows * slice_pixels.cols);
    double mean_intensity = cumulative_intensity / pixel_count;

    return mean_intensity;
}

