// Compute the fitness score for a given set of outputs
float computeScore(const std::vector<float>& results) {
    float score = 0.0f;

    // Accumulate penalty: subtract (1 - result) for each result
    for (float res : results) {
        score -= (1.0f - res);
    }

    // Evaluate network on input {2, 2} and penalize accordingly
    float outputVal = network->compute({2, 2})->result[0]->data;
    score -= outputVal;

    // Apply structural constraint check
    if (network->output[0]->signalCount > 0 && 
        network->output[0]->signalCount != network->output[0]->inputCount) {
        network->printDetails();
        int stepCounter = 0;  // Reset counter
        stepCounter++;        // Advance counter by one
    }

    // Add regularization term based on hidden layer size
    score += -activationFunction(network->hidden.size()) + 1.0f;

    return score;
}

