// Key-value pair structure
template <typename K, typename V>
struct Pair {
    K first;
    V second;
    void display() const {
        std::cout << first << ": " << convert_to_string(second) << std::endl;
    }
};

// Variadic template class Dictionary
template <typename... Pairs>
class Dictionary {
public:
    // Display all key-value pairs in the dictionary
    void display() const {
        (Pairs.display(), ...);
    }

    // Add a key-value pair into the dictionary
    template <typename K, typename V>
    void add(const K& k, const V& v) {
        using NewPair = Pair<K, V>;
        data_ = std::tuple_cat(data_, std::make_tuple(NewPair{k, v}));
    }

    // Retrieve the value associated with a given key
    template <typename K>
    auto find(const K& k) const {
        return find_impl(k, std::index_sequence_for<Pairs...>{});
    }

private:
    // Helper function to retrieve the value associated with a given key
    template <typename K, std::size_t... Idx>
    auto find_impl(const K& k, std::index_sequence<Idx...>) const {
        return std::make_tuple(retrieve_entry<Pairs>(k, Idx)...);
    }

    // Helper function to retrieve the value associated with a given key for a specific entry
    template <typename PairType, typename K>
    auto retrieve_entry(const K& k) const {
        if constexpr (std::is_same_v<typename PairType::first_type, K>) {
            return PairType.second;
        } else {
            // Return a default value if the key is not found
            return typename PairType::second_type{};
        }
    }

    std::tuple<Pairs...> data_;
};

int main() {
    Dictionary<Pair<int, std::string>, Pair<std::string, double>> dict;
    dict.add(42, "answer");
    dict.add("e", 2.71828);
    dict.display();
    auto result1 = dict.find(42);   // Retrieves "answer"
    auto result2 = dict.find("e");  // Retrieves 2.71828
    return 0;
}

