// Determine if enough valid contours are present based on area and aspect ratio criteria
bool CheckContours(const std::vector<std::vector<cv::Point>>& shapes) {
    int acceptableShapes = 0;

    for (const auto& shape : shapes) {
        double regionArea = cv::contourArea(shape);

        // Verify the area falls within acceptable bounds
        if (regionArea > AREA_LOWER_LIMIT && regionArea < AREA_UPPER_LIMIT) {
            // Compute the rectangular boundary of the contour
            cv::Rect shapeBounds = cv::boundingRect(shape);
            double widthToHeight = static_cast<double>(shapeBounds.width) / shapeBounds.height;

            // Confirm the shape's proportions match expected dimensions
            if (widthToHeight >= RATIO_MIN && widthToHeight <= RATIO_MAX) {
                acceptableShapes++;
            }
        }
    }

    // Accept only if sufficient qualifying shapes are detected
    return acceptableShapes > REQUIRED_SHAPES_COUNT;
}

