template <typename T>
class ConfigOption {
public:
    ConfigOption(const std::string& key, const T& initial_value) : key_name(key), current_value(initial_value) {}

    T retrieve() const {
        std::lock_guard<std::mutex> guard(mtx);
        return current_value;
    }

    void update(const T& new_value) {
        std::lock_guard<std::mutex> guard(mtx);
        current_value = new_value;
    }

