#include <vector>

// Compute the mean waiting duration for a collection of tasks
float computeMeanWaitingDuration(const std::vector<std::pair<int, int>>& tasks) {
    int count = tasks.size();
    int accumulatedWait = 0;
    int currentTick = 0;

    for (const auto& task : tasks) {
        int arrival = task.first;
        int duration = task.second;

        // Determine wait period for this task
        int wait = std::max(0, currentTick - arrival);
        accumulatedWait += wait;

        // Advance time by processing this task
        currentTick += duration;

        // Adjust if task arrived after previous processing finished
        if (arrival > currentTick) {
            currentTick = arrival + duration;
        }
    }

    // Derive average waiting duration
    float meanWaitingDuration = static_cast<float>(accumulatedWait) / count;
    return meanWaitingDuration;
}

