class NotImplementedYetException : public std::exception {
private:
    std::string methodName;
    int statusCode;
    std::string details;
public:
    NotImplementedYetException(const std::string& funcName)
        : methodName(funcName), statusCode(0), details("") {}
    NotImplementedYetException(const std::string& funcName, int errCode)
        : methodName(funcName), statusCode(errCode), details("") {}
    NotImplementedYetException(const std::string& funcName, int errCode, const std::string& msg)
        : methodName(funcName), statusCode(errCode), details(msg) {}
    const char* what() const noexcept override {
        std::stringstream ss;
        ss << "Method '" << methodName << "' is not implemented";
        if (statusCode != 0) {
            ss << " (Status code: " << statusCode << ")";
        }
        if (!details.empty()) {
            ss << ": " << details;
        }
        return ss.str().c_str();
    }
};

// Verification function to ensure the behavior of NotImplementedYetException
void verifyNotImplementedYetException() {
    try {
        throw NotImplementedYetException("unimplemented_method");
    } catch (const NotImplementedYetException& e) {
        // Confirm the exception message
        assert(std::string(e.what()) == "Method 'unimplemented_method' is not implemented");
    }
    try {
        throw NotImplementedYetException("sample_func", 789);
    } catch (const NotImplementedYetException& e) {
        // Confirm the exception message
        assert(std::string(e.what()) == "Method 'sample_func' is not implemented (Status code: 789)");
    }
    try {
        throw NotImplementedYetException("sample_func", 101, "Validate error description");
    } catch (const NotImplementedYetException& e) {
        // Confirm the exception message
        assert(std::string(e.what()) == "Method 'sample_func' is not implemented (Status code: 101): Validate error description");
    }
}

