    }
};

// Function to collect hardware device identifiers via WMI
void FetchHardwareIDs(std::vector<std::string>& outputList) {
    HRESULT result;

    // Initialize COM runtime
    result = CoInitializeEx(0, COINIT_MULTITHREADED);
    if (FAILED(result)) {
        ErrorLogger::Log("COM initialization", std::to_string(result));
        return;
    }

    // Configure COM security
    result = CoInitializeSecurity(
        NULL,
        -1,
        NULL,
        NULL,
        RPC_C_AUTHN_LEVEL_DEFAULT,
        RPC_C_IMP_LEVEL_IMPERSONATE,
        NULL,
        EOAC_NONE,
        NULL
    );
    if (FAILED(result)) {
        CoUninitialize();
        ErrorLogger::Log("COM security setup", std::to_string(result));
        return;
    }

    // Create WMI locator instance
    IWbemLocator* wmiLocator = NULL;
    result = CoCreateInstance(
        CLSID_WbemLocator,
        0,
        CLSCTX_INPROC_SERVER,
        IID_IWbemLocator,
        reinterpret_cast<LPVOID*>(&wmiLocator)
    );
    if (FAILED(result)) {
        CoUninitialize();
        ErrorLogger::Log("WMI locator creation", std::to_string(result));
        return;
    }

    // Connect to WMI namespace
    IWbemServices* wmiService = NULL;
    result = wmiLocator->ConnectServer(
        _bstr_t(L"ROOT\\CIMV2"),
        NULL,
        NULL,
        0,
        NULL,
        0,
        0,
        &wmiService
    );
    wmiLocator->Release();  // Release after use
    if (FAILED(result)) {
        CoUninitialize();
        ErrorLogger::Log("WMI connection", std::to_string(result));
        return;
    }

    // Apply security settings on the service proxy
    result = CoSetProxyBlanket(
        wmiService,
        RPC_C_AUTHN_WINNT,
        RPC_C_AUTHZ_NONE,
        NULL,
        RPC_C_AUTHN_LEVEL_CALL,
        RPC_C_IMP_LEVEL_IMPERSONATE,
        NULL,
        EOAC_NONE
    );
    if (FAILED(result)) {
        wmiService->Release();
        CoUninitialize();
        ErrorLogger::Log("Proxy security", std::to_string(result));
        return;
    }

    // Execute WMI query
    IEnumWbemClassObject* enumResult = NULL;
    result = wmiService->ExecQuery(
        bstr_t("WQL"),
        bstr_t("SELECT * FROM Win32_PnPEntity"),
        WBEM_FLAG_FORWARD_ONLY | WBEM_FLAG_RETURN_IMMEDIATELY,
        NULL,
        &enumResult
    );
    if (FAILED(result)) {
        wmiService->Release();
        CoUninitialize();
        ErrorLogger::Log("WMI query execution", std::to_string(result));
        return;
    }

    // Process results
    IWbemClassObject* currentItem = NULL;
    ULONG fetchedCount = 0;
    while (enumResult) {
        result = enumResult->Next(WBEM_INFINITE, 1, &currentItem, &fetchedCount);
        if (fetchedCount == 0) break;

        VARIANT propertyValue;
        result = currentItem->Get(L"DeviceID", 0, &propertyValue, 0, 0);
        if (SUCCEEDED(result)) {
            outputList.push_back(std::string(_bstr_t(propertyValue.bstrVal)));
            VariantClear(&propertyValue);
        }
        currentItem->Release();
    }

    // Cleanup resources
    wmiService->Release();
    enumResult->Release();
    CoUninitialize();
}

