// Compute the greatest common divisor using Euclidean method
int computeGCD(int a, int b) {
    while (b != 0) {
        int temp = b;
        b = a % b;
        a = temp;
    }
    return a;
}

// Compute the least common multiple using the GCD
int computeLCM(int a, int b) {
    return a * b / computeGCD(a, b);
}

int main() {
