    std::cout << "GCD of 12 and 18: " << computeGCD(12, 18) << std::endl; // Output: 6
    std::cout << "LCM of 12 and 18: " << computeLCM(12, 18) << std::endl; // Output: 36
    std::cout << "GCD of 15 and 25: " << computeGCD(15, 25) << std::endl; // Output: 5
    std::cout << "LCM of 15 and 25: " << computeLCM(15, 25) << std::endl; // Output: 75
    std::cout << "GCD of 17 and 31: " << computeGCD(17, 31) << std::endl; // Output: 1
    std::cout << "LCM of 17 and 31: " << computeLCM(17, 31) << std::endl; // Output: 527
