class InvalidDateFormatException : public std::exception {
public:
    const char* what() const noexcept override {
        return "Invalid date format";
    }
};

class InvalidDateTimeValueException : public std::exception {
public:
    const char* what() const noexcept override {
        return "Invalid date or time value";
    }
};

class Timestamp {
private:
    int y, m, d, h, mi, s;
public:
    Timestamp(const std::string& input) {
        std::regex pattern(R"((\d{4})-(\d{2})-(\d{2}) (\d{2}):(\d{2}):(\d{2}))");
        std::smatch result;
        if (!std::regex_match(input, result, pattern)) {
            throw InvalidDateFormatException();
        }
        y = std::stoi(result[1]);
        m = std::stoi(result[2]);
        d = std::stoi(result[3]);
        h = std::stoi(result[4]);
        mi = std::stoi(result[5]);
        s = std::stoi(result[6]);
        if (!checkDate(y, m, d) || !checkTime(h, mi, s)) {
            throw InvalidDateTimeValueException();
        }
    }

    void check() {
        if (!checkDate(y, m, d) || !checkTime(h, mi, s)) {
            throw InvalidDateTimeValueException();
        }
    }

private:
    bool leapYear(int year) {
        return (year % 4 == 0 && year % 100 != 0) || (year % 400 == 0);
    }

    bool checkDate(int year, int month, int day) {
        if (year < 1 || month < 1 || month > 12 || day < 1) {
            return false;
        }
        static const int daysPerMonth[] = {0, 31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31};
        if (month == 2 && leapYear(year)) {
            return day <= 29;
        } else {
            return day <= daysPerMonth[month];
        }
    }

    bool checkTime(int hour, int minute, int second) {
        return (hour >= 0 && hour < 24) && (minute >= 0 && minute < 60) && (second >= 0 && second < 60);
    }
};

int main() {
    try {
