#include <vector>

// Perform parallel multiway merge on multiple sorted sequences using STXXL
std::vector<int> parallelMultiwayMerge(const std::vector<std::vector<int>>& sortedSequences) {
    std::vector<int> finalResult;

    // Initialize external memory vectors for processing
    stxxl::vector<int> externalInput;

    // Insert all input sequences into the external vector
    for (const auto& sequence : sortedSequences) {
        externalInput.insert(externalInput.end(), sequence.begin(), sequence.end());
    }

    stxxl::vector<int> externalResult;

    // Execute parallel multiway merge algorithm
    stxxl::multiway_merge(externalInput.begin(), externalInput.end(), 
                         externalResult.begin(), sortedSequences.size());

    // Transfer results from external memory to standard vector
    finalResult.reserve(externalResult.size());
    for (const auto& element : externalResult) {
        finalResult.push_back(element);
    }

    return finalResult;
}

