class SymbolManager {
private:
  std::unordered_map<std::string, std::unordered_map<std::string, bool>> observed;
  std::unordered_map<std::string, std::unordered_map<std::string, bool>> referenced;

public:
  void observe(const DeclarationEntry& entry) {
    for (const auto& scope : entry.scopes) {
      observed[scope.second][entry.identifier] = true;
    }
  }

  void reference(const DeclarationEntry& entry) {
    for (const auto& scope : entry.scopes) {
      referenced[scope.second][entry.identifier] = true;
    }
  }

  bool wasObserved(const std::string& scope, const std::string& name) {
    return observed[scope][name];
  }

  bool wasReferenced(const std::string& scope, const std::string& name) {
    return referenced[scope][name];
  }
};

int main() {
  SymbolManager manager;

  DeclarationEntry decl1("Y2", TokenType::Var, "SourceFile.h",
                        {{ScopeType::Module, ""}});
  manager.observe(decl1);
  manager.reference(decl1);

  DeclarationEntry decl2("Y3", TokenType::Var, "SourceFile.h",
                        {{ScopeType::Module, ""},
                         {ScopeType::Module, ""}});
  manager.observe(decl2);
  manager.reference(decl2);

  // Check symbol status
  std::cout << "Declaration Y2 observed and referenced in global scope: " 
            << manager.wasObserved("", "Y2") << " " 
            << manager.wasReferenced("", "Y2") << std::endl;

  std::cout << "Declaration Y3 observed and referenced in global scope: " 
            << manager.wasObserved("", "Y3") << " " 
