// Node structure for storing item data
class Item {
public:
    int itemId;
    Item* Next;

    Item() : itemId(0), Next(nullptr) {}
};

// Container class managing a linked list of items
class ItemList {
private:
    Item* mpStart;
    Item* mpCurrent;

public:
    ItemList() : mpStart(nullptr), mpCurrent(nullptr) {
        // Constructor initializes empty list
    }

    void InsertItem(int id) {
        // Insert new item at the beginning of the list
        Item* newNode = new Item();
        newNode->itemId = id;
        newNode->Next = mpStart;
        mpStart = newNode;
    }

    Item* GetNext() {
        if (mpCurrent == nullptr) {
            mpCurrent = mpStart;
        } else {
            mpCurrent = mpCurrent->Next;
        }
        return mpCurrent;
    }

    bool HasMoreItems() {
        // Check if there are remaining items in the list
        Item* temp = (mpCurrent == nullptr) ? mpStart : mpCurrent->Next;
        return temp != nullptr;
    }
};

// Iterator class for traversing the item list
class CustomIterator {
private:
    ItemList* mpContainer;
    Item* mpCurrentPosition;

public:
    CustomIterator(ItemList* pContainer) : mpContainer(pContainer), mpCurrentPosition(nullptr) {
        // Initialize iterator with container reference
    }

    Item* Advance() {
        // Move to next item and return it
        return mpContainer->GetNext();
    }

    bool Remaining() {
        // Determine if more items exist
        return mpContainer->HasMoreItems();
    }
};

int main() {
    ItemList* pContainer = new ItemList();
    pContainer->InsertItem(10);
    pContainer->InsertItem(20);
    pContainer->InsertItem(30);

    CustomIterator iter(pContainer);

    while (iter.Remaining()) {
        Item* pItem = iter.Advance();
        std::cout << "Processing item with id: " << pItem->itemId << std::endl;
    }

    delete pContainer;
    return 0;
}

