// Determine the memory footprint of a specific process
SIZE_T GetProcessMemoryConsumption(DWORD pid) {
    HANDLE hProc = OpenProcess(PROCESS_QUERY_INFORMATION | PROCESS_VM_READ, FALSE, pid);
    if (hProc == NULL) {
        // Failed to open the process
        return 0;
    }
    PROCESS_MEMORY_COUNTERS memCounters;
    if (GetProcessMemoryInfo(hProc, &memCounters, sizeof(memCounters))) {
        CloseHandle(hProc);
        return memCounters.WorkingSetSize;
    } else {
        // Failed to retrieve memory information
        CloseHandle(hProc);
        return 0;
    }
}

