// Define possible terrain categories
enum class Landscape { FOREST, RIVER, HILL, SAND }; // Alternative terrain types

// Generate a procedural map with specified parameters
void generateTerrainMap(int cols, int rows, float coverage, unsigned int seedValue, int categoryCount) {
    if (cols == 0 || rows == 0) {
        throw std::invalid_argument("Map size must be positive in both dimensions.");
    }
    if (coverage <= 0.0f || coverage > 1.0f) {
        throw std::invalid_argument("Coverage factor must be between 0 and 1 (exclusive of 0).");
    }

    std::mt19937 rng(seedValue); // Initialize random number generator
    std::uniform_real_distribution<float> distribution(0.0f, 1.0f);

    // Create 2D grid initialized to FOREST
    std::vector<std::vector<Landscape>> grid(rows, std::vector<Landscape>(cols, FOREST));

    for (int row = 0; row < rows; ++row) {
        for (int col = 0; col < cols; ++col) {
            float randomValue = distribution(rng);
            if (randomValue < coverage) {
                int selectedCategory = rand() % categoryCount;
                grid[row][col] = static_cast<Landscape>(selectedCategory);
            }
        }
    }

    // Display the resulting map
    for (int row = 0; row < rows; ++row) {
        for (int col = 0; col < cols; ++col) {
            std::cout << static_cast<int>(grid[row][col]) << " ";
        }
        std::cout << "\n";
    }
}

int main(int argumentCount, char **argumentVector) {
    try {
        generateTerrainMap(30, 20, 1.0f, 42, 4); // Test case with fixed seed and full coverage
    } catch (const std::invalid_argument &exception) {
        std::cerr << "Error: " << exception.what() << std::endl;
    }
    return 0;
}

#include <cmath>

class Coordinate {
private:
    double a, b;
public:
    Coordinate(double xVal, double yVal) : a(xVal), b(yVal) {}

    double getDistanceFrom(const Coordinate& otherPoint) {
        return std::sqrt(std::pow(otherPoint.a - a, 2) + std::pow(otherPoint.b - b, 2));
    }

    Coordinate getCenterWith(const Coordinate& otherPoint) {
        double centerX = (a + otherPoint.a) / 2.0;
        double centerY = (b + otherPoint.b) / 2.0;
        return Coordinate(centerX, centerY);
    }

    bool areOnSameLine(const Coordinate& point2, const Coordinate& point3) {
        return ((point2.b - b) * (point3.a - point2.a) == (point3.b - point2.b) * (point2.a - a));
    }
};

