    float Yaw;
    float Roll;
};

// Convert RotationData to a sequence of bytes
void ConvertToBytes(const RotationData& data, unsigned char* buffer)
{
    memcpy(buffer, &data, sizeof(RotationData));
}

// Reconstruct RotationData from a byte sequence
RotationData ConvertFromBytes(const unsigned char* buffer)
{
    RotationData result;
    memcpy(&result, buffer, sizeof(RotationData));
    return result;
}

