bool AckBitField::IsSetCorrespondingAckBit( PacketSN ackSN )
{
    uint32_t diff = 0;
    for ( ; RealtimeSrvHelper::SNGreaterThan(
        latestAckSN_, ackSN++ ); ++diff );
    assert( diff );
    uint32_t byteIndex = ( diff - 1 ) >> 3;
    uint32_t bitIndex = ( diff - 1 ) & 0x7;
    // Verify if the corresponding acknowledgment bit is set
    // Assuming bitArray is a member variable representing the bit field
