class FrequencyDistribution {
private:
    const double &lowerBound;
    const double &upperBound;
    const int &numSegments;
    double segmentWidth;
    std::vector<int> counts;

    int determineSegment(const double &value) {
        return static_cast<int>((value - lowerBound) / segmentWidth);
    }

public:
    FrequencyDistribution(const double &lb, const double &ub, const int &nSeg)
        : lowerBound(lb), upperBound(ub), numSegments(nSeg), counts(nSeg, 0) {
        segmentWidth = (upperBound - lowerBound) / numSegments;
    }

    void recordValue(const double &val) {
        int idx = determineSegment(val);
        if (idx >= 0 && idx < numSegments) {
            counts[idx]++;
        }
    }

    int getCount(const int &index) {
        if (index >= 0 && index < numSegments) {
            return counts[index];
        }
        return 0;
    }
};

int main() {
    FrequencyDistribution dist(0.0, 10.0, 5);
    dist.recordValue(2.5);
    dist.recordValue(7.8);
    dist.recordValue(11.0);

    std::cout << "Segment 2 frequency: " << dist.getCount(2) << std::endl;  // Output: Segment 2 frequency: 1
    std::cout << "Segment 4 frequency: " << dist.getCount(4) << std::endl;  // Output: Segment 4 frequency: 0

    return 0;
}

#include <glslang/Public/ShaderLang.h>
#include <SPIRV/GlslangToSpv.h>
#include <SPIRV/SpvTools.h>
#include <SPIRV/disassemble.h>

bool compileGLSLToSPIRV(const std::string& shaderSource, std::vector<uint32_t>& outputSpirv) {
    glslang::InitializeProcess();

    glslang::TShader vertexShader(EShLangVertex);
    const char* sourcePtr = shaderSource.c_str();
    vertexShader.setStrings(&sourcePtr, 1);

    if (!vertexShader.parse(&glslang::DefaultTBuiltInResource, 100, false, EShMsgDefault)) {
        KG_LOGE(LM_RENDER, "[Compile GLSL to SPIR-V] Shader Parsing Failed\n%s", vertexShader.getInfoLog());
        glslang::FinalizeProcess();
        return false;
    }

    std::unique_ptr<glslang::TProgram> linker(new glslang::TProgram());
    linker->addShader(&vertexShader);

    if (!linker->link(EShMsgDefault)) {
        KG_LOGE(LM_RENDER, "[Compile GLSL to SPIR-V] Program Linking Failed\n%s", linker->getInfoLog());
        glslang::FinalizeProcess();
        return false;
    }

    spv::SpvBuildLogger messageLogger;
    glslang::GlslangToSpv(*linker->getIntermediate(EShLangVertex), outputSpirv, &messageLogger);

    if (messageLogger.getAllMessages().length() > 0) {
        KG_LOGW(LM_RENDER, "[Compile GLSL to SPIR-V] SPIR-V Generation Messages\n%s", messageLogger.getAllMessages().c_str());
    }

    glslang::FinalizeProcess();
    return true;
}

