// Load a PNG image from an input stream and return a Bitmap object
Bitmap LoadPNG(std::istream& inputStream)
{
    // Read entire stream into a string buffer
    std::string dataBuffer((std::istreambuf_iterator<char>(inputStream)), std::istreambuf_iterator<char>());

    // Vector to hold the decoded pixel data
    std::vector<unsigned char> pixelData;

    // Variables to store image dimensions
    unsigned long imgWidth, imgHeight;

    // Decode the PNG data
    int decodeResult = decodePNG(pixelData, imgWidth, imgHeight, 
                                 reinterpret_cast<const unsigned char*>(dataBuffer.c_str()), 
                                 dataBuffer.size());

    // Check for decoding errors
    if (decodeResult != 0) {
        Log::Error("Failed to decode PNG: error code " + std::to_string(decodeResult));
        return Bitmap(); // Return default-constructed (empty) bitmap
    }

    // Create a new bitmap with the decoded dimensions
    Bitmap resultBitmap(imgWidth, imgHeight);

    // Process each pixel from the decoded data
    for (unsigned long row = 0; row < imgHeight; ++row) {
        for (unsigned long col = 0; col < imgWidth; ++col) {
            unsigned long index = (row * imgWidth + col) * 4;

            // Extract RGBA components and create color
            Color pixelColor(pixelData[index], 
                           pixelData[index + 1], 
                           pixelData[index + 2], 
                           pixelData[index + 3]);

            // Set the pixel in the bitmap
            resultBitmap.SetPixel(col, row, pixelColor);
        }
    }

    return resultBitmap;
}

