// Compute the 3D rotation matrix from Euler angles (roll, pitch, yaw)
Eigen::Matrix3d computeOrientationMatrix(double phi, double theta, double psi) {
    Eigen::Matrix3d Rx, Ry, Rz, result;

    // Rotation about x-axis (roll)
    Rx << 1, 0, 0,
          0, cos(phi), -sin(phi),
          0, sin(phi), cos(phi);

    // Rotation about y-axis (pitch)
    Ry << cos(theta), 0, sin(theta),
          0, 1, 0,
          -sin(theta), 0, cos(theta);

    // Rotation about z-axis (yaw)
    Rz << cos(psi), -sin(psi), 0,
          sin(psi), cos(psi), 0,
          0, 0, 1;

    // Combined rotation: R = Rz * Ry * Rx
    result = Rz * Ry * Rx;
    return result;
}

int main() {
    // Example Euler angles in radians
    double rollAngle = 0.1;
    double pitchAngle = 0.2;
    double yawAngle = 0.3;

    Eigen::Matrix3d orientationMatrix = computeOrientationMatrix(rollAngle, pitchAngle, yawAngle);

    std::cout << "Orientation Matrix:" << std::endl << orientationMatrix << std::endl;
    return 0;
}

