// Find common elements between two string vectors (with duplicates)
std::vector<std::string> getCommonElements(const std::vector<std::string>& input1, const std::vector<std::string>& input2) {
    std::unordered_map<std::string, int> frequencyMap;
    std::vector<std::string> output;

    // Count occurrences of each string in the first vector
    for (const auto& item : input1) {
        frequencyMap[item]++;
    }

    // Check against second vector and add to result if present
    for (const auto& item : input2) {
        if (frequencyMap[item] > 0) {
            output.push_back(item);
            frequencyMap[item]--;
        }
    }

    return output;
}

