void HipServer::HandleReceive(const boost::system::error_code& error, std::size_t bytesReceived)
{
    if ((!error || error == boost::asio::error::message_size))
    {
        // Process incoming HIP message
        try
        {
            m_context.m_buffer = std::make_shared<ByteBlock>
                (m_buffer.begin(), m_buffer.begin() + bytesReceived);

            m_context.m_packet = HipPacketPtr(new HipPacket(*m_context.m_buffer)); // Construct packet from received data

            // Extract key fields from the packet
            std::string senderIP = m_context.m_packet->GetSourceAddress();
            std::string receiverIP = m_context.m_packet->GetDestinationAddress();

            // Log extracted details
            std::cout << "Source: " << senderIP << ", Dest: " << receiverIP << std::endl;
        }
        catch (const std::exception& ex)
        {
            std::cerr << "Packet processing failed: " << ex.what() << std::endl;
        }
    }
}

