// Insert a new material into the scene at a specific position
bool insertMaterial(aiScene* scene, int position, Material freshMaterial) {
    if (position >= 0 && position < scene->mNumMaterials) {
        // Move existing materials one step forward to create room
        for (int j = scene->mNumMaterials - 1; j >= position; j--) {
            scene->mMaterials[j + 1] = scene->mMaterials[j];
        }
        // Place the new material at the designated position
        scene->mMaterials[position] = freshMaterial;
        scene->mNumMaterials++;  // Update the count of materials
        return true;  // Operation successful
    }
    return false;  // Position is invalid
}

