    std::vector<int> values;
    std::random_device rng;
    std::mt19937 engine(rng());
    std::uniform_int_distribution<int> dist(1, 100); // Generate random numbers between 1 and 100.
    for (size_t idx = 0; idx < COUNT; ++idx) {
        values.push_back(dist(engine)); // Collect random numbers and store them in a vector.
