    // Perform operations on collected numbers.
    // 1. Calculate the sum of all collected numbers.
    int accumulator = 0;
    for (int val : values) {
        accumulator += val;
    }
    // 2. Find the maximum and minimum values among the collected numbers.
    int largest = *std::max_element(values.begin(), values.end());
    int smallest = *std::min_element(values.begin(), values.end());
