// Compute the Euclidean distance between two 3D points
double computeEuclideanDistance(const std::vector<double>& coords1, const std::vector<double>& coords2) {
    double squaredSum = 0;
    for (size_t index = 0; index < coords1.size(); ++index) {
        squaredSum += pow(coords1[index] - coords2[index], 2);
    }
    return sqrt(squaredSum);
}

