class GLIndexBuffer {
public:
    // Initialize the index buffer with provided data
    GLIndexBuffer(uint32_t* data, uint32_t size) {
        glGenBuffers(1, &mBufferID);
        glBindBuffer(GL_ELEMENT_ARRAY_BUFFER, mBufferID);
        glBufferData(GL_ELEMENT_ARRAY_BUFFER, size * sizeof(uint32_t), data, GL_STATIC_DRAW);
        mElementCount = size;
    }

    // Clean up GPU resources
    ~GLIndexBuffer() {
        glDeleteBuffers(1, &mBufferID);
    }

    // Activate this buffer for subsequent operations
    void bind() const {
        glBindBuffer(GL_ELEMENT_ARRAY_BUFFER, mBufferID);
    }

    // Retrieve number of stored indices
    uint32_t getLength() const {
        return mElementCount;
    }

private:
    uint32_t mBufferID;
    uint32_t mElementCount;
};

