template <typename ArgType>
class Signal {
public:
    using Callback = std::function<void(ArgType)>;

    void subscribe(const Callback& cb) {
        callbacks.push_back(cb);
    }

    void unsubscribe(const Callback& cb) {
        callbacks.remove(cb);
    }

    void emit(const ArgType& value) {
        for (const auto& callback : callbacks) {
            callback(value);
        }
    }

private:
    std::list<Callback> callbacks;
};

class DataProcessor {
public:
    void handleData(int data) {
        std::cout << "Signal received with value: " << data << std::endl;
    }
};

int main() {
    DataProcessor processor;
    Signal<int> signal;

    // Subscribe handler
    signal.subscribe([&processor](int val) { processor.handleData(val); });

    // Emit first signal
    if (!signal.callbacks.empty()) {
        signal.emit(2);  // will print once
    }

    // Unsubscribe handler
    signal.unsubscribe([&processor](int val) { processor.handleData(val); });

    // Emit second signal - handler was removed
    if (!signal.callbacks.empty()) {
        signal.emit(3);  // will not be printed since handler was removed
    }

    return 0;
}

