namespace quadrants::lang {

// Substitute every occurrence of statement X with a fresh statement Y.
// Important: the original statement X remains unchanged in the IR.
class StatementOperandSubstituter : public IRVisitor {
  // We avoid BasicStmtVisitor to prevent descending into FrontendForStmt nodes.
 public:
  Stmt *target_stmt, *replacement_stmt;

  StatementOperandSubstituter(Stmt *target, Stmt *replacement)
      : target_stmt(target), replacement_stmt(replacement) {
    allow_undefined_visitor = true;
    invoke_default_visitor = true;
  }

  void visit(Stmt *stmt) override {
    stmt->replace_operand_with(target_stmt, replacement_stmt);
  }

  void visit(WhileStmt *loop) override {
    loop->replace_operand_with(target_stmt, replacement_stmt);
    loop->body->accept(this);
  }

  void visit(IfStmt *conditional) override {
    conditional->replace_operand_with(target_stmt, replacement_stmt);
    if (conditional->true_statements)
      conditional->true_statements->accept(this);
    if (conditional->false_statements) {
      conditional->false_statements->accept(this);
    }
  }

  void visit(Block *block) override {
    for (auto &stmt : block->statements) {
      stmt->accept(this);
    }
  }

  void visit(RangeForStmt *loop) override {
    loop->replace_operand_with(target_stmt, replacement_stmt);
    loop->body->accept(this);
  }

  void visit(StructForStmt *loop) override {
    loop->body->accept(this);
  }

  void visit(MeshForStmt *loop) override {
    loop->body->accept(this);
  }

  void visit(OffloadedStmt *task) override {
    task->all_blocks_accept(this);
  }

  static void execute(IRNode *entry_point, Stmt *old_stmt, Stmt *new_stmt) {
    StatementOperandSubstituter substituter(old_stmt, new_stmt);

    if (entry_point != nullptr) {
      entry_point->accept(&substituter);
      return;
    }

    QD_ASSERT(old_stmt->parent != nullptr);
    old_stmt->parent->accept(&substituter);

    auto current_block = old_stmt->parent->parent_block();

    while (current_block != nullptr) {
      for (auto &stmt : current_block->statements) {
        stmt->replace_operand_with(old_stmt, new_stmt);
      }
      current_block = current_block->parent_block();
    }
  }
};

