namespace examples {
static bool parse_txt_entry(rav::dnssd::TxtRecord& txt_record, const std::string& input_value) {
    if (input_value.empty())
        return false;

    const size_t equal_pos = input_value.find('=');
    if (equal_pos != std::string::npos) {
        txt_record[input_value.substr(0, equal_pos)] = input_value.substr(equal_pos + 1);
    } else {
        txt_record[input_value] = "";
    }
    return true;
}
}  // namespace examples

int main(int const argc, char* argv[]) {
    rav::set_log_level_from_env();
    rav::do_system_checks();

    std::vector<std::string> arguments;
    for (int idx = 1; idx < argc; ++idx) {
        arguments.emplace_back(argv[idx]);
    }

    // Check if we have at least the service type and port number
    if (arguments.size() < 2) {
        std::cout << "Error: expected at least an argument which specifies the service type and an argument which "
                     "specifies the port number (example: _test._tcp 1234 key1=value1 key2=value2)"
                  << std::endl;
        return -1;
    }

    // Parse port number
    int service_port = 0;
    try {
        service_port = std::stoi(arguments[1]);
    } catch (const std::exception& ex) {
        std::cout << "Invalid port number: " << ex.what() << std::endl;
        return -1;
    }

    // Parse remaining arguments as TxtRecord
    rav::dnssd::TxtRecord txt_data;
    for (auto iter = arguments.begin() + 2; iter != arguments.end(); ++iter) {
        examples::parse_txt_entry(txt_data, *iter);
    }

    boost::asio::io_context io_ctx;
    const auto advertiser = rav::dnssd::Advertiser::create(io_ctx);
    if (advertiser == nullptr) {
        RAV_LOG_ERROR("Error: no dnssd advertiser implementation available for this platform");
        return -1;
    }

    advertiser->on_error = [](const auto& error_msg) {
        RAV_LOG_ERROR("Advertiser error: {}", error_msg);
    };

    advertiser->on_name_conflict = [](const auto* reg_type, const auto* name) {
        RAV_LOG_CRITICAL("Name conflict: {} {}", reg_type, name);
    };

    const auto registration_id =
        advertiser->register_service(arguments[0], "Test service", nullptr, static_cast<uint16_t>(service_port), txt_data, true, true);

    std::thread io_thread([&io_ctx] {
        io_ctx.run();
    });

    RAV_LOG_INFO("Enter key=value to update the TXT record, or q to exit...");
    std::string user_input;
    while (true) {
        std::getline(std::cin, user_input);
        if (user_input == "q" || user_input == "Q") {
            break;
        }
        if (user_input == "r" || user_input == "R") {
            advertiser->unregister_service(registration_id);
            continue;
        }
        try {
            if (examples::parse_txt_entry(txt_data, user_input)) {
                // Schedule the updates on the io_context thread because the advertiser is not thread-safe.
                boost::asio::post(io_ctx, [=, &advertiser] {
                    advertiser->update_txt_record(registration_id, txt_data);
                    RAV_LOG_INFO("Updated txt record");
                });
            }
        } catch (const std::exception& e) {
            RAV_LOG_ERROR("Failed to update txt record: {}", e.what());
        }
    }

    io_ctx.stop();
    io_thread.join();
    std::cout << "Exit" << std::endl;
    return 0;
}

