// Use long double for improved numerical stability with small values
using LD = long double;

// Computes log(sum(exp(x_i))) in a numerically stable manner
LD log_sum_exp(const std::vector<LD>& values) {
    if (values.empty()) {
        // Log of zero is negative infinity
        return -std::numeric_limits<LD>::infinity();
    }

    LD max_val = *std::max_element(values.begin(), values.end());
    LD exp_sum = 0.0L;

    for (LD val : values) {
        exp_sum += expl(val - max_val);
    }

    return max_val + logl(exp_sum);
}

int main() {
    // Optimize I/O performance
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int num_experts;   // Number of prediction experts
    int num_rounds;    // Number of betting rounds

    std::cin >> num_experts >> num_rounds;

    // Initialize all weights to 1 (log(1) = 0)
    std::vector<LD> expert_weights(num_experts, 0.0L);

    const LD learning_rate = 0.5L;
    const LD log_learning_rate = logl(learning_rate);

    for (int round = 0; round < num_rounds; ++round) {
        std::string expert_predictions;
        std::cin >> expert_predictions;

        // Partition experts by their predictions
        std::vector<LD> pred0_logs;
        std::vector<LD> pred1_logs;

        for (int i = 0; i < num_experts; ++i) {
            if (expert_predictions[i] == '0') {
                pred0_logs.push_back(expert_weights[i]);
            } else {
                pred1_logs.push_back(expert_weights[i]);
            }
        }

        // Compute aggregated weights for each prediction group
        LD log_weight_0 = log_sum_exp(pred0_logs);
        LD log_weight_1 = log_sum_exp(pred1_logs);

        // Make prediction: prefer '0' on ties
        char my_prediction;
        if (log_weight_0 >= log_weight_1) {
            my_prediction = '0';
        } else {
            my_prediction = '1';
        }

        // Output and flush our prediction
        std::cout << my_prediction << std::endl;

        // Read actual result
        char actual_result;
        std::cin >> actual_result;

        // Update weights: penalize incorrect experts by multiplying by eta
        for (int i = 0; i < num_experts; ++i) {
            if (expert_predictions[i] != actual_result) {
                expert_weights[i] += log_learning_rate;
            }
        }
    }

    return 0;
}

#include <iostream>
#include <algorithm>
#include <vector>
using namespace std;

// Find the subsequence of length k with maximum sum while preserving original order
class Solution {
public:
    vector<int> maxSubsequence(vector<int>& arr, int len) {
        vector<pair<int, int>> indexed;
        for (int idx = 0; idx < arr.size(); ++idx) {
            indexed.emplace_back(arr[idx], idx);
        }

        // Sort by value in descending order to get largest elements first
        sort(indexed.begin(), indexed.end(), [](auto& x, auto& y) {
            return x.first > y.first;
        });

        // Select top 'len' elements based on value
        vector<pair<int, int>> chosen(indexed.begin(), indexed.begin() + len);

        // Reorder selected elements by their original positions to maintain subsequence order
        sort(chosen.begin(), chosen.end(), [](auto& p1, auto& p2) {
            return p1.second < p2.second;
        });

        // Construct final result from selected values
        vector<int> output;
        for (auto& item : chosen) {
            output.push_back(item.first);
        }

        return output;
    }
};

