#include <iostream>
#include <rclcpp/rclcpp.hpp>
#include <rclcpp/serialization.hpp>
#include <rslcpp/rslcpp.hpp>
#include <rslcpp_helper_nodes/monitor.hpp>
#include "rslcpp_test/communication_delay/receiver.hpp"
#include "rslcpp_test/communication_delay/sender.hpp"

/// @brief Custom job implementation for the RSLCPP simulation
class SimulationJob : public rslcpp::Job
{
public:
  /// @brief Return the exit code of the simulation. This will be called after stopping the job.
  std::uint8_t get_exit_code() override { return termination_code_; }

  /// @brief Get whether the simulation is finished
  bool get_finished() override { return completed_; }

  /// @brief Return the initial time of the simulation
  rclcpp::Time get_initial_time() override { return rclcpp::Time(10, 0, RCL_ROS_TIME); }

  std::vector<rclcpp::Node::SharedPtr> create_and_get_nodes() override
  {
    rclcpp::NodeOptions node_options;
    // Enable intra-process communication for better performance
    node_options.use_intra_process_comms(true);

    // Instantiate sender and receiver nodes
    auto tx_node = std::make_shared<CommunicationDelaySender>(node_options);
    auto rx_node = std::make_shared<ReceiverNode>(node_options);

    // Set up monitor node to terminate simulation after timeout
    auto watch_node = std::make_shared<rslcpp::helper_nodes::SimulationMonitor>(
      [this](rslcpp::exit_code_t code) {
        completed_ = true;
        termination_code_ = code;
      },
      node_options);

    watch_node->set_parameter(rclcpp::Parameter("timeout_s", 100));

    // Return all created nodes
    return {tx_node, watch_node, rx_node};
  }

private:
  bool completed_ = false;
  rslcpp::exit_code_t termination_code_ = 0;
};

// Execute the simulation deterministically using RSLCPP
int main(int argc, char ** argv)
{
  // Initialize the job instance
  auto job_instance = std::make_shared<SimulationJob>();

  // Run the simulation
  auto result_code = rslcpp::run_job(argc, argv, job_instance);

  std::cout << "RSLCPP Simulation completed with Exit Code: " 
            << static_cast<int>(result_code) << std::endl;

  return 0;
}

