#include <iostream>
#include <boost/array.hpp>
#include <asio.hpp>

using asio::ip::tcp;

int main(int argc, char* argv[])
{
  try
  {
    if (argc != 2)
    {
      std::cerr << "Usage: client <host>" << std::endl;
      return 1;
    }

    asio::io_context io_context_obj;
    tcp::resolver resolver_obj(io_context_obj);
    tcp::resolver::results_type endpoint_list =
      resolver_obj.resolve(argv[1], "daytime");

    tcp::socket socket_obj(io_context_obj);
    asio::connect(socket_obj, endpoint_list);

    for (;;)
    {
      boost::array<char, 128> buffer;
      asio::error_code err;
      size_t bytes_read = socket_obj.read_some(asio::buffer(buffer), err);

      if (err == asio::error::eof)
        break; // Connection closed cleanly by peer.
      else if (err)
        throw asio::system_error(err); // Some other error.

      std::cout.write(buffer.data(), bytes_read);
    }
  }
  catch (std::exception& ex)
  {
    std::cerr << ex.what() << std::endl;
  }

  return 0;
}

