#include <stack>
#include <string>

class Solution {
public:
    // Check if the bracket sequence is valid
    bool checkBrackets(std::string input) {
        int length = input.length();

        // If length is odd, cannot be valid
        if (length % 2 == 1) {
            return false;
        }

        std::stack<char> stack;

        for (char ch : input) {
            // If opening bracket, push to stack
            if (ch == '(' || ch == '[' || ch == '{') {
                stack.push(ch);
            } 
            // If closing bracket, check match with top of stack
            else {
                if (stack.empty()) {
                    return false;
                }

                char topChar = stack.top();
                if ((topChar == '(' && ch == ')') ||
                    (topChar == '[' && ch == ']') ||
                    (topChar == '{' && ch == '}')) {
                    stack.pop();
                } else {
                    return false;
                }
            }
        }

        return stack.empty();
    }
};

#include <iostream>
#include <vector>
#include <string>
#include <numeric>
#include <algorithm>
#include <random>
#include <iomanip>

// Deterministic random number generator with fixed seed
std::mt19937 gen(42);

void process() {
    int participants;
    int rounds;
    std::cin >> participants >> rounds;

    // Initialize weights for each participant
    std::vector<long double> expert_weights(participants, 1.0L);
    // Track error count per participant
    std::vector<int> error_counts(participants, 0);

    for (int round = 0; round < rounds; ++round) {
        std::string predictions;
        std::cin >> predictions;
        int final_prediction;

        // Determine the smallest error count among all participants
        int lowest_error = *std::min_element(error_counts.begin(), error_counts.end());

        // Strategy: If any expert has zero errors, follow their prediction
        if (lowest_error == 0) {
            int selected_expert = -1;
            for (int idx = 0; idx < participants; ++idx) {
                if (error_counts[idx] == 0) {
                    selected_expert = idx;
                    break;
                }
            }
            final_prediction = predictions[selected_expert] - '0';
        } else {
            // Use randomized weighted majority algorithm
            long double weight_for_zero = 0.0L;
            long double weight_for_one = 0.0L;

            for (int idx = 0; idx < participants; ++idx) {
                if (predictions[idx] == '0') {
                    weight_for_zero += expert_weights[idx];
                } else {
                    weight_for_one += expert_weights[idx];
                }
            }

            long double combined_weight = weight_for_zero + weight_for_one;

            // Fallback if all weights become negligible
            if (combined_weight == 0.0L) {
                final_prediction = 0;
            } else {
                long double probability_one = weight_for_one / combined_weight;
                std::uniform_real_distribution<long double> distribution(0.0L, 1.0L);
                if (distribution(gen) < probability_one) {
                    final_prediction = 1;
                } else {
                    final_prediction = 0;
                }
            }
        }

        std::cout << final_prediction << std::endl;

        int actual_result;
        std::cin >> actual_result;

        // Update expert performance and weights
        for (int idx = 0; idx < participants; ++idx) {
            int expert_prediction = predictions[idx] - '0';
            if (expert_prediction != actual_result) {
                error_counts[idx]++;
                expert_weights[idx] *= 0.5L;
            }
        }
    }
}

int main() {
    // Optimize I/O operations
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    process();
    return 0;
}

