// Custom clock implementation based on std::time_t
struct custom_time_clock
{
  typedef std::chrono::steady_clock::duration duration;
  typedef duration::rep rep;
  typedef duration::period period;
  typedef std::chrono::time_point<custom_time_clock> time_point;
  static constexpr bool is_steady = false;

  static time_point now() noexcept
  {
    return time_point() + std::chrono::seconds(std::time(0));
  }
};

// Custom wait traits for handling the second-granularity clock
struct custom_wait_traits
{
  static custom_time_clock::duration to_wait_duration(
      const custom_time_clock::duration& d)
  {
    if (d > std::chrono::seconds(1))
      return d - std::chrono::seconds(1);
    else if (d > std::chrono::seconds(0))
      return std::chrono::milliseconds(50);
    else
      return std::chrono::seconds(0);
  }

  static custom_time_clock::duration to_wait_duration(
      const custom_time_clock::time_point& t)
  {
    return to_wait_duration(t - custom_time_clock::now());
  }
};

typedef asio::basic_waitable_timer<
  custom_time_clock, custom_wait_traits> custom_timer;

int main()
{
  try
  {
    asio::io_context ioc;
    custom_timer timer(ioc);

    timer.expires_after(std::chrono::seconds(5));
    std::cout << "Begin blocking wait\n";
    timer.wait();
    std::cout << "Blocking wait completed\n";

    timer.expires_after(std::chrono::seconds(5));
    std::cout << "Begin non-blocking wait\n";
    timer.async_wait(
        [](const std::error_code& /*ec*/)
        {
          std::cout << "Timer expired\n";
        });
    ioc.run();
    std::cout << "Non-blocking wait completed\n";
  }
  catch (std::exception& ex)
  {
    std::cerr << "Error: " << ex.what() << "\n";
  }

  return 0;
}

#include <iostream>
#include <queue>
using namespace std;

class MedianFinder {
public:
    // Min heap for the upper half, max heap for the lower half
    priority_queue<int, vector<int>, greater<int>> upperHalf; // right side (larger numbers)
    priority_queue<int> lowerHalf; // left side (smaller numbers)

    MedianFinder() {}

    void addNum(int value) {
        // Insert into lower half first
        lowerHalf.push(value);

        // Rebalance: move the largest from lower half to upper half
        upperHalf.push(lowerHalf.top());
        lowerHalf.pop();

        // Ensure size balance: lowerHalf can have equal or one more element than upperHalf
        if (upperHalf.size() > lowerHalf.size()) {
            lowerHalf.push(upperHalf.top());
            upperHalf.pop();
        }
    }

    double findMedian() {
        if (lowerHalf.size() > upperHalf.size()) {
            return lowerHalf.top();
        } else {
            return (lowerHalf.top() + upperHalf.top()) / 2.0;
        }
    }
};
