using asio::local::stream_protocol;

class connection_handler
  : public std::enable_shared_from_this<connection_handler>
{
public:
  connection_handler(stream_protocol::socket sock)
    : socket_(std::move(sock))
  {
  }

  void begin()
  {
    perform_read();
  }

private:
  void perform_read()
  {
    auto self(shared_from_this());
    socket_.async_read_some(asio::buffer(buffer_),
        [this, self](std::error_code error_code, std::size_t bytes_transferred)
        {
          if (!error_code)
            perform_write(bytes_transferred);
        });
  }

  void perform_write(std::size_t length)
  {
    auto self(shared_from_this());
    asio::async_write(socket_,
        asio::buffer(buffer_, length),
        [this, self](std::error_code error_code, std::size_t /*bytes_transferred*/)
        {
          if (!error_code)
            perform_read();
        });
  }

  // Socket for client communication
  stream_protocol::socket socket_;
  // Buffer to hold incoming/outgoing data
  std::array<char, 2048> buffer_;
};

class local_server
{
public:
  local_server(asio::io_context& context, const std::string& path)
    : acceptor_(context, stream_protocol::endpoint(path))
  {
    initiate_accept();
  }

private:
  void initiate_accept()
  {
    acceptor_.async_accept(
        [this](std::error_code error_code, stream_protocol::socket socket)
        {
          if (!error_code)
          {
            std::make_shared<connection_handler>(std::move(socket))->begin();
          }
          initiate_accept();
        });
  }

  stream_protocol::acceptor acceptor_;
};

int main(int argument_count, char* arguments[])
{
  try
  {
    if (argument_count != 2)
    {
      std::cerr << "Usage: stream_server <path>\n";
      std::cerr << "*** WARNING: existing file is removed ***\n";
      return 1;
    }

    asio::io_context io_context;
    std::remove(arguments[1]);
    local_server server_instance(io_context, arguments[1]);
    io_context.run();
  }
  catch (std::exception& exception)
  {
    std::cerr << "Error: " << exception.what() << "\n";
  }

  return 0;
}

