void transmit_instruction(int stone_id, const std::string& direction, int exit_passage) {
    std::cout << stone_id << " " << direction << " " << exit_passage << std::endl;
}

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int n;
    std::cin >> n;
    int visited_rooms = 0;

    while (true) {
        std::string input;
        std::cin >> input;
        if (input == "treasure") {
            break;
        }

        if (input == "center") {
            // Discovering a new unvisited room
            int label = visited_rooms;

            std::string placement_side;
            if ((label / n) % 2 == 0) {
                placement_side = "left";
            } else {
                placement_side = "right";
            }

            int offset = label % n;
            // From center room, passage numbering is arbitrary
            // We send instruction to place stone at computed offset and exit via passage 0
            transmit_instruction(offset, placement_side, 0);
            visited_rooms++;
        } else { // input is "left" or "right"
            // Previously seen room - advance the stone by one passage in specified direction
            transmit_instruction(1, input, 1);
        }
    }
    return 0;
}

