export struct Image : Node {
    Math::Rectf _bounds;
    Rc<Gfx::Surface> _texture;
    Math::Radiif _corners;

    Image(Math::Rectf bounds, Rc<Gfx::Surface> texture, Math::Radiif corners = {})
        : _bounds(bounds), _texture(texture), _corners(corners) {
    }

    Math::Rectf bound() override {
        return _bounds;
    }

    void paint(Gfx::Canvas& ctx, Math::Rectf region, PaintOptions opts) override {
        if (not region.intersects(bound()))
            return;

        if (not _corners.zero()) {
            ctx.fillStyle(_texture->pixels());
            ctx.fill(_bounds, _corners);
        } else {
            ctx.blit(_bounds.cast<isize>(), _texture->pixels());
        }
    }

    void repr(Io::Emit& out) const override {
        out("(image z:{})", zIndex);
    }
};

