namespace Karm {

/// Execute a task upon exiting the current scope.
/// Tasks are invoked in LIFO order relative to their registration.
export template <typename Func>
struct ScopeGuard : Meta::Pinned {
    Func _action;
    always_inline ScopeGuard(Func action) : _action(action) {}
    always_inline ~ScopeGuard() {
        _action();
    }
};

export template <typename Func>
ScopeGuard(Func) -> ScopeGuard<Func>;

/// A deferred action that can be conditionally suppressed before execution.
/// The action runs only if still armed when going out of scope.
export template <typename Func>
struct ConditionalGuard : Meta::NoCopy {
    Func _action;
    bool _enabled = true;

    always_inline ConditionalGuard(Func action) : _action(action) {}

    always_inline ~ConditionalGuard() {
        if (_enabled)
            _action();
    }

    always_inline void cancel() {
        _enabled = false;
    }

    always_inline void activate() {
        _enabled = true;
    }

    always_inline void trigger() {
        if (_enabled) {
            _action();
        }
        cancel();
    }
};

export template <typename Func>
ConditionalGuard(Func) -> ConditionalGuard<Func>;

} // namespace Karm

