// Helper function to issue a query and process the response
int performQuery(int idx1, int idx2) {
    std::cout << "? " << idx1 << " " << idx2 << std::endl;
    int response;
    std::cin >> response;

    // Handle error condition: exit if response is -1
    if (response == -1) {
        std::exit(0);
    }

    return response;
}

int main() {
    // Optimize I/O operations
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int size;
    std::cin >> size;

    std::vector<int> permutation(size + 1);
    std::vector<int> orResults(size + 1);

    // Phase 1: Query element at position 1 with all other positions
    for (int pos = 2; pos <= size; ++pos) {
        orResults[pos] = performQuery(1, pos);
    }

    // Phase 2: Compute value at position 1 using bitwise AND of all OR results
    int firstElement = -1; // All bits set initially
    for (int pos = 2; pos <= size; ++pos) {
        if (firstElement == -1) {
            firstElement = orResults[pos];
        } else {
            firstElement &= orResults[pos];
        }
    }
    permutation[1] = firstElement;

    // Phase 3: Derive remaining elements from OR results
    for (int pos = 2; pos <= size; ++pos) {
        permutation[pos] = orResults[pos];
    }

    // Output final permutation
    std::cout << "!";
    for (int pos = 1; pos <= size; ++pos) {
        std::cout << " " << permutation[pos];
    }
    std::cout << std::endl;

    return 0;
}

#include <cstdint>
#include <generic/arch.hpp>
#include <arch/riscv64/features.hpp>

namespace arch {
    [[gnu::weak]] void disable_interrupts() {
        asm volatile("csrc sstatus, %0" : : "r"(1 << 1));
    }

    [[gnu::weak]] void enable_interrupts() {
        asm volatile("csrs sstatus, %0" : : "r"(1 << 1));
    }

    [[gnu::weak]] void wait_for_interrupt() {
        asm volatile("wfi");
    }

    [[gnu::weak]] void hcf() {
        disable_interrupts();
        while (true) {
            wait_for_interrupt();
        }
    }

    [[gnu::weak]] void pause() {
#ifdef __riscv_zihintpause
        asm volatile("pause");
#else
        asm volatile("nop");
#endif
    }

    [[gnu::weak]] void tlb_flush(std::uintptr_t addr_hint, std::uintptr_t size_bytes) {
        if (size_bytes / PAGE_SIZE > 256 || size_bytes == 0) {
            asm volatile("sfence.vma");
        } else {
            for (std::uintptr_t offset = 0; offset < size_bytes; offset += PAGE_SIZE) {
                asm volatile("sfence.vma %0" : : "r"(addr_hint + offset) : "memory");
            }
        }
    }

    [[gnu::weak]] const char* get_arch_name() {
        return "riscv64";
    }

    [[gnu::weak]] int get_paging_levels() {
        return riscv64::get_paging_level();
    }

    [[gnu::weak]] void initialize(int init_stage) {
        (void)init_stage;
    }
}

