class Solution {
public:
    // Convert the first occurrence of digit 6 to 9 for maximum value
    int maximum69Number(int inputNumber) {
        int position{1000};
        while(position != 0 && (inputNumber / position) % 10 != 6)
            position /= 10;
        return inputNumber + 3 * position;
