using namespace std;

// LeetCode 56: Merge Intervals - Modified version
// Given a collection of intervals, merge all overlapping intervals.
class Solution {
public:
    vector<vector<int>> merge(vector<vector<int>>& ranges) {
        vector<vector<int>> merged;
        if (ranges.empty()) return merged;

        sort(ranges.begin(), ranges.end());

        for (int index = 0; index < ranges.size(); index++) {
            // If merged is empty or current interval doesn't overlap, add it
            if (merged.empty() || ranges[index][0] > merged.back()[1]) {
                merged.push_back(ranges[index]);
            } else {
                // Overlap detected: update the end of the last merged interval
                merged.back()[1] = max(merged.back()[1], ranges[index][1]);
            }
        }
        return merged;
    }
};

