#include <UniConv/UniConv.h>

int main() {
    std::cout << "=== FetchContent UniConv Demonstration ===" << std::endl;

    try {
        // Retrieve the singleton instance of UniConv
        auto converter = UniConv::GetInstance();

        // Perform basic encoding conversion tests
        std::string source_text = "Hello UniConv! Test text with ASCII only.";
        std::cout << "Source UTF-8 string: " << source_text << std::endl;

        // Transform from UTF-8 to GBK using the optimized API
        auto gbk_output = converter->ConvertEncodingFast(source_text, "UTF-8", "GBK");
        if (!gbk_output.IsSuccess()) {
            std::cout << "FAILURE: GBK conversion error: " << gbk_output.GetErrorMessage() << std::endl;
            return 1;
        }
        std::cout << "Successfully converted to GBK, size: " << gbk_output.GetValue().size() << " bytes" << std::endl;

        // Convert back from GBK to UTF-8
        auto utf8_back = converter->ConvertEncodingFast(gbk_output.GetValue(), "GBK", "UTF-8");
        if (!utf8_back.IsSuccess()) {
            std::cout << "FAILURE: UTF-8 re-conversion error: " << utf8_back.GetErrorMessage() << std::endl;
            return 1;
        }
        std::cout << "Reconverted to UTF-8: " << utf8_back.GetValue() << std::endl;

        // Validate that round-trip conversion preserved data integrity
        if (source_text == utf8_back.GetValue()) {
            std::cout << "VERIFIED: Round-trip conversion completed correctly!" << std::endl;
        } else {
            std::cout << "FAILURE: Round-trip conversion mismatch" << std::endl;
            std::cout << "Original: '" << source_text << "'" << std::endl;
            std::cout << "Final:    '" << utf8_back.GetValue() << "'" << std::endl;
            return 1;
        }

        // Attempt system codepage identification
        auto cp_result = converter->GetSystemCodePageFast();
        if (cp_result.IsSuccess()) {
            std::cout << "Detected system codepage: " << cp_result.GetValue() << std::endl;
        } else {
            std::cout << "Note: Unable to determine system codepage: " << cp_result.GetErrorMessage() << std::endl;
        }

        std::cout << std::endl << "=== FetchContent Integration Verification Passed! ===" << std::endl;
        std::cout << "UniConv has been successfully incorporated as a subproject through FetchContent" << std::endl;

    } catch (const std::exception& e) {
        std::cerr << "Exception occurred: " << e.what() << std::endl;
        return 1;
    }

    return 0;
}

