using namespace infengine;

namespace py = pybind11;

// ============================================================================
// Python override support for RenderPipelineCallback
// ============================================================================
class PyRenderPipelineCallback : public RenderPipelineCallback
{
  public:
    using RenderPipelineCallback::RenderPipelineCallback;

    void Render(ScriptableRenderContext &ctx, const std::vector<Camera *> &cams) override
    {
        // Attempt to invoke Python method named 'render'
        PYBIND11_OVERRIDE_PURE_NAME(void, RenderPipelineCallback, "render", Render, &ctx, cams);
    }

    void Dispose() override
    {
        // Call Python override if present
        PYBIND11_OVERRIDE_NAME(void, RenderPipelineCallback, "dispose", Dispose);
    }
};

// ============================================================================
// Expose bindings to Python
// ============================================================================
namespace infengine
{
void RegisterRenderPipelineBindings(py::module_ &mod)
{
    // ---- CullingResults ----
    py::class_<CullingResults>(mod, "CullingResults")
        .def_property_readonly("visible_object_count",
                               [](const CullingResults &self) { return self.visibleObjectCount(); })
        .def_property_readonly("visible_light_count",
                               [](const CullingResults &self) { return self.visibleLightCount(); });

    // Camera is already registered elsewhere — skip duplicate binding.

    // ---- ScriptableRenderContext ----
    py::class_<ScriptableRenderContext>(mod, "ScriptableRenderContext")
        .def_property_readonly("scene", &ScriptableRenderContext::GetScene,
                               py::return_value_policy::reference,
                               "Access the scene currently being rendered")
        .def("setup_camera_properties", &ScriptableRenderContext::SetupCameraProperties,
             py::arg("camera"), "Configure camera view-projection matrices")
        .def("cull", &ScriptableRenderContext::Cull, py::arg("camera"),
             "Perform frustum culling and return visible objects/lights")
        // RenderGraph API
        .def("apply_graph", &ScriptableRenderContext::ApplyGraph, py::arg("desc"),
             "Install a user-defined render graph from Python")
        .def("submit_culling", &ScriptableRenderContext::SubmitCulling, py::arg("results"),
             "Issue draw calls based on previously computed culling results")
        // CommandBuffer execution
        .def("execute_command_buffer", &ScriptableRenderContext::ExecuteCommandBuffer, py::arg("cmd_buf"),
             "Flush and execute a previously queued CommandBuffer")
        .def("get_camera_target", &ScriptableRenderContext::GetCameraTarget, py::arg("cam"),
             "Retrieve the render target associated with a given camera")
        // Global shader parameters
        .def(
            "set_global_texture",
            [](ScriptableRenderContext &self, const std::string &param_name, RenderTargetHandle tex_handle) {
                self.SetGlobalTexture(param_name, tex_handle);
            },
            py::arg("name"), py::arg("handle"), "Assign a texture to a global shader property")
        .def("set_global_float", &ScriptableRenderContext::SetGlobalFloat,
             py::arg("name"), py::arg("val"), "Set a scalar float shader uniform")
        .def("set_global_vector", &ScriptableRenderContext::SetGlobalVector,
             py::arg("name"), py::arg("x"), py::arg("y"), py::arg("z"), py::arg("w"),
             "Set a vec4 shader uniform");

    // ---- RenderPipelineCallback (abstract base with Python trampoline) ----
    py::class_<RenderPipelineCallback, PyRenderPipelineCallback, std::shared_ptr<RenderPipelineCallback>>(
        mod, "RenderPipelineCallback")
        .def(py::init<>())
        .def("render", &RenderPipelineCallback::Render,
             py::arg("context"), py::arg("cameras"),
             "Main rendering hook: invoked once per frame to schedule passes")
        .def("dispose", &RenderPipelineCallback::Dispose,
             "Cleanup callback invoked when pipeline is destroyed or replaced");
}
