#include <vector>
#include <algorithm>
#include <iostream>

class Solution {
public:
    // Find the minimum difference among any k elements in the array
    int minimumDifference(std::vector<int>& values, int groupSize) {
        int arraySize = values.size();

        // Sort the array to get consecutive elements closest to each other
        std::sort(values.begin(), values.end());

        // If there's only one element, difference is zero
        if (arraySize == 1) 
            return 0;

        // Initialize minimum difference with the first group of k elements
        int smallestDiff = values[groupSize - 1] - values[0];

        // Check all possible groups of k consecutive elements
        for (int index = 1; index <= arraySize - groupSize; index++) {
            int currentDiff = values[index + groupSize - 1] - values[index];
            smallestDiff = std::min(currentDiff, smallestDiff);
        }

        return smallestDiff;
    }
};

#include "quadrants/program/field_info.h"
namespace quadrants {
namespace ui {
using namespace quadrants::lang;

// Retrieve device pointer for a given field (snode) within the program
DevicePtr retrieve_field_device_ptr(quadrants::lang::Program *runtime_program, SNode *field_snode) {
  /*
  GGUI assumes that input fields originate from ti.field() or ti.Vector with
  explicit shape, implying they are built via ti.root.dense.place(). This means:
    - The snode's parent is dense,
    - That parent's parent is a root.
  This structure allows us to compute the field's offset from the root buffer start.
  Note: This holds except possibly for set_image(), where images bypass the VBO.
  */
  SNode *immediate_parent = field_snode->parent;
  SNode *root_node = immediate_parent->parent;
  int tree_identifier = root_node->get_snode_tree_id();
  DevicePtr base_root_ptr = runtime_program->get_snode_tree_device_ptr(tree_identifier);
  return base_root_ptr.get_ptr(
      runtime_program->get_field_in_tree_offset(tree_identifier, field_snode));
}
