#include "Game.h"
namespace Mechanics {
    void Game::UpdateFrame(unsigned timeDelta) {
        // Step 1: move the player's position forward in time
        player.Update(timeDelta);
        // Step 2: advance each active enemy's state
        for(auto &enemy : enemies) {
            enemy.Update(timeDelta);
        }
        // Step 3: create a new asteroid when sufficient time has elapsed
        spawnCounter += timeDelta;
        if(spawnCounter > spawnDelay) {
            spawnCounter = 0;
            // "new EnemyAsteroid()" creates an asteroid on the heap and returns
            // a pointer. The container assumes ownership of this pointer.
            // The asteroid's constructor already randomizes its starting location
            // and movement vector, so no further setup is required here.
            enemies.PushBack(new EnemyAsteroid());
        }
        // Step 4: eliminate enemies that have exited the visible area
        // We use index-based iteration (not range-for) because we alter the
        // list during traversal. After removal, we decrement i
        // to ensure the next loop iteration re-examines the same slot (now occupied
        // by the element shifted down).
        for(int idx = 0; idx < enemies.Count(); idx++) {
            if(enemies[idx].IsVulnerable()) {
                enemies.Remove(idx);
                idx--;  // Correct index since the list size just decreased
            }
        }
        // Step 5: check for overlaps between objects
        // We apply a circular collision model. Each entity is represented
        // as a circle with a specific radius. If the Euclidean distance between
        // their centers is less than the sum of their radii, they intersect -> hit.
        //
        // This technique is commonly referred to as "circle-circle collision" and is
        // widely used in 2D games due to its computational efficiency.
        // We selected slightly reduced radii compared to visual dimensions to allow
        // some leniency for near-misses.
        const int enemyRadius = 48;  // Approximate pixel radius of an asteroid
        const int shipRadius  = 15;  // Approximate pixel radius of the vessel
        for(auto &enemy : enemies) {
            if(enemy.GetKind() == Enemy::Asteroid) {
                // Distance() computes the straight-line separation between two points.
                // If this value falls below the total radii, the circles overlap,
                // indicating a player impact.
                if(enemy.GetLocation().Distance(player.GetLocation()) < enemyRadius / 2.f + shipRadius / 2.f) {
                    // Currently terminates the game instantly.
                    // In a refined version, you'd decrement lives, display a
                    // game-over interface, and enable restart functionality.
                    exit(0);
                }
            }
        }
    }
}

