MainWindow::MainWindow(QWidget *parent)
    : QMainWindow(parent)
    , ui(new Ui::MainWindow)
{
    ui->setupUi(this);
    this->initializeVisualizationWidget();
    // Initialize the initial visual model — specifically, a hexagonal grid visualization
    this->configureHexGridRendering();

    // Set up a periodic timer to animate the surface by updating data values
    QTimer* animationTimer = new QTimer(this);
    connect(animationTimer, &QTimer::timeout, [this]() {
        for (size_t idx = 0; idx < this->hexGrid->count(); ++idx) {
            float dist = std::sqrt(hexGrid->d_x[idx] * hexGrid->d_x[idx] + hexGrid->d_y[idx] * hexGrid->d_y[idx]);
            this->radialDistances[idx] = dist;
            this->surfaceValues[idx] = (std::sin(waveNumber * dist)) / (waveNumber * dist);
        }
        waveNumber += 0.025f;
        if (waveNumber > 7.5f) {
            waveNumber = 1.2f;
        }

        // Signal that the first visual model needs reinitialization before next render
        static_cast<mplot::qt::viswidget<0>*>(this->vwPtr)->set_model_needs_reinit(0);

        // Trigger a redraw of the OpenGL widget
        this->vwPtr->update();
    });
    animationTimer->start(30); // ~33 FPS
}

MainWindow::~MainWindow() {
    delete ui;
}

void MainWindow::configureHexGridRendering() {
    // Create hexagonal grid with specified parameters
    this->hexGrid = std::make_unique<sm::hexgrid>(0.025f, 14.0f, 0.0f);
    hexGrid->setCircularBoundary(3.8f);

    // Prepare storage for computed scalar field
    surfaceValues.resize(hexGrid->count(), 0.0f);
    radialDistances.resize(hexGrid->count(), 0.0f);
    waveNumber = 1.2f;

    // Precompute initial data
    for (size_t hi = 0; hi < hexGrid->count(); ++hi) {
        float r = std::sqrt(hexGrid->d_x[hi] * hexGrid->d_x[hi] + hexGrid->d_y[hi] * hexGrid->d_y[hi]);
        radialDistances[hi] = r;
        surfaceValues[hi] = (std::sin(waveNumber * r)) / (waveNumber * r);
    }

    // Define offset for rendering position
    sm::vec<float, 3> shift = { 0.0f, -0.06f, 0.0f };
    auto hexVis = std::make_unique<mplot::HexGridVisual<float, mplot::qt::gl_version>>(hexGrid.get(), shift);

    // Bind model to shader programs and parent visual context
    static_cast<mplot::qt::viswidget<0>*>(this->vwPtr)->v.bindmodel(hexVis);

    // Attach scalar data for surface coloring
    hexVis->setScalarData(&surfaceValues);

    // Move into shared pointer and add to list of active visuals
    std::unique_ptr<mplot::VisualModel<mplot::qt::gl_version>> basePtr = std::move(hexVis);
    static_cast<mplot::qt::viswidget<0>*>(this->vwPtr)->activeVisuals.push_back(std::move(basePtr));
}

void MainWindow::initializeVisualizationWidget() {
    // Instantiate the visualization widget
    mplot::qt::viswidget<0>* viewWidget = new mplot::qt::viswidget<0>(this->parentWidget());

    // Enable lighting effects for better visual appearance
    viewWidget->v.enableLighting();

    // Integrate into main window layout
    this->ui->mainLayout->addWidget(viewWidget);

    // Store reference for later updates
    this->vwPtr = viewWidget;
}

void MainWindow::on_actionQuit_triggered() {
    close();
}

