void bind_version_check(py::module& module) {
  module.def("_check_serialization_compatibility",
             &qdk::chemistry::data::validate_serialization_version,
             R"(
Check if the serialization version is compatible.
This function ensures that major and minor versions match exactly.
Patch-level differences are acceptable for backward compatibility.
Args:
    required_version: The version string expected by the current code (e.g., "0.1.0")
    actual_version: The version string present in the loaded data
Raises:
    RuntimeError: Thrown when there's a mismatch in major or minor version numbers
Examples:
    >>> check_serialization_compatibility("0.1.0", "0.1.0")  # Succeeds
    >>> check_serialization_compatibility("0.1.0", "0.1.2")  # Succeeds (patch differs)
