#include <ctpl.h>
#include <iostream>
#include <string>

void func1(int id) { 
    std::cout << "hello from " << id << ", function\n"; 
}

void func2(int id, int value) {
    std::cout << "hello from " << id << ", function with parameter " << value
              << '\n';
}

struct CustomClass {
    CustomClass(int val) {
        this->val = val;
        std::cout << "CustomClass ctor " << this->val << '\n';
    }

    CustomClass(CustomClass &&other) {
        this->val = other.val;
        std::cout << "CustomClass move ctor\n";
    }

    CustomClass(const CustomClass &other) {
        this->val = other.val;
        std::cout << "CustomClass copy ctor\n";
    }

    ~CustomClass() { 
        std::cout << "CustomClass dtor\n"; 
    }

    int val;
};

void display_info(int id, const std::string &text) {
    std::cout << "display_info function " << id << ' ' << text << '\n';
}

void delayed_task(int id, CustomClass &obj) {
    std::this_thread::sleep_for(std::chrono::milliseconds(2000));
    std::cout << "hello from " << id << ", function with parameter CustomClass " << obj.val
              << '\n';
}

int main(int argc, char **argv) {
    ctpl::thread_pool pool(2 /* two threads in the pool */);

    std::future<void> future1 = pool.push(std::ref(func1));  // function
    pool.push(func1);                                   // function
    pool.push(func2, 7);                                  // function

    {
        struct LocalFunctor {
            LocalFunctor(const std::string &str) : message(str) { 
                std::cout << "LocalFunctor ctor\n"; 
            }

            LocalFunctor(LocalFunctor &&other) : message(std::move(other.message)) {
                std::cout << "LocalFunctor move ctor\n";
            }

            LocalFunctor(const LocalFunctor &other) : message(other.message) { 
                std::cout << "LocalFunctor copy ctor\n"; 
            };

            ~LocalFunctor() { 
                std::cout << "LocalFunctor dtor\n"; 
            }

            void operator()(int id) const {
                std::cout << "hello from " << id << ' ' << this->message << '\n';
            }

        private:
            std::string message;
        } functor(", functor");

        pool.push(std::ref(functor));  // functor, reference
        std::this_thread::sleep_for(std::chrono::milliseconds(2000));
        pool.push(const_cast<const LocalFunctor &>(functor));  // functor, copy ctor
        pool.push(std::move(functor));                   // functor, move ctor
        pool.push(functor);                              // functor, move ctor
        pool.push(LocalFunctor(", functor"));            // functor, move ctor
    }

    {
        CustomClass instance(100);
        pool.push(delayed_task, std::ref(instance));   // function. reference
        pool.push(delayed_task, instance);             // function. copy ctor, move ctor
        pool.push(delayed_task, std::move(instance));  // function. move ctor, move ctor
    }

    pool.push(delayed_task, CustomClass(200));  // function

    std::string lambda_capture = ", lambda";
    pool.push([lambda_capture](int id) {  // lambda
        std::this_thread::sleep_for(std::chrono::milliseconds(2000));
        std::cout << "hello from " << id << ' ' << lambda_capture << '\n';
    });

    pool.push([lambda_capture](int id) {  // lambda
        std::this_thread::sleep_for(std::chrono::milliseconds(2000));
        std::cout << "hello from " << id << ' ' << lambda_capture << '\n';
    });

    pool.push(display_info, "worked");

    auto task = pool.pop();
    if (task) {
        std::cout << "poped function from the pool ";
        task(0);
    }

    // change the number of threads in the pool
    pool.resize(1);

    std::string result_value = "result";
    auto future_result = pool.push([result_value](int) { return result_value; });

    // other code here
    //...
    std::cout << "returned " << future_result.get() << '\n';

    auto error_task = pool.push([](int) { throw std::exception(); });

    // other code here
    //...
    try {
        error_task.get();
    } catch (std::exception &e) {
        std::cout << "caught exception\n";
    }

    // get thread 0
    auto &thread_ref = pool.get_thread(0);
    return 0;
}

