	void SanitizeFilenameFormat(FString& InOutFilenameFormatString, const bool bIsMultiPass, const bool bIsSequence)
	{
		const FString FrameTokens[] = { TEXT("{frame_number}"), TEXT("{frame_number_shot}"), TEXT("{frame_number_rel}"), TEXT("{frame_number_shot_rel}") };

		// If multiple render passes are active, ensure uniqueness via render_pass token
		if (bIsMultiPass)
		{
			if (!InOutFilenameFormatString.Contains(TEXT("{render_pass}"), ESearchCase::IgnoreCase))
			{
				UE_LOG(LogMovieRenderPipeline, Warning, TEXT("Multiple render passes detected but no {render_pass} placeholder present. Auto-inserting!"));

				// Locate the last occurrence of any frame identifier
				int32 LastFramePos = INDEX_NONE;
				for (const FString& Token : FrameTokens)
				{
					LastFramePos = InOutFilenameFormatString.Find(Token, ESearchCase::IgnoreCase, ESearchDir::FromEnd);
					if (LastFramePos != INDEX_NONE)
					{
						break;
					}
				}

				if (LastFramePos == INDEX_NONE)
				{
					// No frame token found → append render_pass at end
					InOutFilenameFormatString += TEXT("{render_pass}");
				}
				else
				{
					// Insert render_pass before the frame token to preserve sequence recognition
					InOutFilenameFormatString.InsertAt(LastFramePos, TEXT("{render_pass}."));
				}
			}
		}

		// Ensure frame number token exists for image sequences
		if (bIsSequence)
		{
			int32 FramePos = INDEX_NONE;
			for (const FString& Token : FrameTokens)
			{
				FramePos = InOutFilenameFormatString.Find(Token, ESearchCase::IgnoreCase, ESearchDir::FromEnd);
				if (FramePos != INDEX_NONE)
				{
					break;
				}
			}

			if (FramePos == INDEX_NONE)
			{
				// User did not specify a frame identifier — warn about potential overwrites
				UE_LOG(LogMovieRenderPipeline, Warning, TEXT("No frame identifier found in filename format. Files may overwrite each other."));
			}
			else
			{
				// Prepend {file_dup} before the frame token to support duplicate handling while preserving sequence order
				InOutFilenameFormatString.InsertAt(FramePos, TEXT("{file_dup}"));
			}
		}

		// Always ensure {file_dup} is present for safety
		if (!InOutFilenameFormatString.Contains(TEXT("{file_dup}"), ESearchCase::IgnoreCase))
		{
			InOutFilenameFormatString.Append(TEXT("{file_dup}"));
		}
	}

	void StripFrameIdentifiers(FString& InOutFilenameFormatString, const bool bWithShots)
	{
		// Remove all frame-related placeholders to prevent per-frame output files
		InOutFilenameFormatString.ReplaceInline(TEXT("{frame_number}"), TEXT(""));
		InOutFilenameFormatString.ReplaceInline(TEXT("{frame_number_rel}"), TEXT(""));

		if (bWithShots)
		{
			InOutFilenameFormatString.ReplaceInline(TEXT("{frame_number_shot}"), TEXT(""));
			InOutFilenameFormatString.ReplaceInline(TEXT("{frame_number_shot_rel}"), TEXT(""));
		}
	}
}
}

