	1 // Required for interop functionality
#include <sol/sol.hpp>
#include <kaguya/kaguya.hpp> // Assuming kaguya header location

// Example class similar to ABC
struct SampleData {
	SampleData() : data_(0) {}
	SampleData(int val) : data_(val) {}
	int getData() const { return data_; }
	void setData(int v) { data_ = v; }

	void methodA() {
		std::cout << "executing methodA" << std::endl;
	}
	void methodB(int x) {
		std::cout << "executing methodB" << std::endl;
	}

private:
	int data_;
};

// Lua interop type check specialization
template <typename U, typename CheckHandler>
inline bool sol_lua_interop_check(sol::types<U>, lua_State* L,
     int pos, sol::type t, CheckHandler&& h,
     sol::stack::record& tracker) {
	(void)t; (void)h;
	tracker.use(1);
	int absIdx = lua_absindex(L, pos);
	bool valid = kaguya::detail::object_wrapper_type_check(L, absIdx);
	return valid;
}

// Lua interop value extraction specialization
template <typename U>
inline std::pair<bool, U*> sol_lua_interop_get(sol::types<U>,
     lua_State* L, int pos, void* rawPtr,
     sol::stack::record& tracker) {
	int absIdx = lua_absindex(L, pos);
	if (!kaguya::detail::object_wrapper_type_check(L, absIdx)) {
		return { false, nullptr };
	}
	tracker.use(1);
	kaguya::ObjectWrapperBase* base = kaguya::object_wrapper(L, absIdx);
	return { true, static_cast<U*>(base->get()) };
}

// Register sol bindings
void setupSolBindings(lua_State* L) {
	sol::state_view lua(L);
	lua["process"] = sol::overload(
	     [](SampleData& obj) {
		     std::cout << "invoking single-arg version with "
		                  "kaguya-created SampleData { "
		               << obj.getData() << " }"
		               << std::endl;
		     SOL_ASSERT(obj.getData() == 42);
	     },
	     [](SampleData& obj, int extra) {
		     std::cout << "invoking two-arg version with "
		                  "kaguya-created SampleData { "
		               << obj.getData()
		               << " } and integer argument of "
		               << extra << std::endl;
		     SOL_ASSERT(obj.getData() == 42);
		     SOL_ASSERT(extra == 7);
	     });
}

// Verify object via sol
void validateWithSol(lua_State* L) {
	sol::state_view lua(L);
	SampleData& ref = lua["instance"];
	(void)ref;
	SOL_ASSERT(ref.getData() == 42);
}

int main(int argc, char* argv[]) {
	std::cout << "=== interop demo (kaguya-based) ==="
	          << std::endl;
	std::cout << "(adapted from kaguya README: "
	             "https://github.com/satoren/kaguya)"
	          << std::endl;

	kaguya::State vm;
	vm["SampleData"].setClass(
	     kaguya::UserdataMetatable<SampleData>()
	          .setConstructors<SampleData(), SampleData(int)>()
	          .addFunction("getValue", &SampleData::getData)
	          .addFunction("setValue", &SampleData::setData)
	          .addOverloadedFunctions(
	               "dispatch", &SampleData::methodA, &SampleData::methodB)
	          .addStaticFunction("helper",
	               [](SampleData* self, int n) { return n * 2; }));

	setupSolBindings(vm.state());
	vm.dostring(R"(
instance = SampleData.new(42)
process(instance) -- single arg
process(instance, 7) -- two args
)");
	validateWithSol(vm.state());

	return 0;
}

