MConstantInt *MConstantInt::get(CompileContext &Context, MType &Type, APInt Value) {
  // Retrieve an existing entry or determine where to insert
  MConstantInt *&Entry = Context.IntConstants[Value];
  if (!Entry) {
    // Allocate memory for a new MConstantInt instance
    Entry = reinterpret_cast<MConstantInt *>(
        Context.ThreadMemPool.allocate(sizeof(MConstantInt), alignof(MConstantInt)));
    new (Entry) MConstantInt(Type, Value);
  }
  return Entry;
}

MConstantInt *MConstantInt::get(CompileContext &Context, MType &Type, uint64_t Value) {
  return MConstantInt::get(Context, Type, APInt(Type.getBitWidth(), Value, Type.isSigned()));
}

MConstantFloat *MConstantFloat::get(CompileContext &Context, MType &Type, APFloat Value) {
  // Retrieve an existing entry or determine where to insert
  MConstantFloat *&Entry = Context.FPConstants[Value];
  if (!Entry) {
    // Allocate memory for a new MConstantFloat instance
    Entry = reinterpret_cast<MConstantFloat *>(
        Context.ThreadMemPool.allocate(sizeof(MConstantFloat), alignof(MConstantFloat)));
    new (Entry) MConstantFloat(Type, Value);
  }
  return Entry;
}

MConstantFloat *MConstantFloat::get(CompileContext &Context, MType &Type, float Value) {
  return MConstantFloat::get(Context, Type, APFloat(Value));
}

MConstantFloat *MConstantFloat::get(CompileContext &Context, MType &Type, double Value) {
  return MConstantFloat::get(Context, Type, APFloat(Value));
}

void MConstant::print(llvm::raw_ostream &Stream) const {
  if (Type.isInteger()) {
    const MConstantInt *IntConst = cast<MConstantInt>(this);
    IntConst->getValue().print(Stream, IntConst->getType().isSigned());
  } else if (Type.isFloat()) {
    const MConstantFloat *FloatConst = cast<MConstantFloat>(this);
    const APFloat &APF = FloatConst->getValue();
    SmallVector<char, 16> Buffer;
    APF.toString(Buffer);
    Stream << Buffer;
  } else {
    ZEN_UNREACHABLE();
  }
}

