#include <iostream>
#include <vector>
#include <string>
#include <map>
#include <cmath>

// Function to send a "move" command to the judge and receive response
int move_step(long long distance) {
    std::cout << "move " << distance << std::endl;
    int result;
    std::cin >> result;
    return result;
}

// Function to send a "answer" command with the computed cycle length
void report_answer(long long answer) {
    std::cout << "answer " << answer << std::endl;
}

int main() {
    // Optimize I/O performance
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    // Block size for Baby-step Giant-step approach
    // Selected near sqrt(10^9) for optimal query count
    const int BLOCK_SIZE = 32000;

    // Map to track visited nodes and their step counts
    std::map<int, int> visited_nodes;

    // Initial position: walk 0 steps to get starting node
    int current_node = move_step(0);
    visited_nodes[current_node] = 0;

    // Phase 1: Baby steps - take BLOCK_SIZE single-step moves
    for (int step = 1; step <= BLOCK_SIZE; ++step) {
        current_node = move_step(1);

        if (visited_nodes.find(current_node) != visited_nodes.end()) {
            // Collision detected in baby steps - small cycle found
            int cycle_length = step - visited_nodes[current_node];
            report_answer(cycle_length);
            return 0;
        }

        visited_nodes[current_node] = step;
    }

    // Phase 2: Giant steps - continue from position after baby steps
    long long accumulated_steps = BLOCK_SIZE;

    // Perform giant steps of size BLOCK_SIZE
    for (int block_index = 2; block_index <= BLOCK_SIZE + 2; ++block_index) {
        current_node = move_step(BLOCK_SIZE);
        accumulated_steps += BLOCK_SIZE;

        if (visited_nodes.count(current_node)) {
            // Found collision between giant step and baby step
            int baby_step_count = visited_nodes[current_node];
            long long cycle_length = accumulated_steps - baby_step_count;
            report_answer(cycle_length);
            return 0;
        }
    }

    // Should never reach here under normal problem conditions
    return 0;
}

