    }

    // Invoked when hardware initializes a new TA list (TA_LIST_INIT register)
    // Resets entire TA state and reinitializes command handler pointer
    void TA_ListInit()
    {
        // TaHandler is set to ta_main within FifoSplitter::ListInit()
    }

    // Triggered by TA soft reset (SOFTRESET register write)
    // Clears list-related state without performing full hardware reset
    void TA_SoftReset()
    {
