#include <iostream>

int main() {
    // Optimize I/O for faster input/output operations
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int distance;
    std::cin >> distance;

    // Continue until we reach the target (distance becomes 0)
    while (distance > 0) {
        int response;
        int next_distance;

        // --- Attempt path with color 0 ---
        std::cout << "move 0" << std::endl;
        std::cin >> response;
        if (response == 1) {
            // Target reached, exit loop
            break;
        }

        std::cout << "query" << std::endl;
        std::cin >> next_distance;
        if (next_distance < distance) {
            // Progress made: moved closer to target
            distance = next_distance;
            continue;
        }

        // Backtrack after failed attempt with color 0
        std::cout << "move 0" << std::endl;
        std::cin >> response; // Result ignored as backtracking is confirmed

        // --- Attempt path with color 1 ---
        std::cout << "move 1" << std::endl;
        std::cin >> response;
        if (response == 1) {
            // Target reached, exit loop
            break;
        }

        std::cout << "query" << std::endl;
        std::cin >> next_distance;
        if (next_distance < distance) {
            // Progress made: moved closer to target
            distance = next_distance;
            continue;
        }

        // Backtrack after failed attempt with color 1
        std::cout << "move 1" << std::endl;
        std::cin >> response; // Result ignored as backtracking is confirmed

        // --- Infer path with color 2 ---
        // Since colors 0 and 1 both led away, color 2 must lead toward target
        std::cout << "move 2" << std::endl;
        std::cin >> response;
        if (response == 1) {
            // Target reached, exit loop
            break;
        }

        // We've moved one step closer without querying
        distance--;
    }

    return 0;
}

