// Determine if the array is sorted in non-decreasing order starting from a given position
bool checkSorted(const vector<int>& data, int pos) {
    // Base case: if we've reached the last element, the array is sorted up to this point
    if (pos == data.size() - 1) {
        return true;
    }
    // Check if current element is greater than the next one
    if (data[pos] > data[pos + 1]) {
        return false; // Violation of sorting order
    }
    // Continue checking the remaining elements recursively
    return checkSorted(data, pos + 1);
}

int main() {
