#include <vector>
#include <string>

using namespace std;

class Solution {
public:
    // Determine if two strings are anagrams using frequency counting
    bool isAnagram(string str1, string str2) { // Time: O(N), Space: O(1)
        // If lengths differ, they can't be anagrams
        if(str1.length() != str2.length()) {
            return false;
        }

        vector<int> charCount(26, 0);

        // Count characters: increment for str1, decrement for str2
        for(int idx = 0; idx < str1.size(); idx++) {
            charCount[str1[idx] - 'a']++;
            charCount[str2[idx] - 'a']--;
        }

        // Check if all counts are zero
        for(int i = 0; i < 26; i++) {
            if(charCount[i] != 0) {
                return false;
            }
        }

        return true;
    }
};

