namespace engine::store::filter::filesys::smb {
//-----------------------------------------------------------------
// Register the smb protocol config with the Url system. This
// enables usage of Url::toPath(...), Url::toUrl(...), etc. Note that
// only the osPath is provided since the service manager handles
// generic toPath, toUrl and capabilities registration
//-----------------------------------------------------------------
static url::UrlConfig urlConfig{
    {//------------------------------------------------------------
     /// @details
     ///	Specify the protocol identifier
     //------------------------------------------------------------
     .protocol = Type,
     //------------------------------------------------------------
     /// @details
     ///	Converts a fully qualified URL like
     ///	smb://Share/<host>/<share>/dir/file.txt into a UNC path
     ///	represented as ("<host>", "<share>", "dir", "file.txt")
     /// @param[in]	sourceUrl
     ///	URL to be transformed
     /// @param[out] destinationPath
     ///	Output parameter for the resulting path
     //------------------------------------------------------------
     .toPath = [](const Url &sourceUrl, file::Path &destinationPath) -> Error {
         // Strip off protocol and File System components
         destinationPath = "//"_tv + sourceUrl.fullpath().subpth(1).str();
         return {};
     },
     //-------------------------------------------------------------
     /// @details
     ///	This function transforms a path (with prefix removed)
     ///	into a fully qualified UNC path suitable for use with
     ///	the apLib file API.
     ///
     ///	For Windows:
     ///		input: ("<host>", "<share>", "dir", "file.txt")
     ///		output: \\<host>\<share>\dir\file.txt
     ///
     ///	For Linux:
     ///		input: ("<host>", "<share>", "dir", "file.txt")
     ///		output: //<host>/<share>/dir/file.txt
     ///
     ///	@param[in] sourceUrl
     ///		The original URL object
     ///	@param[out] platformPath
     ///		Receives the string representation of the path
     ///	@returns
     ///		Error code indicating success or failure
     //------------------------------------------------------------
     .osPath = [](const Url &sourceUrl, Text &platformPath) -> Error {
         // Retrieve the internal path representation
         Path intermediatePath;
         if (auto errorCode = urlConfig.toPath(sourceUrl, intermediatePath)) return errorCode;
         // Use platform-specific conversion for both Windows and Linux
         platformPath = intermediatePath.plat();
         return {};
     }}};
}  // namespace engine::store::filter::filesys::smb

