// Modified version: renamed variables and adjusted structure for Type II clone
void modified_simple(sol::this_state L_state, sol::this_environment L_env) {
    sol::state_view lua_vm = L_state;

    if (L_env) {
        sol::environment& current_env = L_env;
        sol::environment new_env = lua_vm["freshenv"];
        bool env_match = (new_env == current_env);

        std::cout << "modified this_environment -- current == fresh : "
                  << env_match << std::endl;
    }

    std::cout << "modified this_environment -- no environment present"
              << std::endl;
}

// Complicated version with restructured logic and renamed identifiers
void modified_complicated(sol::this_state L_state) {
    lua_State* raw_L = L_state;
    lua_Debug debug_info;

    int stack_level = 1;  // Changed from 'level' to 'stack_level'
    int initial_stack_depth = lua_gettop(raw_L);

    if (lua_getstack(raw_L, stack_level, &debug_info) != 1) {
        std::cout << "error: cannot walk the call stack" << std::endl;
        lua_settop(raw_L, initial_stack_depth);
        return;
    }

    if (lua_getinfo(raw_L, "fnluS", &debug_info) == 0) {
        std::cout << "manually -- error: failed to retrieve stack info"
                  << std::endl;
        lua_settop(raw_L, initial_stack_depth);
        return;
    }

    std::cout << "manually -- [" << stack_level << "] "
              << debug_info.short_src << ":" << debug_info.currentline
              << " -- " << (debug_info.name ? debug_info.name : "<unknown>")
              << "[" << debug_info.what << "]" << std::endl;

    sol::function func_obj(raw_L, -1);
    sol::environment func_env(sol::env_key, func_obj);

    if (!func_env.valid()) {
        std::cout << "manually -- error: no environment found" << std::endl;
        lua_settop(raw_L, initial_stack_depth);
        return;
    }

    sol::state_view lua_view(raw_L);
    sol::environment fresh_env = lua_view["freshenv"];
    bool is_equal = (fresh_env == func_env);

    std::cout << "manually -- env == freshenv : " << is_equal << std::endl;

    lua_settop(raw_L, initial_stack_depth);
}

int main() {
    std::cout << "=== environment inspection ===" << std::endl;

    sol::state lua_vm;
    sol::environment fresh_env(lua_vm, sol::create, lua_vm.globals());
    lua_vm["freshenv"] = fresh_env;

    lua_vm.set_function("func_a", modified_simple);
    lua_vm.set_function("func_b", modified_complicated);

    lua_vm.script("func_a()", fresh_env);
    lua_vm.script("func_b()", fresh_env);

    std::cout << std::endl;
    return 0;
}

#include <vector>
using namespace std;

class Solution {
public:
    // Generate all permutations starting from position 'pos'
    void generatePermutations(vector<int>& elements, int pos, int size, vector<vector<int>>& results) {
        // Base case: when we've fixed all positions except the last one
        if (pos == size - 1) {
            results.push_back(elements);
            return;
        }

        // Try each element at the current position by swapping
        for (int j = pos; j < size; j++) {
            // Swap current element with position 'pos'
            swap(elements[j], elements[pos]);

            // Recursively generate permutations for remaining positions
            generatePermutations(elements, pos + 1, size, results);

            // Backtrack: restore original order
            swap(elements[j], elements[pos]);
        }
    }

    vector<vector<int>> permute(vector<int>& elements) {
        // Initialize result container
        vector<vector<int>> results;

        // Start permutation generation from position 0
        generatePermutations(elements, 0, elements.size(), results);

        return results;
    }
};

