  try {
    sdb::basics::CleanupFunctions::run(errorCode, nullptr);
    sdb::log::Flush();
    sdb::log::Shutdown();
    gApplicationExitHandler(errorCode, nullptr);
  } catch (...) {
  }
  exit(errorCode);
}

