  return reduce_sum_kernel(
    sparse_tensor,
    indices,
    static_cast<int>(blocks_A),
    static_cast<int>(blocks_B)
  );
}

at::Tensor distribute_values(
  at::Tensor dense_tensor,
  at::Tensor mapping,
  int64_t target_blocks
) {
  return scatter_kernel(
    dense_tensor,
    mapping,
    static_cast<int>(target_blocks)
  );
}

