#include "test_ffb_common.h"

namespace FFBEngineTests {
TEST_CASE(test_issue_42_ffb_inversion_persistence_v2, "Configuration") {
    std::cout << "\nVerification: Issue #42 - Force Feedback Inversion State Retention Across Presets" << std::endl;
    FFBEngine engine;
    InitializeEngine(engine);
    Config::LoadPresets();

    // Scenario A: Initialize with inversion enabled
    FFBEngineTestAccess::SetInvertForce(engine, true);
    ASSERT_TRUE(engine.m_invert_force);

    // Load first preset ("Standard")
    Config::ApplyPreset(1, engine);
    ASSERT_TRUE(engine.m_invert_force); // Must stay true

    // Locate and apply "G29" preset (historically sets inversion to true)
    int preset_index = -1;
    for(int idx = 0; idx < static_cast<int>(Config::presets.size()); ++idx) {
        if(Config::presets[idx].name == "G29") {
            preset_index = idx;
            break;
        }
    }

    if(preset_index != -1) {
        Config::ApplyPreset(preset_index, engine);
        ASSERT_TRUE(engine.m_invert_force);
    }

    // Scenario B: Initialize with inversion disabled
    FFBEngineTestAccess::SetInvertForce(engine, false);
    ASSERT_FALSE(engine.m_invert_force);

    // Apply "Standard" preset again
    Config::ApplyPreset(1, engine);
    ASSERT_FALSE(engine.m_invert_force); // Should remain false!

    if(preset_index != -1) {
        Config::ApplyPreset(preset_index, engine);
        ASSERT_FALSE(engine.m_invert_force); // Still false!
    }

    // Scenario C: Ensure Preset::UpdateFromEngine does not persist inversion state
    // Verified by absence of inversion field in preset storage
    Preset custom_preset("CustomProfile", true);
    FFBEngineTestAccess::SetInvertForce(engine, true);
    custom_preset.UpdateFromEngine(engine);
    FFBEngineTestAccess::SetInvertForce(engine, false);
    custom_preset.Apply(engine);
    ASSERT_FALSE(engine.m_invert_force); // Applying should NOT restore previous inversion
}
} // namespace FFBEngineTests

