#include <iostream>
#include <vector>
#include <queue>
#include <cmath> // For std::abs

// This code solves LeetCode problem 1046: Last Stone Weight
// Process: repeatedly smash the two heaviest stones until at most one remains
using namespace std;

class Solution {
public:
    int lastStoneWeight(vector<int>& stones) {
        // Use a max-heap to efficiently retrieve the largest elements
        priority_queue<int> heap;

        // Insert all stone weights into the heap
        for (int weight : stones) {
            heap.push(weight);
        }

        // Continue while there are at least two stones to smash
        while (heap.size() > 1) {
            // Extract the two heaviest stones
            int heavy1 = heap.top();
            heap.pop();
            int heavy2 = heap.top();
            heap.pop();

            // If they're not equal, push the difference back
            if (heavy1 != heavy2) {
                heap.push(abs(heavy1 - heavy2));
            }
            // If equal, both stones are destroyed (nothing pushed back)
        }

        // Return the remaining stone's weight or 0 if none left
        return heap.empty() ? 0 : heap.top();
    }
};

class Solution {
public:
    vector<vector<int>> minimumAbsDifference(vector<int>& arr) {
        int size = arr.size();
        sort(arr.begin(), arr.end());
        int currentDiff = 0;
        if (size < 2) return {};

        int minDiff = arr[1] - arr[0];
        for (int idx = 0; idx < size - 1; idx++) {
            currentDiff = arr[idx + 1] - arr[idx];
            minDiff = min(currentDiff, minDiff);
        }

        vector<vector<int>> result;
        for (int idx = 0; idx < size - 1; idx++) {
            if (arr[idx + 1] - arr[idx] == minDiff) {
                result.push_back({arr[idx], arr[idx + 1]});
            }
        }
        return result;
    }
};

#include <iostream>
#include <unordered_map>
#include <queue>
using namespace std;

// Function to locate the initial non-repeating character in a given string
char firstNonRepeatingChar(const string& input) {
    unordered_map<char, int> frequencyMap;
    queue<char> charOrder;

    // Track frequency of each character while preserving appearance order
    for (char c : input) {
        if (frequencyMap.find(c) == frequencyMap.end()) {
            frequencyMap[c] = 1;
            charOrder.push(c);
        } else {
            frequencyMap[c]++;
        }

        // Eliminate characters from the front that have duplicates
        while (!charOrder.empty() && frequencyMap[charOrder.front()] > 1) {
            charOrder.pop();
        }
    }

    return charOrder.empty() ? '\0' : charOrder.front();
}

// Demonstration of the function
int main() {
    string text = "level";
    char output = firstNonRepeatingChar(text);

    if (output != '\0') {
        cout << "The first non-repeating character is: " << output << endl;
    } else {
        cout << "No non-repeating character found." << endl;
    }

    return 0;
}

