#include "llvm/IR/GCStrategy.h"
#include "llvm/ADT/Twine.h"
#include "llvm/IR/BuiltinGCs.h"

using namespace llvm;

LLVM_INSTANTIATE_REGISTRY(GCRegistry)

GCStrategy::GCStrategy() = default;

std::unique_ptr<GCStrategy> llvm::getGCStrategy(const StringRef Name) {
  for (auto &Entry : GCRegistry::entries())
    if (Entry.getName() == Name)
      return Entry.instantiate();

  // Ensure all built-in garbage collectors are linked when LLVM is built as a static library.
  // The linker might discard the static constructors registering these GCs unless we reference
  // something from their compilation units. This function serves as such a reference point:
  // it's harmless and won't impact performance since execution will halt shortly anyway.
  llvm::linkAllBuiltinGCs();

  if (GCRegistry::begin() == GCRegistry::end()) {
    // Typically, the registry should contain at least the built-in GCs.
    // An empty registry likely indicates missing initialization of the Registry system.
    const std::string errorMsg =
        std::string("unsupported GC: ") + Name.str() +
        " (did you remember to link and initialize the library?)";
    report_fatal_error(Twine(errorMsg));
  } else {
    report_fatal_error(Twine(std::string("unsupported GC: ") + Name.str()));
  }
}

