int main()
{
    // Construct a JSON object with Italian translations
    const json data =
    {
        {"the good", "il buono"},
        {"the bad", "il cattivo"},
        {"the ugly", "il brutto"}
    };

    // Access and print the value associated with key "the ugly" using string_view
    std::cout << data.at("the ugly"sv) << '\n';

    // Handle type_error exception when calling at() on a non-object JSON value
    try
    {
        const json text = "I am a string";
        std::cout << text.at("the good"sv) << '\n';
    }
    catch (const json::type_error& err)
    {
        std::cout << err.what() << '\n';
    }

    // Handle out_of_range exception when accessing a non-existent key
    try
    {
        std::cout << data.at("the fast"sv) << '\n';
    }
    catch (const json::out_of_range& err)
    {
        std::cout << "out of range" << '\n';
    }
}

#include <stdio.h>
#include <conio.h>
#include <stdlib.h>

void area_square(int side) {
    printf("area of square= %d\n", side * side);
}

void perimeter_rectangle(int length, int width) {
    printf("perimeter of rectangle= %d\n", 2 * (length + width));
}

void area_circle(int radius) {
    printf("area of circle= %d\n", 3 * radius * radius); // Using 3 as approximation for pi
}

void max_of_three(int x, int y, int z) {
    int maximum = x;
    if (y > maximum) maximum = y;
    if (z > maximum) maximum = z;
    printf("max of 3 nos= %d\n", maximum);
}

void table_of_number(int num) {
    printf("table of %d:\n", num);
    for (int i = 1; i <= 10; i++) {
        printf("%d x %d = %d\n", num, i, num * i);
    }
}

int main() {
    int choice = 0, side, length, width, r, n1, n2, n3, number;

    while (choice != 6) {
        system("cls");
        printf("1. area of square\n");
        printf("2. perimeter of rectangle\n");
        printf("3. area of circle\n");
        printf("4. max of 3 nos\n");
        printf("5. table of number\n");
        printf("6. exit\n");
        printf("enter any choice: ");
        scanf("%d", &choice);

        switch(choice) {
            case 1:
                printf("enter any side: ");
                scanf("%d", &side);
                area_square(side);
                break;

            case 2:
                printf("enter length and breadth: ");
                scanf("%d %d", &length, &width);
                perimeter_rectangle(length, width);
                break;

            case 3:
                printf("enter radius: ");
                scanf("%d", &r);
                area_circle(r);
                break;

            case 4:
                printf("enter three numbers: ");
                scanf("%d %d %d", &n1, &n2, &n3);
                max_of_three(n1, n2, n3);
                break;

            case 5:
                printf("enter a number: ");
                scanf("%d", &number);
                table_of_number(number);
                break;

            case 6:
                printf("Exiting...\n");
                break;

            default:
                printf("Invalid choice! Please try again.\n");
        }

        printf("\nPress any key to continue...");
        getch();
    }

    return 0;
}

#include <iostream>
#include <functional>
#include <string>

// Standalone function
void standalone_func(int val) {
    std::cout << "standalone_func: " << val << std::endl;
}

// Callable struct
struct CallableStruct {
    void operator()(int val) const {
        std::cout << "CallableStruct: " << val << std::endl;
    }
};

// Class with various member functions
struct Device {
    void instance_method(int val) {
        std::cout << "Device::instance_method: " << val << std::endl;
    }

    void readonly_method(int val) const {
        std::cout << "Device::readonly_method: " << val << std::endl;
    }

    int state = 100;
};

void demonstrate_invoke fundamentals() {
    std::cout << "=== std::invoke Fundamentals ===" << std::endl;

    CallableStruct c;
    Device d;

    // Call free function
    std::invoke(standalone_func, 84);

    // Call functor
    std::invoke(c, 42);

    // Call lambda expression
    std::invoke([](int val) { std::cout << "LambdaExpr: " << val << std::endl; }, 20);

    // Call non-const member function using object reference
    std::invoke(&Device::instance_method, d, 10);

    // Call non-const member function using pointer to object
    std::invoke(&Device::instance_method, &d, 30);

    // Call const member function
    std::invoke(&Device::readonly_method, d, 50);

    // Retrieve member variable value
    int retrieved = std::invoke(&Device::state, d);
    std::cout << "Device::state = " << retrieved << std::endl;
}

void contrast_with_old_style() {
    std::cout << "\n=== Conventional vs std::invoke ===" << std::endl;

    Device d;

    // Old-style invocation
    std::cout << "Conventional:" << std::endl;
    d.instance_method(2);                   // Direct member call
    (d.*&Device::instance_method)(4);       // Pointer-to-member with reference
    (&d->*&Device::instance_method)(6);     // Pointer-to-member with pointer

    // Unified approach via std::invoke
    std::cout << "\nUsing std::invoke:" << std::endl;
    std::invoke(&Device::instance_method, d, 2);
    std::invoke(&Device::instance_method, &d, 4);
}

void integrate_with_std_function() {
    std::cout << "\n=== std::invoke combined with std::function ===" << std::endl;

    std::function<void(int)> wrapper = [](int val) {
        std::cout << "std::function wrapper: " << val << std::endl;
    };

    std::invoke(wrapper, 200);
}

void handle_reference_wrapper() {
    std::cout << "\n=== std::invoke handling std::reference_wrapper ===" << std::endl;

    Device d;
    auto wrapped = std::ref(d);

    std::invoke(&Device::instance_method, wrapped, 14);
}

int main() {
    demonstrate_invoke fundamentals();
    contrast_with_old_style();
    integrate_with_std_function();
    handle_reference_wrapper();

    std::cout << "\n=== Advantages ===" << std::endl;
    std::cout << "- Consistent calling mechanism across callable entities" << std::endl;
    std::cout << "- Eliminates need for .* and ->* operators" << std::endl;
    std::cout << "- Compatible with std::reference_wrapper objects" << std::endl;
    std::cout << "- Supports generic templates working with arbitrary callables" << std::endl;

    return 0;
}

#include "Base.h"
#include "Writer.h"

namespace Gorgon::Resource {

	// Resolve all child resources recursively
	void Base::Resolve(File &stream) {
		for(auto node = children.First(); node.IsValid(); ) {
			Base &child = *node;
			node.Next();
			child.Resolve(stream);
		}
	}

	// Prepare all child resources for usage
	void Base::Prepare() {
		for(auto &descendant : *this) {
			descendant.Prepare();
		}
	}

	// Discard all child resources
	void Base::Discard() {
		for(auto &descendant : *this) {
			descendant.Discard();
		}
	}

	Base::Base() : Children(children) { }

	Base::~Base() {
		cleanupChildren();
	}

	bool Base::DeleteResource() {
		--referenceCount;
		if(referenceCount > 0) return false;
		delete this;
		return true;
	}

	void Base::cleanupChildren() {
		for(auto node = children.First(); node.IsValid(); node.Next()) {
			if(!node->DeleteResource()) {
				// Ensure no dangling parent references remain
				if(node->parent == this) {
					node->parent = nullptr;
					node->root   = nullptr;
				}
			}
		}
		children.Clear();
	}

	void Base::Save(Writer &output) {
		ASSERT(output.IsGood(), "Writer is not ready for saving the resource");
		if(guid.IsEmpty())
			guid.New();

		store(output);
	}
}

