#include <ankerl/unordered_dense.h>
#include <app/doctest.h> // for ResultBuilder, TestCase, REQUIRE
#include <cstdint>     // for uint64_t
#include <memory>      // for shared_ptr, __unique_ptr_t, make...
#include <type_traits> // for declval

// Verify that hash of smart pointer equals hash of its raw pointer
template <typename SmartPtr>
void validate_hash(SmartPtr const& smart_ptr) {
    REQUIRE(ankerl::unordered_dense::hash<SmartPtr>{}(smart_ptr) ==
            ankerl::unordered_dense::hash<decltype(std::declval<SmartPtr>().get())>{}(smart_ptr.get()));
}

TEST_CASE("hash_smart_ptr") {
    validate_hash(std::unique_ptr<uint64_t>{});
    validate_hash(std::shared_ptr<uint64_t>{});
    validate_hash(std::make_shared<uint64_t>(456U));
    validate_hash(std::make_unique<uint64_t>(789U));
    validate_hash(std::make_unique<uint64_t>(uint64_t{999U}));
}

