#include "llvm/Analysis/IndirectCallPromotionAnalysis.h"
#include "llvm/IR/Instruction.h"
#include "llvm/ProfileData/InstrProf.h"
#include "llvm/Support/CommandLine.h"
#include "llvm/Support/Debug.h"
#include <memory>

using namespace llvm;

#define DEBUG_TYPE "pgo-icall-prom-analysis"

// Threshold (in percent) for the direct-call target relative to remaining unpromoted count
static cl::opt<unsigned> RemainingCountPercentThreshold(
    "icp-remaining-percent-threshold", cl::init(35), cl::Hidden,
    cl::desc("Percentage threshold against remaining unpromoted indirect call count"));

// Threshold (in percent) for the direct-call target relative to total call count
static cl::opt<unsigned>
    TotalCountPercentThreshold("icp-total-percent-threshold", cl::init(8),
                               cl::Hidden,
                               cl::desc("Percentage threshold against total "
                                        "call count for promotion"));

// Upper limit on number of targets promoted per indirect call site
static cl::opt<unsigned>
    MaxTargetsToPromote("icp-max-prom", cl::init(4), cl::Hidden,
                        cl::desc("Maximum number of promotion candidates per "
                                 "indirect call site"));

ICallPromotionAnalysis::ICallPromotionAnalysis() {
  ValueDataArray = std::make_unique<InstrProfValueData[]>(MaxTargetsToPromote);
}

bool ICallPromotionAnalysis::isProfitableForPromotion(uint64_t TargetCount,
                                                      uint64_t CallSiteTotal,
                                                      uint64_t RemainingCount) {
  return TargetCount * 100 >= RemainingCountPercentThreshold * RemainingCount &&
         TargetCount * 100 >= TotalCountPercentThreshold * CallSiteTotal;
}

// Heuristic: select top candidates for promotion, sorted by profile count.
// Stops when encountering a non-promotable candidate.
// Returns count of viable promotion targets.
uint32_t ICallPromotionAnalysis::selectPromotionCandidates(
    const Instruction *Inst, uint32_t NumEntries, uint64_t TotalCount) {
  ArrayRef<InstrProfValueData> EntryList(ValueDataArray.get(), NumEntries);
  LLVM_DEBUG(dbgs() << "\nAnalyzing callsite: " << *Inst
                    << "\nNumber of candidates: " << NumEntries << "\n");

  uint32_t Index = 0;
  uint64_t UnpromotedCount = TotalCount;

  for (; Index < MaxTargetsToPromote && Index < NumEntries; ++Index) {
    uint64_t Count = EntryList[Index].Count;
    assert(Count <= UnpromotedCount);

    LLVM_DEBUG(dbgs() << " Candidate #" << Index << ": count=" << Count
                      << ", function=" << EntryList[Index].Value << "\n");

    if (!isProfitableForPromotion(Count, TotalCount, UnpromotedCount)) {
      LLVM_DEBUG(dbgs() << " Skipped: cold target.\n");
      return Index;
    }

    UnpromotedCount -= Count;
  }
  return Index;
}

ArrayRef<InstrProfValueData>
ICallPromotionAnalysis::getEligibleTargets(
    const Instruction *Inst, uint32_t &NumEntries, uint64_t &TotalCount,
    uint32_t &NumSelected) {
  bool Success =
      getValueProfDataFromInst(*Inst, IPVK_IndirectCallTarget, MaxTargetsToPromote,
                               ValueDataArray.get(), NumEntries, TotalCount);
  if (!Success) {
    NumSelected = 0;
    return ArrayRef<InstrProfValueData>();
  }

  NumSelected = selectPromotionCandidates(Inst, NumEntries, TotalCount);
  return ArrayRef<InstrProfValueData>(ValueDataArray.get(), NumEntries);
}

