#include "app_state.hpp"
#include "curses_interface.hpp"
#include <boost/filesystem/operations.hpp>
#include <boost/filesystem/path.hpp>
#include <iostream>

int main(int argc, char * argv[])
{
    if (argc < 2) {
        std::cerr << "error: You must supply at least a filename.\n";
        return 1;
    }

    boost::filesystem::path file_path(argv[1]);
    if (!exists(file_path)) {
        std::cerr << "error: Could not access filename " << argv[1] << ".\n";
        return 1;
    }

    // Requirement of libcurses.
    std::locale::global(std::locale(""));
    curses_interface_t curses_if;

    // Read the dimensions, but only once; dynamic resizing is not supported.
    auto const window_dims = curses_if.screen_size();

    app_state_t app_state = {
        // Load buffer with file contents from command line argument
        load_buffer(file_path, curses_if.screen_size().col_),
        // Use simplified Emacs-style keybindings
        emacs_lite()
    };

    // Initial display render
    render(app_state.buffer_, window_dims);

    // Main event loop: blocks waiting for user input, updates state accordingly
    boost::optional<app_state_t> updated_state;
    while (
        (updated_state =
             update(std::move(app_state), curses_if.next_event()))) {
        app_state = *updated_state;
        render(app_state.buffer_, window_dims);
    }
}

