// Select OpenGL version for application
constexpr int opengl_ver = mplot::gl::version_4_1; // See mplot/gl/version.h for options

// Custom frame class inheriting from mplot::wx::Frame template
class AppFrame : public mplot::wx::Frame<opengl_ver>
{
public:
    AppFrame(const wxString& label) : mplot::wx::Frame<opengl_ver>(label)
    {
        auto mainLayout = new wxBoxSizer(wxVERTICAL);

        // Add OpenGL canvas to main layout
        mainLayout->Add(this->canvas, 1, wxEXPAND);

        // Bottom control area
        auto controlsLayout = new wxBoxSizer(wxHORIZONTAL);
        auto colorBtn = new wxButton(this, wxID_ANY, "Pick Color");
        controlsLayout->Add(colorBtn, 0, wxALL | wxALIGN_CENTER, FromDIP(12));
        controlsLayout->AddStretchSpacer(1);

        mainLayout->Add(controlsLayout, 0, wxEXPAND);
        SetSizerAndFit(mainLayout);

        // Handle button click to refresh canvas after color change
        colorBtn->Bind(wxEVT_BUTTON, [this]([[maybe_unused]] wxCommandEvent& evt) {
            wxColourData palette;
            wxColourDialog dlg(this, &palette);
            if (dlg.ShowModal() == wxID_OK) {
                this->canvas->Refresh();
            }
        });
    }

    // X-axis data storage (vvec supports vectorized math operations)
    sm::vvec<double> abscissa;

    // Offset for dynamic updates
    double offset = 0.025;

    // Pointer to GraphVisual instance
    mplot::GraphVisual<double, opengl_ver>* visual_graph = nullptr;

    // Update function: increment offset and regenerate sine curve
    void updateScene()
    {
        this->offset += 0.008;
        this->visual_graph->update(this->abscissa, (this->abscissa + this->offset).sin(), 0);
        // Signal reinitialization of VisualModel index 0
        this->canvas->needs_reinit = 0;
    }

    // Initialize visualization models after OpenGL context is ready
    void initVisualModels()
    {
        if (this->canvas->ready()) {
            // Create GraphVisual with origin offset
            auto gv = std::make_unique<mplot::GraphVisual<double, opengl_ver>>(sm::vec<float>({0.0f, 0.0f, 0.0f}));

            // Bind model to canvas visual system
            this->canvas->v.bindmodel(gv);

            // Enable 3D rendering
            gv->twodimensional(false);

            // Generate x-values: -π to π with 100 points
            this->abscissa.linspace(-sm::mathconst<double>::pi, sm::mathconst<double>::pi, 100);

            // Set initial sine data
            gv->setdata(this->abscissa, (this->abscissa + this->offset).sin());

            // Finalize model (requires active GL context)
            gv->finalize();

            // Transfer ownership to canvas and store pointer
            std::cout << "Attaching visual model to Canvas" << std::endl;
            this->visual_graph = this->canvas->v.addVisualModel(gv);
        } else {
            throw std::runtime_error("OpenGL context not initialized yet");
        }
    }
};

// Application class
class App : public wxApp
{
public:
    App() {}
    bool OnInit() override;
};

bool App::OnInit()
{
    if (!wxApp::OnInit()) return false;

    AppFrame* frame = new AppFrame("OpenGL Demo");
    frame->Show(true);
    frame->initVisualModels(); // Must be called after Show()

    return true;
}

wxIMPLEMENT_APP(App);

