#include "Transform/LowerSelect.h"
#include <llvm/IR/Constants.h>
#include <llvm/IR/Instructions.h>
#include <llvm/IR/Verifier.h>
#include <llvm/Support/Debug.h>
#define DEBUG_TYPE "lower-select"

// Convert a select instruction into conditional branches with explicit control flow.
// Splits the original block, creates separate blocks for true/false outcomes,
// and uses a PHI node to merge results at the join point.
static void rewrite(Instruction *Sel) {
  auto *Func = Sel->getFunction();
  auto *OrigBB = Sel->getParent();

  // Split the original block after the select instruction
  BasicBlock *JoinBB = OrigBB->splitBasicBlock(Sel, "");

  // Create new basic blocks for the true and false branches
  auto *TrueBB = BasicBlock::Create(Sel->getContext(), "", Func, JoinBB);
  BranchInst::Create(JoinBB, TrueBB);

  auto *FalseBB = BasicBlock::Create(Sel->getContext(), "", Func, JoinBB);
  BranchInst::Create(JoinBB, FalseBB);

  // Replace the original terminator with a conditional branch
  OrigBB->getTerminator()->eraseFromParent();
  BranchInst::Create(TrueBB, FalseBB, Sel->getOperand(0), OrigBB);

  // Build the PHI node to combine values from both branches
  auto *Phi = PHINode::Create(Sel->getType(), 2, "", Sel);
  Phi->addIncoming(Sel->getOperand(1), TrueBB);
  Phi->addIncoming(Sel->getOperand(2), FalseBB);

  // Replace all uses of the select instruction with the PHI node
  Sel->replaceAllUsesWith(Phi);
  Sel->eraseFromParent();
}

// New Pass Manager entry point: locate all non-pointer select instructions
// and replace them with equivalent if/else control structures.
PreservedAnalyses LowerSelectPass::run(Module &M, ModuleAnalysisManager &) {
  std::vector<SelectInst *> Candidates;

  // Collect all select instructions that are not pointer-typed
  for (auto &F : M) {
    for (auto &B : F) {
      for (auto &I : B) {
        if (I.getType()->isPointerTy())
          continue;
        if (auto *SI = dyn_cast<SelectInst>(&I)) {
          Candidates.push_back(SI);
        }
      }
    }
  }

  // Skip processing if no applicable selects found
  if (Candidates.empty())
    return PreservedAnalyses::all();

  // Transform each collected select instruction
  for (auto *Sel : Candidates)
    rewrite(Sel);

  // Verify module integrity after transformation
  if (verifyModule(M, &errs())) {
    llvm_unreachable("Error: Lowerselect fails...");
  }

  // CFG has been modified, so preserve no analyses
  return PreservedAnalyses::none();
}

#include <iostream>
#include <vector>
#include <string>
#include <algorithm>
using namespace std;

int main() {
    // Optimize standard I/O operations for performance
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int participants, rounds;
    // Check for successful input reading
    if (cin >> participants >> rounds) {
        // Weights for each participant, initialized to 1.0.
        // We use the Multiplicative Weights Update algorithm.
        vector<double> weights(participants, 1.0);

        // The penalty factor (beta).
        // A value in the range [0.8, 0.95] is typically effective for such problems.
        // It determines how quickly we discard experts who make mistakes.
        // beta = 0.9 provides a good balance between stability and adaptability.
        double decayFactor = 0.9; 
        string predictions;
        // Reserve memory to avoid reallocations
        predictions.reserve(participants);

        for (int round = 0; round < rounds; ++round) {
            cin >> predictions;

            double weightSumZero = 0.0;
            double weightSumOne = 0.0;

            // Calculate the weighted vote for '0' and '1'
            for (int idx = 0; idx < participants; ++idx) {
                if (predictions[idx] == '0') {
                    weightSumZero += weights[idx];
                } else {
                    weightSumOne += weights[idx];
                }
            }

            // Predict the outcome with the higher weighted sum
            int forecast = (weightSumOne > weightSumZero) ? 1 : 0;
            cout << forecast << endl; // endl flushes the output, required for interaction

            int actualResult;
            cin >> actualResult;

            // Update weights based on the actual outcome
            // Reduce the weight of participants who guessed incorrectly
            for (int idx = 0; idx < participants; ++idx) {
                int guessValue = predictions[idx] - '0';
                if (guessValue != actualResult) {
                    weights[idx] *= decayFactor;
                }
            }

            // Renormalize weights to prevent floating-point underflow
            // We track the maximum weight and scale up if it becomes too small.
            double maxWeight = 0.0;
            for (double val : weights) {
                if (val > maxWeight) maxWeight = val;
            }

            // If the maximum weight is very small, multiply all weights by a large factor
            if (maxWeight < 1e-150) {
                for (int idx = 0; idx < participants; ++idx) {
                    weights[idx] *= 1e150;
                }
            }
        }
    }
    return 0;
}

#include <gtest/gtest.h>
#include <jonssonic/core/common/circular_audio_buffer.h>
using namespace jnsc;

// Test buffer resizing and basic read/write operations
TEST(CircularAudioBufferTest, ResizeAndWriteRead) {
    CircularAudioBuffer<float> audioBuffer;
    audioBuffer.resize(2, 8);
    EXPECT_EQ(audioBuffer.getNumChannels(), 2u);
    EXPECT_EQ(audioBuffer.getBufferSize(), 8u);

    // Perform write and read operations
    audioBuffer.write(0, 1.0f);
    audioBuffer.write(1, 2.0f);
    EXPECT_FLOAT_EQ(audioBuffer.read(0, 0), 1.0f);
    EXPECT_FLOAT_EQ(audioBuffer.read(1, 0), 2.0f);
}

// Test circular behavior when data exceeds buffer capacity
TEST(CircularAudioBufferTest, WrapAround) {
    CircularAudioBuffer<float> audioBuffer;
    audioBuffer.resize(1, 4);

    // Write more elements than buffer size to trigger wrap-around
    for (int index = 0; index < 6; ++index)
        audioBuffer.write(0, float(index));

    // Verify most recent values are retained in correct order
    EXPECT_FLOAT_EQ(audioBuffer.read(0, 0), 5.0f);
    EXPECT_FLOAT_EQ(audioBuffer.read(0, 1), 4.0f);
    EXPECT_FLOAT_EQ(audioBuffer.read(0, 2), 3.0f);
    EXPECT_FLOAT_EQ(audioBuffer.read(0, 3), 2.0f);
}

// Test buffer clearing functionality
TEST(CircularAudioBufferTest, Clear) {
    CircularAudioBuffer<float> audioBuffer;
    audioBuffer.resize(1, 4);

    audioBuffer.write(0, 1.0f);
    audioBuffer.write(0, 2.0f);
    audioBuffer.clear();
    audioBuffer.write(0, 3.0f);

    EXPECT_FLOAT_EQ(audioBuffer.read(0, 0), 3.0f);
}

// Test multi-channel buffer operations
TEST(CircularAudioBufferTest, MultiChannel) {
    CircularAudioBuffer<float> audioBuffer;
    audioBuffer.resize(2, 4);

    for (int sampleIndex = 0; sampleIndex < 4; ++sampleIndex) {
        audioBuffer.write(0, float(sampleIndex));
        audioBuffer.write(1, float(sampleIndex + 10));
    }

    EXPECT_FLOAT_EQ(audioBuffer.read(0, 0), 3.0f);
    EXPECT_FLOAT_EQ(audioBuffer.read(1, 0), 13.0f);
    EXPECT_FLOAT_EQ(audioBuffer.read(0, 3), 0.0f);
    EXPECT_FLOAT_EQ(audioBuffer.read(1, 3), 10.0f);
}

