using namespace llvm;

namespace {

/// A plugin-based class that accepts a variadic list of plugin types.
/// Each plugin type must adhere to the following interface:
///  1) Its constructor should accept a `Function &f`. Typically, the plugin
///     will traverse the function to identify suitable candidates.
///  2) It must provide a member function with this exact signature and name:
///        void execute(std::vector<CandidateInfo> &Results);
///    where the plugin appends its findings to the vector argument.
///
/// Plugin implementations are declared in ValueProfilePlugins.inc
template <class... Ts> class PluginSequence;
/// The type PluginSequenceFinal represents the finalized plugin chain used by
/// ValueProfileCollectorImpl.
using PluginSequenceFinal = PluginSequence<VP_PLUGIN_LIST>;

template <> class PluginSequence<> {
public:
  PluginSequence(Function &F, TargetLibraryInfo &TLI) {}
  void fetch(InstrProfValueKind K, std::vector<CandidateInfo> &Results) {}
};

template <class PluginType, class... Ts>
class PluginSequence<PluginType, Ts...> : public PluginSequence<Ts...> {
  PluginType PluginInstance;
  using Parent = PluginSequence<Ts...>;
public:
  PluginSequence(Function &F, TargetLibraryInfo &TLI)
      : PluginSequence<Ts...>(F, TLI), PluginInstance(F, TLI) {}
  void fetch(InstrProfValueKind K, std::vector<CandidateInfo> &Results) {
    if (K == PluginType::Category)
      PluginInstance.execute(Results);
    Parent::fetch(K, Results);
  }
};

} // end anonymous namespace

/// ValueProfileCollectorImpl extends the functionality of PluginSequenceFinal.
class ValueProfileCollector::ValueProfileCollectorImpl : public PluginSequenceFinal {
public:
  using PluginSequenceFinal::PluginSequenceFinal;
};

ValueProfileCollector::ValueProfileCollector(Function &F,
                                             TargetLibraryInfo &TLI)
    : PImpl(new ValueProfileCollectorImpl(F, TLI)) {}

ValueProfileCollector::~ValueProfileCollector() = default;

std::vector<CandidateInfo>
ValueProfileCollector::get(InstrProfValueKind Kind) const {
  std::vector<CandidateInfo> Output;
  PImpl->fetch(Kind, Output);
  return Output;
}

#include <iostream>
#include <vector>
#include <string>
using namespace std;

int main() {
    // Grid dimensions
    int rows = 20;
    int cols = 20;

    // Output grid size
    cout << rows << " " << cols << endl;

    // Initialize the maze with walls ('0')
    vector<string> maze(rows, string(cols, '0'));

    // Build a snake-like layout to maximize path length
    // Horizontal paths on even rows (0, 2, ..., 18)
    // Vertical connectors on odd rows (1, 3, ..., 17)

    // Create horizontal corridors on even rows
    for (int r = 0; r <= 18; r += 2) {
        for (int c = 0; c < cols; ++c) {
            maze[r][c] = '1';
        }
    }

    // Add vertical connectors between consecutive corridors
    // Alternating left-to-right and right-to-left patterns
    for (int r = 0; r < 18; r += 2) {
        if ((r / 2) % 2 == 0) {
            // Even segment: connect at rightmost column
            maze[r + 1][cols - 1] = '1';
        } else {
            // Odd segment: connect at leftmost column
            maze[r + 1][0] = '1';
        }
    }

    // Add dead-end branches from the last corridor (row 18)
    // Place them in row 19 at every other column to avoid cycles
    for (int c = 0; c < cols; c += 2) {
        maze[rows - 1][c] = '1';
    }

    // Display the final maze
    for (int i = 0; i < rows; ++i) {
        cout << maze[i] << endl;
    }

    return 0;
}

