#include <iostream>
#include <vector>
#include <cmath>

// Upper bound for XOR values when n <= 10^7 (since 2^24 > 10^7)
const int MAX_POSSIBLE_XOR = 1 << 24;

// Static boolean array to track which XOR results have been seen; zero-initialized by default
bool xor_seen[MAX_POSSIBLE_XOR];

int main() {
    // Optimize I/O performance
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int limit;
    std::cin >> limit;

    std::vector<int> selected_numbers;
    // Pre-allocate memory to avoid repeated reallocations
    selected_numbers.reserve(3000);

    // Greedily construct the set of numbers
    for (int candidate = 1; candidate <= limit; ++candidate) {
        bool is_valid = true;

        // Verify that adding 'candidate' doesn't produce a duplicate XOR
        for (int existing : selected_numbers) {
            if (xor_seen[candidate ^ existing]) {
                is_valid = false;
                break;
            }
        }

        if (is_valid) {
            // Mark all new XORs involving 'candidate'
            for (int existing : selected_numbers) {
                xor_seen[candidate ^ existing] = true;
            }
            selected_numbers.push_back(candidate);
        }
    }

    // Output the count and elements of the resulting set
    std::cout << selected_numbers.size() << "\n";
    for (size_t idx = 0; idx < selected_numbers.size(); ++idx) {
        std::cout << selected_numbers[idx];
        if (idx != selected_numbers.size() - 1) {
            std::cout << " ";
        }
    }
    std::cout << "\n";

    return 0;
}

