#include <iostream>
#include <vector>
#include <numeric>
#include <algorithm>
#include <random>
#include <chrono>
using namespace std;

// Function to ask a query and handle termination
int inquire(int x, int y) {
    cout << "? " << x << " " << y << endl;
    int answer;
    cin >> answer;
    if (answer == -1) {
        exit(0);
    }
    return answer;
}

void process() {
    int size;
    if (!(cin >> size)) return;

    vector<int> players(size);
    iota(players.begin(), players.end(), 1);

    // Shuffle players to randomize order for better average performance
    mt19937 engine(chrono::steady_clock::now().time_since_epoch().count());
    shuffle(players.begin(), players.end(), engine);

    int suspect = -1;
    int limit = size - (size % 2);

    for (int idx = 0; idx < limit; idx += 2) {
        int a = players[idx];
        int b = players[idx + 1];

        int opinionAB = inquire(a, b);
        int opinionBA = inquire(b, a);

        if (opinionAB != opinionBA) {
            int witness;
            if (idx == 0) {
                witness = players[2];  // Safe since n >= 3
            } else {
                witness = players[0];  // Safe as first player is not in current pair
            }

            int opinionAW = inquire(a, witness);
            int opinionBW = inquire(b, witness);

            if (opinionAW != opinionBW) {
                // Case: One is Knight, one is Impostor
                // Knight tells truth about witness, Impostor lies
                // In initial comparison: Knight says 1 about Impostor, Impostor says 0 about Knight
                if (opinionAB == 0) {
                    suspect = a;
                } else {
                    suspect = b;
                }
            } else {
                // Case: One is Knave, one is Impostor
                // Both lie about witness, so opinions match
                // In initial comparison: Knave says 0 about Impostor, Impostor says 1 about Knave
                if (opinionAB == 1) {
                    suspect = a;
                } else {
                    suspect = b;
                }
            }

            cout << "! " << suspect << endl;
            return;
        }
    }

    // If no asymmetric pair found and size is odd, the last unpaired player is the impostor
    if (size % 2 == 1) {
        cout << "! " << players[size - 1] << endl;
    }
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int testCases;
    if (cin >> testCases) {
        while (testCases--) {
            process();
        }
    }

    return 0;
}

