void SeqArrangeJob::process(Ctl &ctl_state)
{
    class JobProcessingError : public std::exception
    {
    };

    try
    {
        m_arrange_impl->process_seq_arrange(
            [&](int current_progress)
            {
                ctl_state.update_status(current_progress, _u8L("Arranging for sequential print"));
                if (ctl_state.was_canceled())
                    throw JobProcessingError();
            });
    }
    catch (const JobProcessingError &)
    {
