/**
 * Module responsible for managing Android target platforms.
 */
class FAndroidTargetPlatformModule : public IAndroidTargetPlatformModule
{
public:
	/**
	 * Destructor - cleans up allocated platform instances.
	 */
	~FAndroidTargetPlatformModule()
	{
		for (ITargetPlatform* Platform : AllPlatforms)
		{
			delete Platform;
		}
		AllPlatforms.Empty();
		SingleFormatPlatforms.Empty();
		MultiFormatPlatforms.Empty();
	}

public:
	// Begin ITargetPlatformModule interface
	virtual TArray<ITargetPlatform*> GetTargetPlatforms() override
	{
		if (AllPlatforms.Num() == 0 && FAndroidTargetPlatform::IsUsable())
		{
			for (int32 Index = 0; Index < 2; Index++)
			{
				bool bIsClientMode = Index == 1;
				SingleFormatPlatforms.Add(new FAndroidTargetPlatform(bIsClientMode));
				SingleFormatPlatforms.Add(new FAndroid_ASTCTargetPlatform(bIsClientMode));
				SingleFormatPlatforms.Add(new FAndroid_DXTTargetPlatform(bIsClientMode));
				SingleFormatPlatforms.Add(new FAndroid_ETC2TargetPlatform(bIsClientMode));
				// These are referenced in NotifyMultiSelectedFormatsChanged, so maintain a separate list
				MultiFormatPlatforms.Add(new FAndroid_MultiTargetPlatform(bIsClientMode));
			}
			// Combine single and multi into one unified list
			AllPlatforms.Append(SingleFormatPlatforms);
			AllPlatforms.Append(MultiFormatPlatforms);
			// Initialize multi-platforms now that all individual platforms are available
			NotifyMultiSelectedFormatsChanged();
		}
		return AllPlatforms;
	}

	virtual void NotifyMultiSelectedFormatsChanged() override
	{
		for (FAndroid_MultiTargetPlatform* Platform : MultiFormatPlatforms)
		{
			Platform->LoadFormats(SingleFormatPlatforms);
		}
		// @todo multi needs to be passed this event!
	}
	// End ITargetPlatformModule interface

public:
	// Begin IModuleInterface interface
	virtual void StartupModule() override { }
	virtual void ShutdownModule() override { }
	// End IModuleInterface interface

private:
	/** Holds all target platforms. */
	TArray<ITargetPlatform*> AllPlatforms;
	TArray<FAndroidTargetPlatform*> SingleFormatPlatforms;
	TArray<FAndroid_MultiTargetPlatform*> MultiFormatPlatforms;
};

#undef LOCTEXT_NAMESPACE

IMPLEMENT_MODULE(FAndroidTargetPlatformModule, AndroidTargetPlatform);

