#include "llvm/Analysis/ScalarEvolutionNormalization.h"
#include "llvm/Analysis/LoopInfo.h"
#include "llvm/Analysis/ScalarEvolution.h"
#include "llvm/Analysis/ScalarEvolutionExpressions.h"
using namespace llvm;

// Different kinds of transformations that can be applied in the normalization process
enum TransformationType {
  // Apply normalization transformation
  ApplyNormalization,
  // Apply denormalization (inverse) transformation
  ApplyDenormalization
};

namespace {
struct NormalizationTransformer
    : public SCEVRewriteVisitor<NormalizationTransformer> {
  const TransformationType Mode;
  // NB! Predicate is a function_ref. Storing it here is safe only because
  // we carefully manage the lifetime of NormalizationTransformer.
  const NormalizePredTy Condition;

  NormalizationTransformer(TransformationType Mode, NormalizePredTy Condition,
                           ScalarEvolution &SE)
      : SCEVRewriteVisitor<NormalizationTransformer>(SE), Mode(Mode),
        Condition(Condition) {}

  const SCEV *visitAddRecExpr(const SCEVAddRecExpr *Expr);
};
} // namespace

const SCEV *
NormalizationTransformer::visitAddRecExpr(const SCEVAddRecExpr *AR) {
  SmallVector<const SCEV *, 8> NewOperands;
  transform(AR->operands(), std::back_inserter(NewOperands),
            [&](const SCEV *Operand) { return visit(Operand); });

  if (!Condition(AR))
    return SE.getAddRecExpr(NewOperands, AR->getLoop(), SCEV::FlagAnyWrap);

  // Normalization and denormalization involve adjusting expressions relative to loops
  if (Mode == ApplyDenormalization) {
    // Denormalization (partial increment) mirrors SCEVAddRecExpr::getPostIncExpr
    for (int idx = 0, limit = NewOperands.size() - 1; idx < limit; idx++)
      NewOperands[idx] = SE.getAddExpr(NewOperands[idx], NewOperands[idx + 1]);
  } else {
    assert(Mode == ApplyNormalization && "Only two modes supported!");

    // Normalization (partial decrement) requires careful handling due to step changes
    // Build result from least significant operand upward:
    //
    // Base case: single operand -> already normalized
    // Recursive case: subtract next-level normalized step from current coefficient

    for (int idx = NewOperands.size() - 2; idx >= 0; idx--)
      NewOperands[idx] = SE.getMinusSCEV(NewOperands[idx], NewOperands[idx + 1]);
  }

  return SE.getAddRecExpr(NewOperands, AR->getLoop(), SCEV::FlagAnyWrap);
}

const SCEV *llvm::normalizeForPostIncUse(const SCEV *Expression,
                                         const PostIncLoopSet &TargetLoops,
                                         ScalarEvolution &SE,
                                         bool VerifyInvertibility) {
  if (TargetLoops.empty())
    return Expression;

  auto Predicate = [&](const SCEVAddRecExpr *AR) {
    return TargetLoops.count(AR->getLoop());
  };

  const SCEV *NormalizedForm =
      NormalizationTransformer(ApplyNormalization, Predicate, SE).visit(Expression);

  const SCEV *DenormalizedForm = denormalizeForPostIncUse(NormalizedForm, TargetLoops, SE);

  // If invertibility check is enabled and denormalization fails to recover original
  if (VerifyInvertibility && DenormalizedForm != Expression)
    return nullptr;

  return NormalizedForm;
}

const SCEV *llvm::normalizeForPostIncUseIf(const SCEV *Expr, NormalizePredTy Pred,
                                           ScalarEvolution &SE) {
  return NormalizationTransformer(ApplyNormalization, Pred, SE).visit(Expr);
}

const SCEV *llvm::denormalizeForPostIncUse(const SCEV *Expr,
                                           const PostIncLoopSet &TargetLoops,
                                           ScalarEvolution &SE) {
  if (TargetLoops.empty())
    return Expr;

  auto Predicate = [&](const SCEVAddRecExpr *AR) {
    return TargetLoops.count(AR->getLoop());
  };

  return NormalizationTransformer(ApplyDenormalization, Predicate, SE).visit(Expr);
}

