namespace {
// Utility to expose a static token as a Python string.  Since directly
// wrapping tokens with def_readonly skips the C++ to Python conversion
// for TfToken, causing an error due to missing Python type info, we
// instead bind a callable wrapper.
class _StaticTokenBinder {
public:
    _StaticTokenBinder(const TfToken* t) : _tokenPtr(t) { }
    std::string operator()() const
    {
        return _tokenPtr->GetString();
    }
private:
    const TfToken* _tokenPtr;
};

template <typename U>
void
_RegisterToken(U& clazz, const char* attrName, const TfToken& tok)
{
    clazz.add_static_property(attrName,
                              boost::python::make_function(
                                  _StaticTokenBinder(&tok),
                                  boost::python::return_value_policy<
                                      boost::python::return_by_value>(),
                                  boost::mpl::vector1<std::string>()));
}
} // anonymous

void wrap{{ tokensPrefix }}Tokens()
{
    boost::python::class_<{{ tokensPrefix }}TokensType, boost::noncopyable>
        pyClass("Tokens", boost::python::no_init);
{% for token in tokens %}
    _RegisterToken(pyClass, "{{ token.id }}", {{ tokensPrefix }}Tokens->{{ token.id }});
{% endfor %}
}

