int main() {
    int exit_code = -1;
    try {
        mplot::ReadCurves reader("../../tests/trial.svg");
        sm::bezcurvepath<float> path = reader.getCorticalPath();
        path.computePoints(0.01f);
        std::vector<sm::bezcoord<float>> points = path.getPoints();
        std::cout << "Retrieved " << points.size() << " points via getPoints()" << std::endl;

        auto iter = points.begin();
        while (iter != points.end()) {
            std::cout << *iter << std::endl;
            ++iter;
        }

        // Expected values: 0.329310834408 0.849295854568 1.00672543049
        std::cout.precision(12);
        std::cout << "points[23] =  " << points[23].t()
                  << " " << points[23].x()
                  << " " << points[23].y()
                  << std::endl;

        if ((std::abs(points[23].t() - 0.329311) < 0.00001f) &&
            (std::abs(points[23].x() - 0.849296) < 0.00001f) &&
            (std::abs(points[23].y() - 1.00673) < 0.00001f)) {
            std::cout << "Values match expectation; exit_code set to 0" << std::endl;
            exit_code = 0;
        } else {
            std::cout << "exit_code remains non-zero" << std::endl;
        }
    } catch (const std::exception& ex) {
        std::cerr << "Exception encountered while reading trial.svg: " << ex.what() << std::endl;
        exit_code = -1;
    }
    return exit_code;
}

