XmlFuseWriter::XmlFuseWriter(QFile &outputFile) : XflXmlWriter(outputFile)
{
}

void XmlFuseWriter::writeHeader()
{
    writeDTD("<!DOCTYPE flow5>");
    writeStartElement("xflfuse");
    writeAttribute("version", "1.0");
    writeStartElement("Units");
    {
        writeTextElement("length_unit_to_meter", QString("%1").arg(1.0 / Units::mtoUnit()));
        writeTextElement("mass_unit_to_kg", QString("%1").arg(1.0 / Units::kgtoUnit()));
    }
    writeEndElement();
}

void XmlFuseWriter::writeXMLFuse(FuseXfl const *pComponent)
{
    writeStartDocument();
    writeHeader();
    writeStartElement("xflfuse");
    {
        writeTextElement("Name", pComponent->name());
        writeTextElement("Description", pComponent->description());
        writeComment("If the field AUTOINERTIA is set to TRUE, the fields COG and COG_I** will be ignored");
        writeTextElement("AutoInertia", xfl::boolToString(pComponent->bAutoInertia()));
        writeInertia(pComponent->inertia());
        writeEndElement();
        writeXflFuse(*pComponent, Vector3d());
    }
    writeEndElement();
    writeEndDocument();
}

