Rect::Rect(float posX, float posY, float sizeW, float sizeH) : x(posX), y(posY), width(sizeW), height(sizeH) { }

LayoutManager::LayoutManager(float posX, float posY, float sizeW, float sizeH) : m_current(posX, posY, sizeW, sizeH) {
}

const Rect& LayoutManager::current() const {
    return m_current;
}

LayoutManager LayoutManager::copy() const {
    return LayoutManager(m_current.x, m_current.y, m_current.width, m_current.height);
}

void LayoutManager::pad(float amount) {
    pad(amount, amount);
}

void LayoutManager::pad(float verticalPad, float horizontalPad) {
    m_current.x += horizontalPad;
    m_current.y += verticalPad;
    m_current.width -= horizontalPad * 2;
    m_current.height -= verticalPad * 2;
}

void LayoutManager::padLeft(float amount) {
    m_current.x += amount;
    m_current.width -= amount;
}

void LayoutManager::padRight(float amount) {
    m_current.width -= amount;
}

void LayoutManager::padUp(float amount) {
    m_current.y += amount;
    m_current.height -= amount;
}

void LayoutManager::padDown(float amount) {
    m_current.height -= amount;
}

void LayoutManager::border(float thickness) {
    m_current.x += thickness;
    m_current.y += thickness;
    m_current.width -= thickness * 2;
    m_current.height -= thickness * 2;
}

void LayoutManager::gapX(float spacing) {
    m_current.x += spacing;
    m_current.width -= spacing;
}

void LayoutManager::gapY(float spacing) {
    m_current.y += spacing;
    m_current.height -= spacing;
}

LayoutManager LayoutManager::sliceTop(float sliceHeight) {
    LayoutManager slice(m_current.x, m_current.y, m_current.width, sliceHeight);
    m_current.y += sliceHeight;
    m_current.height -= sliceHeight;
    return slice;
}

LayoutManager LayoutManager::sliceLeft(float sliceWidth) {
    LayoutManager slice(m_current.x, m_current.y, sliceWidth, m_current.height);
    m_current.x += sliceWidth;
    m_current.width -= sliceWidth;
    return slice;
}

#include <bits/stdc++.h>
using namespace std;

// Constructive solution generating a grid with at most 65 rows/columns
// that has exactly x distinct paths from top-left to bottom-right
// using only right/down moves through cells marked '1'
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long target;
    if (!(cin >> target)) return 0;

    const int SIZE = 65;
    vector<vector<int>> grid(SIZE, vector<int>(SIZE, 0));

    // Build base snake pattern:
    // For row i (1-indexed), place i consecutive 1s
    // Odd rows: left-aligned, even rows: right-aligned
    for (int row = 1; row <= SIZE; ++row) {
        if (row % 2 == 1) {
            for (int col = 1; col <= row; ++col) {
                grid[row-1][col-1] = 1;
            }
        } else {
            for (int col = 0; col < row; ++col) {
                grid[row-1][SIZE-1-col] = 1;
            }
        }
    }

    // Adjust paths by setting bits in remaining positions
    long long remaining = target - 1;
    for (int row = 2; row <= SIZE; ++row) {
        if (row % 2 == 1) {
            // Odd row: extend rightward if current bit is set
            if (remaining & 1) {
                for (int col = row + 1; col <= SIZE; ++col) {
                    grid[row-1][col-1] = 1;
                }
            }
        } else {
            // Even row: extend leftward if current bit is set
            if (remaining & 1) {
                for (int col = 1; col <= SIZE - row; ++col) {
                    grid[row-1][col-1] = 1;
                }
            }
        }
        remaining >>= 1;
        if (remaining == 0) break;
    }

    cout << SIZE << "\n";
    for (int r = 0; r < SIZE; ++r) {
        for (int c = 0; c < SIZE; ++c) {
            cout << grid[r][c];
            if (c + 1 < SIZE) cout << " ";
            else cout << "\n";
        }
    }

    return 0;
}

#include <hip/hip_runtime.h>
