#define HIP_ERROR_CHECK(expr)                        \
{                                                    \
    const hipError_t err = expr;                     \
    if (err != hipSuccess)                           \
    {                                                \
        std::cerr << "HIP error " << err             \
                << ": " << hipGetErrorString(err)    \
                << " at " << __FILE__ << ":"         \
                << __LINE__ << std::endl;            \
        std::exit(EXIT_FAILURE);                     \
    }                                                \
}

int main()
{
    hipMemPool_t memoryPool;
    hipDevice_t gpuDevice = 0; // Specify the device index.

    // Initialize the device.
    HIP_ERROR_CHECK(hipSetDevice(gpuDevice));

    // Get the default memory pool for the device.
    HIP_ERROR_CHECK(hipDeviceGetDefaultMemPool(&memoryPool, gpuDevice));

    // Allocate memory from the pool (e.g., 2 MB).
    std::size_t bufferSize = 2 * 1024 * 1024;
    void* bufferPtr;
    HIP_ERROR_CHECK(hipMalloc(&bufferPtr, bufferSize));

    // Free the allocated memory.
    HIP_ERROR_CHECK(hipFree(bufferPtr));

    // Trim the memory pool to a specific size (e.g., 768 KB).
    std::size_t targetSize = 768 * 1024;
    HIP_ERROR_CHECK(hipMemPoolTrimTo(memoryPool, targetSize));

    std::cout << "Memory pool trimmed to " << targetSize << " bytes." << std::endl;
    return EXIT_SUCCESS;
}

