// Execute a "move" operation with step size x and get the resulting node ID
int moveStep(long long stepSize) {
    std::cout << "move " << stepSize << std::endl;
    int nodeValue;
    std::cin >> nodeValue;
    return nodeValue;
}

// Submit a guess for the cycle length
void submitGuess(long long candidate) {
    std::cout << "answer " << candidate << std::endl;
}

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    // Block size parameter for Baby-step Giant-step method
    // Chosen as 32000, close to sqrt(1e9)
    const int BLOCK_SIZE = 32000;

    // Get initial position without moving
    int initialNode = moveStep(0);

    // --- Step 1: Baby steps ---
    // Record visited nodes and their distances from start
    std::unordered_map<int, int> visitedNodes;
    int currentNode = initialNode;

    for (int stepCount = 1; stepCount <= BLOCK_SIZE; ++stepCount) {
        currentNode = moveStep(1);

        // Check if we've returned to the starting node (cycle found quickly)
        if (currentNode == initialNode) {
            submitGuess(stepCount);
            return 0;
        }

        // Store first occurrence of each node
        if (visitedNodes.find(currentNode) == visitedNodes.end()) {
            visitedNodes[currentNode] = stepCount;
        }
    }

    // Now at distance BLOCK_SIZE from initial node

    // --- Step 2: Giant steps ---
    // Move in blocks of size BLOCK_SIZE and check for collisions
    for (int giantStep = 1; giantStep <= BLOCK_SIZE; ++giantStep) {
        currentNode = moveStep(BLOCK_SIZE);

        // Look for collision with baby-step recorded nodes
        if (visitedNodes.count(currentNode)) {
            int babyStepIndex = visitedNodes[currentNode];

            // Collision detected: positions match at different total distances
            // Total distance after giant steps: BLOCK_SIZE + giantStep * BLOCK_SIZE
            // This equals babyStepIndex modulo n
            // So n divides (BLOCK_SIZE * (giantStep + 1) - babyStepIndex)
            long long possibleN = (long long)(giantStep + 1) * BLOCK_SIZE - babyStepIndex;

            submitGuess(possibleN);
            return 0;
        }
    }

    return 0;
}

