#include <iostream>
#define SOL_ALL_SAFETIES_ON 1
#include <sol/sol.hpp>

struct custom_data {
    int value;
    bool flag;
};

template <typename Callback>
bool sol_lua_check(sol::types<custom_data>, lua_State* state,
     int position, Callback&& callback,
     sol::stack::record& usage_tracking) {
    int normalized_index = lua_absindex(state, position);

    bool result = sol::stack::check<int>(state, normalized_index, callback)
               && sol::stack::check<bool>(state, normalized_index + 1, callback);

    usage_tracking.use(2);
    return result;
}

custom_data sol_lua_get(sol::types<custom_data>, lua_State* state,
     int position, sol::stack::record& usage_tracking) {
    int normalized_index = lua_absindex(state, position);

    int extracted_value = sol::stack::get<int>(state, normalized_index);
    bool extracted_flag   = sol::stack::get<bool>(state, normalized_index + 1);

    usage_tracking.use(2);
    return custom_data { extracted_value, extracted_flag };
}

int sol_lua_push(lua_State* state, const custom_data& data) {
    int count = sol::stack::push(state, data.value);
    count += sol::stack::push(state, data.flag);
    return count;
}

int main() {
    std::cout << "=== customization ===" << std::endl;
    std::cout << std::boolalpha;

    sol::state vm;
    vm.open_libraries(sol::lib::base);

    vm.script("function process(x, y) print(x, y) return x, y end");

    sol::function processor = vm["process"];
    custom_data input{42, true};
    custom_data output = processor(input);

    SOL_ASSERT(output.value == 42);
    SOL_ASSERT(output.flag == true);

    std::cout << "output.value: " << output.value << std::endl;
    std::cout << "output.flag: " << output.flag << std::endl;
    std::cout << std::endl;

    return 0;
}

