#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

class PermutationHelper {
public:
    void computeNextPermutation(vector<int>& arr) {
        int size = arr.size();
        int pivotIndex = -1;

        // Step 1: Locate the rightmost position where arr[i] < arr[i+1]
        for (int idx = size - 2; idx >= 0; idx--) {
            if (arr[idx] < arr[idx + 1]) {
                pivotIndex = idx;
                break;
            }
        }

        if (pivotIndex == -1) {
            // No pivot found: array is in descending order, reverse to get smallest permutation
            reverse(arr.begin(), arr.end());
        } else {
            // Step 2: Find the rightmost element greater than arr[pivotIndex]
            for (int jdx = size - 1; jdx > pivotIndex; jdx--) {
                if (arr[jdx] > arr[pivotIndex]) {
                    swap(arr[jdx], arr[pivotIndex]);
                    break;
                }
            }

            // Step 3: Reverse the suffix after the pivot to get the next lexicographically smallest arrangement
            reverse(arr.begin() + pivotIndex + 1, arr.end());
        }
    }
};

int main() {
    PermutationHelper helper;
    vector<int> data = {2, 3, 7, 6, 5, 1};
    helper.computeNextPermutation(data);

    for (int pos = 0; pos < data.size(); pos++) {
        cout << data[pos] << " ";
    }
    return 0;
}

#include <vector>
#include <string>
#include <algorithm>

class Solution {
public:
    int minCost(std::string colors, std::vector<int>& neededTime) {
        int result = 0; // Total time required to remove balloons
        int left = 0, right = 0; // Two pointers to traverse the array

        // Process all balloons using sliding window approach
        while (left < neededTime.size() && right < neededTime.size()) {
            int groupSum = 0, groupMax = 0; // Sum and max removal time for current color group

            // Expand window to include all consecutive balloons of same color
            while (right < neededTime.size() && colors[left] == colors[right]) {
                groupSum += neededTime[right]; // Accumulate total time for this group
                groupMax = std::max(groupMax, neededTime[right]); // Track maximum time in group
                right++; // Move right pointer forward
            }

            // Add cost of removing all but the one with max time in this group
            result += groupSum - groupMax;
            left = right; // Start next group from where current group ended
        }

        return result; // Return minimum total time needed
    }
};

#include <iostream>
#include <asio.hpp>
#include <boost/bind.hpp>

// Timer callback function to print and schedule next tick
void timer_handler(const asio::error_code& /*ec*/,
    asio::steady_timer* timer_ptr, int* counter_ptr)
{
  if (*counter_ptr < 5)
  {
    std::cout << *counter_ptr << std::endl;
    ++(*counter_ptr);

    // Reschedule the timer for 1 second later
    timer_ptr->expires_at(timer_ptr->expiry() + asio::chrono::seconds(1));
    timer_ptr->async_wait(boost::bind(timer_handler,
          asio::placeholders::error, timer_ptr, counter_ptr));
  }
}

int main()
{
  asio::io_context service;
  int iteration_count = 0;

  // Create a steady timer with initial delay of 1 second
  asio::steady_timer delay_timer(service, asio::chrono::seconds(1));

  // Start asynchronous wait
  delay_timer.async_wait(boost::bind(timer_handler,
        asio::placeholders::error, &delay_timer, &iteration_count));

  // Run the I/O service until all operations complete
  service.run();

  std::cout << "Final count is " << iteration_count << std::endl;
  return 0;
}

#include <pangolin/pangolin.h>
#include <pangolin/log/packetstream_reader.h>
#include <pangolin/log/packetstream_writer.h>
#include <pangolin/video/video.h>

int main(int argc, char* argv[]) {
    if (argc == 3) {
        const std::string input_path = std::string(argv[1]);
        const std::string output_path = std::string(argv[2]);
        PANGO_ASSERT(input_path != output_path);

        pangolin::PacketStreamReader reader(input_path);
        pangolin::PacketStreamWriter writer(output_path);

        // Load JSON configuration from standard input
        picojson::value global_properties;
        std::cout << "Loading JSON metadata from stdin" << std::endl;
        std::cin >> global_properties;
        std::cout << "+ loaded successfully" << std::endl;

        PANGO_ASSERT(global_properties.size() == reader.Sources().size());

        for (size_t idx = 0; idx < reader.Sources().size(); ++idx) {
            const picojson::value& source_config = global_properties[idx];
            pangolin::PacketStreamSource src = reader.Sources()[idx];

            PANGO_ASSERT(source_config.contains("frame_properties"));
            PANGO_ASSERT(source_config.contains("device_properties"));
            PANGO_ASSERT(source_config["frame_properties"].size() == src.index.size());

            // Reset index and update device metadata
            src.index.clear();
            src.info["device"] = source_config["device_properties"];
            writer.AddSource(src);
        }

        std::cout << "Exporting video with updated metadata to '" << output_path << "'" << std::endl;

        try {
            std::vector<unsigned char> frame_buffer;
            while (true) {
                pangolin::Packet pkt = reader.NextFrame();
                frame_buffer.resize(pkt.BytesRemaining());
                pkt.Stream().read(frame_buffer.data(), frame_buffer.size());

                const picojson::value& updated_frame_meta = 
                    global_properties[pkt.src]["frame_properties"][pkt.sequence_num];

                writer.WriteSourcePacket(pkt.src, frame_buffer.data(), pkt.time, 
                                         frame_buffer.size(), updated_frame_meta);

                std::cout << "Processed frames: " << pkt.sequence_num 
                          << " / " << reader.Sources()[pkt.src].index.size() << "\r";
                std::cout.flush();
            }
        } catch (const std::runtime_error& err) {
            std::cout << "Processing error: " << err.what() << std::endl;
            throw err;
        }

        std::cout << std::endl << "+ completed" << std::endl;
    } else {
        std::cout << "Usage:\n\tPangolinVideoTransform input.pango output.pango" << std::endl;
    }

    return 0;
}

#ifndef __Pyx_CppExn2PyErr
#include <new>
#include <typeinfo>
#include <stdexcept>
#include <ios>

// Convert C++ exceptions to Python errors
static void __Pyx_ConvertCppExceptionToPython() {
    try {
        if (PyErr_Occurred())
            ; // let the latest Python exception pass through and ignore the current one
        else
            throw;
    } catch (const std::bad_alloc& exn) {
        PyErr_SetString(PyExc_MemoryError, exn.what());
    } catch (const std::bad_cast& exn) {
        PyErr_SetString(PyExc_TypeError, exn.what());
    } catch (const std::bad_typeid& exn) {
        PyErr_SetString(PyExc_TypeError, exn.what());
    } catch (const std::domain_error& exn) {
        PyErr_SetString(PyExc_ValueError, exn.what());
    } catch (const std::invalid_argument& exn) {
        PyErr_SetString(PyExc_ValueError, exn.what());
    } catch (const std::ios_base::failure& exn) {
        PyErr_SetString(PyExc_IOError, exn.what());
    } catch (const std::out_of_range& exn) {
        PyErr_SetString(PyExc_IndexError, exn.what());
    } catch (const std::overflow_error& exn) {
        PyErr_SetString(PyExc_OverflowError, exn.what());
    } catch (const std::range_error& exn) {
        PyErr_SetString(PyExc_ArithmeticError, exn.what());
    } catch (const std::underflow_error& exn) {
        PyErr_SetString(PyExc_ArithmeticError, exn.what());
    } catch (const std::exception& exn) {
        PyErr_SetString(PyExc_RuntimeError, exn.what());
    } catch (...) {
        PyErr_SetString(PyExc_RuntimeError, "Unknown exception");
    }
}
#endif

