#include <vector>
#include <unordered_map>

class Solution {
public:
    int findCenter(std::vector<std::vector<int>>& connections) {
        int rowCount = connections.size();
        int colCount = connections[0].size();
        std::unordered_map<int, int> frequencyMap;

        for (int row = 0; row < rowCount; row++) {
            for (int col = 0; col < colCount; col++) {
                int currentValue = connections[row][col];
                frequencyMap[currentValue]++;
            }
        }

        for (auto& entry : frequencyMap) {
            if (entry.second > 1) {
                return entry.first;
            }
        }
        return 1;
    }
};

