// Function to determine the two pens with lowest ink levels
void processTestCase() {
    int numPens;
    std::cin >> numPens;
    std::list<int> remainingPens;

    // Initialize list with all pen indices (0 to numPens-1)
    for (int idx = 0; idx < numPens; ++idx) {
        remainingPens.push_back(idx);
    }

    // Repeatedly eliminate pens until at most 2 remain
    while (remainingPens.size() > 2) {
        std::list<int> survivors;

        // Query each remaining pen to check if it should survive
        for (int currentPen : remainingPens) {
            std::cout << "0 " << currentPen << std::endl;
            int result;
            std::cin >> result;

            if (result == 1) {
                survivors.push_back(currentPen);
            }
        }

        remainingPens = survivors;

        // Stop early if we have 2 or fewer candidates left
        if (remainingPens.size() <= 2) {
            break;
        }
    }

    // Handle edge cases where fewer than 2 pens remain
    if (remainingPens.size() < 2) {
        if (remainingPens.empty()) {
            std::cout << "1 0 1" << std::endl;
        } else {
            int firstPen = remainingPens.front();
            int secondPen = (firstPen + 1) % numPens;
            std::cout << "1 " << firstPen << " " << secondPen << std::endl;
        }
        return;
    }

    // Output the final two pens
    int firstPen = remainingPens.front();
    remainingPens.pop_front();
    int secondPen = remainingPens.front();
    std::cout << "1 " << firstPen << " " << secondPen << std::endl;
}

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(NULL);

    int testCases;
    std::cin >> testCases;

    while (testCases--) {
        processTestCase();
    }

    return 0;
}

