namespace engine::store::filter::filesys::base {
//-------------------------------------------------------------------------
/// @details
///		Determines whether the stored object has been modified by comparing
///		current filesystem metadata with previously recorded values. If any
///		relevant field differs, the entry is flagged as changed and updated.
///	@param[inout] targetEntry
///		The entry whose state needs verification and possible update
///	@returns
///		Error code indicating success or failure of the check operation
//-------------------------------------------------------------------------
template <log::Lvl LvlT>
Error IBaseSysInstance<LvlT>::checkChanged(Entry &targetEntry) noexcept {
    WIN32_FIND_DATAW fileData;
    Error status;
    // Acquire the OS-specific path
    Text osPath;
    if (status = Url::osPath(targetEntry.url(), osPath)) return status;

    // Use FindFirstFileW to retrieve comprehensive file info, including reparse points
    HANDLE hSearch = FindFirstFileW(osPath.c_str(), &fileData);

    // Handle failure case — likely due to missing file
    if (hSearch == INVALID_HANDLE_VALUE) {
        return APERR(GetLastError(), _location,
                     "Failed to inspect file for changes");
    }

    FindClose(hSearch);

    // Assume no change initially
    targetEntry.changed(false);

    // Compare creation timestamp
    auto newCreateTime = _tr<time::SystemStamp>(fileData.ftCreationTime);
    if (targetEntry.createTime.get() != newCreateTime) {
        targetEntry.markChanged(LogLevel, "Creation time mismatch");
        targetEntry.createTime(newCreateTime);
    }

    // Compare last modification timestamp
    auto newModifyTime = _tr<time::SystemStamp>(fileData.ftLastWriteTime);
    if (targetEntry.modifyTime.get() != newModifyTime) {
        targetEntry.markChanged(LogLevel, "Modification time mismatch");
        targetEntry.modifyTime(newModifyTime);
    }

    // Update access time without marking as changed
    auto newAccessTime = _tr<time::SystemStamp>(fileData.ftLastAccessTime);
    if (targetEntry.accessTime.get() != newAccessTime) {
        targetEntry.accessTime(newAccessTime);
    }

    // Compare file attributes
    if (targetEntry.attrib() != fileData.dwFileAttributes) {
        targetEntry.markChanged(LogLevel, "File attributes altered");
        targetEntry.attrib(fileData.dwFileAttributes);
    }

    // Compute full size from high/low parts
    uint64_t fileSize =
        (static_cast<uint64_t>(fileData.nFileSizeHigh) << 32) |
        fileData.nFileSizeLow;

    if (targetEntry.size() != fileSize) {
        targetEntry.markChanged(LogLevel, "Logical size differs");
        targetEntry.size(fileSize);
    }

    // Retrieve physical space used on disk
    auto diskUsage = file::getSizeOnDisk(osPath, targetEntry.size(), targetEntry.attrib());

    uint64_t storeSizeVal;
    if (diskUsage.check()) {
        // Fallback to logical size if disk usage unavailable
        storeSizeVal = targetEntry.size();
    } else {
        storeSizeVal = *diskUsage;
    }

    if (targetEntry.storeSize() != storeSizeVal) {
        targetEntry.markChanged(LogLevel, "Storage footprint changed");
        targetEntry.storeSize(storeSizeVal);
    }

    return {};
}
}  // namespace engine::store::filter::filesys::base

#include <vector>

class Solution {
public:
    // Calculate the number of descent periods in price array
    long long getDescentPeriods(std::vector<int>& stockPrices) {
        const int length = stockPrices.size();
        long long totalPeriods = 1;
        long long currentDescent = 1;

        for (int index = 1; index < length; index++) {
            // Check if current price is exactly 1 less than previous (descent condition)
            currentDescent = ((stockPrices[index] + 1) == stockPrices[index - 1]) * currentDescent + 1;
            totalPeriods += currentDescent;
        }

        return totalPeriods;
    }
};

