#include <iostream>

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(NULL);

    int testCases;
    std::cin >> testCases;

    // This solution implements a naive string search algorithm.
    // The A=B program operates in distinct phases:
    //
    // Phase 1: Initialization (lowest priority rules)
    // Converts the source string s from lowercase to uppercase (A, B, C) for distinction from target t.
    // Rules such as `aS=AS` apply only initially since after conversion no lowercase letters precede S.
    //
    // Phase 2: Core Loop (higher priority rules)
    // Repeatedly attempts to align the prefix of the remaining uppercase string S' with the target t.
    //
    // Sub-phase 2a: Character Matching
    // Rules like `ASa=S` verify character equality. When matched, both characters are consumed,
    // proceeding iteratively through subsequent positions.
    //
    // Sub-phase 2b: Shift on Mismatch
    // Absence of applicable match rules indicates mismatch at current start position.
    // Program initiates shift by discarding first character of S'.
    // Implemented via state transitions: `AS=X`, `BS=X`, `CS=X` initiate process.
    // X propagates through remaining S' (`XA=AX`, etc.) and re-establishes separator S (`XS=S`).
    // Effectively removes leading character from S', restarting main loop.
    //
    // Phase 3: Conclusion
    // - If target t is fully consumed (`S` remains between S' and t), match succeeds.
    //   `S=(return)1` manages this success scenario.
    // - If S' exhausts before match completion (`S` appears at string start), t is not substring.
    //   `Sa=(return)0`, `Sb=(return)0`, `Sc=(return)0` handle failure cases.
    // --- Success Termination ---
    // Upon successful matching and consumption of t, resulting string consists of S' remnant followed by S,
    // or just S. In such case, S becomes leftmost match position.
    std::cout << "S=(return)1\n";
    // --- Failure Termination ---
    // When S' depletes, S resides at beginning followed by leftover portion of t, indicating failure.
    std::cout << "Sa=(return)0\n";
    std::cout << "Sb=(return)0\n";
    std::cout << "Sc=(return)0\n";
    // --- Core Loop: Single Character Match ---
    // These rules hold highest precedence among active search operations due to length criteria.
    // They match and consume one character each from S' and t.
    std::cout << "ASa=S\n";
    std::cout << "BSb=S\n";
    std::cout << "CSc=S\n";
    // --- Core Loop: Advance S' (on mismatch) ---
    // When no match rule applies, these trigger the "advance" mechanism.
    std::cout << "AS=X\n";
    std::cout << "BS=X\n";
    std::cout << "CS=X\n";
    // Auxiliary rules facilitate movement of temporary marker X across remaining S'.
    std::cout << "XA=AX\n";
    std::cout << "XB=BX\n";
    std::cout << "XC=CX\n";

    // Reinstate separator S, finalizing the "advance" operation.
    std::cout << "XS=S\n";
    // --- Initialization Phase ---
    // These rules possess lowest priority and execute solely during initial phase.
    // They transform s (lowercase) into S' (uppercase).
    std::cout << "aS=AS\n";
    std::cout << "bS=BS\n";
    std::cout << "cS=CS\n";

    return 0;
}

