class Solution {
public:
    int firstMissingPositive(vector<int>& nums) {
        int size = nums.size();

        // Normalize out-of-range values
        for(int idx = 0; idx < size; idx++) {
            if(nums[idx] <= 0 || nums[idx] > size + 1) {
                nums[idx] = size + 1;
            }
        }

        // Mark present numbers by negating their corresponding index
        for(int idx = 0; idx < size; idx++) {
            int position = abs(nums[idx]);
            if(position >= 1 && position <= size) {
                nums[position - 1] = -abs(nums[position - 1]);
            }
        }

        // Find first positive index which indicates missing number
        for(int idx = 0; idx < size; idx++) {
            if(nums[idx] > 0) {
                return idx + 1;
            }
        }

        return size + 1;   
    }
};

