namespace yams::search {

bool SearchFilters::matches(const SearchResultItem& entry) const {
    // Apply date filters
    for (const auto& filter : dateFilters_) {
        std::chrono::system_clock::time_point checkDate;
        switch (filter.field) {
            case DateRangeFilter::DateField::LastModified:
                checkDate = entry.lastModified;
                break;
            case DateRangeFilter::DateField::Created:
                // Assuming creation timestamp is stored in metadata
                // For now, use lastModified as fallback
                checkDate = entry.lastModified;
                break;
            case DateRangeFilter::DateField::Indexed:
                checkDate = entry.indexedAt;
                break;
        }
        if (!filter.matches(checkDate)) {
            return false;
        }
    }

    // Apply size constraints
    for (const auto& filter : sizeFilters_) {
        if (!filter.matches(entry.fileSize)) {
            return false;
        }
    }

    // Apply content type restrictions
    for (const auto& filter : contentTypeFilters_) {
        if (!filter.matches(entry.contentType)) {
            return false;
        }
    }

    // Apply language-based filters
    for (const auto& filter : languageFilters_) {
        if (!filter.matches(entry.detectedLanguage, entry.languageConfidence)) {
            return false;
        }
    }

    // Apply path-based filters
    for (const auto& filter : pathFilters_) {
        if (!filter.matches(entry.path)) {
            return false;
        }
    }

    // Apply metadata-based filters
    for (const auto& filter : metadataFilters_) {
        if (!filter.matches(entry.metadata)) {
            return false;
        }
    }

    // Apply relevance score filters
    for (const auto& filter : relevanceFilters_) {
        if (!filter.matches(entry.relevanceScore)) {
            return false;
        }
    }

    // Apply user-defined custom filters
    for (const auto& filter : customFilters_) {
        if (!filter(entry)) {
            return false;
        }
    }

    return true;
}

std::vector<SearchResultItem>
SearchFilters::apply(const std::vector<SearchResultItem>& candidates) const {
    if (!hasFilters()) {
        return candidates; // No active filters, return original list
    }

    std::vector<SearchResultItem> resultItems;
    resultItems.reserve(candidates.size());
    for (const auto& candidate : candidates) {
        if (matches(candidate)) {
            resultItems.push_back(candidate);
        }
    }
    return resultItems;
}

