#include <string>

// Global array to store counts of consecutive characters
int runLengths[100000] = {0};

class Solution {
public:
    // Count substrings with equal number of 0s and 1s in contiguous groups
    static int countBinarySubstrings(const std::string& input) {
        const int length = input.length();

        // Initialize first group count
        runLengths[0] = 1;
        int groupCount = 1;

        // Build groups of consecutive identical characters
        for (int index = 1; index < length; index++) {
            if (input[index] == input[index - 1]) {
                runLengths[groupCount - 1]++;
            } else {
                runLengths[groupCount++] = 1;
            }
        }

        // Count valid substrings by comparing adjacent groups
        int result = 0;
        for (int pos = 1; pos < groupCount; pos++) {
            result += std::min(runLengths[pos], runLengths[pos - 1]);
        }

        return result;
    }
};

