namespace engine::store::filter::filesys::base {
//-------------------------------------------------------------------------
/// @details
///		Determines whether the stored object has been modified by comparing
///		metadata such as timestamps, permissions, and size. If any changes
///		are detected, it updates the entry accordingly and flags it as changed.
///	@param[inout] entryObj
///		The entry representing the file to be validated for modifications
///	@returns
///		Error code indicating success or failure of the check operation
//-------------------------------------------------------------------------
template <log::Lvl LvlT>
Error IBaseSysInstance<LvlT>::checkChanged(Entry &entryObj) noexcept {
    Error errCode;
    // Acquire the OS-specific file path
    Text osFilePath;
    if (errCode = Url::osPath(entryObj.url(), osFilePath)) return errCode;

    auto statResult = ap::file::stat(osFilePath, true);
    if (!statResult) return statResult.ccode();

    auto fileStat = _mv(*statResult);

    // Assume no change initially
    entryObj.changed(false);

    // Compare creation time
    if (entryObj.createTime.get() != fileStat.createTime) {
        entryObj.markChanged(LogLevel, "Creation timestamp mismatch");
        entryObj.createTime(fileStat.createTime);
    }

    // Update access time without marking as changed
    if (entryObj.accessTime.get() != fileStat.accessTime) {
        entryObj.accessTime(fileStat.accessTime);
    }

    // Compare modification time
    if (entryObj.modifyTime.get() != fileStat.modifyTime) {
        entryObj.markChanged(LogLevel, "Modification timestamp mismatch");
        entryObj.modifyTime(fileStat.modifyTime);
    }

    // Compare file attributes (permissions)
    if (entryObj.attrib() != fileStat.plat.st_mode) {
        entryObj.markChanged(LogLevel, "File attributes have changed");
        entryObj.attrib(fileStat.plat.st_mode);
    }

    // Compare logical file size
    if (entryObj.size() != fileStat.size) {
        entryObj.markChanged(LogLevel, "File size differs");
        entryObj.size(fileStat.size);
    }

    // Compare physical disk space usage
    if (entryObj.storeSize() != fileStat.sizeOnDisk) {
        entryObj.markChanged(LogLevel, "Disk space usage differs");
        entryObj.storeSize(fileStat.sizeOnDisk);
    }

    return {};
}
}  // namespace engine::store::filter::filesys::base

