// Function to discover words using query-based strategy with exponential search
int main() {
    int T;
    if (cin >> T) {
        while (T--) {
            int total_words;
            if (!(cin >> total_words)) break;

            set<string> discovered;

            // Explore each letter from 'a' to 'z'
            for (char start_char = 'a'; start_char <= 'z'; ++start_char) {
                if (discovered.size() == total_words) break;

                string prefix(1, start_char);
                int current_count = 0;
                int query_size = 1;

                while (discovered.size() < total_words) {
                    if (query_size <= current_count) {
                        query_size *= 2;
                        continue;
                    }

                    int other_words = discovered.size() - current_count;
                    int max_possible = total_words - other_words;
                    int K = min(query_size, max_possible);

                    if (K <= current_count) {
                        query_size *= 2;
                        continue;
                    }

                    cout << "query " << prefix << " " << K << endl;
                    int received;
                    cin >> received;

                    for (int idx = 0; idx < received; ++idx) {
                        string word;
                        cin >> word;
                        discovered.insert(word);
                    }

                    current_count = received;

                    if (received < K) {
                        break;
                    }

                    if (discovered.size() == total_words) break;
                    query_size *= 2;
                }
            }

            cout << "answer";
            for (const string& word : discovered) {
                cout << " " << word;
            }
            cout << endl;
        }
    }
    return 0;
}

#include <iostream>
