// Vector to store the sequence of moves
std::vector<std::pair<int, int>> move_sequence;

/**
 * @brief Recursive function to solve the ball-moving puzzle using a Tower of Hanoi approach.
 * 
 * @param count The number of balls to move.
 * @param source The source basket.
 * @param target The destination basket.
 * @param helper The auxiliary basket.
 */
void solve_puzzle(int count, int source, int target, int helper) {
    if (count == 0) {
        return;
    }

    // Move count-1 balls from source to helper, using target as temporary storage
    solve_puzzle(count - 1, source, helper, target);

    // Record the move of the top ball from source to target
    move_sequence.push_back({source, target});

    // Move the count-1 balls from helper to target, using source as temporary storage
    solve_puzzle(count - 1, helper, target, source);
}

int main() {
    // Optimize standard I/O for faster execution
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int n_balls;
    std::cin >> n_balls;

    // Initial call to solve the problem for N balls from basket 1 to 3, using 2 as auxiliary
    solve_puzzle(n_balls, 1, 3, 2);

    // Output the total number of moves
    std::cout << move_sequence.size() << "\n";

    // Output each move in the sequence
    for (const auto& step : move_sequence) {
        std::cout << step.first << " " << step.second << "\n";
    }

    return 0;
}

