using namespace std;

// LeetCode 733: Flood Fill - Modified implementation
// This function performs depth-first search to fill connected pixels with new color
class Solution {
public:
    void dfsHelper(vector<vector<int>>& grid, int row, int col, int fillColor, int startColor) {
        // Boundary checks and termination conditions
        if (row < 0 || row >= grid.size() || col < 0 || col >= grid[0].size() || 
            grid[row][col] != startColor || grid[row][col] == fillColor) {
            return;
        }

        // Update current pixel color
        grid[row][col] = fillColor;

        // Recursively process all four adjacent directions
        dfsHelper(grid, row + 1, col, fillColor, startColor);
        dfsHelper(grid, row - 1, col, fillColor, startColor);
        dfsHelper(grid, row, col + 1, fillColor, startColor);
        dfsHelper(grid, row, col - 1, fillColor, startColor);
    }

    vector<vector<int>> floodFill(vector<vector<int>>& image, int startX, int startY, int newColor) {
        // Handle case where new color is same as original color
        if (image[startX][startY] == newColor) {
            return image;
        }

        dfsHelper(image, startX, startY, newColor, image[startX][startY]);
        return image;
    }
};

