#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

// Structure to record a swap operation between two positions
struct SwapRecord {
    int r1, c1, r2, c2;
};

int main() {
    // Speed up I/O operations
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    const int ROWS = 30;

    // Represent the pyramid as a vector of vectors
    vector<vector<int>> pyramid(ROWS);

    // Read input data into the pyramid structure
    for (int row = 0; row < ROWS; ++row) {
        pyramid[row].reserve(row + 1);
        for (int col = 0; col <= row; ++col) {
            int value;
            cin >> value;
            pyramid[row].push_back(value);
        }
    }

    vector<SwapRecord> operations;
    // Reserve sufficient capacity to avoid reallocations
    // Upper bound: maximum possible swaps for ROWS=30 is 4495, so 10000 is safe
    operations.reserve(10000);

    // Build min-heap from bottom-up: start from second-to-last row and move upward
    // Leaf nodes (last row) are already valid heaps by themselves
    for (int level = ROWS - 2; level >= 0; --level) {
        for (int index = 0; index <= level; ++index) {
            int current_row = level;
            int current_col = index;

            // Sift-down process: move the element down until heap property is restored
            while (current_row < ROWS - 1) {
                int child_left_row = current_row + 1;
                int child_left_col = current_col;
                int child_right_row = current_row + 1;
                int child_right_col = current_col + 1;

                int val_current = pyramid[current_row][current_col];
                int val_left_child = pyramid[child_left_row][child_left_col];
                int val_right_child = pyramid[child_right_row][child_right_col];

                // Check if parent is smaller than both children (min-heap condition)
                if (val_current < val_left_child && val_current < val_right_child) {
                    break;
                }

                // Otherwise, swap with the smaller child
                if (val_left_child < val_right_child) {
                    operations.push_back({current_row, current_col, child_left_row, child_left_col});
                    swap(pyramid[current_row][current_col], pyramid[child_left_row][child_left_col]);
                    current_row = child_left_row;
                    current_col = child_left_col;
                } else {
                    operations.push_back({current_row, current_col, child_right_row, child_right_col});
                    swap(pyramid[current_row][current_col], pyramid[child_right_row][child_right_col]);
                    current_row = child_right_row;
                    current_col = child_right_col;
                }
            }
        }
    }

    // Output number of swaps followed by each swap operation
    cout << operations.size() << "\n";
    for (const auto& op : operations) {
        cout << op.r1 << " " << op.c1 << " " << op.r2 << " " << op.c2 << "\n";
    }

    return 0;
}

#include <iostream>

class Solution {
public:
    int solveTower(int disks, int source, int destination, int auxiliary) {
        // Base case: single disk requires one move
        if (disks == 1) {
            return 1;
        }

        // Recursive case: move n-1 disks to auxiliary, 
        // move nth disk, then move n-1 disks from auxiliary to destination
        int moves = solveTower(disks - 1, source, auxiliary, destination);
        moves += 1;
        moves += solveTower(disks - 1, auxiliary, destination, source);

        return moves;
    }
};

