namespace quantclaw::cli {

CLIManager::CLIManager() = default;

void CLIManager::RegisterCommand(const Command& cmd) {
    available_commands_.push_back(cmd);
}

int CLIManager::Execute(int argc, char** argv) {
    if (argc < 2) {
        DisplayHelp();
        return 1;
    }

    std::string requested_command = argv[1];

    // Process global options
    if (requested_command == "--version" || requested_command == "-v") {
        std::cout << "quantclaw " << kVersion
                  << " (compiled " << kGitCommit << " " << kBuildDate << ")"
                  << std::endl;
        return 0;
    }

    if (requested_command == "--help" || requested_command == "-h") {
        DisplayHelp();
        return 0;
    }

    // Locate and execute the requested command
    for (const auto& cmd : available_commands_) {
        if (cmd.name == requested_command ||
            std::find(cmd.aliases.begin(), cmd.aliases.end(), requested_command) != cmd.aliases.end()) {
            char** sub_argv = &argv[1];
            int sub_argc = argc - 1;
            return cmd.callback(sub_argc, sub_argv);
        }
    }

    std::cerr << "Unknown command: " << requested_command << std::endl;
    DisplayHelp();
    return 1;
}

void CLIManager::DisplayHelp() const {
    std::cout << "QuantClaw - High-performance C++ AI assistant" << std::endl;
    std::cout << std::endl;
    std::cout << "Syntax: quantclaw <command> [arguments]" << std::endl;
    std::cout << std::endl;
    std::cout << "Available commands:" << std::endl;
    for (const auto& cmd : available_commands_) {
        std::cout << "  " << cmd.name;
        if (!cmd.aliases.empty()) {
            std::cout << " (";
            for (size_t idx = 0; idx < cmd.aliases.size(); ++idx) {
                if (idx > 0) std::cout << ", ";
                std::cout << cmd.aliases[idx];
            }
            std::cout << ")";
        }
        std::cout << "\t" << cmd.summary << std::endl;
    }
    std::cout << std::endl;
    std::cout << "Global options:" << std::endl;
    std::cout << "  --version, -v\tShow version information" << std::endl;
    std::cout << "  --help, -h\tDisplay this help message" << std::endl;
    std::cout << "  --json\tEnable JSON output format" << std::endl;
    std::cout << std::endl;
    std::cout << "Usage examples:" << std::endl;
    std::cout << "  quantclaw gateway              Launch gateway in foreground mode" << std::endl;
    std::cout << "  quantclaw gateway install       Register gateway as a system service" << std::endl;
    std::cout << "  quantclaw gateway status         Check current gateway status" << std::endl;
    std::cout << "  quantclaw agent -m \"Hi there\"   Send a message to the agent" << std::endl;
    std::cout << "  quantclaw sessions list          Show all active sessions" << std::endl;
    std::cout << "  quantclaw health                 Perform system health verification" << std::endl;
    std::cout << "  quantclaw config get gateway.port Retrieve specific configuration value" << std::endl;
}

