// Static file pointer for logging, local to this translation unit
static FILE *log_stream = nullptr;
// Pointer to global application configuration
static const AppSettings *g_config = nullptr;

void log_configure_settings(const AppSettings *config) {
    g_config = config;
}

void log_initialize(bool is_overlay_mode) {
    const char *log_path = is_overlay_mode ? "advancely_overlay_trace.txt" : "advancely_trace.txt";

    // Open log file in write mode to reset contents on startup
    log_stream = fopen(log_path, "w");
    if (log_stream == nullptr) {
        fprintf(stderr, "CRITICAL: Unable to open trace file advancely_trace.txt\n");
        return;
    }

    // Insert timestamp into the log
    const time_t current_time = time(nullptr);
    char timestamp_buffer[64];
    strftime(timestamp_buffer, sizeof(timestamp_buffer), "%Y-%m-%d %H:%M:%S", localtime(&current_time));

    // Select appropriate header based on process type
    const char* header_format = is_overlay_mode ?
                                "Advancely Overlay Trace - %s\n" :
                                "Advancely Trace - %s\n";

    fprintf(log_stream, header_format, timestamp_buffer);
    fprintf(log_stream, "========================================\n\n");
    fflush(log_stream); // Flush immediately to ensure header appears
}

void log_write(LogLevel priority, const char *template_str, ...) {
    // Skip informational messages unless debug output is enabled
    if (priority == LOG_INFO && (g_config == nullptr || !g_config->print_debug_status)) {
        return;
    }

    // Buffer for formatted message content
    char output_buffer[4096];
    va_list argument_list;

    // Format the incoming message
    va_start(argument_list, template_str);
    vsnprintf(output_buffer, sizeof(output_buffer), template_str, argument_list);
    va_end(argument_list);

    // Output to console with optional color coding
    if (priority == LOG_ERROR) {
#ifdef _WIN32
        HANDLE hStdErr = GetStdHandle(STD_ERROR_HANDLE);
        CONSOLE_SCREEN_BUFFER_INFO buffer_info;
        WORD original_color;

        GetConsoleScreenBufferInfo(hStdErr, &buffer_info);
        original_color = buffer_info.wAttributes;

        SetConsoleTextAttribute(hStdErr, FOREGROUND_RED | FOREGROUND_INTENSITY);
        fprintf(stderr, "%s", output_buffer);

        SetConsoleTextAttribute(hStdErr, original_color);
#else
        fprintf(stderr, "\033[91m%s\033[0m", output_buffer);
#endif
    } else {
        printf("%s", output_buffer);
    }

    // Write to log file if available, including timestamp
    if (log_stream != nullptr) {
        char time_buf[16];
        time_t now = time(0);
        strftime(time_buf, sizeof(time_buf), "%H:%M:%S", localtime(&now));
        fprintf(log_stream, "[%s] %s", time_buf, output_buffer);
        fflush(log_stream); // Force flush for crash resilience
    }
}

void log_shutdown(void) {
    if (log_stream != nullptr) {
        fprintf(log_stream, "\n========================================\n");
        fprintf(log_stream, "Trace session ended.\n");
        fclose(log_stream);
        log_stream = nullptr;
    }
}

