// Function to demonstrate reading lines from a file using getline
void demoGetline() {
    std::ifstream inputFile("users.txt");
    if (!inputFile) return;

    const int BUFFER_LENGTH = 128;
    char lineBuffer[BUFFER_LENGTH];

    // Read lines until newline or up to BUFFER_LENGTH - 1 characters
    while (inputFile.getline(lineBuffer, BUFFER_LENGTH)) {
        std::cout << "Read line: " << lineBuffer << std::endl;
    }

    // Check if the stream failed due to a line being too long
    if (inputFile.fail() && !inputFile.eof()) {
