        inputFile.clear();
    }
}

#include "asio/buffer.hpp"
#include "asio/connect.hpp"
#include "asio/io_context.hpp"
#include "asio/ip/tcp.hpp"
#include "asio/read_until.hpp"
#include "asio/system_error.hpp"
#include "asio/write.hpp"
#include <cstdlib>
#include <iostream>
#include <string>
#include <chrono>

using asio::ip::tcp;

//----------------------------------------------------------------------
//
// This class manages socket deadlines by running the io_context using the timed
// io_context::run_for() member function. Each asynchronous operation is given
// a deadline within which it must complete. The socket operations themselves
// use lambdas as completion handlers. For a given socket operation, the client
// object runs the io_context to block thread execution until the operation
// completes or the deadline is reached. If the io_context::run_for() function
// times out, the socket is closed and the outstanding asynchronous operation
// is cancelled.
//
class client_connection
{
public:
  void establish_connection(const std::string& hostname, const std::string& port_number,
      std::chrono::steady_clock::duration limit)
  {
    // Resolve the host name and service to a list of endpoints.
    auto result = tcp::resolver(io_context_).resolve(hostname, port_number);
    // Start the asynchronous operation itself. The lambda that is used as a
    // callback will update the err variable when the operation completes.
    std::error_code err;
    asio::async_connect(my_socket, result,
        [&](const std::error_code& op_result,
            const tcp::endpoint& /*ignored_endpoint*/)
        {
          err = op_result;
        });
    // Run the operation until it finishes, or until the deadline.
    execute_with_timeout(limit);
    // Determine whether a connection was successfully established.
    if (err)
      throw std::system_error(err);
  }

  std::string fetch_line(std::chrono::steady_clock::duration limit)
  {
    // Start the asynchronous operation. The lambda that is used as a callback
    // will update the err and bytes_read variables when the operation completes.
    std::error_code err;
    std::size_t bytes_read = 0;
    asio::async_read_until(my_socket,
        asio::dynamic_buffer(buffer_), '\n',
        [&](const std::error_code& op_result,
            std::size_t op_bytes_read)
        {
          err = op_result;
          bytes_read = op_bytes_read;
        });
    // Run the operation until it finishes, or until the deadline.
    execute_with_timeout(limit);
    // Determine whether the read completed successfully.
    if (err)
      throw std::system_error(err);
    std::string line(buffer_.substr(0, bytes_read - 1));
    buffer_.erase(0, bytes_read);
    return line;
  }

  void send_line(const std::string& message,
      std::chrono::steady_clock::duration limit)
  {
    std::string payload = message + "\n";
    // Start the asynchronous operation itself. The lambda that is used as a
    // callback will update the err variable when the operation completes.
    std::error_code err;
    asio::async_write(my_socket, asio::buffer(payload),
        [&](const std::error_code& op_result,
            std::size_t /*ignored_bytes_written*/)
        {
          err = op_result;
        });
    // Run the operation until it finishes, or until the deadline.
    execute_with_timeout(limit);
    // Determine whether the write completed successfully.
    if (err)
      throw std::system_error(err);
  }

private:
  void execute_with_timeout(std::chrono::steady_clock::duration limit)
  {
    // Restart the io_context, as it may have been left in the "stopped" state
    // by a previous operation.
    io_context_.restart();
    // Block until the asynchronous operation has completed, or timed out. If
    // the pending asynchronous operation is a composed operation, the deadline
    // applies to the entire operation, rather than individual operations on
    // the socket.
    io_context_.run_for(limit);
    // If the asynchronous operation completed successfully then the io_context
    // would have been stopped due to running out of work. If it was not
    // stopped, then the io_context::run_for call must have timed out.
    if (!io_context_.stopped())
    {
      // Close the socket to cancel the outstanding asynchronous operation.
      my_socket.close();
      // Run the io_context again until the operation completes.
      io_context_.run();
    }
  }

  asio::io_context io_context_;
  tcp::socket my_socket{io_context_};
  std::string buffer_;
};

//----------------------------------------------------------------------
int main(int argc, char* argv[])
{
  try
  {
    if (argc != 4)
    {
      std::cerr << "Usage: blocking_tcp_client <host> <port> <message>\n";
      return 1;
    }

    client_connection conn;
    conn.establish_connection(argv[1], argv[2], std::chrono::seconds(10));

    auto start_time = std::chrono::steady_clock::now();
    conn.send_line(argv[3], std::chrono::seconds(10));

    for (;;)
    {
      std::string response = conn.fetch_line(std::chrono::seconds(10));
      // Keep going until we get back the line that was sent.
      if (response == argv[3])
        break;
    }

    auto end_time = std::chrono::steady_clock::now();
    std::cout << "Round trip time: ";
    std::cout << std::chrono::duration_cast<
      std::chrono::microseconds>(
        end_time - start_time).count();
    std::cout << " microseconds\n";
  }
  catch (std::exception& ex)
  {
    std::cerr << "Error: " << ex.what() << "\n";
  }

  return 0;
}

