#include <assert.h>
#include <mpi.h>
#include <stdio.h>
#include <stdlib.h>
#include <time.h>

// Generates an array of random floating-point values in the range [0, 1]
float*
generate_random_values(int count)
{
    float* values = (float*) malloc(sizeof(float) * count);
    assert(values != NULL);
    for (int idx = 0; idx < count; idx++) {
        values[idx] = (rand() / (float) RAND_MAX);
    }
    return values;
}

// Calculates the arithmetic mean of a given array
float
calculate_mean(float* data, int length)
{
    float accumulator = 0.0f;
    for (int i = 0; i < length; i++) {
        accumulator += data[i];
    }
    return accumulator / length;
}

int
main(int argc, char** argv)
{
    if (argc != 2) {
        fprintf(stderr, "Usage: avg num_elements_per_process\n");
        exit(1);
    }

    int elements_per_process = atoi(argv[1]);

    // Initialize random seed for varied results
    srand(time(NULL));

    MPI_Init(NULL, NULL);

    int my_rank;
    MPI_Comm_rank(MPI_COMM_WORLD, &my_rank);

    int total_processes;
    MPI_Comm_size(MPI_COMM_WORLD, &total_processes);

    // Root process allocates and populates the full dataset
    float* full_dataset = NULL;
    if (my_rank == 0) {
        full_dataset = generate_random_values(elements_per_process * total_processes);
    }

    // Each process allocates memory for its local portion
    float* local_data = (float*) malloc(sizeof(float) * elements_per_process);
    assert(local_data != NULL);

    // Distribute data across processes
    MPI_Scatter(full_dataset, elements_per_process, MPI_FLOAT,
                local_data, elements_per_process, MPI_FLOAT, 0, MPI_COMM_WORLD);

    // Compute local average
    float local_avg = calculate_mean(local_data, elements_per_process);

    // Gather all local averages to root
    float* local_averages = NULL;
    if (my_rank == 0) {
        local_averages = (float*) malloc(sizeof(float) * total_processes);
        assert(local_averages != NULL);
    }

    MPI_Gather(&local_avg, 1, MPI_FLOAT,
               local_averages, 1, MPI_FLOAT, 0, MPI_COMM_WORLD);

    // Final average calculation on root process
    if (my_rank == 0) {
        float overall_avg = calculate_mean(local_averages, total_processes);
        printf("Overall average is %f\n", overall_avg);

        // Verify against direct computation on original data
        float reference_avg =
            calculate_mean(full_dataset, elements_per_process * total_processes);
        printf("Reference average from full data is %f\n", reference_avg);

        free(full_dataset);
        free(local_averages);
    }

    free(local_data);
    MPI_Barrier(MPI_COMM_WORLD);
    MPI_Finalize();
}

