// Evaluate logical connectives (expected results: true/false)
void evaluate_logical_connectives(SMTParser::ParserPtr& parser) {
    std::vector<std::pair<std::string, bool>> scenarios = {
        {"(not true)", false},
        {"(not false)", true},
        {"(and true true)", true},
        {"(and true false)", false},
        {"(and false false)", false},
        {"(or true true)", true},
        {"(or true false)", true},
        {"(or false false)", false},
        {"(=> true true)", true},
        {"(=> true false)", false},
        {"(=> false true)", true},
        {"(=> false false)", true},
        {"(xor true true)", false},
        {"(xor true false)", true},
        {"(xor false false)", false}
    };

    std::cout << "=== Evaluating Logical Connectives ===" << std::endl;
    for (const auto& item : scenarios) {
        std::cout << "Expression: " << item.first << std::endl;
        std::shared_ptr<SMTParser::DAGNode> evaluation = parser->mkExpr(item.first);
        assert(evaluation);
        assert(evaluation->isTrue() == item.second || evaluation->isFalse() == !item.second);
        std::cout << "  Output: " << parser->toString(evaluation) << std::endl;
        std::cout << std::endl;
    }
}

// Assess intricate boolean formulas
void assess_complex_formulas(SMTParser::ParserPtr& parser) {
    std::vector<std::pair<std::string, bool>> test_cases = {
        {"(and (or true false) (not false))", true},
        {"(or (and true false) (not true))", false},
        {"(=> (or true false) (and true true))", true},
        {"(xor (not false) (and true false))", true},
        {"(and (=> true false) (or false true))", false},
        {"(not (and (or true false) (=> false true)))", false}
    };

    std::cout << "=== Assessing Complex Boolean Formulas ===" << std::endl;
    for (const auto& entry : test_cases) {
        std::cout << "Expression: " << entry.first << std::endl;
        std::shared_ptr<SMTParser::DAGNode> computed = parser->mkExpr(entry.first);
        assert(computed);
        assert(computed->isTrue() == entry.second || computed->isFalse() == !entry.second);
        std::cout << "  Output: " << parser->toString(computed) << std::endl;
        std::cout << std::endl;
    }
}

int main() {
    std::cout << "======= Boolean Logic Evaluation Test =======" << std::endl;

    SMTParser::ParserPtr parser = SMTParser::newParser();

    verify_boolean_literals(parser);
    evaluate_logical_connectives(parser);
    assess_complex_formulas(parser);

    return 0;
}

#include "clam/clam.h"
/*
  Even after applying loop peeling, the array_adaptive domain (used by option
  sing-mem) lacks sufficient precision in this scenario. Suppose we peel one
  iteration of the loop. Prior to entering the loop, we know that
  0 <= a[0..3] <= 5. After one iteration, we have 0 <= a[0..3] <= 5 and
  0 <= a[4..7] <= 5. Upon joining paths, only 0 <= a[0..3] <= 5 remains.
  In the second iteration, 1 <= i <= 2, so we perform array smashing since
  the index i is not constant. The issue appears here: our knowledge about
  the array is limited to 0 <= a[0..3] <= 5. However, the domain still
  retains that cell a[4..7] was introduced. With no constraints on it,
  smashing causes us to discard all information.
 */
int main() {
  // Local array declaration
  int arr[15];
  int idx;

  for (idx = 0; idx < 10; ++idx) {
    if (nd_int()) {
      arr[idx] = 0;
    } else {
      arr[idx] = 5;
    }
  }

  int result = arr[idx - 1];
  __CRAB_assert(result >= 0 && result <= 5);
  return result;
}

