bool InstallDialog::validateContent()
{
  if (!m_Validator) {
    return true;
  }
  return m_Validator->isValid(m_FileTree->root()->item()->tree()) ==
         ModDataValidator::ValidationResult::OK;
}

void InstallDialog::refreshStatus()
{
  if (!m_Validator) {
    m_FileTree->setStyleSheet("QTreeWidget { border: none; }");
    m_StatusLabel->setText(
        tr("Unable to verify the contents of <%1>.").arg(m_TargetFolderName));
    m_StatusLabel->setToolTip(tr("The active game plugin does not support content validation for <%1>.")
                                   .arg(m_TargetFolderName));
    m_StatusLabel->setStyleSheet("color: #8B4513;");
  } else if (validateContent()) {
    m_FileTree->setStyleSheet(
        "QTreeWidget { border: 2px solid #006400; border-radius: 3px; }");
    m_StatusLabel->setText(
        tr("Contents of <%1> appear correct.").arg(m_TargetFolderName));
    m_StatusLabel->setToolTip(
        tr("Contents of <%1> are consistent with expectations for the current game.")
            .arg(m_TargetFolderName));
    m_StatusLabel->setStyleSheet("color: #006400;");
  } else {
    m_FileTree->setStyleSheet("QTreeWidget { border: 2px solid #FF0000; border-radius: 3px; }");
    m_StatusLabel->setText(
        tr("Contents of <%1> seem invalid.").arg(m_TargetFolderName));
    m_StatusLabel->setToolTip(
        tr("Contents of <%1> likely do not conform to game requirements.")
            .arg(m_TargetFolderName));
    m_StatusLabel->setStyleSheet("color: #FF0000;");
  }
}

void InstallDialog::addNewDirectory(ArchiveTreeWidgetItem* node)
{
  // Guard clause — context menu should prevent this:
  if (!node->item()->isDirectory()) {
    showError(tr("Cannot create a folder inside a file."));
    return;
  }

  // Get directory tree reference:
  auto dirTree = node->item()->tree();
  bool confirmed = false;
  QString input = QInputDialog::getText(this, tr("New Folder Name"), tr("Enter name:"),
                                         QLineEdit::Normal, QString(), &confirmed);
  input = input.simplified();

  if (confirmed && !input.isEmpty()) {
    // Check for existing item:
    if (dirTree->hasEntry(input)) {
      showError(tr("A folder or file with that name already exists."));
      return;
    }

    node->setExpanded(true);
    auto* createdNode = m_FileTree->insertDirectory(node, input);
    m_FileTree->scrollToItem(createdNode);
  }
}

void InstallDialog::on_treeContent_customContextMenuRequested(QPoint position)
{
  ArchiveTreeWidgetItem* selected =
      static_cast<ArchiveTreeWidgetItem*>(m_FileTree->itemAt(position));
  if (selected == nullptr) {
    return;
  }

  QPopupMenu popup;
  if (selected != m_FileTree->root() && selected->item()->isDirectory()) {
    popup.addAction(tr("Mark as <%1> folder").arg(m_TargetFolderName),
                   [this, selected]() {
                     m_FileTree->setRootItem(selected);
                   });
  }
  if (m_FileTree->root()->item() != m_DefaultRoot->item()) {
    popup.addAction(tr("Reset <%1> folder").arg(m_TargetFolderName), [this]() {
      m_FileTree->setRootItem(m_DefaultRoot);
    });
  }

  if (!popup.isEmpty()) {
    popup.addSeparator();
  }

  if (selected->item()->isDirectory()) {
    popup.addAction(tr("Create subfolder..."), [this, selected]() {
      addNewDirectory(selected);
    });
  } else {
    popup.addAction(tr("&Open File"), [this, selected]() {
      emit requestOpenFile(selected->item().get());
    });
  }

  popup.exec(m_FileTree->mapToGlobal(position));
}

void InstallDialog::on_acceptButton_clicked()
{
  if (!validateContent()) {
    if (QMessageBox::question(
            this, tr("Proceed Anyway?"),
            tr("This mod appears to be incorrectly configured and may fail during installation. "
               "We recommend reviewing and correcting the structure in the tree view first."),
            QMessageBox::Yes | QMessageBox::No,
            QMessageBox::No) == QMessageBox::No) {
      return;
    }
  }
  this->accept();
}

void InstallDialog::on_cancelButton_pressed()
{
  this->reject();
}

#include <iostream>
#include <vector>
#include <numeric>
#include <algorithm>
#include <cmath>

std::vector<int> containers[4];
std::vector<std::pair<int, int>> operations;

void execute_transfer(int source, int destination) {
    // Identify the middle ball according to the specified rules.
    // For a sorted collection of m items (1-indexed), the index is (m+2)/2.
    int m = containers[source].size();
    int mid_1_based = (m + 2) / 2;
    int item_to_shift = containers[source][mid_1_based - 1];

    // Locate and remove the item from the 'source' container.
    // std::lower_bound is applicable since the vector remains sorted.
    auto iter = std::lower_bound(containers[source].begin(), containers[source].end(), item_to_shift);
    containers[source].erase(iter);

    // Insert the item into the 'destination' container and re-sort for ordering.
    containers[destination].push_back(item_to_shift);
    std::sort(containers[destination].begin(), containers[destination].end());

    // Log the operation performed.
    operations.emplace_back(source, destination);
}

void solve_towers(int count, int source, int dest, int aux) {
    if (count == 0) {
        return;
    }
    // Standard recursive Tower of Hanoi logic.
    // The 'count' parameter governs recursion depth and operation sequence,
    // not direct selection of an item.
    solve_towers(count - 1, source, aux, dest);
    execute_transfer(source, dest);
    solve_towers(count - 1, aux, dest, source);
}

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int total_balls;
    std::cin >> total_balls;

    // Initialize: all balls start in container 1.
    containers[1].resize(total_balls);
    std::iota(containers[1].begin(), containers[1].end(), 1);

    // Initiate transfer of total_balls from container 1 to 3 using 2 as helper.
    solve_towers(total_balls, 1, 3, 2);

    std::cout << operations.size() << "\n";
    for (const auto& op : operations) {
        std::cout << op.first << " " << op.second << "\n";
    }

    return 0;
}

#include "sax.h"
using namespace NConfig;

namespace {
    class CSax : public IConfig, public IConfig::IValue {
    public:
        inline CSax(const TConfig& config)
            : Config_(config)
        {
        }

        void DoForEach(IFunc* callback) override {
            if (Config_.IsA<TArray>()) {
                const TArray& arr = Config_.Get<TArray>();
                for (size_t idx = 0; idx < arr.size(); ++idx) {
                    CSax child(arr[idx]);
                    callback->Consume(ToString(idx), &child);
                }
            } else if (Config_.IsA<TDict>()) {
                const TDict& dict = Config_.Get<TDict>();
                for (const auto& entry : dict) {
                    CSax child(entry.second);
                    callback->Consume(entry.first, &child);
                }
            }
        }

        TString AsString() override {
            if (Config_.IsA<TArray>()) {
                CSax firstItem(Config_.Get<TArray>()[0]);
                return firstItem.AsString();
            }
            return Config_.As<TString>();
        }

        bool AsBool() override {
            return Config_.As<bool>();
        }

        IConfig* AsSubConfig() override {
            return this;
        }

        bool IsContainer() const override {
            return Config_.IsA<TArray>() || Config_.IsA<TDict>();
        }

        void DumpJson(IOutputStream& output) const override {
            Config_.DumpJson(output);
        }

        void DumpLua(IOutputStream& output) const override {
            Config_.DumpLua(output);
        }

    private:
        TConfig Config_;
    };
}

namespace NConfig {
    THolder<IConfig> ConfigParser(IInputStream& input, const TGlobals& globalVars) {
        return MakeHolder<CSax>(TConfig::FromStream(input, globalVars));
    }
}

