class Solution {
public:
    // Find the first bad version in a sequence of versions
    int firstBadVersion(int n) {
        int firstBad = 0;
        for (int pos = n; pos >= 1; --pos) {
            if (isBadVersion(pos)) {
                firstBad = pos;
            } else {
                break;
            }
        }
        return firstBad;
    }
};

#include <vector>
using namespace std;

class Solution {
public:
    bool searchMatrix(vector<vector<int>>& grid, int value) {
        int rows = grid.size();
        int cols = grid[0].size();
        int row = 0;
        int col = cols - 1;
        while (row < rows && col >= 0) {
            int currentVal = grid[row][col];
            if (currentVal > value) {
                col--;
            } else if (currentVal < value) {
                row++;
            } else {
                return true;
            }
        }
        return false;
    }
};

#include <vector>
#include <algorithm>

class Solution {
public:
    // Find the missing integer in the range [0, n] where n is the size of the array
    int findMissingElement(std::vector<int>& values) {
        int arraySize = values.size();
        std::sort(values.begin(), values.end());

        for (int index = 0; index < arraySize; ++index) {
            if (values[index] != index) {
                return index;
            }
        }

        return arraySize;
    }
};

