class measurement {
private:
    int feet_part, inches_part;
public:
    void input();
    void display();
    measurement combine(measurement m);
};

void measurement::input() {
    cout << "enter feet and inches";
    cin >> feet_part >> inches_part;
}

void measurement::display() {
    cout << feet_part << "feet" << inches_part << "inches" << endl;
}

measurement measurement::combine(measurement m) {
    measurement temp;
    temp.feet_part = feet_part + m.feet_part;
    temp.inches_part = inches_part + m.inches_part;
    if (temp.inches_part >= 12) {
        temp.feet_part = temp.feet_part + temp.inches_part / 12;
        temp.inches_part = temp.inches_part % 12;
    }
    return temp;
}

