    obj1.input(); obj2.input();
    obj1.display(); obj2.display();
    obj3 = obj1.combine(obj2);
    obj3.display();
    return 0;
}

#include "core/horizon/loader/plugins/manager.hpp"

namespace hydra::horizon::loader::plugins {

void Manager::Reload() {
    loaded_plugins.clear();
    loaded_plugins.reserve(CONFIG_INSTANCE.GetLoaderPlugins().size());

    for (const auto& config_entry : CONFIG_INSTANCE.GetLoaderPlugins()) {
        if (!std::filesystem::exists(config_entry.file_path)) {
            LOG_ERROR(Other, "Plugin file \"{}\" is missing",
                      config_entry.file_path);
            continue;
        }

        if (!std::filesystem::is_regular_file(config_entry.file_path)) {
            LOG_ERROR(Other, "Plugin path \"{}\" does not point to a regular file",
                      config_entry.file_path);
            continue;
        }

        try {
            loaded_plugins.emplace_back(config_entry.file_path, config_entry.params);
        } catch (Plugin::LoadFailure err) {
            // TODO: show error dialog?
        } catch (Plugin::InitializationError err) {
            // TODO: show error dialog?
        }
    }
}

Plugin* Manager::LocatePluginForExtension(std::string_view ext) {
    for (auto& plugin_instance : loaded_plugins) {
        if (std::find(plugin_instance.formats.begin(),
                      plugin_instance.formats.end(),
                      ext) != plugin_instance.formats.end()) {
            return &plugin_instance;
        }
    }
    return nullptr;
}

