    ROCPROFILER_REGISTER_COMPUTE_VERSION_3(HIP_VERSION_MAJOR, HIP_VERSION_MINOR, HIP_VERSION_PATCH)

ROCPROFILER_REGISTER_DEFINE_IMPORT(hip, ROCP_REG_VERSION)

namespace hip {
namespace {

auto&
get_hip_api_table_instance()
{
    static auto _table = std::atomic<HipApiTable*>{ nullptr };
    return _table;
}

void
register_profiler_core()
{
    static auto _base_api_table = HipApiTable{};
    initialize_hip_api_table(&_base_api_table);

    get_hip_api_table_instance().exchange(&_base_api_table);

    static auto _modified_api_table = HipApiTable{};
    copy_hip_api_table(&_modified_api_table, &_base_api_table);

    void* _api_table_ptr = static_cast<void*>(&_modified_api_table);
    rocprofiler_register_library_indentifier_t lib_id{};

    auto result = rocprofiler_register_library_api_table(
        "hip",
        &ROCPROFILER_REGISTER_IMPORT_FUNC(hip),
        ROCP_REG_VERSION,
        &_api_table_ptr,
        1,
        &lib_id);

    if(result == 0)
    {
        auto* expected = &_base_api_table;
        if(!get_hip_api_table_instance().compare_exchange_strong(expected, &_modified_api_table))
        {
            std::cerr << "register_profiler_core expected the API table to be the internal "
                         "implementation but it differs. unexpected condition occurred.\n";
            std::abort();
        }
    }
}

void
ensure_registration()
{
    static auto _flag = std::atomic<bool>{ false };
    if(!_flag.load(std::memory_order_acquire))
    {
        using lock_type = std::recursive_mutex;
        using guard_type = std::unique_lock<lock_type>;
        static auto _init_flag = std::once_flag{};
        static auto _sync_mutex = lock_type{};

        auto lock = guard_type{ _sync_mutex, std::defer_lock };

        if(lock.owns_lock()) return;

        lock.lock();

        std::call_once(_init_flag, register_profiler_core);

        _flag.exchange(true, std::memory_order_release);
    }
}

}  // namespace

HipApiTable*
get_hip_api_table()
{
    ensure_registration();
    return get_hip_api_table_instance().load(std::memory_order_relaxed);
}

}  // namespace hip

