void XmlPlaneWriter::writeHeader()
{
    writeDTD("<!DOCTYPE flow5>");
}

void XmlPlaneWriter::writeXMLPlane(PlaneXfl const &aircraft, bool bExportFoils)
{
    writeStartDocument();
    {
        writeHeader();
        writeStartElement("xflplane");
        writeAttribute("version", "1.0");
        {
            writeComment("For convenience, all field names are case-insensitive, as an exception to the standard xml specification");
            writeComment("Where applicable, default values will be used for all undefined fields");
            writeUnits();
            writeStartElement("Plane");
            {
                writeTextElement("Name", aircraft.name());
                if(aircraft.description().length())
                {
                    writeTextElement("Description", aircraft.description());
                }
                writeTheStyle(aircraft.theStyle());
                if(aircraft.pointMassCount())
                {
                    writeStartElement("Inertia");
                    {
                        for(int idx=0; idx<aircraft.pointMassCount(); idx++)
                        {
                            writePointMass(aircraft.pointMassAt(idx));
                        }
                    }
                    writeEndElement();
                }
                for(int ifuse=0; ifuse<aircraft.nFuse(); ifuse++)
                {
                    if(aircraft.fuseAt(ifuse) && aircraft.fuseAt(ifuse)->isXflType())
                    {
                        FuseXfl const* pFuselage = dynamic_cast<FuseXfl const*>(aircraft.fuseAt(ifuse));
                        writeXflFuse(*pFuselage, aircraft.fusePos(0));
                    }
                }
                for(int iw=0; iw<aircraft.nWings(); iw++)
                {
                    if(aircraft.wingAt(iw))
                    {
                        writeWing(*aircraft.wingAt(iw), aircraft.wingLE(iw), aircraft.rxAngle(iw), aircraft.ryAngle(iw), bExportFoils);
                    }
                }
            }
        }
        writeEndElement();
    }
    writeEndDocument();
}

#include <vector>
#include <stack>

class Solution {
public:
    int minOperations(std::vector<int>& values) {
        std::stack<int> buffer;
        int count = 0;
        for (int element : values) {
            while (!buffer.empty() && element < buffer.top()) {
                buffer.pop();  // Remove larger elements that are no longer relevant
            }
            if (buffer.empty() || element > buffer.top()) {
                if (element > 0) count++;
                buffer.push(element);
            }
        }
        return count;
    }
};

#include <iostream>
#include <vector>
using namespace std;

// Global variables to store the array size and contents
int arraySize;
vector<int> dataArray;

// Recursive function to process range [left, right]
void processRange(int left, int right) {
    if (left > right) return;

    // Skip already filled positions from both ends
    while (left <= right && dataArray[left] != 0) left++;
    while (right >= left && dataArray[right] != 0) right--;

    if (left > right) return;

    // Query the current segment
    cout << "? " << left << " " << right << endl;
    int value, frequency;
    cin >> value >> frequency;

    // Handle invalid response
    if (value == -1) exit(0);

    // If all elements in the range are the same value
    if (frequency == right - left + 1) {
        for (int idx = left; idx <= right; ++idx) dataArray[idx] = value;
        return;
    }

    int center = (left + right) / 2;

    // Process left half first
    processRange(left, center);

    // Use query information to fill some values in the right half if needed
    if (dataArray[center] == value) {
        int countLeft = 0;
        int pos = center;

        // Count occurrences of 'value' in the left segment [left, center]
        while (pos >= left && dataArray[pos] == value) {
            countLeft++;
            pos--;
        }

        // Fill remaining occurrences in the right half
        int remaining = frequency - countLeft;
        for (int j = 1; j <= remaining; ++j) {
            if (center + j <= arraySize) dataArray[center + j] = value;
        }
    }

    // Process right half
    processRange(center + 1, right);
}

int main() {
    // Speed up I/O operations
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    if (cin >> arraySize) {
        dataArray.resize(arraySize + 1, 0); // 1-based indexing

        processRange(1, arraySize);

        cout << "! ";
        for (int i = 1; i <= arraySize; ++i) {
            cout << dataArray[i] << (i == arraySize ? "" : " ");
        }
        cout << endl;
    }

    return 0;
}

