#include <asio/ts/executor.hpp>
#include <asio/thread_pool.hpp>
#include <iostream>

using asio::post;
using asio::thread_pool;
using asio::use_future;

// Modified active object pattern implementation
class bank_account
{
  int account_balance_ = 0;
  mutable thread_pool executor_{1};
public:
  void credit(int value)
  {
    post(executor_,
      use_future([=]
        {
          account_balance_ += value;
        })).get();
  }
  void debit(int value)
  {
    post(executor_,
      use_future([=]
        {
          if (account_balance_ >= value)
            account_balance_ -= value;
        })).get();
  }
  int get_balance() const
  {
    return post(executor_,
      use_future([=]
        {
          return account_balance_;
        })).get();
  }
};

int main()
{
  bank_account savings;
  savings.credit(20);
  savings.debit(10);
  std::cout << "current balance = " << savings.get_balance() << "\n";
}

