#include <Application.h>
#include <Bitmap.h>
#include <BitmapStream.h>
#include <File.h>
#include <TranslationUtils.h>
#include <TranslatorRoster.h>
#include <iostream>
#include <cstring>

class ImageExporterApp : public BApplication
{
public:
	ImageExporterApp(int argc, char** argv)
		:
		BApplication("application/x-vnd.image-exporter"),
		fArgc(argc),
		fArgv(argv)
	{
	}

	void ReadyToRun() override
	{
		if (fArgc < 2) {
			std::cout << "Usage: " << fArgv[0] << " <source_image>" << std::endl;
			PostMessage(B_QUIT_REQUESTED);
			return;
		}

		const char* sourcePath = fArgv[1];

		// Load the input image file
		BBitmap* imageBitmap = BTranslationUtils::GetBitmapFile(sourcePath);
		if (!imageBitmap) {
			std::cout << "Error: Unable to load image '" << sourcePath << "'" << std::endl;
			PostMessage(B_QUIT_REQUESTED);
			return;
		}

		// Wrap bitmap in a stream for translation
		BBitmapStream imageStream(imageBitmap);

		// Access default translator roster
		BTranslatorRoster* translatorManager = BTranslatorRoster::Default();
		if (!translatorManager) {
			std::cout << "Error: Could not retrieve translator roster" << std::endl;
			delete imageBitmap;
			PostMessage(B_QUIT_REQUESTED);
			return;
		}

		// Export as JPEG
		BFile jpegOutput("output_image.jpg",
			B_CREATE_FILE | B_ERASE_FILE | B_WRITE_ONLY);
		status_t result = translatorManager->Translate(&imageStream, nullptr, nullptr, &jpegOutput, B_JPEG_FORMAT);
		if (result != B_OK) {
			std::cout << "JPEG export failed: " << strerror(result) << std::endl;
		} else {
			std::cout << "JPEG saved successfully: output_image.jpg" << std::endl;
		}

		// Reset stream position for PNG export
		imageStream.Seek(0, SEEK_SET);

		// Export as PNG
		BFile pngOutput("output_image.png",
			B_CREATE_FILE | B_ERASE_FILE | B_WRITE_ONLY);
		result = translatorManager->Translate(&imageStream, nullptr, nullptr, &pngOutput, B_PNG_FORMAT);
		if (result != B_OK) {
			std::cout << "PNG export failed: " << strerror(result) << std::endl;
		} else {
			std::cout << "PNG saved successfully: output_image.png" << std::endl;
		}

		delete imageBitmap;
		PostMessage(B_QUIT_REQUESTED); // Terminate application
	}

private:
	int fArgc;
	char** fArgv;
};

int main(int argc, char** argv)
{
	ImageExporterApp app(argc, argv);
	app.Run();
	return 0;
}

#include <iostream>
#include <vector>
using namespace std;

// Dutch National Flag Algorithm Implementation
// This function sorts an array consisting of only 0s, 1s, and 2s in-place
void sortZeroOneTwo(vector<int>& arr) {  
    int start = 0, current = 0, end = arr.size() - 1;

    while (current <= end) {
        if (arr[current] == 0) {
            swap(arr[current], arr[start]);
            start++;
            current++;
        } else if (arr[current] == 1) {
            current++;
        } else {
            swap(arr[current], arr[end]);
            end--;
        }
    }
}

int main() {
    vector<int> data = {2, 0, 0, 0, 1, 1, 2, 2, 2, 2, 2, 1, 1, 1};

    sortZeroOneTwo(data);

    for (int index = 0; index < data.size(); index++) {
        cout << data[index] << " ";
    }
    cout << endl;

    return 0;
}

