TEST_CASE("string::urlEncode") {
    SECTION("Basic alphanumeric strings") {
        REQUIRE(ap::string::urlEncode("hello") == "hello");
        REQUIRE(ap::string::urlEncode("HelloWorld") == "HelloWorld");
    }
    SECTION("Strings containing spaces") {
        REQUIRE(ap::string::urlEncode("hello world") == "hello%20world");
        REQUIRE(ap::string::urlEncode("Hello World Test") ==
                "Hello%20World%20Test");
    }
    SECTION("Strings with slashes (no encoding)") {
        REQUIRE(ap::string::urlEncode("path/to/file") == "path/to/file");
        REQUIRE(ap::string::urlEncode("Dir/Sub/Path") == "Dir/Sub/Path");
    }
    SECTION("Strings with slashes (encoding enabled)") {
        REQUIRE(ap::string::urlEncode("path/to/file", true) == "path%2Fto%2Ffile");
        REQUIRE(ap::string::urlEncode("Dir/Sub/Path", true) ==
                "Dir%2FSub%2FPath");
    }
    SECTION("Complex filenames with special characters") {
        REQUIRE(ap::string::urlEncode(
                    "report-2023(1).pdf;v=2?param=a&b=c") ==
                "report-2023%281%29.pdf%3Bv%3D2%3Fparam%3Da%26b%3Dc");
        REQUIRE(ap::string::urlEncode("report%281%29.pdf") ==
                "report%25281%2529.pdf");
