#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

// Maximum array size constraint
const int MAX_SIZE = 200005;
int arr[MAX_SIZE];
int array_size;

// Function to issue a query and get mode and frequency
void perform_query(int left, int right, int &mode_value, int &frequency) {
    if (left > right) {
        mode_value = -1;
        frequency = -1;
        return;
    }

    cout << "? " << left << " " << right << endl;
    cin >> mode_value >> frequency;

    // Handle invalid response by terminating
    if (mode_value == -1) exit(0);
}

// Recursive function to reconstruct the array
// left, right: current segment boundaries
// known_mode, known_freq: pre-known mode info if available (-1 means unknown)
void reconstruct(int left, int right, int known_mode, int known_freq) {
    if (left > right) return;

    int mode_val, freq_val;

    // Use provided known values if available
    if (known_mode != -1) {
        mode_val = known_mode;
        freq_val = known_freq;
    } else {
        perform_query(left, right, mode_val, freq_val);
    }

    // Base case: entire segment is filled with the same value
    if (freq_val == right - left + 1) {
        for (int idx = left; idx <= right; ++idx) {
            arr[idx] = mode_val;
        }
        return;
    }

    // Query prefix part: [left, right - freq_val]
    int prefix_mode, prefix_freq;
    perform_query(left, right - freq_val, prefix_mode, prefix_freq);

    if (prefix_mode == mode_val) {
        // Mode appears in the prefix portion
        reconstruct(left, right - freq_val, prefix_mode, prefix_freq);
        reconstruct(right - freq_val + 1, right, -1, -1);
        return;
    }

    // Query suffix part: [left + freq_val, right]
    int suffix_mode, suffix_freq;
    perform_query(left + freq_val, right, suffix_mode, suffix_freq);

    if (suffix_mode == mode_val) {
        // Mode appears in the suffix portion
        reconstruct(left, left + freq_val - 1, -1, -1);
        reconstruct(left + freq_val, right, suffix_mode, suffix_freq);
        return;
    }

    // If mode doesn't dominate either end, it must be in the overlapping middle region
    // This occurs when 2 * freq_val > total_length
    if (2 * freq_val > right - left + 1) {
        for (int idx = right - freq_val + 1; idx <= left + freq_val - 1; ++idx) {
            arr[idx] = mode_val;
        }
    }

    // Recursively process both subsegments using gathered data
    reconstruct(left, right - freq_val, prefix_mode, prefix_freq);
    reconstruct(left + freq_val, right, suffix_mode, suffix_freq);
}

int main() {
    // Speed up I/O operations
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    if (!(cin >> array_size)) return 0;

    reconstruct(1, array_size, -1, -1);

    cout << "!";
    for (int i = 1; i <= array_size; ++i) {
        cout << " " << arr[i];
    }
    cout << endl;

    return 0;
}

