#include "IntBuffer.h"

// Creates a new integer buffer with specified capacity.
// The resulting buffer starts at position 0, has limit equal to its capacity,
// and an undefined mark. It uses an internally allocated backing array,
// with the array offset set to zero.
//
// Parameters:
// size - The maximum number of integers the buffer can hold
IntBuffer::IntBuffer(unsigned int size) : Buffer(size)
{
	data = new int[size];
	memset(data, 0, sizeof(int) * size);
}

// Constructs a buffer using an externally provided backing array.
// The buffer's capacity is determined by the caller-provided size parameter.
// The backing array is used directly without copying.
//
// Parameters:
// size - The buffer's capacity
// externalArray - Pointer to the pre-allocated integer array to use as backing storage
IntBuffer::IntBuffer(unsigned int size, int* externalArray) : Buffer(size)
{
	hasBackingArray = true;
	data = externalArray;
}

IntBuffer::~IntBuffer()
{
	if (!hasBackingArray)
		delete[] data;
}

int* IntBuffer::getData()
{
	return data;
}

// Reverses the buffer's active region by setting the limit to the current position
// and resetting the position to zero. Any existing mark is invalidated.
//
// Returns:
// Reference to this buffer for method chaining
IntBuffer* IntBuffer::flip()
{
	m_limit = m_position;
	m_position = 0;
	return this;
}

// Reads an integer from a specific location in the buffer.
// Parameters:
// index - Zero-based position to read from; must be less than current limit
// Returns:
// The integer value stored at the specified index
int IntBuffer::get(unsigned int index)
{
	assert(index < m_limit);
	return data[index];
}

// Inserts multiple integers from a source array into this buffer.
// Copies 'count' elements starting at 'start' in the source array,
// placing them beginning at the current buffer position.
// Buffer position is advanced by 'count'.
//
// Throws assertion failure if source indices exceed array bounds or
// destination buffer overflows.
//
// Parameters:
// source - Source array containing integers to copy
// start - First element index in source array (>= 0)
// count - Number of elements to transfer
// Returns:
// This buffer instance for chaining operations
IntBuffer* IntBuffer::put(intArray* src, unsigned int start, unsigned int count)
{
	assert(start + count <= src->size);
	std::copy(src->elements + start, src->elements + start + count, data + m_position);
	m_position += count;
	return this;
}

// Inserts all elements from a complete source array into this buffer.
// Fails assertion if source length exceeds available space in buffer.
//
// Parameters:
// src - Complete source array to copy from
// Returns:
// This buffer for chaining
IntBuffer* IntBuffer::put(intArray src)
{
	if (src.size > remaining())
		assert(false); // TODO: Implement proper exception handling

	std::copy(src.elements, src.elements + src.size, data + m_position);
	m_position += src.size;
	return this;
}

// Writes a single integer into the buffer at the current position,
// then advances the position by one.
//
// Parameters:
// value - Integer to store in the buffer
// Returns:
// This buffer for method chaining
IntBuffer* IntBuffer::put(int value)
{
	assert(m_position < m_limit);
	data[m_position++] = value;
	return this;
}

