#include <iostream>
#include <vector>
#include <algorithm>
#include <limits>
using namespace std;

class Solution {
public:
    // Linear scan approach for searching in rotated sorted array with duplicates
    bool linearSearch(vector<int>& arr, int key) {
        // Handle edge cases: check first and last elements
        if(arr[0] == key || arr[arr.size()-1] == key) {
            return true;
        }

        // Scan through the middle elements
        for(int idx = 1; idx < arr.size()-1; idx++) {
            if(arr[idx] == key) {
                return true;
            }
        }
        return false;
        // Time Complexity: O(n) - checks each element once
        // Space Complexity: O(1) - no additional storage needed
    }

    // Optimized binary search approach for rotated sorted array with duplicates
    bool binarySearchOptimized(vector<int>& arr, int key) {
        // Check boundary elements first
        if(arr[0] == key || arr[arr.size()-1] == key) {
            return true;
        }

        int left = 0;
        int right = arr.size() - 1;

        while(left <= right) {
            int middle = left + (right - left)/2;

            // Found the target
            if(arr[middle] == key) {
                return true;
            }

            // Handle duplicates at boundaries and middle
            if((arr[middle] == arr[left]) && (arr[right] == arr[middle])) {
                left++;
                right--;
            }
            else if(arr[left] <= arr[middle]) {
                // Left half is sorted
                if((arr[left] <= key) && (key < arr[middle])) {
                    // Target lies in left sorted portion
                    right = middle - 1;
                }
                else {
                    // Target lies in right portion
                    left = middle + 1;
                }
            }
            else {
                // Right half is sorted
                if((arr[middle] < key) && (key <= arr[right])) {
                    // Target lies in right sorted portion
                    left = middle + 1;
                }
                else {
                    // Target lies in left portion
                    right = middle - 1;
                }
            }
        } 
        return false;
        /*
            Time Complexity: O(log n) - halves search space each iteration
            Space Complexity: O(1) - constant extra space used
        */
    }
};

int main() {
    vector<int> data = {2,5,6,0,0,1,2};
    int query1 = 3;
    int query2 = 0;

    Solution solver;

    bool result1 = solver.binarySearchOptimized(data, query1);
    cout << result1 << endl; // Expected output: 0 (false)

    bool result2 = solver.binarySearchOptimized(data, query2);
    cout << result2 << endl; // Expected output: 1 (true)

    return 0;
}

#include "server.hpp"
#include <signal.h>
#include <utility>

namespace http {
namespace server {

server::server(const std::string& host, const std::string& port_str,
    const std::string& content_dir)
  : context_(1),
    stop_signals_(context_),
    socket_acceptor_(context_),
    conn_manager_(),
    request_handler_(content_dir)
{
  // Handle termination signals to gracefully shut down the server
  stop_signals_.add(SIGINT);
  stop_signals_.add(SIGTERM);
#if defined(SIGQUIT)
  stop_signals_.add(SIGQUIT);
#endif // defined(SIGQUIT)

  prepare_for_shutdown();

  // Configure the acceptor with address reuse enabled
  asio::ip::tcp::resolver resolver(context_);
  auto endpoints = resolver.resolve(host, port_str);
  asio::ip::tcp::endpoint addr = *endpoints.begin();

  socket_acceptor_.open(addr.protocol());
  socket_acceptor_.set_option(asio::ip::tcp::acceptor::reuse_address(true));
  socket_acceptor_.bind(addr);
  socket_acceptor_.listen();

  start_accepting_connections();
}

void server::run()
{
  // Run the event loop until all operations complete
  context_.run();
}

void server::start_accepting_connections()
{
  socket_acceptor_.async_accept(
      [this](std::error_code err, asio::ip::tcp::socket client_socket)
      {
        // Verify that the acceptor is still open before proceeding
        if (!socket_acceptor_.is_open())
        {
          return;
        }

        if (!err)
        {
          conn_manager_.start(std::make_shared<connection>(
              std::move(client_socket), conn_manager_, request_handler_));
        }

        // Continue accepting new connections
        start_accepting_connections();
      });
}

void server::prepare_for_shutdown()
{
  stop_signals_.async_wait(
      [this](std::error_code /*ec*/, int signal_number)
      {
        // Clean shutdown: close acceptor and terminate all connections
        socket_acceptor_.close();
        conn_manager_.stop_all();
      });
}

} // namespace server
} // namespace http

