/**
 * Definition for a binary tree node.
*/
struct TreeNode {
     int val;
     TreeNode *left;
     TreeNode *right;
     TreeNode() : val(0), left(nullptr), right(nullptr) {}
     TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
     TreeNode(int x, TreeNode *left, TreeNode *right) : val(x), left(left), right(right) {}
};

class BSTValidator {
public:
    bool validateTree(TreeNode* node, long lowerBound, long upperBound) {
        if (!node) return true; // An empty subtree is valid
        // Verify current node respects the allowed range
        if (node->val <= lowerBound || node->val >= upperBound) {
            return false;
        }
        // Check left and right children with updated bounds
        return validateTree(node->left, lowerBound, node->val) &&
               validateTree(node->right, node->val, upperBound);
    }

    bool isValidBinarySearchTree(TreeNode* root) {
        return validateTree(root, LONG_MIN, LONG_MAX);
    }
};

