// Constructs a buffer using an externally provided backing array
// The buffer's capacity is set to the provided value, and it references the given array directly.
//
// Parameters:
// size - The buffer's capacity
// externalArray - Pre-allocated integer array to use as backing storage
IntBuffer::IntBuffer(unsigned int size, int* externalArray) : Buffer(size)
{
	usesExternalArray = true;
	dataArray = externalArray;
}

IntBuffer::~IntBuffer()
{
	if (!usesExternalArray)
		delete[] dataArray;
}

int* IntBuffer::getData()
{
	return dataArray;
}

// Reverses the buffer's state for reading: sets limit to current position and resets position to zero.
// Any existing mark is cleared.
//
// Returns:
// Reference to this buffer (for method chaining)
IntBuffer* IntBuffer::flip()
{
	m_limit = m_position;
	m_position = 0;
	return this;
}

// Reads an integer from a specific index in the buffer
// Parameters:
// idx - Zero-based index to read from; must be less than current limit
// Returns:
// The integer value stored at the specified index
int IntBuffer::get(unsigned int idx)
{
	assert(idx < m_limit);
	return dataArray[idx];
}

// Writes multiple integers from a source array into this buffer
// Copies elements starting at 'startIdx' in the source array, writing 'count' elements beginning at the current position.
// Throws assertion failure if insufficient space remains or indices are out of bounds.
//
// Parameters:
// src - Source array containing integers to copy
// startIdx - First element index in source array to copy (must be valid)
// count - Number of elements to transfer (must be non-negative and within array bounds)
// Returns:
// This buffer instance (supports chaining)
IntBuffer* IntBuffer::put(intArray* source, unsigned int startIdx, unsigned int count)
{
	assert(startIdx + count <= source->size);
	std::copy(source->values + startIdx, source->values + startIdx + count, dataArray + m_position);
	m_position += count;
	return this;
}

// Convenience method: writes entire source array into this buffer
// Verifies sufficient capacity exists before copying all elements.
//
// Parameters:
// src - Complete integer array to append to this buffer
// Returns:
// This buffer instance
IntBuffer* IntBuffer::put(intArray src)
{
	if (src.size > remaining())
