    if (!(cin >> total_boxes >> num_stacks)) return 0;

    // Stacks are 1-indexed (index 0 unused)
    vector<vector<int>> stacks(num_stacks + 1);

    // Initialize stacks with given configuration
    int boxes_per_stack = total_boxes / num_stacks;
    for (int s = 1; s <= num_stacks; ++s) {
        for (int b = 0; b < boxes_per_stack; ++b) {
            int value;
            cin >> value;
            stacks[s].push_back(value);
        }
    }

    vector<Operation> sequence;
    int next_target = 1;

    // Process all boxes in order from 1 to total_boxes
    while (next_target <= total_boxes) {
        int source_stack = -1;
        int position_in_stack = -1;

        // Find the current target box
        for (int s = 1; s <= num_stacks; ++s) {
            for (int pos = 0; pos < stacks[s].size(); ++pos) {
                if (stacks[s][pos] == next_target) {
                    source_stack = s;
                    position_in_stack = pos;
                    break;
                }
            }
            if (source_stack != -1) break;
        }

        // If the box is at the top of its stack, remove it directly
        if (position_in_stack == (int)stacks[source_stack].size() - 1) {
            sequence.push_back({next_target, 0});
            stacks[source_stack].pop_back();
            next_target++;
            continue;
        }

        // Otherwise, determine how many boxes are above the target
        int count_above = stacks[source_stack].size() - 1 - position_in_stack;

        int best_chunk_size = -1;
        int best_destination = -1;
        long long highest_score = -2e18;

        // Evaluate possible moves for chunks of boxes above the target
        for (int chunk_size = 1; chunk_size <= count_above; ++chunk_size) {
            int start_index = stacks[source_stack].size() - chunk_size;

            // Find maximum value in this chunk
            int max_in_chunk = -1;
            for (int k = 0; k < chunk_size; ++k) {
                max_in_chunk = max(max_in_chunk, stacks[source_stack][start_index + k]);
            }

            // Try moving this chunk to each other stack
            for (int dest = 1; dest <= num_stacks; ++dest) {
                if (dest == source_stack) continue;

                int top_of_dest = stacks[dest].empty() ? 1000 : stacks[dest].back();

                long long evaluation;

                if (max_in_chunk < top_of_dest) {
                    // Valid move: maintain decreasing order
                    evaluation = 200000LL + (long long)chunk_size * 1000 - (top_of_dest - max_in_chunk);
                } else {
                    // Invalid move: place larger on smaller
                    evaluation = (long long)top_of_dest * 1000 + chunk_size;
                }

                if (evaluation > highest_score) {
                    highest_score = evaluation;
                    best_chunk_size = chunk_size;
                    best_destination = dest;
                }
            }
        }

        // Execute the best move found
        int move_start = stacks[source_stack].size() - best_chunk_size;
        int first_box_moved = stacks[source_stack][move_start];

        sequence.push_back({first_box_moved, best_destination});

        // Transfer boxes from source to destination
        vector<int> transferred;
        transferred.reserve(best_chunk_size);
        for (int k = 0; k < best_chunk_size; ++k) {
            transferred.push_back(stacks[source_stack][move_start + k]);
        }

        stacks[source_stack].resize(move_start);
        for (int val : transferred) {
            stacks[best_destination].push_back(val);
        }
    }

    // Print the sequence of operations
    for (const auto& op : sequence) {
        cout << op.box_value << " " << op.destination_stack << "\n";
    }

    return 0;
}

