int main() {
    printf("flow5 XFoil execution\n");

    std::string airfoilName = "naca4210";
    std::cout << "Generating airfoil: " << airfoilName << std::endl;

    Foil* pAirfoil = foil::makeNacaFoil(4210, airfoilName);
    if (!pAirfoil) {
        std::cerr << "Failed to create airfoil... terminating" << std::endl;
        return 1;
    }

    std::cout << "Airfoil '" << pAirfoil->name() 
              << "' successfully created and registered in the database." 
              << std::endl << std::endl;

    // Display airfoil metadata
    std::cout << "Airfoil characteristics:" << std::endl;
    std::cout << pAirfoil->name() << std::endl;
    std::string info = pAirfoil->properties(true);
    std::cout << info << std::endl << std::endl;

    // Create and configure polar
    Polar* pPolarData = Objects2d::createPolar(pAirfoil, xfl::T1POLAR, 200000.0, -5.0, 15.0, 0.5, 1.2);
    pPolarData->setName("T1 validation polar");
    Objects2d::insertPolar(pPolarData);

    std::cout << "Polar details:" << std::endl;
    std::cout << pPolarData->name() << std::endl;
    std::cout << pPolarData->properties() << std::endl << std::endl;

    bool retainOpps = true; // keep operating points for later access
    XFoilTask* pSolver = new XFoilTask();

    std::cout << "Setting up XFoil solver..." << std::endl;
    pSolver->initialize(*pAirfoil, pPolarData, retainOpps);

    // Append angle-of-attack ranges: positive first, then negative
    pSolver->appendRange({true, 0.0, 12.0, 1.0});
    pSolver->appendRange({true, 0.0, -8.0, 1.0});

    std::cout << "Executing XFoil analysis..." << std::endl;
    pSolver->run();
    printf(pSolver->log().c_str());
    printf("\n");

    std::cout << "XFoil analysis completed." << std::endl << std::endl;

    // Store individual operating points in the database
    for (OpPoint* pPoint : pSolver->operatingPoints()) {
        Objects2d::insertOpPoint(pPoint);
    }

    delete pSolver;

    // Export polar results to string
    std::string outputData;
    pPolarData->exportToString(outputData, false, true);
    printf(outputData.c_str());

    std::cout << "\nProcess finished." << std::endl;

    globals::saveFl5Project("/tmp/XFoilRun.fl5");
    globals::deleteObjects(); // Cleanup all managed objects

    return 0;
}

#include <sol/sol.hpp>
