// Function that adds 20 to the input value
int addTwenty(int number) {
    return 20 + number;
}

// Function that prepends a message to the input string
std::string prependMessage(std::string inputText) {
    return "received: " + inputText;
}

// Variadic fallback function for handling multiple argument types
sol::variadic_results handleVariadicArgs(
    sol::this_state state, sol::variadic_args arguments) {
    sol::variadic_results result;
    if (arguments.size() == 2) {
        result.push_back({ state,
            sol::in_place,
            arguments.get<int>(0) + arguments.get<int>(1) });
    }
    else {
        result.push_back({ state, sol::in_place, 42 });
    }
    return result;
}

int main(int, char*[]) {
    std::cout << "=== overloading with fallback ==="
              << std::endl;

    sol::state luaEnvironment;
    luaEnvironment.open_libraries();

    // Register overloaded functions with Lua
    luaEnvironment.set_function(
        "compute", 
        sol::overload(addTwenty, prependMessage, handleVariadicArgs)
    );

    // Execute Lua scripts to test function overloading
    luaEnvironment.script("print(compute(5))");       // Calls addTwenty
    luaEnvironment.script("print(compute('hello'))"); // Calls prependMessage
    luaEnvironment.script("print(compute(15, 25))");  // Calls fallback with sum
    luaEnvironment.script("print(compute({}))");      // Calls fallback with default

    return 0;
}

