#include <vector>
#include <algorithm>

class Solution {
public:
    int maxArea(std::vector<int>& heights) {
        int size = heights.size();
        int left = 0;
        int right = size - 1;
        int bestArea = 0;
        int currentArea = 0;

        while (left < right) {
            int distance = right - left;
            int minHeight = std::min(heights[left], heights[right]);
            currentArea = distance * minHeight;
            bestArea = std::max(currentArea, bestArea);

            if (heights[left] < heights[right]) {
                left++;
            } else {
                right--;
            }
        }

        return bestArea;
    }
};

