TEST_CASE(test_tooltip_line_lengths, "UI") {
    std::cout << "\nTest: ToolTip Line Lengths (Issue #179)" << std::endl;
    const size_t MAX_LINE_LENGTH = 80;
    int error_count = 0;
    for (const char* tooltip : Tooltips::ALL) {
        if (!tooltip) continue;
        std::string text(tooltip);
        std::stringstream stream(text);
        std::string row;
        while (std::getline(stream, row, '\n')) {
            if (row.length() > MAX_LINE_LENGTH) {
                std::cout << "  [FAIL] Line too long (" << row.length() << " chars) in tooltip starting with: "
                          << text.substr(0, 20) << "..." << std::endl;
                std::cout << "         Line: " << row << std::endl;
                error_count++;
            }
        }
    }
    if (error_count > 0) {
        std::cout << "  Total failures: " << error_count << std::endl;
    }
    ASSERT_TRUE(error_count == 0);
}
