    // 4J Stu - This function call had to be moved here from the Entity ctor to
    // ensure that the derived version of the function is called
    this->syncData();
}

ThrownEnderpearl::ThrownEnderpearl(Level* world, double posX, double posY, double posZ)
: Throwable(world, posX, posY, posZ) {
    // 4J Stu - This function call had to be moved here from the Entity ctor to
    // ensure that the derived version of the function is called
    this->syncData();
}

void ThrownEnderpearl::onCollision(HitResult* result) {
    if (result->targetEntity != nullptr) {
        DamageSource* source = DamageSource::thrown(shared_from_this(), projectileOwner);
        result->targetEntity->takeDamage(source, 0);
        delete source;
    }

    for (int index = 0; index < 32; ++index) {
        world->spawnParticle(
            eParticleType_ender,
            positionX,
            positionY + rng->nextDouble() * 2.0,
            positionZ,
            rng->nextGaussian(),
            0.0,
            rng->nextGaussian()
        );
    }

    if (!world->isRemote()) {
        // Fix for #67486 - TCR #001: BAS Game Stability: Customer Encountered:
        // TU8: Code: Gameplay: The title crashes on Host's console when Client
        // Player leaves the game before the Ender Pearl thrown by him touches
        // the ground. If the owner has been removed, then ignore
        std::shared_ptr<ServerPlayer> player =
            std::dynamic_pointer_cast<ServerPlayer>(projectileOwner);
        if (player != nullptr && !player->isRemoved()) {
            if (!player->networkHandler->isConnected
                && player->getWorld() == this->world) {
                projectileOwner->moveTo(positionX, positionY, positionZ);
                player->fallDistance = 0.0f;
                player->takeDamage(DamageSource::fall, 5);
            }
        }
        destroy();
    }
}

