#include <stdio.h>

// Recursive function to solve the Tower of Hanoi puzzle
void hanoiSolver(int disks, char fromRod, char viaRod, char toRod) {
    // Base case: single disk movement
    if (disks == 1) {
        printf("Move disk 1 from %c to %c\n", fromRod, toRod);
        return;
    }

    // Move top (disks-1) disks from source to auxiliary rod
    hanoiSolver(disks - 1, fromRod, toRod, viaRod);

    // Move the largest disk from source to destination
    printf("Move disk %d from %c to %c\n", disks, fromRod, toRod);

    // Move the (disks-1) disks from auxiliary to destination
    hanoiSolver(disks - 1, viaRod, fromRod, toRod);
}

int main() {
    int numDisks;

    // Prompt user for input
    printf("Enter the number of disks: ");
    scanf("%d", &numDisks);

    // Display solution header and execute solver
    printf("The sequence of moves to solve the Tower of Hanoi for %d disks is:\n", numDisks);
    hanoiSolver(numDisks, 'X', 'Y', 'Z');  // X=source, Y=auxiliary, Z=destination

    return 0;
}

