#include <iostream>
#include <vector>

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    long long value;
    std::cin >> value;

    // Determine grid dimensions based on maximum bit count needed
    // Using 62 bits ensures coverage for numbers up to 10^18
    int size = 105;
    std::vector<std::vector<int>> matrix(size + 1, std::vector<int>(size + 1, 0));

    int layer = 1;

    // Process each bit position from least significant to most significant
    for (int bit_index = 0; bit_index < 62; ++bit_index) {
        // Establish the primary connection to next layer
        matrix[layer][layer + 1] = 1;

        // When current bit is set, add connections from all previous layers
        if ((value >> bit_index) & 1) {
            for (int row = 1; row < layer; ++row) {
                matrix[row][layer + 1] = 1;
            }
        }
        layer++;
    }

    // Connect all active layers to final column
    for (int row = 1; row <= layer; ++row) {
        matrix[row][layer] = 1;
    }

    // Display results
    std::cout << layer << std::endl;
    for (int row = 1; row <= layer; ++row) {
        for (int col = 1; col <= layer; ++col) {
            std::cout << matrix[row][col];
            if (col != layer) {
                std::cout << " ";
            }
        }
        std::cout << std::endl;
    }

    return 0;
}

