#include <iostream>
#include <vector>
#include <queue>
#include <list>

// Only for Directed Acyclic Graphs (DAGs)
// Graph class definition for Kahn's Algorithm - Modified version

class Digraph {
    int numVertices; // Number of vertices in the graph
    std::list<int>* adjacencyList; // Adjacency list representation

public:
    Digraph(int vertices) {
        numVertices = vertices;
        adjacencyList = new std::list<int>[vertices];
    }

    void addConnection(int from, int to) {
        adjacencyList[from].push_back(to); // Add directed edge from 'from' to 'to'
    }

    void performTopologicalSortKahn() {
        std::vector<int> inDegree(numVertices, 0);

        // Compute in-degrees for all vertices
        for (int vertex = 0; vertex < numVertices; ++vertex) {
            for (int neighbor : adjacencyList[vertex]) {
                inDegree[neighbor]++;
            }
        }

        std::queue<int> zeroInDegreeQueue;

        // Add all vertices with zero in-degree to the queue
        for (int i = 0; i < numVertices; ++i) {
            if (inDegree[i] == 0) {
                zeroInDegreeQueue.push(i);
            }
        }

        std::vector<int> resultOrder;

        // Process vertices using BFS-like approach
        while (!zeroInDegreeQueue.empty()) {
            int currentVertex = zeroInDegreeQueue.front();
            zeroInDegreeQueue.pop();
            resultOrder.push_back(currentVertex);

            // Update in-degrees of adjacent vertices
            for (int adjacentVertex : adjacencyList[currentVertex]) {
                inDegree[adjacentVertex]--;
                if (inDegree[adjacentVertex] == 0) {
                    zeroInDegreeQueue.push(adjacentVertex);
                }
            }
        }

        // Check for cycles
        if (resultOrder.size() != numVertices) {
            std::cout << "Error: The graph contains a cycle; topological sorting is impossible." << std::endl;
            return;
        }

        // Output the topological ordering
        std::cout << "Topological Order (Kahn's Method): ";
        for (int vertex : resultOrder) {
            std::cout << vertex << " ";
        }
        std::cout << std::endl;
    }

    void displayGraphStructure() {
        for (int i = 0; i < numVertices; ++i) {
            std::cout << "Vertex " << i << " connects to: ";
            for (int neighbor : adjacencyList[i]) {
                std::cout << neighbor << " ";
            }
            std::cout << std::endl;
        }
    }

    ~Digraph() {
        delete[] adjacencyList;
    }
};

int main() {
    Digraph g(6); // Create a directed graph with 6 vertices

    g.addConnection(5, 2);
    g.addConnection(5, 0);
    g.addConnection(4, 0);
    g.addConnection(4, 1);
    g.addConnection(2, 3);
    g.addConnection(3, 1);

    g.performTopologicalSortKahn();

    return 0;
}

/*
Kahn's Algorithm for Topological Sorting

Note: We avoid using a visited array here since the in-degree tracking serves as 
the mechanism to monitor which nodes have been processed.

Time Complexity: O(V + E), where V represents vertices and E represents edges.
Space Complexity: O(V), required for the in-degree array and the queue.

Algorithm Steps:
1. Determine the in-degree count for each vertex.
2. Insert all vertices with zero in-degree into a queue.
3. While the queue isn't empty:
   - Remove a vertex from the queue.
   - Append it to the topological sequence.
   - Reduce the in-degree of its neighbors by one.
   - If any neighbor's in-degree reaches zero, add it to the queue.
4. After processing, if the size of the result doesn't match the number of vertices,
   the graph contains a cycle and topological sort cannot be completed.
5. Display the resulting topological order.

Sample Output:
Topological Order (Kahn's Method): 5 4 2 3 1 0
*/

#include <iostream>
#include <vector>
#include <numeric>
#include <algorithm>

// Function to interact with the judge
int ask(int left, int right) {
    if (left >= right) {
        // This case should be prevented by the main logic
        return -1;
    }
    std::cout << "? " << left << " " << right << std::endl;
    int response;
    std::cin >> response;
    return response;
}

// Main logic for a single test case
void process() {
    int size;
    std::cin >> size;
    int low = 1, high = size;

    while (low < high) {
        // Base case for a range of size 2
        if (high - low == 1) {
            int val = ask(low, high);
            if (val == low) {
                low = high;
            } else {
                high = low;
            }
            break;
        }

        // Query the current range to find the position of the second max
        int pos = ask(low, high);

        // Handle edge cases where the second max is at an endpoint
        if (pos == low) {
            low = pos + 1;
            continue;
        }
        if (pos == high) {
            high = pos - 1;
            continue;
        }

        // At this point, low < pos < high. The max is either in [low, pos-1] or [pos+1, high].
        // We make a second query to determine which side.
        // To optimize, we query the smaller of the two potential ranges containing pos.
        if (pos - low < high - pos) {
            int pos2 = ask(low, pos);
            if (pos2 == pos) {
                // The max of arr[low...pos] is in [low, pos-1]. Since arr[pos] is the second max
                // of the larger range [low, high], this element must be the overall max.
                // So, we narrow our search to [low, pos-1].
                high = pos - 1;
            } else {
                // The max of arr[low...pos] is at position pos. This means the overall max
                // of arr[low...high] cannot be in [low, pos-1]. It must be in [pos+1, high].
                low = pos + 1;
            }
        } else {
            int pos2 = ask(pos, high);
            if (pos2 == pos) {
                // Symmetrical to the case above. The max of arr[pos...high] is in [pos+1, high].
                // This must be the overall max of arr[low...high].
                low = pos + 1;
            } else {
                // The max of arr[pos...high] is at position pos. The overall max must be in [low, pos-1].
                high = pos - 1;
            }
        }
    }
    std::cout << "! " << low << std::endl;
}

int main() {
    // Fast I/O
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int testCases;
    std::cin >> testCases;

    while (testCases--) {
        process();
    }

    return 0;
}

