{
    if (!polar) return;
    setAutoFormatting(true);
    writeStartDocument();
    {
        writeDTD("<!DOCTYPE flow5>");
        writeStartElement("XflBoatPolar");
        {
            writeAttribute("version", "1.0");
            writeUnits();
            writeBtPolarData(polar);
        }
        writeEndElement();
    }
    writeEndDocument();
}

void XmlBtPolarWriter::writeBtPolarData(BoatPolar const *polar)
{
   QString buffer;
   writeStartElement("Polar");
   {
       writeTextElement("Polar_Name", polar->name());
       writeComment("For scripts: if the boat's name is left blank, the analysis will be associated to all available boats");
       writeTextElement("Boat_Name", polar->boatName());
       writeComment("Boat polars are necessarily of the control type");
       writeTheStyle(polar->theStyle());
       writeTextElement("Method", Polar3d::analysisMethod(polar->analysisMethod()));
       writeStartElement("Reference_Dimensions");
       {
           writeComment    ("Available options are AUTO and CUSTOM");
           writeTextElement("Reference_Dimensions",   Polar3d::referenceDimension(polar->referenceDim()));
           writeComment("The following fields are required only if dimensions are set to CUSTOM");
           writeTextElement("Reference_Area",         QString::asprintf("%11.5f", polar->referenceArea()*Units::m2toUnit()));
           writeTextElement("Reference_Chord_Length", QString::asprintf("%11.5f", polar->referenceChordLength()*Units::mtoUnit()));
       }
       writeEndElement();
       writeWakeData(*polar);
       buffer = QString::asprintf("%g, %g, %g", polar->CoG().x*Units::mtoUnit(), polar->CoG().y*Units::mtoUnit(), polar->CoG().z*Units::mtoUnit());
       writeTextElement("CoG", buffer);
       writeStartElement("Wind_gradient");
       {
           writeWindSpline(polar->windSpline());
       }
       writeEndElement();
       writeFluidProperties(polar->viscosity(), polar->density());
       if(polar->hasExtraDrag())
           writeExtraDrag(polar->extraDragList());
       writeComment("Min and max values separated by a comma ,");
       writeTextElement("Boat_Speed", QString::asprintf(" %g, %g", polar->VBtMin(),  polar->VBtMax()));
       writeTextElement("TWS",        QString::asprintf(" %g, %g", polar->qInfMin(), polar->qInfMax()));
       writeTextElement("TWA",        QString::asprintf(" %g, %g", polar->twaMin(),  polar->twaMax()));
       writeTextElement("Phi",        QString::asprintf(" %g, %g", polar->phiMin(),  polar->phiMax()));
       writeTextElement("Ry",         QString::asprintf(" %g, %g", polar->RyMin(),   polar->RyMax()));
       writeStartElement("SailAngles");
       {
           for(int index=0; index<polar->sailAngleSize(); index++)
           {
               QString label, value;
               label = QString::asprintf("Sail_%d", index+1);
               value = QString::asprintf("%.3f,  %.3f", polar->sailAngleMin(index), polar->sailAngleMax(index));
               writeTextElement(label, value);
           }
       }
       writeEndElement();
   }
   writeEndElement();
}

void XmlBtPolarWriter::writeWindSpline(BSpline const &spline)
{
    writeTextElement("Degree", QString::asprintf("%d",spline.degree()));
    for(int i=0; i<spline.ctrlPointCount(); i++)
    {
        writeTextElement("Point", QString::asprintf("%g, %g", spline.controlPoint(i).x, spline.controlPoint(i).y)); // meters only
    }
}

