#include <iostream>
#include <vector>
#include <queue>
#include <algorithm>

// Structure representing a candidate state for the priority queue.
// Contains the computed value f(l,T), along with its parameters l (length) and T (time).
struct Candidate {
    int score;
    int len, time;
    // Overload operator< for min-heap behavior using std::greater
    bool operator<(const Candidate& other) const {
        return score > other.score;
    }
};

void process() {
    int size;
    long long k;
    std::cin >> size >> k;

    // Input grid data (not directly used in this approach)
    std::vector<std::vector<int>> grid(size, std::vector<int>(size));
    for (int row = 0; row < size; ++row) {
        for (int col = 0; col < size; ++col) {
            std::cin >> grid[row][col];
        }
    }

    // Min-priority queue to efficiently retrieve smallest values of f(l,T)
    std::priority_queue<Candidate, std::vector<Candidate>, std::greater<Candidate>> heap;

    // Initialize with all f(1, T) candidates for T from 1 to 2*size-1
    for (int T = 1; T < 2 * size; ++T) {
        std::cout << "? 1 " << T << std::endl;
        int val;
        std::cin >> val;
        heap.push({val, 1, T});
    }

    std::vector<int> answers;
    answers.reserve(k);

    // Extract k smallest values using the priority queue
    for (int count = 0; count < k; ++count) {
        Candidate current = heap.top();
        heap.pop();
        answers.push_back(current.score);

        // If possible, add next candidate: f(l+1, T) for same T
        if (current.len < size) {
            std::cout << "? " << current.len + 1 << " " << current.time << std::endl;
            int next_score;
            std::cin >> next_score;
            heap.push({next_score, current.len + 1, current.time});
        }
    }

    // Output final result
    std::cout << "!";
    for (int idx = 0; idx < k; ++idx) {
        std::cout << " " << answers[idx];
    }
    std::cout << std::endl;
}

