namespace ap::plat {

std::array<uint32_t, 4> CpuInfo::cpuid(int function_id) noexcept {
    // Use __cpuidex instead of __cpuid to preserve ECX register contents
    std::array<int, 4> registers;
    __cpuidex(registers.data(), function_id, 0);

    std::array<uint32_t, 4> result = {};
    for (size_t index = 0; index < registers.size(); ++index) {
        result[index] = static_cast<uint32_t>(registers[index]);
    }
    return result;
}

uint32_t CpuInfo::cpuidMax() noexcept {
    // Invoke __cpuid with leaf 0x0 to determine the maximum supported CPUID leaf
    std::array<int, 4> cpu_data;
    __cpuid(cpu_data.data(), 0);
    return static_cast<uint32_t>(cpu_data[0]);
}

uint32_t CpuInfo::cpuidExMax() noexcept {
    // Invoke __cpuid with extended leaf 0x80000000 to get highest extended function ID
    std::array<int, 4> ext_data;
    __cpuid(ext_data.data(), 0x80000000);
    return static_cast<uint32_t>(ext_data[0]);
}

