#include <vector>
#include <algorithm>
#include <climits>

class Solution {
public:
    // Check if the current window [windowLeft, windowRight] is reachable within k steps from startPos
    bool canReach(int windowLeft, int windowRight, int currentPos, int maxSteps) {
        if (windowRight <= currentPos) {
            // All positions are to the left of startPos
            return currentPos - windowLeft <= maxSteps;
        } else if (windowLeft >= currentPos) {
            // All positions are to the right of startPos
            return windowRight - currentPos <= maxSteps;
        } else {
            // Window spans across startPos
            int distLeft = currentPos - windowLeft;
            int distRight = windowRight - currentPos;
            // Two possible paths: go left first then right, or go right first then left
            return (2 * distLeft + distRight) <= maxSteps || (2 * distRight + distLeft) <= maxSteps;
        }
    }

    int maxTotalFruits(std::vector<std::vector<int>>& fruitData, int startPos, int k) {
        int n = fruitData.size();
        int result = INT_MIN;
        int currentSum = 0;
        int leftPtr = 0;

        for (int rightPtr = 0; rightPtr < n; rightPtr++) {
            currentSum += fruitData[rightPtr][1];

            // Shrink window from left until it becomes valid
            while (leftPtr <= rightPtr && !canReach(fruitData[leftPtr][0], fruitData[rightPtr][0], startPos, k)) {
                currentSum -= fruitData[leftPtr++][1];
            }

            result = std::max(result, currentSum);
        }

        return result;
    }
};

