void process_case() {
    int size;
    std::cin >> size;

    if (size == 0) {
        std::cout << "answer" << std::endl;
        std::cout.flush();
        return;
    }

    std::vector<std::string> starting_chars;
    std::set<std::string> collected_words;

    // Check each letter from 'a' to 'z'
    for (char letter = 'a'; letter <= 'z'; ++letter) {
        std::string candidate(1, letter);
        std::cout << "query " << candidate << " " << 1 << std::endl;
        std::cout.flush();

        int count;
        std::cin >> count;

        if (count > 0) {
            starting_chars.push_back(candidate);
            std::string word;
            std::cin >> word;
            collected_words.insert(word);
        }
    }

    // Sort in reverse order as optimization
    std::sort(starting_chars.rbegin(), starting_chars.rend());
    int remaining = size;

    for (size_t idx = 0; idx < starting_chars.size(); ++idx) {
        const std::string& current_str = starting_chars[idx];

        int match_count = 0;
        for (const auto& existing_word : collected_words) {
            if (existing_word.find(current_str) == 0) {
                match_count++;
            }
        }

        int target_count = remaining - (collected_words.size() - match_count);
        if (idx == starting_chars.size() - 1) {
            target_count = remaining - collected_words.size() + match_count;
        }

        if (target_count <= 0) continue;

        std::cout << "query " << current_str << " " << target_count << std::endl;
        std::cout.flush();

        int actual_count;
        std::cin >> actual_count;

        for (int pos = 0; pos < actual_count; ++pos) {
            std::string new_word;
            std::cin >> new_word;
            collected_words.insert(new_word);
        }
    }

    std::cout << "answer";
    for (const auto& word : collected_words) {
        std::cout << " " << word;
    }
    std::cout << std::endl;
    std::cout.flush();
}

