namespace rccl
{
namespace
{
// Renamed atomic pointer to hold API table
auto&
get_api_table_ptr()
{
    static std::atomic<rcclApiFuncTable*> s_api_table{ nullptr };
    return s_api_table;
}

void
init_profiler()
{
    // Initialize constant (read-only) API table
    static rcclApiFuncTable s_const_table{};
    initialize_rccl_api_table(&s_const_table);

    // Atomically set const table first to avoid recursion issues
    auto* expected = get_api_table_ptr().load(std::memory_order_relaxed);
    if (!get_api_table_ptr().compare_exchange_strong(expected, &s_const_table)) {
        // Already initialized by another thread — ignore
    }

    // Create modifiable copy for profiler instrumentation
    static rcclApiFuncTable s_profiler_table{};
    copy_rccl_api_table(&s_profiler_table, &s_const_table);

    void* profiler_table_ptr = &s_profiler_table;
    rocprofiler_register_library_indentifier_t lib_id{};

    auto status = rocprofiler_register_library_api_table(
        "rccl",
        &ROCPROFILER_REGISTER_IMPORT_FUNC(rccl),
        ROCP_REG_VERSION,
        &profiler_table_ptr,
        1,
        &lib_id);

    if (status == 0)
    {
        printf("[%s] rccl library registered with id %lu\n", ROCP_REG_FILE_NAME, lib_id.handle);

        // Attempt to atomically swap in the instrumented table
        rcclApiFuncTable* current = &s_const_table;
        if (!get_api_table_ptr().compare_exchange_strong(current, &s_profiler_table))
        {
            std::cerr << "[ERROR] Unexpected API table state during registration.\n";
            std::abort();
        }
    }
    else if (status != ROCP_REG_NO_TOOLS)
    {
        std::cerr << "[RCCL] Registration failed: " << rocprofiler_register_error_string(status)
                  << "\n";
        std::exit(EXIT_FAILURE);
    }
}

void
ensure_registration()
{
    static std::atomic<bool> s_is_registered{ false };

    if (!s_is_registered.load(std::memory_order_acquire))
    {
        using lock_t     = std::unique_lock<std::recursive_mutex>;
        using flag_t     = std::once_flag;
        static flag_t   s_init_once{};
        static std::recursive_mutex s_mutex{};

        lock_t lk{s_mutex, std::defer_lock};
        // Avoid deadlock if same thread re-enters during registration
        if (lk.owns_lock()) return;

        lk.lock();
        std::call_once(s_init_once, init_profiler);
        s_is_registered.store(true, std::memory_order_release);
    }
}
}  // namespace

rcclApiFuncTable*
fetch_api_table()
{
    ensure_registration();
    return get_api_table_ptr().load(std::memory_order_relaxed);
}

void
initialize_rccl_trace()
{
    printf("[%s] %s\n", ROCP_REG_FILE_NAME, __FUNCTION__);
}
}  // namespace rccl

extern "C" {
void
rccl_init(void)
{
    rccl::fetch_api_table()->ncclGetVersion_fn({});
}
