int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int totalRooms;
    std::cin >> totalRooms;
    std::vector<int> destination(totalRooms + 1);

    // Phase 1: Determine destination for each room using binary search
    std::vector<int> possibleValues(totalRooms);
    std::iota(possibleValues.begin(), possibleValues.end(), 1);

    for (int room = 1; room <= totalRooms; ++room) {
        std::vector<int> candidates = possibleValues;

        while (candidates.size() > 1) {
            int splitIndex = candidates.size() / 2;
            std::vector<int> firstHalf(candidates.begin(), candidates.begin() + splitIndex);

            int queryResult = performQuery(room, 1, firstHalf);

            if (queryResult == 1) {
                // Target is in the first half
                candidates.resize(splitIndex);
            } else {
                // Target is in the second half
                candidates.erase(candidates.begin(), candidates.begin() + splitIndex);
            }
        }
        destination[room] = candidates[0];
    }

    // Phase 2: Build adjacency list from destination mapping
    std::vector<std::vector<int>> graph(totalRooms + 1);
    for (int i = 1; i <= totalRooms; ++i) {
        graph[i].push_back(destination[i]);
        graph[destination[i]].push_back(i);
    }

    // Phase 3: BFS traversal starting from room 1
    std::vector<int> reachableRooms;
    std::vector<bool> seen(totalRooms + 1, false);
    std::queue<int> bfsQueue;

    bfsQueue.push(1);
    seen[1] = true;

    while (!bfsQueue.empty()) {
        int current = bfsQueue.front();
        bfsQueue.pop();
        reachableRooms.push_back(current);

        for (int neighbor : graph[current]) {
            if (!seen[neighbor]) {
                seen[neighbor] = true;
                bfsQueue.push(neighbor);
            }
        }
    }

    // Sort the reachable rooms for consistent output
    std::sort(reachableRooms.begin(), reachableRooms.end());

    // Output the result
    std::cout << "! " << reachableRooms.size();
    for (int room : reachableRooms) {
        std::cout << " " << room;
    }
    std::cout << std::endl;

    return 0;
}

