// Function to send a query and receive the response
char performQuery(int value) {
    std::cout << "? " << value << std::endl;
    char result;
    std::cin >> result;
    return result;
}

// Function to reset the system state
void resetSystem() {
    std::cout << "R" << std::endl;
}

// Function to output the final computed result
void reportResult(int count) {
    std::cout << "! " << count << std::endl;
}

int main() {
    // Optimize I/O operations
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int totalItems, blockSize;
    std::cin >> totalItems >> blockSize;

    // Track whether each item is the first occurrence of its kind
    std::vector<bool> isFirstOccurrence(totalItems + 1, true);

    int numGroups = totalItems / blockSize;

    // Examine all pairs of groups (g1, g2) where g1 <= g2
    for (int group1 = 0; group1 < numGroups; ++group1) {
        for (int group2 = group1; group2 < numGroups; ++group2) {
            resetSystem();

            if (group1 == group2) {
                // Check for duplicates within the same group
                for (int itemIndex = group1 * blockSize + 1; 
                     itemIndex <= (group1 + 1) * blockSize; ++itemIndex) {
                    if (isFirstOccurrence[itemIndex]) {
                        if (performQuery(itemIndex) == 'Y') {
                            isFirstOccurrence[itemIndex] = false;
                        }
                    }
                }
            } else {
                // Handle duplicates between different groups
                // First, load candidates from group1 into memory
                for (int itemIndex = group1 * blockSize + 1; 
                     itemIndex <= (group1 + 1) * blockSize; ++itemIndex) {
                    if (isFirstOccurrence[itemIndex]) {
                        performQuery(itemIndex);
                    }
                }

                // Then check items in group2 against memory
                for (int itemIndex = group2 * blockSize + 1; 
                     itemIndex <= (group2 + 1) * blockSize; ++itemIndex) {
                    if (isFirstOccurrence[itemIndex]) {
                        if (performQuery(itemIndex) == 'Y') {
                            isFirstOccurrence[itemIndex] = false;
                        }
                    }
                }
            }
        }
    }

    // Count how many unique items exist
    int uniqueCount = 0;
    for (int idx = 1; idx <= totalItems; ++idx) {
        if (isFirstOccurrence[idx]) {
            uniqueCount++;
        }
    }

    reportResult(uniqueCount);
    return 0;
}

#include <iostream>
using namespace std;

// Function to perform Selection Sort on an array
void selectionSort(int data[], int size) {
    for (int i = 0; i < size - 1; i++) {
        int minPos = i;  // Assume the current index holds the minimum value

        // Search for the smallest element in the remaining unsorted part
        for (int k = i + 1; k < size; k++) {
            if (data[k] < data[minPos]) {
                minPos = k;
            }
        }
        // Exchange the minimum element with the first element of the unsorted segment
        if (minPos != i) {
            swap(data[i], data[minPos]);
        }
    }
}

// Function to display the elements of an array
void displayArray(int data[], int size) {
    for (int i = 0; i < size; i++) {
        cout << data[i] << " ";
    }
    cout << endl;
}

int main() {
    int arr[] = {64, 25, 12, 22, 11};
    int n = sizeof(arr) / sizeof(arr[0]);
    cout << "Original array: ";
    displayArray(arr, n);
    selectionSort(arr, n);
    cout << "Sorted array: ";
    displayArray(arr, n);
    return 0;
}

