#include <assert.h>
#include <mpi.h>
#include <stdio.h>
#include <stdlib.h>
#include <time.h>

// Generate an array of random floating-point values in range [0, 1]
float*
generate_random_values(int count)
{
    float* values = (float*) malloc(sizeof(float) * count);
    assert(values != NULL);
    for (int idx = 0; idx < count; idx++) {
        values[idx] = (rand() / (float) RAND_MAX);
    }
    return values;
}

// Calculate the arithmetic mean of a given array
float
calculate_mean(float* data, int length)
{
    float accumulator = 0.0f;
    for (int i = 0; i < length; i++) {
        accumulator += data[i];
    }
    return accumulator / length;
}

int
main(int argc, char** argv)
{
    if (argc != 2) {
        fprintf(stderr, "Usage: avg num_elements_per_process\n");
        exit(1);
    }

    int elements_per_rank = atoi(argv[1]);

    // Initialize random seed for varied results
    srand(time(NULL));

    MPI_Init(NULL, NULL);

    int my_rank;
    MPI_Comm_rank(MPI_COMM_WORLD, &my_rank);

    int num_ranks;
    MPI_Comm_size(MPI_COMM_WORLD, &num_ranks);

    // Root process generates the full dataset
    float* full_dataset = NULL;
    if (my_rank == 0) {
        full_dataset = generate_random_values(elements_per_rank * num_ranks);
    }

    // Allocate local buffer for scattered data
    float* local_data = (float*) malloc(sizeof(float) * elements_per_rank);
    assert(local_data != NULL);

    // Distribute data across processes
    MPI_Scatter(full_dataset, elements_per_rank, MPI_FLOAT,
                local_data, elements_per_rank, MPI_FLOAT, 0, MPI_COMM_WORLD);

    // Compute local average
    float local_avg = calculate_mean(local_data, elements_per_rank);

    // Collect all local averages
    float* all_avgs = (float*) malloc(sizeof(float) * num_ranks);
    assert(all_avgs != NULL);

    MPI_Allgather(&local_avg, 1, MPI_FLOAT,
                  all_avgs, 1, MPI_FLOAT, MPI_COMM_WORLD);

    // Compute overall average from partial averages
    float final_avg = calculate_mean(all_avgs, num_ranks);

    printf("Average computed by rank %d: %f\n", my_rank, final_avg);

    // Cleanup memory
    if (my_rank == 0) {
        free(full_dataset);
    }
    free(all_avgs);
    free(local_data);

    MPI_Barrier(MPI_COMM_WORLD);
    MPI_Finalize();
}

#include <vector>

class Solution {
public:
    // Compute the triangular sum of the given array
    int triangularSum(std::vector<int>& values) {
        int length = values.size();

        // Process from bottom to top of the triangle
        for (int row = length - 1; row >= 1; --row) {
            // For each position in current row, compute sum of adjacent elements mod 10
            for (int pos = 0; pos < row; ++pos) {
                values[pos] = (values[pos] + values[pos + 1]) % 10;
            }
        }

        return values[0];
    }
};

