#include <iostream>
#include <vector>
#include <string>
#include <algorithm>
#include <iterator>

int main() {
    // Optimized I/O for competitive programming scenarios
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int n;
    std::cin >> n;

    // Tracks how many times each passage has been used when changing from "left" to "right"
    std::vector<int> left_to_right_count(n, 0);

    // Tracks how many times each passage has been used when changing from "right" to "left"
    std::vector<int> right_to_left_count(n, 0);

    while (true) {
        std::string position;
        std::cin >> position;

        if (position == "treasure") {
            // Target reached, exit the loop
            break;
        }

        if (position == "center") {
            // New chamber found: mark as "left" and use passage 0
            std::cout << "0 left 0" << std::endl;
        } 
        else if (position == "left") {
            // Chamber marked "left": flip to "right", choose least-used passage
            auto min_iter = std::min_element(left_to_right_count.begin(), left_to_right_count.end());
            int chosen_passage = std::distance(left_to_right_count.begin(), min_iter);

            std::cout << "0 right " << chosen_passage << std::endl;
            left_to_right_count[chosen_passage]++;
        } 
        else if (position == "right") {
            // Chamber marked "right": flip to "left", choose least-used passage
            auto min_iter = std::min_element(right_to_left_count.begin(), right_to_left_count.end());
            int chosen_passage = std::distance(right_to_left_count.begin(), min_iter);

            std::cout << "0 left " << chosen_passage << std::endl;
            right_to_left_count[chosen_passage]++;
        }
    }

    return 0;
}

#include "formatted_output.h"

namespace NLastGetopt {
    TFormattedOutput::IndentGuard::IndentGuard(TFormattedOutput* formatter)
        : Output(formatter)
    {
        Output->IndentLevel_ += 2;
    }

    TFormattedOutput::IndentGuard::~IndentGuard() {
        Output->IndentLevel_ -= 2;
    }

    TFormattedOutput::IndentGuard TFormattedOutput::Indent() {
        return IndentGuard(this);
    }

    TStringBuilder& TFormattedOutput::Line() {
        return Lines_.emplace_back(IndentLevel_, TStringBuilder()).second;
    }

    void TFormattedOutput::Print(IOutputStream& stream) {
        for (auto&[level, text] : Lines_) {
            if (level && !text.empty()) {
                TTempBuf spaces(level);
                Fill(spaces.Data(), spaces.Data() + level, ' ');
                stream.Write(spaces.Data(), level);
            }
            stream << text;
            if (!text.EndsWith('\n')) {
                stream << Endl;
            }
        }
    }
}

