// Constructor for debug options menu scene
UIScene_DebugOptionsMenu::UIScene_DebugOptionsMenu(
    int      gamePad,
    void*    initializationData,
    UILayer* parentLayerInstance
) : UIScene(gamePad, parentLayerInstance) {
    // Initialize movie system
    initialiseMovie();

    // Get current debug settings bitmask
    unsigned int currentDebugMask = app.GetGameSettingsDebugMask(gamePad);

    // Create path to player root in Iggy
    IggyValuePath* playerRoot = IggyPlayerRootPath(getMovie());

    // Initialize checkboxes based on current settings
    int checkboxCounter = 0;
    for (checkboxCounter = 0;
         checkboxCounter < eDebugSetting_Max
         && checkboxCounter < 21;
         ++checkboxCounter) {

        std::wstring checkboxLabel(m_DebugCheckboxTextA[checkboxCounter]);
        m_checkboxes[checkboxCounter].init(
            checkboxLabel,
            checkboxCounter,
            (currentDebugMask & (1 << checkboxCounter)) ? true : false
        );
    }

    m_iTotalCheckboxElements = checkboxCounter;
}

// Returns the movie path for this scene
std::wstring UIScene_DebugOptionsMenu::getMoviePath() {
    return L"DebugOptionsMenu";
}

// Handle user input events
void UIScene_DebugOptionsMenu::handleInput(
    int   gamePad,
    int   keyCode,
    bool  isRepeat,
    bool  isPressed,
    bool  isReleased,
    bool& isHandled
) {
    switch (keyCode) {
    case ACTION_MENU_CANCEL:
        if (isPressed) {
            unsigned int updatedDebugMask = 0L;
            int maskBitIndex = 0;

            // Build new bitmask from checkbox states
            for (int i = 0; i < m_iTotalCheckboxElements; i++) {
                if (m_checkboxes[i].IsChecked()) {
                    updatedDebugMask |= (1 << maskBitIndex);
                }
                maskBitIndex++;
            }

            // Update settings if changed
            if (updatedDebugMask != app.GetGameSettingsDebugMask(gamePad)) {
                app.SetGameSettingsDebugMask(gamePad, updatedDebugMask);

                if (app.DebugSettingsOn()) {
                    app.ActionDebugMask(gamePad);
                } else {
                    app.ActionDebugMask(gamePad, true);
                }

                app.CheckGameSettingsChanged(true, gamePad);
            }

            navigateBack();
        }
        break;

    case ACTION_MENU_OK:
    case ACTION_MENU_UP:
    case ACTION_MENU_DOWN:
    case ACTION_MENU_PAGEUP:
    case ACTION_MENU_PAGEDOWN:
        sendInputToMovie(keyCode, isRepeat, isPressed, isReleased);
        break;
    }
}

