  const std::vector<rslcpp::dynamic_composition::ComponentDescription> & component_list,
  rclcpp::NodeOptions const & node_options)
{
  std::vector<rclcpp::Node::SharedPtr> created_nodes;
  for (const auto & comp_desc : component_list) {
    created_nodes.emplace_back(load_single_component(comp_desc, node_options));
  }
  return created_nodes;
}

/// @brief Load a single RCLCPP component and instantiate its corresponding node
/// @param desc The component description object
/// @return std::shared_ptr<rclcpp::Node> Shared pointer to the newly created node
std::shared_ptr<rclcpp::Node> ComponentLoader::load_single_component(
  rslcpp::dynamic_composition::ComponentDescription const & desc,
  rclcpp::NodeOptions const & opts)
{
  std::cout << ">> Loading Component | " << desc.component_name << std::endl;

  std::string lib_path = rslcpp::dynamic_composition::utils::get_shared_library_path(desc);

  if (loaders.find(lib_path) == loaders.end()) {
    loaders[lib_path] = std::make_unique<class_loader::ClassLoader>(lib_path);
  }

  std::string factory_class =
    "rclcpp_components::NodeFactoryTemplate<" + desc.component_name + ">";

  auto factory_instance =
    loaders[lib_path]->createInstance<rclcpp_components::NodeFactory>(factory_class);

  // Adjust node options with component-specific arguments
  rclcpp::NodeOptions adjusted_opts = opts;
  adjusted_opts.arguments(desc.component_arguments);

  // Instantiate the node
  auto node_wrapper = factory_instance->create_node_instance(adjusted_opts);
  auto base_node = std::static_pointer_cast<rclcpp::Node>(node_wrapper.get_node_instance());

  node_wrappers.push_back(node_wrapper);
  return base_node;
}

std::vector<ComponentDescription> parse_components_from_command_line_arguments(
  int & argc, char **& argv)
{
  std::vector<ComponentDescription> components;
  std::size_t idx = 0;

  while (idx < static_cast<std::size_t>(argc)) {
    // Stop parsing when ROS arguments are encountered
    if (std::string(argv[idx]) == "--ros-args") {
      break;
    }

    if (std::string(argv[idx]) == "--component") {
      // Locate the end of this component's argument block
      std::size_t end_idx = idx + 1;
      while (end_idx < static_cast<std::size_t>(argc)) {
        auto current_arg = std::string(argv[end_idx]);
        if (current_arg == "--ros-args" || current_arg == "--component") {
          break;
        }
        end_idx++;
      }

      std::size_t num_sub_args = end_idx - idx - 1;
      if (num_sub_args < 2) {
        throw std::runtime_error(
          "DynamicComposition | '--component' specified without package and class arguments.");
      }

      // Extract required fields: package and component name
      std::string pkg_name = argv[idx + 1];
      std::string cls_name = argv[idx + 2];

      std::vector<std::string> comp_args;

      if (num_sub_args >= 3) {
        if (argv[idx + 3] == std::string("--component-ros-args")) {
          comp_args.push_back("--ros-args");
        } else {
          throw std::runtime_error(
            "DynamicComposition | If you want to add arguments per component, use "
            "'--component-ros-args' after the component name");
        }
      }

      // Collect additional ROS arguments if present
      for (std::size_t j = 4; j <= num_sub_args; ++j) {
        comp_args.push_back(argv[idx + j]);
      }

      components.emplace_back(pkg_name, cls_name, comp_args);
      idx += num_sub_args + 1;
      continue;
    }

    idx++;
  }

  // Shift remaining arguments forward in argv
  argv += idx;
  argc -= idx;

  if (argc <= 0) {
    argc = 0;
    argv = nullptr;
  }

  return components;
}
}  // namespace rslcpp::dynamic_composition

