using asio::ip::udp;

// Generate current time string for daytime service
std::string generate_timestamp()
{
  using namespace std;
  time_t current_time = time(0);
  return ctime(&current_time);
}

class udp_daytime_server
{
public:
  udp_daytime_server(asio::io_context& context)
    : socket_(context, udp::endpoint(udp::v4(), 13))
  {
    begin_receiving();
  }

private:
  void begin_receiving()
  {
    socket_.async_receive_from(
        asio::buffer(receive_buffer_), client_endpoint_,
        boost::bind(&udp_daytime_server::on_receive, this,
          asio::placeholders::error,
          asio::placeholders::bytes_transferred));
  }

  void on_receive(const asio::error_code& error,
      std::size_t /*bytes_received*/)
  {
    if (!error)
    {
      boost::shared_ptr<std::string> response(
          new std::string(generate_timestamp()));

      socket_.async_send_to(asio::buffer(*response), client_endpoint_,
          boost::bind(&udp_daytime_server::on_send, this, response,
            asio::placeholders::error,
            asio::placeholders::bytes_transferred));

      begin_receiving();
    }
  }

  void on_send(boost::shared_ptr<std::string> /*msg*/,
      const asio::error_code& /*err*/,
      std::size_t /*sent_bytes*/)
  {
  }

  udp::socket socket_;
  udp::endpoint client_endpoint_;
  boost::array<char, 1> receive_buffer_;
};

int main()
{
  try
  {
    asio::io_context service;
    udp_daytime_server server(service);
    service.run();
  }
  catch (std::exception& exception)
  {
    std::cerr << exception.what() << std::endl;
  }
  return 0;
}

#include <catch2/catch_test_macros.hpp>
#include <Gorgon/Encoding/LZMA.h>
#include <fstream>
#include <string>
using namespace Gorgon;
using namespace Gorgon::Encoding;

TEST_CASE("LZMA encode and decode vector round-trip", "[LZMA]") {
    // Load README.md from project root
    std::ifstream datafile(TESTDIR "/../../README.md", std::ios::binary);
    REQUIRE(datafile.is_open());
    std::string source((std::istreambuf_iterator<char>(datafile)),
                        std::istreambuf_iterator<char>());
    datafile.close();
    REQUIRE(!source.empty());

    // Transform to byte array
    std::vector<Byte> buffer(source.begin(), source.end());

    SECTION("Using uncompressed length (default mode)") {
        LZMA compressor(true);

        // Encode input
        std::vector<Byte> encoded;
        compressor.Encode(buffer, encoded);
        REQUIRE(!encoded.empty());

        // Encoded data must differ in size from original
        REQUIRE(encoded.size() != buffer.size());

        // Decode back
        std::vector<Byte> decoded;
        compressor.Decode(encoded, decoded);

        // Confirm round-trip integrity
        REQUIRE(decoded.size() == buffer.size());
        std::string recovered(decoded.begin(), decoded.end());
        REQUIRE(recovered == source);
    }

    SECTION("Without uncompressed length") {
        LZMA streamcompressor(false);

        // Encode input
        std::vector<Byte> encoded;
        streamcompressor.Encode(buffer, encoded);
        REQUIRE(!encoded.empty());

        // Decode using end marker (since fsize is unknown)
        std::vector<Byte> decoded;
        streamcompressor.Decode(encoded, decoded);

        // Confirm round-trip integrity
        REQUIRE(decoded.size() == buffer.size());
        std::string recovered(decoded.begin(), decoded.end());
        REQUIRE(recovered == source);
    }

    SECTION("PropertySize returns expected values") {
        LZMA lzma_with_length(true);
        REQUIRE(lzma_with_length.PropertySize() == 13); // 5 props + 8 size

        LZMA lzma_without_length(false);
        REQUIRE(lzma_without_length.PropertySize() == 5); // 5 props only
    }
}

TEST_CASE("LZMA encode and decode string round-trip", "[LZMA]") {
    std::string source = "Hello, this is a test string for LZMA compression! "
                         "It needs to be long enough to actually compress. "
                         "LZMA compression works best with repeated patterns. "
                         "Repeated patterns. Repeated patterns. Repeated patterns. "
                         "The quick brown fox jumps over the lazy dog. "
                         "The quick brown fox jumps over the lazy dog. "
                         "The quick brown fox jumps over the lazy dog.";

    LZMA encoder;

    // Compress string into byte vector
    std::vector<Byte> encoded;
    encoder.Encode(source, encoded);
    REQUIRE(!encoded.empty());

    // Decompress byte vector back to string
    std::string decoded;
    encoder.Decode(encoded, decoded);
    REQUIRE(decoded == source);
}

