// Minimal stub for Linux environments without GUI support
// Prevents linking against LGPL libraries (e.g., GTK3, libappindicator3)
// Applications should launch with --no-tray on Linux systems
namespace lemon_tray {
LinuxTray::LinuxTray()
    : exit_flag_(false)
{
    // No-op: headless environment requires no setup
}
LinuxTray::~LinuxTray() {
    // No cleanup required in headless mode
}
bool LinuxTray::initialize(const std::string& application_name, const std::string& icon_file) {
    app_name_ = application_name;
    icon_path_ = icon_file;
    LOG(DEBUG, "LinuxTray") << "Headless operation — system tray unavailable on Linux" << std::endl;
    LOG(DEBUG, "LinuxTray") << "Consider using the --no-tray command-line option" << std::endl;
    // Trigger ready callback immediately as there's no UI to initialize
    if (on_ready_) {
        on_ready_();
    }
    // Indicate failure so the host app can switch to headless behavior
    return false;
}
void LinuxTray::run() {
    LOG(DEBUG, "LinuxTray") << "Headless execution — no event loop active" << std::endl;
    // Intentionally empty: no GUI event processing needed
}
void LinuxTray::stop() {
    LOG(DEBUG, "LinuxTray") << "Headless shutdown initiated" << std::endl;
    exit_flag_ = true;
}
void LinuxTray::set_menu(const Menu& menu) {
    LOG(DEBUG, "LinuxTray") << "Headless mode — discarding menu with "
    << menu.items.size() << " entries" << std::endl;
    // No action taken in headless configuration
}
void LinuxTray::update_menu() {
    LOG(DEBUG, "LinuxTray") << "Headless mode — skipping menu refresh" << std::endl;
    // No-op: no visible menu exists
}
void LinuxTray::show_notification(
    const std::string& header,
    const std::string& body,
    NotificationType severity)
{
    // Log notification content to standard output instead of GUI
    LOG(INFO, "Notification") << header << ": " << body << std::endl;
}
void LinuxTray::set_icon(const std::string& icon_location) {
    icon_path_ = icon_location;
    LOG(DEBUG, "LinuxTray") << "Headless mode — ignoring icon request: " << icon_location << std::endl;
    // No visual feedback possible in headless mode
}
void LinuxTray::set_tooltip(const std::string& hint_text) {
    LOG(DEBUG, "LinuxTray") << "Headless mode — tooltip ignored: " << hint_text << std::endl;
    // Tooltip has no meaning without a tray icon
}
void LinuxTray::set_ready_callback(std::function<void()> callback) {
    on_ready_ = callback;
}
