#include <unordered_map>
#include <string>

class Solution {
public:
    int firstUniqChar(std::string text) {
        std::unordered_map<char, int> freq_map;

        // Count frequency of each character
        for (int idx = 0; idx < text.length(); idx++) {
            char current_char = text[idx];
            freq_map[current_char]++;
        }

        // Find first character with frequency 1
        for (int pos = 0; pos < text.length(); pos++) {
            if (freq_map[text[pos]] == 1) {
                return pos;
            }
        }

        return -1;
    }
};

#include "MainMenu.h"  // Header for the main menu screen
#include "Game.h"      // Header for the gameplay screen
