#include <Gorgon/EntryPoint.h>  // Provides the entry point function expected by the engine
#include <Gorgon/Window.h>      // Window creation and display configuration
#include <Gorgon/Scene.h>       // Scene and SceneManager type definitions
#include <Gorgon/UI.h>          // UI components (buttons, text labels, etc.)

// Engine invokes this function as the program's entry point.
// The 'args' parameter holds command-line arguments, though they are unused here.
int Main(const std::vector<std::string> &arguments) {
    // Launch the engine with a unique application identifier string.
    Gorgon::Initialize("Shooter");

    // The SceneManager manages all scenes and determines which one is currently active.
    // Gorgon::Window::Fullscreen indicates a full-screen window covering the entire display.
    // The second argument sets the window title shown in the title bar or taskbar.
    // For a non-fullscreen window, pass dimensions instead of Fullscreen.
    // In multi-monitor setups, you can specify a particular monitor after Fullscreen.
    // Use WindowManager::Monitor::Monitors() to retrieve available monitors and their specs.
    Gorgon::SceneManager sceneManager(Gorgon::Window::Fullscreen, "Shooter");

    // Initialize the UI subsystem. The integer (4) serves as the scaling factor.
    // Standard desktop scaling uses 7.5; smaller values increase element size—ideal for games.
    // Actual rendered size depends on screen resolution, ensuring consistent UI proportions
    // across diverse hardware—from low-res SBCs (e.g., 360x240) up to high-end displays (e.g., 8K).
    Gorgon::UI::Initialize(4);

    // Register both scenes. NewScene instantiates each scene class and registers it internally
    // under its corresponding ID. Scenes remain hidden until explicitly activated.
    sceneManager.NewScene<MainMenu>(MAIN_MENU);
    sceneManager.NewScene<Game>(GAME_SCENE);

    // Begin with the main menu; players transition into the game from there.
    sceneManager.SwitchScene(MAIN_MENU);

    // Transfer control to the engine. This call blocks until the user exits.
    // Internally, it repeatedly invokes doframe() and render() on the active scene,
    // targeting ~60 frames per second.
    sceneManager.Run();

    return 0;
}

