void MessageBus::transmit(Message *msg) {
    // Insert or update the message at its target address
    msg_store[msg->get_location()] = msg;
}

Message *MessageBus::fetch(uint64_t location) {
    // Search for a message at the specified location
    auto iter = msg_store.find(location);
    if (iter != msg_store.end()) {
        return iter->second;
