#include "urdf_parser/urdf_parser.h"
#include <fstream>
#include <iostream>

// Read URDF file and parse it repeatedly in a loop
int main(int argc, char** argv) {
  if (argc != 2) {
    fprintf(stderr, "Usage: %s <urdf_file>\n", argv[0]);
    return 1;
  }

  while (true) {
    std::string xml_content;
    std::ifstream input_stream(argv[1], std::ios::in);

    while (input_stream.good()) {
      std::string line_content;
      std::getline(input_stream, line_content);
      xml_content += (line_content + "\n");
    }

    input_stream.close();
    urdf::parseURDF(xml_content);
  }

  return 0;
}

