void UMoviePipelineConfigBase::CopyFrom(UMoviePipelineConfigBase* InConfig)
{
#if WITH_EDITOR
	Modify();
#endif

	// Transfer the display label from the source configuration. When duplicating from a preset,
	// the preset's display name aligns with its asset name, ensuring consistency.
	DisplayName = InConfig->DisplayName;
	Settings.Empty();

	// Duplicate each setting individually from the source config
	for (UMoviePipelineSetting* Setting : InConfig->Settings)
	{
		UMoviePipelineSetting* NewInstance = Cast<UMoviePipelineSetting>(StaticDuplicateObject(Setting, this, Setting->GetFName()));
		NewInstance->ValidateState();
		Settings.Add(NewInstance);
		OnSettingAdded(NewInstance);
	}

	// Increment serial number explicitly as Settings array was modified directly
	SettingsSerialNumber++;
}

