int main(int argc, char* argv[])
{
  try
  {
    // Validate command line parameters
    if (argc != 5)
    {
      std::cerr << "Usage: http_server <address> <port> <threads> <doc_root>\n";
      std::cerr << "  For IPv4, try:\n";
      std::cerr << "    receiver 0.0.0.0 80 1 .\n";
      std::cerr << "  For IPv6, try:\n";
      std::cerr << "    receiver 0::0 80 1 .\n";
      return 1;
    }

    // Parse thread count from arguments
    std::size_t thread_count = boost::lexical_cast<std::size_t>(argv[3]);

    // Create and initialize the web server instance
    http::server3::server web_server(argv[1], argv[2], argv[4], thread_count);

    // Start serving requests
    web_server.run();
  }
  catch (std::exception& error)
  {
    std::cerr << "error occurred: " << error.what() << "\n";
  }

  return 0;
}

