using namespace db;

StopCmd::StopCmd()
    : _argParser("stop")
{
}

StopCmd::~StopCmd() = default;

int StopCmd::execute() {
    LogSetup::setupLogConsole(); // Initialize console logging only, as the log file is managed externally

    TuringConfig settings;
    if (!_turingRoot.empty()) {
        settings.setTuringDirectory(fs::Path {_turingRoot});
    }
    _turingRoot = settings.getTuringDir().get();

    const fs::Path ipcSocketPath = settings.getSocketPath();
    if (!ipcSocketPath.exists()) {
        spdlog::error("No TuringDB server appears to be active at {}", _turingRoot);
        return EXIT_FAILURE;
    }

    // Send a STOP command to the server via the Unix domain socket
    if (!SystemEventHandler::requestStop(ipcSocketPath)) {
        spdlog::error("Failed to terminate the TuringDB instance at {}", _turingRoot);
        return EXIT_FAILURE;
    }

    LockFile lockHandle;
    lockHandle.setPath(settings.getLockFilePath());

    // Wait until the lock file is released — this may take time if the server was handling heavy workloads
    if (!lockHandle.waitUnlock(_waitDuration)) {
        spdlog::error("TuringDB at {} did not shut down within {} ms", _turingRoot, _waitDuration);
        return EXIT_FAILURE;
    }

    spdlog::info("Successfully stopped TuringDB instance at {}", _turingRoot);
    return EXIT_SUCCESS;
}

std::unique_ptr<StopCmd> StopCmd::create() {
    std::unique_ptr<StopCmd> instance {new StopCmd()};
    instance->initialize();
    return instance;
}

void StopCmd::initialize() {
    _argParser.add_description("Terminates the TuringDB server process");
    _argParser.add_argument("-turing-dir")
        .metavar("directory")
        .help("Base directory for TuringDB")
        .store_into(_turingRoot);
    _argParser.add_argument("-timeout", "-t")
        .metavar("milliseconds")
        .help("Maximum wait time in milliseconds for lock release (default: 3000)")
        .store_into(_waitDuration);
}

#include <array>
#include <iostream>
#include <string>
#include "asio.hpp"

constexpr unsigned short udp_multicast_port = 30001;

class multicast_listener
{
public:
  multicast_listener(asio::io_context& context,
      const asio::ip::address& bind_addr,
      const asio::ip::address& group_addr)
    : sock_(context)
  {
    // Set up the UDP socket for multicast reception
    asio::ip::udp::endpoint bind_endpoint(bind_addr, udp_multicast_port);
    sock_.open(bind_endpoint.protocol());
    sock_.set_option(asio::ip::udp::socket::reuse_address(true));
    sock_.bind(bind_endpoint);

    // Subscribe to the multicast group
    sock_.set_option(asio::ip::multicast::join_group(group_addr));

    start_receiving();
  }

private:
  void start_receiving()
  {
    sock_.async_receive_from(
        asio::buffer(buffer_), remote_,
        [this](std::error_code error, std::size_t bytes_transferred)
        {
          if (!error)
          {
            std::cout.write(buffer_.data(), bytes_transferred);
            std::cout << std::endl;
            start_receiving();
          }
        });
  }

  asio::ip::udp::socket sock_;
  asio::ip::udp::endpoint remote_;
  std::array<char, 2048> buffer_;
};

int main(int argc, char* argv[])
{
  try
  {
    if (argc != 3)
    {
      std::cerr << "Usage: receiver <listen_address> <multicast_address>\n";
      std::cerr << "  For IPv4, try:\n";
      std::cerr << "    receiver 0.0.0.0 239.255.0.1\n";
      std::cerr << "  For IPv6, try:\n";
      std::cerr << "    receiver :: ff31::8000:1234\n";
      return 1;
    }

    asio::io_context io_context;
    multicast_listener listener(io_context,
        asio::ip::make_address(argv[1]),
        asio::ip::make_address(argv[2]));

    io_context.run();
  }
  catch (const std::exception& ex)
  {
    std::cerr << "Error: " << ex.what() << "\n";
  }

  return 0;
}

