        R"(^https://huggingface\.co/[a-zA-Z0-9_-]+/[a-zA-Z0-9_-]+/resolve/main/.+\.onnx$)");

    for (const auto& entry : MODEL_LIBRARY) {
        CAPTURE("Validating URL for model: " << entry.identifier);
        CAPTURE("URL value: " << entry.download_url);
        REQUIRE(std::regex_match(entry.download_url, hfUrlRegex));
    }
}

TEST_CASE("InitCommand: All models specify uniform dimensionality", "[cli][init][models]") {
    // Enforce consistency with vector database expectations
    constexpr int EXPECTED_DIM = 384;

    for (const auto& entry : MODEL_LIBRARY) {
        CAPTURE("Checking dimensions for model: " << entry.identifier);
        REQUIRE(entry.output_dim == EXPECTED_DIM);
    }
}

TEST_CASE("InitCommand: Model identifiers conform to naming rules", "[cli][init][models]") {
    const std::regex idPattern(R"(^[a-zA-Z0-9][a-zA-Z0-9_-]*[a-zA-Z0-9]$)");

    for (const auto& entry : MODEL_LIBRARY) {
        CAPTURE("Verifying name format: " << entry.identifier);
        REQUIRE(std::regex_match(entry.identifier, idPattern));
    }
}

TEST_CASE("InitCommand: Model sizes fall within acceptable range", "[cli][init][models]") {
    for (const auto& entry : MODEL_LIBRARY) {
