#include "llvm/CodeGen/MachineFunctionPass.h"

using namespace llvm;

#define DEBUG_TYPE "double barriers"

STATISTIC(NumDMBsEliminated, "Number of DMBs eliminated");

namespace {
class ARMOptimizeBarriersPass : public MachineFunctionPass {
public:
  static char ID;
  ARMOptimizeBarriersPass() : MachineFunctionPass(ID) {}

  bool runOnMachineFunction(MachineFunction &Func) override;

  MachineFunctionProperties getRequiredProperties() const override {
    return MachineFunctionProperties().set(
        MachineFunctionProperties::Property::NoVRegs);
  }

  StringRef getPassName() const override { 
    return "barrier optimization pass"; 
  }
};

char ARMOptimizeBarriersPass::ID = 0;
}

// Returns true if the instruction can be safely reordered across a DMB.
// This is the case only if MI has no memory-accessing behavior or side effects.
static bool CanReorderAcrossDMB(const MachineInstr *Instr) {
  return !(Instr->mayLoad() ||
           Instr->mayStore() ||
           Instr->hasUnmodeledSideEffects() ||
           Instr->isCall() ||
           Instr->isReturn());
}

bool ARMOptimizeBarriersPass::runOnMachineFunction(MachineFunction &Func) {
  if (skipFunction(Func.getFunction()))
    return false;

  std::vector<MachineInstr *> ToDelete;
  int64_t LastDMBImm = -1;

  for (auto &MBB : Func) {
    bool NextDMBIsCandidate = false;

    for (auto &Instr : MBB) {
      if (Instr.getOpcode() == ARM::DMB) {
        if (NextDMBIsCandidate) {
          // Check if current DMB matches previous one in type
          if (Instr.getOperand(0).getImm() == LastDMBImm) {
            ToDelete.push_back(&Instr);
          } else {
            // Update tracking for new DMB type
            LastDMBImm = Instr.getOperand(0).getImm();
          }
        } else {
          // Mark next DMB as potential candidate for removal
          NextDMBIsCandidate = true;
          LastDMBImm = Instr.getOperand(0).getImm();
        }
      } else if (!CanReorderAcrossDMB(&Instr)) {
        // Reset candidate status upon encountering non-reorderable instruction
        NextDMBIsCandidate = false;
      }
    }
  }

  bool Modified = false;
  for (auto *Instr : ToDelete) {
    Instr->eraseFromParent();
    ++NumDMBsEliminated;
    Modified = true;
  }

  return Modified;
}

/// createARMOptimizeBarriersPass - Returns an instance of the barrier
/// optimization pass that eliminates redundant DMB instructions.
FunctionPass *llvm::createARMOptimizeBarriersPass() {
  return new ARMOptimizeBarriersPass();
}

