// NOTE:
// There are TWO ways to retrieve the "this"
// object from calls, when it comes to constructors and regular
// member functions please pay attention to both: this is a
// low-level operation!
int main() {
    struct entity {
        entity(sol::this_state ts) {
            lua_State* L = ts;
            // references the object that called this function
            // in constructors:
            sol::stack_object selfobj(L, 1);
            // definitely the same
            entity& self = selfobj.as<entity>();
            SOL_ASSERT(&self == this);
        }
        void method(sol::this_state ts) const {
            lua_State* L = ts;
            // references the object that called this function
            // in regular member functions:
            sol::stack_object selfobj(L, 1);
            // "1" is the bottom of the Lua stack
            // 2 is one up, so on and so forth...
            entity& self = selfobj.as<entity>();
            // definitely the same
            SOL_ASSERT(&self == this);
        }
    };
    sol::state vm;
    vm.open_libraries(sol::lib::base);
    vm.new_usertype<entity>("entity",
         sol::constructors<entity(sol::this_state)>(),
         "method",
         &entity::method);
    vm.script(R"(
obj = entity.new()
obj:method()
	)");
    return 0;
}

