using json = nlohmann::json;
using namespace nlohmann::literals;

// Function to display UBJSON byte in diagnostic format
void show_byte(uint8_t value)
{
    if (value > 32 && value < 128)
    {
        std::cout << static_cast<char>(value);
    }
    else
    {
        std::cout << static_cast<int>(value);
    }
}

int main()
{
    // Build a JSON object
    json obj = R"({"compact": true, "schema": false})"_json;

    // Convert to UBJSON format
    std::vector<std::uint8_t> bytes = json::to_ubjson(obj);

    // Output the encoded bytes
    for (auto& item : bytes)
    {
        show_byte(item);
    }
    std::cout << std::endl;

    // Create a numeric array
    json numbers = {1, 2, 3, 4, 5, 6, 7, 8};

    // Encode with default settings
    std::vector<std::uint8_t> bytes_default = json::to_ubjson(numbers);

    // Encode with size optimization enabled
    std::vector<std::uint8_t> bytes_size_opt = json::to_ubjson(numbers, true);

    // Encode with both size and type optimizations enabled
    std::vector<std::uint8_t> bytes_full_opt = json::to_ubjson(numbers, true, true);

    // Display each encoding result
    for (auto& item : bytes_default)
    {
        show_byte(item);
    }
    std::cout << std::endl;

    for (auto& item : bytes_size_opt)
    {
        show_byte(item);
    }
    std::cout << std::endl;

    for (auto& item : bytes_full_opt)
    {
        show_byte(item);
    }
    std::cout << std::endl;

    return 0;
}

