#include "ptn/patternia.hpp"
#include "parse_json_pred.hpp"
#include "parse_json_handler.hpp"

using namespace ptn;

void json_parser(const json &data, int level = 0) {
  match(data)
      .when(bind()[is_type(json::value_t::null)] >> show_null(level))
      .when(bind()[is_type(json::value_t::boolean)] >> show_bool(level))
      .when(
          bind()[is_type(json::value_t::number_integer)] >>
          show_number<int>("int", level))
      .when(
          bind()[is_type(json::value_t::number_unsigned)] >>
          show_number<unsigned>("uint", level))
      .when(
          bind()[is_type(json::value_t::number_float)] >>
          show_number<double>("float", level))
      .when(bind()[is_type(json::value_t::string)] >> show_string(level))
      .when(
          bind()[is_empty_array] >>
          [=](const json &) {
            indent(level);
            std::cout << "array []\n";
          })
      .when(
          bind()[is_type(json::value_t::array)] >>
          [=](const json &arr) {
            indent(level);
            std::cout << "array (" << arr.size() << ")\n";
            for (auto &item : arr) {
              json_parser(item, level + 1);
            }
          })
      .when(
          bind()[has_field("name")] >>
          [=](const json &obj) {
            indent(level);
            std::cout << "object <named>\n";
            for (auto &&[key, val] : obj.items()) {
              indent(level + 1);
              std::cout << key << ":\n";
              json_parser(val, level + 2);
            }
          })
      .otherwise([=] {
        indent(level);
        std::cout << "<unknown>\n";
      });
}

