#include <iostream>
#include <algorithm>
#include <vector>
using namespace std;

class Solution {
public:
    void nextPermutation(vector<int>& arr) {
        int size = arr.size();
        int pivot = -1;

        // Step 1: Locate the rightmost element that is smaller than its successor
        for (int idx = size - 2; idx >= 0; idx--) {
            if (arr[idx] < arr[idx + 1]) {
                pivot = idx;
                break;
            }
        }

        if (pivot == -1) {
            // If no such element exists, the sequence is in descending order
            // Reverse the whole array to get the smallest permutation
            reverse(arr.begin(), arr.end());
        } else {
            // Step 2: Find the smallest element in the suffix that is larger than arr[pivot]
            for (int jdx = size - 1; jdx > pivot; jdx--) {
                if (arr[jdx] > arr[pivot]) {
                    swap(arr[jdx], arr[pivot]);
                    break;
                }
            }

            // Step 3: Reverse the suffix after the pivot position
            reverse(arr.begin() + pivot + 1, arr.end());
        }
    }
};

