#include <vector>
#include <algorithm>

class Solution {
public:
    // Calculate minimum number of rescue boats needed
    int numRescueBoats(std::vector<int>& people, int limit) {
        int n = people.size();
        int result = 0;
        int left = 0;

        std::sort(people.begin(), people.end());

        for (int right = n - 1; right >= left; right--) {
            result++;
            if (people[right] + people[left] <= limit) {
                left++;
            }
        }

        return result;
    }
};

#include <sm/vec>
#include <sm/vvec>
#include <mplot/Visual.h>
#include <mplot/GraphVisual.h>
#include <mplot/unicode.h>

namespace uc = mplot::unicode;

int main()
{
    // Initialize a mplot::Visual window with specified dimensions and title
    mplot::Visual scene(1024, 768, "Dual-axis GraphVisual Demo");

    // Instantiate a GraphVisual for double-precision data, positioned at origin
    auto graph = std::make_unique<mplot::GraphVisual<double>>(sm::vec<float, 3>{0.0f});
    scene.bindmodel(graph);

    // Configure axis style to twinax for dual y-axes support
    graph->axisstyle = mplot::axisstyle::twinax;

    // Prepare x-axis data using vvec (vector-like container with math operations)
    sm::vvec<double> abscissa;
    abscissa.linspace(-0.5, 0.8, 14);  // Generate 14 points from -0.5 to 0.8

    // Define curve label using Unicode Greek letter alpha and superscript 3
    std::string curveLabel = uc::toUtf8(uc::alpha) + "(x) = x" + uc::toUtf8(uc::ss3);

    // Plot the cubic function on the right y-axis
    graph->setdata(abscissa, abscissa.pow(3), curveLabel, mplot::axisside::right);

    // Disable left y-axis label and set right y-axis label to Greek alpha
    graph->ylabel = "";
    graph->ylabel2 = uc::toUtf8(uc::alpha);

    // Finalize graph geometry for rendering
    graph->finalize();

    // Register the graph model with the visual scene
    scene.addVisualModel(graph);

    // Display the visualization until user exits via 'Ctrl-q'
    scene.keepOpen();

    // Automatic cleanup when scene goes out of scope
    return 0;
}

