#define _GNU_SOURCE
#define ROCPROFSYS_PUBLIC_API   __attribute__((visibility("default")));
#define ROCPROFSYS_HIDDEN_API   __attribute__((visibility("hidden")));
#define ROCPROFSYS_INTERNAL_API __attribute__((visibility("internal")));
#include <dlfcn.h>
#include <stdbool.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>

//
// local type definitions
//
typedef int (*user_main_func_t)(int, char**, char**);
typedef void (*init_routine_t)(void);
typedef int (*libc_start_wrapper_t)(int (*)(int, char**, char**), int, char**, void (*)(void),
                                    void (*)(void), void (*)(void), void*);

//
// local function declarations
//
int
rocprofsys_libc_interceptor(int (*)(int, char**, char**), int, char**, void (*)(void),
                            void (*)(void), void (*)(void), void*) ROCPROFSYS_INTERNAL_API;
int
__libc_start_main_wrapper(int (*)(int, char**, char**), int, char**, void (*)(void),
                          void (*)(void), void (*)(void), void*) ROCPROFSYS_PUBLIC_API;

//
// external function declarations
//
extern int
rocprofsys_preload_library(void);
extern void
rocprofsys_shutdown(void);
extern void
rocprofsys_enter_region(const char* label);
extern void
rocprofsys_exit_region(const char* label);
extern void
rocprofsys_bootstrap_tooling(void);
extern void
rocprofsys_initialize(const char*, bool, const char*);
extern char*
get_filename(const char*);
extern void rocprofsys_assign_main(user_main_func_t) ROCPROFSYS_INTERNAL_API;
extern void
rocprofsys_assign_init_handler(init_routine_t func) ROCPROFSYS_INTERNAL_API;
extern void
rocprofsys_run_init_handlers(void) ROCPROFSYS_INTERNAL_API;
extern int
rocprofsys_entry_point(int argc, char** argv, char** envp) ROCPROFSYS_INTERNAL_API;

int
rocprofsys_libc_interceptor(int (*_entry)(int, char**, char**), int _count, char** _args,
                            void (*_setup)(void), void (*_cleanup)(void),
                            void (*_rtld_cleanup)(void), void* _stack_top)
{
    int _loaded = rocprofsys_preload_library();
    // prevent re-entry
    static int _flag = 0;
    if(_flag > 0) return -1;
    _flag = 1;

    // capture current function address
    void* _current_addr = __builtin_return_address(0);

    // store original main and init functions
    rocprofsys_assign_main(_entry);
    rocprofsys_assign_init_handler(_setup);

    // locate the real __libc_start_main implementation
    libc_start_wrapper_t real_impl = dlsym(RTLD_NEXT, "__libc_start_main");

    // disable further preloading
    setenv("ROCPROFSYS_PRELOAD", "0", 1);

    if(real_impl && real_impl != _current_addr)
    {
        if(_loaded == 0)
        {
            // delegate to original libc_start_main
            return real_impl(_entry, _count, _args, _setup, _cleanup, _rtld_cleanup, _stack_top);
        }
        else
        {
            // use rocprofsys wrapper instead of user main
            return real_impl(rocprofsys_entry_point, _count, _args, _setup, _cleanup,
                             _rtld_cleanup, _stack_top);
        }
    }
    else
    {
        fprintf(stderr, "Error! rocprofsys failed to resolve __libc_start_main!\n");
        return -1;
    }
}

int
__libc_start_main_wrapper(int (*_entry)(int, char**, char**), int _count, char** _args,
                          void (*_setup)(void), void (*_cleanup)(void),
                          void (*_rtld_cleanup)(void), void* _stack_top)
{
    // redirect control to our interceptor
    return rocprofsys_libc_interceptor(_entry, _count, _args, _setup, _cleanup,
                                       _rtld_cleanup, _stack_top);
}

