namespace FFBEngineTests {

TEST_CASE(test_executable_metadata, "Security") {
    std::cout << "\nAssessment: Executable Metadata & Version Info (Security)" << std::endl;

    // 1. Acquire current executable path
    char exePath[MAX_PATH_LEN];
    if (GetModuleFileNameA(NULL, exePath, MAX_PATH_LEN) == 0) {
        std::cout << "[ERROR] GetModuleFileNameA failed: " << GetLastError() << std::endl;
        g_tests_failed++;
        return;
    }
    std::cout << "  Inspecting: " << exePath << std::endl;

    // 2. Determine version info size
    DWORD dwUnused = 0;
    DWORD dwVersionSize = GetFileVersionInfoSizeA(exePath, &dwUnused);
    if (dwVersionSize == 0) {
        std::cout << "[ERROR] GetFileVersionInfoSizeA failed (No Version Resource found): " << GetLastError()
                  << " (Ensure BUILD_HEADLESS=OFF when building locally)" << std::endl;
        g_tests_failed++;
        return;
    }

    // 3. Retrieve version info data
    std::vector<BYTE> versionBuffer(dwVersionSize);
    if (!GetFileVersionInfoA(exePath, dwUnused, dwVersionSize, versionBuffer.data())) {
        std::cout << "[ERROR] GetFileVersionInfoA failed: " << GetLastError() << std::endl;
        g_tests_failed++;
        return;
    }

    // 4. Extract language & codepage info
    struct LangAndCodePage {
        WORD wLanguage;
        WORD wCodePage;
    } *pLangCodePage;
    UINT langCodePageSize;

    if (!VerQueryValueA(versionBuffer.data(), "\\VarFileInfo\\Translation", (LPVOID*)&pLangCodePage, &langCodePageSize)) {
        std::cout << "[ERROR] VerQueryValueA (Translation) failed" << std::endl;
        g_tests_failed++;
        return;
    }

    // Use first available language/codepage
    char subBlock[64];
    sprintf_s(subBlock, "\\StringFileInfo\\%04x%04x\\CompanyName", pLangCodePage[0].wLanguage, pLangCodePage[0].wCodePage);

    char* companyNamePtr = nullptr;
    UINT companyNameLen = 0;

    if (VerQueryValueA(versionBuffer.data(), subBlock, (LPVOID*)&companyNamePtr, &companyNameLen)) {
        std::string company(companyNamePtr);
        std::cout << "  CompanyName: " << company << std::endl;
        VERIFY_ASSERTION(company == "lmuFFB");
    } else {
        std::cout << "[ERROR] Could not query CompanyName" << std::endl;
        g_tests_failed++;
    }

    // Verify ProductVersion
    sprintf_s(subBlock, "\\StringFileInfo\\%04x%04x\\ProductVersion", pLangCodePage[0].wLanguage, pLangCodePage[0].wCodePage);
    char* productVersionPtr = nullptr;
    if (VerQueryValueA(versionBuffer.data(), subBlock, (LPVOID*)&productVersionPtr, &companyNameLen)) {
        std::string version(productVersionPtr);
        std::cout << "  ProductVersion: " << version << std::endl;

        bool matches = (version.find(LMUFFB_VERSION) == 0);
        if (!matches) {
            std::cout << "  [WARNING] expected prefix: " << LMUFFB_VERSION << ", actual: " << version << std::endl;
        }
        VERIFY_ASSERTION(matches);
    } else {
        std::cout << "[ERROR] Could not query ProductVersion" << std::endl;
        g_tests_failed++;
    }
}

TEST_CASE(test_is_window_safety, "Security") {
    std::cout << "\nAssessment: IsWindow Logic Safety (Simulated)" << std::endl;

    // Ensure robustness against NULL or invalid window handles
    // 1. Test NULL handle
    HWND nullHandle = NULL;
    BOOL result1 = IsWindow(nullHandle);
    VERIFY_ASSERTION(result1 == 0);

    // 2. Test likely-invalid handle
    HWND fakeHandle = reinterpret_cast<HWND>(reinterpret_cast<intptr_t>(0x87654321)); // NOLINT(performance-no-int-to-ptr)
    BOOL result2 = IsWindow(fakeHandle);
    VERIFY_ASSERTION(result2 == 0);

    // 3. Test valid console window (if available)
    HWND consoleWindow = GetConsoleWindow();
    if (consoleWindow) {
        BOOL result3 = IsWindow(consoleWindow);
        VERIFY_ASSERTION(result3 != 0);
    } else {
        std::cout << "  [SKIP] No console window present for valid-handle test" << std::endl;
    }
}

