namespace yams::cli {

class AuthCommand : public ICommand {
public:
    std::string getName() const override { return "authentication"; }
    std::string getDescription() const override { return "Handle authentication keys, tokens, and API credentials"; }

    void registerCommand(CLI::App& app, YamsCLI* cli) override {
        cli_ = cli;
        auto* cmd = app.add_subcommand("auth", getDescription());
        cmd->require_subcommand();

        // Key generation subcommand
        auto* keygenCmd = cmd->add_subcommand("generate-keys", "Create new authentication key pairs");
        keygenCmd->add_option("--algorithm", algorithm_, "Key generation algorithm (ed25519, rsa)")
            ->default_val("ed25519")
            ->check(CLI::IsMember({"ed25519", "rsa"}));
        keygenCmd->add_option("--dest", destinationPath_, "Target directory for storing keys")
            ->default_val((yams::config::get_config_dir() / "keys").string());
        keygenCmd->add_flag("--overwrite", overwrite_, "Replace existing key files if present");
        keygenCmd->callback([this]() {
            spdlog::info("Key generation command - Scheduled for Phase 2");
            spdlog::info("Will produce {} key pair in: {}", algorithm_, destinationPath_);
            std::cout << "Progress: Phase 2 - Feature pending implementation\n";
            std::cout << "Usage example: yams auth generate-keys [--algorithm ed25519|rsa] [--dest directory]\n";
            std::cout << "\nInfo: The 'init' command already creates Ed25519 keys by default.\n";
            std::cout << "This command will extend key management with more flexibility.\n";
            std::exit(0);
        });

        // List keys subcommand
        auto* listKeysCmd = cmd->add_subcommand("show-keys", "Display stored authentication keys");
        listKeysCmd->add_flag("-v,--verbose", detailedOutput_, "Include extended metadata in output");
        listKeysCmd->add_option("--output-mode", outputFormat_, "Result formatting (table, json)")
            ->default_val("table")
            ->check(CLI::IsMember({"table", "json"}));
        listKeysCmd->callback([]() {
            spdlog::info("Key listing command - Scheduled for Phase 2");
            std::cout << "Progress: Phase 2 - Feature pending implementation\n";
            std::cout << "Usage example: yams auth show-keys [--verbose] [--output-mode table|json]\n";
            std::cout << "\nThis will display:\n";
            std::cout << "  - Ed25519 public keys\n";
            std::cout << "  - RSA key pairs\n";
            std::cout << "  - Registered API tokens\n";
            std::cout << "  - Key identifiers and creation timestamps\n";
            std::exit(0);
        });

        // Revoke key subcommand
        auto* revokeCmd = cmd->add_subcommand("invalidate", "Revoke a specific authentication key");
        revokeCmd->add_option("identifier", keyIdentifier_, "Key fingerprint or ID to invalidate")->required();
        revokeCmd->add_flag("--silent", bypassConfirm_, "Suppress interactive confirmation prompt");
        revokeCmd->callback([this]() {
            spdlog::info("Key revocation command - Scheduled for Phase 2");
            spdlog::info("Targeting key for invalidation: {}", keyIdentifier_);
            std::cout << "Progress: Phase 2 - Feature pending implementation\n";
            std::cout << "Usage example: yams auth invalidate <identifier> [--silent]\n";
            std::cout << "\nThis operation will:\n";
            std::cout << "  - Update internal revocation registry\n";
            std::cout << "  - Invalidate active sessions using the key\n";
            std::cout << "  - Ensure future requests are rejected\n";
            std::exit(0);
        });

        // Token generation subcommand (JWT)
        auto* tokenCmd = cmd->add_subcommand("create-token", "Produce a JWT access token");
        tokenCmd->add_option("--private-key", privateKeyPath_, "Path to signing private key")
            ->default_val((yams::config::get_config_dir() / "keys" / "ed25519.pem").string());
        tokenCmd->add_option("--ttl", ttl_, "Token validity period (e.g., '12h', '30d')")
            ->default_val("12h");
        tokenCmd->add_option("--payload", customClaims_, "Additional JWT payload fields (JSON format)")
            ->default_val("{}");
        tokenCmd->callback([this]() {
            spdlog::info("Token creation command - Scheduled for Phase 2");
            spdlog::info("Generating JWT with duration: {}", ttl_);
            std::cout << "Progress: Phase 2 - Feature pending implementation\n";
            std::cout << "Usage example: yams auth create-token [--private-key path] [--ttl duration] "
                         "[--payload json]\n";
            std::cout << "\nThis will generate a signed JWT suitable for API authorization.\n";
            std::exit(0);
        });

        // API key management subcommand
        auto* apiKeyCmd = cmd->add_subcommand("create-api-key", "Generate a new API credential");
        apiKeyCmd->add_option("--label", apiKeyLabel_, "Descriptive name for the API key")->required();
        apiKeyCmd->add_option("--scopes", scopeList_, "Comma-separated permission scopes")
            ->default_val("read,write");
        apiKeyCmd->add_option("--deadline", deadline_, "Expiration timestamp (ISO 8601 or 'permanent')")
            ->default_val("permanent");
        apiKeyCmd->callback([this]() {
            spdlog::info("API key generation command - Scheduled for Phase 2");
            spdlog::info("Creating API key labeled: {}", apiKeyLabel_);
            std::cout << "Progress: Phase 2 - Feature pending implementation\n";
            std::cout << "Usage example: yams auth create-api-key --label <name> [--scopes read,write] "
                         "[--deadline date]\n";
            std::cout << "\nThis will:\n";
            std::cout << "  - Generate a cryptographically secure random key\n";
            std::cout << "  - Store associated metadata securely\n";
            std::cout << "  - Display the key once (not recoverable later)\n";
            std::exit(0);
        });
    }

    Result<void> execute() override {
        // This shouldn't be reached as subcommands handle execution
        return Error{ErrorCode::NotImplemented, "Authentication command requires a subcommand"};
    }

private:
    YamsCLI* cli_ = nullptr;
    std::string algorithm_;
    std::string destinationPath_;
    std::string keyIdentifier_;
    std::string privateKeyPath_;
    std::string ttl_;
    std::string customClaims_;
    std::string apiKeyLabel_;
    std::string scopeList_;
    std::string deadline_;
    std::string outputFormat_;
    bool overwrite_ = false;
    bool detailedOutput_ = false;
    bool bypassConfirm_ = false;
};

// Factory function
std::unique_ptr<ICommand> createAuthCommand() {
    return std::make_unique<AuthCommand>();
}

