#ifdef _WINDOWS
#if defined(_MSC_VER) || defined(_MSC_EXTENSIONS)
  #define EPOCH_DIFFERENCE_MICROSECS  11644473600000000Ui64
#else
  #define EPOCH_DIFFERENCE_MICROSECS  11644473600000000ULL
#endif

struct timezone_data {
  int  offset_minutes; /* minutes W of Greenwich */
  int  dst_status;     /* type of dst correction */
};

int get_system_time(struct timeval *time_val, struct timezone_data *tz_data)
{
  FILETIME current_file_time;
  unsigned __int64 time_in_units = 0;
  static int initialized_timezone = 0;

  if (NULL != time_val)
  {
    GetSystemTimeAsFileTime(&current_file_time);

    time_in_units |= (unsigned long long)current_file_time.dwHighDateTime;
    time_in_units <<= 32;
    time_in_units |= (unsigned long long)current_file_time.dwLowDateTime;

    time_in_units /= 10;
    time_in_units -= EPOCH_DIFFERENCE_MICROSECS;

    time_val->tv_sec = (long)(time_in_units / 1000000UL);
    time_val->tv_usec = (long)(time_in_units % 1000000UL);
  }

  if (NULL != tz_data) {
    if (!initialized_timezone) {
      _tzset();
      initialized_timezone++;
    }
    long seconds_offset;
    int daylight_flag;
    _get_timezone(&seconds_offset);
    _get_daylight(&daylight_flag);

    tz_data->offset_minutes = seconds_offset / 60;
    tz_data->dst_status = daylight_flag;
  }

  return 0;
}
#endif

ScopeTimer::ScopeTimer(const char* label) : _label(label), _startTimestamp(get_monotonic_time()) {}
ScopeTimer::~ScopeTimer() {
  std::cerr << _label << " execution time: " << 1000 * (get_monotonic_time() - _startTimestamp) << " ms\n";
}

double get_monotonic_time()
{
#if (defined(_POSIX_TIMERS) && (_POSIX_TIMERS + 0 >= 0) && defined(_POSIX_MONOTONIC_CLOCK))
  struct timespec ts;
  clock_gettime(CLOCK_MONOTONIC, &ts);
  return static_cast<double>(ts.tv_sec) + static_cast<double>(ts.tv_nsec) * 1e-9;
#else
  return get_wall_clock_time();
#endif
}

