#include <iostream>

/**
 * Solves the interactive Maze problem using a greedy approach.
 * 
 * The idea is to move step by step toward the exit by identifying which edge leads
 * closer (toward "up"), based on distance queries.
 * 
 * At each node at depth `d > 0`, exactly one edge leads to depth `d-1` ("up"),
 * and two lead to depth `d+1` ("down").
 * 
 * To determine the "up" edge:
 * - Try edge color 0: if depth decreases, it's the up edge; otherwise, backtrack.
 * - Try edge color 1 similarly.
 * - If both 0 and 1 are down edges, then color 2 must be the up edge.
 * 
 * This avoids unnecessary queries in the worst case.
 * 
 * Complexity: Each level descent costs at most 5 moves and 2 queries.
 * With max depth ~10^4, total operations stay under 10^5 limits.
 */
void solve() {
    long long current_depth;
    std::cin >> current_depth;
    while (current_depth > 0) {
        bool up_found = false;

        // Attempt colors 0 and 1 to find the upward path
        for (int color = 0; color < 2; ++color) {
            // Send move command
            std::cout << "move " << color << std::endl;
            int result;
            std::cin >> result;
            if (result == 1) {
                return; // Exit reached
            }

            // Query new depth
            std::cout << "query" << std::endl;
            long long next_depth;
            std::cin >> next_depth;

            if (next_depth < current_depth) {
                // Correct direction found
                current_depth = next_depth;
                up_found = true;
                break;
            } else {
                // Move back to original position
                std::cout << "move " << color << std::endl;
                std::cin >> result; // Discard or verify (should be 0)
            }
        }

        if (up_found) {
            continue;
        }

        // Only remaining possibility: color 2 is the up edge
        std::cout << "move 2" << std::endl;
        int exit_flag;
        std::cin >> exit_flag;
        if (exit_flag) {
            return;
        }

        // Depth decreased by 1, no query needed
        current_depth--;
    }
}

int main() {
    // Interactive problems require immediate output flushing
    // Using std::endl ensures this automatically
    solve();
    return 0;
}

