// singleton instance for monitoring system-wide resource usage
GlobalResourceMonitor gSingleton;
}  // namespace

int64_t GlobalResourceMonitor::current() const noexcept {
  return _current_value.load(std::memory_order_relaxed);
}

GlobalResourceMonitor::Stats GlobalResourceMonitor::stats() const noexcept {
  return {
    .global_exceeded_count =
      _global_exceeded_counter.load(std::memory_order_relaxed),
    .local_exceeded_count =
      _local_exceeded_counter.load(std::memory_order_relaxed),
  };
}

void GlobalResourceMonitor::recordGlobalExceedance() noexcept {
  _global_exceeded_counter.fetch_add(1, std::memory_order_relaxed);
}

void GlobalResourceMonitor::recordLocalExceedance() noexcept {
  _local_exceeded_counter.fetch_add(1, std::memory_order_relaxed);
}

/// Attempt to increase the tracked memory usage by <amount> bytes.
/// Returns false if the operation would exceed the configured limit.
/// Otherwise, updates the internal counter and returns true.
bool GlobalResourceMonitor::increaseMemoryUsage(int64_t amount) noexcept {
  SDB_ASSERT(amount >= 0);
  if (_max_limit == 0) {
    // no limit set: perform atomic increment directly
    _current_value.fetch_add(amount, std::memory_order_relaxed);
  } else {
    // enforce limit using compare-and-swap loop
    int64_t current = _current_value.load(std::memory_order_relaxed);
    int64_t proposed;
    do {
      proposed = current + amount;
      if (proposed > _max_limit) [[unlikely]] {
        return false;
      }
    } while (
      !_current_value.compare_exchange_weak(current, proposed,
                                            std::memory_order_relaxed));
  }
  return true;
}

void GlobalResourceMonitor::decreaseMemoryUsage(int64_t amount) noexcept {
  SDB_ASSERT(amount >= 0);
  _current_value.fetch_sub(amount, std::memory_order_relaxed);
}

void GlobalResourceMonitor::overrideMemoryUsage(int64_t delta) noexcept {
  _current_value.fetch_add(delta, std::memory_order_relaxed);
}

GlobalResourceMonitor& GlobalResourceMonitor::get() noexcept {
  return gSingleton;
}
