// Topological Sorting:
// Linear ordering of vertices such that for every directed edge u -> v, vertex u comes before v in the ordering.
// Uses: To solve dependency resolution problems, scheduling tasks, etc.
class Digraph {
    int numVertices; // Number of vertices
    list<int>* adjacencyList; // Adjacency list representation
public:
    Digraph(int numVertices) {
        this->numVertices = numVertices;
        adjacencyList = new list<int>[numVertices];
    }

    void addEdge(int source, int destination) {
        adjacencyList[source].push_back(destination); // Add destination to source's list
    }

    // Additional methods for topological sorting would be implemented here
    void topologicalSortHelper(int vertex, vector<bool>& visitedNodes, stack<int>& resultStack) {
        visitedNodes[vertex] = true;
        for (int adjacentVertex : adjacencyList[vertex]) {
            if (!visitedNodes[adjacentVertex]) {
                topologicalSortHelper(adjacentVertex, visitedNodes, resultStack);
            }
        }
        resultStack.push(vertex);
    }

    void performTopologicalSort() {
        stack<int> resultStack;
        vector<bool> visitedNodes(numVertices, false);
        for (int index = 0; index < numVertices; index++) {
            if (!visitedNodes[index]) {
                topologicalSortHelper(index, visitedNodes, resultStack);
            }
        }
        while (!resultStack.empty()) {
            cout << resultStack.top() << " ";
            resultStack.pop();
        }
    }

    ~Digraph() {
        delete[] adjacencyList;
    }
};

int main() {
    Digraph g(6);
    g.addEdge(5, 2);
    g.addEdge(5, 0);
    g.addEdge(4, 0);
    g.addEdge(4, 1);
    g.addEdge(2, 3);
    g.addEdge(3, 1);
    // Topological sorting implementation would go here
    cout << "Topological Sort of the given graph:\n";
    g.performTopologicalSort();
    return 0;
}
// Time Complexity: O(V + E) for topological sort using DFS
// Space Complexity: O(V) for the stack and visited array

