}

void TestGuideRoute(Checkpoints const & checkpoints, double expectedDistanceMeters, double expectedTimeSeconds,
                    size_t expectedNumberOfPoints)
{
  TRouteResult const routeResult = integration::CalculateRoute(
      integration::GetVehicleComponents(VehicleType::Pedestrian), checkpoints, GetTestGuides());
