  integration::TestRouteLength(*routeResult.first, expectedDistanceMeters);
  integration::TestRouteTime(*routeResult.first, expectedTimeSeconds);
  integration::TestRoutePointsNumber(*routeResult.first, expectedNumberOfPoints);
}

