#include <iostream>
#include <iomanip>
#include <nlohmann/json.hpp>

using json = nlohmann::json;
using namespace nlohmann::literals;

// Helper function to display BJData bytes in human-readable form
void show_byte(uint8_t val)
{
    if (32 < val && val < 128)
    {
        std::cout << static_cast<char>(val);
    }
    else
    {
        std::cout << static_cast<int>(val);
    }
}

int main()
{
    // Build a JSON object with two boolean fields
    json obj = R"({"compact": true, "schema": false})"_json;

    // Convert the object to BJData format
    std::vector<std::uint8_t> bjdata_bytes = json::to_bjdata(obj);

    // Output each byte in diagnostic format
    for (auto& b : bjdata_bytes)
    {
        show_byte(b);
    }
    std::cout << std::endl;

    // Create a numeric array
    json numbers = {1, 2, 3, 4, 5, 6, 7, 8};

    // Serialize using default settings
    std::vector<std::uint8_t> arr_default = json::to_bjdata(numbers);

    // Serialize with size optimization enabled
    std::vector<std::uint8_t> arr_size_opt = json::to_bjdata(numbers, true);

    // Serialize with both size and type optimizations enabled
    std::vector<std::uint8_t> arr_full_opt = json::to_bjdata(numbers, true, true);

    // Print results of each serialization
    for (auto& b : arr_default)
    {
        show_byte(b);
    }
    std::cout << std::endl;

    for (auto& b : arr_size_opt)
    {
        show_byte(b);
    }
    std::cout << std::endl;

    for (auto& b : arr_full_opt)
    {
        show_byte(b);
    }
    std::cout << std::endl;

    return 0;
}

