FWidgetPath UGoogleVRWidgetInteractionComponent::FindHoveredWidgetPath(const FWidgetTraceResult& TraceResult) const
{
	if (TraceResult.HitWidgetComponent != nullptr)
	{
		// The cursor radius does not need to match the pointer's physical size.
		// The LastHitResult.ImpactPoint already reflects where the widget was struck,
		// considering the pointer's actual dimensions.
		// Still, when the impact occurs near the widget's edge, GetHitWidgetPath
		// may fail with a zero-radius setting.
		// To avoid this issue, we use a minimal positive radius.
		const float CursorRadius = 3.0f;
		return FWidgetPath(TraceResult.HitWidgetComponent->GetHitWidgetPath(TraceResult.LocalHitLocation, /*bIgnoreEnabledStatus*/ false, CursorRadius));
	}
	else
	{
		return FWidgetPath();
	}
}

