                 bool deprecated)
  : name(title),
    description(info),
    link(url),
    alias(nickname),
    hidden(invisible),
    obsolete(deprecated) {}

Section::~Section() = default;

std::string Section::displayName() const {
  return alias.empty() ? name : alias;
}

// Check if the section contains any visible options
bool Section::hasOptions() const {
  if (!hidden) {
    for (const auto& item : options) {
      if (!item.second.hasFlag(sdb::options::Flags::Uncommon)) {
        return true;
      }
    }
  }
  return false;
}

// Display help for a section
// Using "." as the search term shows all sections, even hidden ones
void Section::printHelp(const std::string& keyword, size_t labelWidth, size_t valueWidth,
                        bool useColors) const {
  if (keyword != "." && (hidden || !hasOptions())) {
    return;
  }

  std::cout << "Category '" << (useColors ? colors::kBright : "") << displayName()
            << (useColors ? colors::kReset : "") << "' (" << description << ")";

  if (!link.empty()) {
    std::cout << " [";
    if (useColors) {
      std::cout << colors::kLinkStart << link << colors::kLinkMiddle << link
                << colors::kLinkEnd;
    } else {
      std::cout << link;
    }
    std::cout << "]";
  }

  std::cout << std::endl;

  auto headerIt = headlines.begin();

  // Pass on the print request to individual options
  for (const auto& item : options) {
    if (headerIt != headlines.end() && item.first >= (*headerIt).first) {
      // Output a section headline
      std::cout << " # " << (*headerIt).second << std::endl;
      ++headerIt;
    }

    if (item.second.hasFlag(sdb::options::Flags::Deprecated)) {
      // Skip deprecated options
      continue;
    }

    // Print help for this option
    item.second.printHelp(keyword, labelWidth, valueWidth, useColors);
  }

  std::cout << std::endl;
}

// Compute the maximum width needed for options in this section
size_t Section::optionsWidth() const {
  size_t maxWidth = 0;
  if (!hidden) {
    for (const auto& item : options) {
      maxWidth = std::max(maxWidth, item.second.optionsWidth());
    }
  }
  return maxWidth;
}

