using namespace lemon;

// Flag to indicate shutdown request (signal-safe)
static std::atomic<bool> s_exit_requested(false);
static Server* s_active_server = nullptr;

// Handles termination signals: SIGINT, SIGTERM; ignores SIGHUP
void term_signal_handler(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
#ifndef _WIN32
        const char* msg = "Termination signal received, shutting down...\n";
        (void)write(STDOUT_FILENO, msg, 41);
#endif
        // Avoid calling non-async-signal-safe functions like server->stop()
        s_exit_requested = true;
        // Immediate exit — OS cleans up resources
        _exit(0);
#ifdef SIGHUP
    } else if (sig == SIGHUP) {
        // SIGHUP is ignored so the process persists after terminal disconnect
        return;
#endif
    }
}

int main(int argc, char** argv) {
    // Early check for duplicate instances (before argument parsing)
    if (SingleInstance::IsAnotherInstanceRunning("LemonadeRouter")) {
        std::cerr << "Fatal: A second instance of lemonade-router is already active.\n"
                  << "Only one instance may be running at any given time." << std::endl;
        return 1;
    }

    try {
        CLIParser cli;
        cli.parse(argc, argv);

        // Exit early if help/version requested or parsing failed
        if (!cli.continue_execution()) {
            return cli.exit_code();
        }

        // Extract configuration
        auto settings = cli.get_config();

        // Setup logging
        auto log_sink = std::make_shared<AixLog::SinkCout>(
            AixLog::Filter(AixLog::to_severity(settings.log_verbosity)),
            "%Y-%m-%d %H:%M:%S.#ms [#severity] (#tag_func) #message"
        );
        AixLog::Log::init({log_sink});

        // Log startup info
        LOG(INFO) << "Initializing Lemonade Server..." << std::endl;
        LOG(INFO) << "  Build version: " << LEMON_VERSION_STRING << std::endl;
        LOG(INFO) << "  Listening on port: " << settings.port_num << std::endl;
        LOG(INFO) << "  Bound to host: " << settings.bind_addr << std::endl;
        LOG(INFO) << "  Verbosity level: " << settings.log_verbosity << std::endl;
        if (!settings.models_path.empty()) {
            LOG(INFO) << "  Additional model directory: " << settings.models_path << std::endl;
        }

        // Construct and configure server
        Server srv(
            settings.port_num,
            settings.bind_addr,
            settings.log_verbosity,
            settings.recipe_opts,
            settings.max_models,
            settings.models_path,
            settings.disable_broadcast,
            settings.timeout_ms
        );

        // Install signal handlers
        s_active_server = &srv;
        std::signal(SIGINT, term_signal_handler);
        std::signal(SIGTERM, term_signal_handler);

        // Run server loop
        srv.start();

        // Cleanup
        s_active_server = nullptr;
        return 0;

    } catch (const std::exception& ex) {
        LOG(ERROR) << "Exception occurred: " << ex.what() << std::endl;
        return 1;
    }
}

