namespace s11n_example {

/// Client class for fetching stock data from a remote server
class client
{
public:
  /// Constructor initiates the asynchronous connection process.
  client(asio::io_context& context,
      const std::string& hostname, const std::string& port)
    : socket_connection_(context)
  {
    // Convert host name and service into a set of endpoints.
    asio::ip::tcp::resolver resolver(context);
    asio::ip::tcp::resolver::query resolution_query(hostname, port);
    asio::ip::tcp::resolver::iterator iterator = resolver.resolve(resolution_query);

    // Begin asynchronous connection to one of the resolved endpoints.
    asio::async_connect(socket_connection_.socket(), iterator,
        boost::bind(&client::on_connection_complete, this,
          asio::placeholders::error));
  }

  /// Callback invoked when the connect operation finishes.
  void on_connection_complete(const asio::error_code& error)
  {
    if (!error)
    {
      // Connection established successfully; now read the list of stocks.
      socket_connection_.async_read(stock_list_,
          boost::bind(&client::on_data_received, this,
            asio::placeholders::error));
    }
    else
    {
      // Connection failed — report the error and terminate.
      std::cerr << error.message() << std::endl;
    }
  }

  /// Callback invoked after reading stock data from the server.
  void on_data_received(const asio::error_code& error)
  {
    if (!error)
    {
      // Display each stock record in a formatted manner.
      for (std::size_t index = 0; index < stock_list_.size(); ++index)
      {
        std::cout << "Stock entry #" << index << "\n";
        std::cout << "  symbol: " << stock_list_[index].code << "\n";
        std::cout << "  company: " << stock_list_[index].name << "\n";
        std::cout << "  opening: " << stock_list_[index].open_price << "\n";
        std::cout << "  high: " << stock_list_[index].high_price << "\n";
        std::cout << "  low: " << stock_list_[index].low_price << "\n";
        std::cout << "  closing: " << stock_list_[index].last_price << "\n";
        std::cout << "  bid: " << stock_list_[index].buy_price << "\n";
        std::cout << "  bid_vol: " << stock_list_[index].buy_quantity << "\n";
        std::cout << "  ask: " << stock_list_[index].sell_price << "\n";
        std::cout << "  ask_vol: " << stock_list_[index].sell_quantity << "\n";
      }
    }
    else
    {
      std::cerr << "Read error: " << error.message() << std::endl;
    }
    // No further operations scheduled — io_context will exit once all work is done.
  }

private:
  /// Active connection object to the server.
  connection socket_connection_;
  /// Container for received stock records.
  std::vector<stock> stock_list_;
};

} // namespace s11n_example

int main(int argc, char* argv[])
{
  try
  {
    // Validate command-line arguments.
    if (argc != 3)
    {
      std::cerr << "Usage: client <host> <port>" << std::endl;
      return 1;
    }

    asio::io_context io_service;
    s11n_example::client app_client(io_service, argv[1], argv[2]);
    io_service.run();
  }
  catch (const std::exception& ex)
  {
    std::cerr << "Exception: " << ex.what() << std::endl;
    return 1;
  }

  return 0;
}

