#include <iostream>
#include <cstdlib>

// Function to send a query to the judge
long long ask(long long node, long long steps) {
    std::cout << "? " << node << " " << steps << std::endl;
    long long response;
    std::cin >> response;
    return response;
}

// Function to submit the final answer and validate it
void submit(long long cycle_length) {
    std::cout << "! " << cycle_length << std::endl;
    int validation;
    std::cin >> validation;
    if (validation == -1) {
        // Incorrect answer — terminate immediately
        exit(0);
    }
}

void process() {
    // Obtain a node on the cycle by making a large jump from node 1
    long long cycle_node = ask(1, 5000000000000000000LL);

    // Phase 1: Determine an interval [L, 2L] that contains the cycle length
    long long segment_length = 1;
    long long current_end = ask(cycle_node, 1);

    while (current_end != cycle_node) {
        current_end = ask(current_end, segment_length);
        segment_length *= 2;
    }

    // Now we know the cycle length s satisfies: segment_length/2 < s <= segment_length
    long long left = segment_length / 2 + 1;
    long long right = segment_length;
    long long s = segment_length;

    // Phase 2: Binary search for the minimal cycle length within the interval
    while (left <= right) {
        long long mid = left + (right - left) / 2;

        if (mid == 0) { // Safety check — should not occur for valid inputs
            left = 1;
            continue;
        }

        if (ask(cycle_node, mid) == cycle_node) {
            s = mid;              // Found a smaller possible cycle length
            right = mid - 1;
        } else {
            left = mid + 1;       // Cycle length must be larger
        }
    }

    submit(s);
}

int main() {
    // Optimize I/O performance
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int test_cases;
    std::cin >> test_cases;

    while (test_cases-- > 0) {
        process();
    }

    return 0;
}

