#include "ByteArrayOutputStream.h"

// Constructs a new byte array output stream with an initial buffer capacity of 64 bytes
ByteArrayOutputStream::ByteArrayOutputStream()
{
    bufferSize = 0;
    buffer = byteArray(64);
}

// Constructs a new byte array output stream with the specified initial capacity.
// Parameters:
// capacity - the initial buffer size in bytes
ByteArrayOutputStream::ByteArrayOutputStream(unsigned int capacity)
{
    bufferSize = 0;
    buffer = byteArray(capacity);
}

ByteArrayOutputStream::~ByteArrayOutputStream()
{
    if (buffer.data != nullptr)
        delete[] buffer.data;
}

// Writes a single byte to this stream. The byte to be written is specified by the least significant 8 bits of parameter b.
// Parameters:
// b - the byte to write
void ByteArrayOutputStream::write(unsigned int b)
{
    // Expand buffer if necessary before writing
    if (bufferSize + 1 >= buffer.length)
        buffer.resize(buffer.length * 2);

    buffer[bufferSize] = static_cast<byte>(b);
    bufferSize++;
}

// Writes all bytes from the given byte array to this output stream.
// This method behaves identically to calling write(b, 0, b.length).
void ByteArrayOutputStream::write(byteArray b)
{
    write(b, 0, b.length);
}

// Writes a subarray of the given byte array to this stream.
// Parameters:
// b - source data array
// offset - starting position in the source array
// len - number of bytes to copy
void ByteArrayOutputStream::write(byteArray b, unsigned int offset, unsigned int len)
{
    assert(b.length >= offset + len);

    // Ensure sufficient buffer space; grow buffer if needed
    if (bufferSize + len >= buffer.length)
        buffer.resize(std::max(bufferSize + len + 1, buffer.length * 2));

    XMemCpy(&buffer[bufferSize], &b[offset], len);
    bufferSize += len;
}

// No-op implementation: closing this stream has no effect.
void ByteArrayOutputStream::close()
{
}

// Returns a newly allocated copy of the current contents of the stream.
// The returned array's length equals the current stream size.
// Returns:
// a byte array containing the data written so far
byteArray ByteArrayOutputStream::toByteArray()
{
    byteArray result(bufferSize);
    std::memcpy(result.data, buffer.data, bufferSize);
    return result;
}

#include <vector>
#include <algorithm>

class Solution {
public:
    // Find the maximum average of any contiguous subarray of length k
    double calculateMaximumAverage(std::vector<int>& data, int windowSize) {
        int arrayLength = data.size();
        double currentSum = 0;

        // Calculate sum of first window
        for(int index = 0; index < windowSize; ++index) {
            currentSum += data[index];
        }

        double highestSum = currentSum;

        // Slide the window and update maximum sum
        for(int index = windowSize; index < arrayLength; ++index) {
            currentSum = currentSum - data[index - windowSize] + data[index];
            highestSum = std::max(currentSum, highestSum);
        }

        return highestSum / windowSize;
    }
};

