#include <iostream>
#include <vector>
#include <cstdlib>
using namespace std;

// Global array to store the reconstructed sequence (size supports max N = 2*10^5)
int resultArray[200005];

/**
 * Recursive function to reconstruct the sequence in range [start, end].
 * Implements a divide-and-conquer strategy akin to segment tree construction.
 * Queries the current interval to find the dominant value and its count.
 * If the interval is uniform (all elements identical), fills it directly.
 * Otherwise, splits into two sub-intervals and processes recursively.
 */
void reconstruct(int start, int end) {
    if (start > end) return;

    // Issue query for the current range: "? start end"
    cout << "? " << start << " " << end << endl;

    // Read response: "value frequency"
    long long dominantValueLong;
    int frequency;

    // Robust input validation
    if (!(cin >> dominantValueLong >> frequency)) {
        exit(0);
    }

    // Handle error condition (-1 indicates invalid query or termination)
    if (dominantValueLong == -1) {
        exit(0);
    }

    int dominantValue = static_cast<int>(dominantValueLong);

    // If frequency matches the interval length, all elements are equal to dominantValue
    if (frequency == (end - start + 1)) {
        for (int idx = start; idx <= end; ++idx) {
            resultArray[idx] = dominantValue;
        }
        return;
    }

    // Divide step: partition the interval into two halves
    int midpoint = (start + end) / 2;
    reconstruct(start, midpoint);
    reconstruct(midpoint + 1, end);
}

int main() {
    // Optimize I/O performance for interactive problems
    // Flushing is handled explicitly via 'endl' as required by interactive judges
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int sequenceLength;

    // Read input size N
    if (cin >> sequenceLength) {
        // Initiate reconstruction from full range [1, sequenceLength]
        reconstruct(1, sequenceLength);

        // Output final reconstructed sequence
        cout << "! ";
        for (int i = 1; i <= sequenceLength; ++i) {
            cout << resultArray[i];
            if (i != sequenceLength) {
                cout << " ";
            }
        }
        cout << endl;
    }

    return 0;
}

#include <iostream>
#include <vector>
#include <string>
#include <numeric>

void perform_interaction(int size, const std::vector<int>& trans0, const std::vector<int>& trans1) {
    std::cout << 1 << std::endl;
    std::cout << size << std::endl;

    for (int idx = 0; idx < size; ++idx) {
        std::cout << trans0[idx] << (idx == size - 1 ? "" : " ");
    }
    std::cout << std::endl;

    for (int idx = 0; idx < size; ++idx) {
        std::cout << trans1[idx] << (idx == size - 1 ? "" : " ");
    }
    std::cout << std::endl;
    std::cout.flush();
}

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int length;
    std::cin >> length;
    std::string result_string(length, '0');

    for (int position = 0; position < length; ++position) {
        // Determine the k-th character S_position by constructing an automaton
        // with position+2 states to distinguish between '0' and '1'
        int num_states = position + 2;

        std::vector<int> zero_trans(num_states);
        std::vector<int> one_trans(num_states);

        // Build transitions for the first 'position' characters: deterministic path
        for (int state = 0; state < position; ++state) {
            zero_trans[state] = state + 1;
            one_trans[state] = state + 1;
        }

        // Decision state at index 'position'
        zero_trans[position] = position;      // '0' keeps us in decision state
        one_trans[position] = position + 1;   // '1' moves to accepting state

        // Sink states: once reached, stay there
        if (position + 1 < num_states) {
            zero_trans[position + 1] = position + 1;
            one_trans[position + 1] = position + 1;
        }

        perform_interaction(num_states, zero_trans, one_trans);

        int response;
        std::cin >> response;
        if (response == position) {
            result_string[position] = '0';
        } else {
            result_string[position] = '1';
        }
    }

    std::cout << 0 << std::endl;
    std::cout << result_string << std::endl;
    std::cout.flush();

    return 0;
}

