using asio::ip::tcp;

std::string generate_current_time_string()
{
  using namespace std;
  time_t current_time = time(0);
  return ctime(&current_time);
}

class connection_handler
  : public boost::enable_shared_from_this<connection_handler>
{
public:
  typedef boost::shared_ptr<connection_handler> ptr_type;
  static ptr_type create(asio::io_context& context)
  {
    return ptr_type(new connection_handler(context));
  }

  tcp::socket& get_socket()
  {
    return socket_;
  }

  void initiate_transmission()
  {
    data_buffer_ = generate_current_time_string();
    asio::async_write(socket_, asio::buffer(data_buffer_),
        boost::bind(&connection_handler::on_transmit_complete, shared_from_this(),
          asio::placeholders::error,
          asio::placeholders::bytes_transferred));
  }

private:
  connection_handler(asio::io_context& context)
    : socket_(context)
  {
  }

  void on_transmit_complete(const asio::error_code& /*ec*/, size_t /*transferred*/)
  {
  }

  tcp::socket socket_;
  std::string data_buffer_;
};

class server_instance
{
public:
  server_instance(asio::io_context& context)
    : acceptor_(context, tcp::endpoint(tcp::v4(), 13))
  {
    begin_accepting();
  }

private:
  void begin_accepting()
  {
    connection_handler::ptr_type new_connection =
      connection_handler::create(acceptor_.get_executor().context());
    acceptor_.async_accept(new_connection->get_socket(),
        boost::bind(&server_instance::on_client_connected, this, new_connection,
          asio::placeholders::error));
  }

  void on_client_connected(connection_handler::ptr_type new_connection,
      const asio::error_code& error)
  {
    if (!error)
    {
      new_connection->initiate_transmission();
    }
    begin_accepting();
  }

  tcp::acceptor acceptor_;
};

int main()
{
  try
  {
    asio::io_context io_context;
    server_instance server(io_context);
    io_context.run();
  }
  catch (std::exception& exception)
  {
    std::cerr << exception.what() << std::endl;
  }
  return 0;
}

