#include "kml/serdes.hpp"
#include "kml/serdes_binary.hpp"
#include "indexer/classificator_loader.hpp"
#include "coding/file_reader.hpp"
#include "coding/file_writer.hpp"
#include <iostream>

int main(int argc, char ** argv)
{
  if (argc < 2)
  {
    std::cout << "Converts kmb file(s) to kml\n";
    std::cout << "Usage: " << argv[0] << " path_to_kmb_file [path_to_another_kmb_file...]\n";
    return 1;
  }

  classificator::Load();

  do
  {
    std::string inputPath = argv[argc - 1];
    kml::FileData outputData;

    try
    {
      FileReader inputFile(inputPath);
      kml::binary::DeserializerKml parser(outputData);
      parser.Deserialize(inputFile);
    }
    catch (kml::binary::DeserializerKml::DeserializeException const & error)
    {
      std::cerr << "Error reading kmb file " << inputPath << ": " << error.what() << std::endl;
      return 1;
    }

    try
    {
      // Modify extension from .kmb to .kml
      inputPath[inputPath.size() - 1] = 'l';
      kml::SerializerKml exporter(outputData);
      FileWriter outputFile(inputPath);
      exporter.Serialize(outputFile);
    }
    catch (kml::SerializerKml::SerializeException const & error)
    {
      std::cerr << "Error encoding to kml file " << inputPath << ": " << error.what() << std::endl;
      return 1;
    }
    catch (FileWriter::Exception const & error)
    {
      std::cerr << "Error writing to kml file " << inputPath << ": " << error.what() << std::endl;
      return 1;
    }

    std::cout << "Saved converted file as " << inputPath << std::endl;
  }
  while (--argc > 1);

  return 0;
}

