namespace Karm::Ui {

// MARK: Event Utilities -------------------------------------------------------
export template <typename T, typename... Params>
void dispatch(Node& node, Params&&... params) {
    auto evt = App::makeEvent<T>(std::forward<Params>(params)...);
    node.event(evt);
}

export template <typename T, typename... Params>
void propagate(Node& node, Params&&... params) {
    auto evt = App::makeEvent<T>(std::forward<Params>(params)...);
    node.bubble(evt);
}

export template <typename T, typename... Params>
auto createDispatcher(Params&&... params) {
    return [params...](Node& node) {
        dispatch<T>(node, params...);
    };
}

export template <typename T, typename... Params>
auto createPropagator(Params&&... params) {
    return [params...](Node& node) {
        propagate<T>(node, params...);
    };
}

export template <typename T, typename... Params>
Opt<Func<void(Node&)>> createDispatcherIf(bool condition, Params&&... params) {
    if (not condition)
        return NONE;
    return createDispatcher<T>(params...);
}

export template <typename T, typename... Params>
Opt<Func<void(Node&)>> createPropagatorIf(bool condition, Params&&... params) {
    if (not condition)
        return NONE;
    return createPropagator<T>(params...);
}

// MARK: Node Behavior Helpers -------------------------------------------------
export void requestRedraw(Node& node) {
    propagate<Node::PaintEvent>(node, node.bound());
}

export void requestRedraw(Node& node, Math::Recti area) {
    propagate<Node::PaintEvent>(node, area);
}

export void requestRelayout(Node& node) {
    propagate<Node::LayoutEvent>(node);
}

export void requestAnimation(Node& node) {
    propagate<Node::AnimateEvent>(node, .0);
}

export void triggerMouseExit(Node& node) {
    dispatch<App::MouseLeaveEvent>(node);
}

export void triggerMouseExit(Children& list) {
    for (auto& child : list) {
        triggerMouseExit(*child);
    }
}

