int main()
{
    // Initialize mplot::Visual with custom dimensions and title
    mplot::Visual scene(1280, 575, "Created using mplot::GraphVisual");

    // Instantiate GraphVisual at origin in world space
    auto graph = std::make_unique<mplot::GraphVisual<double>>(sm::vec<float>{0.0f, 0.0f, 0.0f});

    // Bind the model to the visual scene (required setup)
    scene.bindmodel(graph);

    // Prepare x-axis data: 11 points from 0 to 10 inclusive
    sm::vvec<double> x_vals;
    x_vals.linspace(0, 10, 11);

    // Define y-values manually
    sm::vvec<double> y_vals = {5, 8, 2, 9, 1, 2, 4, 5, 8, 3, 1};

    // Configure primary dataset style (line plot in crimson)
    mplot::DatasetStyle main_style(mplot::stylepolicy::lines);
    main_style.linecolour = mplot::colour::crimson;

    // Enforce fixed y-axis range for clarity
    graph->setlimits_y(0, 10);

    // Assign data to the graph
    graph->setdata(x_vals, y_vals, main_style);

    // Secondary style for horizontal reference line at y=7
    mplot::DatasetStyle ref_line_style(mplot::stylepolicy::lines);
    ref_line_style.linecolour = mplot::colour::grey68;
    ref_line_style.linewidth = main_style.linewidth * 0.6f;

#ifdef GRAPH_LINES_SIMPLE
    // Add crossing lines without annotation
    graph->add_y_crossing_lines(x_vals, y_vals, 7, main_style);
#else
    // Compute exact crossing points and annotate them
    sm::vvec<double> cross_x = graph->add_y_crossing_lines(x_vals, y_vals, 7, main_style, ref_line_style);

    size_t count = cross_x.size();
    std::stringstream label_stream;

    if (count > 0) {
        for (size_t idx = 0; idx < count; ++idx) {
            label_stream << std::format(
                "{}{}{:.2f}",
                ((idx == 0 || idx == count - 1) ? "" : ", "),
                (idx == count - 1 ? " and " : ""),
                cross_x[idx]
            );
        }
    } else {
        label_stream << "[no intersections]";
    }

    // Insert descriptive label near bottom-left corner
    graph->addLabel(
        std::format("y=7 crossed at x = {}", label_stream.str()),
        {0.05f, 0.05f, 0.0f},
        mplot::TextFeatures(0.03f)
    );
#endif

    // Finalize internal OpenGL model generation
    graph->finalize();

    // Transfer ownership of the graph to the scene
    scene.addVisualModel(std::move(graph));

    // Launch interactive rendering loop
    scene.keepOpen();

    // Memory cleanup handled automatically via RAII
    return 0;
}

#include <iostream>
#include <vector>
#include <string>
#include <algorithm>
#include <cmath>

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    unsigned int n_input;
    std::cin >> n_input;

    if (n_input == 1) {
        std::cout << 1 << "\n";
        std::cout << "HALT PUSH 1 GOTO 1\n";
        return 0;
    }

    unsigned int half_val = (n_input - 1) / 2;
    std::vector<int> binary_digits;

    // Handle the case where half_val is zero (corresponds to n_input=1, already handled above)
    unsigned int temp_val = half_val;

    if (temp_val == 0) {
        // For n_input=3, half_val=1; for n_input=1, half_val=0
        // Ensure binary_digits isn't empty when half_val > 0
        if (half_val > 0) {
            while (temp_val > 0) {
                binary_digits.push_back(temp_val % 2);
                temp_val /= 2;
            }
        }
    } else {
        while (temp_val > 0) {
            binary_digits.push_back(temp_val % 2);
            temp_val /= 2;
        }
    }

    // Fallback for edge cases with large numbers
    if (binary_digits.empty() && half_val > 0) {
        int digit_count = static_cast<int>(std::floor(std::log2(half_val))) + 1;
        temp_val = half_val;
        for (int idx = 0; idx < digit_count; ++idx) {
            binary_digits.push_back(temp_val % 2);
            temp_val /= 2;
        }
    }

    // Reverse to get MSB-first representation
    std::reverse(binary_digits.begin(), binary_digits.end());

    // Ensure at least one bit exists when half_val > 0
    if (half_val > 0 && binary_digits.empty()) {
        binary_digits.push_back(1);
    }

    int bit_count = static_cast<int>(binary_digits.size());
    if (half_val == 0) bit_count = 0;

    int total_instrs = bit_count + 3;
    std::cout << total_instrs << "\n";

    // First instruction: entry point
    std::cout << "POP 1 GOTO 2 PUSH 1 GOTO 2\n";

    // Instructions for processing each bit
    for (int pos = 0; pos < bit_count; ++pos) {
        int instr_num = pos + 2;
        if (binary_digits[pos] == 1) {
            std::cout << "HALT PUSH 1 GOTO " << (instr_num + 1) << "\n";
        } else {
            std::cout << "POP 1 GOTO " << (bit_count + 2) << " PUSH 2 GOTO " << (instr_num + 1) << "\n";
        }
    }

    // Return mechanism instruction
    std::cout << "POP 1 GOTO 2 PUSH 2 GOTO " << (bit_count + 2) << "\n";

    // Final halt instruction
    std::cout << "HALT PUSH 99 GOTO " << (bit_count + 2) << "\n";

    return 0;
}

#include "server.hpp"
#include <boost/bind.hpp>
#include <signal.h>

namespace http {
namespace server {

// Constructor for the HTTP server, initializing resources and setting up signal handling
server::server(const std::string& host, const std::string& port_str,
    const std::string& document_root)
  : service_context_(),
    termination_signals_(service_context_),
    listener_(service_context_),
    active_connections_(),
    incoming_connection_(),
    request_processor_(document_root)
{
  // Set up handlers for termination signals (e.g., Ctrl+C, kill command)
  // Asio allows multiple registrations for the same signal safely
  termination_signals_.add(SIGINT);
  termination_signals_.add(SIGTERM);
#if defined(SIGQUIT)
  termination_signals_.add(SIGQUIT);
#endif // defined(SIGQUIT)

  // Start asynchronous wait for stop signals
  termination_signals_.async_wait(boost::bind(&server::on_shutdown, this));

  // Prepare network endpoint and configure acceptor
  asio::ip::tcp::resolver resolver(service_context_);
  asio::ip::tcp::endpoint bound_endpoint =
    *resolver.resolve(host, port_str).begin();

  listener_.open(bound_endpoint.protocol());
  listener_.set_option(asio::ip::tcp::acceptor::reuse_address(true));
  listener_.bind(bound_endpoint);
  listener_.listen();

  initiate_accept();
}

// Main execution loop: blocks until all async operations complete
void server::execute()
{
  // The context runs until explicitly stopped (e.g., via handle_stop)
  service_context_.run();
}

// Begin accepting new connections asynchronously
void server::initiate_accept()
{
  incoming_connection_.reset(new connection(service_context_,
        active_connections_, request_processor_));

  listener_.async_accept(incoming_connection_->socket(),
      boost::bind(&server::on_connection_arrival, this,
        asio::placeholders::error));
}

// Handle completion of an accept operation
void server::on_connection_arrival(const asio::error_code& err)
{
  // Ignore if acceptor was closed (e.g., during shutdown)
  if (!listener_.is_open())
  {
    return;
  }

  if (!err)
  {
    active_connections_.start(incoming_connection_);
  }

  // Continue accepting more connections
  initiate_accept();
}

// Signal handler to gracefully shut down the server
void server::on_shutdown()
{
  // Cancel pending operations to allow io_context::run() to exit
  listener_.close();
  active_connections_.stop_all();
}

} // namespace server
} // namespace http

