#include <iostream>
#include <vector>
#include <stack>
#include <unordered_map>
using namespace std;

// LeetCode 496: Next Greater Element I - Modified version
class Solution {
public:
    vector<int> nextGreaterElement(vector<int>& searchNums, vector<int>& baseNums) {
        vector<int> result;
        stack<int> stk;  
        unordered_map<int, int> greaterMap;  // maps each element to its next greater value

        // Traverse baseNums from right to left
        for (int idx = baseNums.size() - 1; idx >= 0; idx--) {
            // Maintain a decreasing stack
            while (!stk.empty() && stk.top() <= baseNums[idx]) {
                stk.pop();
            }

            // Determine the next greater element
            greaterMap[baseNums[idx]] = stk.empty() ? -1 : stk.top();

            // Add current element to the stack
            stk.push(baseNums[idx]);
        }

        // Construct the answer for each query in searchNums
        for (int val : searchNums) {
            result.push_back(greaterMap[val]);
        }

        return result;
    }
};

#include <stdint.h>
#include "libcgo.h"
#ifndef __has_feature
#define __has_feature(x) 0
#endif
#if __has_feature(memory_sanitizer)
#include <sanitizer/msan_interface.h>
#endif

// Invoke the user-provided traceback handler followed by sigtramp.
// This approach ensures that the user's traceback function executes within
// a C context that has correct unwind information.
void
x_cgo_callers(uintptr_t signal, void *siginfo, void *ctx, void (*userTraceback)(struct cgoTracebackArg*), uintptr_t* buffer, void (*signalHandler)(uintptr_t, void*, void*)) {
    struct cgoTracebackArg args;
    args.Context = 0;
    args.SigContext = (uintptr_t)(ctx);
    args.Buf = buffer;
    args.Max = 32; // must match len(runtime.cgoCallers)

#if __has_feature(memory_sanitizer)
    // This function is invoked directly from the signal handler.
    // Input parameters are passed via registers, so memory sanitizer's
    // initialization tracking for 'buffer' depends on whether the 
    // relevant register state is considered initialized.
    // In rare scenarios this may lead to false positives.
    // To prevent such issues, explicitly mark the memory region as initialized.
    // Refer to issue #47543 for additional context.
    __msan_unpoison(&args, sizeof(args));
#endif

    _cgo_tsan_acquire();
    (*userTraceback)(&args);
    _cgo_tsan_release();
    signalHandler(signal, siginfo, ctx);
}

