#include "comms/torchcomms/xccl/TorchWorkXCCL.hpp"

namespace torch::comms {

// Perform cleanup of completed or failed work items in the queue
TorchWorkXCCL::WorkStatus TorchWorkXCCLQueue::garbageCollectLocked() {
  TorchWorkXCCL::WorkStatus prev_status = TorchWorkXCCL::WorkStatus::COMPLETED;

  // Iterate over all stream queues and process their work items
  for (auto iter = stream_work_queues_.begin(); iter != stream_work_queues_.end(); ) {
    auto& task_list = iter->second;

    // Process tasks in FIFO order until an incomplete one is found
    while (!task_list.empty()) {
      auto current_task = task_list.front();
      TorchWorkXCCL::WorkStatus check_result = current_task->checkStatus();
      prev_status = check_result;

      if (TorchWorkXCCL::WorkStatus::COMPLETED == check_result) {
        task_list.pop();
      } else if (
          TorchWorkXCCL::WorkStatus::TIMEDOUT == check_result ||
          TorchWorkXCCL::WorkStatus::ERROR == check_result) {
        return check_result;
      } else {
        break; // Stop processing this stream's queue
      }
    }

    // Remove empty stream queues from the map
    if (task_list.empty()) {
      iter = stream_work_queues_.erase(iter);
    } else {
      ++iter;
    }
  }

  return prev_status;
}

// Thread-safe wrapper using mutex lock
TorchWorkXCCL::WorkStatus TorchWorkXCCLQueue::garbageCollect() {
  std::lock_guard<std::mutex> guard(work_queues_mutex_);
  return garbageCollectLocked();
}

// Finalize all pending work — typically called during shutdown
TorchWorkXCCL::WorkStatus TorchWorkXCCLQueue::finalize() {
  // Defensive locking even though watchdog thread should be joined already
  std::lock_guard<std::mutex> guard(work_queues_mutex_);

  TorchWorkXCCL::WorkStatus result = TorchWorkXCCL::WorkStatus::COMPLETED;

  // Keep cleaning until queue empties or terminal state reached
  while (!stream_work_queues_.empty()) {
    result = garbageCollectLocked();
    if (result == TorchWorkXCCL::WorkStatus::ERROR ||
        result == TorchWorkXCCL::WorkStatus::TIMEDOUT ||
        result == TorchWorkXCCL::WorkStatus::COMPLETED) {
      break;
    }
  }

  // Ensure no dangling references remain
  stream_work_queues_.clear();
  return result;
}

// Add new work item to the appropriate stream queue
void TorchWorkXCCLQueue::enqueueWork(
    c10::intrusive_ptr<TorchWorkXCCL> task,
    xpuStream_t stream_id) {
  std::lock_guard<std::mutex> guard(work_queues_mutex_);
  stream_work_queues_[stream_id].push(task);
}

} // namespace torch::comms

