class GamepadExample
{
public:
    GamepadExample() {}

    // Initialize DDS communication layer
    void InitializeDdsCommunication(const std::string &networkInterface = "")
    {
        ChannelFactory::Instance()->Init(0, networkInterface);
        joystick_sub.reset(new ChannelSubscriber<unitree_go::msg::dds_::WirelessController_>(TOPIC_JOYSTICK_DATA));
        joystick_sub->InitChannel(std::bind(&GamepadExample::OnJoystickDataReceived, this, std::placeholders::_1), 1);
    }

    // Configure dead zone for gamepad input smoothing
    void ConfigureDeadZone(float threshold)
    {
        controller.dead_zone = threshold;
    }

    // Configure smoothing factor for analog inputs
    void ConfigureSmoothingFactor(float factor)
    {
        controller.smooth = factor;
    }

    // Callback invoked when new joystick data arrives
    void OnJoystickDataReceived(const void *data)
    {
        std::lock_guard<std::mutex> guard(data_mutex);
        last_joystick_data = *(unitree_go::msg::dds_::WirelessController_ *)data;
    }

    // Main control loop executed periodically
    void RunControlStep()
    {
        {
            std::lock_guard<std::mutex> guard(data_mutex);
            controller.Update(last_joystick_data);
        }

        // Handle button press events
        if (controller.A.on_press)
        {
            button_press_counter += 1;
        }

        // Output current gamepad state
        std::cout << "Left Stick X: " << controller.lx << std::endl
                  << "Button A - Pressed: " << controller.A.pressed
                  << "; Just Pressed: " << controller.A.on_press
                  << "; Just Released: " << controller.A.on_release
                  << std::endl << "Total Presses: " << button_press_counter
                  << std::endl << "---------------------------" << std::endl;
    }

    // Launch the control thread
    void Activate()
    {
        worker_thread = CreateRecurrentThreadEx("gamepad_ctrl", UT_CPU_ID_NONE, 40000, &GamepadExample::RunControlStep, this);
    }

protected:
    ChannelSubscriberPtr<unitree_go::msg::dds_::WirelessController_> joystick_sub;
    unitree_go::msg::dds_::WirelessController_ last_joystick_data;
    Gamepad controller;
    ThreadPtr worker_thread;
    std::mutex data_mutex;
    int button_press_counter = 0;
};

int main()
{
    // Instantiate the example handler
    GamepadExample handler;

    // Apply configuration parameters
    handler.ConfigureSmoothingFactor(0.2f);
    handler.ConfigureDeadZone(0.5f);

    // Start system components
    handler.InitializeDdsCommunication();
    handler.Activate();

    // Keep application alive
    while (true)
    {
        usleep(20000);
    }

    return 0;
}

#include <iostream>
#include <vector>
#include <numeric>
#include <algorithm>
#include <list>

// Function to execute a query and get the winner
int perform_query(const std::vector<int>& items) {
    std::cout << "?";
    for (int item : items) {
        std::cout << " " << item;
    }
    std::cout << std::endl;

    int result;
    std::cin >> result;
    if (result == -1) {
        exit(0); // Terminate on error signal from interactor
    }
    return result;
}

void process() {
    int size;
    std::cin >> size;

    // Maintain a list of available items for processing
    std::list<int> available_items;
    for (int i = 1; i <= size * size; ++i) {
        available_items.push_back(i);
    }

    std::vector<int> ordered_items;
    int count_to_determine = size * size - size + 1;

    // Determine the fastest items sequentially
    for (int index = 0; index < count_to_determine; ++index) {
        // Set up contenders for this round
        std::list<int> contenders = available_items;

        while (contenders.size() > 1) {
            // Create a race group with up to 'size' items from the front
            std::vector<int> race_participants;
            auto iter = contenders.begin();
            for(int j = 0; j < size && iter != contenders.end(); ++j) {
                race_participants.push_back(*iter);
                iter++;
            }

            int champion = perform_query(race_participants);

            // Eliminate all losers from contenders
            auto iter_contender = contenders.begin();
            while(iter_contender != contenders.end()){
                bool eliminated = false;

                // Check if current contender lost the race
                if (*iter_contender != champion) {
                    for(int participant : race_participants){
                        if(*iter_contender == participant){
                            eliminated = true;
                            break;
                        }
                    }
                }

                if(eliminated){
                    iter_contender = contenders.erase(iter_contender);
                } else {
                    ++iter_contender;
                }
            }
        }

        // The last remaining contender is the next fastest item
        int next_item = contenders.front();
        ordered_items.push_back(next_item);
        available_items.remove(next_item);
    }

    // Output the final sorted sequence
    std::cout << "!";
    for (size_t pos = 0; pos < ordered_items.size(); ++pos) {
        std::cout << " " << ordered_items[pos];
    }
    std::cout << std::endl;
}

int main() {
    // Optimize I/O operations
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int test_cases;
    std::cin >> test_cases;
    while (test_cases--) {
        process();
    }
    return 0;
}

