// Recursive function to solve the Tower of Hanoi puzzle
// n: number of disks to transfer
// source: starting peg
// target: destination peg
// helper: auxiliary peg
void hanoi(int n, int source, int target, int helper) {
    if (n == 0) {
        return;
    }

    // Move n-1 disks from source to helper using target as temporary storage
    hanoi(n - 1, source, helper, target);

    // Move the bottom disk from source to target
    std::cout << source << " " << target << "\n";

    // Move n-1 disks from helper to target using source as temporary storage
    hanoi(n - 1, helper, target, source);
}

int main() {
    // Optimize input/output operations
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int diskCount;
    std::cin >> diskCount;

    // Calculate total moves needed: 2^diskCount - 1
    // Using 1LL ensures 64-bit arithmetic to avoid overflow
    long long totalMoves = (1LL << diskCount) - 1;
    std::cout << totalMoves << "\n";

    // Only output individual moves if there are disks to move
    if (diskCount > 0) {
        hanoi(diskCount, 1, 3, 2);
    }

    return 0;
}

