#include <vector>
using namespace std;

class Solution {
public:
    // Calculate the total count of elements that have the maximum frequency
    int maxFrequencyElements(vector<int>& nums) {
        int frequency[101] = {0};
        int maxFrequency = 0;
        int countOfMax = 0;

        for (int num : nums) {
            frequency[num]++;

            if (frequency[num] == maxFrequency) {
                countOfMax++;
            }

            if (frequency[num] > maxFrequency) {
                maxFrequency = frequency[num];
                countOfMax = 1;
            }
        }

        return countOfMax * maxFrequency;
    }
};

#include <iostream>
#include <string>
#include "asio.hpp"
#include "boost/bind.hpp"

const short udp_multicast_port = 30001;

class multicast_listener
{
public:
  multicast_listener(asio::io_context& context,
      const asio::ip::address& interface_address,
      const asio::ip::address& group_address)
    : udp_socket_(context)
  {
    // Configure the socket to allow multiple listeners on the same port
    asio::ip::udp::endpoint bind_endpoint(interface_address, udp_multicast_port);
    udp_socket_.open(bind_endpoint.protocol());
    udp_socket_.set_option(asio::ip::udp::socket::reuse_address(true));
    udp_socket_.bind(bind_endpoint);

    // Subscribe to the multicast group
    udp_socket_.set_option(
        asio::ip::multicast::join_group(group_address));

    // Start asynchronous receive operation
    udp_socket_.async_receive_from(
        asio::buffer(buffer_, buffer_size), remote_endpoint_,
        boost::bind(&multicast_listener::on_data_received, this,
          asio::placeholders::error,
          asio::placeholders::bytes_transferred));
  }

  void on_data_received(const asio::error_code& ec, size_t length)
  {
    if (!ec)
    {
      std::cout.write(buffer_, length);
      std::cout << std::endl;

      // Continue listening for more messages
      udp_socket_.async_receive_from(
          asio::buffer(buffer_, buffer_size), remote_endpoint_,
          boost::bind(&multicast_listener::on_data_received, this,
            asio::placeholders::error,
            asio::placeholders::bytes_transferred));
    }
  }

private:
  asio::ip::udp::socket udp_socket_;
  asio::ip::udp::endpoint remote_endpoint_;
  enum { buffer_size = 1024 };
  char buffer_[buffer_size];
};

int main(int argc, char* argv[])
{
  try
  {
    if (argc != 3)
    {
      std::cerr << "Usage: receiver <listen_address> <multicast_address>\n";
      std::cerr << "  For IPv4, try:\n";
      std::cerr << "    receiver 0.0.0.0 239.255.0.1\n";
      std::cerr << "  For IPv6, try:\n";
      std::cerr << "    receiver 0::0 ff31::8000:1234\n";
      return 1;
    }

    asio::io_context io_service;
    multicast_listener listener(io_service,
        asio::ip::make_address(argv[1]),
        asio::ip::make_address(argv[2]));

    io_service.run();
  }
  catch (std::exception& exception)
  {
    std::cerr << "Error: " << exception.what() << "\n";
  }

  return 0;
}

#include <engLib/eng.h>
namespace engine::store::filter::parse::Tika {
namespace {
//-----------------------------------------------------------------
/// @details
///		Flag to indicate we have already initialized the tika
///		side of the engine
//-----------------------------------------------------------------
bool s_isInitialized = false;
}  // namespace
//-----------------------------------------------------------------
/// @details
///		This function will initialize the global java environment
///		for use with Tika
//-----------------------------------------------------------------
Error TikaGlobal::begin(IServiceConfig &config) noexcept {
    // Define the guarded function
    const auto _initialize = localfcn()->Error {
        // If we have already initialized, then done
        if (s_isInitialized) return {};
        // Initialize the java engine
        if (auto result = java::init()) return result;
        // Setup a reference to our jni interface
        GET_JAVA_JNI(jvmInterface);
        // Get the bound methods
        auto apiMethods = TikaApi(jvmInterface);
        // Get the path to tika-config.xml
        auto basePath = java::rootDir();
        // Register native callbacks and initialize the API
        LOGT("Initializing indexing engine...");
        // Register the callbacks with the jvm
        registerTikaCallbacks();
        // Set the config path
        apiMethods.m_jni.setStaticField(apiMethods.m_class, apiMethods.m_rootPathFieldId,
                                        _ts(basePath.plat(false)));
        // And init it
        apiMethods.m_jni.invokeStaticMethod(apiMethods.m_class,
                                            apiMethods.m_initMethodId);
        // De-initialize Tika API on JVM destruction
        java::addDeinitCallback([](java::Jni &jniRef) noexcept(false) {
            // If this is not called, the JVM will hang on deinit due to
            // scheduled tasks on the Java side
            LOG(Parse, "De-initializing parsing engine");
            // Get the bound methods
            auto apiMethods = TikaApi(jniRef);
            // And deinit it
            jniRef.invokeStaticMethod(apiMethods.m_class, apiMethods.m_deinitMethodId);
        });
        // Say we have initialized
        s_isInitialized = true;
        return {};
    };
    // Call it
    if (auto ccode = _callChk(_initialize)) {
        // Say we did it
        LOGT("Failed to initialize the parsing engine");
        return ccode;
    } else {
        // Say we did it
        LOGT("Successfully initialized the parsing engine");
        return {};
    }
}
//-----------------------------------------------------------------
/// @details
///		This function will deinit and unload the java engine
///	@returns
///		Error
//-----------------------------------------------------------------
Error TikaGlobal::end() noexcept {
    // We wil let the main deinit process handle scrapping the jvm
    return {};
}
}  // namespace engine::store::filter::parse::Tika

