  intrusive_ptr_class<BackendWrapper::Options, c10d::Backend::Options>(
      module, "_BackendWrapperOptions");
}

#include <Application.h>
#include <Entry.h>
#include <Directory.h>
#include <FindDirectory.h>
#include <Path.h>
#include <Volume.h>
#include <Query.h>
#include <stdio.h>
#include <string.h>

class CommentFileSearcher : public BApplication
{
public:
    CommentFileSearcher()
        : BApplication("application/x-vnd.kitlab-commentfilesearcher")
    {
        ExecuteSearch();
        PostMessage(B_QUIT_REQUESTED);
    }

private:
    void ExecuteSearch()
    {
        // --- Locate the user's home directory ---
        BPath userHomePath;
        if (find_directory(B_USER_DIRECTORY, &userHomePath) != B_OK) {
            printf("Error: Could not locate home directory.\n");
            return;
        }

        BDirectory homeDir(userHomePath.Path());
        BVolume volume;
        if (homeDir.GetVolume(&volume) != B_OK) {
            printf("Error: Unable to retrieve volume for home directory.\n");
            return;
        }

        // --- Output search context ---
        printf("Scanning location: %s\n", userHomePath.Path());
        printf("Target: Files containing a 'Comment' attribute.\n\n");

        const char* targetMimeType = "text/plain";

        // --- Build and configure the query ---
        BQuery searchQuery;
        searchQuery.SetVolume(&volume);

        // Condition 1: MIME type must be text/plain
        searchQuery.PushAttr("BEOS:TYPE");
        searchQuery.PushString(targetMimeType);
        searchQuery.PushOp(B_EQ);

        // Condition 2: Must have a non-empty 'Comment' attribute
        searchQuery.PushAttr("Comment");
        searchQuery.PushString("*");
        searchQuery.PushOp(B_EQ);

        // Combine both conditions with AND logic
        searchQuery.PushOp(B_AND);

        // Execute the query
        if (searchQuery.Fetch() != B_OK) {
            printf("Error: Query execution failed.\n");
            return;
        }

        // --- Process results ---
        entry_ref reference;
        int foundCount = 0;
        while (searchQuery.GetNextRef(&reference) == B_OK) {
            BEntry item(&reference);
            BPath fullPath(&item);

            // Ensure the file is within the user's home directory
            if (strncmp(fullPath.Path(), userHomePath.Path(), strlen(userHomePath.Path())) == 0) {
                printf("Match: %s\n", fullPath.Path());
                foundCount++;
            }
        }

        // --- Report no matches found ---
        if (foundCount == 0)
