// Helper to compute next power of two
inline size_t next_power_of_two(size_t n) {
    if (n == 0) return 1;
    size_t p = 1;
    while (p < n) p <<= 1;
    return p;
}

// Black-Scholes Monte Carlo simulation driver
void blackScholesMonteCarlo(const std::vector<double>& input_data, int num_contracts, int params_per_contract) {
    // Create SYCL queue targeting default device
    sycl::queue q{sycl::default_selector_v};

    // Allocate unified shared memory (USM) for parameters
    double* param_array = sycl::malloc_shared<double>(num_contracts * params_per_contract, q);

    // Copy host data to device
    q.memcpy(param_array, input_data.data(), 
             static_cast<size_t>(num_contracts) * params_per_contract * sizeof(double))
     .wait();

    // Validate USM allocation type
    auto mem_type = sycl::get_pointer_type(param_array, q.get_context());
    if (mem_type != sycl::usm::alloc::shared) {
        throw std::runtime_error("Parameter buffer must reside in USM shared memory.");
    }

    // Compute next power-of-two padding for alignment (used internally)
    const size_t padded_stride = next_power_of_two(static_cast<size_t>(params_per_contract));

    // Launch single task with explicit indexing (equivalent to parallel_for over 1D range)
    auto kernel_event = q.submit([&](sycl::handler& h) {
        h.single_task([=]() {
            for (int contract_idx = 0; contract_idx < num_contracts; ++contract_idx) {
                const size_t base_offset = static_cast<size_t>(contract_idx) * params_per_contract;
                const size_t padded_offset = static_cast<size_t>(contract_idx) * padded_stride;

                // Initialize RNG engine per contract (5 samples per contract as per original comment)
                constexpr int samples_per_contract = 5;
                oneapi::mkl::rng::device::philox4x32x10<samples_per_contract> rng_engine{contract_idx};

                // Simulate Black-Scholes computation (placeholder logic)
                // In real implementation, this would use SABR, Heston, etc.
                // Here we just demonstrate structure — actual pricing omitted
                /*
                double spot = param_array[base_offset + 0];
                double strike = param_array[base_offset + 1];
                double rate = param_array[base_offset + 2];
                double vol  = param_array[base_offset + 3];
                double tau  = param_array[base_offset + 4];

                // Generate random numbers via RNG engine
                float4 uniforms = rng_engine.generate_uniform<float4>();
                // ... proceed with Monte Carlo or analytical BS formula ...
                */
            }
        });
    });

    // Ensure kernel completion before freeing resources
    kernel_event.wait();

    // Release USM memory
    sycl::free(param_array, q);
}

