void nonlinear_step(std::shared_ptr<const DefaultExecutor> exec, int n,
                    double nonlinear_scale, double potential_scale,
                    double time_scale,
                    const gko::matrix::Dense<double>* potential,
                    gko::matrix::Dense<std::complex<double>>* ampl)
{
    using device_complex = device_type<std::complex<double>>;

    // Compute combined scaling factor once per kernel launch
    const double combined_scale = nonlinear_scale * potential_scale * time_scale;

    run_kernel(
        exec,
        GKO_KERNEL(auto i, auto j, auto n, auto combined_scale, auto potential, auto ampl) {
            // Calculate the nonlinear step update for amplitude
