// Remove a specific card from the hand if it exists
Card Hand::removeCard(const Card& targetCard)
{
    auto iter = cards.begin();
    while (iter != cards.end())
    {
        if (*iter == targetCard)
        {
            Card result = *iter;
            cards.erase(iter);
            return result;
        }
        ++iter;
    }
    // If no matching card is found, return an empty/default Card instance
    return Card{};
}

// Collect IDs of cards satisfying a given condition
std::list<CardId> Hand::getIds(std::function<bool(const Card&)> condition)
{
    std::list<CardId> selectedIds;
    for (const Card& currentCard : cards)
    {
        if (condition(currentCard))
        {
            selectedIds.push_back(currentCard.id);
        }
    }
    return selectedIds;
}

