class MemoryBuffer {
private:
    char* bufferAddress;
    size_t bufferSize;
public:
    MemoryBuffer(char* addr, size_t sz) : bufferAddress(addr), bufferSize(sz) {}

    void copyData(void* src, size_t pos, size_t len) {
        // Check if the copy operation would exceed buffer boundaries
        if (pos + len > bufferSize) {
            std::cerr << "Error: copy operation exceeds buffer capacity" << std::endl;
            return;
        }

        char* sourcePtr = static_cast<char*>(src);
        // Perform the memory copy operation
        std::memcpy(bufferAddress + pos, sourcePtr, len);
    }
};

