#include <cmath>

struct Point3D {
  double x, y, z;
};

// Compute the volume of a tetrahedron using scalar triple product
double computeTetrahedronVolume(const Point3D& p1, const Point3D& p2, const Point3D& p3, const Point3D& p4) {
  // Vectors from p1 to other points
  double ax = p2.x - p1.x;
  double ay = p2.y - p1.y;
  double az = p2.z - p1.z;

  double bx = p3.x - p1.x;
  double by = p3.y - p1.y;
  double bz = p3.z - p1.z;

  double cx = p4.x - p1.x;
  double cy = p4.y - p1.y;
  double cz = p4.z - p1.z;

  // Scalar triple product: a · (b × c)
  double crossX = by * cz - bz * cy;
  double crossY = bz * cx - bx * cz;
  double crossZ = bx * cy - by * cx;

  double dotProduct = ax * crossX + ay * crossY + az * crossZ;

  return std::abs(dotProduct / 6.0);
}

