using namespace std;

// Function to count elements less than each query value
vector<int> countElementsLessThanX(int a[], int n, int queries[], int q) {
    vector<int> result;

    // Create a copy of the array to avoid modifying original
    vector<int> sortedArray(a, a + n);
    sort(sortedArray.begin(), sortedArray.end());

    // Process each query
    for (int idx = 0; idx < q; idx++) {
        int target = queries[idx];
        int left = 0;
        int right = sortedArray.size();

        // Manual binary search to find insertion point
        while (left < right) {
            int mid = left + (right - left) / 2;
            if (sortedArray[mid] >= target) {
                right = mid;
            } else {
                left = mid + 1;
            }
        }

        // 'left' now represents the count of elements less than target
        result.push_back(left);
    }

