    if (argc == 1) {
        std::cout << "Usage: program_name [options]" << std::endl;
    }
    else if (argc == 2 && (std::string(argv[1]) == "-h" || std::string(argv[1]) == "--help")) {
        std::cout << "Help: Display usage instructions for this application." << std::endl;
    }
    else if (argc == 3 && (std::string(argv[1]) == "-f" || std::string(argv[1]) == "--file")) {
        std::ifstream input_file(argv[2]);
        if (input_file.is_open()) {
            std::string current_line;
            while (std::getline(input_file, current_line)) {
                std::cout << current_line << std::endl;
            }
            input_file.close();
        } else {
            std::cerr << "Error: Unable to open the specified file." << std::endl;
        }
    }
    else if (argc == 4 && (std::string(argv[1]) == "-s" || std::string(argv[1]) == "--size")) {
        int window_width = std::stoi(argv[2]);
