// Function to remove all occurrences of a specified value from a list
std::list<int> filterOutValue(const std::list<int>& sourceList, int targetValue) {
    std::list<int> result;
    for (int element : sourceList) {
        if (element != targetValue) {
            result.push_back(element);
        }
    }
    return result;
}

