int solve() {
    ll inputVal;
    cin >> inputVal; // Read input value
    ll modValue = MOD;

    // Compute n mod MOD and (n+1) mod MOD separately
    ll firstTerm = inputVal % modValue;
    ll secondTerm = (inputVal + 1) % modValue;

    // Multiply the terms and take modulo again
    ll product = (firstTerm * secondTerm) % modValue;

    return product;
}

