int calculateTotalSliderArea(int w, int h, const std::array<Slider, 4>& sliders, int numInputChannels) {
    int accumulatedArea = 0;

    // Iterate through each slider to accumulate their individual areas
    for (size_t idx = 0; idx < sliders.size(); ++idx) {
        const auto& s = sliders[idx];
        accumulatedArea += s.width * s.height;
    }

    // Apply extra area when multiple input channels are present
    if (numInputChannels > 1) {
        accumulatedArea += static_cast<int>(w * h * 0.1);
    }

    return accumulatedArea;
}

