// Alternative implementation of topological sort using Kahn's algorithm with modified traversal order
std::vector<Node::Ptr> topologicalSort(const std::vector<Node::Ptr>& nodes) {
    std::vector<Node::Ptr> resultOrder;
    std::queue<Node::Ptr> pendingNodes;
    std::unordered_map<Node::Ptr, int> incomingCount;

    // Compute incoming edge counts for each node
    for (const auto& srcNode : nodes) {
        for (const auto& dstNode : getNeighbors(srcNode)) {
            incomingCount[dstNode]++;
        }
    }

    // Initialize queue with all nodes having zero incoming edges
    for (const auto& node : nodes) {
        if (incomingCount[node] == 0) {
            pendingNodes.push(node);
        }
    }

    // Process nodes in BFS-like manner
    while (!pendingNodes.empty()) {
        Node::Ptr current = pendingNodes.front();
        pendingNodes.pop();
        resultOrder.push_back(current);

        // Reduce incoming count for all successors
        for (const auto& successor : getNeighbors(current)) {
            incomingCount[successor]--;
            if (incomingCount[successor] == 0) {
                pendingNodes.push(successor);
            }
        }
    }

    return resultOrder;
}

