#include <CL/sycl.hpp>
#include <dpct/dpct.hpp>

// Transpose kernel using a different indexing approach and loop structure
template <typename _DataType>
void dpnp_elemwise_transpose_kernel(void* sycl_queue,
                                    const shape_elem_type* shape,
                                    const _DataType* input,
                                    _DataType* output,
                                    size_t input_strides[2],
                                    size_t output_strides[2],
                                    size_t rows,
                                    size_t cols) {
  sycl::queue* q = reinterpret_cast<sycl::queue*>(sycl_queue);

  q->submit([&](sycl::handler& cgh) {
    auto in_acc = input.get_access<sycl::access::mode::read>(cgh);
    auto out_acc = output.get_access<sycl::access::mode::write>(cgh);

    cgh.parallel_for(sycl::range<2>(rows, cols), [=](sycl::item<2> item) {
      size_t row_idx = item.get_id(0);
      size_t col_idx = item.get_id(1);

      // Calculate original position and transposed position with swapped indices
      size_t original_index = row_idx * input_strides[0] + col_idx * input_strides[1];
      size_t transposed_index = col_idx * output_strides[0] + row_idx * output_strides[1];

      out_acc[transposed_index] = in_acc[original_index];
    });
  });
}

