  std::vector<float> input_data(dim_x * dim_y);
  std::vector<float> output_data(dim_x * dim_y);
  // Initialize the input array
  // ...
  // Create a SYCL queue
  sycl::queue q(sycl::gpu_selector{});

  // Prepare strides for transpose operation: [1, dim_x] for input, [dim_y, 1] for output
  size_t in_strides[2] = {1, static_cast<size_t>(dim_x)};
  size_t out_strides[2] = {static_cast<size_t>(dim_y), 1};

  // Call the DPC++ kernel function for element-wise transpose
  dpnp_elemwise_transpose_kernel<float>(q,
                                        nullptr,
                                        input_data.data(),
                                        output_data.data(),
                                        in_strides,
                                        out_strides,
                                        dim_x,
                                        dim_y);
  // Wait for the kernel to finish
  q.wait();
