#include <asio.hpp>
#include <system_error>

class NetworkManager {
private:
    asio::io_context ioContext;
    asio::ip::tcp::socket clientSocket;

public:
    NetworkManager() : clientSocket(ioContext) {}

    bool EstablishConnection(const std::string& hostAddress, uint16_t serverPort) {
        asio::ip::tcp::resolver resolver(ioContext);
        auto endpoints = resolver.resolve(hostAddress, std::to_string(serverPort));

        try {
            asio::connect(clientSocket, endpoints);
            return true;
        } catch (...) {
            return false;
        }
    }

    bool TransmitData(const EventHeader& msgHeader, const void* payload = nullptr) {
        asio::error_code failureCode;

        // Send message header first
        size_t bytesSent = asio::write(clientSocket, 
                                      asio::buffer(&msgHeader, sizeof(msgHeader)), 
                                      asio::transfer_all(), 
                                      failureCode);

        if (failureCode || bytesSent != sizeof(msgHeader)) {
            return false;
        }

        // Then send optional payload if provided
        if (payload != nullptr && msgHeader.dataSize > 0) {
            bytesSent = asio::write(clientSocket, 
                                   asio::buffer(payload, msgHeader.dataSize), 
                                   asio::transfer_all(), 
                                   failureCode);

            if (failureCode || bytesSent != msgHeader.dataSize) {
                return false;
            }
        }

        return true;
    }
};

