#include <iostream>
#include <cmath>

class Coordinate {
private:
    int xPos, yPos;
public:
    Coordinate(int x, int y) : xPos(x), yPos(y) {}

    double getDistanceFromOrigin() const {
        return std::sqrt(static_cast<double>(xPos * xPos + yPos * yPos));
    }

    double getDistanceTo(const Coordinate& other) const {
        int dx = other.xPos - xPos;
        int dy = other.yPos - yPos;
        return std::sqrt(static_cast<double>(dx * dx + dy * dy));
    }

    void shift(int deltaX, int deltaY) {
        xPos += deltaX;
        yPos += deltaY;
    }

    // Accessors for output purposes
    int getX() const { return xPos; }
    int getY() const { return yPos; }
};

int main() {
    Coordinate pointA(3, 4);
    std::cout << "Distance to origin: " << pointA.getDistanceFromOrigin() << std::endl;

    Coordinate pointB(6, 8);
    std::cout << "Distance between pointA and pointB: " << pointA.getDistanceTo(pointB) << std::endl;

    pointA.shift(1, 1);
    std::cout << "New coordinates of pointA: (" << pointA.getX() << ", " << pointA.getY() << ")" << std::endl;

    return 0;
}

