// Base class for geometric shapes with abstract area calculation
class Shape {
protected:
    double surfaceArea;
public:
    virtual void computeSurface() = 0;
};

// Circle implementation using radius
class CircularRegion : public Shape {
private:
    double radialLength;
public:
    CircularRegion(double r) : radialLength(r) {}
    void computeSurface() override {
        surfaceArea = 3.14159 * radialLength * radialLength;
    }
};

// Rectangle implementation using dimensions
class RectangularRegion : public Shape {
private:
    double horizontalSide;
    double verticalSide;
public:
    RectangularRegion(double h, double v) : horizontalSide(h), verticalSide(v) {}
    void computeSurface() override {
        surfaceArea = horizontalSide * verticalSide;
    }
};

