#include <vector>

// Perform a modified binary search on a rotated sorted array
int find_in_rotated(const std::vector<int>& arr, int target, int left, int right) {
    if (left > right) {
        std::cout << "Value " << target << " not located between positions [" << left << ", " << right << "]." << std::endl;
        return -1;
    }

    int center = left + (right - left) / 2;

    if (arr[center] == target) {
        std::cout << "Value " << target << " discovered at position " << center << "." << std::endl;
        return center;
    }

    // Check if left half is sorted
    if (arr[left] <= arr[center]) {
        // Target lies in the left sorted portion
        if (target >= arr[left] && target < arr[center]) {
            std::cout << "Proceeding to examine left segment indices [" << left << ", " << center - 1 << "]." << std::endl;
            return find_in_rotated(arr, target, left, center - 1);
        } else {
            // Target must be in the right unsorted portion
            std::cout << "Proceeding to examine right segment indices [" << center + 1 << ", " << right << "]." << std::endl;
            return find_in_rotated(arr, target, center + 1, right);
        }
    } else {
        // Right half is sorted
        if (target > arr[center] && target <= arr[right]) {
            std::cout << "Proceeding to examine right segment indices [" << center + 1 << ", " << right << "]." << std::endl;
            return find_in_rotated(arr, target, center + 1, right);
        } else {
            // Target must be in the left unsorted portion
            std::cout << "Proceeding to examine left segment indices [" << left << ", " << center - 1 << "]." << std::endl;
            return find_in_rotated(arr, target, left, center - 1);
        }
    }
}

int main() {
    std::vector<int> data = {6, 7, 8, 9, 10, 1, 2, 3, 4, 5};
    int pos = find_in_rotated(data, 3, 0, static_cast<int>(data.size()) - 1);

    if (pos != -1) {
        std::cout << "Target located at index: " << pos << std::endl;
    } else {
        std::cout << "Target absent from the collection." << std::endl;
    }

    return 0;
}

