#include <unordered_map>
#include <stdexcept>

template <typename T, typename KeyT>
class IndexedStorage {
public:
    using ValueType = T;
    using KeyType = KeyT;

private:
    std::unordered_map<KeyType, ValueType> storage;

public:
    // Inserts a value into the storage and returns its associated key
    KeyType insert(const ValueType& value) {
        static KeyT currentKey = 0;  // Assumes KeyT is incrementable and default-constructible
        storage[currentKey] = value;
        return currentKey++;
    }

    // Fetches the value corresponding to the provided key
    ValueType fetch(const KeyType& key) const {
        auto iter = storage.find(key);
        if (iter != storage.end()) {
            return iter->second;
        }
        throw std::out_of_range("Specified key does not exist in storage");
    }

    // Erases the entry identified by the given key
    void erase(const KeyType& key) {
        storage.erase(key);
    }
};

