// Process a client request and send a fixed response
void processConnection(int connFd) {
    // Define the HTTP response message for the root endpoint
    std::string reply = "HTTP/1.1 200 OK\nContent-Type: text/plain\nContent-Length: 12\n\nHello, World!";
    // Transmit the response to the connected client
    write(connFd, reply.c_str(), reply.length());
    // Terminate the client connection
    close(connFd);
}

int main() {
    // Initialize a TCP socket for the server
    int listenFd = socket(AF_INET, SOCK_STREAM, 0);

    // Configure server address structure
    sockaddr_in serverAddr;
    serverAddr.sin_family = AF_INET;
    serverAddr.sin_port = htons(8080);
    serverAddr.sin_addr.s_addr = INADDR_ANY;

    // Bind the socket to the specified port and interface
    bind(listenFd, (sockaddr *)&serverAddr, sizeof(serverAddr));

    // Start listening for incoming connections with a backlog of 5
    listen(listenFd, 5);

    // Continuously accept and handle client connections
    while (true) {
        int clientFd = accept(listenFd, nullptr, nullptr);
        processConnection(clientFd);
    }

    // Clean up: close the listening socket (unreachable in this infinite loop)
    close(listenFd);
    return 0;
}

#include "Components/Lights/LightInterface.hpp"
#include <vector>
#include <algorithm>

namespace Components::Lights {
    class PointLight : public LightInterface {
    public:
        PointLight(const glm::vec3& pos, const glm::vec3& col)
            : position_(pos), color_(col) {}

        virtual glm::vec3 CalculateIllumination(const glm::vec3& targetPoint) const override {
            glm::vec3 vecToLight = position_ - targetPoint;
            float dist = glm::length(vecToLight);

            if (dist == 0.0f) {
                return glm::vec3(0.0f);
            }

            vecToLight = glm::normalize(vecToLight);
            float attenFactor = 1.0f / (dist * dist);

            float cosAngle = glm::dot(glm::vec3(0.0f, 0.0f, 1.0f), vecToLight);
            float intensity = std::max(cosAngle, 0.0f);

            return color_ * attenFactor * intensity;
        }

    private:
        glm::vec3 position_;
        glm::vec3 color_;
    };

    class DirectionalLight : public LightInterface {
    public:
        DirectionalLight(const glm::vec3& dir, const glm::vec3& col)
            : direction_(dir), color_(col) {}

        virtual glm::vec3 CalculateIllumination(const glm::vec3&) const override {
            glm::vec3 lightDir = -glm::normalize(direction_);
            float cosAngle = glm::dot(glm::vec3(0.0f, 0.0f, 1.0f), lightDir);
            float intensity = std::max(cosAngle, 0.0f);
            return color_ * intensity;
        }

    private:
        glm::vec3 direction_;
        glm::vec3 color_;
    };

    glm::vec3 CalculateIllumination(const glm::vec3& point, 
                                     const std::vector<std::shared_ptr<LightInterface>>& lights) {
        glm::vec3 result(0.0f);
        for (size_t i = 0; i < lights.size(); ++i) {
            result += lights[i]->CalculateIllumination(point);
        }
        return result;
    }
}

