    mutable std::mutex m_mutex;
public:
    void transmit(uint8_t byte) {
        std::lock_guard<std::mutex> lock(m_mutex);
        m_buffer.push_back(byte);
    }

    uint8_t receive() {
        std::lock_guard<std::mutex> lock(m_mutex);
        if (m_buffer.empty()) {
            return 0; // Return default value when buffer is empty
