// Handler management system for callback connections
template <typename... Parameters>
class EventDispatcher {
public:
    using CallbackType = std::function<void(Parameters...)>;

    void addListener(CallbackType handler) {
        handlers_.emplace_back(handler);
    }

    void trigger(Parameters... params) {
        for (size_t i = 0; i < handlers_.size(); ++i) {
            handlers_[i](params...);
        }
    }

private:
    std::vector<CallbackType> handlers_;
};

// Wrapper for individual callback functions
template <typename... Args>
class Connection {
public:
    using Handler = std::function<void(Args...)>;

    Connection(Handler callback) : callback_(callback) {}

    void invoke(Args... arguments) {
        callback_(arguments...);
    }

private:
    Handler callback_;
};

