// Determine the day of the week for a given date using Zeller's congruence
int main(int argc, char* argv[]) {
    int dayInput, monthInput, yearInput;

    // Get day from command line argument or user input
    if (argc > 1) {
        dayInput = std::atoi(argv[1]);
    } else { 
        std::cout << "Enter day: ";
        std::cin >> dayInput;
    }

    // Get month and year from user input
    std::cout << "Enter month: ";
    std::cin >> monthInput;
    std::cout << "Enter year: ";
    std::cin >> yearInput;

    // Adjust month and year for Zeller's formula (January/February are months 13/14 of previous year)
    int adjustedMonth = monthInput;
    int adjustedYear = yearInput;
    if (adjustedMonth < 3) {
        adjustedMonth += 12;
        adjustedYear--;
    }

    // Calculate components for Zeller's congruence
    int centuryValue = adjustedYear / 100;
    int yearInCentury = adjustedYear % 100;

    // Apply Zeller's formula to compute day of week
    int weekday = (dayInput + (13 * (adjustedMonth + 1)) / 5 + yearInCentury + 
                   yearInCentury / 4 + centuryValue / 4 - 2 * centuryValue) % 7;

    // Handle negative results from modulo operation
    if (weekday < 0) {
        weekday += 7;
    }

    // Output corresponding day name
    switch (weekday) {
        case 0:
            std::cout << "Saturday" << std::endl;
            break;
        case 1:
            std::cout << "Sunday" << std::endl;
            break;
        case 2:
            std::cout << "Monday" << std::endl;
            break;
        case 3:
            std::cout << "Tuesday" << std::endl;
            break;
        case 4:
            std::cout << "Wednesday" << std::endl;
            break;
        case 5:
            std::cout << "Thursday" << std::endl;
            break;
        case 6:
            std::cout << "Friday" << std::endl;
            break;
    }

    return 0;
}

