void velocityHandler(const geometry_msgs::Twist::ConstPtr& cmd) {
  // Extract linear and angular components from the incoming message
  double v_linear = cmd->linear.x;
  double v_angular = cmd->angular.z;

  // Compute a combined control signal using weighted combination
  double output_signal = k_linear * v_linear + k_angular * v_angular;

  // Advertise and publish the computed command
  ros::NodeHandle local_nh;
  ros::Publisher cmd_pub = local_nh.advertise<std_msgs::Float64>("/control_commands", 1);

  std_msgs::Float64 output_msg;
  output_msg.data = output_signal;
  cmd_pub.publish(output_msg);
}

