void applyDualThreshold(cv::cuda::GpuMat& inputOutput, float thresholdValue, cv::cuda::Stream& cudaStream) {
    // First: set values below threshold to zero (THRESH_TOZERO_INV)
    cv::cuda::threshold(inputOutput, inputOutput, thresholdValue, 255.0, cv::THRESH_TOZERO_INV, cudaStream);

    // Second: keep only values above threshold as 255 (THRESH_BINARY)
    cv::cuda::threshold(inputOutput, inputOutput, thresholdValue, 255.0, cv::THRESH_BINARY, cudaStream);
}

