namespace cuda {
    // Kernel function to compute element-wise sum of two arrays
    __global__ void computeArraySum(const float* inputX, const float* inputY, float* output, size_t length) {
        size_t position = blockIdx.x * blockDim.x + threadIdx.x;
        if (position < length) {
            output[position] = inputX[position] + inputY[position];
        }
    }

    // Host function to perform array addition on GPU
    void executeVectorAddition(const float* cpuA, const float* cpuB, float* cpuResult, size_t count) {
        float *gpuA, *gpuB, *gpuOutput;

        // Allocate memory on device
        cudaMalloc((void**)&gpuA, count * sizeof(float));
        cudaMalloc((void**)&gpuB, count * sizeof(float));
        cudaMalloc((void**)&gpuOutput, count * sizeof(float));

        // Copy data from host to device
        cudaMemcpy(gpuA, cpuA, count * sizeof(float), cudaMemcpyHostToDevice);
        cudaMemcpy(gpuB, cpuB, count * sizeof(float), cudaMemcpyHostToDevice);

        // Launch kernel with appropriate grid and block dimensions
        int threadsPerBlock = 256;
        int blocksPerGrid = (count + threadsPerBlock - 1) / threadsPerBlock;
        computeArraySum<<<blocksPerGrid, threadsPerBlock>>>(gpuA, gpuB, gpuOutput, count);

        // Copy result back to host
        cudaMemcpy(cpuResult, gpuOutput, count * sizeof(float), cudaMemcpyDeviceToHost);

        // Release device memory
        cudaFree(gpuA);
        cudaFree(gpuB);
        cudaFree(gpuOutput);
    }
}

