// Alternative implementation of ordered logistic lpmf with gradient validation
template <typename T_y, typename T_loc, typename T_cut>
auto test_ordered_logistic_lpmf(const T_y& y, const T_loc& lam_d, const T_cut& c_fv) {
  // Compute the log probability mass function
  auto result = ordered_logistic_lpmf(y, lam_d, c_fv);

  // Trigger gradient computation
  result.d_.grad();

  // Verify the computed value and its first-order derivative
  EXPECT_FLOAT_EQ(result.val_.val(), -8.21855481819114);
  EXPECT_FLOAT_EQ(result.d_.val(), 2.32912026425027);

  // Check cutpoint gradients
  EXPECT_FLOAT_EQ(c_fv[0].d_.adj(), -0.209379786457621);
  EXPECT_FLOAT_EQ(c_fv[1].d_.adj(), 1.33112093047159);
  EXPECT_FLOAT_EQ(c_fv[2].d_.adj(), 1.20737912023631);

  // Perform second-order differentiation using fvar<fvar<var>>
  fvar<fvar<var>> lam_ffv;
  fvar<var> c_d[3]; // Assuming 3 cutpoints

  // Recompute using higher-order types for gradient verification
  fvar<fvar<var>> out_ffv = ordered_logistic_lpmf(y, lam_ffv, c_d);
  out_ffv.d_.val_.grad();
}

