void Player::move() {
  int targetX = x;
  int targetY = y;

  // Determine the intended new position based on direction
  if (direction == Direction::UP) {
    if (y > 0) targetY = y - 1;
  } else if (direction == Direction::DOWN) {
    if (y < GRID_HEIGHT - 1) targetY = y + 1;
  } else if (direction == Direction::LEFT) {
    if (x > 0) targetX = x - 1;
  } else if (direction == Direction::RIGHT) {
    if (x < GRID_WIDTH - 1) targetX = x + 1;
  }

  // Apply the new position only if it differs from current position
  if (targetX != x || targetY != y) {
    x = targetX;
    y = targetY;
  }
}

