// Normalize the result of element-wise multiplication of two images to [0, 1]
cv::Mat normalizeImage(cv::Mat imgA, cv::Mat imgB) {
    // Compute element-wise product of input images
    cv::Mat result = imgA.mul(imgB);

    // Determine the range of pixel values in the result
    double minVal, maxVal;
    cv::minMaxLoc(result, &minVal, &maxVal);

    // Avoid division by zero if all pixels are the same
    double range = maxVal - minVal;
    if (range == 0.0) {
        range = 1.0;  // Prevent division by zero
    }

    // Scale and shift values to fit within [0, 1]
    cv::Mat normalized = (result - minVal) / range;

    return normalized;
}

