namespace {
bool validateCertificate(const net::x509_certificate& cert, const net::x509_certificate& issuerCert) {
    // Get current time once
    auto now = net::x509_util::current_time();

    // Check if certificate is still valid (not expired)
    if (now >= cert.not_after()) {
        return false;
    }

    // Prepare SSL info structure for signature verification
    net::ssl_info sslContext;
    sslContext.set_cert(&cert);
    sslContext.set_issuer(&issuerCert);

    // Perform signature verification
    return net::x509_util::VerifySignedBy(&sslContext);
}
