// Compute the elapsed time in years between two calendar dates
double computeYearDifference(const std::tm& beginTime, const std::tm& finishTime) {
    std::time_t begin = std::mktime(const_cast<std::tm*>(&beginTime));
    std::time_t finish = std::mktime(const_cast<std::tm*>(&finishTime));
    double secondsElapsed = std::difftime(finish, begin);
    const double secondsPerYear = 60.0 * 60.0 * 24.0 * 365.25; // average year length including leap years
    return secondsElapsed / secondsPerYear;
}

