using ArgumentMap = std::map<std::string, std::string>;

// Function to filter out arguments not in the allowed set
void FilterArguments(ArgumentMap& args, const std::set<std::string>& allowedKeys) {
    // Create a temporary copy of keys to avoid iterator invalidation issues
    std::vector<std::string> keysToRemove;

    // Identify keys that should be removed
    for (const auto& pair : args) {
        if (allowedKeys.find(pair.first) == allowedKeys.end()) {
            keysToRemove.push_back(pair.first);
        }
    }

    // Remove the identified keys from the original map
    for (const auto& key : keysToRemove) {
        args.erase(key);
    }
}

