class Vec3 {
public:
    double x, y, z;

    // Constructor with member initializer list
    Vec3(double a, double b, double c) : x(a), y(b), z(c) {}

    // Overloaded + operator: returns a new Vec3 object
    Vec3 operator+(const Vec3 &rhs) const {
        return Vec3(x + rhs.x, y + rhs.y, z + rhs.z);
    }

    // Overloaded += operator: modifies the current object and returns a reference to it
    Vec3& operator+=(const Vec3 &rhs) {
        x += rhs.x;
        y += rhs.y;
        z += rhs.z;
        return *this;
    }
};

