// Redefine the node structure with modified logic
struct TreeNode {
    std::vector<TreeNode*> descendants;
    int x_coord, y_coord;

    TreeNode(std::vector<TreeNode*>& kids, int x, int y) 
        : descendants(kids), x_coord(x), y_coord(y) {}

    void shift(int new_x, int new_y) {
        // Determine how much to shift in each direction
        int dx = new_x - x_coord;
        int dy = new_y - y_coord;

        // Update current position
        x_coord = new_x;
        y_coord = new_y;

        // Propagate the shift to all descendants
        for (TreeNode* child : descendants) {
            child->shift(child->x_coord + dx, child->y_coord + dy);
        }
    }
};

int main() {
    // Build a tree structure
    TreeNode* leaf1 = new TreeNode({}, 1, 1);
    TreeNode* leaf2 = new TreeNode({}, 2, 2);
    TreeNode* root = new TreeNode({leaf1, leaf2}, 0, 0);

    // Apply movement to the root
    root->shift(3, 3);

    // Output final positions for verification
    std::cout << "Root: (" << root->x_coord << ", " << root->y_coord << ")\n";
    std::cout << "Leaf1: (" << leaf1->x_coord << ", " << leaf1->y_coord << ")\n";
    std::cout << "Leaf2: (" << leaf2->x_coord << ", " << leaf2->y_coord << ")\n";

    // Deallocate memory
    delete leaf1;
    delete leaf2;
    delete root;

    return 0;
}

