class UInt64Array {
private:
    std::vector<uint64_t> data;
public:
    // Constructor to initialize the array with a given value
    explicit UInt64Array(uint64_t val) : data(64, val) {}

    // Method to perform element-wise addition
    UInt64Array sumWith(const UInt64Array& other) const {
        UInt64Array temp(0);
        for (size_t idx = 0; idx < 64; ++idx) {
            temp.data[idx] = data[idx] + other.data[idx];
        }
        return temp;
    }

    // Method to perform element-wise subtraction
    UInt64Array diffFrom(const UInt64Array& other) const {
        UInt64Array temp(0);
        for (size_t idx = 0; idx < 64; ++idx) {
            temp.data[idx] = data[idx] - other.data[idx];
        }
        return temp;
    }

    // Method to perform element-wise multiplication
    UInt64Array productWith(const UInt64Array& other) const {
        UInt64Array temp(0);
        for (size_t idx = 0; idx < 64; ++idx) {
            temp.data[idx] = data[idx] * other.data[idx];
        }
        return temp;
    }

    // Method to perform element-wise division
    UInt64Array quotientBy(const UInt64Array& other) const {
        UInt64Array temp(0);
        for (size_t idx = 0; idx < 64; ++idx) {
            if (other.data[idx] != 0) {
                temp.data[idx] = data[idx] / other.data[idx];
            } else {
                temp.data[idx] = std::numeric_limits<uint64_t>::max();
            }
        }
        return temp;
    }

    // Method to get the smallest element in the array
    uint64_t minimum() const {
        return *std::min_element(data.begin(), data.end());
    }

    // Method to get the largest element in the array
    uint64_t maximum() const {
        return *std::max_element(data.begin(), data.end());
    }
};

int main() {
    UInt64Array arr1(5);
    UInt64Array arr2(3);

    UInt64Array resultSum = arr1.sumWith(arr2);
    UInt64Array resultDiff = arr1.diffFrom(arr2);
    UInt64Array resultProduct = arr1.productWith(arr2);
    UInt64Array resultQuotient = arr1.quotientBy(arr2);

    std::cout << "Minimum value of sum: " << resultSum.minimum() << std::endl;
    std::cout << "Maximum value of sum: " << resultSum.maximum() << std::endl;
    std::cout << "Minimum value of difference: " << resultDiff.minimum() << std::endl;
    std::cout << "Maximum value of difference: " << resultDiff.maximum() << std::endl;
    std::cout << "Minimum value of product: " << resultProduct.minimum() << std::endl;
    std::cout << "Maximum value of product: " << resultProduct.maximum() << std::endl;
    std::cout << "Minimum value of quotient: " << resultQuotient.minimum() << std::endl;
    std::cout << "Maximum value of quotient: " << resultQuotient.maximum() << std::endl;

    return 0;
}

