// Abstract base class for geometric shapes
class Shape {
public:
    virtual double calculateArea() = 0;
    virtual double calculateBoundaryLength() = 0;
    virtual void showInformation() = 0;
};

// Circle implementation
class Circle : public Shape {
private:
    double radiusValue;
public:
    Circle(double r) : radiusValue(r) {}

    double calculateArea() override {
        return M_PI * radiusValue * radiusValue;
    }

    double calculateBoundaryLength() override {
        return 2 * M_PI * radiusValue;
    }

    void showInformation() override {
        std::cout << "Circle - Radius: " << radiusValue 
                  << ", Area: " << calculateArea() 
                  << ", Perimeter: " << calculateBoundaryLength() << std::endl;
