// Rectangle implementation
class Rectangle : public Shape {
private:
    double sideA, sideB;
public:
    Rectangle(double l, double w) : sideA(l), sideB(w) {}

    double calculateArea() override {
        return sideA * sideB;
    }

    double calculateBoundaryLength() override {
        return 2 * (sideA + sideB);
    }

    void showInformation() override {
        std::cout << "Rectangle - Length: " << sideA 
                  << ", Width: " << sideB 
                  << ", Area: " << calculateArea() 
                  << ", Perimeter: " << calculateBoundaryLength() << std::endl;
    }
};

// Triangle implementation using Heron's formula
class Triangle : public Shape {
private:
    double edge1, edge2, edge3;
public:
    Triangle(double s1, double s2, double s3) : edge1(s1), edge2(s2), edge3(s3) {}

    double calculateArea() override {
        double semiPerimeter = (edge1 + edge2 + edge3) / 2.0;
        return sqrt(semiPerimeter * (semiPerimeter - edge1) * 
                   (semiPerimeter - edge2) * (semiPerimeter - edge3));
    }

    double calculateBoundaryLength() override {
        return edge1 + edge2 + edge3;
    }

    void showInformation() override {
        std::cout << "Triangle - Edge1: " << edge1 
                  << ", Edge2: " << edge2 
                  << ", Edge3: " << edge3 
                  << ", Area: " << calculateArea() 
                  << ", Perimeter: " << calculateBoundaryLength() << std::endl;
    }
};

