struct ScalaFpgaRawHeader {
    uint16_t m_minApdOffset;
    uint16_t m_maxApdOffset;
    uint16_t m_frequencyInteger;
    uint16_t m_frequencyFractional;
    uint16_t m_deviceId;
    uint16_t m_reservedHeader7;
};

bool parseHeader(const uint8_t* rawData, size_t dataSize, ScalaFpgaRawHeader& header) {
    // Check if the raw data is large enough to contain the header
    constexpr size_t headerSize = sizeof(ScalaFpgaRawHeader);
    if (dataSize < headerSize) {
        return false;  // Not enough bytes for a complete header
    }

    // Read each 16-bit field in little-endian format (LSB first)
    size_t offset = 0;

    // Helper lambda to read a 16-bit value from two consecutive bytes
    auto readUint16 = [&rawData](size_t idx) -> uint16_t {
        return static_cast<uint16_t>((static_cast<uint16_t>(rawData[idx + 1]) << 8) | rawData[idx]);
    };

    header.m_minApdOffset = readUint16(offset); offset += 2;
    header.m_maxApdOffset = readUint16(offset); offset += 2;
    header.m_frequencyInteger = readUint16(offset); offset += 2;
    header.m_frequencyFractional = readUint16(offset); offset += 2;
    header.m_deviceId = readUint16(offset); offset += 2;
    header.m_reservedHeader7 = readUint16(offset);

    return true;  // Successfully parsed all header fields
}

