class ShaderProgram {
public:
    unsigned int createShaderFromSource(const char* shaderCode, GLenum shaderType);
};

unsigned int ShaderProgram::createShaderFromSource(const char* shaderCode, GLenum shaderType) {
    int compileResult;
    char errorLog[512];

    // Create a new shader object of the specified type
    unsigned int shaderId = glCreateShader(shaderType);

    // Provide the shader source code to OpenGL
    glShaderSource(shaderId, 1, &shaderCode, nullptr);

    // Compile the shader
    glCompileShader(shaderId);

    // Check compilation status
    glGetShaderiv(shaderId, GL_COMPILE_STATUS, &compileResult);

    if (compileResult == GL_FALSE) {
        // Retrieve and print error message if compilation failed
        glGetShaderInfoLog(shaderId, 512, nullptr, errorLog);
        std::cerr << "Shader compilation failed: " << errorLog << std::endl;
        return 0;  // Indicate failure by returning 0
    }

    // Return the valid shader ID if compilation succeeded
    return shaderId;
}

