// Performance measurement utility using high-resolution clock
class TimingMonitor {
private:
    static std::map<std::string, std::chrono::high_resolution_clock::time_point> timingStarts;
public:
    // Reset all stored timing data
    static void reset() {
        timingStarts.clear();
    }

    // Begin timing for a named section
    static void beginMeasure(const std::string& label) {
        timingStarts[label] = std::chrono::high_resolution_clock::now();
    }

    // Stop timing for a named section and report duration in milliseconds
    static void endMeasure(const std::string& label) {
        auto it = timingStarts.find(label);
        if (it != timingStarts.end()) {
            auto finish = std::chrono::high_resolution_clock::now();
            auto start = it->second;
            double duration = std::chrono::duration_cast<std::chrono::milliseconds>(finish - start).count();
            std::cerr << "Duration for '" << label << "': " << duration << " ms\n";
            timingStarts.erase(it);
        }
    }

    // Get elapsed time without stopping the timer
    static double currentDuration(const std::string& label) {
        auto it = timingStarts.find(label);
        if (it != timingStarts.end()) {
            auto now = std::chrono::high_resolution_clock::now();
            return std::chrono::duration_cast<std::chrono::milliseconds>(now - it->second).count();
        }
        return 0.0; // No active timer for this label
    }

    // Display currently active timing sections
    static void showActiveTimers() {
        std::cerr << "Active Timers:\n";
        for (const auto& pair : timingStarts) {
            std::cerr << "Section '" << pair.first << "' is running\n";
        }
    }
};

