// Apply smoothing and grayscale conversion to the input image
void applyGeometricFilter(cv::Mat& inputImage, float radius, float baseW, float frontW, int kernelSize) {
    // Convert to grayscale if the image is not already single-channel
    cv::Mat grayScale;
    if (inputImage.channels() == 3) {
        cv::cvtColor(inputImage, grayScale, cv::COLOR_BGR2GRAY);
    } else {
        grayScale = inputImage.clone();
    }

    // Apply Gaussian blur with specified kernel size
    cv::Mat blurred;
    int ksize = kernelSize > 0 ? kernelSize : 1;
    cv::GaussianBlur(grayScale, blurred, cv::Size(ksize, ksize), 0);

    // Replace original image content with processed result
    inputImage = blurred;
}

int main(int argc, char* argv[]) {
    // Validate command-line arguments
    if (argc >= 10) {
        std::string imagePath = argv[1];
        int groundWidth = std::atoi(argv[2]);
        int groundHeight = std::atoi(argv[3]);
        float innerRadius = std::atof(argv[6]);
        float baseWidth = std::atof(argv[7]);
        float frontWidth = std::atof(argv[8]);
        int smoothingKernel = std::atoi(argv[9]);

        // Load the input image
        cv::Mat sourceImage = cv::imread(imagePath);

        // Verify successful image loading
        if (!sourceImage.empty()) {
            // Execute image processing pipeline
            applyGeometricFilter(sourceImage, innerRadius, baseWidth, frontWidth, smoothingKernel);

            // Show the resulting image
            cv::imshow("Filtered Result", sourceImage);
