    }

    return 0;
}

#include <glm/glm.hpp>
#include <glm/gtc/matrix_transform.hpp>

// Apply rotations around Y and Z axes to a 3D position vector
glm::vec3 rotatePosition(const glm::vec3& inputPos, float angleY, float angleZ) {
    // Create rotation matrices for Y and Z axes
    glm::mat4 rotationY = glm::rotate(glm::mat4(1.0f), glm::radians(angleY), glm::vec3(0.0f, 1.0f, 0.0f));
    glm::mat4 rotationZ = glm::rotate(glm::mat4(1.0f), glm::radians(angleZ), glm::vec3(0.0f, 0.0f, 1.0f));

    // Convert the input position to homogeneous coordinates (w = 1.0)
    glm::vec4 posHomogeneous(inputPos.x, inputPos.y, inputPos.z, 1.0f);

    // Apply rotations: first around Y axis, then around Z axis
    posHomogeneous = rotationZ * rotationY * posHomogeneous;

    // Convert back to 3D Cartesian coordinates by discarding the w component
    return glm::vec3(posHomogeneous);
}

