#include <memory>

class CustomMemoryManager {
    std::shared_ptr<void> managedResource;

    template<typename T>
    static void customCleanup(void* rawPtr) {
        if (rawPtr != nullptr) {
            reinterpret_cast<T*>(rawPtr)->~T();
            ::operator delete(rawPtr);
        }
    }

public:
    template<typename T>
    T* acquire() {
        managedResource = std::shared_ptr<void>(
            ::operator new(sizeof(T)), 
            customCleanup<T>
        );
        return static_cast<T*>(managedResource.get());
    }

    template<typename T>
    void release(T* objPtr) {
        if (objPtr != nullptr && objPtr == managedResource.get()) {
            managedResource.reset();
        }
    }
};

