// Process notes based on audition type and parameters
void processNotes(const std::vector<int>& sourceNotes, std::vector<int>& targetInputs, int currentStep, int chunkSize) {
    if (currentStep > 0) {
        size_t startIndex = (currentStep - 1) * chunkSize;

        switch (Settings::getAuditionType()) {
            case AuditionType::NO_AUDITION:
                // No operation required for no audition
                break;

            case AuditionType::PERSONAL: {
                // Manually copy elements from source to target
                for (int i = 0; i < chunkSize && (startIndex + i) < sourceNotes.size(); ++i) {
                    targetInputs[i] = sourceNotes[startIndex + i];
                }
                break;
            }

            case AuditionType::COLLECTIVE:
                // Assert that collective audition is not supported
                assert(false);
                break;
        }
    }
}

