// Create an EGL context for X11 windowing system
bool EGLContextX11::Create(const ContextParams& params, WindowHandle window, const EGLContextBase* shareContext)
{
    // Acquire the default EGL display connection
    EGLDisplay display = eglGetDisplay(EGL_DEFAULT_DISPLAY);
    if (display == EGL_NO_DISPLAY) {
        // Failed to obtain display; abort initialization
        return false;
    }

    // Set up EGL version information
    EGLint majorVersion = 0;
    EGLint minorVersion = 0;

    // Attempt to initialize EGL on the obtained display
    if (!eglInitialize(display, &majorVersion, &minorVersion)) {
        // Initialization failed; clean up and exit
        eglTerminate(display);
        return false;
    }

    // Prepare configuration attributes for surface creation
    EGLConfig config = nullptr;
    EGLint numConfigs = 0;
    const EGLint configAttributes[] = {
        // Define desired surface properties (e.g., color depth, buffer type)
        // Example: EGL_RED_SIZE, EGL_GREEN_SIZE, EGL_BLUE_SIZE, EGL_DEPTH_SIZE
        // ...
        EGL_NONE // End of attribute list marker
    };

    // Select a suitable EGL configuration matching the specified attributes
    if (!eglChooseConfig(display, configAttributes, &config, 1, &numConfigs) || numConfigs == 0) {
        // No valid configuration found; cleanup and fail
        eglTerminate(display);
        return false;
    }

    // Establish rendering context with optional sharing
    EGLContext context = eglCreateContext(display, config, shareContext ? static_cast<EGLContext>(shareContext) : nullptr, nullptr);
    if (context == EGL_NO_CONTEXT) {
        // Context creation failed; release resources
        eglTerminate(display);
        return false;
    }

    // Bind the created context to the current rendering thread and associate with window surfaces
    if (!eglMakeCurrent(display, window, window, context)) {
        // Binding failed; destroy context and terminate display connection
        eglDestroyContext(display, context);
        eglTerminate(display);
        return false;
    }

    // All steps completed successfully — context is ready for use
    return true;
}

