        stream << text << std::endl;
    }
    ~FileDestination() {
        if (stream.is_open()) {
            stream.close();
        }
    }
};

// Main logging utility
class LoggingSystem {
private:
    Severity threshold;
    Destination* target;
public:
    LoggingSystem(Severity minLevel, Destination* dest) 
        : threshold(minLevel), target(dest) {}

    void record(Severity level, const std::string& content) {
        if (level >= threshold) {
            time_t currentTime = time(0);
            char buffer[64];
            strftime(buffer, sizeof(buffer), "%a %b %d %H:%M:%S %Y", localtime(&currentTime));
            std::string formattedTime(buffer);
            std::string fullMessage = "[" + formattedTime + "] " + content;
            target->output(fullMessage);
        }
    }
};

