struct GUID
{
    unsigned long Data1;
    unsigned short Data2;
    unsigned short Data3;
    unsigned char Data4[8];
};

// Convert a 32-character hex string to a GUID structure
GUID hexStringToGuid(const std::string& hexStr)
{
    if (hexStr.length() != 32) {
        throw std::invalid_argument("Hex string must be exactly 32 characters");
    }

    GUID guid = {0};

    // Process each byte individually from the hex string
    for (int idx = 0; idx < 16; ++idx) {
        // Extract two characters representing one byte
        std::string pair = hexStr.substr(2 * idx, 2);

        // Convert the pair of hex digits to an integer value
        unsigned int val = 0;
        for (int j = 0; j < 2; ++j) {
            val *= 16;
            char c = pair[j];
            if (c >= '0' && c <= '9') {
                val += c - '0';
            } else if (c >= 'a' && c <= 'f') {
                val += c - 'a' + 10;
            } else if (c >= 'A' && c <= 'F') {
                val += c - 'A' + 10;
            }
        }

        // Store in the appropriate position
        guid.Data4[idx] = static_cast<unsigned char>(val);
    }

    return guid;
}

