// Create a reversed and folded version of the input string
std::string reverseFoldString(const std::string& input, int n) {
    // Build reversed string manually
    std::string reversed;
    for (int i = input.length() - 1; i >= 0; --i) {
        reversed += input[i];
    }

    // Fold the reversed string into chunks
    std::string result;
    int pos = 0;
    while (pos < reversed.length()) {
        // Extract next chunk of up to n characters
        int chunkSize = (pos + n <= reversed.length()) ? n : (reversed.length() - pos);
        result += reversed.substr(pos, chunkSize);

        // Add comma separator if there are more characters
        if (pos + chunkSize < reversed.length()) {
            result += ",";
        }

        pos += n;
    }

    return result;
}

