#include <folly/Range.h>
#include <folly/IOBuf.h>

// Derive cryptographic keys using HKDF-based key schedule
std::pair<std::vector<uint8_t>, std::unique_ptr<folly::IOBuf>> deriveKeys(
    const std::vector<uint8_t>& sharedSecret,
    const std::vector<uint8_t>& psk,
    const SuiteId& suiteId,
    const KeyScheduleContext& keyScheduleContext,
    const Cipher& cipher) {

  // Perform HKDF-Extract with labeled salt and input key material
  std::vector<uint8_t> prk = hkdf->labeledExtract(
      folly::ByteRange(sharedSecret),
      folly::ByteRange(folly::StringPiece("secret")),
      folly::ByteRange(psk),
      suiteId.clone());

  // Expand pseudorandom key to derive the actual key material
  std::unique_ptr<folly::IOBuf> derivedKey = hkdf->labeledExpand(
      prk,
      folly::ByteRange(folly::StringPiece("key")),
      keyScheduleContext.clone(),
      cipher.keyLength());

  return std::make_pair(prk, std::move(derivedKey));
}

