class Solution {
public:
    bool CheckPermutation(std::string s1, std::string s2) {
        // Early exit if lengths differ - permutations must have same length
        if (s1.size() != s2.size()) {
            return false;
        }

        // Sort both strings in ascending order
        std::sort(s1.begin(), s1.end());
        std::sort(s2.begin(), s2.end());

        // Compare the sorted versions for equality
        return s1.compare(s2) == 0;
    }
};

