class Cone : public Shape {
private:
    double baseRadius;
    double verticalHeight;
public:
    Cone(double r, double h) : baseRadius(r), verticalHeight(h) {}
    double computeVolume() {
        return (1.0 / 3.0) * PI * baseRadius * baseRadius * verticalHeight;
    }
    double computeTotalArea() {
        double slantHeight = sqrt(baseRadius * baseRadius + verticalHeight * verticalHeight);
        return PI * baseRadius * (baseRadius + slantHeight);
    }
};
