class Cylinder : public Shape {
private:
    double baseRadius;
    double verticalHeight;
public:
    Cylinder(double r, double h) : baseRadius(r), verticalHeight(h) {}
    double computeVolume() {
        return PI * baseRadius * baseRadius * verticalHeight;
    }
    double computeTotalArea() {
        return 2 * PI * baseRadius * (baseRadius + verticalHeight);
    }
};

