class UCylinder : public Cylinder {
private:
    double innerHoleRadius;
public:
    UCylinder(double r, double h, double ir) : Cylinder(r, h), innerHoleRadius(ir) {}
    double computeVolume() {
        double outerVol = Cylinder::computeVolume();
        double innerVol = PI * innerHoleRadius * innerHoleRadius * verticalHeight;
        return outerVol - innerVol;
    }
    double computeTotalArea() {
        double outerArea = Cylinder::computeTotalArea();
        double innerSideArea = 2 * PI * innerHoleRadius * verticalHeight;
        return outerArea - innerSideArea;
    }
};

