// Compute the sum of non-NaN values along a given dimension, considering masks
Variable nansum(const Variable &var, const Dim dim, const Masks &masks) {
  // First, compute the combined mask for the given dimension
  if (const auto combined_mask = irreducible_mask(masks, dim); combined_mask.is_valid()) {
    // Apply the mask: replace masked elements with zero and recurse
    return nansum(where(combined_mask, zero_like(var), var), dim, masks);
  } else {
    // No active mask; directly handle NaNs based on dimension
    switch (dim) {
      case Dim::ROW:
        return sum(if_nan_then_zero(var), Dim::ROW);
      case Dim::COLUMN:
        return sum(if_nan_then_zero(var), Dim::COLUMN);
      default:
        throw std::invalid_argument("Unsupported or invalid dimension provided");
    }
  }
}

// Helper function to replace NaNs with zero
Variable if_nan_then_zero(const Variable &var) {
  return where(isnan(var), 0.0, var);
}

