// Verify the normal derivative calculation by comparing numerical and analytical results
void compare_normal_derivative(double step_size, BicubicPatch* surface_patch, Vector3 reference_normal, int tolerance, Vector3 expected_full_deriv) {
    // Preserve original data to restore after testing
    double saved_f = surface_patch->n01->f;
    Vector3 saved_dx = surface_patch->n01->dx;

    // Introduce a slight perturbation to compute finite difference approximation
    surface_patch->n01->f += step_size;
    Vector3 new_normal = surface_patch->calculateNormal();
    Vector3 estimated_deriv = (new_normal - reference_normal) / step_size;

    // Revert the parameter change
    surface_patch->n01->f = saved_f;

    // Determine deviation between estimated and expected derivatives
    double discrepancy = (estimated_deriv - expected_full_deriv).length();

    // Report outcome based on acceptable error margin
    if (discrepancy < tolerance) {
        std::cout << "Normal derivative validation successful, error: " << discrepancy << std::endl;
    } else {
        std::cout << "Normal derivative validation failed, error: " << discrepancy << std::endl;
    }

    // Restore the initial dx state
    surface_patch->n01->dx = saved_dx;
}

