int maxElementsSumLessThanX(int N, int M, int X, int A[], int B[]) {
    // Sort arrays in ascending order for reverse processing
    sort(A, A + N);
    sort(B, B + M);

    int result = 0;
    int currentSum = 0;

    // Try all possible combinations by taking i elements from A (largest ones)
    // and j elements from B (largest ones)
    for (int i = 0; i <= N; ++i) {
        int tempSum = 0;
        int tempCount = 0;

        // Take i largest elements from A (process from end since sorted ascending)
        for (int k = N - 1; k >= N - i && k >= 0; --k) {
            if (tempSum + A[k] > X) break;
            tempSum += A[k];
            tempCount++;
        }

        // With remaining budget, take as many as possible from B (largest first)
        for (int k = M - 1; k >= 0; --k) {
            if (tempSum + B[k] > X) break;
            tempSum += B[k];
            tempCount++;
        }

        if (tempCount > result) {
            result = tempCount;
        }
    }

    return result;
}

