// RAII-style critical section wrapper for mutex operations
class LockGuard {
public:
    void Acquire() {
        mtx.lock();
    }

    void Release() {
        mtx.unlock();
    }

private:
    std::mutex mtx;
};

// RAII lock manager that acquires on construction and releases on destruction
class AutoLock : private NonCopyable {
public:
    explicit AutoLock(LockGuard& guard)
        : lg(guard) {
        lg.Acquire();
    }

    ~AutoLock() {
        lg.Release();
    }

private:
    LockGuard& lg;
};

// Thread-safe stack implementation using mutex-based synchronization
template <typename Item>
class ConcurrentStack {
public:
    void Push(const Item& item) {
        AutoLock lock(lg);
        storage.push(item);
    }

    bool Pop(Item& result) {
        AutoLock lock(lg);
        if (storage.empty()) {
            return false;
        }
        result = storage.top();
        storage.pop();
        return true;
    }

    bool Empty() const {
        AutoLock lock(lg);
        return storage.empty();
    }

private:
    std::stack<Item> storage;
    LockGuard lg;
};

