// Rewrite: Find and modify the first Modbus request and response packets in a PCAP file
void editFirstModbusRequestAndResponsePackets(PcapFileReaderDevice *reader, PcapFileWriterDevice *writer) {
    bool requestProcessed = false;
    bool responseProcessed = false;

    // Process each packet sequentially from the input file
    for (;;) {
        RawPacket currentPacket;
        if (!reader->getNextPacket(currentPacket)) {
            // End of input file reached
            break;
        }

        // Convert raw data into structured Modbus packet
        ModbusPacket parsedPacket = parseModbusPacket(currentPacket);

        // Handle first Modbus request only
        if (parsedPacket.type == ModbusPacketType::Request && !requestProcessed) {
            applyModbusRequestChanges(parsedPacket);
            requestProcessed = true;
        }
        // Handle first Modbus response only
        else if (parsedPacket.type == ModbusPacketType::Response && !responseProcessed) {
            applyModbusResponseChanges(parsedPacket);
            responseProcessed = true;
        }

        // Save packet (modified or original) to output file
        writer->writePacket(currentPacket);
    }

    // Validate that both required packet types were found
    if (!requestProcessed || !responseProcessed) {
        throw std::runtime_error("Missing required Modbus request or response packets");
    }
}

