#include <cmath>

// Determine if and where a ray intersects with a plane
IntersectionTestResult testIntersection(const Ray& ray) {
    IntersectionTestResult result;

    // Compute the denominator: dot product of ray direction and plane normal
    float denominator = dot(ray.direction, getNormal());

    // Check if ray is parallel to the plane (within epsilon tolerance)
    if (std::fabs(denominator) < EPSILON) {
        result.intersects = false;
        return result;
    }

    // Compute the parametric distance along the ray to the intersection point
    float distance = dot(getPlanePoint() - ray.origin, getNormal()) / denominator;

    // If distance is negative, intersection occurs behind the ray origin
    if (distance < 0.0f) {
        result.intersects = false;
        return result;
    }

    // Calculate actual intersection point using parametric equation
    result.intersectionPoint = ray.origin + distance * ray.direction;
    result.intersects = true;
    return result;
}

