const uint32_t INITIAL_HASH[8] = {
    0x6a09e667, 0xbb67ae85, 0x3c6ef372, 0xa54ff53a, 
    0x510e527f, 0x9b05688c, 0x1f83d9ab, 0x5be0cd19
};

// Message schedule array
uint32_t W[64];

// Helper to compute message schedule
void prepare_message_schedule(const uint8_t *block) {
    // Initialize first 16 words from block
    for (int i = 0; i < 16; ++i) {
        W[i] = (static_cast<uint32_t>(block[i*4]) << 24) |
               (static_cast<uint32_t>(block[i*4+1]) << 16) |
               (static_cast<uint32_t>(block[i*4+2]) << 8)  |
               (static_cast<uint32_t>(block[i*4+3]));
    }

    // Extend to 64 words
    for (int i = 16; i < 64; ++i) {
        uint32_t s0 = rotr(W[i-15], 7) ^ rotr(W[i-15], 18) ^ (W[i-15] >> 3);
        uint32_t s1 = rotr(W[i-2], 17) ^ rotr(W[i-2], 19) ^ (W[i-2] >> 10);
        W[i] = W[i-16] + s0 + W[i-7] + s1;
    }
}

// Core compression function
void compress_state(uint32_t *h) {
    // Initialize working variables
    uint32_t a = h[0], b = h[1], c = h[2], d = h[3];
    uint32_t e = h[4], f = h[5], g = h[6], hh = h[7];

    // Main loop
    for (int i = 0; i < 64; ++i) {
        uint32_t S1 = rotr(e, 6) ^ rotr(e, 11) ^ rotr(e, 25);
        uint32_t ch = select_bits(e, f, g);
        uint32_t temp1 = hh + S1 + ch + ROUND_CONSTANTS[i] + W[i];
        uint32_t S0 = rotr(a, 2) ^ rotr(a, 13) ^ rotr(a, 22);
        uint32_t maj = majority_bits(a, b, c);
        uint32_t temp2 = S0 + maj;

        hh = g;
        g = f;
        f = e;
        e = d + temp1;
        d = c;
        c = b;
        b = a;
        a = temp1 + temp2;
    }

    // Update hash values
    h[0] += a; h[1] += b; h[2] += c; h[3] += d;
    h[4] += e; h[5] += f; h[6] += g; h[7] += hh;
}

// SHA-256 processing function
void sha256_process(const uint8_t *data, size_t len, uint32_t state[8]) {
    // Copy initial state
    uint32_t current_state[8];
    for (int i = 0; i < 8; ++i) {
        current_state[i] = state[i];
    }

    // Process each 512-bit (64-byte) block
    for (size_t offset = 0; offset < len; offset += 64) {
        uint8_t block[64];
        size_t remaining = len - offset;
        size_t copy_len = (remaining > 64) ? 64 : remaining;

        // Copy data into block
        for (size_t i = 0; i < copy_len; ++i) {
            block[i] = data[offset + i];
        }
        // Pad remaining bytes with zeros if needed
        for (size_t i = copy_len; i < 64; ++i) {
            block[i] = 0;
        }

        // Prepare message schedule and compress
        prepare_message_schedule(block);
        compress_state(current_state);
    }

    // Update final state
    for (int i = 0; i < 8; ++i) {
        state[i] = current_state[i];
    }
}

