// Helper function to find combinations that sum to target
void combinationSumHelper(std::vector<int>& elements, int remaining, int index, 
                          std::vector<int>& path, std::vector<std::vector<int>>& allPaths) {
    if (remaining == 0) {
        allPaths.emplace_back(path);
        return;
    }

    for (int pos = index; pos < elements.size(); ++pos) {
        // Skip duplicate values to avoid repeated combinations
        if (pos > index && elements[pos] == elements[pos - 1]) continue;

        // Early termination if current element exceeds remaining target
        if (elements[pos] > remaining) break;

        path.push_back(elements[pos]);
        combinationSumHelper(elements, remaining - elements[pos], pos + 1, path, allPaths);
        path.pop_back();
    }
}

// Main function to compute unique combinations summing to target
std::vector<std::vector<int>> computeUniqueCombinations(std::vector<int>& input, int goal) {
    std::sort(input.begin(), input.end());
    std::vector<std::vector<int>> solutions;
    std::vector<int> candidate;
    combinationSumHelper(input, goal, 0, candidate, solutions);
    return solutions;
}

