// Writes point cloud data to a PLY file in binary little-endian format
void PointCloud::writePLY(std::string filePath, cv::Mat pointData) {
  std::ofstream outStream(filePath, std::ios::out | std::ios::binary);
  if (!outStream.is_open()) {
    std::cerr << "Error: Could not open file for writing" << std::endl;
    return;
  }

  int totalPoints = pointData.rows;
  int channelsPerPoint = pointData.cols;

  // Construct and write the PLY header
  outStream << "ply\n";
  outStream << "format binary_little_endian 1.0\n";
  outStream << "element vertex " << totalPoints << "\n";
  outStream << "property float x\n";
  outStream << "property float y\n";
  outStream << "property float z\n";
  outStream << "end_header\n";

  // Serialize each point's coordinates into binary format
  for (int idx = 0; idx < totalPoints; ++idx) {
    float px = pointData.at<float>(idx, 0);
    float py = pointData.at<float>(idx, 1);
    float pz = pointData.at<float>(idx, 2);

    outStream.write(reinterpret_cast<const char*>(&px), sizeof(float));
    outStream.write(reinterpret_cast<const char*>(&py), sizeof(float));
    outStream.write(reinterpret_cast<const char*>(&pz), sizeof(float));

    // Additional properties could be written here if needed
  }

  outStream.close();
}

