void execute_first_task(boost::promise<void>& task_promise) {
    std::random_device entropy_source;
    std::mt19937_64 rng_engine(entropy_source());
    std::uniform_int_distribution<int> sleep_duration(1000, 5000);

    std::this_thread::sleep_for(std::chrono::milliseconds(sleep_duration(rng_engine)));
    task_promise.set_value();
}

void execute_dependent_task(boost::promise<void>& dependent_promise, 
                           boost::future<void>& dependency_future) {
    dependency_future.wait();
    dependent_promise.set_value();
}

int main() {
    boost::promise<void> first_task_promise;
    boost::promise<void> second_task_promise;

    boost::future<void> first_dependency = first_task_promise.get_future();
    boost::future<void> second_dependency = second_task_promise.get_future();

    std::thread worker_thread_1(execute_first_task, std::ref(first_task_promise));
    std::thread worker_thread_2(execute_dependent_task, 
                               std::ref(second_task_promise), 
                               std::ref(first_dependency));

    worker_thread_1.join();
    worker_thread_2.join();

    std::cout << "All operations finished" << std::endl;
    return 0;
}

