            case PinMode::OUTPUT:
                found->second = (value != 0) ? static_cast<int>(LogicLevel::ACTIVE) : static_cast<int>(LogicLevel::INACTIVE);
                break;
            case PinMode::PWM_MODE:
            case PinMode::SERVO_MODE:
                found->second = value;
                break;
            default:
                return;
        }

        if (this->onPinChange) this->onPinChange(pinNumber, found->second);
    }
};

