// Helper function to get last system error as string (assumed to exist)
std::string GetLastSystemError();

// Logging macro (assumed to exist)
#define SAFTM_LOG(level) LogMessage(#level)

void* MapFileIntoMemory(HANDLE file_handle) {
  // Create a file mapping object that refers to the file.
  HANDLE mapping_handle = CreateFileMappingA(
      file_handle, nullptr, PAGE_READONLY, 0, 0, nullptr);

  if (mapping_handle == nullptr) {
    std::string error_msg = GetLastSystemError();
    SAFTM_LOG(ERROR) << "Failed to create file mapping: " << error_msg;
    return nullptr;
  }

  // Ensure the mapping handle is closed on scope exit if not used further
  struct MappingCloser {
    HANDLE h;
    ~MappingCloser() { if (h) CloseHandle(h); }
  } auto_closer(mapping_handle);

  // Map the view of the file into memory
  void* mapped_ptr = MapViewOfFile(mapping_handle, FILE_MAP_READ, 0, 0, 0);

  if (mapped_ptr == nullptr) {
    std::string error_msg = GetLastSystemError();
    SAFTM_LOG(ERROR) << "Failed to map file view: " << error_msg;
    return nullptr;
  }

  // Note: We intentionally do NOT close mapping_handle here because 
  // the returned pointer remains valid only while the mapping exists.
  // The caller is responsible for unmapping via UnmapViewOfFile.
  return mapped_ptr;
}

