// Base class for tokens in the expression system
class Token {
public:
    using Ptr = std::shared_ptr<Token>;
    virtual ~Token() = default;
};

// Token representing a numeric value
class NumToken : public Token {
public:
    double data;
    NumToken(double val) : data(val) {}
};

// Extract numeric value from a token pointer
double extract_value(Token::Ptr tok) {
    return static_cast<NumToken*>(tok.get())->data;
}

// Compute sum of multiple tokens using iterative approach
Token::Ptr compute_sum(const std::vector<Token::Ptr> &inputs) {
    double total = 0.0;
    size_t idx = 0;
    while (idx < inputs.size()) {
        total += extract_value(inputs[idx]);
        ++idx;
    }
    return std::make_shared<NumToken>(total);
}

// Perform subtraction across tokens: first minus all others
Token::Ptr compute_diff(const std::vector<Token::Ptr> &inputs) {
    if (inputs.empty()) {
        return std::make_shared<NumToken>(0.0);
    }
    double acc = extract_value(inputs[0]);
    for (size_t i = 1; i < inputs.size(); ++i) {
        acc -= extract_value(inputs[i]);
    }
    return std::make_shared<NumToken>(acc);
}

// Evaluate a sequence of tokens by applying addition operation
double parse_expression(const std::vector<Token::Ptr> &expr) {
    // Simplified evaluation assuming valid input format
    // In a full implementation, this would handle operator precedence and grouping
    return extract_value(compute_sum(expr));
}

int main() {
    // Construct sample token list: 5 + 3 + 2 + 1
    std::vector<Token::Ptr> expr_tokens = {
        std::make_shared<NumToken>(5.0),
        std::make_shared<NumToken>(3.0),
        std::make_shared<NumToken>(2.0),
        std::make_shared<NumToken>(1.0)
    };

    double final_value = parse_expression(expr_tokens);
    std::cout << "Computed result: " << final_value << std::endl;
    return 0;
}

