// Validate if the given path follows a specific project directory structure
bool checkProjectPath(const std::string& path) {
    // First, ensure the path is not empty
    if (path.empty()) {
        return false;
    }

    // Check for any whitespace characters in the path
    for (char c : path) {
        if (std::isspace(static_cast<unsigned char>(c))) {
            return false;
        }
    }

    // Define regex pattern to match valid project paths:
    // - Starts with a drive letter followed by colon and either \ or /
    // - Then at least two directory segments containing word chars, dots, hyphens, or spaces
    std::regex dirPattern(R"([A-Za-z]:[\\\/][\w.-]+(?:[\\\/][\w.-]+)+)");

    // Verify the entire string matches the pattern
    return std::regex_match(path, dirPattern);
}

