// Compute the total surface area of a rectangular prism
float computeSurfaceArea(float dimX, float dimY, float dimZ) {
    // Using distributive property: 2*(ab + bc + ca) = 2*ab + 2*bc + 2*ca
    float face1 = dimX * dimY;
    float face2 = dimY * dimZ;
    float face3 = dimZ * dimX;

    float total = 2.0f * (face1 + face2 + face3);
    return total;
}

