#include <vector>
#include <algorithm>

class MemoryManager {
private:
    int capacity;
    std::vector<bool> usageFlags;  // Tracks whether each memory slot is in use

public:
    MemoryManager(int totalSize) : capacity(totalSize), usageFlags(totalSize, false) {}

    int findAndReserve(int required) {
        if (required <= 0 || required > capacity) return -1;

        for (int start = 0; start <= capacity - required; ++start) {
            bool available = true;
            for (int k = 0; k < required; ++k) {
                if (usageFlags[start + k]) {
                    available = false;
                    break;
                }
            }

            if (available) {
                for (int k = 0; k < required; ++k) {
                    usageFlags[start + k] = true;
                }
                return start;
            }
        }
        return -1;
    }

    void release(int pos) {
        if (pos >= 0 && pos < capacity) {
            usageFlags[pos] = false;
        }
    }
};

