void writeReducedDataToNetCDF(const std::vector<double>& h_column_data, const std::string& colfile_name) {
    // Synchronize and accumulate data across processors
    amrex::ParallelDescriptor::ReduceRealSum(h_column_data.data(), h_column_data.size(), 
                                             amrex::ParallelDescriptor::IOProcessorNumber());

    // Only the I/O processor handles file writing
    if (amrex::ParallelDescriptor::IOProcessor()) {
        // Open NetCDF file in write mode with NetCDF-4 format
        auto ncf = ncutils::NCFile::open(colfile_name, NC_WRITE | NC_NETCDF4);

        // Determine current position for appending data
        size_t time_index = ncf.dim("ntime").len();

        // Retrieve cumulative simulation time
        amrex::Real sim_time = erf.parent->cumTime();
        ncf.putVar("cumulative_time", &sim_time);

        // Store the processed column data
        ncf.putVar("reduced_data", h_column_data.data(), h_column_data.size());

        // Ensure all changes are committed and close the file
        ncf.close();
    }
}

