// Structure to store parsed command-line configuration
struct ProgramArguments {
    std::string scriptPath;
    std::vector<std::string> extraInputs;
    int testCaseId;
    bool threeDimensional;
    bool enableDiffTesting;
    double diffPerturbationFactor;
};

// Parse command-line arguments into a ProgramArguments object
ProgramArguments extractArgs(int argc, char* argv[]) {
    ProgramArguments config;

    // Map option strings to their corresponding fields and help text
    std::unordered_map<std::string, std::pair<void*, std::string>> argMap = {
        {"-script", {&config.scriptPath, "Lua script file for initial data"}},
        {"-i", {&config.extraInputs, "Additional string input to append"}},
        {"-test", {&config.testCaseId, "Test case identifier (non-Lua test)"}},
        {"--3d", {&config.threeDimensional, "Enable 3D mode (non-Lua test)"}},
        {"--run_diff_test", {&config.enableDiffTesting, "Activate differential testing (non-Lua test)"}},
        {"-dtps", {&config.diffPerturbationFactor, "Scale factor for diff test perturbation"}}
    };

    // Process each argument starting from index 1
    for (int idx = 1; idx < argc; ++idx) {
        std::string currentArg = argv[idx];

        auto it = argMap.find(currentArg);
        if (it != argMap.end()) {
            void* targetPtr = it->second.first;

            if (currentArg == "-i") {
                if (idx + 1 < argc && argv[idx + 1][0] != '-') {
                    static_cast<std::vector<std::string>*>(targetPtr)->push_back(argv[idx + 1]);
                    ++idx;
                }
            } else if (currentArg == "--3d" || currentArg == "--run_diff_test") {
                *static_cast<bool*>(targetPtr) = true;
            } else {
                if (idx + 1 < argc && argv[idx + 1][0] != '-') {
                    if (currentArg == "-dtps") {
                        *static_cast<double*>(targetPtr) = std::stod(argv[idx + 1]);
                    } else {
                        *static_cast<std::string*>(targetPtr) = argv[idx + 1];
                    }
                    ++idx;
                }
            }
        }
    }

    return config;
}

int main(int argc, char* argv[]) {
    ProgramArguments args = extractArgs(argc, argv);

    // Output the parsed configuration
    std::cout << "Script Path: " << args.scriptPath << std::endl;
    std::cout << "Extra Inputs: ";
    for (const auto& input : args.extraInputs) {
        std::cout << input << " ";
    }
    std::cout << std::endl;
    std::cout << "Test Case ID: " << args.testCaseId << std::endl;
    std::cout << "3D Mode: " << (args.threeDimensional ? "enabled" : "disabled") << std::endl;
    std::cout << "Diff Testing: " << (args.enableDiffTesting ? "active" : "inactive") << std::endl;
    std::cout << "Perturbation Factor: " << args.diffPerturbationFactor << std::endl;

    return 0;
}

