namespace blmc_controllers
{
    class CentroidalPDController
    {
    public:
        CentroidalPDController(double proportional_gain, double derivative_gain)
            : kp_(proportional_gain), kd_(derivative_gain) {}

        void update(const RobotState& robot_state, ActuatorCommand& actuator_command)
        {
            // Retrieve current center of mass state from the robot
            Eigen::Vector3d current_com_pos = robot_state.getCenterOfMassPosition();
            Eigen::Vector3d current_com_vel = robot_state.getCenterOfMassVelocity();

            // Compute position and velocity errors
            Eigen::Vector3d pos_error = desired_com_position_ - current_com_pos;
            Eigen::Vector3d vel_error = desired_com_velocity_ - current_com_vel;

            // Apply PD control: force = Kp * error_pos + Kd * error_vel
            Eigen::Vector3d command = kp_ * pos_error + kd_ * vel_error;

            // Apply computed command to actuators
            actuator_command.setControlCommand(command);
        }

        void setTargetCenterOfMass(const Eigen::Vector3d& target_position, const Eigen::Vector3d& target_velocity)
        {
            desired_com_position_ = target_position;
            desired_com_velocity_ = target_velocity;
        }

    private:
        double kp_;  // Proportional gain coefficient
        double kd_;  // Derivative gain coefficient
        Eigen::Vector3d desired_com_position_;
        Eigen::Vector3d desired_com_velocity_;
    };
}  // namespace blmc_controllers

