bool isAligned(int x1, int y1, int x2, int y2) {
    return (x1 == x2) || (y1 == y2);
}

// Check if two points lie on the same diagonal (bishop move)
bool isDiagonal(int x1, int y1, int x2, int y2) {
    return std::abs(x1 - x2) == std::abs(y1 - y2);
}

