#include <iostream>

// Class to detect CPU capabilities using low-level CPUID calls
class ProcessorCapabilities {
public:
    bool hasSSE2;
    bool hasAVX;
    bool hasAVX2;

    // Inline assembly wrapper for CPUID instruction
    void executeCpuid(int registers[4], int leaf) {
        __asm__ __volatile__(
            "cpuid"
            : "=a" (registers[0]), "=b" (registers[1]),
              "=c" (registers[2]), "=d" (registers[3])
            : "a" (leaf)
        );
    }

    // Analyze processor features and update internal flags
    void analyzeProcessor() {
        int regs[4];

        // Get maximum supported CPUID leaf
        executeCpuid(regs, 0);
        int maxLeaf = regs[0];

        if (maxLeaf >= 1) {
            executeCpuid(regs, 1);

            // SSE2 is indicated by bit 26 in EDX register
            hasSSE2 = (regs[3] & (1 << 26)) != 0;

            // AVX is indicated by bit 28 in ECX register
            hasAVX = (regs[2] & (1 << 28)) != 0;
        }

        if (maxLeaf >= 7) {
            executeCpuid(regs, 7);

            // AVX2 is indicated by bit 5 in EBX register
            hasAVX2 = (regs[1] & (1 << 5)) != 0;
        }
    }
};

int main() {
    ProcessorCapabilities procCaps;
    procCaps.analyzeProcessor();

    std::cout << "SSE2 available: " << (procCaps.hasSSE2 ? "Yes" : "No") << std::endl;
    std::cout << "AVX available: " << (procCaps.hasAVX ? "Yes" : "No") << std::endl;
    std::cout << "AVX2 available: " << (procCaps.hasAVX2 ? "Yes" : "No") << std::endl;

    return 0;
}

