{
    return (m_x * rhs.m_x) + (m_y * rhs.m_y);
}

#include <iostream>
#include <vector>
#include <algorithm>
#include <stack>

class TarjanSCC {
private:
    int n;
    std::vector<std::vector<int>> graph;
    std::vector<int> ids;
    std::vector<int> low;
    std::vector<bool> onStack;
    std::stack<int> stk;
    int counter;
    std::vector<std::vector<int>> components;

    void explore(int vertex) {
        ids[vertex] = low[vertex] = counter++;
        stk.push(vertex);
        onStack[vertex] = true;

        for (int neighbor : graph[vertex]) {
            if (ids[neighbor] == -1) {
                explore(neighbor);
                low[vertex] = std::min(low[vertex], low[neighbor]);
            } else if (onStack[neighbor]) {
                low[vertex] = std::min(low[vertex], ids[neighbor]);
            }
        }

        if (ids[vertex] == low[vertex]) {
            std::vector<int> component;
            int current;
            do {
                current = stk.top();
                stk.pop();
                onStack[current] = false;
                component.push_back(current);
                low[current] = ids[vertex];
            } while (current != vertex);

            std::sort(component.begin(), component.end());
            components.push_back(component);
        }
    }

public:
    TarjanSCC(int size) : n(size), 
                         graph(size), 
                         ids(size, -1), 
                         low(size), 
                         onStack(size, false),
                         counter(0),
                         components() {}

    void addEdge(int from, int to) {
        graph[from].push_back(to);
    }

    std::vector<std::vector<int>> getStronglyConnectedComponents() {
        for (int i = 0; i < n; ++i) {
            if (ids[i] == -1) {
                explore(i);
            }
        }

        std::sort(components.begin(), components.end());
        return components;
    }
};

