// Template function to compute maximum of two values (device and host callable)
template <typename T>
__host__ __device__ T odin_max(T a, T b) {
  return (a >= b) ? a : b;
}

// Host-side demonstration using odin_max
void cpuMaxDemo() {
  int first = 10;
  int second = 20;
  int result = odin_max(first, second);
  std::cout << "CPU Max Result: " << result << std::endl;
}

// Device kernel that computes element-wise maximum of two arrays
__global__ void gpuMaxDemo(int* input1, int* input2, int* output, int length) {
  int index = blockIdx.x * blockDim.x + threadIdx.x;
  if (index < length) {
    output[index] = odin_max(input1[index], input2[index]);
  }
}

int main() {
  // Run CPU demonstration
  cpuMaxDemo();

  // GPU demonstration setup
  const int count = 5;
  int hostData1[count] = {1, 5, 3, 7, 9};
  int hostData2[count] = {4, 2, 8, 6, 0};
  int hostOutput[count];

  int* deviceData1, *deviceData2, *deviceOutput;

  // Allocate memory on device
  cudaMalloc((void**)&deviceData1, count * sizeof(int));
  cudaMalloc((void**)&deviceData2, count * sizeof(int));
  cudaMalloc((void**)&deviceOutput, count * sizeof(int));

  // Copy data from host to device
  cudaMemcpy(deviceData1, hostData1, count * sizeof(int), cudaMemcpyHostToDevice);
  cudaMemcpy(deviceData2, hostData2, count * sizeof(int), cudaMemcpyHostToDevice);

  // Launch kernel with one block containing 'count' threads
  gpuMaxDemo<<<1, count>>>(deviceData1, deviceData2, deviceOutput, count);

  // Copy results back to host
  cudaMemcpy(hostOutput, deviceOutput, count * sizeof(int), cudaMemcpyDeviceToHost);

  // Print GPU results
  std::cout << "GPU Max Results: ";
  for (int i = 0; i < count; ++i) {
    std::cout << hostOutput[i] << " ";
  }
  std::cout << std::endl;

  // Clean up device memory
  cudaFree(deviceData1);
  cudaFree(deviceData2);
  cudaFree(deviceOutput);

  return 0;
}

