        return a.size() < b.size();
    }
};

// Compute Euclidean distance between two points in n-dimensional space
double calculateEuclideanDistance(const std::vector<double>& p1, const std::vector<double>& p2) {
    double squaredSum = 0.0;
    for (size_t idx = 0; idx < p1.size(); ++idx) {
        double diff = p1[idx] - p2[idx];
        squaredSum += diff * diff;
    }
    return std::sqrt(squaredSum);
}

