// Check if a mathematical expression has balanced parentheses and valid syntax
bool isProperMathExpression(const std::string& expr) {
    std::stack<char> bracketStack;

    // First pass: check parentheses balance and invalid characters
    for (char ch : expr) {
        if (ch == '(') {
            bracketStack.push(ch);
        } else if (ch == ')') {
            if (bracketStack.empty() || bracketStack.top() != '(') {
                return false;  // Mismatched or extra closing parenthesis
            }
            bracketStack.pop();
        } else if (!std::isdigit(ch) && ch != '+' && ch != '-' && ch != '*' && ch != '/') {
            return false;  // Contains invalid character
        }
    }

    // Ensure all opening parentheses were closed
    if (!bracketStack.empty()) {
        return false;
    }

    // Check for operators at the start or end of the expression
    if (!expr.empty() && 
        (expr[0] == '+' || expr[0] == '-' || expr[0] == '*' || expr[0] == '/')) {
        return false;
    }

    if (!expr.empty() && 
        (expr.back() == '+' || expr.back() == '-' || expr.back() == '*' || expr.back() == '/')) {
        return false;
    }

    // Check for consecutive operators
    for (size_t pos = 0; pos + 1 < expr.length(); ++pos) {
        char current = expr[pos];
        char nextChar = expr[pos + 1];

        bool currentIsOp = (current == '+' || current == '-' || current == '*' || current == '/');
        bool nextIsOp = (nextChar == '+' || nextChar == '-' || nextChar == '*' || nextChar == '/');

        if (currentIsOp && nextIsOp) {
            return false;  // Two operators in sequence
        }
    }

    return true;  // Expression passes all validation checks
}

int main() {
    std::string testExpr1 = "3+4*(7-2)";
    std::string testExpr2 = "(5*2)/3-1";
    std::string testExpr3 = "4+*3";
    std::string testExpr4 = "((8-3)";

    std::cout << std::boolalpha;
    std::cout << "Test expression 1 is valid: " << isProperMathExpression(testExpr1) << std::endl;
    std::cout << "Test expression 2 is valid: " << isProperMathExpression(testExpr2) << std::endl;
    std::cout << "Test expression 3 is valid: " << isProperMathExpression(testExpr3) << std::endl;
    std::cout << "Test expression 4 is valid: " << isProperMathExpression(testExpr4) << std::endl;

    return 0;
}

