// Determine if product version exceeds file version
bool IsProductVersionNewer(const std::wstring& fileVer, const std::wstring& prodVer) {
    int fileMajorPart, fileMinorPart;
    int prodMajorPart, prodMinorPart;
    wchar_t delimiter;

    std::wistringstream fileInput(fileVer), prodInput(prodVer);

    // Parse file version: skip 'v', read major, skip '.', read minor
    fileInput >> delimiter >> fileMajorPart >> delimiter >> fileMinorPart;

    // Parse product version: skip 'v', read major, skip '.', read minor
    prodInput >> delimiter >> prodMajorPart >> delimiter >> prodMinorPart;

    // Compare major versions first
    if (prodMajorPart > fileMajorPart) {
        return true;
    }

    // If major versions are equal, compare minor versions
    if (prodMajorPart == fileMajorPart && prodMinorPart > fileMinorPart) {
        return true;
    }

    return false;
}

int main() {
    std::wstring sampleFileVersion = L"v 1.0";
    std::wstring sampleProductVersion = L"v 5.00";

    if (IsProductVersionNewer(sampleFileVersion, sampleProductVersion)) {
        std::wcout << L"The product version is greater than the file version." << std::endl;
    } else {
        std::wcout << L"The product version is not greater than the file version." << std::endl;
    }

    return 0;
}

