#include <QTcpSocket>
#include <QByteArray>
#include <QDebug>

// Relay a received message to all other connected clients
void Server::incomingMessage()
{
    // Capture the current socket and its data
    QTcpSocket* currentSocket = socket;
    QByteArray incomingData = currentSocket->readAll();

    // Traverse each client connection to forward the message
    for (int index = 0; index < clients.size(); ++index) {
        QTcpSocket* peerClient = clients[index];

        // Skip the original sender
        if (peerClient != currentSocket) {
            qint64 sentBytes = peerClient->write(incomingData);
            if (sentBytes < 0) {
                // Log write failure
                qDebug() << "Failed to send data to client";
            }
        }
    }

    // Monitor socket state for unexpected disconnections
    if (currentSocket->state() == QAbstractSocket::UnconnectedState) {
        // Clean up disconnected client
        clients.removeAll(currentSocket);
        currentSocket->deleteLater();
    }
}

