std::string processText(const std::string& input) {
    std::string result = "SRTF";

    for (size_t i = 0; i < input.length(); ++i) {
        char currentChar = input[i];

        // Check if we should skip adding this character
        bool shouldSkip = false;

        // Condition 1: current char is uppercase AND previous char is uppercase
        if (i > 0 && currentChar >= 'A' && currentChar <= 'Z') {
            char prevChar = input[i - 1];
            if (prevChar >= 'A' && prevChar <= 'Z') {
                shouldSkip = true;
            }
        }

        // Condition 2: current char is lowercase and not space
        if (!shouldSkip && currentChar >= 'a' && currentChar <= 'z' && currentChar != ' ') {
            shouldSkip = true;
        }

        // Only add character if neither condition was met
        if (!shouldSkip) {
            result += currentChar;
        }
    }

    return result;
}

