class CCommandLineProcessor {
public:
    bool HandleInput(const wchar_t* input) {
        std::wstring cmdline(input);
        // Convert to lowercase for case-insensitive matching
        std::transform(cmdline.begin(), cmdline.end(), cmdline.begin(),
            [](wchar_t c) { return static_cast<wchar_t>(std::tolower(c)); });

        if (cmdline.compare(0, 4, L"help") == 0) {
            ShowHelp();
            return true;
        }
        else if (cmdline.compare(0, 7, L"version") == 0) {
            ShowVersion();
            return true;
        }
        else if (cmdline.compare(0, 7, L"execute") == 0) {
            std::wstring target = ExtractSingleArgument(cmdline, L"execute");
            if (!target.empty()) {
                RunFile(target);
                return true;
            }
        }
        else if (cmdline.compare(0, 8, L"settings") == 0) {
            std::vector<std::wstring> options = ExtractMultipleArguments(cmdline, L"settings");
            if (options.size() == 2) {
                Configure(options[0], options[1]);
                return true;
            }
        }

        // Command not recognized or invalid arguments
        return false;
    }

private:
    void ShowHelp() {
        std::cout << "Supported commands:" << std::endl;
        // Add help descriptions here
    }

    void ShowVersion() {
        std::cout << "Program version X.Y.Z" << std::endl;
    }

    void RunFile(const std::wstring& path) {
        // Implementation to run the specified file
    }

    void Configure(const std::wstring& key, const std::wstring& val) {
        // Implementation to update configuration with key-value pair
    }

    std::wstring ExtractSingleArgument(const std::wstring& input, const std::wstring& cmd) {
        size_t idx = input.find(cmd);
        if (idx != std::wstring::npos) {
            size_t start = idx + cmd.length();
            if (start < input.length() && input[start] == L' ') {
                ++start; // Skip the space after command
                return input.substr(start);
            }
        }
        return L"";
    }

    std::vector<std::wstring> ExtractMultipleArguments(const std::wstring& input, const std::wstring& cmd) {
        std::vector<std::wstring> result;
        size_t idx = input.find(cmd);
        if (idx != std::wstring::npos) {
            size_t start = idx + cmd.length();
            if (start < input.length() && input[start] == L' ') {
                ++start;
                std::wstring rest = input.substr(start);

                size_t spaceIdx = rest.find(L' ');
                if (spaceIdx != std::wstring::npos) {
                    result.push_back(rest.substr(0, spaceIdx));
                    result.push_back(rest.substr(spaceIdx + 1));
                }
            }
        }
        return result;
    }
};

