#include <iostream>

// Helper function to check if two subtrees are mirror images of each other
bool checkMirror(TreeNode* first, TreeNode* second) {
    // Both nodes are null: symmetric
    if (first == nullptr && second == nullptr) {
        return true;
    }
    // One is null, the other isn't: not symmetric
    if (first == nullptr || second == nullptr) {
        return false;
    }
    // Values don't match: not symmetric
    if (first->val != second->val) {
        return false;
    }
    // Recursively check: left of first with right of second, and right of first with left of second
    return checkMirror(first->left, second->right) && 
           checkMirror(first->right, second->left);
}

// Main function to determine if the tree is symmetric
bool isSymmetric(TreeNode* root) {
    // An empty tree is considered symmetric
    if (root == nullptr) {
        return true;
    }
    // Check if left and right subtrees are mirrors of each other
    return checkMirror(root->left, root->right);
}

