// Compute the median of a vector of integers
double findMedian(std::vector<int>& nums) {
    // Sort the elements in ascending order
    std::sort(nums.begin(), nums.end());

    size_t count = nums.size();

    if (count == 0) {
        return 0.0; // Handle empty vector case (optional, not specified in original)
    }

    // For even number of elements, compute average of two central values
    if (count % 2 == 0) {
        int left = nums[count / 2 - 1];
        int right = nums[count / 2];
        return (static_cast<double>(left) + static_cast<double>(right)) / 2.0;
    } 
    // For odd number of elements, return the central value
    else {
        return static_cast<double>(nums[count / 2]);
    }
}

