#include <iostream>
#include <stdexcept>

namespace throwing {
    class UniquePtrAssignmentException : public std::exception {
    public:
        const char* what() const noexcept override {
            return "Assignment from throwing::unique_ptr to another is not allowed";
        }
    };

    template <typename T>
    class unique_ptr {
    private:
        T* data_ptr;
    public:
        explicit unique_ptr(T* p = nullptr) : data_ptr(p) {}

        ~unique_ptr() {
            if (data_ptr != nullptr) {
                delete[] data_ptr;
                data_ptr = nullptr;
            }
        }

        // Delete copy constructor and assignment operator to prevent copying
        unique_ptr(const unique_ptr&) = delete;
        unique_ptr& operator=(const unique_ptr&) = delete;

        // Move constructor and move assignment for proper RAII behavior
        unique_ptr(unique_ptr&& other) noexcept : data_ptr(other.data_ptr) {
            other.data_ptr = nullptr;
        }

        unique_ptr& operator=(unique_ptr&& other) noexcept {
            if (this != &other) {
                delete[] data_ptr;
                data_ptr = other.data_ptr;
                other.data_ptr = nullptr;
            }
            return *this;
        }

        T* get() const noexcept { return data_ptr; }

        // Explicitly throw on any attempt to assign via workaround
        void unsafe_assign(const unique_ptr& other) {
            throw UniquePtrAssignmentException();
        }
    };
}

int main() {
    try {
        throwing::unique_ptr<int[]> source(new int[5]);
        throwing::unique_ptr<int[]> destination;

        // This will throw an exception as designed
        destination.unsafe_assign(source);

    } catch (const std::exception& e) {
        std::cout << "Exception: " << e.what() << std::endl;
    }

    return 0;
}

#include <stack>
#include <string>

// Check if brackets in the string are balanced
bool isBalanced(const std::string& input) {
    std::stack<char> brackets;

    for (size_t i = 0; i < input.length(); ++i) {
        char current = input[i];

        // Push opening brackets onto the stack
        if (current == '(' || current == '[' || current == '{') {
            brackets.push(current);
        }
        // Handle closing brackets
        else if (current == ')' || current == ']' || current == '}') {
            // If stack is empty, there's no matching opening bracket
            if (brackets.empty()) {
                return false;
            }

            char lastOpen = brackets.top();
            brackets.pop();

            // Check for mismatched pairs
            if ((current == ')' && lastOpen != '(') ||
                (current == ']' && lastOpen != '[') ||
                (current == '}' && lastOpen != '{')) {
                return false;
            }
        }
    }

    // All brackets must be matched - stack should be empty
    return brackets.empty();
}

