// Helper function to populate a distributed vector with pseudo-random values
void populate_vector(hpx::parallel::vector<int>& vec,
                     hpx::parallel::execution::parallel_executor& exec)
{
    std::srand(static_cast<unsigned>(std::time(nullptr)));
    std::generate(vec.begin(), vec.end(),
                  []() { return std::rand() % 100; });
}

// Helper function to print a distributed vector
void print_vector(const hpx::parallel::vector<int>& vec,
                  const std::string& label = "")
{
    if (!label.empty()) {
        hpx::cout << label << ": ";
    }
    for (const auto& val : vec) {
        hpx::cout << val << " ";
    }
    hpx::cout << hpx::endl;
}

int hpx_main(int argc, char** argv)
{
    // Define two distinct parallel executors
    hpx::parallel::execution::parallel_executor primary_exec;
    hpx::parallel::execution::parallel_executor secondary_exec;

    // Initialize three distributed vectors
    hpx::parallel::vector<int> input_a(100, 0, primary_exec);
    hpx::parallel::vector<int> input_b(100, 0, secondary_exec);
    hpx::parallel::vector<int> output_vec(100, 0, primary_exec);

    // Populate both input vectors with random values
    populate_vector(input_a, primary_exec);
    populate_vector(input_b, secondary_exec);

    // Perform element-wise addition using transform
    hpx::parallel::transform(
        primary_exec,
        input_a.begin(), input_a.end(),
        input_b.begin(),
        output_vec.begin(),
        [](int x, int y) { return x + y; });

    // Output the result
    print_vector(output_vec, "Resultant vector after addition");

    return hpx::finalize();
}

