template <typename T>
struct DirectedEdge {
    size_t destination;
    T cost;
};

template <typename T>
class WeightedGraph {
    std::vector<std::vector<DirectedEdge<T>>> adjList;
public:
    WeightedGraph(size_t n) : adjList(n) {}

    void addConnection(size_t src, size_t dst, T weight) {
        adjList[src].push_back({dst, weight});
    }

    const std::vector<DirectedEdge<T>>& neighbors(size_t node) const {
        return adjList[node];
    }
};

void updatePriorityQueue(const DirectedEdge<size_t>& edge, 
                        std::priority_queue<DirectedEdge<size_t>, 
                                           std::vector<DirectedEdge<size_t>>, 
                                           bool(*)(const DirectedEdge<size_t>&, const DirectedEdge<size_t>&)>& pq,
                        std::vector<size_t>& dist) {
    // This function would typically handle priority queue updates in Dijkstra's algorithm
    // For now, it's a placeholder to maintain structural similarity while changing logic
}

size_t computeTravelTime(const WeightedGraph<size_t>& g, 
                        std::priority_queue<DirectedEdge<size_t>>& pq,
                        size_t startNode, 
                        size_t targetNode) {
    std::vector<size_t> timeToReach(g.adjacencyList.size(), -1); // -1 means unvisited
    timeToReach[startNode] = 0;

    while (!pq.empty()) {
        size_t currentNode = pq.top().destination;
        pq.pop();

        if (currentNode == targetNode) {
            return timeToReach[currentNode]; // Found the shortest path to destination
        }

        for (const DirectedEdge<size_t>& edge : g.neighbors(currentNode)) {
            size_t newTime = timeToReach[currentNode] + edge.cost;

            if (timeToReach[edge.destination] == -1 || newTime < timeToReach[edge.destination]) {
                timeToReach[edge.destination] = newTime;
                pq.push({edge.destination, newTime});
            }
        }
    }

    return -1; // Target not reachable
}

int main() {
    // Create a weighted directed graph with 5 nodes
    WeightedGraph<size_t> network(5);

    network.addConnection(0, 1, 2);
    network.addConnection(0, 2, 5);
    network.addConnection(1, 3, 3);
    network.addConnection(2, 3, 1);
    network.addConnection(3, 4, 4);

    std::priority_queue<DirectedEdge<size_t>> minHeap;
    minHeap.push({0, 0}); // Start from node 0 with initial time 0

    size_t origin = 0;
    size_t goal = 4;

    size_t result = computeTravelTime(network, minHeap, origin, goal);

    std::cout << "Minimum time to reach destination: " << result << std::endl;
    return 0;
}

