#include <openssl/sha.h>

namespace security {
    struct auth_token {
        std::string data;
    };

    struct account_record {
        std::string username;
        auth_token salt_value;
        auth_token hashed_credentials;
    };
}

class CredentialValidator {
public:
    void registerUser(const std::string& user_name, const std::string& secret) {
        security::account_record record;
        record.username = user_name;
        record.salt_value = createRandomSalt();
        record.hashed_credentials = computeHash(secret, record.salt_value);
        // In a real implementation, store the record in persistent storage
        stored_users[user_name] = record;
    }

    bool checkCredentials(const std::string& user_name, const std::string& secret) {
        auto it = stored_users.find(user_name);
        if (it == stored_users.end()) {
            return false; // User not found
        }

        const auto& stored_record = it->second;
        security::auth_token computed_hash = computeHash(secret, stored_record.salt_value);
        return computed_hash.data == stored_record.hashed_credentials.data;
    }

private:
    std::map<std::string, security::account_record> stored_users;

    security::auth_token createRandomSalt() {
        std::random_device entropy_source;
        std::mt19937_64 generator(entropy_source());
        std::uniform_int_distribution<int> distribution(0, 255);
        std::ostringstream buffer;

        for (int index = 0; index < 16; ++index) {
            buffer << std::hex << std::setfill('0') << std::setw(2) << distribution(generator);
        }

        return { buffer.str() };
    }

    security::auth_token computeHash(const std::string& credential, const security::auth_token& salt) {
        std::string combined_input = credential + salt.data;
        unsigned char digest[SHA256_DIGEST_LENGTH];
        SHA256_CTX context;

        SHA256_Init(&context);
        SHA256_Update(&context, combined_input.c_str(), combined_input.size());
        SHA256_Final(digest, &context);

        std::ostringstream hex_stream;
        for (size_t i = 0; i < SHA256_DIGEST_LENGTH; ++i) {
            hex_stream << std::hex << std::setfill('0') << std::setw(2) << static_cast<unsigned int>(digest[i]);
        }

        return { hex_stream.str() };
    }
};

int main() {
    CredentialValidator validator;
    validator.registerUser("Alice", "password123");

    std::cout << "Password verification: " << validator.checkCredentials("Alice", "password123") << std::endl;
    std::cout << "Password verification: " << validator.checkCredentials("Bob", "letmein") << std::endl;

    return 0;
}

