// Extract region of interest data for a specific batch index
Eigen::MatrixXf get_batch_rois(int batch_id, const Eigen::MatrixXf& ground_truth_boxes, const Eigen::MatrixXf& input_rois) {
    // Determine how many ground truth entries belong to the specified batch
    int gt_count = 0;
    for (Eigen::Index idx = 0; idx < ground_truth_boxes.rows(); ++idx) {
        if (static_cast<int>(ground_truth_boxes(idx, 0)) == batch_id) {
            ++gt_count;
        }
    }

    // Allocate space for matching ground truth boxes
    Eigen::MatrixXf selected_gt(gt_count, ground_truth_boxes.cols());
    for (Eigen::Index i = 0, k = 0; i < ground_truth_boxes.rows(); ++i) {
        if (static_cast<int>(ground_truth_boxes(i, 0)) == batch_id) {
            selected_gt.row(k++) = ground_truth_boxes.row(i);
        }
    }

    // Count how many ROIs belong to the current batch
    int roi_count = 0;
    for (Eigen::Index idx = 0; idx < input_rois.rows(); ++idx) {
        if (static_cast<int>(input_rois(idx, 0)) == batch_id) {
            ++roi_count;
        }
    }

    // Prepare matrix for filtered ROIs (excluding the batch index column)
    Eigen::MatrixXf filtered_rois(roi_count, input_rois.cols() - 1);
    for (Eigen::Index i = 0, k = 0; i < input_rois.rows(); ++i) {
        if (static_cast<int>(input_rois(i, 0)) == batch_id) {
            filtered_rois.row(k++) = input_rois.row(i).segment(1, 4);
        }
    }

    return filtered_rois;
}

int main() {
    // Setup test data
    Eigen::MatrixXf gt_boxes(5, 4);
    gt_boxes << 1, 2, 3, 4,
                2, 3, 4, 5,
                1, 2, 3, 4,
                2, 3, 4, 5,
                3, 4, 5, 6;

    Eigen::MatrixXf all_rois(8, 5);
    all_rois << 1, 10, 20, 30, 40,
                2, 15, 25, 35, 45,
                1, 12, 22, 32, 42,
                2, 17, 27, 37, 47,
                3, 11, 21, 31, 41,
                1, 14, 24, 34, 44,
                2, 19, 29, 39, 49,
                3, 16, 26, 36, 46;

