template <typename U>
class python_converter {
public:
    python_converter(PyObject* input_obj)
        : py_obj(input_obj)
        , converted_value()
    {}

    U execute_conversion() {
        // Validate input is callable first
        if (!PyCallable_Check(py_obj)) {
            PyErr_SetString(PyExc_TypeError, "Parameter must be callable");
            throw error_already_set();
        }

        // Execute the callable
        PyObject* call_result = PyObject_CallObject(py_obj, nullptr);
        if (nullptr == call_result) {
            throw error_already_set();
        }

        // Attempt to extract the C++ value
        bool parse_success = PyArg_Parse(call_result, "U", &converted_value);
        Py_DECREF(call_result);

        if (!parse_success) {
            PyErr_SetString(PyExc_TypeError, "Failed to parse Python object to C++ object");
            throw error_already_set();
        }

        return converted_value;
    }

private:
    PyObject* py_obj;
    U converted_value;
};

