using namespace QPatternist;

QString processString(const QString &input) {
    // Convert input to UTF-8 and create UnicodeString
    QByteArray utf8Data = input.toUtf8();
    UnicodeString sourceText(utf8Data.constData(), "UTF-8");

    // Apply Unicode normalization using NFD then compose to NFC
    UnicodeString normalized;
    sourceText.normalize(UNORM_NFC, normalized, 0);

    // Transform all characters to uppercase in-place
    normalized.toUpper();

    // Perform substring replacement using iterative search
    UnicodeString target("QT");
    UnicodeString substitute("qatomicstring");
    int32_t pos = 0;
    while ((pos = normalized.indexOf(target, pos)) != -1) {
        normalized.remove(pos, target.length());
        normalized.insert(pos, substitute);
        pos += substitute.length();
    }

    // Convert back to QString via UTF-8 encoding
    std::string resultUTF8;
    normalized.toUTF8(resultUTF8);
    return QString::fromUtf8(resultUTF8.c_str());
}

