class DnsProvisioner {
public:
    using cb_t = std::function<void(bool)>;

    void provisionHostname(const std::string& hostname, const cb_t& onDone) {
        int attemptsRemaining = 3; // Total allowed attempts including initial try
        attemptProvisioning(hostname, onDone, attemptsRemaining);
    }

    void deleteHostname(const std::string& hostname, const cb_t& onDone) {
        simulateDeleteRequest(hostname, [onDone](bool success) {
            onDone(success); // Propagate deletion result directly
        });
    }

private:
    // Helper to simulate HTTP POST request with retry mechanism
    void attemptProvisioning(const std::string& hostname, const cb_t& onDone, int attemptsLeft) {
        bool operationSucceeded = simulatePostRequest(hostname);

        if (operationSucceeded) {
            onDone(true); // Success case
        } else {
            if (attemptsLeft > 1) {
                // Retry with one less attempt remaining
                attemptProvisioning(hostname, onDone, attemptsLeft - 1);
            } else {
                std::cerr << "Failed to provision hostname after all attempts: " << hostname << std::endl;
                onDone(false); // Exhausted all retries
            }
        }
    }

    // Simulates a POST request to the DNS zone endpoint
    bool simulatePostRequest(const std::string& hostname) {
        // In real implementation, this would make an actual HTTP request
        // For demonstration, assume success only for certain hostnames
        return !hostname.empty() && hostname.length() % 2 == 0;
    }

    // Simulates a DELETE request to remove a DNS entry
    void simulateDeleteRequest(const std::string& hostname, const std::function<void(bool)>& callback) {
        // In real implementation, this would perform an actual DELETE request
        bool success = !hostname.empty(); // Simple heuristic for demo
        callback(success);
    }
};

