class SimpleString {
  private:
    const char* p_;
  public:
    // Constructor
    SimpleString(const char* str) : p_(str) {}

    // Method to return the length of the string using manual counting
    size_t length() const {
        size_t len = 0;
        while (p_[len] != '\0') {
            ++len;
        }
        return len;
    }

    // Method to return the character at a specified index in the string
    char charAt(size_t pos) const {
        if (pos < length()) {
            return p_[pos];
        } else {
            // Handle out-of-bounds index
            return '\0';
        }
    }

    // Method to concatenate another string to the current string and return a new string object
    SimpleString concat(const char* other) const {
        size_t len1 = length();
        size_t len2 = strlen(other);
        size_t totalLen = len1 + len2;

        char* tempBuffer = new char[totalLen + 1];

        // Copy first part manually
        for (size_t i = 0; i < len1; ++i) {
            tempBuffer[i] = p_[i];
        }
        // Copy second part manually
        for (size_t i = 0; i <= len2; ++i) {
            tempBuffer[len1 + i] = other[i];
        }

        SimpleString result(tempBuffer);
        delete[] tempBuffer;
        return result;
    }
};

