// Structure definitions assumed for completeness (not part of original snippet)
struct Ray {
    Vector3 origin;
    Vector3 dir;
};

struct Vector3 {
    float x, y, z;

    Vector3 operator-(const Vector3& other) const {
        return {x - other.x, y - other.y, z - other.z};
    }

    Vector3 operator+(const Vector3& other) const {
        return {x + other.x, y + other.y, z + other.z};
    }

    Vector3 operator*(float scalar) const {
        return {x * scalar, y * scalar, z * scalar};
    }
};

// Dot product function assumed
float DotProduct(const Vector3& a, const Vector3& b) {
    return a.x * b.x + a.y * b.y + a.z * b.z;
}

// Epsilon constant for floating point comparison
constexpr float EPSILON = 1e-6f;

// Special value to indicate no intersection
const Vector3 NO_INTERSECTION = {std::numeric_limits<float>::infinity(), 
                                 std::numeric_limits<float>::infinity(), 
                                 std::numeric_limits<float>::infinity()};

Vector3 CalculateRayPlaneIntersection(const Ray& ray, const Vector3& planePoint, const Vector3& planeNormal) {
    // Compute the dot product of plane normal and ray direction
    float denom = DotProduct(planeNormal, ray.dir);

    // Determine if ray is parallel or nearly parallel to the plane
    if (std::fabs(denom) < EPSILON) {
        return NO_INTERSECTION;
    }

    // Vector from plane point to ray origin
    Vector3 originToPlane = ray.origin - planePoint;

    // Calculate parameter t using the formula: t = (planeNormal · (origin - planePoint)) / denom
    // Note: This is algebraically equivalent to the original but rearranged for numerical stability
    float paramT = -DotProduct(planeNormal, originToPlane) / denom;

    // Check if intersection occurs in the forward direction of the ray
    if (paramT < 0.0f) {
        return NO_INTERSECTION;
    }

    // Compute the actual intersection point
    Vector3 hitPoint = ray.origin + ray.dir * paramT;
    return hitPoint;
}

