// Helper function to get current timestamp (assumed to exist)
uint64_t getCurrentTimeStamp();

void addToSSTable(int targetLevel, const std::string& targetDir, const std::string& key, const std::string& val, 
                  std::vector<std::vector<ssTable>>& levelArray, std::vector<int>& nextLabel, 
                  uint64_t& tmpTimeStamp, uint64_t& tmpSize, std::vector<std::pair<std::string, std::string>>& tmp) {
    // Construct the filename for the new SSTable
    std::string sstFileName = targetDir + "/" + std::to_string(nextLabel[targetLevel]) + ".sst";

    // Create and add new SSTable to the specified level
    levelArray[targetLevel].push_back(ssTable::genTable(sstFileName, tmpTimeStamp, tmp));

    // Increment the label counter for this level
    ++nextLabel[targetLevel];

    // Reset temporary storage
    tmp.clear();
    tmpTimeStamp = 0;
    tmpSize = 0;

    // Insert the new key-value pair into temporary storage
    tmp.emplace_back(key, val);

    // Calculate size contribution: value size + timestamp size + key size field
    tmpSize += val.size() + sizeof(uint64_t) + sizeof(uint32_t);

    // Set timestamp if not already set
    if (tmpTimeStamp == 0) {
        tmpTimeStamp = getCurrentTimeStamp();
    }

    // Sort entries by key in ascending order
    std::sort(tmp.begin(), tmp.end(), 
              [](const auto& lhs, const auto& rhs) { return lhs.first < rhs.first; });

    // Add all key-value pairs from temporary buffer to the latest SSTable
    auto& currentSSTable = levelArray[targetLevel].back();
    for (size_t i = 0; i < tmp.size(); ++i) {
        currentSSTable.addKeyValuePair(tmp[i].first, tmp[i].second);
    }

    // Finalize the SSTable metadata
    currentSSTable.updateMetadata(tmpTimeStamp, tmpSize);
}

