std::vector<std::pair<int, int>> manipulateVector(int M, int N) {
    std::vector<std::pair<int, int>> result;
    int counter = 2; // Start generating from value 2

    // Generate M pairs using decrementing counter approach
    for (int i = 0; i <= M; ++i) {
        result.emplace_back(counter, counter + 1);
        counter += 2;
    }

    // Add the special pair {1, next_value}
    result.emplace_back(1, counter);
    counter += 2;

    // Check if we exceeded N elements
    if (static_cast<int>(result.size()) > N) {
        return {};
    }

    // Pad with additional pairs if needed
    while (static_cast<int>(result.size()) < N) {
        result.emplace_back(counter, counter + 1);
        counter += 2;
    }

    return result;
}

#include <vector>
using namespace std;

// Helper function to traverse and mark connected 'L' cells as visited
void traverseAndMark(vector<vector<char>>& matrix, int row, int col) {
    // Boundary checks and termination condition: out of bounds or not a land cell
    if (row < 0 || row >= matrix.size() || col < 0 || col >= matrix[0].size() || matrix[row][col] != 'L') {
        return;
    }

    // Mark current cell as visited by changing it to water
    matrix[row][col] = 'W';

    // Explore all 8 directions (including diagonals)
    traverseAndMark(matrix, row + 1, col);     // Down
    traverseAndMark(matrix, row - 1, col);     // Up
    traverseAndMark(matrix, row, col + 1);     // Right
    traverseAndMark(matrix, row, col - 1);     // Left
    traverseAndMark(matrix, row + 1, col + 1); // Down-Right diagonal
    traverseAndMark(matrix, row - 1, col - 1); // Up-Left diagonal
    traverseAndMark(matrix, row + 1, col - 1); // Down-Left diagonal
    traverseAndMark(matrix, row - 1, col + 1); // Up-Right diagonal
}

// Count the number of connected components of 'L' cells in the grid
int countIslands(vector<vector<char>>& grid) {
    int islandCount = 0;

    for (int r = 0; r < grid.size(); ++r) {
        for (int c = 0; c < grid[0].size(); ++c) {
            if (grid[r][c] == 'L') {
                islandCount++;
                traverseAndMark(grid, r, c);
            }
        }
    }

    return islandCount;
}

