    std::cout << "Result for 'Float': " << static_cast<int>(TypeParser::parseType("Float")) << std::endl;     // 2 (DataType::Float)
    std::cout << "Result for 'String': " << static_cast<int>(TypeParser::parseType("String")) << std::endl;    // 3 (DataType::String)
    std::cout << "Result for 'Boolean': " << static_cast<int>(TypeParser::parseType("Boolean")) << std::endl;  // 4 (DataType::Boolean)

