class URIQuery {
private:
    std::unordered_map<std::string, std::string> queryMap;
public:
    void AddEntry(const std::string& key, const std::string& value) {
        queryMap[key] = value;
    }

    std::string ToString() const {
        if (queryMap.empty()) {
            return "";
        }

        std::stringstream buffer;
        buffer << "?";

        auto iter = queryMap.begin();
        while (iter != queryMap.end()) {
            buffer << iter->first << "=" << iter->second;

            auto nextIter = iter;
            ++nextIter;
            if (nextIter != queryMap.end()) {
                buffer << "&";
            }
            ++iter;
        }

        return buffer.str();
    }
};

int main() {
    URIQuery q1, q2, q3;
    std::cout << "q1: " << q1.ToString() << std::endl;  // Output: ""

    q1.AddEntry("key1", "value1");
    std::cout << "q1: " << q1.ToString() << std::endl;  // Output: "?key1=value1"

    q1.AddEntry("key2", "value2");
    std::cout << "q1: " << q1.ToString() << std::endl;  // Output: "?key1=value1&key2=value2"

    return 0;
}

