namespace detail {
    // Helper to check if F is not a member pointer
    template <class T>
    using is_not_member_ptr = std::integral_constant<bool, !std::is_member_pointer_v<std::decay_t<T>>>;

    // Overload for non-member function calls
    template <class F, class... Args>
    inline auto INVOKE_IMPL(F&& f, Args&&... args)
      -> std::enable_if_t<is_not_member_ptr<F>::value,
                          decltype(std::forward<F>(f)(std::forward<Args>(args)...))> {
        return std::forward<F>(f)(std::forward<Args>(args)...);
    }
} // namespace detail

// Public interface for invoke-like functionality
template <class F, class... ArgTypes>
auto my_invoke(F&& f, ArgTypes&&... args)
  -> decltype(detail::INVOKE_IMPL(std::forward<F>(f), std::forward<ArgTypes>(args)...)) {
    return detail::INVOKE_IMPL(std::forward<F>(f), std::forward<ArgTypes>(args)...);
}

