void loadAndProcessIR(const std::string& irPath, const std::string& kernelId, bool includeIR) {
    llvm::LLVMContext llvmContext;
    llvm::SMDiagnostic diag;
    auto module = llvm::parseIRFile(irPath, diag, llvmContext);

    if (!module) {
        diag.print("irtoopencl", llvm::errs());
        throw std::runtime_error("IR parsing failed");
    }

    KernelDumper dumper(module.get(), kernelId);
    if (includeIR) {
        dumper.addIRToCl();
    }
}

