// Determine whether the given range type satisfies the View concept requirements
template <typename Range>
constexpr bool models_view() {
    // Check if Range type meets the criteria for being a View
    // This includes being movable, copyable (for some views), and having valid begin/end iterators
    return std::is_move_constructible_v<Range> && 
           requires(Range r) {
               { r.begin() };
               { r.end() };
           };
}

// Alternative implementation using a more explicit trait-based approach
template <typename Range>
constexpr bool check_view_model() {
    // Verify the range type supports essential view operations
    bool has_begin = requires(Range r) { r.begin(); };
    bool has_end = requires(Range r) { r.end(); };
    bool is_movable = std::is_move_constructible_v<Range>;

    return has_begin && has_end && is_movable;
}

