// Compute minimum cost considering two purchasing strategies
int64_t minCost(int64_t unitPrice, int64_t bundlePrice, int64_t totalNeeded, int64_t bundleSize) {
    // Strategy 1: Buy as many bundles as possible, then buy remaining items individually
    int64_t bundles = totalNeeded / bundleSize;
    int64_t remainder = totalNeeded % bundleSize;
    int64_t cost1 = bundles * bundlePrice + remainder * unitPrice;

    // Strategy 2: Buy one more bundle than needed (if beneficial)
    int64_t cost2 = (bundles + 1) * bundlePrice;

    return std::min(cost1, cost2);
}

int main() {
    std::cout << minCost(3, 5, 7, 2) << std::endl;  // Output: 26
    std::cout << minCost(2, 3, 5, 3) << std::endl;  // Output: 9
    return 0;
}

