void updateProbabilities(double c[][10], int posX, int posY, double totalProb, 
                        double probRight, double probUp, double probLeft, int size) {
    // Process each direction using a unified approach
    int dx[] = {1, 0, -1};  // x-direction changes: right, up (no change), left
    int dy[] = {0, -1, 0};  // y-direction changes: right (no change), up, left

    double probs[] = {probRight, probUp, probLeft};

    for (int i = 0; i < 3; ++i) {
        int nextX = posX + dx[i];
        int nextY = posY + dy[i];

        if (isValid(nextX, nextY, size)) {
            c[nextX][nextY] += totalProb * probs[i];
        } else {
            c[posX][posY] += totalProb * probs[i];
        }
    }
}

