// Abstract base class for timer management
class ITimeoutHandler {
public:
    virtual ~ITimeoutHandler() = default;
    virtual void scheduleTimer(int delay, std::function<void()> handler) = 0;
    virtual void tick(int count) = 0;
    virtual std::vector<std::function<void()>> retrieveReadyCallbacks() = 0;
};

// Implementation using hierarchical wheel timer approach
class MultiLevelWheelTimer : public ITimeoutHandler {
private:
    // Storage for timer callbacks organized by time slots
    std::vector<std::unordered_map<int, std::function<void()>>> timerSlots;
    int activeSlotIndex;

public:
    MultiLevelWheelTimer() : timerSlots(5), activeSlotIndex(0) {}

    void scheduleTimer(int delay, std::function<void()> handler) override {
        int targetSlot = (activeSlotIndex + delay) % timerSlots.size();
        timerSlots[targetSlot][delay] = std::move(handler);
    }

    void tick(int steps) override {
        activeSlotIndex = (activeSlotIndex + steps) % timerSlots.size();
    }

    std::vector<std::function<void()>> retrieveReadyCallbacks() override {
        std::vector<std::function<void()>> readyCallbacks;

        for (const auto& slotEntry : timerSlots[activeSlotIndex]) {
            readyCallbacks.push_back(slotEntry.second);
        }

        timerSlots[activeSlotIndex].clear();
        return readyCallbacks;
    }
};

// Factory function to create timer instances
std::shared_ptr<ITimeoutHandler> makeTimer() {
    return std::make_shared<MultiLevelWheelTimer>();
}

int main() {
    std::shared_ptr<ITimeoutHandler> timerSystem = makeTimer();

    timerSystem->scheduleTimer(10, [](){ 
        std::cout << "Timer A triggered" << std::endl; 
    });

    timerSystem->scheduleTimer(5, [](){ 
        std::cout << "Timer B triggered" << std::endl; 
    });

    timerSystem->tick(5);

    auto readyCallbacks = timerSystem->retrieveReadyCallbacks();
    for (const auto& callback : readyCallbacks) {
        callback();
    }

    return 0;
}

