class ValueProcessor {
private:
    int storedValue;
public:
    ValueProcessor() : storedValue(0) {}

    // Overloaded function for lvalue references - adds the value to storedValue
    void compute(int& input) & {
        storedValue += input;
    }

    // Overloaded function for rvalue references - subtracts the value from storedValue
    void compute(int&& input) && {
