#include <string>
#include <algorithm>
#include <cmath>

class Solution
{
public:
    std::vector<int> shortestToChar(std::string &s, char c)
    {
        int n = s.length();
        std::vector<int> distances(n, n);  // Initialize with maximum possible distance

        // First pass: left to right
        int lastPos = -n;  // Track last seen position of character c
        for (int idx = 0; idx < n; ++idx)
        {
            if (s[idx] == c)
                lastPos = idx;
            distances[idx] = std::min(distances[idx], std::abs(idx - lastPos));
        }

        // Second pass: right to left
        lastPos = 2 * n;  // Reset position tracker for reverse traversal
        for (int idx = n - 1; idx >= 0; --idx)
        {
            if (s[idx] == c)
                lastPos = idx;
            distances[idx] = std::min(distances[idx], std::abs(idx - lastPos));
        }

        return distances;
    }
};

