double computeMeanPixelValue(const misaxx::ome::misa_ome_tiff_cache &image_cache, int slice_id) {
    // Extract the planes location metadata from the cache attachment
    misaxx::ome::misa_ome_planes_location plane_info = image_cache.get_attachment<misaxx::ome::misa_ome_planes_location>();

    // Validate the provided slice index
    if (slice_id < 0 || slice_id >= static_cast<int>(plane_info.size())) {
        throw std::out_of_range("Plane index out of bounds");
    }

    // Access the pixel matrix for the requested slice
    const cv::Mat &slice_pixels = plane_info[slice_id].get_plane();

    // Accumulate pixel intensities using a different loop structure
    double cumulative_intensity = 0.0;
    int row_counter = 0;
    while (row_counter < slice_pixels.rows) {
        int col_counter = 0;
        while (col_counter < slice_pixels.cols) {
            cumulative_intensity += static_cast<double>(slice_pixels.at<ushort>(row_counter, col_counter));
            ++col_counter;
        }
        ++row_counter;
    }

    // Compute the arithmetic mean based on total pixels
    double pixel_count = static_cast<double>(slice_pixels.rows * slice_pixels.cols);
    double mean_value = cumulative_intensity / pixel_count;

    return mean_value;
}

