std::pair<cv::Mat, cv::Mat> performImageProcessing(const ImageSet& a, const ImageSet& b) {
    // Compute product of squared images using element-wise multiplication
    cv::Mat productSquared = a.imageSquare.clone();
    productSquared *= b.imageSquare;

    // Compute product of blurred images using element-wise multiplication
    cv::Mat productBlurred = a.imageBlur.clone();
    productBlurred *= b.imageBlur;

    return std::make_pair(productSquared, productBlurred);
}

