// Determine if enough valid contours are present based on area and aspect ratio constraints
bool FilterAndFind(const std::vector<std::vector<cv::Point>>& contours) {
    int acceptableCount = 0;

    for (const auto& shape : contours) {
        double regionArea = cv::contourArea(shape);

        // First filter: check if the contour's area falls within acceptable bounds
        if (regionArea > AREA_LOWER_BOUND && regionArea < AREA_UPPER_BOUND) {
            // Compute the minimum enclosing rectangle for this contour
            cv::Rect rect = cv::boundingRect(shape);

            // Derive the width-to-height ratio of the bounding rectangle
            double widthHeightRatio = static_cast<double>(rect.width) / rect.height;

            // Second filter: validate the aspect ratio against specified limits
            if (widthHeightRatio >= RATIO_MIN && widthHeightRatio <= RATIO_MAX) {
                acceptableCount++;
            }
        }
    }

    // Accept only if the number of qualifying contours exceeds the required minimum
    return acceptableCount > REQUIRED_VALID_COUNT;
