#include <mutex>
#include <unordered_map>

// Base class for type-erased storage of configuration options
class EnvOptionBase {
public:
    virtual ~EnvOptionBase() = default;
};

// Template class to hold typed configuration values with thread-safe access
template <typename T>
class TypedOption : public EnvOptionBase {
public:
    TypedOption(const std::string& n, const T& val) : name(n), storedValue(val) {}

    T getValue() const {
        std::lock_guard<std::mutex> guard(mtx);
        return storedValue;
    }

    void setValue(const T& newValue) {
        std::lock_guard<std::mutex> guard(mtx);
        storedValue = newValue;
    }

private:
    std::string name;
    T storedValue;
    mutable std::mutex mtx;
};

// Centralized manager for configuration settings
class ConfigManager {
public:
    template <typename T>
    static T retrieve(const std::string& key, const T& fallback) {
        if (registry.find(key) == registry.end()) {
            registry[key] = new TypedOption<T>(key, fallback);
        }
        return static_cast<TypedOption<T>*>(registry[key])->getValue();
    }

    template <typename T>
    static void update(const std::string& key, const T& value) {
        auto it = registry.find(key);
        if (it == registry.end()) {
            std::cerr << "Warning: Configuration key '" << key << "' does not exist." << std::endl;
            return;
        }
        static_cast<TypedOption<T>*>(it->second)->setValue(value);
    }

private:
    static std::unordered_map<std::string, EnvOptionBase*> registry;
};

std::unordered_map<std::string, EnvOptionBase*> ConfigManager::registry;

// Helper function to initialize a configuration option with a default value
template <typename T>
void initialize_option(const std::string& key, const T& defaultValue) {
    ConfigManager::retrieve<T>(key, defaultValue);
}

// Demonstration of usage
int main() {
    initialize_option("DEBUG_MODE", true);
    ConfigManager::update<bool>("DEBUG_MODE", false);
    std::cout << "DEBUG_MODE: " << ConfigManager::retrieve<bool>("DEBUG_MODE", true) << std::endl;
    return 0;
}

