namespace phaeton {
    // Enumeration for fundamental data categories
    enum class DataType {
        INTEGER,
        DECIMAL,
        TEXTUAL
    };

    class TypeDescriptor {
    private:
        std::string name;
        DataType category;
        std::vector<TypeDescriptor> compositeTypes;

    public:
        TypeDescriptor(const std::string& identifier, DataType kind) 
            : name(identifier), category(kind) {}

        // Accessor for the type's identifier
        std::string getName() const {
            return name;
        }

        // Append a derived or composite type to the current type
        void addCompositeType(const TypeDescriptor& type) {
            compositeTypes.emplace_back(type);
        }

        // Determine resulting type from binary operation on two operands
        TypeDescriptor deduceResultType(const TypeDescriptor& left, const TypeDescriptor& right) const {
            // Simplified logic: promote to higher precision if mixed numeric types
            if ((left.category == DataType::INTEGER && right.category == DataType::DECIMAL) ||
                (left.category == DataType::DECIMAL && right.category == DataType::INTEGER)) {
                return TypeDescriptor("FLOAT", DataType::DECIMAL);
            }
            // Same type or non-numeric combinations remain unchanged
            return left.category == right.category ? left : TypeDescriptor("UNKNOWN", DataType::TEXTUAL);
        }

        // Validate whether two types can be used together in an operation
        bool areCompatible(const TypeDescriptor& first, const TypeDescriptor& second) const {
            // Allow same-category compatibility (e.g., INT + INT, STRING + STRING)
            if (first.category == second.category) {
                return true;
            }
            // Permit numeric promotion (INT and FLOAT)
            bool isNumericFirst = (first.category == DataType::INTEGER || first.category == DataType::DECIMAL);
            bool isNumericSecond = (second.category == DataType::INTEGER || second.category == DataType::DECIMAL);
            return isNumericFirst && isNumericSecond;
        }
    };
}  // namespace phaeton

