class ThreadIdManager {
public:
    using ThreadName = std::string;
    using ThreadIdentifier = std::pair<ThreadName, int>;

    ThreadIdManager() : next_available_id(0) {}

    ThreadIdentifier createNewId() {
        ThreadIdentifier identifier;
        if (!recycled_ids.empty()) {
            identifier.second = recycled_ids.back();
            recycled_ids.pop_back();
        } else {
            identifier.second = next_available_id++;
        }
        return identifier;
    }

    void releaseId(const ThreadName& thread_name) {
        // Add the released ID back to the pool for reuse
        std::cout << "Releasing thread resource: " << thread_name << std::endl;
    }

private:
    int next_available_id;
    std::vector<int> recycled_ids;
};

