// Node structure for the stack, storing value and current minimum
struct StackNode {
    int value;
    int currentMin;
    StackNode* link;

    StackNode(int v, int m, StackNode* l) : value(v), currentMin(m), link(l) {}
};

class EfficientMinStack {
private:
    StackNode* head;

public:
    EfficientMinStack() : head(nullptr) {}

    // Add element to stack while tracking minimum
    void push(int newValue) {
        if (head == nullptr) {
            head = new StackNode(newValue, newValue, nullptr);
        } else {
            int newMin = (newValue < head->currentMin) ? newValue : head->currentMin;
            head = new StackNode(newValue, newMin, head);
        }
    }

    // Remove top element from stack
    void pop() {
        assert(head != nullptr);  // Verify stack is not empty
        StackNode* oldNode = head;
        head = head->link;
        delete oldNode;
    }

    // Get top element value
    int peek() {
        assert(head != nullptr);  // Verify stack is not empty
        return head->value;
    }

    // Retrieve minimum element in stack
    int findMinimum() {
        assert(head != nullptr);  // Verify stack is not empty
        return head->currentMin;
    }
};

int main() {
    EfficientMinStack stack;
    stack.push(5);
    stack.push(3);
    stack.push(7);
    stack.push(2);

    std::cout << "Top element: " << stack.peek() << std::endl;  // Output: 2
    std::cout << "Minimum element: " << stack.findMinimum() << std::endl;  // Output: 2

    stack.pop();
    std::cout << "Top element after pop: " << stack.peek() << std::endl;  // Output: 7
    std::cout << "Minimum element after pop: " << stack.findMinimum() << std::endl;  // Output: 3

    return 0;
}

