// Compute the mean waiting time using a different approach
float computeMeanWaitingTime(const std::vector<std::pair<int, int>>& jobs) {
    int count = jobs.size();
    int accumulatedWait = 0;
    int elapsed = 0;

    for (const auto& job : jobs) {
        int entryTime = job.first;
        int workDuration = job.second;

        // Determine how long this job waits before execution starts
        int idleTime = (elapsed > entryTime) ? (elapsed - entryTime) : 0;
        accumulatedWait += idleTime;

        // Advance simulation clock by the job's duration
        elapsed += workDuration;

        // If the job arrived after the current clock, adjust to its arrival time first
        if (entryTime > elapsed - workDuration) {
            elapsed = entryTime + workDuration;
        }
    }

    // Convert total waiting time to average (mean)
    float result = static_cast<float>(accumulatedWait) / count;
    return result;
}

