#include <boost/compute/algorithm/transform.hpp>
#include <boost/compute/container/vector.hpp>
#include <boost/compute/iterator/counting_iterator.hpp>
#include <boost/compute/functional/operator.hpp>
namespace compute = boost::compute;

int main() {
    // Input arrays
    compute::vector<float> source_array_1;
    compute::vector<float> source_array_2;
    // Output array
    compute::vector<float> destination_array;

    float scale_factor = 2.0f; // Define the scaling factor

    // Create a compute context and command queue
    compute::device gpu_device = compute::system::default_device();
    compute::context execution_context(gpu_device);
    compute::command_queue processing_queue(execution_context, gpu_device);

    // Get vector size
    auto data_size = source_array_1.size();

    // Perform element-wise computation: dst[i] = src1[i] + src2[i] * factor
    compute::transform(
        compute::make_counting_iterator(0),
        compute::make_counting_iterator(static_cast<int>(data_size)),
        destination_array.begin(),
        [scale_factor, &source_array_1, &source_array_2] __device__ (int idx) {
            return source_array_1[idx] + source_array_2[idx] * scale_factor;
        },
        processing_queue
    );

    // Result is now stored in destination_array
    return 0;
}

