// Compute the product based on set sizes after inserting b into u
int computeProduct(int n, int b, std::set<int> v, std::set<int> u) {
    u.insert(b);  // Add b to set u

    // Determine how many elements are not in each set
    int missingFromV = n - static_cast<int>(v.size());
    int missingFromU = n - static_cast<int>(u.size());

    // Multiply the counts of missing elements from both sets
    int product = missingFromV * missingFromU;

    return product;  // Return the resulting product
}

