class NotImplementedYetException : public std::exception {
private:
    std::string methodName;
    int errorNumber;
    std::string details;
public:
    NotImplementedYetException(const std::string& funcName)
        : methodName(funcName), errorNumber(0), details("") {}
    NotImplementedYetException(const std::string& funcName, int errCode)
        : methodName(funcName), errorNumber(errCode), details("") {}
    NotImplementedYetException(const std::string& funcName, int errCode, const std::string& msg)
        : methodName(funcName), errorNumber(errCode), details(msg) {}

    const char* what() const noexcept override {
        std::stringstream builder;
        builder << "Method '" << methodName << "' has not been implemented";
        if (errorNumber != 0) {
            builder << " [Error #: " << errorNumber << "]";
        }
        if (!details.empty()) {
            builder << " - " << details;
        }
        static std::string result;
        result = builder.str();
        return result.c_str();
    }
};

// Validation routine to ensure the exception behaves correctly
void validateNotImplementedException() {
    try {
        throw NotImplementedYetException("unimplemented_method");
    } catch (const NotImplementedYetException& ex) {
        // Confirm the exception message matches expected format
        assert(std::string(ex.what()) == "Method 'unimplemented_method' has not been implemented");
    }

    try {
        throw NotImplementedYetException("sample_func", 789);
    } catch (const NotImplementedYetException& ex) {
        // Confirm the exception message includes error code
        assert(std::string(ex.what()) == "Method 'sample_func' has not been implemented [Error #: 789]");
    }

    try {
        throw NotImplementedYetException("sample_func", 101, "Additional info");
    } catch (const NotImplementedYetException& ex) {
        // Confirm the exception message includes all components
        assert(std::string(ex.what()) == "Method 'sample_func' has not been implemented [Error #: 101] - Additional info");
    }
}

