// Alternative implementation to fetch PnP device identifiers via WMI
void FetchHardwareIdentifiers(std::vector<std::string>& outputList) {
    HRESULT hr = S_OK;

    // Initialize COM runtime with multithreading support
    hr = CoInitializeEx(nullptr, COINIT_MULTITHREADED);
    if (FAILED(hr)) {
        Diagnostics::LogFailure("COM initialization", std::to_string(hr));
        return;
    }

    // Configure COM security policy for impersonation
    hr = CoInitializeSecurity(
        nullptr,
        -1,
        nullptr,
        nullptr,
        RPC_C_AUTHN_LEVEL_DEFAULT,
        RPC_C_IMP_LEVEL_IMPERSONATE,
        nullptr,
        EOAC_NONE,
        nullptr
    );
    if (FAILED(hr)) {
        CoUninitialize();
        Diagnostics::LogFailure("COM security setup", std::to_string(hr));
        return;
    }

    // Create WMI locator instance
    IWbemLocator* pWmiLocator = nullptr;
    hr = CoCreateInstance(
        CLSID_WbemLocator,
        nullptr,
        CLSCTX_INPROC_SERVER,
        IID_IWbemLocator,
        reinterpret_cast<void**>(&pWmiLocator)
    );
    if (FAILED(hr)) {
        CoUninitialize();
        Diagnostics::LogFailure("WMI locator creation", std::to_string(hr));
        return;
    }

    // Connect to the WMI namespace
    IWbemServices* pWmiServices = nullptr;
    hr = pWmiLocator->ConnectServer(
        _bstr_t(L"ROOT\\CIMV2"),
        nullptr,
        nullptr,
        0,
        nullptr,
        0,
        0,
        &pWmiServices
    );
    pWmiLocator->Release(); // Release after connection established

    if (FAILED(hr)) {
        CoUninitialize();
        Diagnostics::LogFailure("WMI namespace connection", std::to_string(hr));
        return;
    }

    // Apply authentication blanket to the service proxy
    hr = CoSetProxyBlanket(
        pWmiServices,
        RPC_C_AUTHN_WINNT,
        RPC_C_AUTHZ_NONE,
        nullptr,
        RPC_C_AUTHN_LEVEL_CALL,
        RPC_C_IMP_LEVEL_IMPERSONATE,
        nullptr,
        EOAC_NONE
    );
    if (FAILED(hr)) {
        pWmiServices->Release();
        CoUninitialize();
        Diagnostics::LogFailure("Proxy blanket configuration", std::to_string(hr));
        return;
    }

    // Execute WQL query to enumerate Plug and Play devices
    IEnumWbemClassObject* pResultEnum = nullptr;
    hr = pWmiServices->ExecQuery(
        _bstr_t(L"WQL"),
        _bstr_t(L"SELECT * FROM Win32_PnPEntity"),
        WBEM_FLAG_FORWARD_ONLY | WBEM_FLAG_RETURN_IMMEDIATELY,
        nullptr,
        &pResultEnum
    );

    if (FAILED(hr)) {
        pWmiServices->Release();
        CoUninitialize();
        Diagnostics::LogFailure("WMI query execution", std::to_string(hr));
        return;
    }

    // Process results iteratively
    IWbemClassObject* pDeviceObject = nullptr;
    ULONG uNumObjs = 0;

    while (true) {
        hr = pResultEnum->Next(WBEM_INFINITE, 1, &pDeviceObject, &uNumObjs);
        if (FAILED(hr) || uNumObjs == 0) {
            break;
        }

        VARIANT deviceIdVariant;
        VariantInit(&deviceIdVariant);

        hr = pDeviceObject->Get(L"DeviceID", 0, &deviceIdVariant, nullptr, nullptr);
        if (SUCCEEDED(hr) && V_VT(&deviceIdVariant) == VT_BSTR) {
            outputList.emplace_back(std::string(_bstr_t(deviceIdVariant.bstrVal)));
        }

        VariantClear(&deviceIdVariant);
        pDeviceObject->Release();
    }

    // Cleanup resources
    pResultEnum->Release();
    pWmiServices->Release();
    CoUninitialize();
}

