// Calculate GCD using iterative Euclidean algorithm with swapped parameters handling
int greatestCommonDivisor(int a, int b) {
    // Ensure non-negative values for consistency
    if (a < 0) a = -a;
    if (b < 0) b = -b;

    // Handle zero cases
    if (a == 0) return b;
    if (b == 0) return a;

    // Iterative reduction using modulo operation
    while (b != 0) {
        int remainder = a % b;
        a = b;
        b = remainder;
    }
    return a;
}

// Compute LCM using the relationship: lcm(a,b) = |a*b| / gcd(a,b)
int leastCommonMultiple(int p, int q) {
    if (p == 0 || q == 0) return 0;

    int commonDivisor = greatestCommonDivisor(p, q);

    // Avoid potential overflow by dividing first before multiplying
    return (p / commonDivisor) * q;
}

int main() {
    // Display results for various test pairs
    std::cout << "GCD of 12 and 18: " << greatestCommonDivisor(12, 18) << std::endl;   // Expected: 6
    std::cout << "LCM of 12 and 18: " << leastCommonMultiple(12, 18) << std::endl;     // Expected: 36
    std::cout << "GCD of 15 and 25: " << greatestCommonDivisor(15, 25) << std::endl;  // Expected: 5
    std::cout << "LCM of 15 and 25: " << leastCommonMultiple(15, 25) << std::endl;    // Expected: 75
    std::cout << "GCD of 17 and 31: " << greatestCommonDivisor(17, 31) << std::endl;  // Expected: 1
    std::cout << "LCM of 17 and 31: " << leastCommonMultiple(17, 31) << std::endl;    // Expected: 527

    return 0;
}

