// Custom exception for date parsing errors
class DateParsingError : public std::exception {
public:
    const char* what() const noexcept override {
        return "Date parsing error";
    }
};

// Custom exception for date validation errors
class DateValidationError : public std::exception {
public:
    const char* what() const noexcept override {
        return "Date validation error";
    }
};

// Class representing a date and time with validation
class DateTime {
private:
    int year_val, month_val, day_val;
    int hour_val, minute_val, second_val;

public:
    // Constructor that parses and validates the input string
    DateTime(const std::string& inputStr) {
        // Regex pattern to match YYYY-MM-DD HH:MM:SS format
        std::regex dtPattern(R"((\d{4})-(\d{2})-(\d{2}) (\d{2}):(\d{2}):(\d{2}))");
        std::smatch result;

        if (!std::regex_match(inputStr, result, dtPattern)) {
            throw DateParsingError();
        }

        // Extract components from regex match
        year_val = std::stoi(result[1]);
        month_val = std::stoi(result[2]);
        day_val = std::stoi(result[3]);
        hour_val = std::stoi(result[4]);
        minute_val = std::stoi(result[5]);
        second_val = std::stoi(result[6]);

        // Validate parsed values
        if (!checkDate(year_val, month_val, day_val) || !checkTime(hour_val, minute_val, second_val)) {
            throw DateValidationError();
        }
    }

    // Public method to validate current date/time values
    void checkValidity() {
        if (!checkDate(year_val, month_val, day_val) || !checkTime(hour_val, minute_val, second_val)) {
            throw DateValidationError();
        }
    }

private:
    // Check if a year is a leap year
    bool isLeapYear(int y) {
        return (y % 4 == 0 && y % 100 != 0) || (y % 400 == 0);
    }

    // Validate date components
    bool checkDate(int y, int m, int d) {
        if (y < 1 || m < 1 || m > 12 || d < 1) {
            return false;
        }

        // Days per month array (index 0 unused)
        static const int daysPerMonth[] = {0, 31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31};

        // Handle February in leap years
        if (m == 2 && isLeapYear(y)) {
            return d <= 29;
        } else {
            return d <= daysPerMonth[m];
        }
    }

    // Validate time components
    bool checkTime(int h, int min, int sec) {
        return (h >= 0 && h < 24) && 
               (min >= 0 && min < 60) && 
               (sec >= 0 && sec < 60);
    }
};

int main() {
    // Test case 1: Invalid month (13)
    try {
        DateTime dt1("2015-13-05 :06:03");
    } catch (const DateParsingError& e) {
        std::cout << "DateParsingError caught: " << e.what() << std::endl;
    }

    // Test case 2: Wrong separator format
    try {
        DateTime dt2("2015-13-05 09 06 03");
    } catch (const DateParsingError& e) {
        std::cout << "DateParsingError caught: " << e.what() << std::endl;
    }

    // Test case 3: Valid format but invalid month (13)
    try {
        DateTime dt3("2015-13-05 09:06:03");
        dt3.checkValidity();
    } catch (const DateValidationError& e) {
        std::cout << "DateValidationError caught: " << e.what() << std::endl;
    }

    // Test case 4: Fully valid date and time
    try {
        DateTime dt4("2015-12-05 00:06:03");
        dt4.checkValidity();
        std::cout << "Valid date and time" << std::endl;
    } catch (const DateValidationError& e) {
        std::cout << "DateValidationError caught: " << e.what() << std::endl;
    }

    return 0;
}

#include <stxxl/vector>
#include <stxxl/algorithm>
#include <vector>

std::vector<int> externalMultiwayMerge(const std::vector<std::vector<int>>& inputSequences) {
    std::vector<int> mergedResult;

    // Transfer all sorted sequences into STXXL external memory container
    stxxl::vector<int> externalData;
    for (const auto& sequence : inputSequences) {
        externalData.insert(externalData.end(), sequence.begin(), sequence.end());
    }

    // Prepare output container in external memory
    stxxl::vector<int> externalOutput;
    externalOutput.resize(externalData.size());

    // Perform merge operation using STXXL's parallel multiway merge
    // Using iterator-based approach with explicit block size configuration
    stxxl::sort::merge::parallel_multiway_merge(
        externalData.begin(), 
        externalData.end(), 
        externalOutput.begin(), 
        static_cast<unsigned int>(inputSequences.size())
    );

    // Copy results back to standard STL container
    mergedResult.reserve(externalOutput.size());
    for (size_t idx = 0; idx < externalOutput.size(); ++idx) {
        mergedResult.push_back(externalOutput[idx]);
    }

    return mergedResult;
}

