template<typename T>
class Stack {
private:
    std::vector<T> m_Data;
    size_t m_Position;

public:
    Stack() : m_Position(0) {}

    void push(const T& item, bool replace = false) {
        if (replace || m_Data.empty()) {
            m_Data.push_back(item);
        } else {
            T combined = combineElements(m_Data.back(), item);
            m_Data.push_back(combined);
        }
        m_Position = m_Data.size();
    }

    T combineElements(const T& first, const T& second) {
        // Generic combination logic - can be specialized for specific types
        // For numeric types: addition
        // For strings: concatenation
        // This provides a default behavior while allowing customization
        return second; // Default: just use the new element
    }

    // Additional utility functions
    const T& top() const {
        if (m_Data.empty()) {
            throw std::out_of_range("Stack is empty");
        }
        return m_Data.back();
    }

    bool isEmpty() const {
        return m_Data.empty();
    }

    size_t size() const {
        return m_Data.size();
    }

    void pop() {
        if (!m_Data.empty()) {
            m_Data.pop_back();
            m_Position = m_Data.size();
        }
    }
};

