enum class SymbolType {
  Var,
  Func,
  ClassType
};

enum class ScopeType {
  Global,
  ClassScope
};

struct SymbolRecord {
  std::string identifier;
  SymbolType type;
  std::string sourceFile;
  std::vector<std::pair<ScopeType, std::string>> scopes;

  SymbolRecord(const std::string& id, SymbolType t, const std::string& file,
               std::vector<std::pair<ScopeType, std::string>> s)
      : identifier(id), type(t), sourceFile(file), scopes(s) {}
};

class SymbolMonitor {
private:
  std::unordered_map<std::string, std::unordered_map<std::string, bool>> observed;
  std::unordered_map<std::string, std::unordered_map<std::string, bool>> accessed;

public:
  void observe(const SymbolRecord& rec) {
    for (const auto& scope : rec.scopes) {
      observed[scope.second][rec.identifier] = true;
    }
  }

  void markAccessed(const SymbolRecord& rec) {
    for (const auto& scope : rec.scopes) {
      accessed[scope.second][rec.identifier] = true;
    }
  }

  bool hasBeenObserved(const std::string& scope, const std::string& name) const {
    auto it = observed.find(scope);
    if (it != observed.end()) {
      auto innerIt = it->second.find(name);
      return innerIt != it->second.end();
    }
    return false;
  }

  bool hasBeenAccessed(const std::string& scope, const std::string& name) const {
    auto it = accessed.find(scope);
    if (it != accessed.end()) {
      auto innerIt = it->second.find(name);
      return innerIt != it->second.end();
    }
    return false;
  }
};

int main() {
  SymbolMonitor monitor;

  SymbolRecord var1("X2", SymbolType::Var, "HeaderName",
                   {{ScopeType::Global, ""}});
  monitor.observe(var1);
  monitor.markAccessed(var1);

  SymbolRecord var2("X3", SymbolType::Var, "HeaderName",
                   {{ScopeType::Global, ""},
                    {ScopeType::Global, ""}});
  monitor.observe(var2);
  monitor.markAccessed(var2);

  // Check tracking status
  std::cout << "Symbol X2 observed and accessed in global scope: " 
            << monitor.hasBeenObserved("", "X2") << " " 
            << monitor.hasBeenAccessed("", "X2") << std::endl;

  std::cout << "Symbol X3 observed and accessed in global scope: " 
            << monitor.hasBeenObserved("", "X3") << " " 
            << monitor.hasBeenAccessed("", "X3") << std::endl;

  return 0;
}

#include <iostream>

class Item {
public:
    int mnId;
    Item* Next;

    Item(int id) : mnId(id), Next(nullptr) {}
};

class ItemList {
private:
    Item* mHead;
    Item* mTail;
public:
    ItemList() : mHead(nullptr), mTail(nullptr) {}

    ~ItemList() {
        // Clean up memory
        Item* current = mHead;
        while (current != nullptr) {
            Item* next = current->Next;
            delete current;
            current = next;
        }
    }

    void AddItem(int id) {
        Item* newItem = new Item(id);
        if (mHead == nullptr) {
            mHead = newItem;
            mTail = newItem;
        } else {
            mTail->Next = newItem;
            mTail = newItem;
        }
    }

    Item* GetHead() const {
        return mHead;
    }
};

class CustomIterator {
private:
    Item* mpCurrent;
public:
    CustomIterator(Item* pHead) : mpCurrent(pHead) {}

    bool HasNext() const {
        return mpCurrent != nullptr;
    }

    Item* Next() {
        if (mpCurrent == nullptr) {
            return nullptr;
        }
        Item* currentItem = mpCurrent;
        mpCurrent = mpCurrent->Next;
        return currentItem;
    }
};

int main() {
    ItemList* mpItemList = new ItemList();
    mpItemList->AddItem(1);
    mpItemList->AddItem(2);
    mpItemList->AddItem(3);

    CustomIterator iterator(mpItemList->GetHead());

    while (iterator.HasNext()) {
        Item* pItem = iterator.Next();
        std::cout << "Processing item with id: " << pItem->mnId << std::endl;
    }

    delete mpItemList;
    return 0;
}

