// Define terrain types using an enum class for type safety
enum class Terrain { GRASS, WATER, MOUNTAIN, DESERT };

// Generate a terrain map with specified parameters
void generateTerrainMap(int cols, int rows, float fillRatio, unsigned int seedValue, int terrainCount) {
    // Validate input parameters
    if (cols <= 0 || rows <= 0) {
        throw std::invalid_argument("Map dimensions must be positive integers.");
    }
    if (fillRatio <= 0.0f || fillRatio > 1.0f) {
        throw std::invalid_argument("Fill ratio must be in the range (0.0, 1.0].");
    }

    // Initialize random number generator with provided seed
    std::mt19937 rng(seedValue);
    std::uniform_real_distribution<float> dist(0.0f, 1.0f);

    // Create 2D grid initialized to GRASS terrain
    std::vector<std::vector<Terrain>> grid(rows, std::vector<Terrain>(cols, Terrain::GRASS));

    // Populate map based on density
    for (int row = 0; row < rows; ++row) {
        for (int col = 0; col < cols; ++col) {
            if (dist(rng) < fillRatio) {
                // Randomly select a terrain type within valid range
                int selectedType = static_cast<int>(std::rand() % terrainCount);
                grid[row][col] = static_cast<Terrain>(selectedType);
            }
        }
    }

    // Display the generated map
    for (int row = 0; row < rows; ++row) {
        for (int col = 0; col < cols; ++col) {
            std::cout << static_cast<int>(grid[row][col]) << " ";
        }
        std::cout << "\n";
    }
}

int main(int argc, char** argv) {
    try {
        // Example call: 30 columns, 20 rows, full coverage, seed 0, 4 terrain types
        generateTerrainMap(30, 20, 1.0f, 0, 4);
    } catch (const std::invalid_argument& error) {
        std::cerr << "Error: " << error.what() << std::endl;
    }
    return 0;
}

