class Point {
private:
    double x, y;
public:
    Point(double xVal, double yVal) : x(xVal), y(yVal) {}

    double getDistance(const Point& otherPoint) const {
        double dx = otherPoint.x - x;
        double dy = otherPoint.y - y;
        return std::sqrt(dx * dx + dy * dy);
    }

    Point getMidpoint(const Point& otherPoint) const {
        double midX = (x + otherPoint.x) * 0.5;
        double midY = (y + otherPoint.y) * 0.5;
        return Point(midX, midY);
    }

    bool isOnSameLine(const Point& point1, const Point& point2) const {
        // Using cross product to check collinearity: (p2-p1) × (p3-p1) = 0
        double dx1 = point1.x - x;
        double dy1 = point1.y - y;
        double dx2 = point2.x - x;
        double dy2 = point2.y - y;
        return std::abs(dx1 * dy2 - dx2 * dy1) < 1e-9;
    }
};

