// Structure representing rotation in 3D space
struct RotationData
{
    float Pitch;
    float Yaw;
    float Roll;
};

// Convert RotationData to a sequence of bytes
void ConvertToBytes(const RotationData& data, unsigned char* buffer)
{
    std::memcpy(buffer, &data, sizeof(RotationData));
}

// Reconstruct RotationData from a byte sequence
RotationData ConvertFromBytes(const unsigned char* buffer)
{
    RotationData result;
    std::memcpy(&result, buffer, sizeof(RotationData));
    return result;
}

int main()
{
    // Initialize rotation data with sample values
    RotationData inputRotation = {45.0f, 90.0f, 135.0f};

    // Prepare byte storage
