    ConvertToBytes(inputRotation, tempBuffer);

    // Display the byte representation in hexadecimal format
    std::cout << "Byte array representation: ";
    for (size_t index = 0; index < sizeof(RotationData); ++index)
    {
        std::cout << std::hex << static_cast<int>(tempBuffer[index]) << " ";
    }
    std::cout << std::endl;

    // Deserialize bytes back into rotation data
    RotationData recoveredRotation = ConvertFromBytes(tempBuffer);

    // Output the reconstructed rotation values
    std::cout << "Reconstructed RotationData: Pitch=" << recoveredRotation.Pitch
              << ", Yaw=" << recoveredRotation.Yaw
              << ", Roll=" << recoveredRotation.Roll << std::endl;

