      default:
        hash_code = 'M';  // Fallback for unknown hash algorithms
        break;
    }

    // Convert signature algorithm to character code
    char sig_code;
    switch (digitally_signed.signature_algorithm) {
      case DigitallySigned::SIG_ALGO_ECDSA:
        sig_code = 'E';
        break;
      // Handle other signature algorithms if defined
      default:
        sig_code = 'O';  // Fallback for unknown signature algorithms
        break;
    }

    // Construct the encoded string by concatenating components
    *encoded = "";
    *encoded += hash_code;
    *encoded += sig_code;
    *encoded += digitally_signed.signature_data;

