bool AckBitField::IsSetCorrespondingAckBit(PacketSN ackSN)
{
    // Calculate the distance from ackSN to latestAckSN_
    PacketSN current = ackSN;
    uint32_t distance = 0;

    // Count how many increments needed to reach or exceed latestAckSN_
    while (RealtimeSrvHelper::SNGreaterThan(latestAckSN_, current)) {
        current++;
        distance++;
    }

    // If distance is zero, ackSN equals latestAckSN_, so bit should be set
    if (distance == 0) {
        return true;
    }

    // Convert distance to bit position (distance-1 since we count from 0)
    uint32_t bitPosition = distance - 1;
    uint32_t byteOffset = bitPosition / 8;      // Equivalent to >> 3
    uint32_t bitOffset = bitPosition % 8;       // Equivalent to & 0x7

    // Check bounds and bit status
    if (byteOffset >= bitField.size()) {
        return false;
    }

    uint8_t byte = bitField[byteOffset];
    uint8_t mask = static_cast<uint8_t>(1U << bitOffset);
    return (byte & mask) != 0;
}

