// Template structure for binary operation with neutral element
template <typename T>
struct Operation {
  static T identity;  // Identity/neutral value for the operation

  // Apply the binary operation to two values
  static T combine(T a, T b) {
    return a + b;  // Default: addition operation
  }
};

// Initialize the identity element (0 for addition)
template <typename T>
T Operation<T>::identity = 0;

// Generic algorithm that processes data using binary operations
template <typename ForwardIterator1, typename ForwardIterator2, typename Type1, typename Type2, typename Container>
void transformAndAccumulate(ForwardIterator1 start1, ForwardIterator1 finish1, 
                            ForwardIterator2 start2,
                            const Container& offsets, 
                            const Container& validIndices, 
                            const Container& inputValue, 
                            Container& outputValue) {
  for (; start1 != finish1; ++start1, ++start2) {
    Type1 accumulator = Operation<Type1>::identity;

    for (const auto& offset : offsets) {
      auto computedIndex = *start1 + offset;

      // Skip if index is not in the valid set
      if (validIndices.find(computedIndex) == validIndices.end()) {
        continue;
      }

      accumulator = Operation<Type1>::combine(accumulator, inputValue[computedIndex]);
    }

    outputValue[*start2] = static_cast<Type2>(accumulator);
  }
}

