class Histogram {
private:
    const double& lowerBound;
    const double& upperBound;
    const int& numberOfBins;
    double binSize;
    std::vector<int> histogramBins;

    int determineBinNumber(const double& value) {
        return static_cast<int>((value - lowerBound) / binSize);
    }

public:
    Histogram(const double& low, const double& high, const int& bins)
        : lowerBound(low), upperBound(high), numberOfBins(bins), histogramBins(bins, 0) {
        binSize = (upperBound - lowerBound) / numberOfBins;
    }

    void insertValue(const double& value) {
        int index = determineBinNumber(value);
        if (index >= 0 && index < numberOfBins) {
            histogramBins[index]++;
        }
    }

    int getFrequency(const int& binIndex) {
        if (binIndex >= 0 && binIndex < numberOfBins) {
            return histogramBins[binIndex];
        }
        return 0;
    }
};

int main() {
    Histogram dataHistogram(0.0, 10.0, 5);
    dataHistogram.insertValue(2.5);
    dataHistogram.insertValue(7.8);
    dataHistogram.insertValue(11.0);

    std::cout << "Bin 2 count: " << dataHistogram.getFrequency(2) << std::endl;  // Output: Bin 2 count: 1
    std::cout << "Bin 4 count: " << dataHistogram.getFrequency(4) << std::endl;  // Output: Bin 4 count: 0

    return 0;
}

#include <glslang/Public/ShaderLang.h>
#include <SPIRV/GlslangToSpv.h>
#include <SPIRV/SpvTools.h>
#include <SPIRV/disassemble.h>

bool compileGLSLToSPIRV(const std::string& shaderSource, std::vector<unsigned int>& outputSpirv) {
    glslang::InitializeProcess();

    // Create vertex shader object
    glslang::TShader* pShader = new glslang::TShader(EShLangVertex);
    const char* sourcePtr = shaderSource.c_str();
    pShader->setStrings(&sourcePtr, 1);

    // Parse the shader source
    if (!pShader->parse(&glslang::DefaultTBuiltInResource, 100, false, EShMsgDefault)) {
        KG_LOGE(LM_RENDER, "[Compile GLSL to SPIR-V] Shader parsing failed\n%s", pShader->getInfoLog());
        delete pShader;
        glslang::FinalizeProcess();
        return false;
    }

    // Create program and attach shader
    glslang::TProgram* pProgram = new glslang::TProgram();
    pProgram->addShader(pShader);

    // Link the program
    if (!pProgram->link(EShMsgDefault)) {
        KG_LOGE(LM_RENDER, "[Compile GLSL to SPIR-V] Program linking failed\n%s", pProgram->getInfoLog());
        delete pShader;
        delete pProgram;
        glslang::FinalizeProcess();
        return false;
    }

    // Convert to SPIR-V
    spv::SpvBuildLogger messageLogger;
    glslang::GlslangToSpv(*pProgram->getIntermediate(EShLangVertex), outputSpirv, &messageLogger);

    // Report any warnings or errors from SPIR-V generation
    const std::string& allMessages = messageLogger.getAllMessages();
    if (!allMessages.empty()) {
        KG_LOGE(LM_RENDER, "[Compile GLSL to SPIR-V] SPIR-V compilation messages\n%s", allMessages.c_str());
    }

    // Cleanup resources
    delete pShader;
    delete pProgram;
    glslang::FinalizeProcess();

    return true;
}

