// Process image: convert to grayscale, blur, then detect edges
void imageProcessing(cv::Mat &inputImage) {
    // Convert the input image from BGR to grayscale
    cv::Mat intermediateGray;
    cv::cvtColor(inputImage, intermediateGray, cv::COLOR_BGR2GRAY);

    // Apply Gaussian smoothing with a 5x5 kernel and zero sigma
    cv::Mat blurredImage;
    cv::GaussianBlur(intermediateGray, blurredImage, cv::Size(5, 5), 0.0);

    // Detect edges using Canny algorithm with lower threshold 100 and upper threshold 200
    cv::Canny(blurredImage, inputImage, 100, 200);
}

