class ResourceManager {
private:
    std::unordered_map<int, ResourceTexture*> texture_cache;

public:
    ResourceManager() : next_id(1000) {}

    ~ResourceManager() {
        // Clean up allocated resources
        for (auto& pair : texture_cache) {
            delete pair.second;
        }
        texture_cache.clear();
    }

    // Search for existing texture resource by file path and name
    ResourceTexture* FindExistingTexture(const std::string& origin_file, const std::string& resource_name) {
        for (auto& pair : texture_cache) {
            if (pair.second->filePath == origin_file && 
                pair.second->name == resource_name) {
                return pair.second;
            }
        }
        return nullptr;
    }

    // Manage texture resource with improved logic
    ResourceTexture* GetOrCreateTexture(const std::string& file_path, 
                                       const std::string& tex_name, 
                                       SceneImporter* importer) {
        // First check if already exists in cache
        ResourceTexture* existing = FindExistingTexture(file_path, tex_name);
        if (existing != nullptr) {
            return existing;
        }

        // If not found, import new texture
        ResourceTexture* imported = importer->TextureImport(file_path, tex_name);
        if (imported != nullptr) {
            // Store using ID as key
            texture_cache[imported->ID] = imported;
        }
        return imported;
    }

private:
    int next_id;
};

