class NamespaceManager {
private:
    std::unordered_map<std::string, std::unordered_map<std::string, bool>> symbolTables;

public:
    void registerSymbol(const std::string& scopeName, const std::string& symbolName) {
        symbolTables[scopeName][symbolName] = true;
    }

    std::string checkSymbol(const std::string& scopeName, const std::string& symbolName) {
        auto scopeIt = symbolTables.find(scopeName);
        if (scopeIt != symbolTables.end()) {
            auto symbolIt = scopeIt->second.find(symbolName);
            if (symbolIt != scopeIt->second.end()) {
                return "Symbol '" + symbolName + "' exists in scope '" + scopeName + "'.";
            }
        }
        return "Symbol '" + symbolName + "' does not exist in scope '" + scopeName + "'.";
    }
};

int main() {
    NamespaceManager manager;
    manager.registerSymbol("namespace1", "identifier1");
    manager.registerSymbol("namespace1", "identifier2");
    manager.registerSymbol("namespace2", "identifier3");

    std::cout << manager.checkSymbol("namespace1", "identifier1") << std::endl;  // Output: Symbol 'identifier1' exists in scope 'namespace1'.
    std::cout << manager.checkSymbol("namespace1", "identifier3") << std::endl;  // Output: Symbol 'identifier3' does not exist in scope 'namespace1'.
    std::cout << manager.checkSymbol("namespace2", "identifier3") << std::endl;  // Output: Symbol 'identifier3' exists in scope 'namespace2'.

    return 0;
}

