// Scale a polygon to fit within the target dimensions using linear interpolation
QPolygonF EFXPreviewArea::scale(const QPolygonF& poly, const QSize& target)
{
    QPolygonF result;

    // Iterate through each point in the input polygon
    for (int index = 0; index < poly.size(); ++index)
    {
        QPointF point = poly.at(index);

        // Apply scaling transformation to x-coordinate
        qreal scaledX = SCALE(qreal(point.x()), qreal(0), qreal(255), qreal(0), qreal(target.width()));

        // Apply scaling transformation to y-coordinate  
        qreal scaledY = SCALE(qreal(point.y()), qreal(0), qreal(255), qreal(0), qreal(target.height()));

        // Create new scaled point and add to result
        QPointF newPoint(scaledX, scaledY);
        result << newPoint;
    }

    return result;
}

