// Load a PNG image from an input stream and return it as a Bitmap object
Bitmap LoadPNG(std::istream& stream)
{
    // Read entire stream into a string buffer
    std::string raw_data((std::istreambuf_iterator<char>(stream)), std::istreambuf_iterator<char>());

    // Prepare output buffer for decoded pixel data
    std::vector<unsigned char> pixel_data;
    unsigned long img_width = 0, img_height = 0;

    // Decode PNG using PicoPNG library
    int decode_result = decodePNG(pixel_data, img_width, img_height, 
                                  reinterpret_cast<const unsigned char*>(raw_data.c_str()), 
                                  raw_data.size());

    // Check for decoding errors
    if (decode_result != 0) {
        Log::Error("Failed to decode PNG: error code " + std::to_string(decode_result));
        return Bitmap(); // Return default-constructed (empty) bitmap
    }

    // Create bitmap with decoded dimensions
    Bitmap result_bitmap(img_width, img_height);

    // Iterate through each pixel in the decoded image
    for (unsigned long row = 0; row < img_height; ++row) {
        for (unsigned long col = 0; col < img_width; ++col) {
            // Calculate position in the flat pixel array (RGBA format)
            size_t index = (row * img_width + col) * 4;

            // Extract color components and create Color object
            Color pixel_color(pixel_data[index], 
                             pixel_data[index + 1], 
                             pixel_data[index + 2], 
                             pixel_data[index + 3]);

            // Set pixel in the bitmap
            result_bitmap.SetPixel(col, row, pixel_color);
        }
    }

    return result_bitmap;
}

