// Perform arithmetic operations on two numbers based on the given operator
double PerformOperation(double first, double second, char operation) {
    switch (operation) {
        case '+':
            return first + second;
        case '-':
            return first - second;
        case '*':
            return first * second;
        case '/':
            if (second != 0.0) {
                return first / second;
            } else {
                std::cerr << "Error: Division by zero" << std::endl;
                return 0.0;  // Return 0 for division by zero
            }
        default:
            std::cerr << "Error: Invalid operator" << std::endl;
            return 0.0;  // Return 0 for invalid operator
    }
}

int main() {
