    std::cout << PerformOperation(2.0, 3.0, '+') << std::endl;  // Output: 5.0
    std::cout << PerformOperation(5.0, 2.0, '-') << std::endl;  // Output: 3.0
    std::cout << PerformOperation(4.0, 2.0, '*') << std::endl;  // Output: 8.0
    std::cout << PerformOperation(6.0, 3.0, '/') << std::endl;  // Output: 2.0
    std::cout << PerformOperation(8.0, 0.0, '/') << std::endl;  // Output: Error: Division by zero, 0.0
