float LinuxParser::CpuUtilization(int pid) {
  long activeJiffies = LinuxParser::ActiveJiffies(pid);
  long systemUptime = LinuxParser::UpTime();

  // Convert jiffies to seconds using clock ticks per second
  double totalSeconds = static_cast<double>(activeJiffies) / sysconf(_SC_CLK_TCK);

  // Calculate process runtime in seconds (current uptime minus process start time)
  double processStartTime = static_cast<double>(LinuxParser::UpTime(pid)) / sysconf(_SC_CLK_TCK);
  double runtimeSeconds = static_cast<double>(systemUptime) - processStartTime;

  // Avoid division by zero if process started very recently
  if (runtimeSeconds <= 0.0) {
    return 0.0f;
  }

  // Get number of online processors for normalization
  long numProcessors = sysconf(_SC_NPROCESSORS_ONLN);

  // Compute CPU utilization as percentage: (process CPU time / runtime) * 100 / #processors
  float cpuUtilization = static_cast<float>((totalSeconds / runtimeSeconds) * 100.0 / numProcessors);

  return cpuUtilization;
}

