// Returns the intersection of two string vectors, preserving duplicates up to their count in vec1
std::vector<std::string> getCommonElements(const std::vector<std::string>& inputA, const std::vector<std::string>& inputB) {
    std::unordered_map<std::string, int> frequencyTable;
    std::vector<std::string> outputList;

    // Record how many times each string appears in the first vector
    for (const std::string& item : inputA) {
        frequencyTable[item]++;
    }

    // Check against second vector and add matches while respecting frequency limits
    for (const std::string& candidate : inputB) {
        if (frequencyTable[candidate] > 0) {
            outputList.push_back(candidate);
            frequencyTable[candidate]--;
        }
    }

    return outputList;
}

