            m_context.m_buffer = std::make_shared<ByteBlock>(
                m_buffer.begin(), m_buffer.begin() + static_cast<std::ptrdiff_t>(numBytes));

            LOGGER_DEBUG("Bytes received: ", *m_context.m_buffer);

            // Construct HIP packet from the received data
            m_context.m_packet = HipPacketPtr(new HipPacket(*m_context.m_buffer));

            // Extract source and destination addresses from the packet
            std::string srcAddr = m_context.m_packet->GetSourceAddress();
            std::string dstAddr = m_context.m_packet->GetDestinationAddress();

