// Insert a new material into the scene at a given position
bool insertMaterial(aiScene* scene, int position, Material newMaterial) {
    if (position >= 0 && position <= scene->mNumMaterials) {
        // Move materials from the end to create space for insertion
        for (int j = scene->mNumMaterials - 1; j >= position; --j) {
            scene->mMaterials[j + 1] = scene->mMaterials[j];
        }
        // Place the new material at the desired location
        scene->mMaterials[position] = newMaterial;
        ++(scene->mNumMaterials);  // Increase the count of materials
        return true;  // Successfully inserted
    }
    return false;  // Position is invalid
}

