    // Determine maximum and minimum values
    int largest = *std::max_element(values.begin(), values.end());
    int smallest = *std::min_element(values.begin(), values.end());

    // Sort the numbers in ascending order
    std::sort(values.begin(), values.end());

    // Display results
    std::cout << "Generated random numbers: ";
    for (int value : values) {
        std::cout << value << " ";
    }
    std::cout << "\nTotal sum: " << total << std::endl;
    std::cout << "Largest number: " << largest << std::endl;
    std::cout << "Smallest number: " << smallest << std::endl;

    return 0;
}

