class OpenGLIndexBuffer {
public:
    // Constructor: initializes the index buffer with provided data
    OpenGLIndexBuffer(uint32_t* indices, uint32_t count) {
        glGenBuffers(1, &mBufferID);
        glBindBuffer(GL_ELEMENT_ARRAY_BUFFER, mBufferID);
        glBufferData(GL_ELEMENT_ARRAY_BUFFER, count * sizeof(uint32_t), indices, GL_STATIC_DRAW);
        mElementCount = count;
    }

    // Destructor: cleans up GPU resources
    ~OpenGLIndexBuffer() {
        glDeleteBuffers(1, &mBufferID);
    }

    // Binds the index buffer for rendering operations
    void bind() const {
        glBindBuffer(GL_ELEMENT_ARRAY_BUFFER, mBufferID);
    }

    // Returns the number of indices stored in this buffer
    uint32_t getElementCount() const {
        return mElementCount;
    }

private:
    uint32_t mBufferID;      // OpenGL buffer object identifier
    uint32_t mElementCount;  // Number of indices in the buffer
};

