std::vector<char> determineConfigEnumValueNamesZeroSeparated(const char *stringizedMacroVarags)
{
    std::vector<char> resultBuffer;

    // Get the individual enum value names
    std::vector<std::string> namesList = determineConfigEnumValueNames(stringizedMacroVarags);

    // Calculate total size needed for the buffer
    size_t totalSize = 0;
    for (const auto& name : namesList) {
        totalSize += name.length() + 1; // +1 for null terminator
    }
    resultBuffer.reserve(totalSize);

    // Process each name and add null separators
    bool firstEntry = true;
    for (const auto& itemName : namesList) {
        if (!firstEntry) {
