// Custom delegate class to bind objects and methods
template<typename T>
class Delegate {
public:
    using Callback = std::function<void(T)>;

    Delegate() : obj(nullptr), callback(nullptr) {}

    template<typename ObjType, typename Method>
    Delegate(ObjType* o, Method m) : obj(o), callback([m, o](T arg) { (o->*m)(arg); }) {}

    void operator()(T arg) const {
        if (callback) callback(arg);
    }

    bool isValid() const { return callback != nullptr; }

private:
    void* obj;
    Callback callback;
};

// Event class template with simplified interface
template <typename T>
class SimpleEvent {
public:
    void subscribe(const Delegate<T>& del) {
        if (del.isValid()) {
            delegates.push_back(del);
        }
    }

    void unsubscribe(const Delegate<T>& del) {
        for (auto it = delegates.begin(); it != delegates.end(); ++it) {
            if (it->isValid() && del.isValid()) {
                // Simple comparison by checking if both have same callback logic
                // In real implementation would need better comparison mechanism
                delegates.erase(it);
                break;
            }
        }
    }

    void trigger(const T& value) {
        for (const auto& del : delegates) {
            if (del.isValid()) {
                del(value);
            }
        }
    }

private:
    std::vector<Delegate<T>> delegates;
};

