// Custom exception class that formats the message before throwing
class RuntimeError : public std::runtime_error {
public:
    RuntimeError(const std::string& base_msg, int code) 
        : std::runtime_error(formatMessage(base_msg, code)) {}
private:
    static std::string formatMessage(const std::string& msg, int code) {
        std::ostringstream oss;
        oss << msg;
        std::string result = oss.str();
        size_t marker = result.find("error={}");
        if (marker != std::string::npos) {
            result.replace(marker, 8, "error=" + std::to_string(code));
        }
        return result;
    }
};

