namespace quadrants::lang {

// Substitute every occurrence of statement A with statement B.
// The original statement A remains unchanged in the IR tree.
class StatementOperandSubstitutor : public IRVisitor {
  // We avoid BasicStmtVisitor to prevent descending into FrontendForStmt nodes.
 public:
  Stmt *target_old, *replacement_new;

  StatementOperandSubstitutor(Stmt *old_stmt, Stmt *new_stmt)
      : target_old(old_stmt), replacement_new(new_stmt) {
    allow_undefined_visitor = true;
    invoke_default_visitor = true;
  }

  void visit(Stmt *stmt) override {
    stmt->replace_operand_with(target_old, replacement_new);
  }

  void visit(WhileStmt *loop) override {
    loop->replace_operand_with(target_old, replacement_new);
    loop->body->accept(this);
  }

  void visit(IfStmt *conditional) override {
    conditional->replace_operand_with(target_old, replacement_new);
    if (conditional->true_statements)
      conditional->true_statements->accept(this);
    if (conditional->false_statements)
      conditional->false_statements->accept(this);
  }

  void visit(Block *block) override {
    for (auto &stmt : block->statements) {
      stmt->accept(this);
    }
  }

  void visit(RangeForStmt *range_loop) override {
    range_loop->replace_operand_with(target_old, replacement_new);
    range_loop->body->accept(this);
  }

  void visit(StructForStmt *struct_loop) override {
    struct_loop->body->accept(this);
  }

  void visit(MeshForStmt *mesh_loop) override {
    mesh_loop->body->accept(this);
  }

  void visit(OffloadedStmt *offload) override {
    offload->all_blocks_accept(this);
  }

  static void execute(IRNode *root, Stmt *old_stmt, Stmt *new_stmt) {
    StatementOperandSubstitutor substitutor(old_stmt, new_stmt);

    if (root != nullptr) {
      // If a specific root is given, traverse only that subtree.
      root->accept(&substitutor);
      return;
    }

    // Process statements within the immediate parent of old_stmt
    QD_ASSERT(old_stmt->parent != nullptr);
    old_stmt->parent->accept(&substitutor);

    // Propagate changes upward through enclosing blocks
    auto current_block = old_stmt->parent->parent_block();
    while (current_block != nullptr) {
      for (auto &stmt : current_block->statements) {
        stmt->replace_operand_with(old_stmt, new_stmt);
      }
      current_block = current_block->parent_block();
    }
  }
};

namespace irpass {
void replace_all_usages_with(IRNode *root, Stmt *old_stmt, Stmt *new_stmt) {
  QD_AUTO_PROF;
  StatementOperandSubstitutor::execute(root, old_stmt, new_stmt);
}
}  // namespace irpass
}  // namespace quadrants::lang

