namespace examples {

// Parse a key=value string into the TXT record; returns true if successful
bool parse_txt_entry(rav::dnssd::TxtRecord& record, const std::string& input) {
    if (input.empty()) return false;

    auto eq_pos = input.find('=');
    if (eq_pos != std::string::npos) {
        record[input.substr(0, eq_pos)] = input.substr(eq_pos + 1);
    } else {
        // If no '=', treat entire string as key with empty value
        record[input] = "";
    }
    return true;
}

}  // namespace examples

int main(int argc, char* argv[]) {
    rav::set_log_level_from_env();
    rav::do_system_checks();

    std::vector<std::string> arguments;
    for (int idx = 1; idx < argc; ++idx) {
        arguments.emplace_back(argv[idx]);
    }

    // Validate minimum required arguments: service type and port
    if (arguments.size() < 2) {
        std::cerr << "Usage: <service_type> <port> [key=value ...]" << std::endl;
        return -1;
    }

    // Extract and validate port number
    int raw_port = 0;
    try {
        raw_port = std::stoi(arguments[1]);
    } catch (...) {
        std::cerr << "Error: invalid port '" << arguments[1] << "'" << std::endl;
        return -1;
    }

    // Build TXT record from remaining arguments
    rav::dnssd::TxtRecord txt_data;
    for (size_t i = 2; i < arguments.size(); ++i) {
        examples::parse_txt_entry(txt_data, arguments[i]);
    }

    boost::asio::io_context ctx;
    auto advertiser_opt = rav::dnssd::Advertiser::create(ctx);
    if (!advertiser_opt) {
        RAV_LOG_ERROR("No DNS-SD advertiser available on this platform");
        return -1;
    }

    auto& advertiser = *advertiser_opt;

    // Set up callbacks
    advertiser.on_error = [](const std::string& msg) {
        RAV_LOG_ERROR("DNS-SD error: {}", msg);
    };

    advertiser.on_name_conflict = [](const char* type, const char* name) {
        RAV_LOG_CRITICAL("Name conflict detected: {} / {}", type, name);
    };

    // Register service
    auto service_handle = advertiser.register_service(
        arguments[0],
        "Example service",
        nullptr,
        static_cast<uint16_t>(raw_port),
        txt_data,
        true,
        true
    );

    // Run IO context in background thread
    std::thread worker([&ctx] {
        ctx.run();
    });

    RAV_LOG_INFO("Ready — enter 'key=value' to update TXT, 'r' to reset, or 'q' to quit");

    std::string line;
    while (true) {
        std::getline(std::cin, line);
        if (line == "q" || line == "Q") break;

        if (line == "r" || line == "R") {
            advertiser.unregister_service(service_handle);
            continue;
        }

        try {
            if (examples::parse_txt_entry(txt_data, line)) {
                // Post update to io_context thread for safety
                boost::asio::post(ctx, [&advertiser, &txt_data, service_handle]() {
                    advertiser.update_txt_record(service_handle, txt_data);
                    RAV_LOG_INFO("TXT record updated");
                });
            }
        } catch (const std::exception& ex) {
            RAV_LOG_ERROR("Exception during TXT update: {}", ex.what());
        }
    }

    ctx.stop();
    worker.join();
    std::cout << "Terminated." << std::endl;
    return 0;
}

