// Use long double for improved numerical stability
using LD = long double;

// Computes log(sum(exp(x_i))) in a numerically stable manner
LD log_sum_exp_stable(const std::vector<LD>& values) {
    if (values.empty()) {
        return -std::numeric_limits<LD>::infinity();
    }

    // Find the maximum value to avoid overflow
    LD max_val = values[0];
    for (const auto& v : values) {
        if (v > max_val) {
            max_val = v;
        }
    }

    // Compute sum of exponentials relative to max_val
    LD adjusted_sum = 0.0L;
    for (const auto& v : values) {
        adjusted_sum += expl(v - max_val);
    }

    // Return log of sum: max + log(sum(exp(x_i - max)))
    return max_val + logl(adjusted_sum);
}

int main() {
    // Optimize I/O performance
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int num_experts, num_rounds;
    std::cin >> num_experts >> num_rounds;

    // Initialize all weights to 1 (log(1) = 0)
    std::vector<LD> expert_weights(num_experts, 0.0L);

    const LD learning_rate = 0.5L;
    const LD log_learning_rate = logl(learning_rate);

    for (int round = 0; round < num_rounds; ++round) {
        std::string expert_predictions;
        std::cin >> expert_predictions;

        // Partition experts by their predictions
        std::vector<LD> zero_group, one_group;
        for (int i = 0; i < num_experts; ++i) {
            if (expert_predictions[i] == '0') {
                zero_group.push_back(expert_weights[i]);
            } else {
                one_group.push_back(expert_weights[i]);
            }
        }

        // Compute aggregated log-weights for each prediction group
        LD log_total_zero = log_sum_exp_stable(zero_group);
        LD log_total_one = log_sum_exp_stable(one_group);

        // Make prediction: prefer '0' on ties
        char predicted_outcome = (log_total_zero >= log_total_one) ? '0' : '1';
        std::cout << predicted_outcome << '\n';

        // Read actual outcome
        char actual_outcome;
        std::cin >> actual_outcome;

        // Update weights: multiply by eta for incorrect predictions
        for (int i = 0; i < num_experts; ++i) {
            if (expert_predictions[i] != actual_outcome) {
                expert_weights[i] += log_learning_rate;
            }
        }
    }

    return 0;
}

#include <iostream>
#include <algorithm>
#include <vector>
using namespace std;

// Leetcode 2099. Find Subsequence of Length K With the Largest Sum
class Solution {
public:
    vector<int> maxSubsequence(vector<int>& nums, int k) {
        // Create a list of pairs containing value and original index
        vector<pair<int, int>> indexedValues;
        for (int idx = 0; idx < nums.size(); ++idx) {
            indexedValues.push_back({nums[idx], idx});
        }

        // Sort by value in descending order to find largest elements
        sort(indexedValues.begin(), indexedValues.end(), 
             [](const pair<int, int>& x, const pair<int, int>& y) {
                 return x.first > y.first;
             });

        // Select the top k elements
        vector<pair<int, int>> topK(indexedValues.begin(), indexedValues.begin() + k);

        // Reorder selected elements by their original positions to preserve subsequence order
        sort(topK.begin(), topK.end(),
             [](const pair<int, int>& x, const pair<int, int>& y) {
                 return x.second < y.second;
             });

        // Extract values from the ordered pairs to form the result
        vector<int> output;
        for (const auto& element : topK) {
            output.push_back(element.first);
        }

        return output;
    }
};

