// Custom job implementation for deterministic simulation execution
class SimulationJob : public rslcpp::Job
{
public:
  // Override to provide exit status upon job termination
  std::uint8_t get_exit_code() override { return termination_code_; }

  // Indicate whether the simulation has completed
  bool is_complete() override { return completed_; }

  // Specify the starting time for the simulation (ROS time)
  rclcpp::Time get_initial_time() override { return rclcpp::Time(10, 0, RCL_ROS_TIME); }

  // Construct and configure nodes required for the simulation
  std::vector<rclcpp::Node::SharedPtr> create_and_get_nodes() override
  {
    rclcpp::NodeOptions config;
    config.use_intra_process_comms(true);

    // Instantiate communication components
    auto tx_node = std::make_shared<CommunicationDelaySender>(config);
    auto rx_node = std::make_shared<ReceiverNode>(config);

    // Setup monitoring node with timeout logic
    auto watcher_node = std::make_shared<rslcpp::helper_nodes::SimulationMonitor>(
      [this](rslcpp::exit_code_t code) {
        completed_ = true;
        termination_code_ = code;
      },
      config);

    watcher_node->set_parameter(rclcpp::Parameter("timeout_s", 100));

    // Return all active nodes
    return {tx_node, watcher_node, rx_node};
  }

private:
  bool completed_ = false;
  rslcpp::exit_code_t termination_code_ = 0;
};

// Entry point for running the deterministic simulation
int main(int argc, char ** argv)
{
  auto job_instance = std::make_shared<SimulationJob>();
  auto result = rslcpp::run_job(argc, argv, job_instance);

  std::cout << "RSLCPP simulation completed with exit code: "
            << static_cast<int>(result) << std::endl;

  return 0;
}

