#include <iostream>
#include <stack>
#include <string>

class Solution {
public:
    bool isValid(std::string str) {
        int length = str.length();
        if (length % 2 != 0) return false;

        std::stack<char> stack;
        for (char ch : str) {
            if (ch == '(' || ch == '[' || ch == '{') {
                stack.push(ch);
            } else {
                if (stack.empty()) return false;

                char topChar = stack.top();
                if ((topChar == '(' && ch == ')') ||
                    (topChar == '[' && ch == ']') ||
                    (topChar == '{' && ch == '}')) {
                    stack.pop();
                } else {
                    return false;
                }
            }
        }
        return stack.empty();
    }
};

#include <iostream>
#include <vector>
#include <string>
#include <random>
#include <iomanip>

// Use a fixed seed for deterministic behavior of the randomized algorithm
std::mt19937 rng(42);

void solve() {
    int n, m;
    std::cin >> n >> m;

    // Initialize weights and error counts for each expert
    std::vector<long double> expert_weights(n, 1.0L);
    std::vector<int> expert_errors(n, 0);

    for (int round = 0; round < m; ++round) {
        std::string predictions;
        std::cin >> predictions;

        int predicted_outcome;

        // Check if any expert has zero errors so far
        bool has_perfect_expert = false;
        for (int i = 0; i < n; ++i) {
            if (expert_errors[i] == 0) {
                has_perfect_expert = true;
                break;
            }
        }

        if (has_perfect_expert) {
            // Follow the first perfect expert's prediction
            for (int i = 0; i < n; ++i) {
                if (expert_errors[i] == 0) {
                    predicted_outcome = (predictions[i] == '1') ? 1 : 0;
                    break;
                }
            }
        } else {
            // Compute weighted votes for outcome 0 and 1
            long double weight_for_zero = 0.0L;
            long double weight_for_one = 0.0L;

            for (int i = 0; i < n; ++i) {
                if (predictions[i] == '0') {
                    weight_for_zero += expert_weights[i];
                } else {
                    weight_for_one += expert_weights[i];
                }
            }

            long double total_weight = weight_for_zero + weight_for_one;

            if (total_weight == 0.0L) {
                predicted_outcome = 0; // fallback guess
            } else {
                long double probability_one = weight_for_one / total_weight;
                std::uniform_real_distribution<long double> distribution(0.0L, 1.0L);

                if (distribution(rng) < probability_one) {
                    predicted_outcome = 1;
                } else {
                    predicted_outcome = 0;
                }
            }
        }

        std::cout << predicted_outcome << std::endl;

        int actual_result;
        std::cin >> actual_result;

        // Update experts' weights and error counts
        for (int i = 0; i < n; ++i) {
            int expert_prediction = (predictions[i] == '1') ? 1 : 0;
            if (expert_prediction != actual_result) {
                expert_errors[i]++;
                expert_weights[i] *= 0.5L;
            }
        }
    }
}

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);
    solve();
    return 0;
}

