#include <asio.hpp>
#include <ctime>
#include <chrono>
#include <iostream>

// Custom clock implementation based on std::time_t, aligned with asio's requirements
struct system_time_clock
{
  using duration = std::chrono::steady_clock::duration;
  using rep = duration::rep;
  using period = duration::period;
  using time_point = std::chrono::time_point<system_time_clock>;

  static constexpr bool is_steady = false;

  static time_point now() noexcept
  {
    auto seconds_since_epoch = std::time(nullptr);
    return time_point{} + std::chrono::seconds(seconds_since_epoch);
  }
};

// Custom wait traits to optimize polling for low-granularity clocks
struct optimized_wait_traits
{
  // Convert a duration into an appropriate polling interval
  static system_time_clock::duration to_poll_duration(
      const system_time_clock::duration& d)
  {
    if (d > std::chrono::seconds(1))
      return d - std::chrono::seconds(1);
    else if (d > std::chrono::seconds(0))
      return std::chrono::milliseconds(50);  // More frequent polling for near timeouts
    else
      return std::chrono::seconds(0);
  }

  // Convert a time point into a polling interval
  static system_time_clock::duration to_poll_duration(
      const system_time_clock::time_point& t)
  {
    return to_poll_duration(t - system_time_clock::now());
  }
};

// Type alias for the custom timer type
using custom_timer = asio::basic_waitable_timer<
    system_time_clock, optimized_wait_traits>;

int main()
{
  try
  {
    asio::io_context ioc;
    custom_timer timer(ioc);

    // Synchronous wait demonstration
    timer.expires_after(std::chrono::seconds(5));
    std::cout << "Initiating blocking wait...\n";
    timer.wait();
    std::cout << "Blocking wait completed.\n";

    // Asynchronous wait demonstration
    timer.expires_after(std::chrono::seconds(5));
    std::cout << "Starting non-blocking wait...\n";
    timer.async_wait(
        [](const std::error_code& ec)
        {
          if (!ec) {
            std::cout << "Timer expired\n";
          }
        });
    ioc.run();
    std::cout << "Non-blocking wait finished.\n";
  }
  catch (const std::exception& ex)
  {
    std::cerr << "Error occurred: " << ex.what() << '\n';
  }

  return 0;
}

#include <iostream>
#include <queue>
using namespace std;

class MedianFinder {
public:
    // Min heap for the lower half (stores smaller numbers, using reverse logic)
    priority_queue<int> leftHeap; 
    // Max heap for the upper half (stores larger numbers)
    priority_queue<int, vector<int>, greater<int>> rightHeap;

    MedianFinder() {}

    void addNum(int value) {
        // Insert into left heap first
        leftHeap.push(value);

        // Move the largest element from left to right to maintain order
        rightHeap.push(leftHeap.top());
        leftHeap.pop();

        // Rebalance if needed: ensure left heap has at least as many elements as right heap
        if (rightHeap.size() > leftHeap.size()) {
            leftHeap.push(rightHeap.top());
            rightHeap.pop();
        }
    }

    double findMedian() {
        if (leftHeap.size() > rightHeap.size()) {
            return static_cast<double>(leftHeap.top());
        } else {
            return (static_cast<double>(leftHeap.top()) + rightHeap.top()) / 2.0;
        }
    }
};

#include <array>
#include <cstdio>
#include <iostream>
#include <memory>
#include "asio.hpp"

#if defined(ASIO_HAS_LOCAL_SOCKETS)
using asio::local::stream_protocol;

// Session class handles communication with a connected client
class session
  : public std::enable_shared_from_this<session>
{
public:
  explicit session(stream_protocol::socket sock)
    : socket_(std::move(sock))
  {
  }

  void begin()
  {
    initiate_read();
  }

private:
  void initiate_read()
  {
    auto self(shared_from_this());
    socket_.async_read_some(asio::buffer(buffer_),
        [this, self](const std::error_code& error, std::size_t bytes_transferred)
        {
          if (!error)
            send_response(bytes_transferred);
        });
  }

  void send_response(std::size_t size)
  {
    auto self(shared_from_this());
    asio::async_write(socket_,
        asio::buffer(buffer_, size),
        [this, self](const std::error_code& error, std::size_t /*bytes_written*/)
        {
          if (!error)
            initiate_read();
        });
  }

  // Socket for client communication
  stream_protocol::socket socket_;
  // Data buffer for incoming/outgoing messages
  std::array<char, 1024> buffer_;
};

// Server class manages incoming connections
class server
{
public:
  server(asio::io_context& context, const std::string& path)
    : acceptor_(context, stream_protocol::endpoint(path))
  {
    await_connection();
  }

private:
  void await_connection()
  {
    acceptor_.async_accept(
        [this](const std::error_code& error, stream_protocol::socket socket)
        {
          if (!error)
          {
            std::make_shared<session>(std::move(socket))->begin();
          }
          await_connection();
        });
  }

  stream_protocol::acceptor acceptor_;
};

int main(int argc, char* argv[])
{
  try
  {
    if (argc != 2)
    {
      std::cerr << "Usage: stream_server <file>\n";
      std::cerr << "*** WARNING: existing file is removed ***\n";
      return 1;
    }

    asio::io_context io_context;
    std::remove(argv[1]);
    server instance(io_context, argv[1]);
    io_context.run();
  }
  catch (const std::exception& exception)
  {
    std::cerr << "Error: " << exception.what() << "\n";
  }

  return 0;
