// Helper function to send a command with stone position, side, and exit passage
void issue_command(int stone_pos, const std::string& direction, int exit_passage) {
    std::cout << stone_pos << " " << direction << " " << exit_passage << std::endl;
}

int main() {
    // Optimize I/O operations
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int m;
    std::cin >> m;
    int visited_count = 0;

    while (true) {
        std::string input;
        std::cin >> input;

        if (input == "treasure") {
            break;
        }

        if (input == "center") {
            // New unvisited chamber encountered
            int chamber_id = visited_count;

            std::string chosen_side;
            if ((chamber_id / m) % 2 == 0) {
                chosen_side = "left";
            } else {
                chosen_side = "right";
            }

            int offset = chamber_id % m;
            // Command: place stone at offset from reference, exit via passage 0
            issue_command(offset, chosen_side, 0);
            visited_count++;
        } else {
            // Previously seen chamber ("left" or "right")
            // Advance stone by one passage in the specified direction and exit there
            issue_command(1, input, 1);
        }
    }

    return 0;
}

