namespace Karm::Scene {

export struct Image : Node {
    Math::Rectf _bounds;
    Rc<Gfx::Surface> _imgSurface;
    Math::Radiif _corners;

    Image(Math::Rectf bounds, Rc<Gfx::Surface> imgSurface, Math::Radiif corners = {})
        : _bounds(bounds), _imgSurface(imgSurface), _corners(corners) {
    }

    Math::Rectf bound() override {
        return _bounds;
    }

    void paint(Gfx::Canvas& ctx, Math::Rectf clip, PaintOptions) override {
        if (not clip.intersects(_bounds))
            return;

        if (not _corners.empty()) {
            ctx.fillStyle(_imgSurface->pixels());
            ctx.fill(_bounds, _corners);
        } else {
            ctx.blit(_bounds.cast<isize>(), _imgSurface->pixels());
        }
    }

    void repr(Io::Emit& e) const override {
        e("(image z:{})", zIndex);
    }
};

