// Helper function to perform query and handle errors
int ask(int x, int y) {
    std::cout << "? " << x << " " << y << std::endl;
    int response;
    std::cin >> response;
    if (response == -1) {
        std::exit(0);
    }
    return response;
}

int main() {
    // Optimize I/O operations
    std::ios::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int size;
    std::cin >> size;

    std::vector<int> orResults(size + 1);

    // Query first element with all others
    for (int idx = 2; idx <= size; ++idx) {
        orResults[idx] = ask(1, idx);
    }

    // Find p[1] by computing the minimum of all OR results
    // Since one of the elements must be 0, p[1]|0 = p[1], which will be the minimum
    int firstElement = INT_MAX;
    for (int idx = 2; idx <= size; ++idx) {
        if (orResults[idx] < firstElement) {
            firstElement = orResults[idx];
        }
    }

    // Handle edge case when n=1
    if (size == 1) {
        firstElement = 0;
    }

    // Reconstruct the permutation
    std::vector<int> permutation(size + 1);
    permutation[1] = firstElement;

    for (int idx = 2; idx <= size; ++idx) {
        // For each position, the value is the OR result with first element
        // But we need to find the actual value: since we know firstElement,
        // and firstElement | permutation[idx] = orResults[idx],
        // we can compute permutation[idx] = orResults[idx] ^ (firstElement & orResults[idx])
        // However, the simpler approach works because of the permutation property
        permutation[idx] = orResults[idx];
    }

    // Output the answer
    std::cout << "!";
    for (int idx = 1; idx <= size; ++idx) {
        std::cout << " " << permutation[idx];
    }
    std::cout << std::endl;

    return 0;
}

#include <cstdint>
#include <generic/arch.hpp>
#include <arch/riscv64/features.hpp>

namespace arch {
    [[gnu::weak]] void disable_interrupts() {
        // Clear the SIE bit (bit 1) in sstatus register
        asm volatile("csrc sstatus, %0" : : "r"(0x2)); 
    }

    [[gnu::weak]] void enable_interrupts() {
        // Set the SIE bit (bit 1) in sstatus register
        asm volatile("csrs sstatus, %0" : : "r"(0x2));
    }

    [[gnu::weak]] void wait_for_interrupt() {
        // Wait for interrupt instruction
        asm volatile("wfi"); 
    }

    [[gnu::weak]] void hcf() {
        disable_interrupts();
        for (;;) {
            wait_for_interrupt();
        }
    }

    [[gnu::weak]] void pause() {
#ifdef __riscv_zihintpause
        // Use hint instruction if available
        asm volatile("pause");
#else
        // Fallback to no operation
        asm volatile("nop");
#endif
    }

    [[gnu::weak]] void tlb_flush(std::uintptr_t addr_hint, std::uintptr_t size) {
        // Determine if bulk flush is more efficient than per-page flush
        if (size / PAGE_SIZE > 256 || size == 0) {
            // Flush entire TLB
            asm volatile("sfence.vma");
        } else {
            // Flush specific pages incrementally
            for (std::uintptr_t offset = 0; offset < size; offset += PAGE_SIZE) {
                asm volatile("sfence.vma %0" : : "r"(addr_hint + offset) : "memory");
            }
        }
    }

    [[gnu::weak]] const char* architecture_name() {
        return "riscv64";
    }

    [[gnu::weak]] int get_paging_depth() {
        return riscv64::get_paging_level();
    }

    [[gnu::weak]] void initialize(int phase) {
        (void)phase;
    }
}

