class Solution {
public:
    int maximum69Number(int num) {
        int divisor = 1000;
        int temp = num;

        // Scan from left to right to find the first '6'
        while (divisor > 0) {
            int digit = (temp / divisor) % 10;
            if (digit == 6) {
                break;
            }
            divisor /= 10;
        }

        return num + 3 * divisor;
    }
};

