// LeetCode 56: Merge Intervals - Type III Clone
// Given a collection of intervals, merge all overlapping intervals.
class Solution {
public:
    vector<vector<int>> merge(vector<vector<int>>& intervals) {
        vector<vector<int>> merged;
        if (intervals.empty()) return merged;

        // Sort intervals by start time
        sort(intervals.begin(), intervals.end(), 
             [](const vector<int>& a, const vector<int>& b) {
                 return a[0] < b[0];
             });

        // Process each interval
        for (int idx = 0; idx < intervals.size(); ++idx) {
            // If no overlap or first interval, add directly
            if (merged.empty() || intervals[idx][0] > merged.back()[1]) {
                merged.push_back(intervals[idx]);
            } else {
                // Overlap exists: update end time to maximum
                merged.back()[1] = max(merged.back()[1], intervals[idx][1]);
            }
        }

        return merged;
    }
};

