void ThrownEnderpearl::onCollision(HitResult *hit)
{
	if (nullptr != hit->targetEntity)
	{
		DamageSource *src = DamageSource::thrown(shared_from_this(), getThrower());
		hit->targetEntity->takeDamage(src, 0);
		delete src;
	}

	// Emit visual particles
	for (int idx = 0; idx < 32; ++idx)
	{
		double offsetX = random->nextGaussian();
		double offsetY = random->nextDouble() * 2.0;
		double offsetZ = random->nextGaussian();
		level->spawnParticle(eParticleType_ender, x, y + offsetY, z, offsetX, 0.0, offsetZ);
	}

	if (!level->isRemote())
	{
		LivingEntity *owner = getThrower();
		if (nullptr != owner)
		{
			// Early exit if owner no longer valid
			if (owner->getTypeID() == eTYPE_SERVERPLAYER)
			{
				ServerPlayer *player = static_cast<ServerPlayer*>(owner);
				if (!player->isMarkedForRemoval())
				{
					PlayerConnection *conn = player->getConnection();
					if (conn && conn->isFullyConnected() && player->getWorld() == level)
					{
						// Cancel any vehicle mount before teleporting
						if (player->hasVehicle())
						{
							player->dismountVehicle();
						}
						// Teleport to impact point
						player->moveTo(x, y, z);
						player->resetFallDistance();
						// Apply fall damage
						DamageSource *fallDmg = DamageSource::fall;
						player->takeDamage(fallDmg, 5);
						delete fallDmg;
					}
				}
			}
		}
		destroy(); // Mark entity for removal
	}
}

#include <iostream>
#ifdef __SSE__
#include "svd3x3_sse.h"
#include <cmath>
#include <algorithm>
#undef USE_SCALAR_IMPLEMENTATION
#define USE_SSE_IMPLEMENTATION
#undef USE_AVX_IMPLEMENTATION
#define COMPUTE_U_AS_MATRIX
#define COMPUTE_V_AS_MATRIX
#include "Singular_Value_Decomposition_Preamble.hpp"
#pragma runtime_checks( "u", off )  

template<typename T>
IGL_INLINE void igl::svd3x3_sse(
  const Eigen::Matrix<T, 3*4, 3>& A, 
  Eigen::Matrix<T, 3*4, 3> &U, 
  Eigen::Matrix<T, 3*4, 1> &S, 
  Eigen::Matrix<T, 3*4, 3>&V)
{
  // Prepare temporary buffers for shuffling matrix entries across SIMD lanes
  float Ashuffle[9][4], Ushuffle[9][4], Vshuffle[9][4], Sshuffle[3][4];

  // Flatten and transpose A into Ashuffle: A[row + 3*col] -> Ashuffle[col*3 + row][lane]
  int idx = 0;
  while (idx < 9) {
    int col = idx / 3;
    int row = idx % 3;
    int lane = 0;
    while (lane < 4) {
      Ashuffle[idx][lane] = A(row + 3 * lane, col);
      ++lane;
    }
    ++idx;
  }

#include "Singular_Value_Decomposition_Kernel_Declarations.hpp"

  // Load data into SSE registers
  ENABLE_SSE_IMPLEMENTATION(Va11=_mm_loadu_ps(&Ashuffle[0][0]);)
  ENABLE_SSE_IMPLEMENTATION(Va21=_mm_loadu_ps(&Ashuffle[1][0]);)
  ENABLE_SSE_IMPLEMENTATION(Va31=_mm_loadu_ps(&Ashuffle[2][0]);)
  ENABLE_SSE_IMPLEMENTATION(Va12=_mm_loadu_ps(&Ashuffle[3][0]);)
  ENABLE_SSE_IMPLEMENTATION(Va22=_mm_loadu_ps(&Ashuffle[4][0]);)
  ENABLE_SSE_IMPLEMENTATION(Va32=_mm_loadu_ps(&Ashuffle[5][0]);)
  ENABLE_SSE_IMPLEMENTATION(Va13=_mm_loadu_ps(&Ashuffle[6][0]);)
  ENABLE_SSE_IMPLEMENTATION(Va23=_mm_loadu_ps(&Ashuffle[7][0]);)
  ENABLE_SSE_IMPLEMENTATION(Va33=_mm_loadu_ps(&Ashuffle[8][0]);)

#include "Singular_Value_Decomposition_Main_Kernel_Body.hpp"

  // Store results back from SSE registers
  ENABLE_SSE_IMPLEMENTATION(_mm_storeu_ps(&Ushuffle[0][0],Vu11);)
  ENABLE_SSE_IMPLEMENTATION(_mm_storeu_ps(&Ushuffle[1][0],Vu21);)
  ENABLE_SSE_IMPLEMENTATION(_mm_storeu_ps(&Ushuffle[2][0],Vu31);)
  ENABLE_SSE_IMPLEMENTATION(_mm_storeu_ps(&Ushuffle[3][0],Vu12);)
  ENABLE_SSE_IMPLEMENTATION(_mm_storeu_ps(&Ushuffle[4][0],Vu22);)
  ENABLE_SSE_IMPLEMENTATION(_mm_storeu_ps(&Ushuffle[5][0],Vu32);)
  ENABLE_SSE_IMPLEMENTATION(_mm_storeu_ps(&Ushuffle[6][0],Vu13);)
  ENABLE_SSE_IMPLEMENTATION(_mm_storeu_ps(&Ushuffle[7][0],Vu23);)
  ENABLE_SSE_IMPLEMENTATION(_mm_storeu_ps(&Ushuffle[8][0],Vu33);)

  ENABLE_SSE_IMPLEMENTATION(_mm_storeu_ps(&Vshuffle[0][0],Vv11);)
  ENABLE_SSE_IMPLEMENTATION(_mm_storeu_ps(&Vshuffle[1][0],Vv21);)
  ENABLE_SSE_IMPLEMENTATION(_mm_storeu_ps(&Vshuffle[2][0],Vv31);)
  ENABLE_SSE_IMPLEMENTATION(_mm_storeu_ps(&Vshuffle[3][0],Vv12);)
  ENABLE_SSE_IMPLEMENTATION(_mm_storeu_ps(&Vshuffle[4][0],Vv22);)
  ENABLE_SSE_IMPLEMENTATION(_mm_storeu_ps(&Vshuffle[5][0],Vv32);)
  ENABLE_SSE_IMPLEMENTATION(_mm_storeu_ps(&Vshuffle[6][0],Vv13);)
  ENABLE_SSE_IMPLEMENTATION(_mm_storeu_ps(&Vshuffle[7][0],Vv23);)
  ENABLE_SSE_IMPLEMENTATION(_mm_storeu_ps(&Vshuffle[8][0],Vv33);)

  ENABLE_SSE_IMPLEMENTATION(_mm_storeu_ps(&Sshuffle[0][0],Va11);)
  ENABLE_SSE_IMPLEMENTATION(_mm_storeu_ps(&Sshuffle[1][0],Va22);)
  ENABLE_SSE_IMPLEMENTATION(_mm_storeu_ps(&Sshuffle[2][0],Va33);)

  // Unshuffle U and V back into output matrices
  int out_idx = 0;
  while (out_idx < 9) {
    int col = out_idx / 3;
    int row = out_idx % 3;
    int lane = 0;
    while (lane < 4) {
      U(row + 3 * lane, col) = Ushuffle[out_idx][lane];
      V(row + 3 * lane, col) = Vshuffle[out_idx][lane];
      ++lane;
    }
    ++out_idx;
  }

  // Extract diagonal singular values into S
  int s_idx = 0;
  while (s_idx < 3) {
    int lane = 0;
    while (lane < 4) {
      S(s_idx + 3 * lane, 0) = Sshuffle[s_idx][lane];
      ++lane;
    }
    ++s_idx;
  }
}

