#include <iostream>
#include <string>
#include <UniConv/UniConv.h>

int main() {
    std::cout << "=== FetchContent UniConv Demonstration ===" << std::endl;

    try {
        // Retrieve the singleton instance of UniConv
        auto converter = UniConv::GetInstance();

        // Sample UTF-8 string for testing
        std::string sample_text = "Hello UniConv! Test text with ASCII only.";
        std::cout << "Input UTF-8 string: " << sample_text << std::endl;

        // Perform fast encoding conversion from UTF-8 to GBK
        auto gbk_conversion = converter->ConvertEncodingFast(sample_text, "UTF-8", "GBK");
        if (!gbk_conversion.IsSuccess()) {
            std::cerr << "FAILED: UTF-8 to GBK conversion error: " << gbk_conversion.GetErrorMessage() << std::endl;
            return 1;
        }
        std::cout << "GBK conversion completed. Output size: " << gbk_conversion.GetValue().size() << " bytes" << std::endl;

        // Reverse the conversion: GBK back to UTF-8
        auto utf8_back = converter->ConvertEncodingFast(gbk_conversion.GetValue(), "GBK", "UTF-8");
        if (!utf8_back.IsSuccess()) {
            std::cerr << "FAILED: GBK to UTF-8 conversion error: " << utf8_back.GetErrorMessage() << std::endl;
            return 1;
        }
        std::cout << "Restored UTF-8 string: " << utf8_back.GetValue() << std::endl;

        // Validate that round-trip conversion preserved original content
        if (sample_text == utf8_back.GetValue()) {
            std::cout << "VERIFIED: Round-trip encoding conversion is accurate." << std::endl;
        } else {
            std::cerr << "MISMATCH: Round-trip conversion failed!" << std::endl;
            std::cerr << "Expected: '" << sample_text << "'" << std::endl;
            std::cerr << "Got:      '" << utf8_back.GetValue() << "'" << std::endl;
            return 1;
        }

        // Attempt to detect system's default codepage
        auto sys_codepage = converter->GetSystemCodePageFast();
        if (sys_codepage.IsSuccess()) {
            std::cout << "Detected system codepage: " << sys_codepage.GetValue() << std::endl;
        } else {
            std::cout << "Note: System codepage detection unavailable — " << sys_codepage.GetErrorMessage() << std::endl;
        }

        std::cout << std::endl << "=== FetchContent UniConv Integration Verified! ===" << std::endl;
        std::cout << "UniConv successfully integrated using FetchContent mechanism." << std::endl;

    } catch (const std::exception& ex) {
        std::cerr << "Exception caught: " << ex.what() << std::endl;
        return 1;
    }

    return 0;
}

