// ============================================================================
// Trampoline class for Python subclassing support (renamed & refactored)
// ============================================================================
class RenderPipelineHook : public RenderPipelineCallback
{
  public:
    using RenderPipelineCallback::RenderPipelineCallback;

    void Render(ScriptableRenderContext &context, const std::vector<Camera *> &cameras) override
    {
        // Attempt to invoke Python method 'render' if overridden
        py::object self = py::cast(this);
        if (self.attr("__dict__").contains("render")) {
            py::object method = self.attr("render");
            method(context, cameras);
        } else {
            PYBIND11_OVERRIDE_PURE_NAME(void, RenderPipelineCallback, "render", Render, &context, cameras);
        }
    }

    void Dispose() override
    {
        py::object self = py::cast(this);
        if (self.attr("__dict__").contains("dispose")) {
            py::object method = self.attr("dispose");
            method();
        } else {
            PYBIND11_OVERRIDE_NAME(void, RenderPipelineCallback, "dispose", Dispose);
        }
    }
};

