// ============================================================================
// Registration function (restructured for modularity)
// ============================================================================
namespace infengine {

void RegisterRenderPipelineBindings(py::module_ &m)
{
    // ---- CullingResults ----
    py::class_<CullingResults>(m, "CullingResults")
        .def_property_readonly("visible_object_count",
                               &detail::GetVisibleObjectCount,
                               "Number of visible objects after culling")
        .def_property_readonly("visible_light_count",
                               &detail::GetVisibleLightCount,
                               "Number of visible lights after culling");

    // ---- ScriptableRenderContext ----
    py::class_<ScriptableRenderContext>(m, "ScriptableRenderContext")
        .def_property_readonly("scene",
                               &ScriptableRenderContext::GetScene,
                               py::return_value_policy::reference,
                               "Access the scene being rendered")

        .def("setup_camera_properties",
             &ScriptableRenderContext::SetupCameraProperties,
             py::arg("camera"),
             "Configure camera view-projection matrices")

        .def("cull",
             &ScriptableRenderContext::Cull,
             py::arg("camera"),
             "Perform frustum + occlusion culling; returns statistics")

        .def("apply_graph",
             &ScriptableRenderContext::ApplyGraph,
             py::arg("description"),
             "Install a render graph topology from Python description")

        .def("submit_culling",
             &ScriptableRenderContext::SubmitCulling,
             py::arg("culling"),
             "Submit all accumulated culling data as draw calls")

        .def("execute_command_buffer",
             &ScriptableRenderContext::ExecuteCommandBuffer,
             py::arg("cmd"),
             "Flush and execute a previously queued command buffer")

        .def("get_camera_target",
             &ScriptableRenderContext::GetCameraTarget,
             py::arg("camera"),
             "Retrieve render target handle for camera output")

        // Global shader parameter setters (unified via wrapper)
        .def("set_global_texture",
             [](ScriptableRenderContext &ctx, const std::string &name, RenderTargetHandle hdl) {
                 ctx.SetGlobalTexture(name, hdl);
             },
             py::arg("name"), py::arg("handle"),
             "Assign a texture to a global shader variable")

        .def("set_global_float",
             &ScriptableRenderContext::SetGlobalFloat,
             py::arg("name"), py::arg("value"),
             "Set a scalar float uniform")

        .def("set_global_vector",
             &ScriptableRenderContext::SetGlobalVector,
             py::arg("name"), py::arg("x"), py::arg("y"), py::arg("z"), py::arg("w"),
             "Set a vec4 uniform (RGBA or xyzw)");
}

// ---- RenderPipelineCallback binding (with trampoline) ----
void RegisterRenderPipelineCallbackBinding(py::module_ &m)
{
    py::class_<RenderPipelineCallback, RenderPipelineHook, std::shared_ptr<RenderPipelineCallback>>(
        m, "RenderPipelineCallback")
        .def(py::init<>())
        .def("render",
             &RenderPipelineCallback::Render,
             py::arg("context"), py::arg("cameras"),
             "Main rendering callback invoked per frame")
        .def("dispose",
             &RenderPipelineCallback::Dispose,
             "Cleanup hook called when pipeline is swapped out");
}

