void UIScene_TrialExitUpsell::handleInput(int controllerIndex, int keyCode, bool isRepeat, bool isDown, bool isUp, bool &consumed)
{
    // Optional debug logging omitted for brevity

    // Animate key press visually
    ui.AnimateKeyPress(m_iPad, keyCode, isRepeat, isDown, isUp);

    switch (keyCode)
    {
        case ACTION_MENU_CANCEL:
            goBack();
            break;

        case ACTION_MENU_OK:
#if defined(__ORBIS__)
        case ACTION_MENU_TOUCHPAD_PRESS:
#endif
            if (isDown)
            {
                // Play feedback sound
                ui.PlayUISFX(eSFX_Press);
                // Trigger application exit
                app.ExitGame();
            }
            break;

        case ACTION_MENU_X:
            if (ProfileManager.IsSignedIn(controllerIndex))
            {
                // Audio feedback
                ui.PlayUISFX(eSFX_Press);

                // Check content restrictions before proceeding
#if defined(__PS3__) || defined(__PSVITA__)
                bool hasContentRestriction;
