class Solution {
public:
    int minimumDifference(vector<int>& nums, int k) {
        int n = nums.size();
        sort(nums.begin(), nums.end());

        if (n == 1) {
            return 0;
        }

        int minDiff = nums[k - 1] - nums[0];
        int index = 1;

        while (index <= n - k) {
            int currentDiff = nums[index + k - 1] - nums[index];
            if (currentDiff < minDiff) {
                minDiff = currentDiff;
            }
            index++;
        }

        return minDiff;
    }
};

#include "quadrants/program/field_info.h"
namespace quadrants {
namespace ui {
using namespace quadrants::lang;

// Retrieve the device pointer for a given field (snode) within the program
DevicePtr get_device_ptr(quadrants::lang::Program *program, SNode *snode) {
  /*
  GGUI assumes that input fields originate from ti.field() or ti.Vector with
  explicit shape, implying they are built using ti.root.dense.place().
  Specifically: snode's parent is dense, and that parent's parent is root.
  This structure enables computing the field's offset from the root buffer.
  Note: This holds except possibly for set_image(), where image data bypasses
  the VBO staging mechanism.
  */

  // Navigate up the SNode hierarchy to find the dense and root nodes
  SNode *dense_parent = snode->parent;
  SNode *root_node = dense_parent->parent;

  // Extract tree ID and root buffer device pointer
  int tree_id = root_node->get_snode_tree_id();
  DevicePtr root_buffer_ptr = program->get_snode_tree_device_ptr(tree_id);

  // Compute the byte offset of the field within its tree and return adjusted pointer
  int field_offset = program->get_field_in_tree_offset(tree_id, snode);
  return root_buffer_ptr.get_ptr(field_offset);
}
