#include "Game.h"
namespace Mechanics {
    void Game::DoFrame(unsigned delta) {
        // Step 1: advance player state
        player.Update(delta);

        // Step 2: process each active enemy
        for(auto &enemy : enemies) {
            enemy.Update(delta);
        }

        // Step 3: handle asteroid spawning based on elapsed time
        spawnTimer += delta;
        if(spawnTimer >= spawnTimeout) {
            spawnTimer = 0;
            // Create a new asteroid object on the heap and add it to the enemy list
            // The asteroid initializes with randomized position and velocity internally
            enemies.PushBack(new Astroid());
        }

        // Step 4: clean up off-screen or destroyed enemies
        // Use index-based iteration since we're modifying the container during traversal
        for(size_t idx = 0; idx < enemies.Size(); ++idx) {
            if(enemies[idx].IsMarkedForDeletion()) {
                enemies.RemoveAt(idx);
                --idx;  // Re-check current index after removal
            }
        }

        // Step 5: perform collision checks between player and asteroids
        // Using circular collision detection (distance-based)
        // Radii are tuned slightly smaller than visual size for better gameplay feel
        const float asteroidRadius = 24.0f;   // Half of 48 pixels
        const float playerRadius   = 7.5f;    // Half of 15 pixels

        for(auto &enemy : enemies) {
            if(enemy.GetType() == EnemyType::Asteroid) {
                // Compute Euclidean distance between centers
                float dist = enemy.GetLocation().DistanceTo(player.GetLocation());

                // Check if circles overlap
                if(dist < asteroidRadius + playerRadius) {
                    // Trigger game over condition
                    // Future enhancement: implement lives system, pause menu, restart logic
                    std::exit(0);
                }
            }
        }
    }
}

