        if (!condition) {  // Inverted logic: report error when condition is false
            std::cout << "Error " __FILE__ "(" << line << "): " << message
                 << "    (failed)" << std::endl;
            if (0 <= testStatus && testStatus <= 100) {
                ++testStatus;
            }
        }
    }
