MainWindow::MainWindow(QWidget *parent)
    : QMainWindow(parent)
    , ui(new Ui::MainWindow)
{
    ui->setupUi(this);
    this->initializeVisualizationWidget();
    this->configureHexSurface();

    // Timer to animate the surface evolution over time
    auto animationTimer = new QTimer(this);
    connect(animationTimer, &QTimer::timeout, [this]() {
        // Update radial distances and scalar field values for each hex cell
        std::for_each(hg->begin(), hg->end(), [this](size_t idx) {
            float dx = hg->d_x[idx];
            float dy = hg->d_y[idx];
            r_vals[idx] = std::sqrt(dx * dx + dy * dy);
            data_vals[idx] = std::sin(k_param * r_vals[idx]) / (k_param * r_vals[idx]);
        });

        k_param += 0.02f;
        if (k_param > 8.0f) {
            k_param = 1.0f;
        }

        // Signal that the first visual model needs rebuilding
        auto* vw_ptr = static_cast<mplot::qt::viswidget<0>*>(vw_handle);
        vw_ptr->set_model_needs_reinit(0);

        // Trigger redraw
        vw_handle->update();
    });

    animationTimer->start(30); // ~33 FPS
}

MainWindow::~MainWindow() { delete ui; }

void MainWindow::configureHexSurface()
{
    // Initialize hexagonal grid: spacing=0.02, radius=15, origin offset=0
    hex_grid = std::make_unique<sm::hexgrid>(0.02f, 15.0f, 0.0f);
    hex_grid->setCircularBoundary(4.0f);

    // Prepare storage for computed data
    size_t num_cells = hex_grid->num();
    data_vals.assign(num_cells, 0.0f);
    r_vals.assign(num_cells, 0.0f);
    k_param = 1.0f;

    // Precompute initial scalar field
    for (size_t i = 0; i < num_cells; ++i) {
        float x = hex_grid->d_x[i];
        float y = hex_grid->d_y[i];
        r_vals[i] = std::sqrt(x * x + y * y);
        data_vals[i] = std::sin(k_param * r_vals[i]) / (k_param * r_vals[i]);
    }

    // Create visual representation with slight vertical offset
    sm::vec<float, 3> visual_offset = { 0.0f, -0.05f, 0.0f };
    auto hex_vis = std::make_unique<mplot::HexGridVisual<float, mplot::qt::gl_version>>(hex_grid.get(), visual_offset);

    // Bind model to rendering context before finalizing
    auto* vw = static_cast<mplot::qt::viswidget<0>*>(vw_handle);
    vw->v.bindmodel(hex_vis);

    // Attach scalar data to visualizer
    hex_vis->setScalarData(&data_vals);

    // Transfer ownership to visualization container
    std::unique_ptr<mplot::VisualModel<mplot::qt::gl_version>> base_model = std::move(hex_vis);
    vw->newvisualmodels.push_back(std::move(base_model));
}

void MainWindow::initializeVisualizationWidget()
{
    // Instantiate OpenGL visualization widget
    mplot::qt::viswidget<0>* temp_vw = new mplot::qt::viswidget<0>(this->parentWidget());

    // Enable lighting effects for better visual appearance
    temp_vw->v.lightingEffects();

    // Embed into main window layout
    ui->verticalLayout->addWidget(temp_vw);

    // Store reference for later updates
    vw_handle = temp_vw;
}

void MainWindow::on_actionQuit_triggered() 
{ 
    close(); 
}

