// Hidden entry point for dynamic linker stage 2
hidden void __dls2(unsigned char *base, size_t *sp)
{
    // Extract arguments from stack pointer: argc is at *sp, argv starts at sp+1
    int argc_val = *sp;
    char **argv_ptr = reinterpret_cast<char **>(sp + 1);

    // Call libc startup routine with main and cleanup hooks
    __libc_start_main(
        main,
        argc_val,
        argv_ptr,
        _init,
        _fini,
        nullptr
    );
}

