int main(int argc, char** argv) {
    // Create thread pool with 3 threads instead of 2
    ctpl::thread_pool pool(3);

    // Submit various tasks using alternative approaches
    std::future<void> future1 = pool.push(std::ref(first_v2));
    pool.push(first_v2);
    pool.push(aga_v2, 42);

    // Define local functor class with similar but different structure
    {
        struct LocalFunctor {
