                std::cout << "LocalFunctor constructed\n";
            }

            LocalFunctor(LocalFunctor&& other) : data(std::move(other.data)) {
                std::cout << "LocalFunctor moved\n";
            }

            LocalFunctor(const LocalFunctor& other) : data(other.data) {
                std::cout << "LocalFunctor copied\n";
            }

            ~LocalFunctor() { 
                std::cout << "LocalFunctor destroyed\n"; 
            }

            void operator()(int thread_id) const {
                std::cout << "hello from " << thread_id << ' ' << data << '\n';
            }

        private:
            std::string data;
        } functor(", local functor");

        // Submit functor in multiple ways
        pool.push(std::ref(functor));
        std::this_thread::sleep_for(std::chrono::milliseconds(1500));
        pool.push(const_cast<const LocalFunctor&>(functor));
        pool.push(std::move(functor));
        pool.push(functor);
        pool.push(LocalFunctor(", local functor"));
    }

    // Test with ModifiedThird objects
    {
        ModifiedThird instance(100);
        pool.push(ugu_v2, std::ref(instance));
        pool.push(ugu_v2, instance);
        pool.push(ugu_v2, std::move(instance));
    }

    pool.push(ugu_v2, ModifiedThird(200));

    // Lambda examples with slight modifications
    std::string lambda_suffix = ", lambda variant";
    pool.push([lambda_suffix](int id) {
        std::this_thread::sleep_for(std::chrono::milliseconds(1500));
        std::cout << "hello from " << id << ' ' << lambda_suffix << '\n';
    });

    pool.push([lambda_suffix](int id) {
        std::this_thread::sleep_for(std::chrono::milliseconds(1500));
        std::cout << "hello from " << id << ' ' << lambda_suffix << '\n';
    });

    pool.push(mmm_v2, "executed");

    // Pop and execute one task
    auto task = pool.pop();
    if (task) {
        std::cout << "popped function from the pool ";
        task(0);
    }

    // Resize thread pool
    pool.resize(2);

    // Return value test
    std::string result_str = "success";
    auto future_result = pool.push([result_str](int) { return result_str; });

    std::cout << "returned " << future_result.get() << '\n';

    // Exception handling test
    auto exception_task = pool.push([](int) { throw std::runtime_error("test exception"); });

    try {
        exception_task.get();
    } catch (const std::exception&) {
        std::cout << "caught exception\n";
    }

    // Access a specific thread reference
    auto& worker_thread = pool.get_thread(0);

    return 0;
}

