    // Helper function to manage patch activation state
    void ConfigurePatch(Patch* patch, bool activate)
    {
        if (activate)
            patch->Apply();
        else
            patch->Restore();
    }

    class Aimbot : public BoolCommand
    {
        using BoolCommand::BoolCommand;

        virtual void OnEnable() override
        {
            // Apply multiple patches when feature is turned on
            ConfigurePatch(Pointers.ShouldNotTargetEntityPatch.get(), true);
            ConfigurePatch(Pointers.GetAssistedAimTypePatch.get(), true);
        }

        virtual void OnDisable() override
        {
            // Restore patches when feature is turned off
            ConfigurePatch(Pointers.ShouldNotTargetEntityPatch.get(), false);
            ConfigurePatch(Pointers.GetAssistedAimTypePatch.get(), false);
        }
    };

    class HeadshotPriority : public BoolCommand
    {
