TEST_CASE("PluginContentExtractorAdapter external backend behavior", "[daemon][extractor]") {
    SECTION("MIME type matching via internal cache") {
        PluginContentExtractorAdapter extractor(
            nullptr, "sample_plugin", {"application/x-executable", "application/octet-stream"},
            {".exe", ".bin"}, std::chrono::seconds{30});

        REQUIRE(extractor.supports("application/x-executable", ""));
        REQUIRE(extractor.supports("application/octet-stream", ""));
    }

    SECTION("Extension-based support with leading dot") {
        PluginContentExtractorAdapter extractor(nullptr, "sample_plugin", {"application/x-executable"},
                                              {".exe", ".bin"}, std::chrono::seconds{30});

        REQUIRE(extractor.supports("", ".exe"));
        REQUIRE(extractor.supports("", ".bin"));
    }

    SECTION("Extension-based support without leading dot") {
        PluginContentExtractorAdapter extractor(nullptr, "sample_plugin", {}, {".exe", ".bin"},
                                              std::chrono::seconds{30});

        REQUIRE(extractor.supports("", "exe"));
        REQUIRE(extractor.supports("", "bin"));
    }

    SECTION("Reject unsupported MIME types and extensions") {
        PluginContentExtractorAdapter extractor(nullptr, "sample_plugin", {"text/plain"}, {".txt"},
                                              std::chrono::seconds{30});

        REQUIRE_FALSE(extractor.supports("application/pdf", ""));
        REQUIRE_FALSE(extractor.supports("", ".pdf"));
        REQUIRE_FALSE(extractor.supports("image/png", ".png"));
    }

    SECTION("Empty inputs are not supported") {
        PluginContentExtractorAdapter extractor(nullptr, "sample_plugin", {"text/plain"}, {".txt"},
                                              std::chrono::seconds{30});

        REQUIRE_FALSE(extractor.supports("", ""));
    }

    SECTION("External backend detection") {
        PluginContentExtractorAdapter extractor(nullptr, "sample_plugin", {"text/plain"}, {".txt"},
                                              std::chrono::seconds{30});

        REQUIRE(extractor.isExternal());
    }
}

#include <iostream>
#include <functional>

#define SOL_ALL_SAFETIES_ON 1
#define SOL_ENABLE_INTEROP 1

#include <sol/sol.hpp>

// Forward declaration for kaguya compatibility
namespace kaguya {
    class State;
}

struct ABC {
    int stored_value;

    ABC() : stored_value(0) {}
    explicit ABC(int v) : stored_value(v) {}

    int getValue() const { return stored_value; }
    void assignValue(int v) { stored_value = v; }

    void methodA() {
        std::cout << "executing methodA" << std::endl;
    }

    void methodB(int x) {
        std::cout << "executing methodB with " << x << std::endl;
    }
};

// Helper to normalize index handling
inline int normalize_index(lua_State* L, int relidx) {
    return lua_absindex(L, relidx);
}

// Interop check specialization for ABC type
template <>
inline bool sol_lua_interop_check(sol::types<ABC>, lua_State* L,
     int relindex, sol::type, sol::stack::record& tracking) {
    tracking.use(1);
    int idx = normalize_index(L, relindex);
    return kaguya::detail::object_wrapper_type_check(L, idx);
}

// Interop get specialization for ABC type
template <>
inline std::pair<bool, ABC*> sol_lua_interop_get(sol::types<ABC>,
     lua_State* L, int relindex, void*, sol::stack::record& tracking) {
    int idx = normalize_index(L, relindex);
    if (!kaguya::detail::object_wrapper_type_check(L, idx)) {
        return { false, nullptr };
    }
    tracking.use(1);
    auto* base = kaguya::object_wrapper(L, idx);
    return { true, static_cast<ABC*>(base->get()) };
}

// Register sol2 bindings — renamed and refactored
void setup_sol_bindings(lua_State* L) {
    sol::state_view lua(L);

    // Create reusable lambdas for overloads
    auto handler1 = [](ABC& obj) {
        std::cout << "invoking single-arg overload with ABC { "
                  << obj.getValue() << " }\n";
        SOL_ASSERT(obj.getValue() == 24);
    };

    auto handler2 = [](ABC& obj, int extra) {
        std::cout << "invoking two-arg overload with ABC { "
                  << obj.getValue() << " } and integer " << extra << "\n";
        SOL_ASSERT(obj.getValue() == 24);
        SOL_ASSERT(extra == 5);
    };

    lua["process"] = sol::overload(handler1, handler2);
}

// Verify state via sol2 — renamed and simplified
void validate_via_sol(lua_State* L) {
    sol::state_view lua(L);
    ABC& instance = lua["instance"];
    (void)instance;
    SOL_ASSERT(instance.getValue() == 24);
}

// Helper to construct ABC instance in kaguya context
void instantiate_and_test(kaguya::State& engine) {
    engine.dostring(R"(
instance = ABC.new(24)
process(instance)         -- single argument case
process(instance, 5)      -- two argument case
)");
}

int main(int, char*[]) {
    std::cout << "=== interop demo: kaguya + sol2 ===\n";
    std::cout << "(adapted from satoren/kaguya README)\n";

    kaguya::State engine;

    // Register ABC class into kaguya
    engine["ABC"].setClass(
        kaguya::UserdataMetatable<ABC>()
            .setConstructors<ABC(), ABC(int)>()
            .addFunction("retrieve", &ABC::getValue)
            .addFunction("assign", &ABC::assignValue)
            .addOverloadedFunctions("dispatch", &ABC::methodA, &ABC::methodB)
            .addStaticFunction("static_helper",
                [](ABC*, int) { return 42; })
    );

    // Setup sol2 interop layer
    setup_sol_bindings(engine.state());

    // Execute script and verify
    instantiate_and_test(engine);
    validate_via_sol(engine.state());

    return 0;
}

