MConstantInt *MConstantInt::get(CompileContext &Ctx, MType &Ty, APInt Val) {
  // Look up or prepare insertion slot for the constant
  MConstantInt *&Entry = Ctx.IntConstants[Val];
  if (!Entry) {
    // Allocate memory and construct the new constant
    Entry = ::new (Ctx.ThreadMemPool.allocate(sizeof(MConstantInt), alignof(MConstantInt)))
        MConstantInt(Ty, Val);
  }
  return Entry;
}

MConstantInt *MConstantInt::get(CompileContext &Ctx, MType &Ty, uint64_t Value) {
  return MConstantInt::get(Ctx, Ty, APInt(Ty.getBitWidth(), Value, Ty.isSigned()));
}

MConstantFloat *MConstantFloat::get(CompileContext &Ctx, MType &Ty, APFloat Val) {
  // Retrieve existing entry or determine where to insert
  MConstantFloat *&Slot = Ctx.FPConstants[Val];
  if (!Slot) {
    // Allocate raw memory and placement-new the object
    Slot = ::new (Ctx.ThreadMemPool.allocate(sizeof(MConstantFloat), alignof(MConstantFloat)))
        MConstantFloat(Ty, Val);
  }
  return Slot;
}

MConstantFloat *MConstantFloat::get(CompileContext &Ctx, MType &Ty, float Value) {
  return MConstantFloat::get(Ctx, Ty, APFloat(Value));
}

MConstantFloat *MConstantFloat::get(CompileContext &Ctx, MType &Ty, double Value) {
  return MConstantFloat::get(Ctx, Ty, APFloat(Value));
}

void MConstant::print(llvm::raw_ostream &OS) const {
  if (Type.isInteger()) {
    auto *ConstInt = cast<MConstantInt>(this);
    ConstInt->getValue().print(OS, ConstInt->getType().isSigned());
  } else if (Type.isFloatingPoint()) {
    auto *ConstFloat = cast<MConstantFloat>(this);
    SmallVector<char, 16> Buffer;
    ConstFloat->getValue().toString(Buffer);
    OS << Buffer;
  } else {
    ZEN_UNREACHABLE();
  }
}

