#include <iostream>
#include <vector>
#include <string>
#include <map>
#include <cmath>

// Send a walk command with step count x and receive response from judge
int move_forward(long long steps) {
    std::cout << "walk " << steps << std::endl;
    int result;
    std::cin >> result;
    return result;
}

// Send a guess command with the computed cycle length
void report_answer(long long answer) {
    std::cout << "guess " << answer << std::endl;
}

int main() {
    // Optimize I/O for interactive problems
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    // Block size for Baby-step Giant-step: sqrt(10^9) ≈ 31623, rounded to 32000
    const int BLOCK_SIZE = 32000;

    // Map to store visited nodes and their first occurrence step count
    std::map<int, int> visited_nodes;

    // Initial position: walk 0 steps to get starting node
    int current_node = move_forward(0);
    visited_nodes[current_node] = 0;

    // Baby steps: explore up to BLOCK_SIZE steps one by one
    for (int step_count = 1; step_count <= BLOCK_SIZE; ++step_count) {
        current_node = move_forward(1);

        // Check if we've seen this node before
        if (visited_nodes.find(current_node) != visited_nodes.end()) {
            // Found a collision - cycle detected during baby steps
            int previous_step = visited_nodes[current_node];
            report_answer(step_count - previous_step);
            return 0;
        }

        // Record this node and its step count
        visited_nodes[current_node] = step_count;
    }

    // Giant steps: continue from where baby steps left off
    long long accumulated_steps = BLOCK_SIZE;

    // Take giant steps of size BLOCK_SIZE
    for (int giant_step_index = 2; giant_step_index <= BLOCK_SIZE + 2; ++giant_step_index) {
        current_node = move_forward(BLOCK_SIZE);
        accumulated_steps += BLOCK_SIZE;

        // Check if current node was seen in baby steps
        auto it = visited_nodes.find(current_node);
        if (it != visited_nodes.end()) {
            // Found match between giant step and baby step
            int baby_step_count = it->second;
            report_answer(accumulated_steps - baby_step_count);
            return 0;
        }
    }

    // Should never reach here under normal problem constraints
    return 0;
}

