extern "C" LLVM_EXTERNAL_VISIBILITY void LLVMInitializeWebAssemblyTargetMC() {
  // Iterate over both 32-bit and 64-bit WebAssembly targets
  for (Target *target : {&getTheWebAssemblyTarget32(), &getTheWebAssemblyTarget64()}) {
