    TargetRegistry::RegisterMCRegInfo(*target, buildMCRegInfo);
    TargetRegistry::RegisterMCInstPrinter(*target, buildMCInstPrinter);
    TargetRegistry::RegisterMCCodeEmitter(*target, buildCodeEmitter);
    TargetRegistry::RegisterMCAsmBackend(*target, buildAsmBackend);
