// Tile Accelerator (TA) execution engine for PowerVR2 (Dreamcast) emulation
// Manages input from Store Queue and DMA transfers; routes commands to handlers
namespace TASplitter
{
    // Pointer to the current command dispatcher (state machine)
    TaListFP* ActiveTaHandler = nullptr;
}
using namespace TASplitter;

// Handle Store Queue write: single 32-byte packet
void libPvr_TaSQ(u32* buffer)
{
    if (ActiveTaHandler == nullptr)
        throw std::runtime_error("TA handler not initialized");

    Ta_Dma* entry = reinterpret_cast<Ta_Dma*>(buffer);
    ActiveTaHandler(entry, entry);
}

// Process DMA buffer: iterates over 32-byte TA entries
// 'length' specifies number of Ta_Dma elements (not bytes)
void libPvr_TaDMA(u32* buffer, u32 length)
{
    if (ActiveTaHandler == nullptr)
        throw std::runtime_error("TA handler not initialized");
    if (length == 0)
        throw std::invalid_argument("DMA length must be positive");

    Ta_Dma* start = reinterpret_cast<Ta_Dma*>(buffer);
    Ta_Dma* finish = start + length - 1;
    Ta_Dma* cursor = start;

    do
    {
        cursor = ActiveTaHandler(cursor, finish);
    }
    while (cursor <= finish);
}

namespace TASplitter
{
    // Invoked when hardware asserts list continuation (TA_LIST_CONT register)
    // Allows reopening of previously finished lists
    void TA_ListCont()
    {
