    // Triggered on new list initialization (TA_LIST_INIT register)
    // Reinitializes TA state and resets command handler
    void TA_ListInit()
    {
        // Handler reset to ta_main occurs in FifoSplitter::ListInit()
    }

    // Executed on software-initiated TA reset (SOFTRESET register write)
    // Clears internal list tracking without full hardware reload
    void TA_SoftReset()
    {
