#include <iostream>

int main() {
    // Optimize I/O for performance
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int distance;
    std::cin >> distance;

    // Continue until we reach the destination (distance becomes 0)
    while (distance > 0) {
        int response;
        int next_distance;

        // Attempt path with color 0
        std::cout << "move 0" << std::endl;
        std::cin >> response;
        if (response == 1) {
            break; // Exit found
        }

        std::cout << "query" << std::endl;
        std::cin >> next_distance;
        if (next_distance < distance) {
            distance = next_distance;
            continue;
        }

        // Backtrack from color 0 attempt
        std::cout << "move 0" << std::endl;
        std::cin >> response;

        // Attempt path with color 1
        std::cout << "move 1" << std::endl;
        std::cin >> response;
        if (response == 1) {
            break; // Exit found
        }

        std::cout << "query" << std::endl;
        std::cin >> next_distance;
        if (next_distance < distance) {
            distance = next_distance;
            continue;
        }

        // Backtrack from color 1 attempt
        std::cout << "move 1" << std::endl;
        std::cin >> response;

        // Since colors 0 and 1 both led away, color 2 must be correct
        std::cout << "move 2" << std::endl;
        std::cin >> response;
        if (response == 1) {
            break; // Exit found
        }

        // Successfully moved closer without querying
        distance--;
    }

    return 0;
}

