// Determine if the array is sorted in non-decreasing order
bool checkSorted(const std::vector<int>& data, int pos) {
    // Base case: reached the last element or beyond — array is sorted
    if (pos >= data.size() - 1) {
        return true;
    }
    // If current element is greater than the next, it's not sorted
    if (data[pos] > data[pos + 1]) {
        return false;
    }
    // Continue checking the remaining elements
    return checkSorted(data, pos + 1);
}

