#include <string>
#include <vector>
#include <algorithm>

class Solution {
public:
    bool isAnagram(std::string s, std::string t) {
        // Early exit if lengths differ
        if (s.length() != t.length()) {
            return false;
        }

        // Count character frequencies using two separate arrays
        std::vector<int> freq_s(26, 0);
        std::vector<int> freq_t(26, 0);

        // Populate frequency counts for both strings
        for (int idx = 0; idx < s.length(); ++idx) {
            freq_s[s[idx] - 'a']++;
            freq_t[t[idx] - 'a']++;
        }

        // Compare the frequency arrays element by element
        for (int i = 0; i < 26; ++i) {
            if (freq_s[i] != freq_t[i]) {
                return false;
            }
        }

        return true;
    }
};

