#include <sol/sol.hpp>
#include <iostream>

// Alternative implementation: uses different naming and structure
void alternative_approach(sol::this_state ts, sol::this_environment te) {
    sol::state_view lua_vm = ts;

    if (te.has_value()) {
        auto& current_env = *te;
        auto custom_env = lua_vm["custom_context"];

        bool same_context = (custom_env == current_env);
        std::cout << "environment check -- context matches custom_context: "
                  << same_context << '\n';
    } else {
        std::cout << "no environment bound to this call\n";
    }
}

// Deeper introspection version — rewritten with equivalent behavior
void deeper_inspection(sol::this_state ts) {
    lua_State* L = ts.lua_state();
    lua_Debug frame_info;

    const int target_level = 1; // skip current function frame
    int initial_stack_depth = lua_gettop(L);

    if (lua_getstack(L, target_level, &frame_info) != 1) {
        std::cerr << "stack traversal failed\n";
        lua_settop(L, initial_stack_depth);
        return;
    }

    if (!lua_getinfo(L, "fnluS", &frame_info)) {
        std::cerr << "failed to retrieve debug info for frame\n";
        lua_settop(L, initial_stack_depth);
        return;
    }

    // Output metadata about the calling frame
    std::cout << "introspection -- [" << target_level << "] "
              << frame_info.short_src << ':' << frame_info.currentline
              << " :: " << (frame_info.name ? frame_info.name : "<unnamed>")
              << " [" << frame_info.what << "]\n";

    // Extract function from top of stack
    sol::function caller_func(L, -1);
    sol::environment caller_env(sol::env_key, caller_func);

    if (!caller_env.valid()) {
        std::cerr << "introspection -- no environment found\n";
        lua_settop(L, initial_stack_depth);
        return;
    }

    sol::state_view view(L);
    sol::environment expected_env = view["custom_context"];

    bool match = (expected_env == caller_env);
    std::cout << "introspection -- env matches custom_context: " << match << '\n';

    // Restore stack before returning
    lua_settop(L, initial_stack_depth);
}

int main() {
    std::cout << "=== environment discovery demo ===\n";

    sol::state vm;
    sol::environment custom_context(vm, sol::create, vm.globals());
    vm["custom_context"] = custom_context;

    vm.set_function("run_simple", alternative_approach);
    vm.set_function("run_deep", deeper_inspection);

    vm.script("run_simple()", custom_context);
    vm.script("run_deep()", custom_context);

    std::cout << std::endl;
    return 0;
}

#include <vector>
using namespace std;

class Solution {
public:
    void generatePermutations(vector<int>& elements, int position, int size, vector<vector<int>>& result) {
        // Base case: when we've fixed all positions
        if (position == size - 1) {
            result.push_back(elements);
            return;
        }

        // Try each element at the current position
        for (int j = position; j < size; ++j) {
            // Swap to place element at current position
            swap(elements[j], elements[position]);

            // Recursively generate permutations for remaining positions
            generatePermutations(elements, position + 1, size, result);

            // Backtrack by swapping back
            swap(elements[j], elements[position]);
        }
    }

    vector<vector<int>> permute(vector<int>& nums) {
        vector<vector<int>> permutations;
        generatePermutations(nums, 0, nums.size(), permutations);
        return permutations;
    }
};

