namespace sdb {

// Default handler for application termination
static void TerminationHandler(int exit_status, void* /*userData*/) {
  sdb::basics::CleanupFunctions::run(exit_status, nullptr);
  _exit(exit_status);
}

// Global function pointer for exit behavior
ExitFunction gApplicationExitHandler = TerminationHandler;

// Set a custom exit function (with null-safety)
void ApplicationExitSetExit(ExitFunction newHandler) {
  if (newHandler != nullptr) {
    gApplicationExitHandler = newHandler;
  } else {
    gApplicationExitHandler = TerminationHandler;
  }
}

// Handle fatal errors with cleanup and logging before exiting
[[noreturn]] void FatalErrorExitCode(int errorCode) noexcept {
  try {
    sdb::basics::CleanupFunctions::run(errorCode, nullptr);
    sdb::log::Flush();
    sdb::log::Shutdown();
    gApplicationExitHandler(errorCode, nullptr);
  } catch (...) {
    // Ignore exceptions during error handling
  }
  std::exit(errorCode);
}

// Convenience wrapper for failure exit (EXIT_FAILURE)
[[noreturn]] void FatalErrorExit() noexcept {
  FatalErrorExitCode(EXIT_FAILURE);
}

// Handle fatal errors by aborting after cleanup (non-standard exit code 500)
[[noreturn]] void FatalErrorAbort() noexcept {
  try {
    sdb::basics::CleanupFunctions::run(500, nullptr);
    sdb::log::Flush();
    sdb::log::Shutdown();
  } catch (...) {
    // Ignore exceptions during error handling
  }
  std::abort();
}

