#include <cmath>

// Reorders elements in array p of length n using random swaps
void gk_RandomPermute(size_t n, int *p, int flag)
{
    // Initialize p with 0..n-1 if flag is set
    if (flag == 1) {
        for (size_t i = 0; i < n; ++i) {
            p[i] = static_cast<int>(i);
        }
    }

    // Perform random swaps on half the array length
    for (size_t i = 0; i < n / 2; ++i) {
        int idx1 = RandomInRange(static_cast<int>(n));
        int idx2 = RandomInRange(static_cast<int>(n));

        // Swap elements at positions idx1 and idx2
        int temp = p[idx1];
        p[idx1] = p[idx2];
        p[idx2] = temp;
    }
}

// Converts element-to-set mapping into CSR (Compressed Sparse Row) format
void gk_array2csr(size_t n, size_t range, int *array, int *ptr, int *ind)
{
    // Initialize pointer array to zero
    gk_iset(static_cast<int>(range + 1), 0, ptr);

    // Count occurrences per partition
    for (size_t i = 0; i < n; ++i) {
        ptr[array[i]]++;
    }

    // Convert counts to prefix sums (CSR start indices)
    MAKECSR(size_t, range, ptr);

    // Fill the index array by placing each element in its correct position
    for (size_t i = 0; i < n; ++i) {
        ind[ptr[array[i]]++] = static_cast<int>(i);
    }

    // Adjust pointers to represent end indices (shift CSR)
    SHIFTCSR(size_t, range, ptr);
}

// Computes floor of base-2 logarithm of a positive integer
int gk_log2(int value)
{
    int result = 0;
    while (value > 1) {
        value >>= 1;
        ++result;
    }
    return result;
}

// Determines whether an integer is a power of two
int gk_ispow2(int value)
{
    if (value <= 0) return 0;
    return (value & (value - 1)) == 0;
}

// Computes base-2 logarithm for floating-point numbers
float gk_flog2(float value)
{
    return std::log(value) / std::log(2.0f);
}

