// Helper lambda to wrap kernel calls with consistent casting
auto call_index_max_kernel = [](const at::Tensor& vals,
                                const at::Tensor& idx,
                                int blocksA,
                                int blocksB) {
  return index_max_kernel(vals, idx, blocksA, blocksB);
};

auto call_mm_to_sparse_kernel = [](const at::Tensor& A,
                                   const at::Tensor& B,
                                   const at::Tensor& idx) {
  return mm_to_sparse_kernel(A, B, idx);
};

auto call_sparse_dense_mm_kernel = [](const at::Tensor& sparseA,
                                      const at::Tensor& idx,
                                      const at::Tensor& denseB,
                                      int blocksA) {
  return sparse_dense_mm_kernel(sparseA, idx, denseB, blocksA);
};

auto call_reduce_sum_kernel = [](const at::Tensor& sparseA,
                                 const at::Tensor& idx,
                                 int blocksA,
                                 int blocksB) {
  return reduce_sum_kernel(sparseA, idx, blocksA, blocksB);
};

auto call_scatter_kernel = [](const at::Tensor& denseA,
                              const at::Tensor& idx,
                              int blocksB) {
  return scatter_kernel(denseA, idx, blocksB);
};

// Index maximum operation over blocks
std::vector<at::Tensor> index_max(
    at::Tensor index_vals,
    at::Tensor indices,
    int64_t num_blocks_A,
    int64_t num_blocks_B) {
  return call_index_max_kernel(
      index_vals,
      indices,
      static_cast<int>(num_blocks_A),
      static_cast<int>(num_blocks_B));
}

// Convert dense matrix multiplication result to sparse format
at::Tensor mm_to_sparse(
    at::Tensor matrix_A_dense,
    at::Tensor matrix_B_dense,
    at::Tensor indices) {
  return call_mm_to_sparse_kernel(
      matrix_A_dense,
      matrix_B_dense,
      indices);
}

// Sparse-dense matrix multiplication
at::Tensor sparse_dense_mm(
    at::Tensor sparse_matrix_A,
    at::Tensor indices,
    at::Tensor dense_matrix_B,
    int64_t num_blocks_A) {
  return call_sparse_dense_mm_kernel(
      sparse_matrix_A,
      indices,
      dense_matrix_B,
      static_cast<int>(num_blocks_A));
}

// Reduce sum over sparse structure
at::Tensor reduce_sum(
    at::Tensor sparse_matrix_A,
    at::Tensor indices,
    int64_t num_blocks_A,
    int64_t num_blocks_B) {
  return call_reduce_sum_kernel(
      sparse_matrix_A,
      indices,
      static_cast<int>(num_blocks_A),
      static_cast<int>(num_blocks_B));
}

// Scatter dense tensor into sparse layout
at::Tensor scatter(
    at::Tensor dense_tensor_A,
    at::Tensor indices,
    int64_t num_blocks_B) {
  return call_scatter_kernel(
      dense_tensor_A,
      indices,
      static_cast<int>(num_blocks_B));
}

// Register CUDA ops with PyTorch
TORCH_LIBRARY_EXPAND(TORCH_EXTENSION_NAME, ops) {
  // Define signatures and implementations
  auto def_impl = [&](const std::string& name,
                      const std::string& signature,
                      at::Tensor (*func)(const at::Tensor&, const at::Tensor&, ...)) {
    ops.def(signature);
    ops.impl(name, torch::kCUDA, func);
  };

  // Explicitly register each op with its signature
  ops.def("index_max(Tensor index_vals, Tensor indices, int A_num_block, int B_num_block) -> Tensor[]");
  ops.impl("index_max", torch::kCUDA, &index_max);

  ops.def("mm_to_sparse(Tensor dense_A, Tensor dense_B, Tensor indices) -> Tensor");
  ops.impl("mm_to_sparse", torch::kCUDA, &mm_to_sparse);

  ops.def("sparse_dense_mm(Tensor sparse_A, Tensor indices, Tensor dense_B, int A_num_block) -> Tensor");
  ops.impl("sparse_dense_mm", torch::kCUDA, &sparse_dense_mm);

  ops.def("reduce_sum(Tensor sparse_A, Tensor indices, int A_num_block, int B_num_block) -> Tensor");
  ops.impl("reduce_sum", torch::kCUDA, &reduce_sum);

  ops.def("scatter(Tensor dense_A, Tensor indices, int B_num_block) -> Tensor");
  ops.impl("scatter", torch::kCUDA, &scatter);
}

REGISTER_EXTENSION(TORCH_EXTENSION_NAME);

