#include <iostream>
#include <vector>
#include <stack>

// Function to send a query and receive a response
int query(int x) {
    std::cout << "? " << x << std::endl;
    int r;
    std::cin >> r;
    return r;
}

// Function to output an answer
void answer(int a, int b) {
    std::cout << "! " << a << " " << b << std::endl;
}

int main() {
    // Fast I/O
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int n;
    std::cin >> n;

    // Track which items have been paired
    std::vector<bool> matched(2 * n + 1, false);

    // Stack to hold candidate items that haven't found their pair yet
    std::stack<int> candidates;

    int distinct_count = 0;
    int pair_count = 0;

    for (int item = 1; item <= 2 * n; ++item) {
        if (matched[item]) continue;

        // Query with current item
        int result = query(item);

        if (result > distinct_count) {
            // This item's pair is not in our collection yet
            candidates.push(item);
            distinct_count = result;
        } else {
            // The item's pair must be somewhere in candidates
            // We'll test candidates one by one to find the match

            std::vector<int> temp_storage;

            while (!candidates.empty()) {
                int candidate = candidates.top();
                candidates.pop();

                // Temporarily remove candidate and check if count changes
                int test_result = query(candidate);

                if (test_result == distinct_count) {
                    // Found the match! candidate is paired with item
                    answer(item, candidate);
                    pair_count++;
                    matched[item] = true;
                    matched[candidate] = true;

                    // Remove item from device since we've found its pair
                    distinct_count = query(item);

                    // Restore all temporarily removed candidates
                    for (int restored : temp_storage) {
                        distinct_count = query(restored);
                        candidates.push(restored);
                    }

                    break;
                } else {
                    // Not the match, keep it aside for now
                    temp_storage.push_back(candidate);
                }
            }
        }

        if (pair_count == n) break;
    }

    return 0;
}

