namespace FFBEngineTests {

TEST_CASE(test_issue_42_ffb_inversion_persistence, "Config") {
    std::cout << "\nTest: Issue #42 - FFB Inversion Persistence Across Presets" << std::endl;
    FFBEngine engine;
    InitializeEngine(engine);
    Config::LoadPresets();

    // Scenario A: Begin with inversion enabled
    FFBEngineTestAccess::SetInvertForce(engine, true);
    REQUIRE(engine.m_invert_force == true);

    Config::ApplyPreset(0, engine);
    REQUIRE(engine.m_invert_force == true); // Must stay true

    // Locate T300 preset index via standard algorithm
    auto t300_it = std::find_if(Config::presets.begin(), Config::presets.end(),
        [](auto const& p) { return p.name == "T300"; });
    if (t300_it != Config::presets.end()) {
        size_t t300_pos = std::distance(Config::presets.begin(), t300_it);
        Config::ApplyPreset(static_cast<int>(t300_pos), engine);
        REQUIRE(engine.m_invert_force == true);
    }

    // Scenario B: Begin with inversion disabled
    FFBEngineTestAccess::SetInvertForce(engine, false);
    REQUIRE(engine.m_invert_force == false);

    Config::ApplyPreset(0, engine);
    REQUIRE(engine.m_invert_force == false); // Must stay false

    if (t300_it != Config::presets.end()) {
        size_t t300_pos = std::distance(Config::presets.begin(), t300_it);
        Config::ApplyPreset(static_cast<int>(t300_pos), engine);
        REQUIRE(engine.m_invert_force == false); // Must stay false
    }

    // Scenario C: Verify user preset doesn't capture engine inversion state
    Preset user_preset("UserTest", false);
    FFBEngineTestAccess::SetInvertForce(engine, true);
    user_preset.UpdateFromEngine(engine);
    FFBEngineTestAccess::SetInvertForce(engine, false);
    user_preset.Apply(engine);
    REQUIRE(engine.m_invert_force == false); // Should not revert to true
}

TEST_CASE(test_issue_42_ffb_inversion_global_persistence, "Config") {
    std::cout << "\nTest: Issue #42 - FFB Inversion Global Persistence (Save/Load)" << std::endl;
    FFBEngine engine;
    InitializeEngine(engine);
    std::string config_file = "test_issue_42_persistence.ini";

    // Test 1: Save state as true → Load should restore true
    FFBEngineTestAccess::SetInvertForce(engine, true);
    Config::Save(engine, config_file);

    FFBEngine loaded_engine_1;
    FFBEngineTestAccess::SetInvertForce(loaded_engine_1, false); // Intentionally corrupt initial state
    Config::Load(loaded_engine_1, config_file);
    REQUIRE(loaded_engine_1.m_invert_force == true);

    // Test 2: Save state as false → Load should restore false
    FFBEngineTestAccess::SetInvertForce(engine, false);
    Config::Save(engine, config_file);

    FFBEngine loaded_engine_2;
    FFBEngineTestAccess::SetInvertForce(loaded_engine_2, true); // Intentionally corrupt initial state
    Config::Load(loaded_engine_2, config_file);
    REQUIRE(loaded_engine_2.m_invert_force == false);

    std::remove(config_file.c_str());
}

