#include <iostream>
#include <vector>
#include <queue>
#include <cmath>

// This code solves LeetCode problem 1046: Last Stone Weight
// It simulates repeatedly smashing the two heaviest stones until at most one remains.
using namespace std;

class Solution {
public:
    int lastStoneWeight(vector<int>& stones) {
        // Use a max-heap (priority queue) to efficiently retrieve the largest elements
        priority_queue<int> heap;

        // Insert all stone weights into the heap
        for (int weight : stones) {
            heap.push(weight);
        }

        // Process stones until fewer than two remain
        while (heap.size() >= 2) {
            // Extract the two heaviest stones
            int heavy = heap.top();
            heap.pop();
            int lighter = heap.top();
            heap.pop();

            // If they're not equal, push the difference back
            if (heavy != lighter) {
                heap.push(abs(heavy - lighter));
            }
            // If equal, both are destroyed (nothing pushed back)
        }

        // Return the remaining stone's weight or 0 if none remain
        return heap.empty() ? 0 : heap.top();
    }
};

#include <vector>
#include <algorithm>

class Solution {
public:
    std::vector<std::vector<int>> minimumAbsDifference(std::vector<int>& arr) {
        int size = arr.size();
        if (size < 2) return {};

        std::sort(arr.begin(), arr.end());

        int minDiff = arr[1] - arr[0];
        for (int i = 1; i < size - 1; ++i) {
            int currentDiff = arr[i + 1] - arr[i];
            if (currentDiff < minDiff) {
                minDiff = currentDiff;
            }
        }

        std::vector<std::vector<int>> result;
        for (int i = 0; i < size - 1; ++i) {
            if (arr[i + 1] - arr[i] == minDiff) {
                result.push_back({arr[i], arr[i + 1]});
            }
        }

        return result;
    }
};

#include <iostream>
#include <unordered_map>
#include <queue>
using namespace std;

// Function to locate the first non-repeating character in a string
char findFirstDistinctChar(const string& input) {
    unordered_map<char, int> frequencyMap;
    queue<char> orderQueue;

    // Traverse the string to count frequencies and track potential unique characters
    for (char c : input) {
        if (frequencyMap.count(c) == 0) {
            frequencyMap[c] = 1;
            orderQueue.push(c);
        } else {
            frequencyMap[c]++;
        }

        // Clean up the queue by removing characters that have become repeated
        while (!orderQueue.empty() && frequencyMap[orderQueue.front()] > 1) {
            orderQueue.pop();
        }
    }

    return orderQueue.empty() ? '\0' : orderQueue.front();
}

// Demonstration of the function
int main() {
    string text = "level";
    char uniqueChar = findFirstDistinctChar(text);

    if (uniqueChar != '\0') {
        cout << "The first distinct character is: " << uniqueChar << endl;
    } else {
        cout << "No distinct character found." << endl;
    }

    return 0;
}

