#include "llvm/IR/GCStrategy.h"
#include "llvm/ADT/Twine.h"
#include "llvm/IR/BuiltinGCs.h"

using namespace llvm;

LLVM_INSTANTIATE_REGISTRY(GCRegistry)

// Default constructor for GCStrategy
GCStrategy::GCStrategy() = default;

// Function to retrieve a GC strategy by name, with fallback handling for missing registrations
std::unique_ptr<GCStrategy> llvm::getGCStrategy(const StringRef Name) {
  // First, try to find an existing registered strategy
  for (auto &Entry : GCRegistry::entries()) {
    if (Entry.getName() == Name)
      return Entry.instantiate();
  }

  // Ensure all built-in GCs are linked in static builds
  llvm::linkAllBuiltinGCs();

  // Check if registry is still empty after linking built-ins
  if (GCRegistry::begin() == GCRegistry::end()) {
    // Registry is empty: likely missing initialization or linking
    std::string errorMsg = "unsupported GC: " + Name.str() +
                           " (did you remember to link and initialize the library?)";
    report_fatal_error(Twine(errorMsg));
  } else {
    // Registry has entries but not the requested one
    std::string errorMsg = "unsupported GC: " + Name.str();
    report_fatal_error(Twine(errorMsg));
  }
}

