// Function to compute and display area of square
void computeSquareArea(int side) {
    int area = side * side;
    std::cout << "area of square = " << area << std::endl;
}

// Function to compute and display perimeter of rectangle
void computeRectanglePerimeter(int length, int breadth) {
    int perimeter = 2 * (length + breadth);
    std::cout << "perimeter of rectangle = " << perimeter << std::endl;
}

// Function to compute and display area of circle (using pi = 3.14 approx)
void computeCircleArea(int radius) {
    const double PI = 3.14;
    double area = PI * radius * radius;
    std::cout << "area of circle = " << area << std::endl;
}

// Function to find and print maximum among three integers
int findMaxOfThree(int x, int y, int z) {
    int max = x;
    if (y > max) max = y;
    if (z > max) max = z;
    return max;
}

// Function to print multiplication table of a number
void printMultiplicationTable(int n) {
    std::cout << "table of " << n << ":" << std::endl;
    for (int i = 1; i <= 10; ++i) {
        std::cout << n << " x " << i << " = " << (n * i) << std::endl;
    }
}

int main() {
    int choice = 0;
    int side, length, breadth, radius, num;

    do {
        system("cls");

        std::cout << "1. area of square\n";
        std::cout << "2. perimeter of rectangle\n";
        std::cout << "3. area of circle\n";
        std::cout << "4. max of 3 nos\n";
        std::cout << "5. table of number\n";
        std::cout << "6. exit\n";
        std::cout << "enter your choice: ";
        std::cin >> choice;

        switch (choice) {
            case 1:
                std::cout << "enter side: ";
                std::cin >> side;
                computeSquareArea(side);
                break;

            case 2:
                std::cout << "enter length and breadth: ";
                std::cin >> length >> breadth;
                computeRectanglePerimeter(length, breadth);
                break;

            case 3:
                std::cout << "enter radius: ";
                std::cin >> radius;
                computeCircleArea(radius);
                break;

            case 4: {
                int x, y, z;
                std::cout << "enter three numbers: ";
                std::cin >> x >> y >> z;
                int maxVal = findMaxOfThree(x, y, z);
                std::cout << "max of 3 nos = " << maxVal << std::endl;
                break;
            }

            case 5:
                std::cout << "enter number: ";
                std::cin >> num;
                printMultiplicationTable(num);
                break;

            case 6:
                std::cout << "Exiting..." << std::endl;
                break;

            default:
                std::cout << "Invalid choice! Please try again." << std::endl;
        }

        if (choice != 6) {
            std::cout << "Press Enter to continue...";
            std::cin.ignore();
            std::cin.get();
        }

    } while (choice != 6);

    return 0;
}

#include <iostream>
#include <functional>
#include <string>

// Standalone function
void standalone_function(int value) {
    std::cout << "standalone_function: " << value << std::endl;
}

// Callable struct (functor)
struct CallableStruct {
    void operator()(int value) const {
        std::cout << "CallableStruct: " << value << std::endl;
    }
};

// Class containing various callable members
struct DataProcessor {
    void process_value(int value) {
        std::cout << "DataProcessor::process_value: " << value << std::endl;
    }

    void process_const(int value) const {
        std::cout << "DataProcessor::process_const: " << value << std::endl;
    }

    int stored_value = 100;
};

void demonstrate_invoke_features() {
    std::cout << "=== Demonstrating std::invoke Capabilities ===" << std::endl;

    CallableStruct callable_obj;
    DataProcessor processor;

    // Call free function using std::invoke
    std::invoke(standalone_function, 7);

    // Call functor object
    std::invoke(callable_obj, 14);

    // Call lambda expression
    std::invoke([](int val) { std::cout << "Lambda: " << val << std::endl; }, 28);

    // Invoke member function on object instance
    std::invoke(&DataProcessor::process_value, processor, 35);

    // Invoke member function via pointer to object
    std::invoke(&DataProcessor::process_value, &processor, 49);

    // Invoke const member function
    std::invoke(&DataProcessor::process_const, processor, 63);

    // Access member variable through std::invoke
    int retrieved = std::invoke(&DataProcessor::stored_value, processor);
    std::cout << "DataProcessor::stored_value = " << retrieved << std::endl;
}

void compare_calling_methods() {
    std::cout << "\n=== Comparison: Traditional vs std::invoke ===" << std::endl;

    DataProcessor processor;

    // Traditional method calls
    std::cout << "Traditional approach:" << std::endl;
    processor.process_value(1);              // Direct member call
    (processor.*&DataProcessor::process_value)(2);  // Pointer-to-member with reference
    (&processor->*&DataProcessor::process_value)(3); // Pointer-to-member with pointer

    // Unified syntax with std::invoke
    std::cout << "\nUnified std::invoke approach:" << std::endl;
    std::invoke(&DataProcessor::process_value, processor, 1);
    std::invoke(&DataProcessor::process_value, &processor, 2);
}

void integrate_with_std_function() {
    std::cout << "\n=== Integration with std::function ===" << std::endl;

    std::function<void(int)> wrapper = [](int val) {
        std::cout << "std::function wrapper: " << val << std::endl;
    };

    std::invoke(wrapper, 200);
}

void handle_reference_wrappers() {
    std::cout << "\n=== Handling std::reference_wrapper ===" << std::endl;

    DataProcessor processor;
    auto wrapped_ref = std::ref(processor);

    std::invoke(&DataProcessor::process_value, wrapped_ref, 11);
}

int main() {
    demonstrate_invoke_features();
    compare_calling_methods();
    integrate_with_std_function();
    handle_reference_wrappers();

    std::cout << "\n=== Advantages of std::invoke ===" << std::endl;
    std::cout << "- Consistent interface for invoking any callable entity" << std::endl;
    std::cout << "- Eliminates need for .* and ->* operators" << std::endl;
    std::cout << "- Seamlessly works with std::reference_wrapper" << std::endl;
    std::cout << "- Simplifies template code dealing with arbitrary callables" << std::endl;

    return 0;
}

#include "Base.h"
#include "Writer.h"

namespace Gorgon::Resource {

    // Resolve resources by traversing and processing each child
    void Base::Resolve(File &file) {
        auto current = children.Begin();
        while(current != children.End()) {
            Base &child = *current;
            ++current;  // advance before recursive call in case of modification
            child.Resolve(file);
        }
    }

    // Prepare all child resources for usage
    void Base::Prepare() {
        for(auto &child : children) {
            child.Prepare();
        }
    }

    // Discard all child resources
    void Base::Discard() {
        for(auto &child : children) {
            child.Discard();
        }
    }

    Base::Base() : Children(children) { }

    Base::~Base() {
        cleanupChildren();
    }

    // Attempt to delete this resource if reference count reaches zero
    bool Base::DeleteResource() {
        --refcount;
        if(refcount > 0)
            return false;

        delete this;
        return true;
    }

    // Safely destroy all child resources
    void Base::cleanupChildren() {
        auto iter = children.begin();
        while(iter != children.end()) {
            auto nextIter = iter;
            ++nextIter;

            if(!iter->DeleteResource()) {
                // Detach from parent to avoid dangling references
                if(iter->parent == this) {
                    iter->parent = nullptr;
                    iter->root   = nullptr;
                }
            }

            iter = nextIter;
        }

        children.clear();
    }

    // Save the resource using provided writer
    void Base::Save(Writer &writer) {
        ASSERT(writer.isAvailable(), "Writer is not ready for saving the resource");
        if(guid.isEmpty())
            guid.generate();

        doSave(writer);
    }

}

