#include <ankerl/unordered_dense.h>
#include <app/doctest.h>
#include <cstdint>
#include <memory>
#include <type_traits>

// Verify that hash of a smart pointer equals hash of its underlying raw pointer
template <typename SmartPtr>
void validate_hash_equality(SmartPtr const& smart_ptr) {
    using HashSmart = ankerl::unordered_dense::hash<SmartPtr>;
    using HashRaw = ankerl::unordered_dense::hash<decltype(smart_ptr.get())>;

    REQUIRE(HashSmart{}(smart_ptr) == HashRaw{}(smart_ptr.get()));
}

TEST_CASE("hash_smart_ptr") {
    // Test with default-constructed unique_ptr
    validate_hash_equality(std::unique_ptr<uint64_t>{});

    // Test with default-constructed shared_ptr
    validate_hash_equality(std::shared_ptr<uint64_t>{});

    // Test with shared_ptr initialized to 123U
    validate_hash_equality(std::make_shared<uint64_t>(123U));

    // Test with unique_ptr initialized to 123U
    validate_hash_equality(std::make_unique<uint64_t>(123U));

    // Test with unique_ptr explicitly constructed with uint64_t literal
    validate_hash_equality(std::make_unique<uint64_t>(static_cast<uint64_t>(123U)));
}

