#include "llvm/Analysis/IndirectCallPromotionAnalysis.h"
#include "llvm/IR/Instruction.h"
#include "llvm/ProfileData/InstrProf.h"
#include "llvm/Support/CommandLine.h"
#include "llvm/Support/Debug.h"
#include <memory>

using namespace llvm;

#define DEBUG_TYPE "pgo-icall-prom-analysis"

// Thresholds for promotion decisions — renamed options for clarity
static cl::opt<unsigned> RemainingCountPctThreshold(
    "icp-remaining-percent-threshold", cl::init(30), cl::Hidden,
    cl::desc("Minimum percentage of remaining unpromoted count required for promotion"));

static cl::opt<unsigned>
    TotalCountPctThreshold("icp-total-percent-threshold", cl::init(5),
                           cl::Hidden,
                           cl::desc("Minimum percentage of total call count required for promotion"));

// Upper bound on how many targets can be promoted per indirect call site
static cl::opt<unsigned>
    MaxTargetsToPromote("icp-max-prom", cl::init(3), cl::Hidden,
                        cl::desc("Maximum number of direct-call targets to promote per indirect call"));

// Constructor initializes internal buffer for value data storage
ICallPromotionAnalysis::ICallPromotionAnalysis() {
  CandidateBuffer = std::make_unique<InstrProfValueData[]>(MaxTargetsToPromote);
}

// Determines if promoting a specific target is beneficial based on thresholds
bool ICallPromotionAnalysis::isPromotionProfitable(uint64_t TargetCount,
                                                   uint64_t CallSiteTotal,
                                                   uint64_t UnpromotedRemaining) {
  // Check both relative thresholds: against remaining and total counts
  return (TargetCount * 100 >= RemainingCountPctThreshold * UnpromotedRemaining) &&
         (TargetCount * 100 >= TotalCountPctThreshold * CallSiteTotal);
}

// Selects top profitable candidates from sorted list of targets
// Stops when encountering first non-profitable candidate
uint32_t ICallPromotionAnalysis::getProfitablePromotionCandidates(
    const Instruction *Inst, uint32_t NumAvailable, uint64_t TotalCalls) {
  ArrayRef<InstrProfValueData> Candidates(CandidateBuffer.get(), NumAvailable);
  LLVM_DEBUG(dbgs() << "\nAnalyzing callsite:\n" << *Inst
                    << " | Targets available: " << NumAvailable << "\n");

  uint32_t SelectedIdx = 0;
  uint64_t LeftoverCount = TotalCalls;

  while (SelectedIdx < MaxTargetsToPromote && SelectedIdx < NumAvailable) {
    uint64_t CurrentCount = Candidates[SelectedIdx].Count;
    assert(CurrentCount <= LeftoverCount);

    LLVM_DEBUG(dbgs() << " Examining candidate #" << SelectedIdx
                      << " — Count=" << CurrentCount
                      << ", FuncID=" << Candidates[SelectedIdx].Value << "\n");

    if (!isPromotionProfitable(CurrentCount, TotalCalls, LeftoverCount)) {
      LLVM_DEBUG(dbgs() << " Skipping: below threshold.\n");
      break;
    }

    LeftoverCount -= CurrentCount;
    ++SelectedIdx;
  }

  return SelectedIdx;
}

// Retrieves and filters promotion candidates for a given instruction
ArrayRef<InstrProfValueData>
ICallPromotionAnalysis::getPromotionCandidatesForInstruction(
    const Instruction *Instr, uint32_t &NumValues, uint64_t &TotalCalls,
    uint32_t &NumSelected) {
  bool Success =
      getValueProfDataFromInst(*Instr, IPVK_IndirectCallTarget, MaxTargetsToPromote,
                               CandidateBuffer.get(), NumValues, TotalCalls);

  if (!Success) {
    NumSelected = 0;
    return ArrayRef<InstrProfValueData>();
  }

  NumSelected = getProfitablePromotionCandidates(Instr, NumValues, TotalCalls);
  return ArrayRef<InstrProfValueData>(CandidateBuffer.get(), NumValues);
}

