// Helper to assign shader parameters using lambda for brevity
void assignShaderParams(
    Mat::OMaterialSchema &schema,
    const std::string &shaderType,
    const std::string &shaderTarget,
    const std::vector<std::pair<std::string, double>> &floatProps,
    const std::vector<std::pair<std::string, std::string>> &stringProps)
{
    auto params = schema.getShaderParameters(shaderType, shaderTarget);
    for (const auto &p : floatProps) {
        Abc::OFloatProperty(params, p.first).set(p.second);
    }
    for (const auto &p : stringProps) {
        Abc::OStringProperty(params, p.first).set(p.second);
    }
}

void storeMaterials()
{
    Abc::OArchive archive(
        Alembic::AbcCoreOgawa::WriteArchive(), "FlattenMaterial.abc");
    Abc::OObject root(archive, Abc::kTop);

    // Create container object for materials
    Abc::OObject matContainer(root, "shaderset");

    // Define parent material
    Mat::OMaterial baseMat(matContainer, "baseMaterial");
    {
        baseMat.getSchema().setShader("prman", "surface", "paintedplastic");
        baseMat.getSchema().setShader("prman", "displacement", "knobby");

        assignShaderParams(
            baseMat.getSchema(),
            "prman",
            "surface",
            {{"Kd", 0.5}},
            {{"texname", "taco"}}
        );

        assignShaderParams(
            baseMat.getSchema(),
            "prman",
            "displacement",
            {{"height", 0.75}},
            {}
        );
    }

    // Derive child material from parent
    Mat::OMaterial derivedMat(baseMat, "derivedMaterial");
    {
        derivedMat.getSchema().setShader("prman", "surface", "betterpaintedplastic");
        assignShaderParams(
            derivedMat.getSchema(),
            "prman",
            "surface",
            {},
            {{"texname", "cheese"}}
        );
    }
}

void loadAndInspectMaterials()
{
    Abc::IArchive archive(
        Alembic::AbcCoreOgawa::ReadArchive(), "FlattenMaterial.abc");
    Abc::IObject topObj = archive.getTop();
    Abc::IObject matContainer(topObj, "shaderset");

    Mat::IMaterial baseMat(matContainer, "baseMaterial");
    Mat::IMaterial derivedMat(baseMat, "derivedMaterial");

    std::cout << "----------------------------------------\n";
    std::cout << "LOCAL\n";
    std::cout << "---------------------------\n";
    std::cout << "Local base material\n";
    std::cout << "---------------------------\n";
    printMaterialSchema(baseMat.getSchema());

    std::cout << "---------------------------\n";
    std::cout << "Local derived material\n";
    std::cout << "---------------------------\n";
    printMaterialSchema(derivedMat.getSchema());

    std::cout << "----------------------------------------\n";
    std::cout << "FLATTENED\n";
    printFlattenedMaterial(baseMat);
    printFlattenedMaterial(derivedMat);
}

int main(int argc, char *argv[])
{
    storeMaterials();
    loadAndInspectMaterials();
    return 0;
}

#include "app_state.hpp"
#include "curses_interface.hpp"
#include <boost/filesystem/operations.hpp>
#include <boost/filesystem/path.hpp>
#include <iostream>

int main(int argc, char * argv[])
{
    // Validate command-line arguments
    if (argc < 2) {
        std::cerr << "error: You must supply at least a filename.\n";
        return 1;
    }

    // Construct path from argument and verify existence
    boost::filesystem::path file_path(argv[1]);
    if (!boost::filesystem::exists(file_path)) {
        std::cerr << "error: Could not access filename " << argv[1] << ".\n";
        return 1;
    }

    // Set up locale for curses compatibility
    std::locale::global(std::locale(""));

    // Initialize the curses interface
    curses_interface_t curses_if;

    // Capture screen dimensions once (resizing unsupported)
    auto const display_dims = curses_if.screen_size();

    // Initialize application state
    app_state_t initial_state = {
        load_buffer(file_path, curses_if.screen_size().col_),
        emacs_lite()
    };

    // Perform initial rendering
    render(initial_state.buffer_, display_dims);

    // Main event loop
    boost::optional<app_state_t> updated_state;
    app_state_t current_state = std::move(initial_state);

    while (
        (updated_state = update(std::move(current_state), 
                                curses_if.next_event()))) {
        current_state = *updated_state;
        render(current_state.buffer_, display_dims);
    }

    return 0;
}

