namespace {
    ULONG_PTR g_gdiplusHandle = 0;

    class LifecycleManager : public initquit {
    public:
        void on_init() override {
            // Initialize GDI+
            Gdiplus::GdiplusStartupInput startupInfo;
            Gdiplus::GdiplusStartup(&g_gdiplusHandle, &startupInfo, nullptr);

            // Pre-warm playback state manager early to ensure callback registration
            nowbar::PlaybackStateManager::get();

            // Prepare artwork bridge for online cover support
            prepare_artwork_support();
        }

        void on_quit() override {
            // Deregister artwork callbacks first
            finalize_artwork_support();

            // Shutdown services in reverse dependency order
            // ControlPanelCore must be torn down before PlaybackStateManager
            nowbar::ControlPanelCore::cleanup();
            nowbar::PlaybackStateManager::cleanup();

            // Release GDI+ resources if initialized
            if (g_gdiplusHandle != 0) {
                Gdiplus::GdiplusShutdown(g_gdiplusHandle);
                g_gdiplusHandle = 0;
            }
        }
    };

    static initquit_factory_t<LifecycleManager> g_lifecycle_hook;
}

