namespace {
    int failureCount = 0;

    void validateCondition(bool result, const char* expr, int lineNumber) {
        if (!result) {
            std::cout << "Assertion failed: " << expr 
                      << " at line " << lineNumber << std::endl;
            if (0 <= failureCount && failureCount <= 100) {
                ++failureCount;
            }
        }
    }
}  // unnamed namespace

#define VERIFY(EXPR) \
    validateCondition((EXPR), #EXPR, __LINE__)

int main() {
    // Verification block 1: safe_pred property
    {
        VERIFY(Opaque::test_safe_pred == 4);
        std::cout << "Verification 1 (safe_pred): SUCCESS" << std::endl;
    }

    // Verification block 2: pred_of_succ property
    {
        VERIFY(Opaque::test_pred_succ == 7);
        std::cout << "Verification 2 (pred_of_succ): SUCCESS" << std::endl;
    }

    // Verification block 3: equality checks
    {
        VERIFY(Opaque::test_eq_true == true);
        VERIFY(Opaque::test_eq_false == false);
        std::cout << "Verification 3 (equality): SUCCESS" << std::endl;
