NxsBlock::NxsBlock()
	{
	next			= nullptr;
	nexus			= nullptr;
	isEmpty			= true;
	isEnabled		= true;
	isUserSupplied	= false;
	id.clear();
	errormsg.clear();
	}

/*----------------------------------------------------------------------------------------------------------------------
|	Destructor: no special cleanup required in base class.
*/
NxsBlock::~NxsBlock()
	{
	}

/*----------------------------------------------------------------------------------------------------------------------
|	Converts a character label string to its corresponding numeric index.
|	Base implementation returns 0; derived classes should override for actual functionality.
*/
unsigned NxsBlock::CharLabelToNumber(
  NxsString s)	// the character label to be translated to the character's number
	{
#	if defined(HAVE_PRAGMA_UNUSED)
#		pragma unused(s)
#	endif
	return 0u;
	}

/*----------------------------------------------------------------------------------------------------------------------
|	Disables this block so it will be ignored during file processing.
|	A disabled block triggers SkippingDisabledBlock() when encountered.
*/
void NxsBlock::Disable()
	{
	isEnabled = false;
	}

/*----------------------------------------------------------------------------------------------------------------------
|	Re-enables this block after it has been disabled.
*/
void NxsBlock::Enable()
	{
	isEnabled = true;
	}

/*----------------------------------------------------------------------------------------------------------------------
|	Returns whether this block is currently enabled (i.e., not skipped).
*/
bool NxsBlock::IsEnabled() const
	{
	return isEnabled;
	}

/*----------------------------------------------------------------------------------------------------------------------
|	Returns whether this block was populated from user-supplied data (as opposed to being auto-generated internally).
*/
bool NxsBlock::IsUserSupplied() const
	{
	return isUserSupplied;
	}

/*----------------------------------------------------------------------------------------------------------------------
|	Returns true if the block has not yet processed any data since last reset.
|	Defaults to checking isEmpty flag; derived classes must update appropriately.
*/
bool NxsBlock::IsEmpty() const
	{
	return isEmpty;
	}

/*----------------------------------------------------------------------------------------------------------------------
|	Retrieves the identifier string associated with this block.
*/
NxsString NxsBlock::GetID() const
	{
	return id;
	}

/*----------------------------------------------------------------------------------------------------------------------
|	Main parsing routine: reads and processes content following the block name.
|	Must be overridden by derived classes to implement specific block parsing logic.
*/
void NxsBlock::Read(
  NxsToken &token)	// token used for lexical analysis during parsing
	{
#	if defined(HAVE_PRAGMA_UNUSED)
#		pragma unused(token)
#	endif
	}

/*----------------------------------------------------------------------------------------------------------------------
|	Resets internal state in preparation for re-reading a block of this type.
|	Should be overridden by derived classes to clear all relevant state.
*/
void NxsBlock::Reset()
	{
	isEmpty = true;
	}

/*----------------------------------------------------------------------------------------------------------------------
|	Writes a summary report of the block's contents to the given output stream.
|	Base version does nothing; can be overridden for debugging or logging purposes.
