        Raw(TString(input).Quote());
    } else {
        Raw("(empty)");
    }
}

DBGDUMP_INLINE_IF_INCLUDED void TDumpBase::String(const TWtringBuf& wstr) {
    Raw("w");
    String(ToString(wstr));
}

DBGDUMP_INLINE_IF_INCLUDED void TDumpBase::Raw(const TStringBuf& data) {
    auto& stream = Stream();
    if (!data.empty()) {
        stream.Write(data.data(), data.length());
    }
}

DBGDUMP_INLINE_IF_INCLUDED void TDumpBase::Char(char symbol) {
    TString escaped = EscapeC(&symbol, 1);
    Raw("'" + escaped + "'");
}

DBGDUMP_INLINE_IF_INCLUDED void TDumpBase::Char(wchar16 wideChar) {
    TString escaped = EscapeC(&wideChar, 1);
    Raw("w'" + ToString(escaped) + "'");
