// Select OpenGL version — same as original, just renamed constant
constexpr int opengl_api_version = mplot::gl::version_4_1;

// Custom frame class: same purpose, rewritten structure & naming
class MyFrame : public mplot::wx::Frame<opengl_api_version>
{
public:
    MyFrame(const wxString& title) 
        : mplot::wx::Frame<opengl_api_version>(title)
        , offsetIncrement(0.0)
        , graph(nullptr)
    {
        auto mainLayout = new wxBoxSizer(wxVERTICAL);
        mainLayout->Add(this->canvas, 1, wxEXPAND);

        auto controls = new wxBoxSizer(wxHORIZONTAL);
        auto btnColor = new wxButton(this, wxID_ANY, wxT("Pick Color"));
        controls->Add(btnColor, 0, wxALL | wxALIGN_CENTER, FromDIP(15));
        controls->AddStretchSpacer();

        mainLayout->Add(controls, 0, wxEXPAND);
        SetSizerAndFit(mainLayout);

        // Bind button click to a named member function instead of lambda
        btnColor->Bind(wxEVT_BUTTON, &MyFrame::OnColorChange, this);
    }

    // Replaced dx → offsetIncrement; x remains same type
    sm::vvec<double> abscissa;
    double offsetIncrement;

    mplot::GraphVisual<double, opengl_api_version>* graph;

    // Renamed updateModel() → refreshGraph()
    void refreshGraph()
    {
        offsetIncrement += 0.01;
        // Use std::transform-like semantics via expression template
        auto shiftedX = abscissa + offsetIncrement;
        auto newY = shiftedX.sin();
        graph->update(abscissa, newY, 0);
        canvas->needs_reinit = 0;
    }

    // Renamed setupVisualModels() → initializeRendering()
    void initializeRendering()
    {
        if (!canvas->ready()) {
            throw std::runtime_error("OpenGL context not yet initialized");
        }

        auto gv = std::make_unique<mplot::GraphVisual<double, opengl_api_version>>(
            sm::vec<float>({0.0f, 0.0f, 0.0f})
        );

        canvas->v.bindmodel(gv);
        gv->twodimensional(false);

        // Initialize x-axis points using range-based loop alternative
        const double pi = sm::mathconst<double>::pi;
        const int N = 100;
        abscissa.resize(N);
        double step = 2 * pi / (N - 1);
        for (int i = 0; i < N; ++i) {
            abscissa[i] = -pi + i * step;
        }

        // Initial y = sin(x + offset)
        auto initialY = (abscissa + offsetIncrement).sin();
        gv->setdata(abscissa, initialY);
        gv->finalize();

        graph = canvas->v.addVisualModel(std::move(gv));
    }

private:
    void OnColorChange([[maybe_unused]] wxCommandEvent& evt)
    {
        wxColourData data;
        wxColourDialog dlg(this, &data);
        if (dlg.ShowModal() == wxID_OK) {
            canvas->Refresh();
        }
    }
};

// Application class — minimal change, renamed constructor body
class MyApp : public wxApp
{
public:
    bool OnInit() override
    {
        if (!wxApp::OnInit()) return false;

        auto frame = new MyFrame(wxT("Interactive Plot"));
        frame->Show(true);
        frame->initializeRendering(); // renamed method call

        return true;
    }
};

wxIMPLEMENT_APP(MyApp);

