#include "Transform/LowerSelect.h"
#include <llvm/IR/Constants.h>
#include <llvm/IR/Instructions.h>
#include <llvm/IR/Verifier.h>
#include <llvm/Support/Debug.h>
#define DEBUG_TYPE "lower-select"

// Convert a select instruction to conditional branches + phi node
static void lowerSelectToBranches(Instruction *Sel) {
  Function *Func = Sel->getFunction();
  BasicBlock *OrigBB = Sel->getParent();

  // Split the original block after the select instruction
  BasicBlock *MergeBB = OrigBB->splitBasicBlock(Sel, "");

  // Create two new blocks for true/false outcomes
  BasicBlock *ThenBB = BasicBlock::Create(Sel->getContext(), "select.true", Func, MergeBB);
  BasicBlock *ElseBB = BasicBlock::Create(Sel->getContext(), "select.false", Func, MergeBB);

  // Add unconditional branches from both new blocks to the merge block
  BranchInst::Create(MergeBB, ThenBB);
  BranchInst::Create(MergeBB, ElseBB);

  // Replace original terminator with conditional branch based on condition operand
  OrigBB->getTerminator()->eraseFromParent();
  BranchInst::Create(ThenBB, ElseBB, Sel->getOperand(0), OrigBB);

  // Build phi node in merge block to unify results
  PHINode *ResultPhi = PHINode::Create(Sel->getType(), 2, "", Sel);
  ResultPhi->addIncoming(Sel->getOperand(1), ThenBB);
  ResultPhi->addIncoming(Sel->getOperand(2), ElseBB);

  // Redirect all uses of select to phi, then remove select
  Sel->replaceAllUsesWith(ResultPhi);
  Sel->eraseFromParent();
}

// Pass entry point: collect non-pointer selects and transform them
PreservedAnalyses LowerSelectPass::run(Module &Mod, ModuleAnalysisManager &) {
  std::vector<SelectInst *> Candidates;

  // Traverse module, functions, blocks, and instructions
  for (auto &F : Mod) {
    for (auto &B : F) {
      for (auto &I : B) {
        if (I.getType()->isPointerTy())
          continue;
        if (SelectInst *SI = dyn_cast<SelectInst>(&I)) {
          Candidates.push_back(SI);
        }
      }
    }
  }

  if (Candidates.empty())
    return PreservedAnalyses::all();

  // Apply transformation to each candidate
  for (SelectInst *Sel : Candidates)
    lowerSelectToBranches(Sel);

  // Verify module integrity post-transformation
  if (verifyModule(Mod, &errs())) {
    llvm_unreachable("Error: Lowerselect fails...");
  }

  // CFG changed — preserve nothing
  return PreservedAnalyses::none();
}

#include <iostream>
#include <vector>
#include <string>
using namespace std;

int main() {
    // Speed up I/O operations
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int participants, rounds;
    if (cin >> participants >> rounds) {
        // Initialize weights for each participant
        vector<double> weights(participants, 1.0);

        // Decay factor for incorrect predictions
        const double decay = 0.9;

        string responses;
        responses.reserve(participants);

        for (int round = 0; round < rounds; ++round) {
            cin >> responses;

            double weightZero = 0.0;
            double weightOne = 0.0;

            // Compute weighted votes for both outcomes
            for (int i = 0; i < participants; ++i) {
                if (responses[i] == '0') {
                    weightZero += weights[i];
                } else {
                    weightOne += weights[i];
                }
            }

            // Make prediction based on higher weight
            int predicted = (weightOne > weightZero) ? 1 : 0;
            cout << predicted << '\n';

            int actual;
            cin >> actual;

            // Adjust weights of participants who were wrong
            for (int i = 0; i < participants; ++i) {
                int choice = responses[i] - '0';
                if (choice != actual) {
                    weights[i] *= decay;
                }
            }

            // Prevent underflow by rescaling if needed
            double highestWeight = 0.0;
            for (double w : weights) {
                if (w > highestWeight) {
                    highestWeight = w;
                }
            }

            if (highestWeight < 1e-150) {
                for (int i = 0; i < participants; ++i) {
                    weights[i] *= 1e150;
                }
            }
        }
    }

    return 0;
}

#include <gtest/gtest.h>
#include <jonssonic/core/common/circular_audio_buffer.h>

using namespace jnsc;

// Test basic resize and immediate read/write operations
TEST(CircularAudioBufferTest, ResizeAndWriteRead) {
    CircularAudioBuffer<float> audioBuffer;
    audioBuffer.resize(2, 8);

    ASSERT_EQ(audioBuffer.getNumChannels(), 2u);
    ASSERT_EQ(audioBuffer.getBufferSize(), 8u);

    // Write sample values to each channel
    audioBuffer.write(0, 1.0f);
    audioBuffer.write(1, 2.0f);

    // Verify the written values can be read back correctly
    EXPECT_FLOAT_EQ(audioBuffer.read(0, 0), 1.0f);
    EXPECT_FLOAT_EQ(audioBuffer.read(1, 0), 2.0f);
}

// Test buffer wrap-around behavior when writing beyond capacity
TEST(CircularAudioBufferTest, WrapAround) {
    CircularAudioBuffer<float> audioBuffer;
    audioBuffer.resize(1, 4);

    // Write six samples into a size-4 buffer (should overwrite oldest)
    for (int idx = 0; idx < 6; ++idx)
        audioBuffer.write(0, static_cast<float>(idx));

    // After wrapping: most recent is 5, then 4, 3, 2 (oldest overwritten)
    EXPECT_FLOAT_EQ(audioBuffer.read(0, 0), 5.0f);
    EXPECT_FLOAT_EQ(audioBuffer.read(0, 1), 4.0f);
    EXPECT_FLOAT_EQ(audioBuffer.read(0, 2), 3.0f);
    EXPECT_FLOAT_EQ(audioBuffer.read(0, 3), 2.0f);
}

// Test clear functionality followed by new writes
TEST(CircularAudioBufferTest, Clear) {
    CircularAudioBuffer<float> audioBuffer;
    audioBuffer.resize(1, 4);

    // Fill buffer with initial data
    audioBuffer.write(0, 1.0f);
    audioBuffer.write(0, 2.0f);

    // Clear buffer contents
    audioBuffer.clear();

    // Write new value after clearing
    audioBuffer.write(0, 3.0f);

    // Verify only new value is present
    EXPECT_FLOAT_EQ(audioBuffer.read(0, 0), 3.0f);
}

// Test multi-channel buffer behavior with interleaved writes
TEST(CircularAudioBufferTest, MultiChannel) {
    CircularAudioBuffer<float> audioBuffer;
    audioBuffer.resize(2, 4);

    // Interleave writes across channels
    for (int idx = 0; idx < 4; ++idx) {
        audioBuffer.write(0, static_cast<float>(idx));
        audioBuffer.write(1, static_cast<float>(idx + 10));
    }

    // Verify latest values per channel
    EXPECT_FLOAT_EQ(audioBuffer.read(0, 0), 3.0f);   // Last written to ch0
    EXPECT_FLOAT_EQ(audioBuffer.read(1, 0), 13.0f);  // Last written to ch1

    // Verify oldest values still accessible at end of buffer
    EXPECT_FLOAT_EQ(audioBuffer.read(0, 3), 0.0f);   // First written to ch0
    EXPECT_FLOAT_EQ(audioBuffer.read(1, 3), 10.0f);  // First written to ch1
}

