using namespace llvm;

namespace {

// Helper template to build a chain of plugins with compile-time composition
template <typename...> class PluginChain;

// Final plugin chain type used by ValueProfileCollectorImpl
using PluginChainFinal = PluginChain<VP_PLUGIN_LIST>;

// Base case: empty plugin chain — does nothing
template <>
class PluginChain<> {
public:
  PluginChain(Function &, TargetLibraryInfo &) {}

  void collect(InstrProfValueKind K, std::vector<CandidateInfo> &out) {
    // No-op: no plugins to run
  }
};

// Recursive case: process first plugin, delegate rest to base
template <typename FirstPlugin, typename... Rest>
class PluginChain<FirstPlugin, Rest...> : private PluginChain<Rest...> {
  using Base = PluginChain<Rest...>;
  FirstPlugin instance;

public:
  PluginChain(Function &F, TargetLibraryInfo &TLI)
      : Base(F, TLI), instance(F, TLI) {}

  void collect(InstrProfValueKind K, std::vector<CandidateInfo> &out) {
    // If this plugin handles the current kind, invoke its run method
    if constexpr (K == FirstPlugin::Kind) {
      instance.run(out);
    }
    // Delegate remaining work to the rest of the chain
    Base::collect(K, out);
  }
};

} // end anonymous namespace

// Implementation class inherits from the final plugin chain
class ValueProfileCollector::ValueProfileCollectorImpl 
    : public PluginChainFinal {
public:
  using PluginChainFinal::PluginChainFinal;
};

// Public constructor delegates to implementation
ValueProfileCollector::ValueProfileCollector(Function &F,
                                             TargetLibraryInfo &TLI)
    : PImpl(std::make_unique<ValueProfileCollectorImpl>(F, TLI)) {}

// Destructor uses default (unique_ptr manages lifetime)
ValueProfileCollector::~ValueProfileCollector() = default;

// Public API: retrieve candidates for a given value kind
std::vector<CandidateInfo>
ValueProfileCollector::get(InstrProfValueKind Kind) const {
  std::vector<CandidateInfo> output;
  PImpl->collect(Kind, output);
  return output;
}

#include <iostream>
#include <vector>
#include <string>
using namespace std;

int main() {
    // Grid dimensions
    int rows = 20;
    int cols = 20;

    // Output the grid size
    cout << rows << " " << cols << endl;

    // Initialize a 2D grid filled with walls ('0')
    vector<string> maze(rows, string(cols, '0'));

    // Create horizontal pathways on even-numbered rows (0, 2, ..., 18)
    for (int r = 0; r <= 18; r += 2) {
        for (int c = 0; c < cols; ++c) {
            maze[r][c] = '1';
        }
    }

    // Connect adjacent horizontal paths using vertical links in odd rows
    // Alternate connection points: right side for first pair, left for next, etc.
    for (int r = 0; r < 18; r += 2) {
        int pairIndex = r / 2;
        if (pairIndex % 2 == 0) {
            // Even-indexed pair: connect at the rightmost column
            maze[r + 1][cols - 1] = '1';
        } else {
            // Odd-indexed pair: connect at the leftmost column
            maze[r + 1][0] = '1';
        }
    }

    // Add dead-end branches ("teeth") from the bottom corridor (row 18)
    // Place them only at even column indices to avoid creating cycles
    for (int c = 0; c < cols; c += 2) {
        maze[rows - 1][c] = '1';
    }

    // Display the final maze layout
    for (int i = 0; i < rows; ++i) {
        cout << maze[i] << '\n';
    }

    return 0;
}

