#include <iostream>
#include <vector>
#include <cmath>

// Maximum possible XOR value for n <= 10^7 (since 2^24 > 10^7)
const int MAX_XOR_VAL = 1 << 24;

// Static boolean array to track which XOR values have been seen
bool xor_seen[MAX_XOR_VAL] = {false};

int main() {
    // Optimize I/O performance
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int n;
    std::cin >> n;

    std::vector<int> selected_numbers;
    selected_numbers.reserve(3000);  // Pre-allocate space for efficiency

    // Greedily construct the set by checking XOR uniqueness
    for (int current = 1; current <= n; ++current) {
        bool is_valid = true;

        // Check if 'current' would create a duplicate XOR with existing elements
        for (int existing : selected_numbers) {
            if (xor_seen[current ^ existing]) {
                is_valid = false;
                break;
            }
        }

        if (is_valid) {
            // Mark all new XORs formed with 'current'
            for (int existing : selected_numbers) {
                xor_seen[current ^ existing] = true;
            }
            selected_numbers.push_back(current);
        }
    }

    // Output the size and elements of the resulting set
    std::cout << selected_numbers.size() << "\n";
    for (size_t idx = 0; idx < selected_numbers.size(); ++idx) {
        std::cout << selected_numbers[idx];
        if (idx != selected_numbers.size() - 1) {
            std::cout << " ";
        }
    }
    std::cout << "\n";

    return 0;
}

