using namespace llvm;

// Constructor initializes the assembler interface
WinCFGuard::WinCFGuard(AsmPrinter *printer) : Asm(printer) {}

// Destructor — default behavior
WinCFGuard::~WinCFGuard() = default;

// Collect longjmp targets from each function into module-wide list
void WinCFGuard::endFunction(const MachineFunction *func) {
  // Skip processing if no longjmp targets exist in this function
  if (func->getLongjmpTargets().empty())
    return;

  // Append current function’s targets to global collection
  LongjmpTargets.insert(LongjmpTargets.end(),
                        func->getLongjmpTargets().begin(),
                        func->getLongjmpTargets().end());
}

// Determine whether a function may be invoked indirectly (e.g., via pointer)
static bool mightBeIndirectCallTarget(const Function *F) {
  SmallVector<const Value *, 4> worklist{F};
  while (!worklist.empty()) {
    const Value *current = worklist.pop_back_val();
    for (const Use &use : current->uses()) {
      const User *user = use.getUser();

      // Ignore block addresses — not relevant for indirect calls
      if (isa<BlockAddress>(user))
        continue;

      // Check call sites: if operand isn't used as callee, it's an escape
      if (const auto *call = dyn_cast<CallBase>(user)) {
        if (!call->isCallee(&use))
          return true;
      }
      // Any other instruction usage implies potential escape
      else if (isa<Instruction>(user)) {
        return true;
      }
      // Handle constants: only preserve casts that strip to original function
      else if (const auto *constant = dyn_cast<Constant>(user)) {
        if (constant->stripPointerCasts() == F) {
          worklist.push_back(user);
        } else {
          return true; // e.g., vtable initializer or unrelated cast
        }
      }
    }
  }
  return false;
}

// Helper: resolve corresponding __imp_ symbol if present
MCSymbol *WinCFGuard::resolveImportSymbol(const MCSymbol *sym) {
  StringRef name = sym->getName();
  if (name.startswith("__imp_"))
    return nullptr;
  return Asm->OutContext.lookupSymbol(("__imp_" + name).str());
}

// Final pass over module: emit .gfids, .giats, and .gljmp sections
void WinCFGuard::endModule() {
  const Module *mod = Asm->MMI->getModule();
  std::vector<const MCSymbol *> gfidsSymbols;
  std::vector<const MCSymbol *> giatsSymbols;

  // Scan all functions for those potentially called indirectly
  for (const Function &func : *mod) {
    if (mightBeIndirectCallTarget(&func)) {
      // For dllimport functions, also record their __imp_ symbols
      if (func.hasDLLImportStorageClass()) {
        MCSymbol *impSym = resolveImportSymbol(Asm->getSymbol(&func));
        if (impSym)
          giatsSymbols.push_back(impSym);
      }

      // Always include the actual function symbol in .gfids
      gfidsSymbols.push_back(Asm->getSymbol(&func));
    }
  }

  // Early exit if nothing to emit
  if (gfidsSymbols.empty() && giatsSymbols.empty() && LongjmpTargets.empty())
    return;

  MCStreamer &streamer = *Asm->OutStreamer;
  MCContext &context = Asm->OutContext;
  const MCObjectFileInfo *objInfo = context.getObjectFileInfo();

  // Emit .gfids section entries
  streamer.switchSection(objInfo->getGFIDsSection());
  for (const MCSymbol *sym : gfidsSymbols)
    streamer.emitCOFFSymbolIndex(sym);

  // Emit .giats section entries
  streamer.switchSection(objInfo->getGIATsSection());
  for (const MCSymbol *sym : giatsSymbols)
    streamer.emitCOFFSymbolIndex(sym);

  // Emit .gljmp section entries
  streamer.switchSection(objInfo->getGLJMPSection());
  for (const MCSymbol *sym : LongjmpTargets)
    streamer.emitCOFFSymbolIndex(sym);
}

