void findImpostor() {
    int size;
    if (!(cin >> size)) return;

    // Create list of player IDs from 1 to size
    vector<int> players(size);
    iota(players.begin(), players.end(), 1);

    // Shuffle players to randomize order for efficiency
    mt19937 generator(chrono::steady_clock::now().time_since_epoch().count());
    shuffle(players.begin(), players.end(), generator);

    int impostor = -1;

    // Process players in adjacent pairs
    int pairLimit = size - (size % 2);

    for (int idx = 0; idx < pairLimit; idx += 2) {
        int first = players[idx];
        int second = players[idx + 1];

        // Get mutual accusations
        int opinion1 = query(first, second); // first's view of second
        int opinion2 = query(second, first); // second's view of first

        if (opinion1 != opinion2) {
            // Found the asymmetric pair containing the impostor

            // Choose a reliable witness (not in current pair)
            int witness;
            if (idx == 0) {
                witness = players[2]; // safe since n >= 3
            } else {
                witness = players[0]; // first element is safe
            }

            // Ask both suspects about the witness
            int suspect1View = query(first, witness);
            int suspect2View = query(second, witness);

            if (suspect1View != suspect2View) {
                // Case: One is Knight (truth-teller), one is Impostor (liar)
                // Knight says truth about witness, Impostor lies
                // In original comparison: Knight sees Impostor as Knight (1), 
                // Impostor sees Knight as Knight but lies (0)
                impostor = (opinion1 == 0) ? first : second;
            } else {
                // Case: One is Knave (always lies), one is Impostor (also lies)
                // Both lie about witness, so same answer
                // In original comparison: Knave sees Impostor as Knight, lies (0),
                // Impostor sees Knave as Knave, lies (1)
                impostor = (opinion1 == 1) ? first : second;
            }

            cout << "! " << impostor << endl;
            return;
        }
    }

    // If no asymmetric pair found, the last unpaired player must be the impostor
    if (size % 2 == 1) {
        cout << "! " << players.back() << endl;
    }
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int testCases;
    if (cin >> testCases) {
        while (testCases--) {
            findImpostor();
        }
    }

    return 0;
}

