class SeqArrangeJob::Impl
{
public:
    std::unique_ptr<SeqArrange> m_impl;
    Impl(const Model& model, const DynamicPrintConfig& cfg, bool only_current_bed)
        : m_impl(std::make_unique<SeqArrange>(model, cfg, only_current_bed)) {}
};

SeqArrangeJob::SeqArrangeJob(const Model &model, const DynamicPrintConfig &config, bool current_bed_only)
    : pimpl(std::make_unique<Impl>(model, config, current_bed_only))
{}

void SeqArrangeJob::process(Ctl &ctl)
{
    struct CancelledException : public std::exception {};

    try {
        pimpl->m_impl->process_seq_arrange(
            [&](int step) {
                ctl.update_status(step, _u8L("Arranging for sequential print"));
                if (ctl.was_canceled())
                    throw CancelledException{};
            }
        );
    }
    catch (const CancelledException&) {
        ctl.update_status(100, ""); // Clear status after cancellation
    }
    catch (const std::exception&) {
        ctl.update_status(100, ""); // Clear status before rethrowing
        throw;
    }
}

void SeqArrangeJob::finalize(bool was_cancelled, std::exception_ptr &err)
{
    bool had_error = false;

    if (err) {
        try {
            std::rethrow_exception(err);
        }
        catch (const ExceptionCannotApplySeqArrange &) {
            ErrorDialog(wxGetApp().plater(),
                        _L("The result of the single-bed arrange would scatter "
                           "instances of a single object between several beds, possibly affecting order of printing "
                           "of the non-selected beds. Consider using global arrange across all beds."),
                        false).ShowModal();
            had_error = true;
            err = nullptr;
        }
        catch (const Sequential::ObjectTooLargeException &) {
            ErrorDialog(wxGetApp().plater(), _L("One of the objects is too large to fit the bed."), false).ShowModal();
            had_error = true;
            err = nullptr;
        }
        catch (const std::runtime_error &ex) {
            ErrorDialog(wxGetApp().plater(), GUI::format_wxstr(_L("Internal error: %1%"), ex.what()), false).ShowModal();
            had_error = true;
            err = nullptr;
        }
    }

    if (!was_cancelled && !had_error) {
        Plater::TakeSnapshot snap(wxGetApp().plater(), _u8L("Arrange for sequential print"));
        pimpl->m_impl->apply_seq_arrange(wxGetApp().model());
        wxGetApp().plater()->canvas3D()->reload_scene(true, true);
        wxGetApp().obj_list()->update_after_undo_redo();
    }

    pimpl.reset();
}

