/**
 * Module implementation for Android target platform support.
 */
class FAndroidTargetPlatformModule : public IAndroidTargetPlatformModule
{
public:
	/**
	 * Destructor - cleans up allocated target platforms.
	 */
	~FAndroidTargetPlatformModule() override
	{
		for (ITargetPlatform* Platform : TargetPlatforms)
		{
			delete Platform;
		}
		TargetPlatforms.Reset();
		SinglePlatforms.Reset();
		MultiPlatforms.Reset();
	}

	// Begin ITargetPlatformModule interface
	virtual TArray<ITargetPlatform*> GetTargetPlatforms() override
	{
		if (TargetPlatforms.IsEmpty() && FAndroidTargetPlatform::IsUsable())
		{
			// Create platforms for both client and server configurations
			for (int32 ConfigIndex = 0; ConfigIndex < 2; ++ConfigIndex)
			{
				const bool bIsClientMode = (ConfigIndex == 1);

				// Add single-format platforms for each texture compression type
				SinglePlatforms.Emplace(new FAndroidTargetPlatform(bIsClientMode));
				SinglePlatforms.Emplace(new FAndroid_ASTCTargetPlatform(bIsClientMode));
				SinglePlatforms.Emplace(new FAndroid_DXTTargetPlatform(bIsClientMode));
				SinglePlatforms.Emplace(new FAndroid_ETC2TargetPlatform(bIsClientMode));

				// Track multi-format platform separately for later initialization
				MultiPlatforms.Emplace(new FAndroid_MultiTargetPlatform(bIsClientMode));
			}

			// Combine all platforms into the main list
			TargetPlatforms.Append(SinglePlatforms);
			TargetPlatforms.Append(MultiPlatforms);

			// Finalize multi-platform configuration after all platforms exist
			NotifyMultiSelectedFormatsChanged();
		}

		return TargetPlatforms;
	}

	virtual void NotifyMultiSelectedFormatsChanged() override
	{
		for (FAndroid_MultiTargetPlatform* MultiPlatform : MultiPlatforms)
		{
			MultiPlatform->InitializeFromFormats(SinglePlatforms);
		}
		// @todo multi needs to be passed this event!
	}
	// End ITargetPlatformModule interface

	// Begin IModuleInterface interface
	virtual void StartupModule() override { }
	virtual void ShutdownModule() override { }
	// End IModuleInterface interface

private:
	/** Collection of all active target platforms */
	TArray<ITargetPlatform*> TargetPlatforms;

	/** Single-format Android platforms (ASTC, DXT, ETC2, base) */
	TArray<FAndroidTargetPlatform*> SinglePlatforms;

	/** Multi-format Android platforms that combine multiple texture formats */
	TArray<FAndroid_MultiTargetPlatform*> MultiPlatforms;
};

#undef LOCTEXT_NAMESPACE

