#include "llvm/Analysis/ScalarEvolutionNormalization.h"
#include "llvm/Analysis/LoopInfo.h"
#include "llvm/Analysis/ScalarEvolution.h"
#include "llvm/Analysis/ScalarEvolutionExpressions.h"

using namespace llvm;

enum class TransformAction {
  NormalizeExpr,
  DenormalizeExpr
};

namespace {

class ExprTransformer : public SCEVRewriteVisitor<ExprTransformer> {
  const TransformAction Action;
  const NormalizePredTy Predicate;

public:
  ExprTransformer(TransformAction A, NormalizePredTy P, ScalarEvolution &SE)
      : SCEVRewriteVisitor<ExprTransformer>(SE), Action(A), Predicate(P) {}

  const SCEV *visitAddRecExpr(const SCEVAddRecExpr *Expr);
};

} // namespace

const SCEV *ExprTransformer::visitAddRecExpr(const SCEVAddRecExpr *AR) {
  SmallVector<const SCEV *, 8> TransformedOps;
  std::transform(AR->op_begin(), AR->op_end(), std::back_inserter(TransformedOps),
                 [this](const SCEV *Op) { return this->visit(Op); });

  if (!Predicate(AR))
    return SE.getAddRecExpr(TransformedOps, AR->getLoop(), SCEV::FlagAnyWrap);

  if (Action == TransformAction::DenormalizeExpr) {
    // Partial increment: accumulate forward through operands
    for (size_t idx = 0; idx + 1 < TransformedOps.size(); ++idx) {
      TransformedOps[idx] = SE.getAddExpr(TransformedOps[idx], TransformedOps[idx + 1]);
    }
  } else {
    assert(Action == TransformAction::NormalizeExpr && "Invalid action kind");

    // Partial decrement: process from right to left, subtracting next operand
    for (ptrdiff_t idx = static_cast<ptrdiff_t>(TransformedOps.size()) - 2;
         idx >= 0; --idx) {
      TransformedOps[idx] = SE.getMinusSCEV(TransformedOps[idx], TransformedOps[idx + 1]);
    }
  }

  return SE.getAddRecExpr(TransformedOps, AR->getLoop(), SCEV::FlagAnyWrap);
}

const SCEV *llvm::normalizeForPostIncUse(const SCEV *Expr,
                                         const PostIncLoopSet &TargetLoops,
                                         ScalarEvolution &SE,
                                         bool RequireInvertible) {
  if (TargetLoops.empty())
    return Expr;

  auto LoopMatches = [&](const SCEVAddRecExpr *AR) {
    return TargetLoops.contains(AR->getLoop());
  };

  const SCEV *Normalized =
      ExprTransformer(TransformAction::NormalizeExpr, LoopMatches, SE).visit(Expr);

  const SCEV *Reconstructed =
      denormalizeForPostIncUse(Normalized, TargetLoops, SE);

  if (RequireInvertible && Reconstructed != Expr)
    return nullptr;

  return Normalized;
}

const SCEV *llvm::normalizeForPostIncUseIf(const SCEV *Expr,
                                           NormalizePredTy Pred,
                                           ScalarEvolution &SE) {
  return ExprTransformer(TransformAction::NormalizeExpr, Pred, SE).visit(Expr);
}

const SCEV *llvm::denormalizeForPostIncUse(const SCEV *Expr,
                                           const PostIncLoopSet &TargetLoops,
                                           ScalarEvolution &SE) {
  if (TargetLoops.empty())
    return Expr;

  auto LoopMatches = [&](const SCEVAddRecExpr *AR) {
    return TargetLoops.contains(AR->getLoop());
  };

  return ExprTransformer(TransformAction::DenormalizeExpr, LoopMatches, SE).visit(Expr);
}

