// Helper to expose static tokens as Python strings. Since direct wrapping
// of TfToken via def_readonly fails due to missing Python type conversion,
// we use a callable wrapper that returns the underlying string representation.
class _StaticTokenAccessor {
public:
    explicit _StaticTokenAccessor(const TfToken* tokenPtr) : _pToken(tokenPtr) {}

    std::string operator()() const {
        return _pToken->AsString();
    }

private:
    const TfToken* _pToken;
};

template <typename ClassType>
void
_RegisterToken(ClassType& pyClass, const char* propertyName, const TfToken& tokenRef)
{
    pyClass.add_static_property(propertyName,
        boost::python::make_function(
            _StaticTokenAccessor(&tokenRef),
            boost::python::return_value_policy<boost::python::return_by_value>(),
            boost::mpl::vector1<std::string>()
        )
    );
}
