XmlFuseWriter::XmlFuseWriter(QFile &rFile) : XflXmlWriter(rFile)
{
}

void XmlFuseWriter::writeHeader()
{
    writeDTD("<!DOCTYPE flow5>");
    writeStartElement("xflfuse");
    writeAttribute("version", "1.0");

    writeStartElement("Units");
    {
        // Compute inverse conversion factors explicitly
        double const lenFactor = 1.0 / Units::mtoUnit();
        double const massFactor = 1.0 / Units::kgtoUnit();

        std::ostringstream ossLen;
        ossLen << lenFactor;
        writeTextElement("length_unit_to_meter", QString::fromStdString(ossLen.str()));

        std::ostringstream ossMass;
        ossMass << massFactor;
        writeTextElement("mass_unit_to_kg", QString::fromStdString(ossMass.str()));
    }
    writeEndElement();
}

void XmlFuseWriter::writeXMLFuse(FuseXfl const *pInertialComponent)
{
    writeStartDocument();
    writeHeader();

    writeStartElement("xflfuse");
    {
        writeTextElement("Name", pInertialComponent->name());
        writeTextElement("Description", pInertialComponent->description());

        writeComment("When AUTOINERTIA is enabled, COG and COG_I** entries are disregarded");
        writeTextElement("AutoInertia", xfl::boolToString(pInertialComponent->bAutoInertia()));

        writeInertia(pInertialComponent->inertia());
        writeEndElement(); // closes inner "xflfuse" start element

        writeXflFuse(*pInertialComponent, Vector3d{});
    }
    writeEndElement(); // closes outer "xflfuse"
    writeEndDocument();
}

#include "layoutmanager.hpp"

Rect::Rect(float x, float y, float width, float height) 
    : x(x), y(y), width(width), height(height) { }

LayoutManager::LayoutManager(float x, float y, float width, float height) 
    : m_current(x, y, width, height) { }

const Rect& LayoutManager::current() const {
    return m_current;
}

LayoutManager LayoutManager::copy() const {
    return LayoutManager(m_current.x, m_current.y, m_current.width, m_current.height);
}

void LayoutManager::pad(float padding) {
    pad(padding, padding);
}

void LayoutManager::pad(float paddingY, float paddingX) {
    // Adjust rectangle inward by padding on all sides
    m_current.x += paddingX;
    m_current.y += paddingY;
    m_current.width -= 2 * paddingX;
    m_current.height -= 2 * paddingY;
}

void LayoutManager::padLeft(float padding) {
    m_current.x += padding;
    m_current.width -= padding;
}

void LayoutManager::padRight(float padding) {
    m_current.width -= padding;
}

void LayoutManager::padUp(float padding) {
    m_current.y += padding;
    m_current.height -= padding;
}

void LayoutManager::padDown(float padding) {
    m_current.height -= padding;
}

void LayoutManager::border(float border_size) {
    // Apply uniform border inset
    m_current.x += border_size;
    m_current.y += border_size;
    m_current.width -= 2 * border_size;
    m_current.height -= 2 * border_size;
}

void LayoutManager::gapX(float gap_size) {
    m_current.x += gap_size;
    m_current.width -= gap_size;
}

void LayoutManager::gapY(float gap_size) {
    m_current.y += gap_size;
    m_current.height -= gap_size;
}

LayoutManager LayoutManager::sliceTop(float height) {
    LayoutManager slice(m_current.x, m_current.y, m_current.width, height);
    // Move the current rectangle down and reduce its height
    m_current.y += height;
    m_current.height -= height;
    return slice;
}

LayoutManager LayoutManager::sliceLeft(float width) {
    LayoutManager slice(m_current.x, m_current.y, width, m_current.height);
    // Move the current rectangle right and reduce its width
    m_current.x += width;
    m_current.width -= width;
    return slice;
}

#include <bits/stdc++.h>
using namespace std;

// Alternative constructive solution for generating a grid with exactly x paths
// Uses a similar snake-like pattern but with modified indexing and bit handling
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long target;
    if (!(cin >> target)) return 0;

    const int GRID_SIZE = 65;
    vector<vector<int>> grid(GRID_SIZE, vector<int>(GRID_SIZE, 0));

    // Build base snake structure: alternating left/right segments per row
    for (int row = 1; row <= GRID_SIZE; ++row) {
        if (row % 2 == 1) {
            // Odd rows: fill from left side up to 'row' columns
            for (int col = 0; col < row; ++col) {
                grid[row-1][col] = 1;
            }
        } else {
            // Even rows: fill from right side starting at column (GRID_SIZE - row + 1)
            for (int col = GRID_SIZE - row; col < GRID_SIZE; ++col) {
                grid[row-1][col] = 1;
            }
        }
    }

    // Adjust for the target path count by setting additional cells based on binary representation
    long long remaining = target - 1;
    for (int row = 2; row <= GRID_SIZE; ++row) {
        if (remaining & 1LL) {
            if (row % 2 == 1) {
                // For odd rows, extend rightward beyond the initial segment
                for (int col = row; col < GRID_SIZE; ++col) {
                    grid[row-1][col] = 1;
                }
            } else {
                // For even rows, extend leftward beyond the initial segment
                for (int col = 0; col < GRID_SIZE - row + 1; ++col) {
                    grid[row-1][col] = 1;
                }
            }
        }
        remaining >>= 1;
        if (remaining == 0) break;
    }

    cout << GRID_SIZE << "\n";
    for (int i = 0; i < GRID_SIZE; ++i) {
        for (int j = 0; j < GRID_SIZE; ++j) {
            cout << grid[i][j];
            if (j < GRID_SIZE - 1) cout << " ";
        }
        cout << "\n";
    }

    return 0;
}

