#include <iostream>
#include <boost/array.hpp>
#include <asio.hpp>

int main(int argc, char* argv[])
{
  try
  {
    if (argc != 2)
    {
      std::cerr << "Usage: client <host>" << std::endl;
      return 1;
    }

    asio::io_context io_context;
    asio::ip::udp::resolver resolver(io_context);

    // Resolve the daytime service for the given host
    auto endpoints = resolver.resolve(asio::ip::udp::v4(), argv[1], "daytime");
    asio::ip::udp::endpoint receiver_endpoint = *endpoints.begin();

    asio::ip::udp::socket socket(io_context);
    socket.open(asio::ip::udp::v4());

    // Send a single null byte to trigger the daytime response
    boost::array<char, 1> send_buffer = {{ '\0' }};
    socket.send_to(asio::buffer(send_buffer), receiver_endpoint);

    // Prepare buffer to receive the time string
    boost::array<char, 128> receive_buffer;
    asio::ip::udp::endpoint sender_address;
    size_t bytes_received = socket.receive_from(
        asio::buffer(receive_buffer), sender_address);

    // Output the received time string
    std::cout.write(receive_buffer.data(), bytes_received);
  }
  catch (const std::exception& exception)
  {
    std::cerr << "Error: " << exception.what() << std::endl;
    return 1;
  }

  return 0;
}

#include <iostream>
#include <string>
#include <unordered_map>
#include <vector>

// Send a "move" command with step size x and get the resulting node
int move_step(long long step_size) {
    std::cout << "move " << step_size << std::endl;
    int next_node;
    std::cin >> next_node;
    return next_node;
}

// Report our guess for the cycle length n
void report_guess(long long candidate_n) {
    std::cout << "answer " << candidate_n << std::endl;
}

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    // Choose block size B ~ sqrt(1e9), using 32000 as in original
    const int BLOCK_SIZE = 32000;

    // Get initial position without moving (equivalent to walk(0))
    int start_pos = move_step(0);

    // --- Phase 1: Small steps (baby steps) ---
    std::unordered_map<int, int> visited_positions;
    int current_pos = start_pos;

    // Take up to BLOCK_SIZE single-step moves
    for (int step_count = 1; step_count <= BLOCK_SIZE; ++step_count) {
        current_pos = move_step(1);

        // If we've returned to the starting point, we found the period directly
        if (current_pos == start_pos) {
            report_guess(step_count);
            return 0;
        }

        // Record first occurrence of this node
        if (visited_positions.find(current_pos) == visited_positions.end()) {
            visited_positions[current_pos] = step_count;
        }
    }

    // Now we're at distance BLOCK_SIZE from start
    // --- Phase 2: Large jumps (giant steps) ---
    for (int giant_step = 1; giant_step <= BLOCK_SIZE; ++giant_step) {
        current_pos = move_step(BLOCK_SIZE);

        // Check if this node was seen during baby steps
        auto it = visited_positions.find(current_pos);
        if (it != visited_positions.end()) {
            int small_steps = it->second;

            // Total steps so far: BLOCK_SIZE + giant_step * BLOCK_SIZE
            // This equals small_steps modulo n
            // So n divides (BLOCK_SIZE * (giant_step + 1) - small_steps)
            long long possible_n = static_cast<long long>(giant_step + 1) * BLOCK_SIZE - small_steps;

            report_guess(possible_n);
            return 0;
        }
    }

    return 0;
}

