#include <iostream>
#include <sol/sol.hpp>

// Custom struct with two fields
struct custom_pair {
    int value;
    bool flag;
};

// Custom type checking for sol2
template <typename Handler>
bool sol_lua_check(sol::types<custom_pair>, lua_State* L,
     int idx, Handler&& handler,
     sol::stack::record& tracking) {
    // Normalize index to absolute position
    int abs_idx = lua_absindex(L, idx);

    // Validate both components: int and bool
    bool valid_int = sol::stack::check<int>(L, abs_idx, handler);
    bool valid_bool = sol::stack::check<bool>(L, abs_idx + 1, handler);

    tracking.use(2);
    return valid_int && valid_bool;
}

// Extract custom_pair from Lua stack
custom_pair sol_lua_get(sol::types<custom_pair>, lua_State* L,
     int idx, sol::stack::record& tracking) {
    int abs_idx = lua_absindex(L, idx);

    int val = sol::stack::get<int>(L, abs_idx);
    bool flg = sol::stack::get<bool>(L, abs_idx + 1);

    tracking.use(2);
    return custom_pair{val, flg};
}

// Push custom_pair to Lua stack
int sol_lua_push(lua_State* L, const custom_pair& pair) {
    int pushed = sol::stack::push(L, pair.value);
    pushed += sol::stack::push(L, pair.flag);
    return pushed;
}

int main() {
    std::cout << "=== customization ===" << std::endl;
    std::cout << std::boolalpha;

    sol::state lua;
    lua.open_libraries(sol::lib::base);

    // Define a Lua function that echoes its arguments
    lua.script("function echo(x, y) print(x, y); return x, y end");

    // Retrieve the Lua function
    sol::function echo_fn = lua["echo"];

    // Test passing custom type through Lua
    custom_pair input_data{42, true};
    custom_pair result = echo_fn(input_data);

    // Verify results
    if (result.value != 42 || result.flag != true) {
        std::cerr << "Assertion failed!" << std::endl;
        return 1;
    }

    std::cout << "result.value: " << result.value << std::endl;
    std::cout << "result.flag: " << result.flag << std::endl;
    std::cout << std::endl;

    return 0;
}

