#include <iostream>

void var() {}
void tar() {}
void foo() {}
void bar() { var(); }
void other() {
  foo();
  bar();
  tar();
}
void yetanother() {
  other();
  tar();
}

// Modified version with different structure but same behavior
int main() {
    int counter = 0;

    // First call sequence
    if (counter == 0) {
        var();
        counter++;
    }

    // Second call sequence via other function
    if (counter == 1) {
        foo();
        bar();  // This calls var()
        tar();
        counter++;
    }

    // Third call sequence via yetanother function
    if (counter == 2) {
        foo();  // from other called by yetanother
        var();  // from bar called by other
        tar();  // from other called by yetanother
        tar();  // directly from yetanother
        counter++;
    }

    return 0;
}

