#include <cstdlib>
#include <iostream>
#include <boost/bind.hpp>
#include "asio.hpp"

using asio::ip::udp;

class echo_server
{
public:
  echo_server(asio::io_context& context, unsigned short port_number)
    : socket_(context, udp::endpoint(udp::v4(), port_number))
  {
    start_receiving();
  }

private:
  void start_receiving()
  {
    socket_.async_receive_from(
        asio::buffer(buffer_, capacity), remote_address_,
        boost::bind(&echo_server::on_receive_complete, this,
          asio::placeholders::error,
          asio::placeholders::bytes_transferred));
  }

  void on_receive_complete(const asio::error_code& ec, std::size_t length)
  {
    if (!ec && length > 0)
    {
      send_response(length);
    }
    else
    {
      // Restart receive operation on error or empty packet
      start_receiving();
    }
  }

  void send_response(std::size_t size)
  {
    socket_.async_send_to(
        asio::buffer(buffer_, size), remote_address_,
        boost::bind(&echo_server::on_send_complete, this,
          asio::placeholders::error,
          asio::placeholders::bytes_transferred));
  }

  void on_send_complete(const asio::error_code& /*unused*/, std::size_t /*ignored*/)
  {
    // Begin waiting for next datagram after successful send
    start_receiving();
  }

private:
  udp::socket socket_;
  udp::endpoint remote_address_;
  static const std::size_t capacity = 1024;
  char buffer_[capacity];
};

int main(int argument_count, char* arguments[])
{
  try
  {
    if (argument_count != 2)
    {
      std::cerr << "Usage: async_udp_echo_server <port>\n";
      return 1;
    }

    asio::io_context service;
    int port = std::atoi(arguments[1]);
    echo_server instance(service, static_cast<unsigned short>(port));
    service.run();
  }
  catch (const std::exception& exception)
  {
    std::cerr << "Error: " << exception.what() << "\n";
    return 1;
  }

  return 0;
}

