void ThrownEnderpearl::onCollision(HitResult *impact)
{
	if (impact == nullptr || impact->targetEntity == nullptr)
		return;

	DamageSource *source = DamageSource::thrown(shared_from_this(), this->owner);
	impact->targetEntity->takeDamage(source, 0);
	delete source;

	// Emit visual particles
	for (int particleCount = 0; particleCount < 32; ++particleCount)
	{
		double offsetX = random->nextGaussian();
		double offsetZ = random->nextGaussian();
		level->spawnParticle(eParticleType_ender, x, y + random->nextDouble() * 2.0, z, offsetX, 0.0, offsetZ);
	}

	if (level->isClientSide)
		return;

	// Fix for #67486 - TCR #001: BAS Game Stability: Customer Encountered: TU8: Code: Gameplay: The title crashes on Host's console when Client Player leaves the game before the Ender Pearl thrown by him touches the ground.
	shared_ptr<ServerPlayer> playerPtr = dynamic_pointer_cast<ServerPlayer>(owner);
	if (playerPtr == nullptr || playerPtr->removed)
	{
		remove();
		return;
	}

	PlayerConnection *conn = playerPtr->connection.get();
	if (conn != nullptr && conn->isFinishedLoading && playerPtr->dimension == level)
	{
		owner->moveTo(x, y, z);
		owner->resetFallDistance();
		owner->takeDamage(DamageSource::fall, 5);
	}

	remove();
}

