#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

class PermutationGenerator {
public:
    void computeNextPermutation(vector<int>& arr) {
        int size = arr.size();
        int pivotIndex = -1;

        // Step 1: Locate the rightmost position where an element is smaller than its successor
        for (int j = size - 2; j >= 0; --j) {
            if (arr[j] < arr[j + 1]) {
                pivotIndex = j;
                break;
            }
        }

        if (pivotIndex == -1) {
            // No pivot found means the sequence is non-increasing; reverse to get smallest permutation
            reverse(arr.begin(), arr.end());
        } else {
            // Step 2: Find the rightmost element larger than arr[pivotIndex]
            for (int k = size - 1; k > pivotIndex; --k) {
                if (arr[k] > arr[pivotIndex]) {
                    swap(arr[k], arr[pivotIndex]);
                    break;
                }
            }

            // Step 3: Sort the suffix in ascending order (equivalent to reversing since it's descending)
            reverse(arr.begin() + pivotIndex + 1, arr.end());
        }
    }
};

int main() {
    PermutationGenerator generator;
    vector<int> data = {2, 3, 7, 6, 5, 1};
    generator.computeNextPermutation(data);

    for (int idx = 0; idx < data.size(); ++idx) {
        cout << data[idx] << " ";
    }
    return 0;
}

#include <vector>
#include <string>
#include <algorithm>

class Solution {
public:
    int minCost(std::string colors, std::vector<int>& neededTime) {
        int totalRemovalTime = 0;

        // Iterate through each balloon starting from the second one
        for (int idx = 1; idx < colors.length(); ++idx) {
            // If current balloon has same color as previous one
            if (colors[idx] == colors[idx - 1]) {
                // Remove the one with smaller removal time
                if (neededTime[idx] < neededTime[idx - 1]) {
                    totalRemovalTime += neededTime[idx];
                    // Keep the larger time for future comparisons
                    neededTime[idx] = neededTime[idx - 1];
                } else {
                    totalRemovalTime += neededTime[idx - 1];
                }
            }
        }

        return totalRemovalTime;
    }
};

#include <iostream>
#include <asio.hpp>
#include <functional>

// Asynchronous timer callback function to print and increment counter
void timer_handler(const asio::error_code& error,
    asio::steady_timer* timer_ptr, int* counter_ptr)
{
  if (!error && *counter_ptr < 5)
  {
    std::cout << *counter_ptr << std::endl;
    ++(*counter_ptr);

    // Reset timer for next second
    timer_ptr->expires_at(timer_ptr->expiry() + asio::chrono::seconds(1));

    // Schedule next callback using lambda instead of boost::bind
    timer_ptr->async_wait(
        [timer_ptr, counter_ptr](const asio::error_code& ec) {
          timer_handler(ec, timer_ptr, counter_ptr);
        });
  }
}

int main()
{
  asio::io_context io_service;
  int counter = 0;

  // Create and configure the timer
  asio::steady_timer timer(io_service, asio::chrono::seconds(1));

  // Start the first asynchronous wait
  timer.async_wait(
      [&timer, &counter](const asio::error_code& ec) {
        timer_handler(ec, &timer, &counter);
      });

  // Run the I/O service until all operations complete
  io_service.run();

  std::cout << "Final count is " << counter << std::endl;
  return 0;
}

#include <pangolin/pangolin.h>
#include <pangolin/log/packetstream_reader.h>
#include <pangolin/log/packetstream_writer.h>
#include <pangolin/video/video.h>

int main(int argc, char* argv[]) {
    if (2 != argc) {
        std::cerr << "Usage:\n\tPangolinVideoTransform input.pango output.pango\n";
        return 1;
    }

    const std::string input_path{argv[1]};
    const std::string output_path{argv[2]};

    if (input_path == output_path) {
        std::cerr << "Error: Input and output paths must differ.\n";
        return 1;
    }

    pangolin::PacketStreamReader reader(input_path);
    pangolin::PacketStreamWriter writer(output_path);

    // Read updated JSON metadata from stdin
    picojson::value new_metadata;
    std::cout << "Reading JSON from input..." << std::endl;
    std::cin >> new_metadata;
    std::cout << "+ done" << std::endl;

    const auto& sources = reader.Sources();
    PANGO_ASSERT(new_metadata.size() == sources.size());

    // Rebuild source definitions with new device/frame properties
    for (size_t idx = 0; idx < sources.size(); ++idx) {
        const auto& src = sources[idx];
        const auto& src_meta = new_metadata[idx];

        PANGO_ASSERT(src_meta.contains("frame_properties"));
        PANGO_ASSERT(src_meta.contains("device_properties"));

        const auto& frame_props = src_meta["frame_properties"];
        PANGO_ASSERT(frame_props.size() == src.index.size());

        // Reset index and inject new device info
        pangolin::PacketStreamSource rebuilt_src = src;
        rebuilt_src.index.clear();
        rebuilt_src.info["device"] = src_meta["device_properties"];

        writer.AddSource(rebuilt_src);
    }

    std::cout << "Writing transformed video to '" << output_path << "'...\n";

    try {
        std::vector<char> frame_buffer;
        size_t total_frames_read = 0;

        while (true) {
            pangolin::Packet pkt = reader.NextFrame();

            // Copy raw packet data into buffer
            const size_t bytes_to_read = pkt.BytesRemaining();
            frame_buffer.resize(bytes_to_read);
            pkt.Stream().read(frame_buffer.data(), bytes_to_read);

            // Retrieve corresponding new frame metadata
            const picojson::value& frame_json = new_metadata[pkt.src]["frame_properties"][pkt.sequence_num];

            // Write packet with updated metadata
            writer.WriteSourcePacket(pkt.src, frame_buffer.data(), pkt.time, bytes_to_read, frame_json);

            // Progress indicator
            ++total_frames_read;
            const size_t expected_frames = sources[pkt.src].index.size();
            std::cout << "\rFrames processed: " << total_frames_read << " / " << expected_frames;
            std::cout.flush();
        }
    } catch (const std::runtime_error& err) {
        std::cerr << "Processing stopped due to runtime error: " << err.what() << '\n';
        throw;
    }

    std::cout << "\n+ transformation complete\n";
    return 0;
}

#ifndef __Pyx_CppExn2PyErr
#include <new>
#include <typeinfo>
#include <stdexcept>
#include <ios>

static void __Pyx_ConvertCppExceptionToPython() {
    if (PyErr_Occurred()) {
        // A Python exception is already set; do not overwrite it.
        return;
    }

    try {
        throw;
    } catch (const std::bad_alloc& e) {
        PyErr_SetString(PyExc_MemoryError, e.what());
    } catch (const std::bad_cast& e) {
        PyErr_SetString(PyExc_TypeError, e.what());
    } catch (const std::bad_typeid& e) {
        PyErr_SetString(PyExc_TypeError, e.what());
    } catch (const std::domain_error& e) {
        PyErr_SetString(PyExc_ValueError, e.what());
    } catch (const std::invalid_argument& e) {
        PyErr_SetString(PyExc_ValueError, e.what());
    } catch (const std::ios_base::failure& e) {
        PyErr_SetString(PyExc_IOError, e.what());
    } catch (const std::out_of_range& e) {
        PyErr_SetString(PyExc_IndexError, e.what());
    } catch (const std::overflow_error& e) {
        PyErr_SetString(PyExc_OverflowError, e.what());
    } catch (const std::range_error& e) {
        PyErr_SetString(PyExc_ArithmeticError, e.what());
    } catch (const std::underflow_error& e) {
        PyErr_SetString(PyExc_ArithmeticError, e.what());
    } catch (const std::exception& e) {
        PyErr_SetString(PyExc_RuntimeError, e.what());
    } catch (...) {
        PyErr_SetString(PyExc_RuntimeError, "Unknown exception");
    }
}
#endif

