#include <vector>
#include <unordered_map>
using namespace std;

class Solution {
public:
    int findCenter(vector<vector<int>>& edges) {
        // Count degree of each node - the center will have the highest degree
        unordered_map<int, int> degree;

        // Iterate through each edge and count both endpoints
        for (const auto& edge : edges) {
            if (edge.size() >= 2) {
                degree[edge[0]]++;
                degree[edge[1]]++;
            }
        }

        // Find the node with maximum degree (center of star graph)
        int center = 0;
        int maxDegree = 0;

        for (const auto& nodeDegree : degree) {
            if (nodeDegree.second > maxDegree) {
                maxDegree = nodeDegree.second;
                center = nodeDegree.first;
            }
        }

        return center;
    }
};

