// Function to find the two pens with highest ink levels using queries
void findTopPens() {
    int n;
    std::cin >> n;

    // Initialize list with all pen indices (0 to n-1)
    std::list<int> active_pens;
    for (int i = 0; i < n; ++i) {
        active_pens.push_back(i);
    }

    // Continue eliminating pens until at most 2 remain
    while (active_pens.size() > 2) {
        std::list<int> survivors;

        // Query each remaining pen to determine if it should survive
        for (int current_pen : active_pens) {
            std::cout << "0 " << current_pen << std::endl;
            int result;
            std::cin >> result;

            if (result == 1) {
                survivors.push_back(current_pen);
            }
        }

        active_pens = survivors;

        // Stop early if we have 2 or fewer candidates
        if (active_pens.size() <= 2) {
            break;
        }
    }

    // Handle edge cases where fewer than 2 pens remain
    if (active_pens.size() < 2) {
        if (active_pens.empty()) {
            // No pens survived - output default pair
            std::cout << "1 0 1" << std::endl;
        } else {
            // Only one pen survived - pair with next available pen
            int first = active_pens.front();
            int second = (first + 1) % n;
            std::cout << "1 " << first << " " << second << std::endl;
        }
        return;
    }

    // Output the final two pens
    auto it = active_pens.begin();
    int pen_a = *it;
    ++it;
    int pen_b = *it;
    std::cout << "1 " << pen_a << " " << pen_b << std::endl;
}

