namespace engine::store::filter::filesys::base {
//-------------------------------------------------------------------------
/// @details
///		Determines whether the file system entry has been modified since
///		last inspection. Compares timestamps, attributes, and sizes.
///		If any relevant field differs, updates the entry and flags it as changed.
///	@param[inout] entryRef
///		Reference to the metadata object representing the file
///	@returns
///		Error status; empty if successful
//-------------------------------------------------------------------------
template <log::Lvl LvlT>
Error IBaseSysInstance<LvlT>::checkChanged(Entry &entryRef) noexcept {
    WIN32_FIND_DATAW fileInfo;
    Error err;

    // Acquire OS-specific path from URL
    Text osPath;
    if ((err = Url::osPath(entryRef.url(), osPath))) return err;

    // Open file/directory handle using FindFirstFileW for full metadata (incl. symlinks)
    HANDLE hFind = FindFirstFileW(osPath.c_str(), &fileInfo);
    if (INVALID_HANDLE_VALUE == hFind) {
        DWORD lastErr = GetLastError();
        return APERR(lastErr, _location,
                     "Failed to retrieve file metadata via FindFirstFileW");
    }

    // Clean up handle immediately after use
    FindClose(hFind);

    // Assume no change unless proven otherwise
    entryRef.changed(false);

    // Compare creation time
    auto const newCreateTime = _tr<time::SystemStamp>(fileInfo.ftCreationTime);
    if (entryRef.createTime.get() != newCreateTime) {
        entryRef.markChanged(LogLevel, "Creation timestamp mismatch");
        entryRef.createTime(newCreateTime);
    }

    // Compare last write time
    auto const newModifyTime = _tr<time::SystemStamp>(fileInfo.ftLastWriteTime);
    if (entryRef.modifyTime.get() != newModifyTime) {
        entryRef.markChanged(LogLevel, "Modification timestamp mismatch");
        entryRef.modifyTime(newModifyTime);
    }

    // Update access time only (no change flag set)
    entryRef.accessTime(_tr<time::SystemStamp>(fileInfo.ftLastAccessTime));

    // Compare file attributes
    if (entryRef.attrib() != fileInfo.dwFileAttributes) {
        entryRef.markChanged(LogLevel, "File attributes altered");
        entryRef.attrib(fileInfo.dwFileAttributes);
    }

    // Compute total size from high/low parts
    uint64_t logicalSize =
        (static_cast<uint64_t>(fileInfo.nFileSizeHigh) << 32) |
        static_cast<uint64_t>(fileInfo.nFileSizeLow);

    if (entryRef.size() != logicalSize) {
        entryRef.markChanged(LogLevel, "Logical size differs");
        entryRef.size(logicalSize);
    }

    // Retrieve physical (on-disk) size
    auto diskSizeResult = file::getSizeOnDisk(osPath, entryRef.size(), entryRef.attrib());

    uint64_t storeSizeVal{};
    if (diskSizeResult.check()) {
        // Fallback to logical size if on-disk query fails
        storeSizeVal = entryRef.size();
    } else {
        storeSizeVal = *diskSizeResult;
    }

    // Flag change only if stored size differs
    if (entryRef.storeSize() != storeSizeVal) {
        entryRef.markChanged(LogLevel, "Physical storage size changed");
        entryRef.storeSize(storeSizeVal);
    }

    return {};
}
}  // namespace engine::store::filter::filesys::base

class Solution {
public:
    long long getDescentPeriods(vector<int>& prices) {
        if (prices.empty()) return 0;

        long long total_periods = 0;
        int n = prices.size();

        for (int start = 0; start < n; ) {
            int end = start;
            // Find the longest descent sequence starting at 'start'
            while (end + 1 < n && prices[end] == prices[end + 1] + 1) {
                end++;
            }

            // For a descent sequence of length L (number of elements), 
            // there are L*(L+1)/2 subarrays that are descent periods
            long long length = end - start + 1;
            total_periods += length * (length + 1) / 2;

            start = end + 1;
        }

        return total_periods;
    }
};

