#include "connection.hpp"
#include <vector>
#include <boost/bind.hpp>
#include "request_handler.hpp"

namespace http {
namespace server3 {

connection::connection(asio::io_context& io_context, request_handler& handler)
  : strand_(io_context),
    socket_(io_context),
    request_handler_(handler)
{
}

asio::ip::tcp::socket& connection::socket() {
  return socket_;
}

void connection::start() {
  socket_.async_read_some(asio::buffer(buffer_),
      asio::bind_executor(strand_,
        boost::bind(&connection::process_input, shared_from_this(),
          asio::placeholders::error,
          asio::placeholders::bytes_transferred)));
}

void connection::process_input(const asio::error_code& e, std::size_t bytes_read) {
  if (!e) {
    auto begin = buffer_.data();
    auto end = begin + bytes_read;

    auto parse_result = request_parser_.parse(request_, begin, end);
    bool valid = std::get<0>(parse_result);

    if (valid) {
      request_handler_.handle_request(request_, reply_);
      asio::async_write(socket_, reply_.to_buffers(),
          asio::bind_executor(strand_,
            boost::bind(&connection::send_response, shared_from_this(),
              asio::placeholders::error)));
    } else if (!valid) {
      reply_ = reply::stock_reply(reply::bad_request);
      asio::async_write(socket_, reply_.to_buffers(),
          asio::bind_executor(strand_,
            boost::bind(&connection::send_response, shared_from_this(),
              asio::placeholders::error)));
    } else {
      // Incomplete data - continue reading
      socket_.async_read_some(asio::buffer(buffer_),
          asio::bind_executor(strand_,
            boost::bind(&connection::process_input, shared_from_this(),
              asio::placeholders::error,
              asio::placeholders::bytes_transferred)));
    }
  }
  // Error handling: when an error occurs, no further async operations are scheduled.
  // The connection object will be automatically destroyed once all shared_ptr references vanish.
  // The destructor handles closing the socket.
}

void connection::send_response(const asio::error_code& e) {
  if (!e) {
    // Gracefully close the connection
    asio::error_code ec;
    socket_.shutdown(asio::ip::tcp::socket::shutdown_both, ec);
  }
  // No new async operations are initiated here either.
  // All shared_ptr references to this connection will go out of scope,
  // leading to automatic destruction and socket closure via the destructor.
}

