    std::vector<std::string> rules;

    // Termination success case
    rules.push_back("S=(return)1");

    // Termination failure cases
    rules.push_back("Sa=(return)0");
    rules.push_back("Sb=(return)0");
    rules.push_back("Sc=(return)0");

    // Character matching rules (highest priority)
    rules.push_back("ASa=S");
    rules.push_back("BSb=S");
    rules.push_back("CSc=S");

    // Advance rules on mismatch
    rules.push_back("AS=X");
    rules.push_back("BS=X");
    rules.push_back("CS=X");

    // Helper rules for X marker movement
    rules.push_back("XA=AX");
    rules.push_back("XB=BX");
    rules.push_back("XC=CX");

    // Restore separator S
    rules.push_back("XS=S");

    // Setup phase conversion rules (lowest priority)
    rules.push_back("aS=AS");
    rules.push_back("bS=BS");
    rules.push_back("cS=CS");

    // Output all rules in order
    for (const auto& rule : rules) {
        std::cout << rule << "\n";
    }

