    // Process a single test case
    void handleTestCase() {
        int n;
        std::cin >> n;

        // Create list of candidate pens numbered 0 to n-1
        std::vector<int> remainingPens(n);
        for (int i = 0; i < n; ++i) {
            remainingPens[i] = i;
        }

        // Continue eliminating until only two remain
        while (remainingPens.size() > 2) {
            std::vector<int> nextRound;

            // Handle odd number by giving last pen a bye
            if (remainingPens.size() % 2 == 1) {
                nextRound.push_back(remainingPens.back());
                remainingPens.pop_back();
            }

            // Process pairs of pens
            for (size_t j = 0; j < remainingPens.size(); j += 2) {
                int penA = remainingPens[j];
                int penB = remainingPens[j + 1];

                // Check first pen
                std::cout << "0 " << penA << std::endl;
                int resultA;
                std::cin >> resultA;

                // Check second pen
                std::cout << "0 " << penB << std::endl;
                int resultB;
                std::cin >> resultB;

                // Winner selection: prefer pen with ink (result=1)
                // If both have ink or both empty, default to penA
                if (resultA == 1 || resultB == 0) {
                    nextRound.push_back(penA);
                } else {
                    nextRound.push_back(penB);
                }
            }

            // Update candidates for next round
            remainingPens = nextRound;
        }

        // Output the final two pens
        std::cout << "1 " << remainingPens[0] << " " << remainingPens[1] << std::endl;
    }

    int main() {
        // Optimize I/O operations
        std::ios_base::sync_with_stdio(false);
        std::cin.tie(nullptr);

        int testCases;
        std::cin >> testCases;

        for (int tc = 0; tc < testCases; ++tc) {
            handleTestCase();
        }

        return 0;
    }

