#include <vector>
#include <cmath>

class Solution {
public:
    int firstMissingPositive(std::vector<int>& nums) {
        int size = nums.size();

        // Normalize non-positive and out-of-range values
        for (int i = 0; i < size; ++i) {
            if (nums[i] <= 0 || nums[i] > size + 1) {
                nums[i] = size + 1;
            }
        }

        // Mark presence of numbers by negating corresponding indices
        for (int i = 0; i < size; ++i) {
            int val = std::abs(nums[i]);
            if (val >= 1 && val <= size) {
                nums[val - 1] = -std::abs(nums[val - 1]);
            }
        }

        // Find the first positive index (missing number)
        for (int i = 0; i < size; ++i) {
            if (nums[i] > 0) {
                return i + 1;
            }
        }

        return size + 1;
    }
};

