namespace yams::search {

bool SearchFilters::matches(const SearchResultItem& item) const {
    // Early exit if no filters are defined
    if (!hasFilters()) {
        return true;
    }

    // Process date-based constraints
    for (const auto& filter : dateFilters_) {
        std::chrono::system_clock::time_point checkDate;
        switch (filter.field) {
            case DateRangeFilter::DateField::LastModified:
                checkDate = item.lastModified;
                break;
            case DateRangeFilter::DateField::Created:
                // Fallback to lastModified when created date is unavailable
                checkDate = item.lastModified;
                break;
            case DateRangeFilter::DateField::Indexed:
                checkDate = item.indexedAt;
                break;
        }
        if (!filter.satisfies(checkDate)) {
            return false;
        }
    }

    // Enforce size restrictions
    for (const auto& filter : sizeFilters_) {
        if (!filter.satisfies(item.fileSize)) {
            return false;
        }
    }

    // Validate content type compatibility
    for (const auto& filter : contentTypeFilters_) {
        if (!filter.satisfies(item.contentType)) {
            return false;
        }
    }

    // Check language requirements
    for (const auto& filter : languageFilters_) {
        if (!filter.satisfies(item.detectedLanguage, item.languageConfidence)) {
            return false;
        }
    }

    // Verify path inclusion/exclusion rules
    for (const auto& filter : pathFilters_) {
        if (!filter.satisfies(item.path)) {
            return false;
        }
    }

    // Apply metadata constraints
    for (const auto& filter : metadataFilters_) {
        if (!filter.satisfies(item.metadata)) {
            return false;
        }
    }

    // Assess relevance thresholds
    for (const auto& filter : relevanceFilters_) {
        if (!filter.satisfies(item.relevanceScore)) {
            return false;
        }
    }

    // Execute user-defined custom checks
    for (const auto& filter : customFilters_) {
        if (!filter(item)) {
            return false;
        }
    }

    return true;
}

std::vector<SearchResultItem>
SearchFilters::apply(const std::vector<SearchResultItem>& items) const {
    // If no filters exist, return original list unchanged
    if (!hasFilters()) {
        return items;
    }

    std::vector<SearchResultItem> result;
    result.reserve(items.size());

    for (const auto& candidate : items) {
        if (matches(candidate)) {
            result.emplace_back(candidate);
        }
    }

    return result;
}

