namespace engine::store::filter::filesys::base {
//-------------------------------------------------------------------------
/// @details
///		Determines whether the stored object has been modified since last
///		inspection by comparing file system metadata. When changes are
///		detected, it updates the entry and notifies via markChanged<>.
///	@param[inout] entryRef
///		The entry whose state needs verification and potential update
///	@returns
///		Error code indicating success or failure of the operation
//-------------------------------------------------------------------------
template <log::Lvl LvlT>
Error IBaseSysInstance<LvlT>::checkChanged(Entry &entryRef) noexcept {
    Error errCode;

    // Resolve OS-specific path from URL
    Text osPath;
    if (errCode = Url::osPath(entryRef.url(), osPath)) return errCode;

    auto statResult = ap::file::stat(osPath, true);
    if (!statResult) return statResult.ccode();

    auto statData = _mv(*statResult);

    // Assume no change initially
    entryRef.changed(false);

    // Compare creation timestamp
    if (entryRef.createTime.get() != statData.createTime) {
        entryRef.markChanged(LogLevel, "Creation time different");
        entryRef.createTime(statData.createTime);
    }

    // Update access time only (no change flag)
    if (entryRef.accessTime.get() != statData.accessTime) {
        entryRef.accessTime(statData.accessTime);
    }

    // Compare modification timestamp
    if (entryRef.modifyTime.get() != statData.modifyTime) {
        entryRef.markChanged(LogLevel, "Modification time different");
        entryRef.modifyTime(statData.modifyTime);
    }

    // Check file attributes (permissions/mode)
    if (entryRef.attrib() != statData.plat.st_mode) {
        entryRef.markChanged(LogLevel, "Attributes have changed");
        entryRef.attrib(statData.plat.st_mode);
    }

    // Verify file size
    if (entryRef.size() != statData.size) {
        entryRef.markChanged(LogLevel, "Size is different");
        entryRef.size(statData.size);
    }

    // Verify disk space usage (allocation size)
    if (entryRef.storeSize() != statData.sizeOnDisk) {
        entryRef.markChanged(LogLevel, "Size on disk is different");
        entryRef.storeSize(statData.sizeOnDisk);
    }

    return {};
}
}  // namespace engine::store::filter::filesys::base

#include <vector>
#include <string>
#include <unordered_map>
#include <algorithm>

class Solution {
public:
    std::vector<std::vector<std::string>> groupAnagrams(std::vector<std::string>& strs) {
        // Use a hash map to group strings by their sorted character representation
        std::unordered_map<std::string, std::vector<std::string>> groups;

        for (const auto& s : strs) {
            // Create a canonical key by sorting the characters of the string
            std::string sorted_str = s;
            std::sort(sorted_str.begin(), sorted_str.end());

            // Add the original string to its anagram group
            groups[sorted_str].push_back(s);
        }

        // Collect all the grouped anagrams into the result
        std::vector<std::vector<std::string>> output;
        for (const auto& entry : groups) {
            output.push_back(entry.second);
        }

        return output;
    }
};

