// Helper function to check if a word already exists in our list
bool contains_word(const vector<string>& words, const string& w) {
    for (const auto& word : words) {
        if (word == w) return true;
    }
    return false;
}

void solve() {
    int total_words;
    if (!(cin >> total_words)) return;

    // Use vector instead of set, will handle uniqueness manually
    vector<string> collected_words;

    // Process each letter from 'a' to 'z'
    char current_char = 'a';
    while (current_char <= 'z') {
        // Stop if we've collected all required words
        if (collected_words.size() >= total_words) break;

        string prefix(1, current_char);
        int found_for_letter = 0;     // Words found for this letter so far
        int query_size = 1;           // Current query size K

        while (collected_words.size() < total_words) {
            // Skip if query size is not larger than what we already have for this letter
            if (query_size <= found_for_letter) {
                query_size *= 2;
                continue;
            }

            // Calculate maximum possible words for this letter
            int other_letters_count = collected_words.size() - found_for_letter;
            int max_possible_for_this = total_words - other_letters_count;

            // Determine actual query size
            int k_limit = min(query_size, max_possible_for_this);

            // If limit doesn't exceed current count, increase query size
            if (k_limit <= found_for_letter) {
                query_size *= 2;
                continue;
            }

            cout << "query " << prefix << " " << k_limit << endl;

            int received_count;
            cin >> received_count;

            // Read the returned words
            for (int i = 0; i < received_count; ++i) {
                string word;
                cin >> word;

                // Only add if not already present
                if (!contains_word(collected_words, word)) {
                    collected_words.push_back(word);
                }
            }

            found_for_letter = received_count;

            // If fewer words than requested, no more words for this prefix
            if (received_count < k_limit) {
                break;
            }

            // Check if we've collected all needed words
            if (collected_words.size() == total_words) break;

            // Double the query size for next iteration
            query_size *= 2;
        }

        // Move to next character
        current_char++;
    }

    // Output the answer
    cout << "answer";
    for (const auto& word : collected_words) {
        cout << " " << word;
    }
    cout << endl;
}

int main() {
    int test_cases;
    if (cin >> test_cases) {
        while (test_cases--) {
            solve();
        }
    }
    return 0;
}

#include <iostream>
