// Vector to store the sequence of moves as pairs of basket indices
std::vector<std::pair<int, int>> moveSequence;

/**
 * @brief Recursive function to solve the ball-moving puzzle using a Tower of Hanoi approach.
 * 
 * @param ballsCount The number of balls to move.
 * @param source The source basket identifier.
 * @param target The destination basket identifier.
 * @param helper The auxiliary basket identifier.
 */
void computeMoves(int ballsCount, int source, int target, int helper) {
    if (ballsCount == 0) {
        return;
    }

    // Move ballsCount-1 balls from source to helper using target as temporary storage
    computeMoves(ballsCount - 1, source, helper, target);

    // Record the direct move of the bottom-most ball from source to target
    moveSequence.push_back(std::make_pair(source, target));

    // Move the remaining balls from helper to target using source as temporary storage
    computeMoves(ballsCount - 1, helper, target, source);
}

int main() {
    // Optimize standard I/O for faster execution
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int n;
    std::cin >> n;

    // Start the recursive solution: move n balls from basket 1 to basket 3 using basket 2 as helper
    computeMoves(n, 1, 3, 2);

    // Output the total number of moves performed
    std::cout << moveSequence.size() << "\n";

    // Print each individual move in order
    for (const auto& step : moveSequence) {
        std::cout << step.first << " " << step.second << "\n";
    }

    return 0;
}

