using namespace std;

// LeetCode 733: Flood Fill - Type III Clone
// Modified implementation using iterative DFS with explicit stack
class Solution {
public:
    vector<vector<int>> floodFill(vector<vector<int>>& image, int sr, int sc, int newColor) {
        int originalColor = image[sr][sc];

        // If the new color is the same as original, no changes needed
        if (originalColor == newColor) {
            return image;
        }

        int rows = image.size();
        int cols = image[0].size();

        // Use a stack for iterative DFS
        vector<pair<int, int>> stack;
        stack.push_back({sr, sc});

        while (!stack.empty()) {
            auto [r, c] = stack.back();
            stack.pop_back();

            // Skip if out of bounds or not matching original color
            if (r < 0 || r >= rows || c < 0 || c >= cols || image[r][c] != originalColor) {
                continue;
            }

            // Change the color
            image[r][c] = newColor;

            // Add all four neighbors to the stack
            stack.push_back({r + 1, c});
            stack.push_back({r - 1, c});
            stack.push_back({r, c + 1});
            stack.push_back({r, c - 1});
        }

        return image;
    }
};

