#include <algorithm>
using namespace std;

// Structure to represent a swap operation between two positions
struct SwapOperation {
    int row1, col1;
    int row2, col2;
};

int main() {
    // Speed up I/O operations
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    const int PYRAMID_HEIGHT = 30;
    vector<vector<int>> pyramid(PYRAMID_HEIGHT);

    // Read input pyramid data
    for (int level = 0; level < PYRAMID_HEIGHT; ++level) {
        pyramid[level].reserve(level + 1);
        for (int position = 0; position <= level; ++position) {
            int value;
            cin >> value;
            pyramid[level].push_back(value);
        }
    }

    vector<SwapOperation> operations;
    operations.reserve(10000); // Pre-allocate space for efficiency

    // Build min-heap property from bottom-up
    // Start from second-to-last level and move upward
    for (int currentLevel = PYRAMID_HEIGHT - 2; currentLevel >= 0; --currentLevel) {
        for (int currentIndex = 0; currentIndex <= currentLevel; ++currentIndex) {
            int x = currentLevel;
            int y = currentIndex;

            // Sift down the element at (x, y)
            while (x < PYRAMID_HEIGHT - 1) {
                int childX = x + 1;
                int leftChildY = y;
                int rightChildY = y + 1;

                int parentVal = pyramid[x][y];
                int leftVal = pyramid[childX][leftChildY];
                int rightVal = pyramid[childX][rightChildY];

                // Check if heap property is satisfied: parent <= both children
                if (parentVal <= leftVal && parentVal <= rightVal) {
                    break;
                }

                // Determine which child is smaller for swapping
                if (leftVal <= rightVal) {
                    operations.push_back({x, y, childX, leftChildY});
                    swap(pyramid[x][y], pyramid[childX][leftChildY]);
                    x = childX;
                    y = leftChildY;
                } else {
                    operations.push_back({x, y, childX, rightChildY});
                    swap(pyramid[x][y], pyramid[childX][rightChildY]);
                    x = childX;
                    y = rightChildY;
                }
            }
        }
    }

    // Output number of swaps followed by each swap operation
    cout << operations.size() << "\n";
    for (const auto& op : operations) {
        cout << op.row1 << " " << op.col1 << " " << op.row2 << " " << op.col2 << "\n";
    }

    return 0;
}

#include <iostream>
#include <cmath>

class Solution {
  public:
    int towerOfHanoi(int n, int from, int to, int aux) {
        // Using iterative approach with mathematical formula: 2^n - 1
        // This avoids redundant recursive calls
        if (n <= 0) {
            return 0;
        }

        // Calculate 2^n - 1 iteratively to avoid recursion overhead
        int moves = 1;
        for (int i = 1; i < n; ++i) {
            moves = moves * 2 + 1;
        }

        return moves;
    }
};

