namespace quantclaw::cli {

CLIManager::CLIManager() = default;

void CLIManager::AddCommand(const Command& command) {
    commands_.emplace_back(command);
}

int CLIManager::Run(int argc, char** argv) {
    // Check if at least one argument is provided
    if (argc < 2) {
        ShowUsage();
        return 1;
    }

    std::string requested_cmd = argv[1];

    // Process special flags first
    if (requested_cmd == "--version" || requested_cmd == "-v") {
        std::cout << "quantclaw " << kVersion
                  << " (build " << kGitCommit << " " << kBuildDate << ")"
                  << std::endl;
        return 0;
    }

    if (requested_cmd == "--help" || requested_cmd == "-h") {
        ShowUsage();
        return 0;
    }

    // Search for matching command by name or alias
    for (const auto& cmd : commands_) {
        if (cmd.name == requested_cmd ||
            std::any_of(cmd.aliases.begin(), cmd.aliases.end(),
                        [&requested_cmd](const std::string& alias) { return alias == requested_cmd; })) {
            char** adjusted_argv = &argv[1];
            int adjusted_argc = argc - 1;
            return cmd.handler(adjusted_argc, adjusted_argv);
        }
    }

    // Command not found
    std::cerr << "Unknown command: " << requested_cmd << std::endl;
    ShowUsage();
    return 1;
}

void CLIManager::ShowHelp() const {
    ShowUsage();
}

void CLIManager::ShowUsage() const {
    std::cout << "QuantClaw - High-performance C++ AI assistant" << std::endl;
    std::cout << std::endl;
    std::cout << "Usage: quantclaw <command> [options]" << std::endl;
    std::cout << std::endl;
    std::cout << "Available Commands:" << std::endl;

    for (const auto& cmd : commands_) {
        std::cout << "  " << cmd.name;
        if (!cmd.aliases.empty()) {
            std::cout << " (";
            for (size_t i = 0; i < cmd.aliases.size(); ++i) {
                if (i > 0) std::cout << ", ";
                std::cout << cmd.aliases[i];
            }
            std::cout << ")";
        }
        std::cout << "\t" << cmd.description << std::endl;
    }

    std::cout << std::endl;
    std::cout << "Global Options:" << std::endl;
    std::cout << "  --version, -v\tPrint version information" << std::endl;
    std::cout << "  --help, -h\tDisplay this help message" << std::endl;
    std::cout << "  --json\tEnable JSON output format" << std::endl;
    std::cout << std::endl;
    std::cout << "Examples:" << std::endl;
    std::cout << "  quantclaw gateway              Start gateway in foreground mode" << std::endl;
    std::cout << "  quantclaw gateway install       Register gateway as a system service" << std::endl;
    std::cout << "  quantclaw gateway status         Display current gateway status" << std::endl;
    std::cout << "  quantclaw agent -m \"Hello\"       Send a message to the agent" << std::endl;
    std::cout << "  quantclaw sessions list          Retrieve list of active sessions" << std::endl;
    std::cout << "  quantclaw health                 Perform system health check" << std::endl;
    std::cout << "  quantclaw config get gateway.port Fetch specific configuration value" << std::endl;
}

