        {
            TDate d("20110215");
            UNIT_ASSERT_EQUAL(d.GetYear(), 2011);
            UNIT_ASSERT_EQUAL(d.GetMonth(), 2);
            UNIT_ASSERT_EQUAL(d.GetDayOfMonth(), 15);
            UNIT_ASSERT_EQUAL(d.AsString("%Y%m%d"), "20110215");
            UNIT_ASSERT_EQUAL(d.AsString(), "20110215");
            UNIT_ASSERT_EQUAL(d.AsString("%Y--%m--%d"), "2011--02--15");
            UNIT_ASSERT_EQUAL(d.AsString("%U"), "07");
            UNIT_ASSERT_EQUAL(d.GetUnixTime(), 1297728000);
        }

        // Test constructing from year, month, day components
        {
            TDate d(2005, 6, 3);
            UNIT_ASSERT_EQUAL(d.GetYear(), 2005);
            UNIT_ASSERT_EQUAL(d.GetMonth(), 6);
            UNIT_ASSERT_EQUAL(d.GetDayOfMonth(), 3);
            UNIT_ASSERT_EQUAL(d.AsString(), "20050603");
            UNIT_ASSERT_EQUAL(d.AsString("____%Y__%m____%d"), "____2005__06____03");
            UNIT_ASSERT_EQUAL(d.GetUnixTime(), 1117756800);
        }

        // Test parsing from string with custom format
        {
            TDate d("2011-02-15", "%Y-%m-%d");
            UNIT_ASSERT_EQUAL(d.GetYear(), 2011);
            UNIT_ASSERT_EQUAL(d.GetMonth(), 2);
            UNIT_ASSERT_EQUAL(d.GetDayOfMonth(), 15);
            UNIT_ASSERT_EQUAL(d.AsString("%Y%m%d"), "20110215");
            UNIT_ASSERT_EQUAL(d.GetUnixTime(), 1297728000);
