// Internal log file handle, local to this translation unit
static FILE *log_handle = nullptr;
// Pointer to global application configuration
static const AppSettings *g_config = nullptr;

void log_configure_settings(const AppSettings *settings) {
    g_config = settings;
}

void log_start(bool is_overlay_mode) {
    const char *filename = is_overlay_mode ? "advancely_overlay_log.txt" : "advancely_log.txt";

    // Open log file in write mode (truncates existing content)
    log_handle = fopen(filename, "w");
    if (!log_handle) {
        fprintf(stderr, "CRITICAL: Unable to open log file %s\n", filename);
        return;
    }

    // Insert timestamp at the beginning of the log
    time_t current_time = time(nullptr);
    struct tm *local_time = localtime(&current_time);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", local_time);

    // Select appropriate header based on process type
    const char* header_format = is_overlay_mode ?
                                "Advancely Overlay Log - %s\n" :
                                "Advancely Log - %s\n";

    fprintf(log_handle, header_format, timestamp);
    fprintf(log_handle, "========================================\n\n");
    fflush(log_handle); // Flush immediately for early visibility
}

void log_output(LogLevel severity, const char *fmt, ...) {
    // Skip INFO messages unless debug output is explicitly enabled
    if (severity == LOG_INFO && (g_config == nullptr || !g_config->print_debug_status)) {
        return;
    }

    // Prepare formatted message buffer
    char buffer[4096];
    va_list arg_list;
    va_start(arg_list, fmt);
    vsnprintf(buffer, sizeof(buffer), fmt, arg_list);
    va_end(arg_list);

    // Output to console with optional color formatting
    if (severity == LOG_ERROR) {
#ifdef _WIN32
        HANDLE console_handle = GetStdHandle(STD_ERROR_HANDLE);
        CONSOLE_SCREEN_BUFFER_INFO info;
        WORD original_color;
        GetConsoleScreenBufferInfo(console_handle, &info);
        original_color = info.wAttributes;
        SetConsoleTextAttribute(console_handle, FOREGROUND_RED | FOREGROUND_INTENSITY);
        fprintf(stderr, "%s", buffer);
        SetConsoleTextAttribute(console_handle, original_color);
#else
        fprintf(stderr, "\033[91m%s\033[0m", buffer);
#endif
    } else {
        printf("%s", buffer);
    }

    // Write to persistent log file if available
    if (log_handle != nullptr) {
        char time_str[16];
        time_t now = time(nullptr);
        strftime(time_str, sizeof(time_str), "%H:%M:%S", localtime(&now));
        fprintf(log_handle, "[%s] %s", time_str, buffer);
        fflush(log_handle); // Ensure immediate persistence
    }
}

void log_shutdown(void) {
    if (log_handle != nullptr) {
        fprintf(log_handle, "\n========================================\n");
        fprintf(log_handle, "Log session ended.\n");
        fclose(log_handle);
        log_handle = nullptr;
    }
}

