// Function to read and display lines from a file, handling long lines
void demoGetline() {
    std::ifstream inputFile("users.txt");
    if (!inputFile) return;

    const int BUFFER_CAPACITY = 128;
    char lineBuffer[BUFFER_CAPACITY];

    // Continuously read lines until end-of-file or error
    while (inputFile.getline(lineBuffer, BUFFER_CAPACITY)) {
        std::cout << "Read line: " << lineBuffer << std::endl;
    }

    // Check for failure due to buffer overflow (line too long)
    if (inputFile.fail() && !inputFile.eof()) {
        std::cout << "ERROR: Found a line longer than the buffer." << std::endl;
        // Reset stream state to allow further operations
        inputFile.clear();
    }
}

