#include <string>

using asio::ip::tcp;

// A client implementation that enforces timeouts on network operations
class timeout_client
{
public:
    void establish_connection(const std::string& hostname, const std::string& port_number,
        std::chrono::steady_clock::duration deadline)
    {
        // Resolve the target host and service
        tcp::resolver resolver(io_context_);
        auto results = resolver.resolve(hostname, port_number);

        // Initiate asynchronous connection with a lambda handler
        std::error_code err;
        asio::async_connect(connection_, results,
            [&](const std::error_code& ec, const tcp::endpoint&)
            {
                err = ec;
            });

        // Execute with timeout constraint
        execute_with_timeout(deadline);

        // Check for connection errors
        if (err)
            throw std::system_error(err);
    }

    std::string fetch_line(std::chrono::steady_clock::duration deadline)
    {
        std::error_code err;
        std::size_t bytes_read = 0;

        // Asynchronous read until newline delimiter
        asio::async_read_until(connection_,
            asio::dynamic_buffer(buffer_), '\n',
            [&](const std::error_code& ec, std::size_t n)
            {
                err = ec;
                bytes_read = n;
            });

        execute_with_timeout(deadline);

        if (err)
            throw std::system_error(err);

        std::string result(buffer_.substr(0, bytes_read - 1));
        buffer_.erase(0, bytes_read);
        return result;
    }

    void send_line(const std::string& text, std::chrono::steady_clock::duration deadline)
    {
        std::string payload = text + "\n";
        std::error_code err;

        // Asynchronous write operation
        asio::async_write(connection_, asio::buffer(payload),
            [&](const std::error_code& ec, std::size_t)
            {
                err = ec;
            });

        execute_with_timeout(deadline);

        if (err)
            throw std::system_error(err);
    }

private:
    void execute_with_timeout(std::chrono::steady_clock::duration limit)
    {
        io_context_.restart();
        io_context_.run_for(limit);

        // If timeout occurred before completion
        if (!io_context_.stopped())
        {
            // Cancel pending operations by closing socket
            connection_.close();
            // Process any remaining work to ensure clean state
            io_context_.run();
        }
    }

    asio::io_context io_context_;
    tcp::socket connection_{io_context_};
    std::string buffer_;
};

int main(int argc, char* argv[])
{
    try
    {
        if (argc != 4)
        {
            std::cerr << "Usage: timeout_tcp_client <host> <port> <message>\n";
            return 1;
        }

        timeout_client client_instance;
        client_instance.establish_connection(argv[1], argv[2], std::chrono::seconds(10));

        auto start_time = std::chrono::steady_clock::now();
        client_instance.send_line(argv[3], std::chrono::seconds(10));

        // Wait for echo response matching original message
        for (;;)
        {
            std::string response = client_instance.fetch_line(std::chrono::seconds(10));
            if (response == argv[3])
                break;
        }

        auto end_time = std::chrono::steady_clock::now();
        auto duration = std::chrono::duration_cast<std::chrono::microseconds>(end_time - start_time);

        std::cout << "Round trip time: " << duration.count() << " microseconds\n";
    }
    catch (const std::exception& ex)
    {
        std::cerr << "Error: " << ex.what() << "\n";
        return 1;
    }

    return 0;
}

