struct NullValueReader {
    static void extractNullFlags(const uint8_t* pageFrame, PageCursor& cursor,
        ValueVector* outputVector, uint32_t outOffset, uint32_t count,
        const CompressionMetadata& compInfo) {

        if (compInfo.isConstant()) {
            bool constantVal = false;
            ConstantCompression::decompressValues(
                reinterpret_cast<uint8_t*>(&constantVal), 0, 1,
                PhysicalTypeID::BOOL, 1, compInfo);
            outputVector->setNullRange(outOffset, count, constantVal);
        } else {
            // Interpret the frame as an array of 64-bit words for bit extraction
            const uint64_t* bitArray = reinterpret_cast<const uint64_t*>(pageFrame);
            uint32_t bitOffset = cursor.elemPosInPage;
            outputVector->setNullFromBits(bitArray, bitOffset, outOffset, count);
        }
    }
};

NullColumn::NullColumn(const std::string& colName, FileHandle* dataFH, MemoryManager* mm,
    ShadowFile* shadowFile, bool enableCompression)
    : Column{colName, LogicalType::BOOL(), dataFH, mm, shadowFile, enableCompression,
             false /*requireNullColumn*/} {
    readToVectorFunc = NullValueReader::extractNullFlags;
}

