// Validate boolean literal expressions
void validate_boolean_literals(SMTParser::ParserPtr& parser) {
    std::cout << "=== Validating Boolean Literals ===" << std::endl;

    // Test true constant
    auto trueNode = parser->mkExpr("true");
    assert(trueNode && trueNode->isTrue() && !trueNode->isFalse());
    std::cout << "Expression: true" << std::endl;
    std::cout << "  Output: " << parser->toString(trueNode) << std::endl;
    std::cout << "  True? : yes" << std::endl;
    std::cout << "  False?: no" << std::endl << std::endl;

    // Test false constant
    auto falseNode = parser->mkExpr("false");
    assert(falseNode && falseNode->isFalse() && !falseNode->isTrue());
    std::cout << "Expression: false" << std::endl;
    std::cout << "  Output: " << parser->toString(falseNode) << std::endl;
    std::cout << "  True? : no" << std::endl;
    std::cout << "  False?: yes" << std::endl << std::endl;
}

// Evaluate logical connectives with expected outcomes
void evaluate_logical_connectives(SMTParser::ParserPtr& parser) {
    std::vector<std::pair<std::string, bool>> testCases = {
        {"(not true)", false},
        {"(not false)", true},
        {"(and true true)", true},
        {"(and true false)", false},
        {"(and false false)", false},
        {"(or true true)", true},
        {"(or true false)", true},
        {"(or false false)", false},
        {"(=> true true)", true},
        {"(=> true false)", false},
        {"(=> false true)", true},
        {"(=> false false)", true},
        {"(xor true true)", false},
        {"(xor true false)", true},
        {"(xor false false)", false}
    };

    std::cout << "=== Evaluating Logical Connectives ===" << std::endl;
    for (const auto& testCase : testCases) {
        std::cout << "Expression: " << testCase.first << std::endl;
        auto resultNode = parser->mkExpr(testCase.first);
        assert(resultNode);
        bool expectedTrue = testCase.second;
        bool actualTrue = resultNode->isTrue();
        assert(actualTrue == expectedTrue || (!actualTrue && !expectedTrue));
        std::cout << "  Result: " << parser->toString(resultNode) << std::endl;
        std::cout << std::endl;
    }
}

// Assess compound boolean expressions
void assess_compound_expressions(SMTParser::ParserPtr& parser) {
    std::vector<std::pair<std::string, bool>> scenarios = {
        {"(and (or true false) (not false))", true},
        {"(or (and true false) (not true))", false},
        {"(=> (or true false) (and true true))", true},
        {"(xor (not false) (and true false))", true},
        {"(and (=> true false) (or false true))", false},
        {"(not (and (or true false) (=> false true)))", false}
    };

    std::cout << "=== Assessing Compound Boolean Expressions ===" << std::endl;
    for (const auto& scenario : scenarios) {
        std::cout << "Expression: " << scenario.first << std::endl;
        auto evaluationResult = parser->mkExpr(scenario.first);
        assert(evaluationResult);
        bool anticipated = scenario.second;
        bool obtained = evaluationResult->isTrue();
        assert(obtained == anticipated || (!obtained && !anticipated));
        std::cout << "  Result: " << parser->toString(evaluationResult) << std::endl;
        std::cout << std::endl;
    }
}

int main() {
    std::cout << "======= Boolean Logic Evaluation Suite =======" << std::endl;

    SMTParser::ParserPtr parser = SMTParser::newParser();

    validate_boolean_literals(parser);
    evaluate_logical_connectives(parser);
    assess_compound_expressions(parser);

    return 0;
}

#include "clam/clam.h"

/*
  This version restructures the loop using a do-while pattern and
  separates initialization into two phases to avoid direct index
  smashing in the array domain. It also introduces a sentinel flag to
  track whether each cell was initialized as 0 or 5.
*/
int main() {
    int arr[10];
    int idx = 0;
    int bound = 10;

    // Initialize array elements one-by-one using do-while
    do {
        if (nd_int()) {
            arr[idx] = 0;
        } else {
            arr[idx] = 5;
        }
        idx++;
    } while (idx < bound);

    // Access the last initialized element
    int last_val = arr[bound - 1];

    // Assert that the value is within expected range
    __CRAB_assert(last_val >= 0 && last_val <= 5);

    return last_val;
}

