void InstallDialog::createDirectoryUnder(ArchiveTreeWidgetItem* item)
{
  // Guard against non-directory items
  if (!item->entry()->isDir()) {
    reportError(tr("Cannot create directory under a file."));
    return;
  }

  auto fileTree = item->entry()->astree();
  bool accepted = false;
  QString nameInput = QInputDialog::getText(this,
                                            tr("Enter a directory name"),
                                            tr("Name"),
                                            QLineEdit::Normal,
                                            QString(),
                                            &accepted);
  nameInput = nameInput.trimmed();

  if (accepted && !nameInput.isEmpty()) {
    if (fileTree->exists(nameInput)) {
      reportError(tr("A directory or file with that name already exists."));
      return;
    }

    item->setExpanded(true);
    ArchiveTreeWidgetItem* createdItem = m_Tree->addDirectory(item, nameInput);
    m_Tree->scrollToItem(createdItem);
  }
}

void InstallDialog::on_treeContent_customContextMenuRequested(QPoint position)
{
  ArchiveTreeWidgetItem* selected =
      static_cast<ArchiveTreeWidgetItem*>(m_Tree->itemAt(position));
  if (!selected) {
    return;
  }

  QMenu contextMenu;

  bool isRoot = (selected == m_Tree->root());
  bool isDirectory = selected->entry()->isDir();

  if (!isRoot && isDirectory) {
    contextMenu.addAction(tr("Set as <%1> directory").arg(m_DataFolderName),
                          [this, selected]() {
                            m_Tree->setDataRoot(selected);
                          });
  }

  bool hasDifferentRoot = (m_Tree->root()->entry() != m_TreeRoot->entry());
  if (hasDifferentRoot) {
    contextMenu.addAction(tr("Unset <%1> directory").arg(m_DataFolderName), [this]() {
      m_Tree->setDataRoot(m_TreeRoot);
    });
  }

  if (!contextMenu.isEmpty()) {
    contextMenu.addSeparator();
  }

  if (isDirectory) {
    contextMenu.addAction(tr("Create directory..."), [this, selected]() {
      createDirectoryUnder(selected);
    });
  } else {
    contextMenu.addAction(tr("&Open"), [this, selected]() {
      emit openFile(selected->entry().get());
    });
  }

  contextMenu.exec(m_Tree->mapToGlobal(position));
}

void InstallDialog::on_okButton_clicked()
{
  bool isValid = testForProblem();
  if (!isValid) {
    QMessageBox::StandardButton choice = QMessageBox::question(
        this,
        tr("Continue?"),
        tr("This mod was probably NOT set up correctly, most likely it will NOT "
           "work. "
           "You should first correct the directory layout using the content-tree."),
        QMessageBox::Ignore | QMessageBox::Cancel,
        QMessageBox::Cancel);

    if (choice == QMessageBox::Cancel) {
      return;
    }
  }

  accept();
}

void InstallDialog::on_cancelButton_clicked()
{
  reject();
}

#include <iostream>
#include <vector>
#include <numeric>
#include <algorithm>
#include <cmath>

std::vector<int> baskets[4];
std::vector<std::pair<int, int>> move_sequence;

void execute_transfer(int source, int destination) {
    // Find the middle ball according to the specified rule:
    // For k balls (1-indexed), the center position is (k + 2) / 2
    int count = baskets[source].size();
    int center_index_0_based = (count + 2) / 2 - 1;
    int selected_ball = baskets[source][center_index_0_based];

    // Locate and remove the selected ball from the source basket
    auto iter = std::lower_bound(baskets[source].begin(), baskets[source].end(), selected_ball);
    baskets[source].erase(iter);

    // Insert the ball into the destination basket and maintain sorted order
    baskets[destination].push_back(selected_ball);
    std::sort(baskets[destination].begin(), baskets[destination].end());

    // Log this transfer operation
    move_sequence.emplace_back(source, destination);
}

void solve_towers(int disks, int start, int target, int auxiliary) {
    if (disks <= 0) {
        return;
    }

    // Recursive Tower of Hanoi pattern:
    // Move top n-1 disks from start to auxiliary using target as helper
    solve_towers(disks - 1, start, auxiliary, target);

    // Move the current disk (middle ball) from start to target
    execute_transfer(start, target);

    // Move the n-1 disks from auxiliary to target using start as helper
    solve_towers(disks - 1, auxiliary, target, start);
}

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int total_balls;
    std::cin >> total_balls;

    // Initialize first basket with balls numbered 1 through N
    baskets[1].resize(total_balls);
    std::iota(baskets[1].begin(), baskets[1].end(), 1);

    // Execute the solution to move all balls from basket 1 to basket 3
    solve_towers(total_balls, 1, 3, 2);

    // Output results
    std::cout << move_sequence.size() << "\n";
    for (const auto& step : move_sequence) {
        std::cout << step.first << " " << step.second << "\n";
    }

    return 0;
}

#include "sax.h"
using namespace NConfig;

namespace {

    class TSax : public IConfig, public IConfig::IValue {
    public:
        explicit TSax(const TConfig& cfg)
            : Config_(cfg)
        {
        }

        void DoForEach(IFunc* func) override {
            if (!func) return;

            if (Config_.IsA<TArray>()) {
                const TArray& arr = Config_.Get<TArray>();
                for (size_t idx = 0; idx < arr.size(); ++idx) {
                    TSax child(arr[idx]);
                    func->Consume(FormatIndex(idx), &child);
                }
            } else if (Config_.IsA<TDict>()) {
                const TDict& dict = Config_.Get<TDict>();
                for (auto iter = dict.begin(); iter != dict.end(); ++iter) {
                    TSax child(iter->second);
                    func->Consume(iter->first, &child);
                }
            }
        }

        TString AsString() override {
            if (Config_.IsA<TArray>()) {
                const TArray& arr = Config_.Get<TArray>();
                if (!arr.empty()) {
                    TSax firstItem(arr.front());
                    return firstItem.AsString();
                }
                return TString{};
            }
            return Config_.As<TString>();
        }

        bool AsBool() override {
            return Config_.As<bool>();
        }

        IConfig* AsSubConfig() override {
            return this;
        }

        bool IsContainer() const override {
            return Config_.IsA<TArray>() || Config_.IsA<TDict>();
        }

        void DumpJson(IOutputStream& out) const override {
            Config_.DumpJson(out);
        }

        void DumpLua(IOutputStream& out) const override {
            Config_.DumpLua(out);
        }

    private:
        static TString FormatIndex(size_t index) {
            return TString::Number(index);
        }

        TConfig Config_;
    };

} // anonymous namespace

namespace NConfig {

    THolder<IConfig> ConfigParser(IInputStream& input, const TGlobals& globals) {
        TConfig root = TConfig::FromStream(input, globals);
        return MakeHolder<TSax>(std::move(root));
    }

}

