namespace ValdiTest {

// Helper lambda to reduce redundancy in path string comparisons
auto assertPathEq = [](const Path& p, const std::string& expected) {
    EXPECT_EQ(p.toString(), expected);
};

TEST(PathUtils, isAbsolutePathAcceptance) {
    ASSERT_TRUE(Path("/").isAbsolute());
    ASSERT_FALSE(Path("").isAbsolute());
    ASSERT_TRUE(Path("/test/dir").isAbsolute());
    ASSERT_FALSE(Path("test/dir").isAbsolute());
}

TEST(PathUtils, normalizePathAcceptance) {
    // Empty and root cases
    assertPathEq(Path("").normalize(), "");
    assertPathEq(Path("/").normalize(), "/");
    assertPathEq(Path("/test/").normalize(), "/test");
    assertPathEq(Path("test").normalize(), "test");

    // Multiple slashes
    assertPathEq(Path("test///dir").normalize(), "test/dir");

    // Single dot handling
    assertPathEq(Path("./").normalize(), "");
    assertPathEq(Path("/./").normalize(), "/");
    assertPathEq(Path("././test").normalize(), "test");
    assertPathEq(Path("/test/./././dir/.").normalize(), "/test/dir");

    // Double dot handling
    assertPathEq(Path("/test/../dir").normalize(), "/dir");
    assertPathEq(Path("/test/../../dir").normalize(), "/dir");
    assertPathEq(Path("test/../../dir").normalize(), "../dir");
    assertPathEq(Path("/test/dir/..").normalize(), "/test");
    assertPathEq(Path("test/dir/../..").normalize(), "");
    assertPathEq(Path("/../../test/dir/../..").normalize(), "/");
    assertPathEq(Path("../test/dir/../..").normalize(), "..");
    assertPathEq(Path("../test/dir/..").normalize(), "../test");
}

TEST(PathUtils, removeComponentAcceptance) {
    assertPathEq(Path("").removeLastComponent(), "");
    assertPathEq(Path("/").removeLastComponent(), "");
    assertPathEq(Path("test").removeLastComponent(), "");
    assertPathEq(Path("/test").removeLastComponent(), "/");
    assertPathEq(Path("test/dir").removeLastComponent(), "test");
    assertPathEq(Path("/test/dir").removeLastComponent(), "/test");
}

TEST(PathUtils, appendPathAcceptance) {
    assertPathEq(Path("").append(""), "");
    assertPathEq(Path("/").append(""), "/");
    assertPathEq(Path("").append("/"), "/");
    assertPathEq(Path("/").append("test"), "/test");
    assertPathEq(Path("./").append("/test").normalize(), "test");
    assertPathEq(Path("test").append("dir"), "test/dir");
    assertPathEq(Path("/test").append("dir"), "/test/dir");
    assertPathEq(Path("/test/dir").append("/path"), "/test/dir/path");
    assertPathEq(Path("test/dir").append("/path"), "test/dir/path");
    assertPathEq(Path("test/dir").append("../path").normalize(), "test/path");
}

TEST(PathUtils, removeFileExtensionAcceptance) {
    assertPathEq(Path("").removeFileExtension(), "");
    assertPathEq(Path("/").removeFileExtension(), "/");
    assertPathEq(Path("/test").removeFileExtension(), "/test");
    assertPathEq(Path("./test").removeFileExtension(), "./test");
    assertPathEq(Path("/test/").removeFileExtension(), "/test");
    assertPathEq(Path("./test/").removeFileExtension(), "./test");
    assertPathEq(Path("/test.foo").removeFileExtension(), "/test");
    assertPathEq(Path("./test.foo").removeFileExtension(), "./test");
}

TEST(PathUtils, appendFileExtensionAcceptance) {
    assertPathEq(Path("").appendFileExtension("bar"), "");
    assertPathEq(Path("/").appendFileExtension("bar"), "/.bar");
    assertPathEq(Path("/test").appendFileExtension("bar"), "/test.bar");
    assertPathEq(Path("./test").appendFileExtension("bar"), "./test.bar");
    assertPathEq(Path("/test/").appendFileExtension("bar"), "/test.bar");
    assertPathEq(Path("./test/").appendFileExtension("bar"), "./test.bar");
    assertPathEq(Path("/test.foo").appendFileExtension("bar"), "/test.foo.bar");
    assertPathEq(Path("./test.foo").appendFileExtension("bar"), "./test.foo.bar");
}

TEST(PathUtils, startsWithAcceptance) {
    EXPECT_TRUE(Path("").startsWith(Path("")));
    EXPECT_TRUE(Path("/").startsWith(Path("")));
    EXPECT_TRUE(Path("/").startsWith(Path("/")));
    EXPECT_FALSE(Path("/").startsWith(Path("/hello")));
    EXPECT_TRUE(Path("/hello").startsWith(Path("/")));
    EXPECT_FALSE(Path("hello").startsWith(Path("/")));
    EXPECT_FALSE(Path("hello/boy").startsWith(Path("/")));
    EXPECT_FALSE(Path("hello/boy").startsWith(Path("h")));
    EXPECT_TRUE(Path("hello/boy").startsWith(Path("hello")));
    EXPECT_TRUE(Path("hello/boy").startsWith(Path("hello/boy")));
    EXPECT_FALSE(Path("hello/boy").startsWith(Path("hello/boy/nein")));
}

TEST(PathUtils, getFileExtensionAcceptable) {
    EXPECT_EQ("", Path("").getFileExtension());
    EXPECT_EQ("", Path("hello").getFileExtension());
    EXPECT_EQ("txt", Path("hello.txt").getFileExtension());
    EXPECT_EQ("png", Path("nice/bro/hello.png").getFileExtension());
    EXPECT_EQ("jpg", Path("/nice/bro/hello.jpg").getFileExtension());
}

