class Solution {
public:
    int firstBadVersion(int n) {
        int left = 1;
        int right = n;
        int result = n;

        while (left <= right) {
            int mid = left + (right - left) / 2;

            if (isBadVersion(mid)) {
                result = mid;
                right = mid - 1;
            } else {
                left = mid + 1;
            }
        }

        return result;
    }
};

#include <vector>
using namespace std;

class Solution {
public:
    bool searchMatrix(vector<vector<int>>& matrix, int target) {
        int rows = matrix.size();
        if (rows == 0) return false;

        int cols = matrix[0].size();
        int row = 0;
        int col = cols - 1;

        while (row < rows && col >= 0) {
            int currentVal = matrix[row][col];

            if (currentVal > target) {
                col--;
            } else if (currentVal < target) {
                row++;
            } else {
                return true;
            }
        }

        return false;
    }
};

class Solution {
public:
    int missingNumber(vector<int>& nums) {
        int n = nums.size();
        sort(nums.begin(), nums.end());

        int current = 0;
        for (int i = 0; i < n; ++i) {
            if (nums[i] != current) {
                return current;
            }
            ++current;
        }

        return n;
    }
};

