    HmdDriverLoader* pHmdLoader = HmdDriverLoader::Instance();
    bool bWineDetected = Util::IsRunningOnWine();

    // Patch: Skip signature verification
    INSTALL_STUB_RET0(reinterpret_cast<void*>(pHmdLoader->GetBaseAddress() + 0x134FF0)); // VrDialogManager::VerifyLibrary

    // Conditional patching based on settings or Wine environment
    bool const disableOverlay = VRSettings::GetBool(STEAMVR_SETTINGS_DISABLE_OVERLAY, SETTING_DISABLE_OVERLAY_DEFAULT_VALUE);
    bool const disableSense   = VRSettings::GetBool(STEAMVR_SETTINGS_DISABLE_SENSE,   SETTING_DISABLE_SENSE_DEFAULT_VALUE);
    bool const disableDialog  = VRSettings::GetBool(STEAMVR_SETTINGS_DISABLE_DIALOG,  SETTING_DISABLE_DIALOG_DEFAULT_VALUE);

