      INSTALL_STUB(reinterpret_cast<void*>(pHmdLoader->GetBaseAddress() + 0x12F830)); // VrDialogManager::CreateDashboardProcess
    }

    if (disableDialog || disableSense || bWineDetected) {
      INSTALL_STUB(reinterpret_cast<void*>(pHmdLoader->GetBaseAddress() + 0x130020)); // VrDialogManager::CreateDialogProcess
    }

    CaesarManagerHooks::InstallHooks();
    HmdDeviceHooks::InstallHooks();
    UsbThreadHooks::InstallHooks();
