string reverseString(string &s) {
    // Reverse the string by swapping characters from both ends
    int left = 0;
    int right = s.length() - 1;

    while (left < right) {
        char temp = s[left];
        s[left] = s[right];
        s[right] = temp;

        left++;
        right--;
    }

    return s;
}

