namespace hydra::horizon::loader::plugins {

void Manager::Refresh() {
    // Reset plugin list and pre-allocate space
    plugins.clear();
    const auto& raw_configs = CONFIG_INSTANCE.GetLoaderPlugins();
    plugins.reserve(raw_configs.size());

    for (const auto& config : raw_configs) {
        // Validate plugin file path
        if (!std::filesystem::exists(config.path)) {
            LOG_ERROR(Other, "Plugin file path \"{}\" is missing",
                      config.path);
            continue;
        }

        if (!std::filesystem::is_regular_file(config.path)) {
            LOG_ERROR(Other, "Plugin path \"{}\" does not point to a regular file",
                      config.path);
            continue;
        }

        // Attempt to load the plugin
        try {
            plugins.emplace_back(config.path, config.options);
        } catch (const Plugin::Error&) {
            // Plugin loading failed due to general error
        } catch (const Plugin::ContextError&) {
            // Plugin loading failed due to context mismatch
        }
    }
}

Plugin* Manager::FindPluginForFormat(std::string_view format) {
    // Search through loaded plugins for one supporting the given format
    for (auto& plugin_instance : plugins) {
        if (std::any_of(plugin_instance.supported_formats.begin(),
                        plugin_instance.supported_formats.end(),
                        [&](const std::string& fmt) { return fmt == format; })) {
            return &plugin_instance;
        }
    }
    return nullptr;
}

} // namespace hydra::horizon::loader::plugins

