// Version macro for HIP registration
#define ROCP_REG_VERSION \
    ROCPROFILER_REGISTER_COMPUTE_VERSION_3( \
        HIP_VERSION_MAJOR, HIP_VERSION_MINOR, HIP_VERSION_PATCH)

ROCPROFILER_REGISTER_DEFINE_IMPORT(hip, ROCP_REG_VERSION)

namespace hip {

namespace {

// Atomic pointer to hold the current HIP API table
auto&
get_api_table_storage()
{
    static std::atomic<HipApiTable*> s_table{ nullptr };
    return s_table;
}

// Internal function to perform actual registration
void
init_registration()
{
    // Immutable base table initialized first
    static HipApiTable s_base_table{};
    initialize_hip_api_table(&s_base_table);

    // Atomically install base table as initial active table
    get_api_table_storage().store(&s_base_table, std::memory_order_release);

    // Prepare modifiable copy for profiler instrumentation
    static HipApiTable s_instrumented_table{};
    copy_hip_api_table(&s_instrumented_table, &s_base_table);

    void* p_instrumented = &s_instrumented_table;
    rocprofiler_register_library_indentifier_t lib_id{};

    auto result = rocprofiler_register_library_api_table(
        "hip",
        &ROCPROFILER_REGISTER_IMPORT_FUNC(hip),
        ROCP_REG_VERSION,
        &p_instrumented,
        1,
        &lib_id);

    if (result == 0) {
        HipApiTable* expected = &s_base_table;
        if (!get_api_table_storage().compare_exchange_strong(
                expected, &s_instrumented_table)) {
            std::cerr << "[ERROR] Registration conflict: expected base table, "
                         "but found another. Aborting.\n";
            std::abort();
        }
    }
}

// Public-facing registration guard (ensures single execution)
void
ensure_registered()
{
    static std::atomic<bool> s_flag{ false };

    if (!s_flag.load(std::memory_order_acquire)) {
        using lock_type = std::unique_lock<std::recursive_mutex>;
        using once_flag = std::once_flag;

        static once_flag s_once{};
        static std::recursive_mutex s_mutex{};

        // Avoid deadlock if same thread re-enters during registration
        lock_type lk{s_mutex, std::defer_lock};
        if (lk.owns_lock()) return;  // already inside critical section

        lk.lock();

        std::call_once(s_once, init_registration);
        s_flag.store(true, std::memory_order_release);
    }
}

}  // namespace

// Exposed accessor: triggers registration if needed, returns current API table
HipApiTable*
get_hip_api_table()
{
    ensure_registered();
    return get_api_table_storage().load(std::memory_order_relaxed);
}

}  // namespace hip

