XmlPlaneWriter::XmlPlaneWriter(QFile &XFile) : XflXmlWriter(XFile)
{
}

void XmlPlaneWriter::writeHeader()
{
    writeDTD("<!DOCTYPE flow5>");
}

void XmlPlaneWriter::writeXMLPlane(PlaneXfl const &aircraft, bool shouldWriteAirfoils)
{
    writeStartDocument();

    // Write document header information
    writeHeader();
    writeStartElement("xflplane");
    writeAttribute("version", "1.0");

    {
        // Add documentation comments
        writeComment("For convenience, all field names are case-insensitive, as an exception to the standard xml specification");
        writeComment("Where applicable, default values will be used for all undefined fields");

        writeUnits();

        // Begin main Plane element
        writeStartElement("Plane");

        {
            // Write basic aircraft information
            writeTextElement("Name", aircraft.name());

            if (!aircraft.description().isEmpty()) {
                writeTextElement("Description", aircraft.description());
            }

            writeTheStyle(aircraft.theStyle());

            // Handle point masses if any exist
            int massCount = aircraft.pointMassCount();
            if (massCount > 0) {
                writeStartElement("Inertia");

                for (int pmIndex = 0; pmIndex < massCount; ++pmIndex) {
                    writePointMass(aircraft.pointMassAt(pmIndex));
                }

                writeEndElement(); // Inertia
            }

            // Process fuselages
            int fuseCount = aircraft.nFuse();
            for (int fIdx = 0; fIdx < fuseCount; ++fIdx) {
                if (aircraft.fuseAt(fIdx) && aircraft.fuseAt(fIdx)->isXflType()) {
                    FuseXfl const* pFuselage = dynamic_cast<FuseXfl const*>(aircraft.fuseAt(fIdx));
                    writeXflFuse(*pFuselage, aircraft.fusePos(0));
                }
            }

            // Process wings
            int wingCount = aircraft.nWings();
            for (int wIdx = 0; wIdx < wingCount; ++wIdx) {
                if (aircraft.wingAt(wIdx)) {
                    writeWing(*aircraft.wingAt(wIdx), 
                             aircraft.wingLE(wIdx), 
                             aircraft.rxAngle(wIdx), 
                             aircraft.ryAngle(wIdx), 
                             shouldWriteAirfoils);
                }
            }
        }

        writeEndElement(); // Plane
    }

    writeEndElement(); // xflplane
    writeEndDocument();
}

class Solution {
public:
    int minOperations(vector<int>& nums) {
        int count = 0;
        int prev = -1;

        for (int current : nums) {
            if (current > prev) {
                if (current > 0) {
                    count++;
                }
                prev = current;
            } else {
                // Skip elements that don't maintain increasing order
                continue;
            }
        }

        return count;
    }
};

#include <iostream>
#include <vector>
using namespace std;

// Global variables to store the array and its size
int n;
vector<int> a;

// Recursive function to determine array elements using queries
void processRange(int left, int right) {
    // Base case: invalid range
    if (left > right) return;

    // Skip already-filled positions from the left
    while (left <= right && a[left] != 0) left++;
    // Skip already-filled positions from the right
    while (right >= left && a[right] != 0) right--;

    // If no unfilled positions remain, exit
    if (left > right) return;

    // Query the current segment [left, right]
    cout << "? " << left << " " << right << endl;
    int value, frequency;
    cin >> value >> frequency;

    // Handle error response
    if (value == -1) exit(0);

    // If all positions in the range are filled with 'value', fill them directly
    if (frequency == right - left + 1) {
        for (int idx = left; idx <= right; ++idx) {
            a[idx] = value;
        }
        return;
    }

    // Split the range at midpoint
    int center = (left + right) / 2;

    // Process left half first
    processRange(left, center);

    // Use query information to pre-fill some elements in the right half
    // Check if 'value' appears at the center position
    if (a[center] == value) {
        int countLeft = 0;
        int pos = center;

        // Count consecutive occurrences of 'value' ending at 'center'
        while (pos >= left && a[pos] == value) {
            countLeft++;
            pos--;
        }

        // Calculate how many 'value's should be in the right half
        int remaining = frequency - countLeft;
        for (int offset = 1; offset <= remaining; ++offset) {
            int targetIndex = center + offset;
            if (targetIndex <= n) {
                a[targetIndex] = value;
            }
        }
    }

    // Process right half
    processRange(center + 1, right);
}

int main() {
    // Optimize I/O operations
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    if (cin >> n) {
        a.assign(n + 1, 0); // Initialize with zeros (1-based indexing)
        processRange(1, n);

        // Output final result
        cout << "! ";
        for (int i = 1; i <= n; ++i) {
            cout << a[i];
            if (i < n) cout << " ";
        }
        cout << "\n";
    }

    return 0;
}

