using asio::post;
using asio::thread_pool;
using asio::use_future;

// Modified active object pattern with equivalent functionality
class bank_account
{
    int balance_ = 0;
    mutable thread_pool pool_{1};
public:
    void deposit(int amount)
    {
        auto future = post(pool_, use_future([=] {
            balance_ += amount;
        }));
        future.wait();
        future.get();
    }

    void withdraw(int amount)
    {
        auto future = post(pool_, use_future([=] {
            if (balance_ >= amount) {
                balance_ -= amount;
            }
        }));
        future.wait();
        future.get();
    }

    int balance() const
    {
        auto future = post(pool_, use_future([=] {
            return balance_;
        }));
        future.wait();
        return future.get();
    }
};

int main()
{
    bank_account acct;
    acct.deposit(20);
    acct.withdraw(10);
    std::cout << "balance = " << acct.balance() << "\n";
    return 0;
}

