#include <Application.h>
#include <Bitmap.h>
#include <BitmapStream.h>
#include <File.h>
#include <TranslationUtils.h>
#include <TranslatorRoster.h>
#include <iostream>
#include <cstring>

class ImageExporter : public BApplication {
public:
    ImageExporter(int argc, char** argv)
        : BApplication("application/x-vnd.image-exporter"),
          fArgc(argc),
          fArgv(argv)
    {
    }

    void ReadyToRun() override {
        if (fArgc < 2) {
            std::cerr << "Usage: " << fArgv[0] << " <input_image>" << std::endl;
            PostMessage(B_QUIT_REQUESTED);
            return;
        }

        const char* inputPath = fArgv[1];

        // Load the source image
        BBitmap* bitmap = BTranslationUtils::GetBitmapFile(inputPath);
        if (!bitmap) {
            std::cerr << "Error: Unable to load image '" << inputPath << "'" << std::endl;
            PostMessage(B_QUIT_REQUESTED);
            return;
        }

        // Wrap bitmap in a stream for translation
        BBitmapStream bitmapStream(bitmap);

        // Access default translator roster
        BTranslatorRoster* roster = BTranslatorRoster::Default();
        if (!roster) {
            std::cerr << "Error: Could not retrieve translator roster" << std::endl;
            delete bitmap;
            PostMessage(B_QUIT_REQUESTED);
            return;
        }

        // Export as JPEG
        {
            BFile jpegOutput("output.jpg", 
                B_CREATE_FILE | B_ERASE_FILE | B_WRITE_ONLY);
            status_t result = roster->Translate(&bitmapStream, nullptr, nullptr, &jpegOutput, B_JPEG_FORMAT);

            if (result != B_OK) {
                std::cerr << "JPEG export failed: " << strerror(result) << std::endl;
            } else {
                std::cout << "Successfully exported: output.jpg" << std::endl;
            }
        }

        // Reset stream position for next export
        bitmapStream.Seek(0, SEEK_SET);

        // Export as PNG
        {
            BFile pngOutput("output.png", 
                B_CREATE_FILE | B_ERASE_FILE | B_WRITE_ONLY);
            status_t result = roster->Translate(&bitmapStream, nullptr, nullptr, &pngOutput, B_PNG_FORMAT);

            if (result != B_OK) {
                std::cerr << "PNG export failed: " << strerror(result) << std::endl;
            } else {
                std::cout << "Successfully exported: output.png" << std::endl;
            }
        }

        delete bitmap;
        PostMessage(B_QUIT_REQUESTED);
    }

private:
    int fArgc;
    char** fArgv;
};

int main(int argc, char** argv) {
    ImageExporter app(argc, argv);
    app.Run();
    return 0;
}

#include <iostream>
#include <vector>
using namespace std;

// Dutch National Flag Algorithm - Alternative Implementation
// This function reorders a vector containing only 0s, 1s, and 2s in-place
// using the three-pointer approach developed by Edsger Dijkstra

void reorderColors(vector<int>& arr) {
    // Initialize pointers for partitioning
    int start = 0;        // Points to the end of the 0s section
    int current = 0;      // Current element being examined
    int end = arr.size() - 1;  // Points to the start of the 2s section

    // Process elements until current pointer crosses end pointer
    while (current <= end) {
        if (arr[current] == 0) {
            // Element is 0: swap with start boundary and advance both pointers
            swap(arr[current], arr[start]);
            start++;
            current++;
        }
        else if (arr[current] == 2) {
            // Element is 2: swap with end boundary and move end pointer backward
            swap(arr[current], arr[end]);
            end--;
            // Note: current is not incremented here since swapped element needs verification
        }
        else {
            // Element is 1: leave in place and advance current pointer
            current++;
        }
    }
}

int main() {
    // Test case with mixed 0s, 1s, and 2s
    vector<int> input = {2, 0, 0, 0, 1, 1, 2, 2, 2, 2, 2, 1, 1, 1};

    // Apply the sorting algorithm
    reorderColors(input);

    // Output the sorted result
    for (int i = 0; i < input.size(); i++) {
        cout << input[i] << " ";
    }
    cout << endl;

    return 0;
}

