        REQUIRE(ap::string::urlEncode("hello") == "hello");
        REQUIRE(ap::string::urlEncode("HelloWorld") == "HelloWorld");
    }
    SECTION("Strings containing spaces") {
        REQUIRE(ap::string::urlEncode("hello world") == "hello%20world");
        REQUIRE(ap::string::urlEncode("Hello World Test") ==
                "Hello%20World%20Test");
    }
    SECTION("Strings with slashes preserved by default") {
        REQUIRE(ap::string::urlEncode("path/to/file") == "path/to/file");
        REQUIRE(ap::string::urlEncode("Folder/Sub/Dir") == "Folder/Sub/Dir");
    }
    SECTION("Strings with slashes explicitly encoded") {
        REQUIRE(ap::string::urlEncode("path/to/file", true) == "path%2Fto%2Ffile");
        REQUIRE(ap::string::urlEncode("Folder/Sub/Dir", true) ==
                "Folder%2FSub%2FDir");
    }
    SECTION("Complex filenames with special characters") {
        REQUIRE(ap::string::urlEncode(
                    "document-1234(202105)78:9<102::rev-abc>2.1.st;1-x.xml") ==
                "document-1234%28202105%2978%3A9%3C102%3A%3Arev-abc%3E2.1.st%3B1-"
                "x.xml");
        REQUIRE(ap::string::urlEncode("doc%282021%29data%3Aval%3Ckey%3Eend.xml") ==
                "doc%25282021%2529data%253Aval%253Ckey%253Eend.xml");
    }
}

