#include "oneDNN/Reorder.h"
using namespace kernels::xpu::oneDNN;

namespace at {
namespace AtenTypeXPU {

// Convert an opaque tensor to its plain (non-blocked) layout representation
at::Tensor DPCPPTensorConvertor::to_plain(const at::Tensor& input_tensor) {
  // If not an opaque tensor, return as-is
  if (!is_opaque_tensor(input_tensor)) {
    return input_tensor;
  }

  auto current_tensor = input_tensor;

  // Check whether the tensor's metadata dtype matches the stored context dtype
  bool dtype_mismatch = check_equality_for_meta_dtype_and_ctx_dtype(input_tensor);

  // Handle cases where metadata dtype differs from actual stored data type
  // e.g., during serialization: meta says u8, but context holds f32/s8/etc.
  if (dtype_mismatch) {
    // Infer correct dtype from context using opaqueTypeToScalarType
    auto inferred_dtype = opaqueTypeToScalarType(input_tensor);
    // Reconstruct tensor with correct dtype in meta
    current_tensor = at::empty_like(
        input_tensor,
        input_tensor.options().dtype(inferred_dtype));
    // Copy underlying data pointer without copying data
    unsafe_get_and_set_data_ptr(input_tensor, current_tensor);
  }

  // Prepare output tensor with same shape/layout as current_tensor
  auto output_tensor = at::empty_like(current_tensor);

  // Extract context info from input tensor
  auto* ctx_ptr = static_cast<DPCPPTensorContext*>(
      current_tensor.unsafeGetTensorImpl()->storage().data_ptr().get_context());
  DPCPPTensorContext ctx = *ctx_ptr;

  // Get target metadata (sizes/strides) for output tensor
  auto target_meta = ctx.aten_meta();

  // Share storage and set strides on output tensor
  auto output_view = share_storage_and_set_strided_as(
      output_tensor, target_meta.sizes_, target_meta.strides_, c10::nullopt);

  // Perform reorder operation (blocked → plain layout)
  kernels::xpu::oneDNN::reorder(current_tensor, output_view);

  // If original had mismatched dtypes, restore original metadata on output
  if (dtype_mismatch) {
    // Create new tensor matching original's meta
    output_tensor = at::empty_like(input_tensor);

    // Transfer context from view to final tensor
    unsafe_release_and_set_data_ptr(output_view, output_tensor);

    // Clean up temporary context attached to current_tensor
    current_tensor.unsafeGetTensorImpl()
        ->storage()
        .unsafeGetStorageImpl()
        ->mutable_data_ptr()
        .release_context();
  }

  return output_tensor;
}

// In-place version: modifies the input tensor to be plain
at::Tensor DPCPPTensorConvertor::to_plain_(at::Tensor& input_tensor) {
  if (!is_opaque_tensor(input_tensor)) {
    return input_tensor;
  }

  // Use out-of-place conversion first
  auto plain_tensor = to_plain(input_tensor);

  // Move context from converted tensor back into original tensor
  auto ctx = DPCPPTensorContext::get_tensor_ctx(plain_tensor);
  DPCPPTensorContext::set_tensor_ctx(input_tensor, std::move(ctx));

  return input_tensor;
}

