#include <iostream>
#include <vector>
using namespace std;

const int MAXN = 200005;
int resultArray[MAXN];
int arraySize;

// Function to perform a query and get mode and frequency
void askQuery(int left, int right, int &modeValue, int &frequency) {
    if (left > right) {
        modeValue = -1;
        frequency = -1;
        return;
    }

    cout << "? " << left << " " << right << endl;
    cin >> modeValue >> frequency;

    // Handle invalid response
    if (modeValue == -1) {
        exit(0);
    }
}

// Recursive function to fill the array
void reconstruct(int left, int right, int knownMode, int knownFreq) {
    if (left > right) return;

    int currentMode, currentFreq;

    // Use pre-known values if available, otherwise make a query
    if (knownMode != -1) {
        currentMode = knownMode;
        currentFreq = knownFreq;
    } else {
        askQuery(left, right, currentMode, currentFreq);
    }

    // If all elements in range are the same
    if (currentFreq == right - left + 1) {
        for (int idx = left; idx <= right; ++idx) {
            resultArray[idx] = currentMode;
        }
        return;
    }

    // Query left segment: [left, right - currentFreq]
    int leftMode, leftFreq;
    askQuery(left, right - currentFreq, leftMode, leftFreq);

    // Check if mode appears in left segment
    if (leftMode == currentMode) {
        // Left part contains the mode, process left first
        reconstruct(left, right - currentFreq, leftMode, leftFreq);
        // Remaining right part needs new query
        reconstruct(right - currentFreq + 1, right, -1, -1);
        return;
    }

    // Query right segment: [left + currentFreq, right]
    int rightMode, rightFreq;
    askQuery(left + currentFreq, right, rightMode, rightFreq);

    // Check if mode appears in right segment
    if (rightMode == currentMode) {
        // Right part contains the mode, process right first
        reconstruct(left, left + currentFreq - 1, -1, -1);
        reconstruct(left + currentFreq, right, rightMode, rightFreq);
        return;
    }

    // Mode must be in the overlapping middle section
    if (2 * currentFreq > right - left + 1) {
        int startMiddle = right - currentFreq + 1;
        int endMiddle = left + currentFreq - 1;
        for (int idx = startMiddle; idx <= endMiddle; ++idx) {
            resultArray[idx] = currentMode;
        }
    }

    // Continue processing both segments with gathered info
    reconstruct(left, right - currentFreq, leftMode, leftFreq);
    reconstruct(left + currentFreq, right, rightMode, rightFreq);
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    if (!(cin >> arraySize)) return 0;

    reconstruct(1, arraySize, -1, -1);

    cout << "!";
    for (int i = 1; i <= arraySize; ++i) {
        cout << " " << resultArray[i];
    }
    cout << endl;

    return 0;
}

