#include <iostream>
#include <vector>
using namespace std;

class SearchRotatedArray {
public:
    // Linear scan approach to find target in rotated sorted array with duplicates
    bool linearScan(vector<int>& arr, int val) {
        // Check first and last elements directly
        if (arr[0] == val || arr[arr.size() - 1] == val) {
            return true;
        }

        // Scan remaining elements one by one
        for (int idx = 1; idx < arr.size() - 1; ++idx) {
            if (arr[idx] == val) {
                return true;
            }
        }
        return false;
    }

    // Optimized binary search approach for rotated sorted array with duplicates
    bool efficientSearch(vector<int>& arr, int val) {
        // Handle edge cases where endpoints are the target
        if (arr[0] == val || arr[arr.size() - 1] == val) {
            return true;
        }

        int left = 0;
        int right = arr.size() - 1;

        while (left <= right) {
            int center = left + (right - left) / 2;

            // Found the target
            if (arr[center] == val) {
                return true;
            }

            // Handle duplicates at boundaries and center
            if (arr[left] == arr[center] && arr[right] == arr[center]) {
                ++left;
                --right;
            }
            // Left half is sorted
            else if (arr[left] <= arr[center]) {
                if (arr[left] <= val && val < arr[center]) {
                    right = center - 1;
                } else {
                    left = center + 1;
                }
            }
            // Right half is sorted
            else {
                if (arr[center] < val && val <= arr[right]) {
                    left = center + 1;
                } else {
                    right = center - 1;
                }
            }
        }
        return false;
    }
};

int main() {
    vector<int> data = {2, 5, 6, 0, 0, 1, 2};
    int query1 = 3;
    int query2 = 0;

    SearchRotatedArray solver;

    bool result1 = solver.efficientSearch(data, query1);
    cout << result1 << endl; // Expected: 0 (false)

    bool result2 = solver.efficientSearch(data, query2);
    cout << result2 << endl; // Expected: 1 (true)

    return 0;
}

#include "server.hpp"
