namespace http {
namespace server {

server::server(const std::string& addr, const std::string& port_str,
    const std::string& root_dir)
  : context_(1),
    stop_signals_(context_),
    listener_(context_),
    conn_manager_(),
    req_handler_(root_dir)
{
  // Set up signal handlers for graceful shutdown
  stop_signals_.add(SIGINT);
  stop_signals_.add(SIGTERM);
#if defined(SIGQUIT)
  stop_signals_.add(SIGQUIT);
#endif

  prepare_for_shutdown();

  // Resolve and bind to the specified address and port
  asio::ip::tcp::resolver resolver(context_);
  auto endpoints = resolver.resolve(addr, port_str);
  asio::ip::tcp::endpoint ep = *endpoints.begin();

  listener_.open(ep.protocol());
  listener_.set_option(asio::ip::tcp::acceptor::reuse_address(true));
  listener_.bind(ep);
  listener_.listen();

  start_accepting();
}

void server::run()
{
  // Run the event loop until all operations complete (e.g., on shutdown)
  context_.run();
}

void server::start_accepting()
{
  listener_.async_accept(
      [this](std::error_code ec, asio::ip::tcp::socket cli_socket)
      {
        // Exit early if acceptor was closed during shutdown
        if (!listener_.is_open())
          return;

        if (!ec)
        {
          conn_manager_.start(std::make_shared<connection>(
              std::move(cli_socket), conn_manager_, req_handler_));
        }

        // Continue accepting new connections
        start_accepting();
      });
}

void server::prepare_for_shutdown()
{
  stop_signals_.async_wait(
      [this](std::error_code /*err*/, int sig_num)
      {
        // Initiate shutdown: close acceptor and stop all active connections
        listener_.close();
        conn_manager_.stop_all();
      });
}

} // namespace server
} // namespace http

