#include <iostream>
#include <vector>
using namespace std;

int main() {
    // Initialize a vector with integers 1 through 5
    vector<int> v = {1, 2, 3, 4, 5};

    cout << "Original vector: ";
    for (int i = 0; i < v.size(); ++i) {
        cout << v[i] << " ";
    }
    cout << endl;

    // Manually reverse the vector by swapping elements from both ends
    int left = 0;
    int right = v.size() - 1;
    while (left < right) {
        int temp = v[left];
        v[left] = v[right];
        v[right] = temp;
        ++left;
        --right;
    }

    cout << "Reversed vector: ";
    for (int i = 0; i < v.size(); ++i) {
        cout << v[i] << " ";
    }
    cout << endl;

    // Create another vector and reverse only its first three elements
    vector<int> v1 = {1, 2, 3, 4, 5};

    // Reverse the first 3 elements manually
    int start = 0;
    int end = 2; // index of third element (0-based)
    while (start < end) {
        int temp = v1[start];
        v1[start] = v1[end];
        v1[end] = temp;
        ++start;
        --end;
    }

    cout << "Partially reversed vector: ";
    for (int i = 0; i < v1.size(); ++i) {
        cout << v1[i] << " ";
    }
    cout << endl;

    return 0;
}

