using namespace std;

// Definition for a binary tree node
struct TreeNode {
    int val;
    TreeNode *left;
    TreeNode *right;
    TreeNode() : val(0), left(nullptr), right(nullptr) {}
    TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
    TreeNode(int x, TreeNode *left, TreeNode *right) : val(x), left(left), right(right) {}
};

class Solution {
public:
    // Helper function to validate BST with given bounds
    bool checkBST(TreeNode* node, long lowerBound, long upperBound) {
        // Base case: null nodes are valid BSTs
        if (node == nullptr) return true;

        // Check if current node violates the BST property
        if (node->val <= lowerBound || node->val >= upperBound) {
            return false;
        }

        // Recursively validate left and right subtrees with updated bounds
        bool leftValid = checkBST(node->left, lowerBound, node->val);
        bool rightValid = checkBST(node->right, node->val, upperBound);

        return leftValid && rightValid;
    }

    // Main function to check if the tree is a valid BST
    bool isValidBST(TreeNode* root) {
        return checkBST(root, static_cast<long>(LONG_MIN), static_cast<long>(LONG_MAX));
    }
};

