// Constructor: creates a new buffer with specified capacity, initializes memory to zero
IntBuffer::IntBuffer(unsigned int capacity) : Buffer(capacity)
{
    buffer = new int[capacity];
    for (unsigned int i = 0; i < capacity; ++i)
        buffer[i] = 0;
}

// Constructor: uses an externally provided backing array
IntBuffer::IntBuffer(unsigned int capacity, int* backingArray) : Buffer(capacity)
{
    hasBackingArray = true;
    buffer = backingArray;
}

// Destructor: releases allocated memory only if not using external backing array
IntBuffer::~IntBuffer()
{
    if (!hasBackingArray && buffer != nullptr)
        delete[] buffer;
}

// Returns the internal buffer pointer
int* IntBuffer::getBuffer()
{
    return buffer;
}

// Flips the buffer: sets limit to current position, resets position to 0
IntBuffer* IntBuffer::flip()
{
    m_limit = m_position;
    m_position = 0;
    return this;
}

// Absolute read: retrieves value at specific index (bounds-checked)
int IntBuffer::get(unsigned int index)
{
    assert(index < m_limit);
    return buffer[index];
}

// Bulk put: copies elements from array segment [offset, offset+length) into buffer
IntBuffer* IntBuffer::put(intArray* inputArray, unsigned int offset, unsigned int length)
{
    assert(offset + length <= inputArray->length); // Adjusted assertion for correctness

    // Manual copy loop as alternative to std::copy
    for (unsigned int i = 0; i < length; ++i)
        buffer[m_position + i] = inputArray->data[offset + i];

    m_position += length;
    return this;
}

// Bulk put: copies entire source array into buffer
IntBuffer* IntBuffer::put(intArray inputArray)
{
    if (inputArray.length > remaining())
        assert(false); // TODO 4J Stu - Some kind of exception?

    // Manual copy loop instead of std::copy
    for (unsigned int i = 0; i < inputArray.length; ++i)
        buffer[m_position + i] = inputArray.data[i];

    m_position += inputArray.length;
    return this;
}

// Relative write: stores integer at current position and advances position
IntBuffer* IntBuffer::put(int value)
{
    assert(m_position < m_limit);
    buffer[m_position++] = value;
    return this;
}

#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

// Structure to represent an operation: moving box 'v' to stack 'i'
struct Operation {
    int box_value;
    int destination_stack;
};

int main() {
    // Fast I/O optimization
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int total_boxes, num_stacks;
    if (!(cin >> total_boxes >> num_stacks)) return 0;

    // Stacks are 1-indexed (index 0 unused)
    vector<vector<int>> stacks(num_stacks + 1);

    // Initialize stacks with given configuration
    int boxes_per_stack = total_boxes / num_stacks;
    for (int s = 1; s <= num_stacks; ++s) {
        for (int b = 0; b < boxes_per_stack; ++b) {
            int box;
            cin >> box;
            stacks[s].push_back(box);
        }
    }

    vector<Operation> operations;
    int next_target = 1;

    // Process each box in order from 1 to n
    while (next_target <= total_boxes) {
        int source_stack = -1;
        int box_position = -1;

        // Find the current target box
        for (int s = 1; s <= num_stacks; ++s) {
            for (size_t pos = 0; pos < stacks[s].size(); ++pos) {
                if (stacks[s][pos] == next_target) {
                    source_stack = s;
                    box_position = pos;
                    break;
                }
            }
            if (source_stack != -1) break;
        }

        // If the target is at the top of its stack, remove it directly
        if (box_position == (int)stacks[source_stack].size() - 1) {
            operations.push_back({next_target, 0});
            stacks[source_stack].pop_back();
            next_target++;
            continue;
        }

        // Otherwise, determine how many boxes need to be moved above the target
        int boxes_above = stacks[source_stack].size() - 1 - box_position;

        int best_chunk_size = -1;
        int best_destination = -1;
        long long best_score = -2e18;

        // Evaluate all possible chunk sizes and destinations
        for (int chunk_size = 1; chunk_size <= boxes_above; ++chunk_size) {
            int start_index = stacks[source_stack].size() - chunk_size;

            // Find maximum value in this chunk
            int max_in_chunk = -1;
            for (int k = 0; k < chunk_size; ++k) {
                max_in_chunk = max(max_in_chunk, stacks[source_stack][start_index + k]);
            }

            // Try each possible destination stack
            for (int dest = 1; dest <= num_stacks; ++dest) {
                if (dest == source_stack) continue;

                int top_of_dest = stacks[dest].empty() ? 1000 : stacks[dest].back();

                long long score;

                if (max_in_chunk < top_of_dest) {
                    // Valid move: maintain decreasing order
                    score = 200000LL + (long long)chunk_size * 1000 - (top_of_dest - max_in_chunk);
                } else {
                    // Invalid move: place larger on smaller
                    score = (long long)top_of_dest * 1000 + chunk_size;
                }

                if (score > best_score) {
                    best_score = score;
                    best_chunk_size = chunk_size;
                    best_destination = dest;
                }
            }
        }

        // Execute the best move found
        int move_start = stacks[source_stack].size() - best_chunk_size;
        int first_box_moved = stacks[source_stack][move_start];

        operations.push_back({first_box_moved, best_destination});

        // Transfer the chunk to the destination
        vector<int> temp;
        temp.reserve(best_chunk_size);
        for (int k = 0; k < best_chunk_size; ++k) {
            temp.push_back(stacks[source_stack][move_start + k]);
        }

        // Remove from source
        stacks[source_stack].resize(move_start);

        // Add to destination
        for (int val : temp) {
            stacks[best_destination].push_back(val);
        }
    }

    // Output all operations
    for (const auto& op : operations) {
        cout << op.box_value << " " << op.destination_stack << "\n";
    }

    return 0;
}

