int main() {
    std::printf("flow5 XFoil run\n");

    std::string airfoilName = "theNaca2410";
    std::cout << "Generating airfoil: " << airfoilName << '\n';

    Foil* airfoilPtr = foil::makeNacaFoil(2410, airfoilName);
    if (!airfoilPtr) {
        std::cerr << "Failed to create airfoil — aborting.\n";
        return 0;
    }

    std::cout << "Airfoil '" << airfoilPtr->name() 
              << "' successfully created and registered.\n\n";

    std::cout << "Airfoil details:\n";
    std::cout << airfoilPtr->name() << '\n';
    std::string propsStr = airfoilPtr->properties(true);
    std::cout << propsStr << "\n\n";

    // Create and register polar
    Polar* polarPtr = Objects2d::createPolar(airfoilPtr, xfl::T1POLAR, 100000.0, 0.0, 9.0, 1.0, 1.0);
    polarPtr->setName("T1 test polar");
    Objects2d::insertPolar(polarPtr);

    std::cout << "Polar info:\n";
    std::cout << polarPtr->name() << '\n';
    std::cout << polarPtr->properties() << "\n\n";

    bool retainOperatingPoints = true;
    XFoilTask* analysisTask = new XFoilTask;

    std::cout << "Initializing analysis task...\n";
    analysisTask->initialize(*airfoilPtr, polarPtr, retainOperatingPoints);

    analysisTask->appendRange({true, 0.0, 11.0, 1.0});
    analysisTask->appendRange({true, 0.0, -7.0, 1.0});

    std::cout << "Running analysis...\n";
    analysisTask->run();

    std::printf("%s", analysisTask->log().c_str());
    std::printf("\nAnalysis complete.\n\n");

    // Store each operating point in the global database
    const auto& oppList = analysisTask->operatingPoints();
    for (OpPoint* opp : oppList) {
