    }

    delete analysisTask;

    // Export polar data to string and print
    std::string exportBuffer;
    polarPtr->exportToString(exportBuffer, false, true);
    std::printf("%s", exportBuffer.c_str());

    std::cout << "\nExport finished.\n";

    globals::saveFl5Project("/tmp/XFoilRun.fl5");
    globals::deleteObjects(); // Cleanup

    return 0;
}

#define SOL_ALL_SAFETIES_ON 1
#include <sol/sol.hpp>
#include <iostream>

// Helper function that doubles the input value and adds 20
int compute_value(int input) {
    return 20 + input;
}

// Function that prepends a message to the input string
std::string format_message(std::string message) {
    return "received: " + message;
}

// Variadic fallback handler for Lua function calls
sol::variadic_results handle_variadic_call(
    sol::this_state state, sol::variadic_args arguments) {

    sol::variadic_results results;

    // If exactly two integer arguments are provided, sum them
    if (arguments.size() == 2) {
        int first = arguments.get<int>(0);
        int second = arguments.get<int>(1);
        results.push_back({ state, sol::in_place, first + second });
    } 
    // Otherwise, return a default value
    else {
        results.push_back({ state, sol::in_place, 52 });
    }

    return results;
}

int main(int, char*[]) {
    std::cout << "=== overloading with fallback ===" << std::endl;

    sol::state lua_environment;
    lua_environment.open_libraries();

    // Register overloaded function 'f' with three variants
    lua_environment.set_function(
        "f", 
        sol::overload(compute_value, format_message, handle_variadic_call)
    );

    // Execute test cases in Lua
    lua_environment.script("print(f(1))");      // Calls compute_value
    lua_environment.script("print(f('hi'))");   // Calls format_message
    lua_environment.script("print(f(22, 11))"); // Calls handle_variadic_call (sum)
    lua_environment.script("print(f({}))");     // Calls handle_variadic_call (default)

    return 0;
}

