namespace ap::application {

//-------------------------------------------------------------------------
/// @details
///		Setup the paths. This looks in the current directory and all the
///		way up to the root for the testdata and testdata/source directory
///		Once it is found, the rest of the paths are set to the dir
//-------------------------------------------------------------------------
Error establishPaths() {
    // Assign the base test path
    config::paths() = testPath();

    // Create required directories
    auto err = config::paths().makePaths();
    if (err) return err;

    // Log diagnostic info
    LOG(Test, "Executable   :", application::execPath());
    LOG(Test, "Arguments    :", application::cmdline());
    LOG(Test, "Test path    :", testPath());

    return {};
}

//-------------------------------------------------------------------------
/// @details
///		Main entry point -- setup the environment and call the
///		TestMain to actually execute the tests
//-------------------------------------------------------------------------
ErrorCode Main() {
    // Redirect logging output to test console
    ::engine::monitor::MonitorType.setValue("TestConsole");

    // Reinitialize options from command line
    ::ap::application::Options::get().init();

    // Initialize engine subsystems
    auto initResult = engine::init();
    if (initResult) dev::fatality(_location, "Failed engine init", initResult);

    // Activate specific log levels by default
    log::enableLevel<true>(Lvl::Perf, Lvl::Dev);

    // Configure paths
    auto pathErr = establishPaths();
    if (pathErr) return pathErr.code();

    // Handle Python execution if applicable
    if (engine::python::isPython()) {
        auto pyErr = engine::python::execPython();
        if (pyErr) return pyErr;
        return {};
    }

    // Handle Java execution if applicable
    if (auto javaCheck = engine::java::isJava()) {
        auto javaErr = engine::java::execJava();
        if (javaErr) return javaErr;
        return {};
    }

#if ROCKETRIDE_PLAT_LIN
    // Prevent WSL1 usage due to known issues
    if (plat::isWsl1())
        dev::fatality(_location,
                      "Word DB does not work under WSL1: "
                      "https://github.com/microsoft/WSL/issues/902");
#endif

    // Set node ID configuration
    config::nodeId(false) = *nodeIdOpt;
    config::vars().add("NodeId", config::nodeId());

    // Parse test arguments into vector of C-strings
    std::vector<const Utf8Chr*> argPtrs;
    std::list<Text> argStorage;
    std::istringstream stream(testArgsOpt.val());

    Text token;
    while (stream >> token) {
        argStorage.push_front(token);
        argPtrs.push_back(&argStorage.front());
    }

    // Execute test suite
    auto exitCode = TestMain(argPtrs);
    LOG(Test, "Test returning code", exitCode);

    // Cleanup engine resources
    engine::deinit();
    return exitCode;
}
