// Custom stream class for testing buffered behavior
class custom_test_stream
{
public:
  using io_context_ref = asio::io_context&;
  using self_type = custom_test_stream;
  using executor_type = asio::io_context::executor_type;

  explicit custom_test_stream(asio::io_context& ctx)
    : context_(ctx)
  {
  }

  asio::io_context& get_io_context()
  {
    return context_;
  }

  self_type& get_lowest_layer()
  {
    return *this;
  }

  template <typename ConstBufferSequence>
  std::size_t write(const ConstBufferSequence&)
  {
    return 0;
  }

  template <typename ConstBufferSequence>
  std::size_t write(const ConstBufferSequence&, asio::error_code& ec)
  {
    ec.clear();
    return 0;
  }

  template <typename ConstBufferSequence, typename CompletionHandler>
  void async_write(const ConstBufferSequence&, CompletionHandler handler)
  {
    asio::error_code err;
    asio::post(context_,
        asio::detail::bind_handler(handler, err, 0));
  }

  template <typename MutableBufferSequence>
  std::size_t read(const MutableBufferSequence&)
  {
    return 0;
  }

  template <typename MutableBufferSequence>
  std::size_t read(const MutableBufferSequence&, asio::error_code& ec)
  {
    ec.clear();
    return 0;
  }

  template <typename MutableBufferSequence, typename CompletionHandler>
  void async_read(const MutableBufferSequence&, CompletionHandler handler)
  {
    asio::error_code err;
    asio::post(context_,
        asio::detail::bind_handler(handler, err, 0));
  }

private:
  asio::io_context& context_;
};

void verify_read_buffering()
{
  ASIO_CHECK(!asio::is_read_buffered<
      asio::ip::tcp::socket>::value);
  ASIO_CHECK(!!asio::is_read_buffered<
      asio::buffered_read_stream<
        asio::ip::tcp::socket> >::value);
  ASIO_CHECK(!asio::is_read_buffered<
      asio::buffered_write_stream<
        asio::ip::tcp::socket> >::value);
  ASIO_CHECK(!!asio::is_read_buffered<
      asio::buffered_stream<asio::ip::tcp::socket> >::value);
  ASIO_CHECK(!asio::is_read_buffered<custom_test_stream>::value);
  ASIO_CHECK(!!asio::is_read_buffered<
      asio::buffered_read_stream<custom_test_stream> >::value);
  ASIO_CHECK(!asio::is_read_buffered<
      asio::buffered_write_stream<custom_test_stream> >::value);
  ASIO_CHECK(!!asio::is_read_buffered<
      asio::buffered_stream<custom_test_stream> >::value);
}

ASIO_TEST_SUITE
(
  "is_read_buffered",
  ASIO_TEST_CASE(verify_read_buffering)
)

