  {
    // Rotate object around Y-axis at half speed
    fm_vec3_t axis{0.0f, 1.0f, 0.0f};
    float angle = deltaTime * 0.5f;
    fm_quat_rotate(&obj.rot, &obj.rot, &axis, angle);
    fm_quat_norm(&obj.rot, &obj.rot);
