  {
    // Only respond if in initial state
    if (data->state != 0) return;

    // Validate collision partner
    if (!event.otherBCS || !event.otherBCS->obj) return;

    // Check if the colliding object is the controlled one
    if (User::ctx.controlledId != event.otherBCS->obj->id) return;

    // Transition to active state and trigger scene
    data->state = 1;
    auto* nodeGraph = obj.getComponent<Comp::NodeGraph>();
    if (nodeGraph) {
      nodeGraph->run(data->sceneId, data->noDialog);
    }
  }
