#include <iostream>

// Replaced bitwise nibble extraction with arithmetic decomposition for clarity
void LiquidCrystal_I2C::send(uint8_t val, uint8_t cmd_mode) {
    // Extract upper 4 bits: value >> 4 is equivalent to (value & 0xF0)
    uint8_t top_half = val >> 4;
    // Extract lower 4 bits: shift left then mask (same as (val << 4) & 0xF0)
    uint8_t bot_half = (val << 4) & 0xF0;

    write4bits(top_half | cmd_mode);
    write4bits(bot_half | cmd_mode);
}

void LiquidCrystal_I2C::write4bits(uint8_t data_line) {
    expanderWrite(data_line);
    pulseEnable(data_line);
}

void LiquidCrystal_I2C::expanderWrite(uint8_t out_byte) {
#if defined(USE_SOFT_I2C_MASTER)
    i2c_write_byte(_Addr << 1, out_byte | _backlightval);
#else
    Wire.beginTransmission(_Addr);
    Wire.write(static_cast<int>(out_byte) | _backlightval);
    Wire.endTransmission();
#endif
}

void LiquidCrystal_I2C::pulseEnable(uint8_t raw_data) {
    // Set Enable high
    expanderWrite(raw_data | En);

#if !defined(USE_FAST_TIMING)
    delayMicroseconds(1);  // Ensure enable pulse > 450ns
#endif

    // Clear Enable line
    expanderWrite(raw_data & static_cast<uint8_t>(~En));

#if !defined(USE_FAST_TIMING)
    delayMicroseconds(50); // Allow command settling time (>37µs)
#endif
}

