void ThrownEnderpearl::onHit(HitResult* hitRes) {
    // Handle entity impact first
    if (hitRes->entity != nullptr) {
        auto dmgSrc = DamageSource::thrown(shared_from_this(), owner);
        hitRes->entity->hurt(dmgSrc, 0);
        delete dmgSrc;
    }

    // Spawn ender particles around impact point
    for (int idx = 0; idx < 32; ++idx) {
        level->addParticle(
            eParticleType_ender,
            x,
            y + rng->nextDouble() * 2.0,
            z,
            rng->nextGaussian(),
            0.0,
            rng->nextGaussian()
        );
    }

    // Only perform server-side logic
    if (level->isClientSide) return;

    // Safely attempt teleportation and damage application
    auto playerPtr = std::dynamic_pointer_cast<ServerPlayer>(owner);
    if (!playerPtr || playerPtr->removed) return;

    auto& conn = playerPtr->connection;
    if (conn->done || playerPtr->level != level) return;

    owner->teleportTo(x, y, z);
    owner->fallDistance = 0.0f;
    owner->hurt(DamageSource::fall, 5);

    remove();
}

