#include <iostream>

// Recursive function to solve Tower of Hanoi problem
void solveHanoi(int disks, char fromRod, char tempRod, char toRod) {
    // Base case: single disk movement
    if (disks == 1) {
        std::cout << "Move disk 1 from " << fromRod << " to " << toRod << std::endl;
        return;
    }

    // Move top (disks-1) disks from source to temporary rod
    solveHanoi(disks - 1, fromRod, toRod, tempRod);

    // Move the largest disk from source to destination
    std::cout << "Move disk " << disks << " from " << fromRod << " to " << toRod << std::endl;

    // Move the (disks-1) disks from temporary rod to destination
    solveHanoi(disks - 1, tempRod, fromRod, toRod);
}

int main() {
    int numberOfDisks;

    // Input number of disks
    std::cout << "Enter the number of disks: ";
    std::cin >> numberOfDisks;

    // Output the solution sequence
    std::cout << "The sequence of moves to solve the Tower of Hanoi for " 
              << numberOfDisks << " disks is:" << std::endl;

    // Call the recursive solver with rods A (source), B (auxiliary), C (destination)
    solveHanoi(numberOfDisks, 'A', 'B', 'C');

    return 0;
}

