#include <iostream>
#include <vector>

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    long long target_value;
    std::cin >> target_value;

    // Determine grid dimensions: 100x100 is sufficient for numbers up to 10^18
    const int max_size = 100;
    std::vector<std::vector<int>> matrix(max_size + 2, std::vector<int>(max_size + 2, 0));

    int active_layer = 1;

    // Process each bit position from least significant to most significant
    for (int bit_pos = 0; bit_pos < 61; ++bit_pos) {
        // Establish the default transition to next layer
        matrix[active_layer][active_layer + 1] = 1;

        // If current bit is set in target_value, add connections from all previous layers
        if ((target_value >> bit_pos) & 1) {
            for (int prev_layer = 1; prev_layer < active_layer; ++prev_layer) {
                matrix[prev_layer][active_layer + 1] = 1;
            }
        }

        active_layer++;
    }

    // Connect all active layers to final column
    for (int layer = 1; layer <= active_layer; ++layer) {
        matrix[layer][active_layer] = 1;
    }

    // Output grid size and contents
    std::cout << active_layer << '\n';
    for (int row = 1; row <= active_layer; ++row) {
        for (int col = 1; col <= active_layer; ++col) {
            std::cout << matrix[row][col];
            if (col < active_layer) {
                std::cout << ' ';
            }
        }
        std::cout << '\n';
    }

    return 0;
}

