#include <iostream>
#include <vector>
#include <queue>
#include <list>

// Topological sorting using Kahn's algorithm for DAGs
class Digraph {
    int nodeCount;                // Number of nodes
    std::list<int>* adjacencyList; // Adjacency list

public:
    Digraph(int n) : nodeCount(n) {
        adjacencyList = new std::list<int>[n];
    }

    void insertEdge(int from, int to) {
        adjacencyList[from].push_back(to);
    }

    void performTopologicalSort() {
        std::vector<int> inDegree(nodeCount, 0);

        // Compute in-degrees by traversing all edges
        for (int u = 0; u < nodeCount; ++u) {
            for (int neighbor : adjacencyList[u]) {
                inDegree[neighbor]++;
            }
        }

        // Initialize queue with all zero in-degree nodes
        std::queue<int> zeroInDegreeQueue;
        for (int i = 0; i < nodeCount; ++i) {
            if (inDegree[i] == 0) {
                zeroInDegreeQueue.push(i);
            }
        }

        std::vector<int> resultOrder;

        // Process nodes in BFS-like manner
        while (!zeroInDegreeQueue.empty()) {
            int current = zeroInDegreeQueue.front();
            zeroInDegreeQueue.pop();
            resultOrder.push_back(current);

            // Reduce in-degree of adjacent nodes
            for (int nextNode : adjacencyList[current]) {
                inDegree[nextNode]--;
                if (inDegree[nextNode] == 0) {
                    zeroInDegreeQueue.push(nextNode);
                }
            }
        }

        // Detect cycle: if not all nodes are processed
        if (static_cast<int>(resultOrder.size()) != nodeCount) {
            std::cout << "Cycle detected — topological ordering impossible." << std::endl;
            return;
        }

        // Output the sorted sequence
        std::cout << "Topological Order (Kahn's Method): ";
        for (int node : resultOrder) {
            std::cout << node << " ";
        }
        std::cout << std::endl;
    }

    void displayAdjacencyLists() {
        for (int i = 0; i < nodeCount; ++i) {
            std::cout << "Vertex " << i << ": ";
            for (int neighbor : adjacencyList[i]) {
                std::cout << neighbor << " ";
            }
            std::cout << std::endl;
        }
    }

    ~Digraph() {
        delete[] adjacencyList;
    }
};

int main() {
    Digraph g(6); // Create graph with 6 nodes

    // Add directed edges
    g.insertEdge(5, 2);
    g.insertEdge(5, 4);
    g.insertEdge(4, 0);
    g.insertEdge(4, 1);
    g.insertEdge(2, 3);
    g.insertEdge(3, 1);

    // Perform topological sort
    g.performTopologicalSort();

    return 0;
}

#include <iostream>
#include <vector>
#include <numeric>
#include <algorithm>

// Function to interact with the judge
int query(int left, int right) {
    if (left >= right) {
        // This case should be prevented by the main logic
        return -1;
    }
    std::cout << "? " << left << " " << right << std::endl;
    int result;
    std::cin >> result;
    return result;
}

// Main logic for a single test case
void solve() {
    int n;
    std::cin >> n;

    int low = 1;
    int high = n;

    while (low < high) {
        // Base case for a range of size 2
        if (high - low == 1) {
            int pos = query(low, high);
            if (pos == low) {
                low = high;  // The maximum is at position high
            } else {
                high = low;  // The maximum is at position low
            }
            break;
        }

        // Query the current range to find the position of the second max
        int second_max_pos = query(low, high);

        // Handle edge cases where the second max is at an endpoint
        if (second_max_pos == low) {
            low = second_max_pos + 1;
            continue;
        }
        if (second_max_pos == high) {
            high = second_max_pos - 1;
            continue;
        }

        // At this point, low < second_max_pos < high.
        // The maximum is either in [low, second_max_pos-1] or [second_max_pos+1, high].
        // We make a second query to determine which side contains the maximum.
        // To optimize, we query the smaller of the two potential ranges containing second_max_pos.
        if (second_max_pos - low < high - second_max_pos) {
            int candidate = query(low, second_max_pos);
            if (candidate == second_max_pos) {
                // The maximum of p[low...second_max_pos] is in [low, second_max_pos-1]
                // Since p[second_max_pos] is the second max of the larger range [low, high],
                // this element must be the overall max. So, narrow search to [low, second_max_pos-1].
                high = second_max_pos - 1;
            } else {
                // The maximum of p[low...second_max_pos] is at position candidate,
                // meaning the overall max of p[low...high] cannot be in [low, second_max_pos-1].
                // It must be in [second_max_pos+1, high].
                low = second_max_pos + 1;
            }
        } else {
            int candidate = query(second_max_pos, high);
            if (candidate == second_max_pos) {
                // The maximum of p[second_max_pos...high] is in [second_max_pos+1, high]
                // This must be the overall max of p[low...high].
                low = second_max_pos + 1;
            } else {
                // The maximum of p[second_max_pos...high] is at position candidate.
                // The overall max must be in [low, second_max_pos-1].
                high = second_max_pos - 1;
            }
        }
    }

    std::cout << "! " << low << std::endl;
}

int main() {
    // Fast I/O
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int test_cases;
    std::cin >> test_cases;

    while (test_cases--) {
        solve();
    }

    return 0;
}

