#include <queue>
#include <algorithm>

// State structure for priority queue operations
struct Candidate {
    int score;
    int length, time;

    // Custom comparator for min-heap behavior
    bool operator<(const Candidate& other) const {
        return score > other.score;
    }
};

void process() {
    int n;
    long long m;
    std::cin >> n >> m;

    // Read grid data (not used directly in this approach)
    std::vector<std::vector<int>> grid(n, std::vector<int>(n));
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            std::cin >> grid[i][j];
        }
    }

    // Min-heap using custom comparator
    std::priority_queue<Candidate> heap;

    // Initialize with all f(1, T) candidates where T ranges from 1 to 2n-1
    for (int T = 1; T < 2 * n; ++T) {
        std::cout << "? 1 " << T << std::endl;
        int val;
        std::cin >> val;
        heap.push({val, 1, T});
    }

    std::vector<int> answers;
    answers.reserve(m);

    // Extract m smallest values using priority queue
    for (int count = 0; count < m; ++count) {
        Candidate current = heap.top();
        heap.pop();
        answers.push_back(current.score);

        // Generate next candidate for same time T if possible
        if (current.length < n) {
            std::cout << "? " << current.length + 1 << " " << current.time << std::endl;
            int next_score;
            std::cin >> next_score;
            heap.push({next_score, current.length + 1, current.time});
        }
    }

    // Output final result
    std::cout << "!";
    for (int i = 0; i < m; ++i) {
        std::cout << " " << answers[i];
    }
    std::cout << std::endl;
}

int main() {
    // Optimize I/O performance
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int test_cases;
    std::cin >> test_cases;

    while (test_cases-- > 0) {
        process();
    }

    return 0;
}

