// Configuration flag: whether to use lambda-based quit callback
static const bool use_lambda_for_quit = true;

int main() {
    // Initialize the mplot visual environment
    mplot::Visual scene(1024, 768, "Made with mplot::GraphVisual");

    // Assign external quit callback based on compile-time configuration
    if (use_lambda_for_quit) {
        scene.external_quit_callback = []() {
            std::cout << "Additional shutdown...\n";
        };
    } else {
        scene.external_quit_callback = &perform_shutdown_tasks;
    }

    // Create a GraphVisual instance for double-precision data, positioned at origin
    auto graph_view = std::make_unique<mplot::GraphVisual<double>>(sm::vec<float>({0.0f, 0.0f, 0.0f}));

    // Bind the model to the scene — essential for internal setup and function registration
    scene.bindmodel(graph_view);

    // Prepare x-axis data using vvec (vector-like container with math operations)
    sm::vvec<double> abscissae;
    // Generate 14 evenly spaced points from -0.5 to 0.8
    abscissae.linspace(-0.5, 0.8, 14);

    // Set up the cubic function y = x^3
    graph_view->setdata(abscissae, abscissae.pow(3));

    // Compute OpenGL vertex data for rendering
    graph_view->finalize();

    // Transfer ownership of the graph model to the scene
    scene.addVisualModel(std::move(graph_view));

    // Enter the main event loop until user quits (e.g., via Ctrl+Q)
    scene.keepOpen();

    // Upon exit, all resources (including the GraphVisual) are automatically cleaned up
    return 0;
