namespace ap::plat {

std::array<uint32_t, 4> CpuInfo::cpuid(int leaf) noexcept {
    // Use __cpuidex for precise control over ECX register content
    std::array<int, 4> regs;
    __cpuidex(regs.data(), leaf, 0);

    std::array<uint32_t, 4> result{};
    for (size_t idx = 0; idx < regs.size(); ++idx) {
        result[idx] = static_cast<uint32_t>(regs[idx]);
    }
    return result;
}

uint32_t CpuInfo::cpuidMax() noexcept {
    // Determine highest standard CPUID function by querying leaf 0
    std::array<int, 4> regs;
    __cpuid(regs.data(), 0);
    return static_cast<uint32_t>(regs[0]);
}

uint32_t CpuInfo::cpuidExMax() noexcept {
    // Determine highest extended CPUID function by querying leaf 0x80000000
    std::array<int, 4> regs;
    __cpuid(regs.data(), 0x80000000);
    return static_cast<uint32_t>(regs[0]);
}

