#include <vector>
#include <algorithm>
#include <climits>

class Solution {
public:
    bool canCollect(int leftIdx, int rightIdx, const std::vector<std::vector<int>>& fruits, int startPos, int k) {
        int leftPos = fruits[leftIdx][0];
        int rightPos = fruits[rightIdx][0];

        if (rightPos <= startPos) {
            return (startPos - leftPos) <= k;
        } else if (leftPos >= startPos) {
            return (rightPos - startPos) <= k;
        } else {
            int distLeft = startPos - leftPos;
            int distRight = rightPos - startPos;
            return (2 * distLeft + distRight) <= k || (2 * distRight + distLeft) <= k;
        }
    }

    int maxTotalFruits(std::vector<std::vector<int>>& fruits, int startPos, int k) {
        int n = fruits.size();
        int result = 0;
        int currentSum = 0;
        int leftPtr = 0;

        for (int rightPtr = 0; rightPtr < n; ++rightPtr) {
            currentSum += fruits[rightPtr][1];

            while (leftPtr <= rightPtr && !canCollect(leftPtr, rightPtr, fruits, startPos, k)) {
                currentSum -= fruits[leftPtr][1];
                ++leftPtr;
            }

            result = std::max(result, currentSum);
        }

        return result;
    }
};

#include <iostream>
#include <vector>
#include <string>
#include <set>
#include <algorithm>

void process_case() {
    int total_words;
    std::cin >> total_words;

    if (total_words == 0) {
        std::cout << "answer" << std::endl;
        std::cout.flush();
        return;
    }

    std::set<std::string> collected_words;
    std::vector<std::string> promising_prefixes;

    // First pass: check each single-letter prefix from 'a' to 'z'
    for (char letter = 'a'; letter <= 'z'; ++letter) {
        std::string test_prefix(1, letter);
        std::cout << "query " << test_prefix << " " << 1 << std::endl;
        std::cout.flush();

        int count;
        std::cin >> count;

        if (count > 0) {
            promising_prefixes.push_back(test_prefix);

            std::string word;
            std::cin >> word;
            collected_words.insert(word);
        }
    }

    // Sort prefixes in reverse alphabetical order for processing
    std::sort(promising_prefixes.begin(), promising_prefixes.end(), 
              [](const std::string& a, const std::string& b) {
                  return a > b;
              });

    int remaining_count = total_words;

    // Process each promising prefix
    for (size_t idx = 0; idx < promising_prefixes.size(); ++idx) {
        const std::string& current_prefix = promising_prefixes[idx];

        // Count how many already-collected words match this prefix
        int matched_existing = 0;
        for (const auto& word : collected_words) {
            if (word.substr(0, current_prefix.length()) == current_prefix) {
                matched_existing++;
            }
        }

        // Calculate how many new words we expect to find with this query
        int expected_new = total_words - static_cast<int>(collected_words.size()) + matched_existing;

        // For the last prefix, use exact calculation
        if (idx == promising_prefixes.size() - 1) {
            expected_new = total_words - static_cast<int>(collected_words.size()) + matched_existing;
        }

        if (expected_new <= 0) continue;

        std::cout << "query " << current_prefix << " " << expected_new << std::endl;
        std::cout.flush();

        int response_count;
        std::cin >> response_count;

        for (int i = 0; i < response_count; ++i) {
            std::string new_word;
            std::cin >> new_word;
            collected_words.insert(new_word);
        }
    }

    // Output final answer
    std::cout << "answer";
    for (const auto& word : collected_words) {
        std::cout << " " << word;
    }
    std::cout << std::endl;
    std::cout.flush();
}

int main() {
    std::ios_base::sync_with_stdio(false);
