namespace rccl {

namespace {

using api_table_ptr = std::atomic<rcclApiFuncTable*>;

// State enum to manage registration phases
enum class RegistrationState : uint8_t {
    Uninitialized,
    InProgress,
    Completed
};

// Thread-safe singleton-like storage for API tables
api_table_ptr& get_api_table_storage() {
    static api_table_ptr table{ nullptr };
    return table;
}

// Helper: safely copy and initialize API tables
void populate_api_tables(
    rcclApiFuncTable& out_initial,
    rcclApiFuncTable& out_instrumented
) {
    initialize_rccl_api_table(&out_initial);
    copy_rccl_api_table(&out_instrumented, &out_initial);
}

// Helper: register library with rocprofiler-register
bool try_register_library(
    rcclApiFuncTable* initial,
    rcclApiFuncTable* instrumented,
    rocprofiler_register_library_indentifier_t& lib_id_out
) {
    void* table_ptr = static_cast<void*>(instrumented);
    auto result = rocprofiler_register_library_api_table(
        "rccl",
        &ROCPROFILER_REGISTER_IMPORT_FUNC(rccl),
        ROCP_REG_VERSION,
        &table_ptr,
        1,
        &lib_id_out
    );

    if (result == 0) {
        std::cout << "[" << get_filename() << "] rccl identifier " << lib_id_out.handle << "\n";
        return true;
    } else if (result != ROCP_REG_NO_TOOLS) {
        std::cerr << "rccl library failed to register with rocprofiler-register: "
                  << rocprofiler_register_error_string(result) << "\n";
        return false;
    }
    return false; // ROCP_REG_NO_TOOLS case: no tools, silently skip
}

// Core registration logic — encapsulated in lambda to avoid duplication
void perform_registration() {
    static rcclApiFuncTable initial_api_table{};
    static rcclApiFuncTable instrumented_api_table{};

    populate_api_tables(initial_api_table, instrumented_api_table);

    // Preemptively set initial table so recursive calls during registration don't fail
    auto& global_table = get_api_table_storage();
    global_table.store(&initial_api_table, std::memory_order_release);

    rocprofiler_register_library_indentifier_t lib_id{};
    if (!try_register_library(&initial_api_table, &instrumented_api_table, lib_id)) {
        std::exit(EXIT_FAILURE); // Only exit on hard failure
    }

    // Atomically swap to instrumented version
    rcclApiFuncTable* expected = &initial_api_table;
    if (!global_table.compare_exchange_strong(expected, &instrumented_api_table)) {
        std::cerr << "[ERROR] Unexpected race during API table promotion.\n";
        std::exit(EXIT_FAILURE);
    }
}

// Global registration guard with recursion protection
RegistrationState& get_registration_state() {
    static RegistrationState state = RegistrationState::Uninitialized;
    return state;
}

void ensure_registered() {
    auto& state = get_registration_state();

    // Fast path: already registered
    if (state == RegistrationState::Completed) return;

    // Use mutex + state check to prevent re-entry and ensure single initialization
    static std::mutex mtx;
    std::lock_guard lock{ mtx };

    // Double-check inside lock
    if (state == RegistrationState::Completed) return;

    if (state == RegistrationState::InProgress) {
        // Recursion detected: allow access to initial table only
        return;
    }

    state = RegistrationState::InProgress;

    try {
        perform_registration();
        state = RegistrationState::Completed;
    } catch (...) {
        state = RegistrationState::Uninitialized;
        throw;
    }
}

} // namespace

rcclApiFuncTable* get_rccl_api_table() {
    ensure_registered();
    return get_api_table_storage().load(std::memory_order_acquire);
}

void rccl_init() {
    std::cout << "[" << get_filename() << "] " << __FUNCTION__ << "\n";
}

} // namespace rccl

