// Function to perform a query and return the response
int performQuery(int u, int k, const std::vector<int>& rooms) {
    std::cout << "? " << u << " " << k << " " << rooms.size();
    for (int room : rooms) {
        std::cout << " " << room;
    }
    std::cout << std::endl;

    int result;
    std::cin >> result;
    if (result == -1) {
        // Handle error condition as per problem specification
        std::exit(0);
    }
    return result;
}

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int n;
    std::cin >> n;
    std::vector<int> mapping(n + 1);

    // Phase 1: Determine the mapping using binary search
    std::vector<int> possibleValues(n);
    std::iota(possibleValues.begin(), possibleValues.end(), 1);

    for (int position = 1; position <= n; ++position) {
        std::vector<int> candidates = possibleValues;

        while (candidates.size() > 1) {
            int splitPoint = candidates.size() / 2;
            std::vector<int> firstHalf(candidates.begin(), candidates.begin() + splitPoint);

            int answer = performQuery(position, 1, firstHalf);

            if (answer == 1) {
                // Target is in the first half
                candidates.resize(splitPoint);
            } else {
                // Target is in the second half
                candidates.erase(candidates.begin(), candidates.begin() + splitPoint);
            }
        }
        mapping[position] = candidates[0];
    }

    // Phase 2: Build adjacency list from the mapping
    std::vector<std::vector<int>> graph(n + 1);
    for (int i = 1; i <= n; ++i) {
        graph[i].push_back(mapping[i]);
        graph[mapping[i]].push_back(i);
    }

    // Phase 3: BFS traversal starting from node 1
    std::vector<int> reachableNodes;
    std::vector<bool> seen(n + 1, false);
    std::queue<int> frontier;

    frontier.push(1);
    seen[1] = true;

    while (!frontier.empty()) {
        int current = frontier.front();
        frontier.pop();
        reachableNodes.push_back(current);

        for (int neighbor : graph[current]) {
            if (!seen[neighbor]) {
                seen[neighbor] = true;
                frontier.push(neighbor);
            }
        }
    }

    // Sort the result for consistent output format
    std::sort(reachableNodes.begin(), reachableNodes.end());

    // Output the final answer
    std::cout << "! " << reachableNodes.size();
    for (int node : reachableNodes) {
        std::cout << " " << node;
    }
    std::cout << std::endl;

    return 0;
}

