#include <iostream>
#include <stack>
using namespace std;

int main() {
    // Initialize three stacks: s, s1 (default), and s2 (copy of s1)
    stack<int> s;
    stack<int> s1;
    stack<int> s2(s1);

    // Fill stack 's' with values 1 through 6 using push and emplace
    s.push(1);
    s.push(2);
    s.push(3);
    s.push(4);
    s.emplace(5);
    s.emplace(6);

    // Fill stack 's1' with values 7 through 10
    s1.push(7);
    s1.push(8);
    s1.push(9);
    s1.push(10);

    // Swap contents between s and s1
    s.swap(s1);

    // Display top element and size of s1 after swap
    cout << "s1 top: " << s1.top() << endl;   // Should be 10
    cout << "s1 size: " << s1.size() << endl; // Should be 4

    // Display top element and size of s2 (which now holds original s1 content)
    cout << "s2 top: " << s2.top() << endl;   // Should be 7
    cout << "s2 size: " << s2.size() << endl; // Should be 4

    // Remove top element from s (which is now the swapped version)
    s.pop(); // Removes 10

    // Show new top and size after pop
    cout << "Top after pop: " << s.top() << endl; // Should be 9
    cout << "Size after pop: " << s.size() << endl; // Should be 3

    // Check if stack is empty
    cout << "Is stack empty? " << (s.empty() ? "Yes" : "No") << endl;

    // Print all remaining elements by popping them one by one
    while (!s.empty()) {
        cout << s.top() << " ";
        s.pop();
    }
    cout << endl;

    // Final size check after full clearing
    cout << "Final size after clearing: " << s.size() << endl;

    return 0;
}

