                    entt::attribute{"wrap", true}
                });
        }
    }

    REFLECT(ui_tree)
    {
        detail::register_ui_tree_meta();
    }

    // Serialization helpers: generic save/load wrappers
    template<typename Archive>
    void serialize_ui_tree(Archive& ar, ui_tree& obj) {
        ar(ser20::make_nvp("content", obj.content));
    }

    SAVE(ui_tree)
    {
        serialize_ui_tree(ar, obj);
    }

    LOAD(ui_tree)
    {
        serialize_ui_tree(ar, obj);
    }

    // Explicit instantiation for archive types
    SAVE_INSTANTIATE(ui_tree, ser20::oarchive_associative_t);
    SAVE_INSTANTIATE(ui_tree, ser20::oarchive_binary_t);
    LOAD_INSTANTIATE(ui_tree, ser20::iarchive_associative_t);
    LOAD_INSTANTIATE(ui_tree, ser20::iarchive_binary_t);

    // Text-based file I/O: reads/writes raw string content
    void write_text_file(const std::string& path, const ui_tree::sptr& node) {
        if (!node || path.empty()) return;

        std::ofstream out(path);
        if (out.is_open() && out.good()) {
            out << node->content;
        }
    }

    void read_text_file(const std::string& path, ui_tree::sptr& node) {
        if (path.empty()) return;

        std::ifstream in(path);
        if (in.is_open() && in.good()) {
            node->content = fs::read_stream_str(in);
        }
    }

    // Binary serialization using Ser20
    void write_binary_file(const std::string& path, const ui_tree::sptr& node) {
        if (!node || path.empty()) return;

        std::ofstream out(path, std::ios::binary);
        if (out.is_open() && out.good()) {
            ser20::oarchive_binary_t ar(out);
            ar(ser20::make_nvp("ui_tree", *node));
        }
    }

    void read_binary_file(const std::string& path, ui_tree::sptr& node) {
        if (path.empty()) return;

        std::ifstream in(path, std::ios::binary);
        if (in.is_open() && in.good()) {
            ser20::iarchive_binary_t ar(in);
            ar(ser20::make_nvp("ui_tree", *node));
        }
    }

    // Public API aliases (renamed for clarity)
    void save_to_file(const std::string& absolute_path, const ui_tree::sptr& obj) {
        write_text_file(absolute_path, obj);
    }

    void save_to_file_bin(const std::string& absolute_path, const ui_tree::sptr& obj) {
        write_binary_file(absolute_path, obj);
    }

    void load_from_file(const std::string& absolute_path, ui_tree::sptr& obj) {
        read_text_file(absolute_path, obj);
    }

    void load_from_file_bin(const std::string& absolute_path, ui_tree::sptr& obj) {
        read_binary_file(absolute_path, obj);
    }
} // namespace unravel

