namespace vb {
namespace x86_64 {

// RelPatchObj provides a mechanism to defer patching of jump instructions in
// generated machine code. It supports both 8-bit (short) and 32-bit (long)
// relative jumps, with validation to ensure correctness at runtime or debug time.

RelPatchObj::RelPatchObj() VB_NOEXCEPT 
    : positionAfterInstruction_(0U), 
      binary_(nullptr), 
      initialized_(false), 
      short_(false) {
}

RelPatchObj::RelPatchObj(bool const isShort, uint32_t const positionAfterInstruction, MemWriter &binary) VB_NOEXCEPT
    : positionAfterInstruction_(positionAfterInstruction),
      binary_(&binary),
      initialized_(true),
      short_(isShort) {
}

// Links the jump target to the current end of the output binary stream.
void RelPatchObj::linkToHere() const {
  assert(initialized_ && "Attempting to modify an uninitialized patch object");
  linkToBinaryPos(binary_->size());
}

// Updates the jump offset to point to a specific location within the binary.
void RelPatchObj::linkToBinaryPos(uint32_t const targetPosition) const {
  assert(initialized_ && "Attempting to modify an uninitialized patch object");

  uint8_t* instructionEnd = binary_->posToPtr(positionAfterInstruction_);
  int64_t displacement = static_cast<int64_t>(targetPosition) - static_cast<int64_t>(positionAfterInstruction_);

  if (short_) {
    // Enforce compile-time assumption: only use short jumps when range is guaranteed.
    assert(displacement >= INT8_MIN && displacement <= INT8_MAX && 
           "Relative offset exceeds 8-bit signed range");

    // Patch the last byte before the end of the instruction with the 8-bit offset.
    writeToPtr<int8_t>(pSubI(instructionEnd, 1U), static_cast<int8_t>(displacement));
  } else {
    // Validate that the displacement fits into a 32-bit signed integer.
    if (displacement <= INT32_MIN || displacement >= INT32_MAX) {
      throw ImplementationLimitationException(
          ErrorCode::BrHANDLE_ERRORanches_can_only_maximally_target_32_bit_signed_offsets);
    }

    // Patch the 4 bytes preceding the end of the instruction with the 32-bit offset.
    writeToPtr<int32_t>(pSubI(instructionEnd, 4U), static_cast<int32_t>(displacement));
  }
}

// Retrieves the current target position encoded in the jump instruction.
uint32_t RelPatchObj::getLinkedBinaryPos() const VB_NOEXCEPT {
  assert(initialized_ && "Attempting to read from an uninitialized patch object");

  uint8_t const* instructionEnd = binary_->posToPtr(positionAfterInstruction_);
  int64_t baseOffset = static_cast<int64_t>(positionAfterInstruction_);

  int64_t resolvedTarget;
  if (short_) {
    // Read the 8-bit displacement and compute the absolute target position.
    resolvedTarget = baseOffset + readFromPtr<int8_t>(pSubI(instructionEnd, 1));
  } else {
    // Read the 32-bit displacement and compute the absolute target position.
    resolvedTarget = baseOffset + readFromPtr<int32_t>(pSubI(instructionEnd, 4));
  }

  assert(resolvedTarget >= 0 && resolvedTarget <= UINT32_MAX &&
         "Resolved target position out of valid addressable range");

  return static_cast<uint32_t>(resolvedTarget);
}

} // namespace x86_64
} // namespace vb
#endif

