// Custom exception handler for Lua script errors
int custom_lua_error_handler(lua_State* L,
    sol::optional<const std::exception&> maybe_ex,
    sol::string_view desc) {

    std::cout << "Error caught during script execution: ";

    if (maybe_ex.has_value()) {
        const std::exception& ex = maybe_ex.value();
        std::cout << "[Exception message] " << ex.what() << std::endl;
    } else {
        std::cout << "[Description] ";
        std::cout.write(desc.data(), static_cast<std::streamsize>(desc.size()));
        std::cout << std::endl;
    }

    // Push the description as a string onto the Lua stack for error propagation
    return sol::stack::push(L, desc);
}

// Function that deliberately throws an exception
void trigger_exception() {
    throw std::runtime_error("Runtime error occurred in C++ function!");
}

int main() {
    std::cout << "=== Lua Exception Handling Demo ===" << std::endl;

    sol::state lua_vm;
    lua_vm.open_libraries(sol::lib::base);

    // Register our custom exception handler
    lua_vm.set_exception_handler(custom_lua_error_handler);

    // Expose the C++ function to Lua
    lua_vm.set_function("trigger_error", trigger_exception);

    // Execute Lua script with error handling enabled
    sol::protected_function_result result = lua_vm.safe_script(
        "trigger_error()", 
        sol::script_pass_on_error
    );

    // Verify that the script failed as expected
    if (!result.valid()) {
        sol::error error_obj = result;
        std::cout << "Lua reported error: " << error_obj.what() << std::endl;
    }

    std::cout << std::endl;
    return 0;
}

