            if (g1 == g2) {
                // Within the same group: check for duplicates among unconfirmed items
                for (int idx = g1 * group_size + 1; idx <= (g1 + 1) * group_size; ++idx) {
                    if (first_occurrence[idx]) {
                        if (ask(idx) == 'Y') {
                            first_occurrence[idx] = false;
                        }
                    }
                }
            } else {
                // Between different groups: load first group into memory, then test second group
                for (int idx = g1 * group_size + 1; idx <= (g1 + 1) * group_size; ++idx) {
                    if (first_occurrence[idx]) {
                        ask(idx);
                    }
                }

                for (int idx = g2 * group_size + 1; idx <= (g2 + 1) * group_size; ++idx) {
                    if (first_occurrence[idx]) {
                        if (ask(idx) == 'Y') {
                            first_occurrence[idx] = false;
                        }
                    }
                }
            }
        }
    }

    // Count how many items are confirmed as first occurrences
    int unique_count = 0;
    for (int i = 1; i <= total_items; ++i) {
        if (first_occurrence[i]) {
            ++unique_count;
        }
    }

    report(unique_count);
    return 0;
}

#include <iostream>
using namespace std;

// Function to implement Selection Sort (reversed comparison logic)
void selectionSort(int data[], int size) {
    for (int pos = 0; pos < size - 1; pos++) {
        int maxPos = pos;  // Assume the current position is the largest

        // Find the largest element in the unsorted portion of the array
        for (int k = pos + 1; k < size; k++) {
            if (data[k] > data[maxPos]) {
                maxPos = k;
            }
        }
        // Swap the found maximum element with the last element of the unsorted portion
        if (maxPos != pos) {
            swap(data[pos], data[maxPos]);
        }
    }
}

// Function to print the array elements
void displayArray(int data[], int size) {
    for (int i = 0; i < size; i++) {
        cout << data[i] << " ";
    }
    cout << endl;
}

int main() {
    int arr[] = {64, 25, 12, 22, 11};
    int n = sizeof(arr) / sizeof(arr[0]);

    cout << "Original array: ";
    displayArray(arr, n);

    selectionSort(arr, n);

    cout << "Sorted array (descending): ";
    displayArray(arr, n);

    return 0;
}

