#include <assert.h>
#include <mpi.h>
#include <stdio.h>
#include <stdlib.h>
#include <time.h>

// Generate an array of random floating-point values in [0, 1]
float*
generate_random_values(int count)
{
    float* values = (float*) malloc(sizeof(float) * count);
    assert(values != NULL);

    for (int idx = 0; idx < count; ++idx) {
        values[idx] = static_cast<float>(rand()) / static_cast<float>(RAND_MAX);
    }

    return values;
}

// Compute the arithmetic mean of a given array
float
calculate_mean(const float* data, int length)
{
    float total = 0.0f;
    for (int i = 0; i < length; ++i) {
        total += data[i];
    }
    return total / static_cast<float>(length);
}

int
main(int argc, char** argv)
{
    if (argc != 2) {
        fprintf(stderr, "Usage: %s num_elements_per_process\n", argv[0]);
        exit(EXIT_FAILURE);
    }

    int elements_per_rank = atoi(argv[1]);

    // Initialize random seed for different results per run
    srand(static_cast<unsigned>(time(NULL)));

    MPI_Init(nullptr, nullptr);

    int my_rank;
    MPI_Comm_rank(MPI_COMM_WORLD, &my_rank);

    int num_ranks;
    MPI_Comm_size(MPI_COMM_WORLD, &num_ranks);

    float* global_data = nullptr;

    // Root process generates the full dataset
    if (my_rank == 0) {
        global_data = generate_random_values(elements_per_rank * num_ranks);
    }

    // Allocate local buffer for receiving scattered data
    float* local_data = (float*) malloc(sizeof(float) * elements_per_rank);
    assert(local_data != nullptr);

    // Distribute data evenly across all processes
    MPI_Scatter(global_data, elements_per_rank, MPI_FLOAT,
                local_data, elements_per_rank, MPI_FLOAT, 0, MPI_COMM_WORLD);

    // Compute local average
    float local_avg = calculate_mean(local_data, elements_per_rank);

    // Collect all local averages into an array on each process
    float* all_local_avgs = (float*) malloc(sizeof(float) * num_ranks);
    assert(all_local_avgs != nullptr);

    MPI_Allgather(&local_avg, 1, MPI_FLOAT,
                  all_local_avgs, 1, MPI_FLOAT, MPI_COMM_WORLD);

    // Compute overall average from the collected partial averages
    float final_avg = calculate_mean(all_local_avgs, num_ranks);

    printf("Average computed by rank %d: %f\n", my_rank, final_avg);

    // Memory cleanup
    if (my_rank == 0) {
        free(global_data);
    }

    free(all_local_avgs);
    free(local_data);

    MPI_Barrier(MPI_COMM_WORLD);
    MPI_Finalize();

    return 0;
}

class Solution {
public:
    int triangularSum(vector<int>& nums) {
        // Create a copy to avoid modifying the input
        vector<int> current = nums;
        int size = current.size();

        // Process until only one element remains
        while (size > 1) {
            // Update elements in-place for next level
            for (int pos = 0; pos < size - 1; ++pos) {
                current[pos] = (current[pos] + current[pos + 1]) % 10;
            }
            --size; // Reduce effective size by 1
        }

        return current[0];
    }
};

