#include <iostream>
#include <vector>
#include <string>
#include <algorithm>
#include <iterator>

int main() {
    // Fast I/O setup for competitive programming
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int m;
    std::cin >> m;

    // Track how many times each passage has been used during left-to-right flips
    std::vector<int> l_to_r_usage(m, 0);

    // Track how many times each passage has been used during right-to-left flips
    std::vector<int> r_to_l_usage(m, 0);

    while (true) {
        std::string current_stone;
        std::cin >> current_stone;

        if (current_stone == "treasure") {
            // Goal reached - exit the loop
            break;
        }

        if (current_stone == "center") {
            // First visit to a new chamber: mark as "left" and use passage 0
            std::cout << "0 left 0\n";
        } 
        else if (current_stone == "left") {
            // Chamber is marked "left"; flip to "right"
            // Find the least-used passage for left->right transitions
            int min_idx = 0;
            for (int i = 1; i < m; ++i) {
                if (l_to_r_usage[i] < l_to_r_usage[min_idx]) {
                    min_idx = i;
                }
            }

            // Output command: keep reference passage 0, flip to "right", use passage min_idx
            std::cout << "0 right " << min_idx << "\n";
            l_to_r_usage[min_idx]++;
        } 
        else if (current_stone == "right") {
            // Chamber is marked "right"; flip to "left"
            // Find the least-used passage for right->left transitions
            int min_idx = 0;
            for (int i = 1; i < m; ++i) {
                if (r_to_l_usage[i] < r_to_l_usage[min_idx]) {
                    min_idx = i;
                }
            }

            // Output command: keep reference passage 0, flip to "left", use passage min_idx
            std::cout << "0 left " << min_idx << "\n";
            r_to_l_usage[min_idx]++;
        }
    }

    return 0;
}

#include "formatted_output.h"

namespace NLastGetopt {
    TFormattedOutput::IndentGuard::IndentGuard(TFormattedOutput* output)
        : Output(output)
    {
        // Increase indentation level by 2 upon guard construction
        Output->IndentLevel_ += 2;
    }

    TFormattedOutput::IndentGuard::~IndentGuard() {
        // Restore previous indentation level when guard goes out of scope
        Output->IndentLevel_ -= 2;
    }

    TFormattedOutput::IndentGuard TFormattedOutput::Indent() {
        // Create and return an IndentGuard to manage indentation scope
        return IndentGuard(this);
    }

    TStringBuilder& TFormattedOutput::Line() {
        // Add a new line with current indentation level and return its builder reference
        return Lines_.emplace_back(IndentLevel_, TStringBuilder()).second;
    }

    void TFormattedOutput::Print(IOutputStream& out) {
        // Iterate through all accumulated lines
        for (const auto& [indent, line] : Lines_) {
            // If there's non-zero indent and the line is not empty, write leading spaces
            if (indent > 0 && !line.empty()) {
                // Allocate temporary buffer for indentation spaces
                TTempBuf spaceBuffer(indent);
                // Fill buffer with ' ' characters
                std::fill_n(spaceBuffer.Data(), indent, ' ');
                // Write the indentation to output stream
                out.Write(spaceBuffer.Data(), indent);
            }
            // Output the actual line content
            out << line;
            // Ensure newline at end unless already present
            if (!line.EndsWith('\n')) {
                out << Endl;
            }
        }
    }
}

