// Input handler: rewritten with clearer branching and bit accumulation logic
void UIScene_DebugOptionsMenu::handleInput(
    int   controllerIndex,
    int   keyCode,
    bool  isRepeated,
    bool  isDown,
    bool  justReleased,
    bool& consumed
) {
    switch (keyCode) {
    case ACTION_MENU_CANCEL:
        if (isDown) {
            unsigned int updatedMask = 0u;
            int bitPosition = 0;

            // Accumulate checked state into bitmask
            for (int idx = 0; idx < m_iTotalCheckboxElements; ++idx) {
                if (m_checkboxes[idx].IsChecked()) {
                    updatedMask |= (1u << bitPosition);
                }
                ++bitPosition;
            }

            unsigned int originalMask = app.GetGameSettingsDebugMask(controllerIndex);
            if (updatedMask != originalMask) {
                app.SetGameSettingsDebugMask(controllerIndex, updatedMask);

                if (app.DebugSettingsOn()) {
                    app.ActionDebugMask(controllerIndex);
                } else {
                    app.ActionDebugMask(controllerIndex, true); // force off
                }

                app.CheckGameSettingsChanged(true, controllerIndex);
            }

            navigateBack();
        }
        break;

    case ACTION_MENU_OK:
    case ACTION_MENU_UP:
    case ACTION_MENU_DOWN:
    case ACTION_MENU_PAGEUP:
    case ACTION_MENU_PAGEDOWN:
        sendInputToMovie(keyCode, isRepeated, isDown, justReleased);
        break;
    }
}

