namespace rslcpp::dynamic_composition
{

std::vector<rclcpp::Node::SharedPtr> ComponentLoader::load_and_create_nodes(
  const std::vector<rslcpp::dynamic_composition::ComponentDescription>& component_list,
  rclcpp::NodeOptions const& base_options)
{
  std::vector<rclcpp::Node::SharedPtr> node_collection;
  for (const auto& desc : component_list) {
    node_collection.push_back(load_single_component(desc, base_options));
  }
  return node_collection;
}

/// @brief Instantiates a single RCLCPP component into a node
/// @param comp_desc Description of the component to instantiate
/// @return Shared pointer to the newly created node
std::shared_ptr<rclcpp::Node> ComponentLoader::load_single_component(
  rslcpp::dynamic_composition::ComponentDescription const& comp_desc,
  rclcpp::NodeOptions const& base_opts)
{
  std::cout << ">> Loading Component | " << comp_desc.component_name << std::endl;

  std::string lib_path = rslcpp::dynamic_composition::utils::get_shared_library_path(comp_desc);

  if (loaders.find(lib_path) == loaders.end()) {
    loaders[lib_path] = std::make_unique<class_loader::ClassLoader>(lib_path);
  }

  std::string factory_class =
    "rclcpp_components::NodeFactoryTemplate<" + comp_desc.component_name + ">";

  auto factory_instance =
    loaders[lib_path]->createInstance<rclcpp_components::NodeFactory>(factory_class);

  // Apply per-component overrides on top of base options
  rclcpp::NodeOptions local_opts = base_opts;
  local_opts.arguments(comp_desc.component_arguments);

  auto wrapper_obj = factory_instance->create_node_instance(local_opts);
  auto node_ptr = std::static_pointer_cast<rclcpp::Node>(wrapper_obj.get_node_instance());

  node_wrappers.emplace_back(wrapper_obj);
  return node_ptr;
}

std::vector<ComponentDescription> parse_components_from_command_line_arguments(
  int& arg_count, char*** arg_vector)
{
  std::vector<ComponentDescription> parsed_components;
  std::size_t idx = 0;

  while (idx < static_cast<std::size_t>(arg_count)) {
    std::string current_arg = arg_vector[idx];

    // Stop parsing when ROS-specific args begin
    if (current_arg == "--ros-args") {
      break;
    }

    if (current_arg == "--component") {
      std::size_t scan_end = idx + 1;
      while (scan_end < static_cast<std::size_t>(arg_count)) {
        std::string next_token = arg_vector[scan_end];
        if (next_token == "--ros-args" || next_token == "--component") {
          break;
        }
        ++scan_end;
      }

      std::size_t sub_arg_count = scan_end - idx - 1;
      if (sub_arg_count < 2) {
        throw std::runtime_error(
          "DynamicComposition | '--component' specified without package and class arguments.");
      }

      std::string pkg_name = arg_vector[idx + 1];
      std::string cls_name = arg_vector[idx + 2];
      std::vector<std::string> extra_args;

      if (sub_arg_count >= 3) {
        if (std::string(arg_vector[idx + 3]) == "--component-ros-args") {
          extra_args.emplace_back("--ros-args");
        } else {
          throw std::runtime_error(
            "DynamicComposition | If you want to add arguments per component, use "
            "'--component-ros-args' after the component name");
        }
      }

      for (std::size_t k = 4; k <= sub_arg_count; ++k) {
        extra_args.emplace_back(arg_vector[idx + k]);
      }

      parsed_components.emplace_back(pkg_name, cls_name, extra_args);
      idx += sub_arg_count + 1;
      continue;
    }

    ++idx;
  }

  // Shift remaining arguments forward in argv
  arg_vector += idx;
  arg_count -= idx;

  if (arg_count <= 0) {
    arg_count = 0;
    arg_vector = nullptr;
  }

  return parsed_components;
}

