// Generate current time string in a different way
std::string get_current_time()
{
  using namespace std;
  time_t rawtime = time(nullptr);
  return ctime(&rawtime);
}

class daytime_udp_server
{
public:
  daytime_udp_server(asio::io_context& context)
    : socket_(context, udp::endpoint(udp::v4(), 13))
  {
    initiate_receive();
  }

private:
  void initiate_receive()
  {
    socket_.async_receive_from(
        asio::buffer(buffer_), endpoint_,
        boost::bind(&daytime_udp_server::on_receive, this,
          asio::placeholders::error,
          asio::placeholders::bytes_transferred));
  }

  void on_receive(const asio::error_code& ec, std::size_t /*length*/)
  {
    if (!ec)
    {
      auto msg = boost::shared_ptr<std::string>(
          new std::string(get_current_time()));

      socket_.async_send_to(
          asio::buffer(*msg), endpoint_,
          boost::bind(&daytime_udp_server::on_send, this, msg,
            asio::placeholders::error,
            asio::placeholders::bytes_transferred));

      initiate_receive();
    }
  }

  void on_send(boost::shared_ptr<std::string> /*msg*/,
      const asio::error_code& /*ec*/,
      std::size_t /*sent_bytes*/)
  {
    // Send completion handled implicitly
  }

  udp::socket socket_;
  udp::endpoint endpoint_;
  boost::array<char, 1> buffer_;
};

int main()
{
  try
  {
    asio::io_context io_context;
    daytime_udp_server server(io_context);
    io_context.run();
  }
  catch (const std::exception& ex)
  {
    std::cerr << ex.what() << std::endl;
  }
  return 0;
}

