// Test LZMA compression/decompression with vector input/output
TEST_CASE("LZMA compress and decompress vector round-trip", "[LZMA]") {
    // Load README.md from project root directory
    std::ifstream inputStream(TESTDIR "/../../README.md", std::ios::binary);
    REQUIRE(inputStream.is_open());

    std::string sourceContent((std::istreambuf_iterator<char>(inputStream)),
                               std::istreambuf_iterator<char>());
    inputStream.close();
    REQUIRE_FALSE(sourceContent.empty());

    // Transform string into byte sequence
    std::vector<Byte> dataVector(sourceContent.begin(), sourceContent.end());

    SECTION("Using uncompressed size hint (default mode)") {
        LZMA compressor(true);  // Enable size header

        // Perform compression
        std::vector<Byte> encodedData;
        compressor.Encode(dataVector, encodedData);
        REQUIRE_FALSE(encodedData.empty());

        // Ensure compressed data differs in size from original
        REQUIRE(encodedData.size() != dataVector.size());

        // Decompress back
        std::vector<Byte> decodedData;
        compressor.Decode(encodedData, decodedData);

        // Validate integrity of round-trip
        REQUIRE(decodedData.size() == dataVector.size());
        std::string reconstructed(decodedData.begin(), decodedData.end());
        REQUIRE(reconstructed == sourceContent);
    }

    SECTION("Without uncompressed size hint") {
        LZMA compressor(false);  // No size header, rely on end marker

        // Compress using alternative configuration
        std::vector<Byte> encodedData;
        compressor.Encode(dataVector, encodedData);
        REQUIRE_FALSE(encodedData.empty());

        // Decompress without size information
        std::vector<Byte> decodedData;
        compressor.Decode(encodedData, decodedData);

        // Confirm correct reconstruction
        REQUIRE(decodedData.size() == dataVector.size());
        std::string reconstructed(decodedData.begin(), decodedData.end());
        REQUIRE(reconstructed == sourceContent);
    }

    SECTION("Verify property sizes for different configurations") {
        LZMA configWithSize(true);
        REQUIRE(configWithSize.PropertySize() == 13); // 5 props + 8 size bytes

        LZMA configWithoutSize(false);
        REQUIRE(configWithoutSize.PropertySize() == 5); // Only properties
    }
}

// Test LZMA compression/decompression with direct string handling
TEST_CASE("LZMA compress and decompress string round-trip", "[LZMA]") {
    std::string testString = "Hello, this is a test string for LZMA compression! "
                             "It needs to be long enough to actually compress. "
                             "LZMA compression works best with repeated patterns. "
                             "Repeated patterns. Repeated patterns. Repeated patterns. "
                             "The quick brown fox jumps over the lazy dog. "
                             "The quick brown fox jumps over the lazy dog. "
                             "The quick brown fox jumps over the lazy dog.";

    LZMA lzmaEncoder;

    // Compress directly from string to byte vector
    std::vector<Byte> compressedBuffer;
    lzmaEncoder.Encode(testString, compressedBuffer);
    REQUIRE_FALSE(compressedBuffer.empty());

    // Decompress back to string
    std::string recoveredString;
    lzmaEncoder.Decode(compressedBuffer, recoveredString);

    REQUIRE(recoveredString == testString);
}

#include "test.h"

TEST_CASE("log::Levels") {
    SECTION("String to level mapping") {
        for (auto level : Lvl{}) {
            auto enumStr = _ts(EnumIndex(level));
            REQUIRE(log::mapLogLevel(enumStr) == level);
        }
    }

    SECTION("Case-insensitive string parsing") {
        for (auto level : Lvl{}) {
            auto upperStr = _ts(EnumIndex(level)).upperCase();
            REQUIRE(log::mapLogLevel(upperStr) == level);
        }
    }

    SECTION("Initial state verification") {
        REQUIRE_FALSE(log::isLevelEnabled(Lvl::Error));
        log::enableLevel("dev,perf");
        REQUIRE_FALSE(log::isLevelEnabled(Lvl::Error));
    }

    SECTION("Single level enable/disable") {
        log::enableLevel(Lvl::Work);
        REQUIRE(log::isLevelEnabled(Lvl::Work));
        log::disableLevel(Lvl::Work);
        REQUIRE_FALSE(log::isLevelEnabled(Lvl::Work));
    }

    SECTION("Sticky level behavior") {
        log::enableLevel<true>(Lvl::Work);
        REQUIRE(log::isLevelEnabled(Lvl::Work));
        log::disableAllLevels();
        REQUIRE(log::isLevelEnabled(Lvl::Work));
        log::disableLevel(Lvl::Work);
        REQUIRE_FALSE(log::isLevelEnabled(Lvl::Work));
    }

    SECTION("Redundant enable operations") {
        log::enableLevel(Lvl::Work, Lvl::Work);
        log::disableLevel(Lvl::File);
        REQUIRE(log::isLevelEnabled(Lvl::Work));
        REQUIRE(log::isLevelEnabled(Lvl::Work, Lvl::Work));
        REQUIRE_FALSE(log::isLevelEnabled(Lvl::Work, Lvl::Work, Lvl::File));

        SECTION("Redundant disable operations") {
            log::disableLevel(Lvl::Work, Lvl::Work, Lvl::File);
            REQUIRE_FALSE(log::isLevelEnabled(Lvl::Work));
            REQUIRE_FALSE(log::isLevelEnabled(Lvl::Work, Lvl::Work));
            REQUIRE_FALSE(log::isLevelEnabled(Lvl::Work, Lvl::Work, Lvl::File));
        }
    }

    SECTION("String-based multiple enable") {
        log::enableLevel("WORK", "WORK");
        log::disableLevel("CONNECTION");
        REQUIRE(log::isLevelEnabled("WORK"));
        REQUIRE(log::isLevelEnabled("WORK", "WORK"));
        REQUIRE_FALSE(log::isLevelEnabled("WORK", "WORK", "CONNECTION"));

        SECTION("String-based multiple disable") {
            log::disableLevel("WORK", "WORK", "CONNECTION");
            REQUIRE_FALSE(log::isLevelEnabled("WORK"));
            REQUIRE_FALSE(log::isLevelEnabled("WORK", "WORK"));
            REQUIRE_FALSE(log::isLevelEnabled("WORK", "WORK", "CONNECTION"));
        }
    }

    SECTION("Whitespace-tolerant string enable") {
        log::enableLevel(" WORK", " WORK ");
        log::disableLevel(" CONNECTION");
        REQUIRE(log::isLevelEnabled("WORK"));
        REQUIRE(log::isLevelEnabled("WORK", "WORK"));
        REQUIRE_FALSE(log::isLevelEnabled("WORK", "WORK", "CONNECTION"));

