class Biome;

// Precomputed spike positions — derived from angular sampling at radius 40
// Original derivation:
// for(int idx=0; idx<8; ++idx) {
//     int dx = 40 * Mth::cos(2*(-PI + (PI/8)*idx));
//     int dz = 40 * Mth::sin(2*(-PI + (PI/8)*idx));
// }
struct EndSpikeData {
    int chunkX;
    int chunkZ;
    int centerX;
    int centerZ;
    int heightTier;
};

static const EndSpikeData SPIKE_CONFIG[8] = {
    // Format: {chunkX, chunkZ, centerX, centerZ, heightTier}
    {32,  -16, 40,  0,   2}, // base spike #0
    {16,  16,  28,  28,  2}, // base spike #1
    {-16, 32,  0,   40,  2}, // base spike #2
    {-32, 16,  -28, 28,  3}, // taller spike #3
    {-48, -16, -40, 0,   3}, // taller spike #4
    {-32, -32, -28, -28, 3}, // taller spike #5
    {-16, -48, 0,   -40, 4}, // tallest spike #6
    {16,  -32, 28,  -28, 4}  // tallest spike #7
};

TheEndBiomeDecorator::TheEndBiomeDecorator(Biome* biome)
: BiomeDecorator(biome) {
    spikeFeature     = new SpikeFeature(Tile::whiteStone_Id);
    endPodiumFeature = new EndPodiumFeature(Tile::whiteStone_Id);
}

void TheEndBiomeDecorator::decorate() {
    decorateOres();

    // Determine top solid block at center of current chunk
    int surfaceY = level->getTopSolidBlock(xo + 8, zo + 8);
    if (surfaceY > level->GetHighestY()) {
        level->SetHighestY(surfaceY);
    }

    // Place spikes only in designated chunks
    int idx = 0;
    while (idx < 8) {
        if ((xo == SPIKE_CONFIG[idx].chunkX) && (zo == SPIKE_CONFIG[idx].chunkZ)) {
            spikeFeature->placeWithIndex(
                level,
                random,
                SPIKE_CONFIG[idx].centerX,
                level->GetHighestY(),
                SPIKE_CONFIG[idx].centerZ,
                idx,
                SPIKE_CONFIG[idx].heightTier
            );
        }
        ++idx;
    }

    // Spawn Ender Dragon only in central chunk (0,0)
    if (xo == 0 && zo == 0) {
        std::shared_ptr<EnderDragon> dragonInstance =
            std::make_shared<EnderDragon>(level);
        float yaw = random->nextFloat() * 360.0f;
        dragonInstance->moveTo(0, 128, 0, yaw, 0.0f);
        level->addEntity(dragonInstance);
    }

    // Place End Podium only when chunk (-16,-16) is processed
    if (xo == -16 && zo == -16) {
        endPodiumFeature->place(level, random, 0, Level::genDepth / 2, 0);
    }
}

