#include "Abilities/Tasks/AbilityTask_NetworkSyncPoint.h"
#include "AbilitySystemComponent.h"

UAbilityTask_NetworkSyncPoint::UAbilityTask_NetworkSyncPoint(const FObjectInitializer& ObjectInitializer)
	: Super(ObjectInitializer)
{
	// Initialize to no event by default
	ListenForEvent = EAbilityGenericReplicatedEvent::MAX;
}

void UAbilityTask_NetworkSyncPoint::OnSignalReceived()
{
	if (ensure(AbilitySystemComponent))
	{
		// Consume the event we were waiting for
		AbilitySystemComponent->ConsumeGenericReplicatedEvent(
			ListenForEvent, 
			GetAbilitySpecHandle(), 
			GetActivationPredictionKey()
		);
	}

	// Signal that synchronization is complete
	CompleteSynchronization();
}

UAbilityTask_NetworkSyncPoint* UAbilityTask_NetworkSyncPoint::WaitNetSync(class UGameplayAbility* OwningAbility, EAbilityTaskNetSyncType InSyncType)
{
	// Create new task instance
	UAbilityTask_NetworkSyncPoint* NewTask = NewAbilityTask<UAbilityTask_NetworkSyncPoint>(OwningAbility);
	NewTask->SyncMode = InSyncType;
	return NewTask;
}

void UAbilityTask_NetworkSyncPoint::Activate()
{
	// Establish prediction window for client-side prediction
	FScopedPredictionWindow PredictionScope(AbilitySystemComponent, IsPredictingClient());

	if (!AbilitySystemComponent)
	{
		return;
	}

	// Determine what event we should listen for and what signals to send
	bool bShouldListenForServerSignal = false;
	bool bShouldSendClientSignal = false;
	bool bShouldListenForClientSignal = false;
	bool bShouldSendServerSignal = false;

	if (IsPredictingClient())
	{
		// Client in prediction mode
		bShouldListenForServerSignal = (SyncMode != EAbilityTaskNetSyncType::OnlyServerWait);
		bShouldSendClientSignal = (SyncMode != EAbilityTaskNetSyncType::OnlyClientWait);
	}
	else if (IsForRemoteClient())
	{
		// Server handling remote client
		bShouldListenForClientSignal = (SyncMode != EAbilityTaskNetSyncType::OnlyClientWait);
		bShouldSendServerSignal = (SyncMode != EAbilityTaskNetSyncType::OnlyServerWait);
	}

	// Set up event listening based on sync requirements
	if (bShouldListenForServerSignal)
	{
		ListenForEvent = EAbilityGenericReplicatedEvent::GenericSignalFromServer;
	}
	else if (bShouldListenForClientSignal)
	{
		ListenForEvent = EAbilityGenericReplicatedEvent::GenericSignalFromClient;
	}
	else
	{
		ListenForEvent = EAbilityGenericReplicatedEvent::MAX;
	}

	// Send appropriate signals if needed
	if (bShouldSendClientSignal)
	{
		AbilitySystemComponent->ServerSetReplicatedEvent(
			EAbilityGenericReplicatedEvent::GenericSignalFromClient,
			GetAbilitySpecHandle(),
			GetActivationPredictionKey(),
			AbilitySystemComponent->ScopedPredictionKey
		);
	}

	if (bShouldSendServerSignal)
	{
		AbilitySystemComponent->ClientSetReplicatedEvent(
			EAbilityGenericReplicatedEvent::GenericSignalFromServer,
			GetAbilitySpecHandle(),
			GetActivationPredictionKey()
		);
	}

	// Register delegate if we're waiting for an event
	if (ListenForEvent != EAbilityGenericReplicatedEvent::MAX)
	{
		RegisterReplicatedDelegate(ListenForEvent, 
			FSimpleMulticastDelegate::FDelegate::CreateUObject(this, &UAbilityTask_NetworkSyncPoint::OnSignalReceived));
	}
	else
	{
		// No event to wait for - synchronization complete immediately
		CompleteSynchronization();
	}
}

void UAbilityTask_NetworkSyncPoint::CompleteSynchronization()
{
	// Only proceed if task is still valid
	if (IsValid(this) && !HasEndTaskBeenCalled())
	{
		// Broadcast completion if delegates should be used
		if (ShouldBroadcastAbilityTaskDelegates())
		{
			OnSync.Broadcast();
		}

		// Clean up and end task
		EndTask();
	}
}

#include "test/jemalloc_test.h"

/*
 * This test verifies that memory allocation functions properly handle
 * requests for sizes exceeding the maximum supported class size.
 * To suppress compiler warnings about oversized allocation requests,
 * we temporarily disable the "-Walloc-size-larger-than" diagnostic.
 */
JEMALLOC_DIAGNOSTIC_PUSH
JEMALLOC_DIAGNOSTIC_IGNORE_ALLOC_SIZE_LARGER_THAN

TEST_BEGIN(test_overflow) {
    unsigned num_large_extents;
    size_t ctl_mib[4];
    size_t item_size, mib_length, max_alloc_size;
    void *ptr;

    // Query number of large extent classes
    item_size = sizeof(unsigned);
    expect_d_eq(mallctl("arenas.nlextents", (void *)&num_large_extents,
                        &item_size, NULL, 0), 0,
                "Unexpected mallctl() failure");

    // Prepare MIB for querying largest extent size
    mib_length = sizeof(ctl_mib) / sizeof(size_t);
    expect_d_eq(mallctlnametomib("arenas.lextent.0.size", ctl_mib, &mib_length),
                0, "Failed to convert name to MIB");

    // Set index to last (largest) extent class
    ctl_mib[2] = num_large_extents - 1;
    item_size = sizeof(size_t);

    // Retrieve maximum allocatable size class
    expect_d_eq(mallctlbymib(ctl_mib, mib_length, (void *)&max_alloc_size,
                             &item_size, NULL, 0), 0,
                "Failed to get lextent size");

    // Test malloc with oversized arguments
    expect_ptr_null(malloc(max_alloc_size + 1),
                    "malloc should fail for oversized request");
    expect_ptr_null(malloc(SIZE_T_MAX),
                    "malloc should fail for SIZE_T_MAX");

    // Test calloc with oversized arguments
    expect_ptr_null(calloc(1, max_alloc_size + 1),
                    "calloc should fail for oversized request");
    expect_ptr_null(calloc(1, SIZE_T_MAX),
                    "calloc should fail for SIZE_T_MAX");

    // Allocate a small block and attempt to resize it beyond limits
    ptr = malloc(1);
    expect_ptr_not_null(ptr, "Initial small allocation should succeed");

    expect_ptr_null(realloc(ptr, max_alloc_size + 1),
                    "realloc should fail when growing beyond max size");
    expect_ptr_null(realloc(ptr, SIZE_T_MAX),
                    "realloc should fail when resizing to SIZE_T_MAX");

    free(ptr);
}
TEST_END

// Restore diagnostic settings after test
JEMALLOC_DIAGNOSTIC_POP

int main(void) {
    return test(test_overflow);
}

