void MessageBus::store(Message* msg) {
    // Insert or update the message at its associated address
    uint64_t addr = msg->get_address();
    messages[addr] = msg;
}

Message* MessageBus::fetch(uint64_t addr) {
    // Search for a message by its address
    auto iter = messages.find(addr);
    if (iter != messages.end()) {
        return iter->second;
    }
    return nullptr; // Indicate no message exists at this address
}

