// Read URDF file and parse it repeatedly in a loop
int main(int argc, char** argv) {
    if (argc != 2) {
        std::cerr << "Usage: " << argv[0] << " <urdf_file>" << std::endl;
        return 1;
    }

    while (true) {
        std::string content;
        std::ifstream input_file(argv[1]);

        if (!input_file.is_open()) {
            std::cerr << "Error: Could not open file " << argv[1] << std::endl;
            return 1;
        }

        std::string line;
        while (std::getline(input_file, line)) {
            content += line + "\n";
        }
        input_file.close();

        urdf::parseURDF(content);
    }

    return 0;
}

#include <iostream>
using namespace std;

// Definition for singly-linked list.
struct ListNode {
    int val;
    ListNode *next;
    ListNode() : val(0), next(nullptr) {}
    ListNode(int x) : val(x), next(nullptr) {}
    ListNode(int x, ListNode *next) : val(x), next(next) {}
};

class Solution {
public:
    ListNode* swapPairs(ListNode* head) {
        // Handle edge cases: empty list or single node
        if (!head || !head->next) {
            return head;
        }

        // Create a dummy node to simplify handling the head
        ListNode* sentinel = new ListNode(0);
        sentinel->next = head;

        // Use current pointer to track position before each pair
        ListNode* current = sentinel;

        while (current->next && current->next->next) {
            // Identify the two nodes to swap
            ListNode* first = current->next;
            ListNode* second = current->next->next;

            // Perform the swap
            current->next = second;
            first->next = second->next;
            second->next = first;

            // Advance to the next pair
            current = first;
        }

        // Return the new head (after dummy node)
        return sentinel->next;
    }
};

