void UMoviePipelineConfigBase::RemoveSetting(UMoviePipelineSetting* InSetting)
{
	// Remove the specified setting from the internal list
	Settings.Remove(InSetting);

	// Notify listeners that a setting has been removed
	OnSettingRemoved(InSetting);

	// Increment serial number to signal UI updates are needed
	SettingsSerialNumber += 1;
}

void UMoviePipelineConfigBase::CopyFrom(UMoviePipelineConfigBase* InConfig)
{
#if WITH_EDITOR
	// Mark this object as modified for editor undo/redo support
	Modify();
#endif

	// Transfer display name from source config (e.g., preset asset name)
	DisplayName = InConfig->DisplayName;

	// Clear existing settings before populating with duplicates
	Settings.Reset();

	// Iterate through each setting in the source configuration
	for (UMoviePipelineSetting* OriginalSetting : InConfig->Settings)
	{
		// Create a deep copy of the setting within this object's context
		UMoviePipelineSetting* NewSetting = Cast<UMoviePipelineSetting>(
			StaticDuplicateObject(OriginalSetting, this, OriginalSetting->GetFName())
		);

		// Ensure copied setting is in a valid state
		NewSetting->ValidateState();

		// Add the new setting to our collection
		Settings.Add(NewSetting);

		// Notify listeners about the newly added setting
		OnSettingAdded(NewSetting);
	}

	// Bump serial number explicitly since we've modified Settings directly
	SettingsSerialNumber += 1;
}

