#include "LogSetup.h"

using namespace db;

StopCmd::StopCmd()
    : _argParser("stop")
{
}

StopCmd::~StopCmd() = default;

int StopCmd::execute() {
    LogSetup::setupLogConsole(); // Initialize console logging only, as log file is managed externally

    TuringConfig config;

    // Override config directory if explicitly provided
    if (!_turingDir.empty()) {
        config.setTuringDirectory(fs::Path {_turingDir});
    }

    // Ensure _turingDir reflects current config
    _turingDir = config.getTuringDir().get();

    const fs::Path socketPath = config.getSocketPath();

    // Verify server socket exists before attempting to stop
    if (!socketPath.exists()) {
        spdlog::error("No TuringDB instance appears active in {}", _turingDir);
        return EXIT_FAILURE;
    }

    // Send stop signal via Unix domain socket
    if (!SystemEventHandler::requestStop(socketPath)) {
        spdlog::error("Failed to send shutdown command to TuringDB at {}", _turingDir);
        return EXIT_FAILURE;
    }

    // Monitor lock file release to confirm graceful shutdown
    LockFile lockFile;
    lockFile.setPath(config.getLockFilePath());

    if (!lockFile.waitUnlock(_timeout)) {
        spdlog::error("TuringDB process at {} did not terminate within {} ms", _turingDir, _timeout);
        return EXIT_FAILURE;
    }

    spdlog::info("Successfully stopped TuringDB instance at {}", _turingDir);
    return EXIT_SUCCESS;
}

std::unique_ptr<StopCmd> StopCmd::create() {
    auto cmd = std::make_unique<StopCmd>();
    cmd->initialize();
    return cmd;
}

void StopCmd::initialize() {
    _argParser.add_description("Terminates the running TuringDB server process");
    _argParser.add_argument("-turing-dir")
        .metavar("path")
        .help("Base directory for TuringDB installation")
        .store_into(_turingDir);
    _argParser.add_argument("-timeout", "-t")
        .metavar("milliseconds")
        .help("Maximum wait time (in milliseconds) for lock release (default: 3000)")
        .store_into(_timeout);
}

#include <array>
#include <iostream>
#include <string>
#include "asio.hpp"

constexpr unsigned short udp_multicast_port = 30001;

class multicast_listener
{
public:
  multicast_listener(asio::io_context& context,
      const asio::ip::address& bind_addr,
      const asio::ip::address& group_addr)
    : socket_(context)
  {
    // Configure the UDP socket for multicast reception
    asio::ip::udp::endpoint endpoint(bind_addr, udp_multicast_port);
    socket_.open(endpoint.protocol());
    socket_.set_option(asio::ip::udp::socket::reuse_address(true));
    socket_.bind(endpoint);

    // Subscribe to the multicast group
    socket_.set_option(asio::ip::multicast::join_group(group_addr));

    start_receiving();
  }

private:
  void start_receiving()
  {
    socket_.async_receive_from(
        asio::buffer(buffer_), remote_,
        [this](const std::error_code& error, std::size_t bytes_transferred)
        {
          if (!error)
          {
            std::cout.write(buffer_.data(), bytes_transferred);
            std::cout << std::endl;
            start_receiving();
          }
        });
  }

  asio::ip::udp::socket socket_;
  asio::ip::udp::endpoint remote_;
  std::array<char, 2048> buffer_;
};

int main(int argc, char* argv[])
{
  try
  {
    if (argc != 3)
    {
      std::cerr << "Usage: receiver <listen_address> <multicast_address>\n";
      std::cerr << "  For IPv4, try:\n";
      std::cerr << "    receiver 0.0.0.0 239.255.0.1\n";
      std::cerr << "  For IPv6, try:\n";
      std::cerr << "    receiver ::  ff31::8000:1234\n";
      return 1;
    }

    asio::io_context io_ctx;
    multicast_listener listener(io_ctx,
        asio::ip::make_address(argv[1]),
        asio::ip::make_address(argv[2]));

    io_ctx.run();
  }
  catch (const std::exception& ex)
  {
    std::cerr << "Error: " << ex.what() << "\n";
    return 1;
  }

  return 0;
}

