#define DEBUG_TYPE "double barriers"
STATISTIC(RemovedDMBCount, "Number of redundant DMBs eliminated");

namespace {

class ARMRedundantBarrierEliminator : public MachineFunctionPass {
public:
  static char ID;
  ARMRedundantBarrierEliminator() : MachineFunctionPass(ID) {}

  bool runOnMachineFunction(MachineFunction &Func) override;

  MachineFunctionProperties getRequiredProperties() const override {
    return MachineFunctionProperties().set(
        MachineFunctionProperties::Property::NoVRegs);
  }

  StringRef getPassName() const override {
    return "eliminate redundant memory barriers";
  }
};

char ARMRedundantBarrierEliminator::ID = 0;

} // anonymous namespace

// Determines whether an instruction may be reordered across a DMB.
// Returns true if MI is *safe* to move past a DMB — i.e., it does not involve memory access or side effects.
static bool IsSafeToMoveAcrossDMB(const MachineInstr *Instr) {
  return !(Instr->mayLoad() ||
           Instr->mayStore() ||
           Instr->hasUnmodeledSideEffects() ||
           Instr->isCall() ||
           Instr->isReturn());
}

bool ARMRedundantBarrierEliminator::runOnMachineFunction(MachineFunction &Func) {
  if (skipFunction(Func.getFunction()))
    return false;

  std::vector<MachineInstr *> MarkedForRemoval;
  int64_t LastDMBKind = -1; // Stores the barrier type (e.g., ish, osh, sy)
  bool ExpectNextDMBToRemove = false;

  for (auto &MBB : Func) {
    for (auto &Instr : MBB) {
      if (Instr.getOpcode() == ARM::DMB) {
        const int64_t CurrentDMBKind = Instr.getOperand(0).getImm();

        if (ExpectNextDMBToRemove) {
          if (CurrentDMBKind == LastDMBKind) {
            // Same barrier kind → this DMB is redundant
            MarkedForRemoval.push_back(&Instr);
          } else {
            // Different barrier kind → update tracking but do not remove
            LastDMBKind = CurrentDMBKind;
            ExpectNextDMBToRemove = true;
          }
        } else {
          // First DMB encountered in this block: prepare to look for next one
          ExpectNextDMBToRemove = true;
          LastDMBKind = CurrentDMBKind;
        }
      } else if (!IsSafeToMoveAcrossDMB(&Instr)) {
        // Non-reorderable instruction resets the expectation
        ExpectNextDMBToRemove = false;
      }
    }
  }

  bool Modified = false;
  for (auto *Instr : MarkedForRemoval) {
    Instr->eraseFromParent();
    ++RemovedDMBCount;
    Modified = true;
  }

  return Modified;
}

/// createARMRedundantBarrierEliminatorPass — returns a new instance of the pass.
FunctionPass *llvm::createARMRedundantBarrierEliminatorPass() {
  return new ARMRedundantBarrierEliminator();
}

