using asio::ip::udp;
using std::placeholders::_1;
using std::placeholders::_2;

// A UDP client that receives data with a timeout mechanism
class udp_receiver
{
public:
  udp_receiver(const udp::endpoint& local_endpoint)
    : socket_(io_context_, local_endpoint)
  {
  }

  // Receive data into buffer with specified timeout, returns bytes received
  std::size_t recv_with_timeout(const asio::mutable_buffer& buffer,
      std::chrono::steady_clock::duration max_wait,
      std::error_code& ec)
  {
    std::size_t bytes_read = 0;

    // Initiate async receive operation
    socket_.async_receive(asio::buffer(buffer),
        [this, &ec, &bytes_read](const std::error_code& error, size_t length) {
          handle_recv(error, length, &ec, &bytes_read);
        });

    // Execute with timeout constraint
    execute_with_deadline(max_wait);

    return bytes_read;
  }

private:
  void execute_with_deadline(std::chrono::steady_clock::duration limit)
  {
    // Reset io_context for reuse
    io_context_.restart();

    // Run until completion or timeout
    io_context_.run_for(limit);

    // If not stopped, the deadline expired before completion
    if (!io_context_.stopped())
    {
      // Cancel pending operations
      socket_.cancel();

      // Wait for cancellation to take effect
      io_context_.run();
    }
  }

  static void handle_recv(const std::error_code& err,
      std::size_t bytes_transferred,
      std::error_code* target_ec,
      std::size_t* target_bytes)
  {
    *target_ec = err;
    *target_bytes = bytes_transferred;
  }

private:
  asio::io_context io_context_;
  udp::socket socket_;
};

int main(int argc, char* argv[])
{
  try
  {
    using namespace std; // For atoi

    if (argc != 3)
    {
      cerr << "Usage: udp_client <address> <port>\n";
      return 1;
    }

    // Parse command line arguments
    udp::endpoint listen_addr(
        asio::ip::make_address(argv[1]),
        static_cast<unsigned short>(atoi(argv[2])));

    udp_receiver receiver(listen_addr);

    // Continuous reception loop
    while (true)
    {
      char buffer[1024];
      std::error_code err;

      size_t received = receiver.recv_with_timeout(
          asio::buffer(buffer),
          std::chrono::seconds(10),
          err);

      if (err)
      {
        cout << "Error during receive: " << err.message() << "\n";
      }
      else
      {
        cout << "Received: ";
        cout.write(buffer, received);
        cout << "\n";
      }
    }
  }
  catch (const exception& ex)
  {
    cerr << "Fatal error: " << ex.what() << "\n";
    return 1;
  }

  return 0;
}

