// Define an enumeration for primary colors with flag semantics
enum class PrimaryColor { RED = 1, GREEN = 2, BLUE = 4 };

// Specialize magic_enum to treat PrimaryColor as a flags type
template <>
struct magic_enum::customize::enum_range<PrimaryColor> {
  static constexpr bool is_flags = true;
};

int main() {
    std::cout << std::boolalpha;

    // Create a set-like container using magic_enum's set implementation
    magic_enum::containers::set color_container{PrimaryColor::RED, PrimaryColor::GREEN, PrimaryColor::BLUE};

    // Check initial state
    std::cout << color_container.empty() << std::endl; // false
    std::cout << color_container.size() << std::endl;  // 3

    // Clear all elements
    color_container.clear();
    std::cout << color_container.empty() << std::endl; // true
    std::cout << color_container.size() << std::endl;  // 0

    // Insert some elements again
    color_container.insert(PrimaryColor::GREEN);
    color_container.insert(PrimaryColor::BLUE);
    std::cout << color_container.empty() << std::endl; // false
    std::cout << color_container.size() << std::endl;  // 2

    return 0;
}

