#include <sol/sol.hpp>

// Alternative implementation: Using sol::state_view and sol::stack::get
// to retrieve 'this' in constructor and member function
int main() {
    struct Example {
        Example(sol::this_state ts) {
            auto L = ts.lua_state();
            // Retrieve the first argument from Lua stack as 'Example&'
            Example& instance = sol::stack::get<Example&>(L, 1);
            SOL_ASSERT(&instance == this);
        }

        void execute(sol::this_state ts) const {
            auto L = ts.lua_state();
            // Use sol::stack::get for type-safe retrieval
            const Example& instance = sol::stack::get<const Example&>(L, 1);
            SOL_ASSERT(&instance == this);
        }
    };

    sol::state lua;
    lua.open_libraries(sol::lib::base);

    // Register usertype with constructor and method
    lua.new_usertype<Example>(
        "Example",
        sol::constructors<Example(sol::this_state)>(),
        "run", &Example::execute);

    // Execute Lua script to test both constructor and method
    lua.script(R"(
local obj = Example.new()
obj:run()
)");

    return 0;
}

