using json = nlohmann::json;
using namespace nlohmann::literals;

// Helper function to display UBJSON bytes in human-readable form
void show_ubjson_byte(std::uint8_t b)
{
    if (b > 32 && b < 127)
    {
        std::cout << static_cast<char>(b);
    }
    else
    {
        std::cout << static_cast<int>(b);
    }
}

int main()
{
    // Build a JSON object from raw string literal
    json obj = R"({"compact": true, "schema": false})"_json;

    // Convert to UBJSON format
    std::vector<std::uint8_t> ubjson_bytes = json::to_ubjson(obj);

    // Output the raw byte sequence
    for (std::uint8_t byte : ubjson_bytes)
    {
        show_ubjson_byte(byte);
    }
    std::cout << '\n';

    // Create a numeric array
    json numbers = {1, 2, 3, 4, 5, 6, 7, 8};

    // Generate three variants of UBJSON encoding:
    // 1. Standard encoding
    std::vector<std::uint8_t> standard_encoding = json::to_ubjson(numbers);

    // 2. Size-optimized encoding
    std::vector<std::uint8_t> size_optimized = json::to_ubjson(numbers, true);

    // 3. Size + type optimized encoding
    std::vector<std::uint8_t> full_optimized = json::to_ubjson(numbers, true, true);

    // Print each encoding on separate lines
    for (std::uint8_t b : standard_encoding)
    {
        show_ubjson_byte(b);
    }
    std::cout << '\n';

    for (std::uint8_t b : size_optimized)
    {
        show_ubjson_byte(b);
    }
    std::cout << '\n';

    for (std::uint8_t b : full_optimized)
    {
        show_ubjson_byte(b);
    }
    std::cout << '\n';

    return 0;
}

