              << obj.contains("/array/1"_json_pointer) << '\n'
              << obj.contains("/array/-"_json_pointer) << '\n'
              << obj.contains("/array/4"_json_pointer) << '\n'
              << obj.contains("/baz"_json_pointer) << std::endl;

    // Handle invalid array index (leading zero)
    try {
        obj.contains("/array/01"_json_pointer);
    } catch (const json::parse_error& ex) {
        std::cout << ex.what() << '\n';
    }

    // Handle non-numeric array index
    try {
        obj.contains("/array/one"_json_pointer);
    } catch (const json::parse_error& ex) {
        std::cout << ex.what() << '\n';
    }

    return 0;
}

#include "ptn/patternia.hpp"
#include "parse_json_pred.hpp"
#include "parse_json_handler.hpp"

using namespace ptn;

void traverse_json(const json &j, int level = 0) {
    match(j)
        .if_match(
            bind()[is_type(json::value_t::null)],
            [&](const json &) {
                indent(level);
                std::cout << "null\n";
            }
        )
        .if_match(
            bind()[is_type(json::value_t::boolean)],
            [&](const json &val) {
                print_bool(level)(val);
            }
        )
        .if_match(
            bind()[is_type(json::value_t::number_integer)],
            [&](const json &val) {
                print_number<int>("int", level)(val);
            }
        )
        .if_match(
            bind()[is_type(json::value_t::number_unsigned)],
            [&](const json &val) {
                print_number<unsigned>("uint", level)(val);
            }
        )
        .if_match(
            bind()[is_type(json::value_t::number_float)],
            [&](const json &val) {
                print_number<double>("float", level)(val);
            }
        )
        .if_match(
            bind()[is_type(json::value_t::string)],
            [&](const json &val) {
                print_string(level)(val);
            }
        )
        .if_match(
            bind()[is_empty_array],
            [&](const json &) {
                indent(level);
                std::cout << "array []\n";
            }
        )
        .if_match(
            bind()[is_type(json::value_t::array)],
            [&](const json &arr) {
                indent(level);
                std::cout << "array (" << arr.size() << ")\n";
                for (const auto &item : arr) {
                    traverse_json(item, level + 1);
                }
            }
        )
        .if_match(
            bind()[has_field("name")],
            [&](const json &obj) {
                indent(level);
                std::cout << "object <named>\n";
                for (const auto &[key, value] : obj.items()) {
                    indent(level + 1);
                    std::cout << key << ":\n";
                    traverse_json(value, level + 2);
                }
            }
        )
        .else_match([&]() {
            indent(level);
            std::cout << "<unknown>\n";
        });
}

