class Solution {
public:
    void nextPermutation(vector<int>& nums) {
        int n = nums.size();
        int pivot = -1;

        // Step 1: Locate the rightmost index where nums[i] < nums[i+1]
        for (int j = n - 2; j >= 0; --j) {
            if (nums[j] < nums[j + 1]) {
                pivot = j;
                break;
            }
        }

        // If no pivot found, array is in descending order - reverse to get smallest permutation
        if (pivot == -1) {
            reverse(nums.begin(), nums.end());
        } else {
            // Step 2: Find the rightmost element greater than nums[pivot] in the suffix
            int successor = n - 1;
            while (successor > pivot && nums[successor] <= nums[pivot]) {
                --successor;
            }

            // Swap pivot with successor
            swap(nums[pivot], nums[successor]);

            // Step 3: Reverse the suffix to get the next lexicographically smallest arrangement
            reverse(nums.begin() + pivot + 1, nums.end());
        }
    }
};

