#include <vector>
#include <algorithm>

class Solution {
public:
    int numRescueBoats(std::vector<int>& people, int limit) {
        // Sort people by weight in ascending order
        std::sort(people.begin(), people.end());

        int totalBoats = 0;
        int lightIndex = 0;           // Pointer to lightest remaining person
        int heavyIndex = people.size() - 1;  // Pointer to heaviest remaining person

        // Process people from both ends
        while (lightIndex <= heavyIndex) {
            // Always take the heaviest person on current boat
            totalBoats++;

            // Try to pair with lightest remaining person if possible
            if (people[heavyIndex] + people[lightIndex] <= limit) {
                lightIndex++;  // Light person boards too
            }

            // Heaviest person always boards, so move to next heaviest
            heavyIndex--;
        }

        return totalBoats;
    }
};

