#include <mplot/unicode.h>

namespace uc = mplot::unicode;

int main() {
    // Initialize the main visualization window
    mplot::Visual scene(1024, 768, "Right-axis only GraphVisual example");

    // Construct a GraphVisual instance for double-precision data
    auto graphModel = std::unique_ptr<mplot::GraphVisual<double>>(
        new mplot::GraphVisual<double>(sm::vec<float, 3>{0.0f, 0.0f, 0.0f})
    );

    scene.bindmodel(graphModel);

    // Configure axis style to twinaxial (left + right y-axes)
    graphModel->axisstyle = mplot::axisstyle::twinax;

    // Prepare x-values manually using a loop instead of linspace()
    sm::vvec<double> xValues;
    const double startX = -0.5;
    const double endX   =  0.8;
    const int    count  = 14;
    const double step   = (endX - startX) / (count - 1);
    for (int i = 0; i < count; ++i) {
        xValues.push_back(startX + i * step);
    }

    // Define dataset label: α(x) = x³
    std::string dataLabel = uc::toUtf8(uc::alpha) + "(x) = x" + uc::toUtf8(uc::ss3);

    // Bind data to the right-hand side y-axis
    graphModel->setdata(xValues, xValues.pow(3), dataLabel, mplot::axisside::right);

    // Customize axis labels
    graphModel->ylabel  = "";               // Disable left ylabel
    graphModel->ylabel2 = uc::toUtf8(uc::alpha);  // Set right ylabel to Greek alpha

    // Finalize model geometry computation
    graphModel->finalize();

    // Add the finalized model to the visual scene
    scene.addVisualModel(graphModel);

    // Keep window open until user exits (Ctrl-q)
    scene.keepOpen();

    // graphModel is automatically deallocated when scene goes out of scope
    return 0;
}

