// Type aliases for function pointers used in startup chain
typedef int (*main_entry_fn)(int, char**, char**);
typedef void (*init_routine_fn)(void);
typedef int (*libc_start_main_fn)(int (*)(int, char**, char**), int, char**, void (*)(void),
                                  void (*)(void), void (*)(void), void*);

// Forward declarations of our instrumentation hooks
int rocprofsys_libc_start_main(int (*)(int, char**, char**), int, char**, void (*)(void),
                               void (*)(void), void (*)(void), void*) ROCPROFSYS_INTERNAL_API;

int __libc_start_main(int (*)(int, char**, char**), int, char**, void (*)(void),
                      void (*)(void), void (*)(void), void*) ROCPROFSYS_PUBLIC_API;

// External tooling functions
extern int rocprofsys_preload_library(void);
extern void rocprofsys_finalize(void);
extern void rocprofsys_push_trace(const char*);
extern void rocprofsys_pop_trace(const char*);
extern void rocprofsys_init_tooling(void);
extern void rocprofsys_init(const char*, bool, const char*);
extern char* basename(const char*);

// Internal state setters
extern void rocprofsys_set_main(main_entry_fn) ROCPROFSYS_INTERNAL_API;
extern void rocprofsys_set_main_init(init_routine_fn) ROCPROFSYS_INTERNAL_API;
extern void rocprofsys_main_init(void) ROCPROFSYS_INTERNAL_API;
extern int rocprofsys_main(int, char**, char**) ROCPROFSYS_INTERNAL_API;

// Implementation of intercepted libc_start_main
int
rocprofsys_libc_start_main(int (*entry_point)(int, char**, char**),
                           int arg_count,
                           char** arg_vector,
                           void (*init_fn)(void),
                           void (*fini_fn)(void),
                           void (*rtld_fini_fn)(void),
                           void* stack_end)
{
    // Preload check
    int preload_status = rocprofsys_preload_library();

    // Prevent recursive interception
    static int entered = 0;
    if (entered) {
        return -1;
    }
    entered = 1;

    // Capture current address to avoid self-recursion
    void* this_hook_addr = __builtin_return_address(0);

    // Register original main and init handlers
    rocprofsys_set_main(entry_point);
    rocprofsys_set_main_init(init_fn);

    // Resolve real __libc_start_main from next link in chain
    libc_start_main_fn real_start_main = (libc_start_main_fn)dlsym(RTLD_NEXT, "__libc_start_main");

    // Disable further preloading to avoid loops
    setenv("ROCPROFSYS_PRELOAD", "0", 1);

    // Proceed only if we found the real symbol and it's not us
    if (!real_start_main || real_start_main == this_hook_addr) {
        fprintf(stderr, "Error! rocprof-sys could not find __libc_start_main!\n");
        return -1;
    }

    // If preload succeeded, wrap main; otherwise call directly
    if (preload_status == 0) {
        return real_start_main(entry_point, arg_count, arg_vector,
                               init_fn, fini_fn, rtld_fini_fn, stack_end);
    } else {
        return real_start_main(rocprofsys_main, arg_count, arg_vector,
                               init_fn, fini_fn, rtld_fini_fn, stack_end);
    }
}

// Public entry point aliasing internal implementation
int
__libc_start_main(int (*entry_point)(int, char**, char**),
                  int arg_count,
                  char** arg_vector,
                  void (*init_fn)(void),
                  void (*fini_fn)(void),
                  void (*rtld_fini_fn)(void),
                  void* stack_end)
{
    return rocprofsys_libc_start_main(entry_point, arg_count, arg_vector,
                                      init_fn, fini_fn, rtld_fini_fn, stack_end);
}

