namespace FFBEngineTests {

TEST_CASE(test_executable_metadata, "Security") {
    std::cout << "\nTest: Executable Metadata & Version Info (Security)" << std::endl;

    char exePath[MAX_PATH]{};
    DWORD pathLen = GetModuleFileNameA(NULL, exePath, MAX_PATH);
    if (pathLen == 0 || pathLen >= MAX_PATH) {
        std::cerr << "[FAIL] Failed to retrieve executable path: error code " << GetLastError() << std::endl;
        ++g_tests_failed;
        return;
    }

    std::cout << "  Analyzing: " << exePath << std::endl;

    // Retrieve version info size
    DWORD dummyHandle = 0;
    DWORD versionSize = GetFileVersionInfoSizeA(exePath, &dummyHandle);
    if (versionSize == 0) {
        std::cerr << "[FAIL] No version resources found — ensure BUILD_HEADLESS=OFF" << std::endl;
        ++g_tests_failed;
        return;
    }

    // Load version info into buffer
    std::vector<BYTE> versionBuffer(versionSize);
    if (!GetFileVersionInfoA(exePath, dummyHandle, versionSize, versionBuffer.data())) {
        std::cerr << "[FAIL] Could not load version info: error " << GetLastError() << std::endl;
        ++g_tests_failed;
        return;
    }

    // Extract language & codepage mapping
    struct LangCP {
        WORD langId;
        WORD codePage;
    };
    LangCP* langTable = nullptr;
    UINT tableSize = 0;

    if (!VerQueryValueA(versionBuffer.data(), "\\VarFileInfo\\Translation", reinterpret_cast<LPVOID*>(&langTable), &tableSize)) {
        std::cerr << "[FAIL] Unable to read translation info" << std::endl;
        ++g_tests_failed;
        return;
    }

    // Construct sub-block paths using first available locale
    char subBlock[64];
    sprintf_s(subBlock, "\\StringFileInfo\\%04x%04x\\CompanyName", langTable[0].langId, langTable[0].codePage);

    char* companyNamePtr = nullptr;
    UINT nameLen = 0;
    if (VerQueryValueA(versionBuffer.data(), subBlock, reinterpret_cast<LPVOID*>(&companyNamePtr), &nameLen)) {
        std::string companyName(companyNamePtr);
        std::cout << "  CompanyName: " << companyName << std::endl;
        CHECK_PASS(companyName == "lmuFFB");
    } else {
        std::cerr << "[FAIL] Could not extract CompanyName" << std::endl;
        ++g_tests_failed;
    }

    // Check ProductVersion
    sprintf_s(subBlock, "\\StringFileInfo\\%04x%04x\\ProductVersion", langTable[0].langId, langTable[0].codePage);
    char* productVersionPtr = nullptr;
    if (VerQueryValueA(versionBuffer.data(), subBlock, reinterpret_cast<LPVOID*>(&productVersionPtr), &nameLen)) {
        std::string productVersion(productVersionPtr);
        std::cout << "  ProductVersion: " << productVersion << std::endl;

        bool startsWithExpected = (productVersion.find(LMUFFB_VERSION) == 0);
        if (!startsWithExpected) {
            std::cerr << "  [WARN] Expected prefix '" << LMUFFB_VERSION << "', got '" << productVersion << "'" << std::endl;
        }
        CHECK_PASS(startsWithExpected);
    } else {
        std::cerr << "[FAIL] Could not extract ProductVersion" << std::endl;
        ++g_tests_failed;
    }
}

