namespace yams::cli {

class AuthCommand : public ICommand {
public:
    std::string getName() const override { return "auth"; }
    std::string getDescription() const override { return "Manage authentication keys and tokens"; }

    void registerCommand(CLI::App& app, YamsCLI* cli) override {
        cli_ = cli;
        auto* authGroup = app.add_subcommand("auth", getDescription());
        authGroup->require_subcommand();

        // Key generation subcommand
        auto* keyGenSub = authGroup->add_subcommand("keygen", "Generate authentication keys");
        std::string selectedKeyType = "ed25519";
        keyGenSub->add_option("--type", selectedKeyType, "Key type (ed25519, rsa)")
            ->default_val(selectedKeyType)
            ->check([](const std::string& val) -> std::string {
                if (val != "ed25519" && val != "rsa") {
                    return "Invalid key type. Must be 'ed25519' or 'rsa'.";
                }
                return "";
            });

        std::string keyOutputDir = (yams::config::get_config_dir() / "keys").string();
        keyGenSub->add_option("--output", keyOutputDir, "Output directory for keys")
            ->default_val(keyOutputDir);

        bool overwriteExisting = false;
        keyGenSub->add_flag("--force", overwriteExisting, "Overwrite existing keys");

        keyGenSub->callback([this, selectedKeyType, keyOutputDir, overwriteExisting]() {
            spdlog::info("Auth keygen command - Coming in Phase 2");
            spdlog::info("This will generate {} keys in: {}", selectedKeyType, keyOutputDir);

            std::cout << "Status: Phase 2 - Not yet implemented\n";
            std::cout << "Expected usage: yams auth keygen [--type ed25519|rsa] [--output path]\n";
            std::cout << "\nNote: The 'init' command already generates Ed25519 keys.\n";
            std::cout << "This command will provide additional key management capabilities.\n";
            std::exit(0);
        });

        // List keys subcommand
        auto* listKeysSub = authGroup->add_subcommand("list-keys", "List authentication keys");
        bool detailedView = false;
        listKeysSub->add_flag("-v,--verbose", detailedView, "Show detailed key information");

        std::string outputFormat = "table";
        listKeysSub->add_option("--format", outputFormat, "Output format (table, json)")
            ->default_val(outputFormat)
            ->check(CLI::IsMember({"table", "json"}));

        listKeysSub->callback([detailedView, outputFormat]() {
            spdlog::info("Auth list-keys command - Coming in Phase 2");
            std::cout << "Status: Phase 2 - Not yet implemented\n";
            std::cout << "Expected usage: yams auth list-keys [--verbose] [--format table|json]\n";
            std::cout << "\nThis will list:\n";
            std::cout << "  - Ed25519 keys\n";
            std::cout << "  - RSA keys\n";
            std::cout << "  - API keys\n";
            std::cout << "  - Key fingerprints and creation dates\n";
            std::exit(0);
        });

        // Revoke subcommand
        auto* revokeSub = authGroup->add_subcommand("revoke", "Revoke an authentication key");
        std::string targetKeyId;
        revokeSub->add_option("key-id", targetKeyId, "Key ID or fingerprint to revoke")->required();

        bool skipConfirm = false;
        revokeSub->add_flag("--force", skipConfirm, "Skip confirmation prompt");

        revokeSub->callback([this, targetKeyId, skipConfirm]() {
            spdlog::info("Auth revoke command - Coming in Phase 2");
            spdlog::info("This will revoke key: {}", targetKeyId);
            std::cout << "Status: Phase 2 - Not yet implemented\n";
            std::cout << "Expected usage: yams auth revoke <key-id> [--force]\n";
            std::cout << "\nThis will:\n";
            std::cout << "  - Mark the key as revoked\n";
            std::cout << "  - Invalidate associated tokens\n";
            std::cout << "  - Update revocation list\n";
            std::exit(0);
        });

        // Token generation subcommand (JWT)
        auto* tokenSub = authGroup->add_subcommand("token", "Generate JWT token");
        std::string signingKeyPath = (yams::config::get_config_dir() / "keys" / "ed25519.pem").string();
        tokenSub->add_option("--key", signingKeyPath, "Private key path for signing")
            ->default_val(signingKeyPath);

        std::string tokenDuration = "24h";
        tokenSub->add_option("--validity", tokenDuration, "Token validity duration (e.g., '24h', '7d')")
            ->default_val(tokenDuration);

        std::string extraClaims = "{}";
        tokenSub->add_option("--claims", extraClaims, "Additional JWT claims (JSON)")
            ->default_val(extraClaims);

        tokenSub->callback([this, tokenDuration, extraClaims]() {
            spdlog::info("Auth token command - Coming in Phase 2");
            spdlog::info("This will generate JWT with validity: {}", tokenDuration);
            std::cout << "Status: Phase 2 - Not yet implemented\n";
            std::cout << "Expected usage: yams auth token [--key path] [--validity duration] "
                         "[--claims json]\n";
            std::cout << "\nThis will generate a JWT token for API access.\n";
            std::exit(0);
        });

        // API key subcommand
        auto* apiKeySub = authGroup->add_subcommand("api-key", "Generate API key");
        std::string apiKeyLabel;
        apiKeySub->add_option("--name", apiKeyLabel, "API key name/description")->required();

        std::string permList = "read,write";
        apiKeySub->add_option("--permissions", permList, "Comma-separated permissions")
            ->default_val(permList);

        std::string expirationDate = "never";
        apiKeySub->add_option("--expires", expirationDate, "Expiry date (ISO 8601 or 'never')")
            ->default_val(expirationDate);

        apiKeySub->callback([this, apiKeyLabel, permList, expirationDate]() {
            spdlog::info("Auth api-key command - Coming in Phase 2");
            spdlog::info("This will generate API key: {}", apiKeyLabel);
            std::cout << "Status: Phase 2 - Not yet implemented\n";
            std::cout << "Expected usage: yams auth api-key --name <name> [--permissions "
                         "read,write] [--expires date]\n";
            std::cout << "\nThis will:\n";
            std::cout << "  - Generate a secure random API key\n";
            std::cout << "  - Store it with metadata\n";
            std::cout << "  - Return the key (shown only once)\n";
            std::exit(0);
        });
    }

    Result<void> execute() override {
        // Should never be called since subcommands handle execution
        return Error{ErrorCode::NotImplemented, "Auth command requires a subcommand"};
    }

private:
    YamsCLI* cli_ = nullptr;

    // Note: These are now local variables inside registerCommand(),
    // so no need to store them as member variables unless needed elsewhere.
    // Kept for compatibility with original design intent.
};

// Factory function
std::unique_ptr<ICommand> createAuthCommand() {
    return std::make_unique<AuthCommand>();
}

