void ServerCommandDispatcher::logAdminCommand(
    std::shared_ptr<CommandSender> source,
    int flags,
    ChatPacket::EChatPacketMessage msgType,
    const std::wstring& msg,
    int extraData,
    const std::wstring& extraMsg)
{
    PlayerList* playerRegistry = MinecraftServer::getInstance()->getPlayers();

    // Notify all op players except the command sender
    for (auto iter = playerRegistry->players.begin(); iter != playerRegistry->players.end(); ++iter)
    {
        std::shared_ptr<ServerPlayer> currentPlayer = *iter;
        if (currentPlayer != source && playerRegistry->isOp(currentPlayer))
        {
            // TODO: Enhance chat packet to support richer metadata (e.g., executor name)
            // For now, suppress admin notifications until full data is available
            // currentPlayer->sendMessage(msg, msgType, extraData, extraMsg);
            // currentPlayer->sendMessage(L"\u00A77\u00A7o[" + source->getName() + L": " + currentPlayer->localize(msg, {}) + L"]");
        }
    }

    // Deliver feedback to the command origin unless explicitly suppressed
    if ((flags & LOGTYPE_DONT_SHOW_TO_SELF) == 0)
    {
        source->sendMessage(msg, msgType, extraData, extraMsg);
    }
}

