namespace YimMenu::Features
{
	class CeoKick : public PlayerCommand
	{
		using PlayerCommand::PlayerCommand;

		virtual void OnCall(Player target) override
		{
			// Handle single player case by delegating to vector version
			std::vector<Player> targets;
			targets.push_back(target);
			ExecuteKick(targets);
		}

		virtual void OnCall(const std::vector<Player>& targets) override
		{
			ExecuteKick(targets);
		}

	private:
		void ExecuteKick(const std::vector<Player>& targets)
		{
			SCRIPT_EVENT_KICK_FROM_CEO kick_message;

			for (const auto& target_player : targets)
			{
				kick_message.SetPlayer(target_player.GetId());
			}

			kick_message.Send();
		}
	};

	static CeoKick _CeoKick{"ceokick", "CEO Kick", "Kicks the player from their organization or motorcycle club"};
}

