namespace g2o {

#ifdef _WINDOWS
#if defined(_MSC_VER) || defined(_MSC_EXTENSIONS)
  #define EPOCH_DIFFERENCE_MICROSECS  11644473600000000Ui64
#else
  #define EPOCH_DIFFERENCE_MICROSECS  11644473600000000ULL
#endif

struct timezone_ex {
  int offset_minutes;   // minutes west of Greenwich
  int dst_mode;         // daylight saving time flag
};

int gettimeofday(struct timeval* tv, struct timezone_ex* tz) {
  FILETIME file_time;
  unsigned __int64 time_in_microseconds = 0;
  static int initialized_timezone = 0;

  if (tv != nullptr) {
    GetSystemTimeAsFileTime(&file_time);

    // Combine high and low parts into a 64-bit value
    time_in_microseconds |= static_cast<unsigned __int64>(file_time.dwHighDateTime) << 32;
    time_in_microseconds |= static_cast<unsigned __int64>(file_time.dwLowDateTime);

    // Convert from 100-nanosecond intervals to microseconds
    time_in_microseconds /= 10;

    // Adjust for Unix epoch (Jan 1, 1970) relative to Windows filetime base (Jan 1, 1601)
    time_in_microseconds -= EPOCH_DIFFERENCE_MICROSECS;

    // Split into seconds and microseconds
    tv->tv_sec  = static_cast<long>(time_in_microseconds / 1000000UL);
    tv->tv_usec = static_cast<long>(time_in_microseconds % 1000000UL);
  }

  if (tz != nullptr) {
    if (!initialized_timezone) {
      _tzset();
      initialized_timezone = 1;
    }

    long seconds_offset;
    int daylight_flag;
    _get_timezone(&seconds_offset);
    _get_daylight(&daylight_flag);

    tz->offset_minutes = seconds_offset / 60;
    tz->dst_mode       = daylight_flag;
  }

  return 0;
}
#endif

ScopeTime::ScopeTime(const char* title) 
  : _title(title), 
    _startTime(get_monotonic_time()) {}

ScopeTime::~ScopeTime() {
  double elapsed = get_monotonic_time() - _startTime;
  std::cerr << _title << " took " << (elapsed * 1000.0) << "ms.\n";
}

double get_monotonic_time() {
#if (defined(_POSIX_TIMERS) && (_POSIX_TIMERS+0 >= 0) && defined(_POSIX_MONOTONIC_CLOCK))
  struct timespec ts;
  clock_gettime(CLOCK_MONOTONIC, &ts);
  return static_cast<double>(ts.tv_sec) + static_cast<double>(ts.tv_nsec) * 1e-9;
#else
  return get_wall_clock_time();
#endif
}

} // end namespace g2o

