#include <iostream>

/**
 * Solves the interactive Maze problem using a deterministic edge-search strategy.
 * 
 * The maze is structured such that from any non-exit node at depth d, exactly one edge
 * leads to a node at depth d-1 (the "ascending" edge), while the other two lead to depth d+1.
 * 
 * The algorithm identifies the ascending edge by testing candidate edges and observing
 * whether the depth decreases. Once identified, it proceeds along that edge.
 * 
 * Implementation details:
 * - For each current node, test edges in order: 0, then 1.
 * - If an edge leads to a lower depth, it's the ascending edge; proceed and update depth.
 * - If not, return to the original node and try the next edge.
 * - If both tested edges are descending, infer that edge 2 must be ascending.
 * 
 * This ensures at most 5 moves and 2 queries per depth reduction step,
 * which is efficient for depths up to 10^4.
 */
void solve() {
    long long current_depth;
    std::cin >> current_depth;

    while (current_depth > 0) {
        bool ascent_found = false;

        // Test edges 0 and 1 sequentially
        for (int edge_color = 0; edge_color < 2; ++edge_color) {
            // Attempt move along current edge
            std::cout << "move " << edge_color << std::endl;
            int exit_status;
            std::cin >> exit_status;
            if (exit_status == 1) {
                return; // Reached exit
            }

            // Query new depth after tentative move
            std::cout << "query" << std::endl;
            long long next_depth;
            std::cin >> next_depth;

            if (next_depth < current_depth) {
                // Confirmed ascending edge
                current_depth = next_depth;
                ascent_found = true;
                break;
            } else {
                // Descending edge: backtrack
                std::cout << "move " << edge_color << std::endl;
                std::cin >> exit_status; // Discard result (should be 0)
            }
        }

        if (ascent_found) {
            continue;
        }

        // Both 0 and 1 were descending; deduce 2 is ascending
        std::cout << "move 2" << std::endl;
        int exit_status;
        std::cin >> exit_status;
        if (exit_status == 1) {
            return; // Reached exit
        }

        // Depth must have decreased by 1; no query needed
        --current_depth;
    }
}

int main() {
    // Interactive problems require immediate output flushing
    // Using std::endl ensures automatic flush on each line
    solve();
    return 0;
}

