namespace sdb {

namespace {
// Singleton instance for monitoring system-wide resource usage
GlobalResourceMonitor gResourceMonitor;
}  // namespace

int64_t GlobalResourceMonitor::current() const noexcept {
  return _current.load(std::memory_order_relaxed);
}

GlobalResourceMonitor::Stats GlobalResourceMonitor::stats() const noexcept {
  Stats result;
  result.global_limit_reached =
      _global_limit_reached_counter.load(std::memory_order_relaxed);
  result.local_limit_reached =
      _local_limit_reached_counter.load(std::memory_order_relaxed);
  return result;
}

void GlobalResourceMonitor::trackGlobalViolation() noexcept {
  _global_limit_reached_counter.fetch_add(1, std::memory_order_relaxed);
}

void GlobalResourceMonitor::trackLocalViolation() noexcept {
  _local_limit_reached_counter.fetch_add(1, std::memory_order_relaxed);
}

/// Attempt to increase global memory usage by <amount> bytes.
/// Returns false if the operation would exceed the configured limit.
/// Otherwise, updates the counter atomically and returns true.
bool GlobalResourceMonitor::increaseMemoryUsage(int64_t amount) noexcept {
  SDB_ASSERT(amount >= 0);

  if (_limit == 0) {
    // No limit enforced — directly increment
    _current.fetch_add(amount, std::memory_order_relaxed);
    return true;
  }

  // Enforce limit: use CAS loop to avoid race conditions
  int64_t current_val = _current.load(std::memory_order_relaxed);
  while (true) {
    int64_t proposed = current_val + amount;
    if (proposed > _limit) [[unlikely]] {
      return false;  // Would exceed limit
    }
    if (_current.compare_exchange_weak(current_val, proposed,
                                       std::memory_order_relaxed)) {
      return true;  // Successfully updated
    }
    // CAS failed — retry with updated current_val
  }
}

void GlobalResourceMonitor::decreaseMemoryUsage(int64_t amount) noexcept {
  SDB_ASSERT(amount >= 0);
  _current.fetch_sub(amount, std::memory_order_relaxed);
}

void GlobalResourceMonitor::forceUpdateMemoryUsage(int64_t delta) noexcept {
  _current.fetch_add(delta, std::memory_order_relaxed);
}

GlobalResourceMonitor& GlobalResourceMonitor::instance() noexcept {
  return gResourceMonitor;
}

