using namespace std;

// Topological Sorting:
// Linear ordering of vertices such that for every directed edge u -> v, vertex u comes before v in the ordering.
// Uses: To solve dependency resolution problems, scheduling tasks, etc.

class DirectedGraph {
    int vertexCount; // Number of vertices
    list<int>* adjacencyList; // Adjacency list representation
public:
    DirectedGraph(int V) {
        vertexCount = V;
        adjacencyList = new list<int>[V];
    }

    void addConnection(int from, int to) {
        adjacencyList[from].push_back(to); // Add 'to' to 'from's adjacency list
    }

    // Kahn's algorithm for topological sorting using BFS
    void performTopologicalSort() {
        vector<int> inDegree(vertexCount, 0);

        // Calculate in-degrees for all vertices
        for (int i = 0; i < vertexCount; ++i) {
            for (int neighbor : adjacencyList[i]) {
                inDegree[neighbor]++;
            }
        }

        // Queue to store vertices with zero in-degree
        queue<int> zeroInDegreeQueue;
        for (int i = 0; i < vertexCount; ++i) {
            if (inDegree[i] == 0) {
                zeroInDegreeQueue.push(i);
            }
        }

        vector<int> resultOrder;

        // Process vertices with zero in-degree
        while (!zeroInDegreeQueue.empty()) {
            int current = zeroInDegreeQueue.front();
            zeroInDegreeQueue.pop();
            resultOrder.push_back(current);

            // Reduce in-degree of adjacent vertices
            for (int neighbor : adjacencyList[current]) {
                inDegree[neighbor]--;
                if (inDegree[neighbor] == 0) {
                    zeroInDegreeQueue.push(neighbor);
                }
            }
        }

        // Output the topological order
        cout << "Topological Sort of the given graph:\n";
        for (int vertex : resultOrder) {
            cout << vertex << " ";
        }
        cout << endl;
    }

    ~DirectedGraph() {
        delete[] adjacencyList;
    }
};

int main() {
    DirectedGraph g(6);
    g.addConnection(5, 2);
    g.addConnection(5, 0);
    g.addConnection(4, 0);
    g.addConnection(4, 1);
    g.addConnection(2, 3);
    g.addConnection(3, 1);

    g.performTopologicalSort();
    return 0;
}
// Time Complexity: O(V + E) for topological sort using Kahn's algorithm (BFS)
// Space Complexity: O(V) for the in-degree array and queue

