// Helper to validate route against expectations
void ValidateRouteAgainstExpectations(Checkpoints const& cps, double distM, double timeS, size_t ptsCount)
{
  auto const routeResult = integration::CalculateRoute(
      integration::GetVehicleComponents(VehicleType::Pedestrian), cps, GetTestGuides());
  TEST_EQUAL(routeResult.second, RouterResultCode::NoError, ());
  integration::TestRouteLength(*routeResult.first, distM);
  integration::TestRouteTime(*routeResult.first, timeS);
  integration::TestRoutePointsNumber(*routeResult.first, ptsCount);
}

// Reverses the checkpoint sequence in-place by copying, reversing, and reassigning
void InvertCheckpointsOrder(Checkpoints& cps)
{
  auto pts = cps.GetPoints();
  std::reverse(pts.begin(), pts.end());
  cps = Checkpoints{pts};
}

// Test case: two checkpoints both lying directly on the guide track
UNIT_TEST(Guides_TwoPointsOnTrack)
{
  Checkpoints cps{mercator::FromLatLon(48.14367, 11.57257), mercator::FromLatLon(48.13999, 11.56873)};
  double const expectedDistM = 600.8;
  double const expectedTimeS = 721.0;
  size_t const expectedPointsCount = 7;

  ValidateRouteAgainstExpectations(cps, expectedDistM, expectedTimeS, expectedPointsCount);
  InvertCheckpointsOrder(cps);
  ValidateRouteAgainstExpectations(cps, expectedDistM, expectedTimeS, expectedPointsCount);
}

