using json = nlohmann::json;
using namespace nlohmann::literals;

// Helper function to display BJData bytes in human-readable form
void show_byte(uint8_t val)
{
    if (val >= 32 && val <= 126)
    {
        std::cout << static_cast<char>(val);
    }
    else
    {
        std::cout << static_cast<int>(val);
    }
}

int main()
{
    // Construct a JSON object with two key-value pairs
    json obj = R"({"compact": true, "schema": false})"_json;

    // Convert the JSON object to BJData format
    std::vector<std::uint8_t> bjdata_bytes = json::to_bjdata(obj);

    // Output each byte in readable format
    for (const auto& b : bjdata_bytes)
    {
        show_byte(b);
    }
    std::cout << '\n';

    // Create a JSON array of integers
    json numbers = {1, 2, 3, 4, 5, 6, 7, 8};

    // Serialize using default settings
    std::vector<std::uint8_t> default_encoding = json::to_bjdata(numbers);

    // Serialize with size optimization enabled
    std::vector<std::uint8_t> size_optimized = json::to_bjdata(numbers, true);

    // Serialize with both size and type optimizations enabled
    std::vector<std::uint8_t> full_optimized = json::to_bjdata(numbers, true, true);

    // Print results of each encoding strategy
    for (const auto& b : default_encoding)
    {
        show_byte(b);
    }
    std::cout << '\n';

    for (const auto& b : size_optimized)
    {
        show_byte(b);
    }
    std::cout << '\n';

    for (const auto& b : full_optimized)
    {
        show_byte(b);
    }
    std::cout << '\n';

    return 0;
}

