UGoogleVRWidgetInteractionComponent::UGoogleVRWidgetInteractionComponent(const FObjectInitializer& ObjectInitializer)
{
	PrimaryComponentTick.bCanEverTick = false;
}

void UGoogleVRWidgetInteractionComponent::UpdateState(const FHitResult& HitResult)
{
	// Ensure the interaction source is explicitly set to custom
	InteractionSource = EWidgetInteractionSource::Custom;

	// Store the provided hit result for later use
	SetCustomHitResult(HitResult);

	// Trigger pointer movement simulation to update UI state
	SimulatePointerMovement();
}

FWidgetPath UGoogleVRWidgetInteractionComponent::FindHoveredWidgetPath(const FWidgetTraceResult& TraceResult) const
{
	if (TraceResult.HitWidgetComponent.IsValid())
	{
		// Use a small positive radius to avoid edge-case failures in path detection.
		// Although LastHitResult.ImpactPoint already reflects the precise hit location,
		// using zero radius may cause GetHitWidgetPath to miss valid widgets near boundaries.
		const float CursorRadius = 5.0f;

		return FWidgetPath(
			TraceResult.HitWidgetComponent->GetHitWidgetPath(
				TraceResult.LocalHitLocation, 
				/*bIgnoreEnabledStatus=*/ false, 
				CursorRadius
			)
		);
	}
	else
	{
		return FWidgetPath{};
	}
}

