using namespace sdb::options;

Section::Section(const std::string& sectionName,
                 const std::string& sectionDesc,
                 const std::string& urlLink,
                 const std::string& altName,
                 bool isHidden,
                 bool isOutdated)
  : name(sectionName),
    description(sectionDesc),
    link(urlLink),
    alias(altName),
    hidden(isHidden),
    obsolete(isOutdated) {}

Section::~Section() = default;

std::string Section::displayName() const {
  return (!alias.empty()) ? alias : name;
}

// Check if this section contains any visible (non-uncommon) options
bool Section::hasOptions() const {
  if (hidden) {
    return false;
  }
  for (size_t idx = 0; idx < options.size(); ++idx) {
    const auto& optRef = options.at(idx);
    if (!(optRef.second.hasFlag(sdb::options::Flags::Uncommon))) {
      return true;
    }
  }
  return false;
}

// Display help for this section or all sections if search == "."
void Section::printHelp(const std::string& query,
                        size_t labelWidth,
                        size_t valueWidth,
                        bool useColors) const {
  // Skip printing if not matching search criteria
  if (query != "." && (hidden || !hasOptions())) {
    return;
  }

  std::cout << "Section '" 
            << (useColors ? colors::kBright : "") 
            << displayName()
            << (useColors ? colors::kReset : "") 
            << "' (configure " << description << ")";

  if (!link.empty()) {
    std::cout << " [";
    if (useColors) {
      std::cout << colors::kLinkStart << link << colors::kLinkMiddle << link << colors::kLinkEnd;
    } else {
      std::cout << link;
    }
    std::cout << "]";
  }
  std::cout << std::endl;

  auto headlineIter = headlines.begin();
  // Iterate over options using index to allow mixed traversal with headlines
  for (size_t i = 0; i < options.size(); ++i) {
    const auto& key = options.key_at(i); // assuming map-like container supports .key_at(i)
    const auto& optionObj = options.at(i);

    // Print section headline if current option matches next headline threshold
    if (headlineIter != headlines.end() && key >= headlineIter->first) {
      std::cout << " # " << headlineIter->second << std::endl;
      ++headlineIter;
    }

    // Skip obsolete options entirely
    if (optionObj.hasFlag(sdb::options::Flags::Obsolete)) {
      continue;
    }

    // Delegate actual option help printing
    optionObj.printHelp(query, labelWidth, valueWidth, useColors);
  }

  std::cout << std::endl;
}

// Compute maximum display width among all non-hidden options
size_t Section::optionsWidth() const {
  size_t maxWidth = 0;
  if (!hidden) {
    for (auto iter = options.begin(); iter != options.end(); ++iter) {
      size_t optWidth = iter->second.optionsWidth();
      if (optWidth > maxWidth) {
        maxWidth = optWidth;
      }
    }
  }
  return maxWidth;
}

