using namespace lemon;

// Shared shutdown indicator and server reference
static std::atomic<bool> s_exit_requested{false};
static Server* s_active_server = nullptr;

// Asynchronous-safe signal handler for termination signals
void handle_termination_signal(int sig) {
    if (SIGINT == sig || SIGTERM == sig) {
#ifndef _WIN32
        constexpr const char msg[] = "Shutdown signal received, exiting...\n";
        write(STDOUT_FILENO, msg, sizeof(msg) - 1);
#endif
        // Avoid unsafe operations in signal context; just flag and exit
        s_exit_requested.store(true);
        _exit(EXIT_SUCCESS);
#ifdef SIGHUP
    } else if (SIGHUP == sig) {
        // SIGHUP is intentionally ignored to support daemonization
        return;
#endif
    }
}

int main(int argc, char* argv[]) {
    // Early single-instance guard
    if (SingleInstance::IsAnotherInstanceRunning("Router")) {
        std::cerr << "Error: Another instance of lemonade-router is already active.\n"
                  << "Only one instance may run at a time." << std::endl;
        return EXIT_FAILURE;
    }

    try {
        CLIParser cli;
        cli.parse(argc, argv);

        // Handle early exits (e.g., --help, --version)
        if (!cli.should_proceed()) {
            return cli.get_exit_status();
        }

        auto settings = cli.get_config();

        // Setup logging sink
        auto console_sink = std::make_shared<AixLog::SinkCout>(
            AixLog::Filter(AixLog::to_severity(settings.log_level)),
            "%Y-%m-%d %H:%M:%S.#ms [#severity] (#tag_func) #message"
        );
        AixLog::Log::initialize({console_sink});

        // Log startup info
        LOG(INFO) << "Initializing Lemonade Server..." << std::endl;
        LOG(INFO) << "  Version: " << LEMON_VERSION_STRING << std::endl;
        LOG(INFO) << "  Listening on port " << settings.port << " at " << settings.host << std::endl;
        LOG(INFO) << "  Logging verbosity set to: " << settings.log_level << std::endl;
        if (!settings.models_path.empty()) {
            LOG(INFO) << "  Additional model directory: " << settings.models_path << std::endl;
        }

        // Construct and configure server
        Server srv(
            settings.port,
            settings.host,
            settings.log_level,
            settings.recipe_opts,
            settings.max_models,
            settings.models_path,
            settings.disable_broadcast,
            settings.global_timeout_ms
        );

        // Install signal handlers
        s_active_server = &srv;
        std::signal(SIGINT, handle_termination_signal);
        std::signal(SIGTERM, handle_termination_signal);

        // Run server loop
        srv.start();

        // Cleanup after graceful shutdown
        s_active_server = nullptr;
        return EXIT_SUCCESS;

    } catch (const std::exception& ex) {
        LOG(ERROR) << "Fatal error: " << ex.what() << std::endl;
        return EXIT_FAILURE;
    }
}

