namespace s11n_example {

/// Client class that fetches stock data from a remote server
class client
{
public:
  /// Constructor initiates connection to the server
  client(asio::io_context& context,
      const std::string& hostname, const std::string& port)
    : conn_(context)
  {
    // Convert host and service into endpoints
    asio::ip::tcp::resolver resolver(context);
    auto results = resolver.resolve(hostname, port);

    // Initiate asynchronous connection
    asio::async_connect(conn_.socket(), results,
        boost::bind(&client::on_connection_complete, this,
          asio::placeholders::error));
  }

  /// Called when the connection attempt finishes
  void on_connection_complete(const asio::error_code& err)
  {
    if (!err)
    {
      // Connection successful — begin receiving stock data
      conn_.async_read(stock_data_,
          boost::bind(&client::on_data_received, this,
            asio::placeholders::error));
    }
    else
    {
      std::cerr << "Connection failed: " << err.message() << std::endl;
    }
  }

  /// Called after stock list is fully received
  void on_data_received(const asio::error_code& err)
  {
    if (!err)
    {
      // Display each stock record
      for (std::size_t idx = 0; idx < stock_data_.size(); ++idx)
      {
        const auto& item = stock_data_[idx];
        std::cout << "Stock #" << idx << "\n";
        std::cout << "  symbol: " << item.code << "\n";
        std::cout << "  company: " << item.name << "\n";
        std::cout << "  opening: " << item.open_price << "\n";
        std::cout << "  high: " << item.high_price << "\n";
        std::cout << "  low: " << item.low_price << "\n";
        std::cout << "  closing: " << item.last_price << "\n";
        std::cout << "  bid: " << item.buy_price << "\n";
        std::cout << "  bid_vol: " << item.buy_quantity << "\n";
        std::cout << "  ask: " << item.sell_price << "\n";
        std::cout << "  ask_vol: " << item.sell_quantity << "\n";
      }
    }
    else
    {
      std::cerr << "Data transfer error: " << err.message() << std::endl;
    }
    // No further operations scheduled — io_context will terminate naturally
  }

private:
  connection conn_;
  std::vector<stock> stock_data_;
};

} // namespace s11n_example

