#include <iostream>
#include <cstdlib>

// Function to send a query and receive the result
long long ask(long long node, long long steps) {
    std::cout << "? " << node << " " << steps << std::endl;
    long long response;
    std::cin >> response;
    return response;
}

// Function to submit the final answer and verify correctness
void submit(long long cycle_length) {
    std::cout << "! " << cycle_length << std::endl;
    int verification;
    std::cin >> verification;
    if (verification == -1) {
        // Incorrect answer — terminate immediately
        std::exit(0);
    }
}

// Main solving logic
void process() {
    // First, find a node that lies on the cycle by starting from node 1 with a huge jump
    long long cycle_node = ask(1, 5000000000000000000LL);

    // Step 1: Determine an upper bound for the cycle length using exponential search
    long long interval_size = 1;
    long long current_position = ask(cycle_node, 1);

    while (current_position != cycle_node) {
        current_position = ask(current_position, interval_size);
        interval_size <<= 1;  // Double the interval size each time
    }

    // Now we know the cycle length s satisfies: interval_size/2 < s <= interval_size
    long long left = interval_size / 2 + 1;
    long long right = interval_size;
    long long min_cycle = interval_size;

    // Step 2: Binary search within [left, right] to find the minimal cycle length
    while (left <= right) {
        long long mid = left + (right - left) / 2;

        if (mid == 0) {
            left = 1;
            continue;
        }

        if (ask(cycle_node, mid) == cycle_node) {
            min_cycle = mid;
            right = mid - 1;
        } else {
            left = mid + 1;
        }
    }

    submit(min_cycle);
}

int main() {
    // Optimize I/O performance
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int test_cases;
    std::cin >> test_cases;

    while (test_cases--) {
        process();
    }

    return 0;
}

