#include "ByteArrayOutputStream.h"

// Creates a new byte array output stream. The buffer capacity is initially 32 bytes, though its size increases if necessary.
ByteArrayOutputStream::ByteArrayOutputStream()
{
    size = 0;
    buffer = byteArray(32);
}

// Creates a new byte array output stream, with a buffer capacity of the specified size, in bytes.
// Parameters:
// size - the initial size.
ByteArrayOutputStream::ByteArrayOutputStream(unsigned int initialCapacity)
{
    size = 0;
    buffer = byteArray(initialCapacity);
}

ByteArrayOutputStream::~ByteArrayOutputStream()
{
    if (buffer.data != nullptr)
    {
        delete[] buffer.data;
        buffer.data = nullptr;
    }
}

// Writes the specified byte to this byte array output stream.
// Parameters:
// b - the byte to be written.
void ByteArrayOutputStream::write(unsigned int value)
{
    // Ensure sufficient space before writing
    if (size >= buffer.length)
    {
        buffer.resize(buffer.length == 0 ? 1 : buffer.length * 2);
    }

    buffer[size] = static_cast<byte>(value);
    ++size;
}

// Writes b.length bytes from the specified byte array to this output stream.
// The general contract for write(b) is that it should have exactly the same effect as the call write(b, 0, b.length).
void ByteArrayOutputStream::write(byteArray source)
{
    write(source, 0, source.length);
}

// Writes len bytes from the specified byte array starting at offset off to this byte array output stream.
// Parameters:
// b - the data.
// off - the start offset in the data.
// len - the number of bytes to write.
void ByteArrayOutputStream::write(byteArray source, unsigned int offset, unsigned int length)
{
    // Validate input parameters
    if (source.length < offset + length)
    {
        return; // Or handle error appropriately
    }

    // Expand buffer if needed
    unsigned int requiredSize = size + length;
    if (requiredSize > buffer.length)
    {
        unsigned int newCapacity = buffer.length * 2;
        if (newCapacity < requiredSize + 1)
        {
            newCapacity = requiredSize + 1;
        }
        buffer.resize(newCapacity);
    }

    // Copy data into the internal buffer
    std::memcpy(buffer.data + size, source.data + offset, length);
    size += length;
}

// Closing a ByteArrayOutputStream has no effect.
// The methods in this class can be called after the stream has been closed without generating an IOException.
void ByteArrayOutputStream::close()
{
    // No-op implementation
}

// Creates a newly allocated byte array. Its size is the current size of this output stream and the valid contents of the buffer have been copied into it.
// Returns:
// the current contents of this output stream, as a byte array.
byteArray ByteArrayOutputStream::toByteArray() const
{
    byteArray result(size);
    if (size > 0 && buffer.data != nullptr)
    {
        std::memcpy(result.data, buffer.data, size);
    }
    return result;
}

#include <vector>
#include <algorithm>

class Solution {
public:
    double findMaxAverage(std::vector<int>& nums, int k) {
        int n = nums.size();
        double currentSum = 0;

        // Calculate sum of first k elements
        for (int i = 0; i < k; ++i) {
            currentSum += nums[i];
        }

        double maximumSum = currentSum;
        int currentIndex = k;

        // Slide the window and update max sum
        while (currentIndex < n) {
            currentSum = currentSum - nums[currentIndex - k] + nums[currentIndex];
            maximumSum = std::max(currentSum, maximumSum);
            ++currentIndex;
        }

        return maximumSum / k;
    }
};

