using namespace std;

// Global array to store the reconstructed sequence (size sufficient for max N = 200,000)
int result[200010];

/**
 * Recursive divide-and-conquer function to reconstruct the sequence.
 * Works by querying subranges and filling in values when a uniform segment is found.
 */
void reconstruct(int left, int right) {
    if (left > right) return;

    // Query the current segment [left, right]
    cout << "? " << left << " " << right << endl;
    cout.flush(); // Ensure output is sent immediately for interactive problems

    long long mode_value;
    int frequency;

    // Read response with error handling
    if (!(cin >> mode_value >> frequency)) {
        exit(0);
    }

    // Handle invalid query response
    if (mode_value == -1) {
        exit(0);
    }

    int mode = static_cast<int>(mode_value);

    // If all elements in this range are identical, fill them directly
    if (frequency == right - left + 1) {
        for (int idx = left; idx <= right; ++idx) {
            result[idx] = mode;
        }
        return;
    }

    // Otherwise, split the range and recurse on both halves
    int center = (left + right) / 2;
    reconstruct(left, center);
    reconstruct(center + 1, right);
}

int main() {
    // Optimize I/O performance
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    if (cin >> n) {
        // Begin reconstruction from full range [1, n]
        reconstruct(1, n);

        // Output final answer
        cout << "! ";
        for (int i = 1; i <= n; ++i) {
            cout << result[i];
            if (i < n) cout << " ";
        }
        cout << endl;
    }

    return 0;
}

#include <iostream>
#include <vector>
#include <string>

void send_query(int state_count, const std::vector<int>& trans0, const std::vector<int>& trans1) {
    std::cout << 1 << "\n";
    std::cout << state_count << "\n";

    for (int i = 0; i < state_count; ++i) {
        std::cout << trans0[i];
        if (i < state_count - 1) std::cout << " ";
    }
    std::cout << "\n";

    for (int i = 0; i < state_count; ++i) {
        std::cout << trans1[i];
        if (i < state_count - 1) std::cout << " ";
    }
    std::cout << "\n";
    std::cout.flush();
}

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int len;
    std::cin >> len;

    std::string result_str(len, '0');

    // Process each character position sequentially
    for (int pos = 0; pos < len; ++pos) {
        // Create automaton with (pos + 2) states
        int num_states = pos + 2;

        std::vector<int> zero_trans(num_states);
        std::vector<int> one_trans(num_states);

        // Build transition table: first 'pos' positions form a chain
        for (int st = 0; st < pos; ++st) {
            zero_trans[st] = st + 1;
            one_trans[st] = st + 1;
        }

        // At position 'pos', decide based on input bit
        zero_trans[pos] = pos;      // '0' keeps us in decision state
        one_trans[pos] = pos + 1;   // '1' moves to accepting state

        // Sink states remain fixed once reached
        if (pos + 1 < num_states) {
            zero_trans[pos + 1] = pos + 1;
            one_trans[pos + 1] = pos + 1;
        }

        // Send query and get response
        send_query(num_states, zero_trans, one_trans);

        int answer;
        std::cin >> answer;

        // Determine the actual bit value from the response
        result_str[pos] = (answer == pos) ? '0' : '1';
    }

    // Output final result
    std::cout << 0 << "\n";
    std::cout << result_str << "\n";
    std::cout.flush();

    return 0;
}

