// Generate current time string (daytime)
std::string get_current_time()
{
  using namespace std;
  time_t current_time = time(0);
  return ctime(&current_time);
}

// Connection class handling client communication
class connection_handler
  : public boost::enable_shared_from_this<connection_handler>
{
public:
  typedef boost::shared_ptr<connection_handler> ptr_type;

  static ptr_type make(asio::io_context& ctx)
  {
    return ptr_type(new connection_handler(ctx));
  }

  tcp::socket& get_socket()
  {
    return socket_;
  }

  void begin()
  {
    data_ = get_current_time();
    asio::async_write(socket_, asio::buffer(data_),
        boost::bind(&connection_handler::on_write_complete,
          shared_from_this(),
          asio::placeholders::error,
          asio::placeholders::bytes_transferred));
  }

private:
  connection_handler(asio::io_context& ctx)
    : socket_(ctx)
  {
  }

  void on_write_complete(const asio::error_code& /*err*/, size_t /*bytes*/)
  {
    // Write operation completed - no further action needed
  }

  tcp::socket socket_;
  std::string data_;
};

// Server class managing incoming connections
class server_instance
{
public:
  server_instance(asio::io_context& ctx)
    : acceptor_(ctx, tcp::endpoint(tcp::v4(), 13))
  {
    initiate_accept();
  }

private:
  void initiate_accept()
  {
    connection_handler::ptr_type new_conn =
      connection_handler::make(acceptor_.get_executor().context());

    acceptor_.async_accept(new_conn->get_socket(),
        boost::bind(&server_instance::on_accept,
          this, new_conn, asio::placeholders::error));
  }

  void on_accept(connection_handler::ptr_type conn, const asio::error_code& err)
  {
    if (!err)
    {
      conn->begin();
    }
    initiate_accept();
  }

  tcp::acceptor acceptor_;
};

int main()
{
  try
  {
    asio::io_context context;
    server_instance server(context);
    context.run();
  }
  catch (const std::exception& ex)
  {
    std::cerr << "Error: " << ex.what() << std::endl;
  }
  return 0;
}

