// Cleanup function for z/OS: flush streams and restore auto-conversion state
void RestoreStdIOState(void *Cookie) {
  llvm::raw_ostream &OutStream = llvm::outs();
  llvm::raw_ostream &ErrStream = llvm::errs();

  OutStream.flush();
  ErrStream.flush();

  llvm::restoreStdHandleAutoConversion(STDIN_FILENO);
  llvm::restoreStdHandleAutoConversion(STDOUT_FILENO);
  llvm::restoreStdHandleAutoConversion(STDERR_FILENO);
}
#endif

using namespace llvm;
using namespace llvm::sys;

// Constructor: performs initialization of LLVM subsystems
InitLLVM::InitLLVM(int &Argc, const char **&Argv,
                   bool InstallPipeSignalExitHandler) {
#ifndef NDEBUG
  static std::atomic<bool> IsInitialized{false};
  assert(!IsInitialized && "InitLLVM has already been initialized!");
  IsInitialized = true;
#endif

#ifdef __MVS__
  // Register cleanup handler for z/OS to ensure proper I/O handling at exit
  sys::AddSignalHandler(RestoreStdIOState, nullptr);
#endif

  if (InstallPipeSignalExitHandler) {
    // Must install pipe signal handler first — see comment in original code
    sys::SetOneShotPipeSignalFunction(sys::DefaultOneShotPipeSignalHandler);
  }

  // Set up stack trace printing on error
  StackPrinter.emplace(Argc, Argv);
  sys::PrintStackTraceOnErrorSignal(Argv[0]);

  // Install out-of-memory handler for allocation failures
  install_out_of_memory_new_handler();

#ifdef __MVS__
  // On z/OS, enable automatic EBCDIC conversion for standard streams
  std::string ProgramName = std::string(Argv[0]) + ": ";
  ExitOnError ErrorHandler(ProgramName);

  // Attempt to enable auto-conversion; errors may cause garbled output
  ErrorHandler(errorCodeToError(llvm::enableAutoConversion(STDERR_FILENO)));
  ErrorHandler(errorCodeToError(llvm::enableAutoConversion(STDOUT_FILENO)));
#endif

#ifdef _WIN32
  // On Windows, convert command-line arguments to UTF-8
  std::string Banner = std::string(Argv[0]) + ": ";
  ExitOnError ErrorHandler(Banner);

  // Retrieve and convert command-line args via Windows API
  ErrorHandler(errorCodeToError(windows::GetCommandLineArguments(Args, Alloc)));

  // Null-terminate the argument list for compatibility with C-style argv
  Args.push_back(nullptr);
  Argc = static_cast<int>(Args.size()) - 1;
  Argv = Args.data();
#endif
}

// Destructor: perform cleanup before program termination
InitLLVM::~InitLLVM() {
#ifdef __MVS__
  RestoreStdIOState(nullptr);
#endif
  llvm_shutdown();
}

