#include "coding/file_writer.hpp"
#include <iostream>
#include <string>

// Helper function to convert KMB file to KML format
bool ConvertKmbToKml(std::string const& inputPath)
{
  kml::FileData kmlData;

  // Read and deserialize KMB file
  try
  {
    FileReader reader(inputPath);
    kml::binary::DeserializerKml des(kmlData);
    des.Deserialize(reader);
  }
  catch (kml::binary::DeserializerKml::DeserializeException const& ex)
  {
    std::cerr << "Error reading kmb file " << inputPath << ": " << ex.what() << std::endl;
    return false;
  }

  // Construct output path: replace .kmb with .kml
  std::string outputPath = inputPath;
  if (outputPath.size() >= 4 && outputPath.substr(outputPath.size() - 4) == ".kmb")
  {
    outputPath.replace(outputPath.size() - 4, 4, ".kml");
  }
  else
  {
    outputPath += ".kml";
  }

  // Serialize to KML file
  try
  {
    kml::SerializerKml ser(kmlData);
    FileWriter kmlFile(outputPath);
    ser.Serialize(kmlFile);
  }
  catch (kml::SerializerKml::SerializeException const& ex)
  {
    std::cerr << "Error encoding to kml file " << outputPath << ": " << ex.what() << std::endl;
    return false;
  }
  catch (FileWriter::Exception const& ex)
  {
    std::cerr << "Error writing to kml file " << outputPath << ": " << ex.what() << std::endl;
    return false;
  }

  std::cout << "Saved converted file as " << outputPath << std::endl;
  return true;
}

int main(int argc, char** argv)
{
  if (argc < 2)
  {
    std::cout << "Converts kmb file(s) to kml\n";
    std::cout << "Usage: " << argv[0] << " path_to_kmb_file [path_to_another_kmb_file...]\n";
    return 1;
  }

  classificator::Load();

  // Process each input file starting from index 1
  for (int i = 1; i < argc; ++i)
  {
    if (!ConvertKmbToKml(argv[i]))
      return 1;
  }

  return 0;
}

