namespace Karm::Ui {

// MARK: Event Dispatching ------------------------------------------------------
export template <typename EventType, typename... ParamTypes>
void dispatch(Node& target, ParamTypes&&... params) {
    auto eventPtr = App::makeEvent<EventType>(std::forward<ParamTypes>(params)...);
    target.event(*eventPtr);
}

export template <typename EventType, typename... ParamTypes>
void propagate(Node& target, ParamTypes&&... params) {
    auto eventPtr = App::makeEvent<EventType>(std::forward<ParamTypes>(params)...);
    target.bubble(*eventPtr);
}

export template <typename EventType, typename... ParamTypes>
auto makeHandler(ParamTypes&&... params) {
    return [captured = std::make_tuple(std::forward<ParamTypes>(params)...)](Node& node) mutable {
        std::apply([&node](auto&&... args) {
            dispatch<EventType>(node, std::forward<decltype(args)>(args)...);
        }, captured);
    };
}

export template <typename EventType, typename... ParamTypes>
auto makePropagator(ParamTypes&&... params) {
    return [captured = std::make_tuple(std::forward<ParamTypes>(params)...)](Node& node) mutable {
        std::apply([&node](auto&&... args) {
            propagate<EventType>(node, std::forward<decltype(args)>(args)...);
        }, captured);
    };
}

export template <typename EventType, typename... ParamTypes>
Opt<Func<void(Node&)>> conditionalHandler(bool condition, ParamTypes&&... params) {
    if (not condition)
        return std::nullopt;
    return makeHandler<EventType>(std::forward<ParamTypes>(params)...);
}

export template <typename EventType, typename... ParamTypes>
Opt<Func<void(Node&)>> conditionalPropagator(bool condition, ParamTypes&&... params) {
    if (not condition)
        return std::nullopt;
    return makePropagator<EventType>(std::forward<ParamTypes>(params)...);
}

// MARK: UI Lifecycle Helpers ---------------------------------------------------
export void requestRepaint(Node& node) {
    propagate<Node::PaintEvent>(node, node.bound());
}

export void requestRepaint(Node& node, Math::Recti region) {
    propagate<Node::PaintEvent>(node, region);
}

export void requestRelayout(Node& node) {
    propagate<Node::LayoutEvent>(node);
}

export void requestAnimation(Node& node) {
    propagate<Node::AnimateEvent>(node, 0.0);
}

export void notifyMouseExit(Node& node) {
    dispatch<App::MouseLeaveEvent>(node);
}

export void notifyMouseExit(Container& container) {
    for (auto& child : container) {
        notifyMouseExit(*child);
    }
}

} // namespace Karm::Ui

