#include <mplot/Visual.h>
#include <mplot/GraphVisual.h>
#include <sstream>

int main() {
    // Initialize the visualization window with custom dimensions and title
    mplot::Visual scene(1280, 575, "Made with mplot::GraphVisual");

    // Instantiate a GraphVisual for double-precision data at origin
    auto graph = std::make_unique<mplot::GraphVisual<double>>(sm::vec<float>{0.0f, 0.0f, 0.0f});

    // Bind the graph to the visual scene (required internal setup)
    scene.bindmodel(graph);

    // Prepare x-axis data: 11 points from 0 to 10 inclusive
    sm::vvec<double> x_coords;
    x_coords.linspace(0.0, 10.0, 11);

    // Define y-values manually (same as original)
    sm::vvec<double> y_values{5.0, 8.0, 2.0, 9.0, 1.0, 2.0, 4.0, 5.0, 8.0, 3.0, 1.0};

    // Configure primary dataset style: crimson line
    mplot::DatasetStyle primary_style(mplot::stylepolicy::lines);
    primary_style.linecolour = mplot::colour::crimson;

    // Enforce fixed y-axis range [0, 10]
    graph->setlimits_y(0.0, 10.0);

    // Assign data to the graph
    graph->setdata(x_coords, y_values, primary_style);

    // Secondary style for horizontal reference line at y=7
    mplot::DatasetStyle cross_line_style(mplot::stylepolicy::lines);
    cross_line_style.linecolour = mplot::colour::grey68;
    cross_line_style.linewidth = primary_style.linewidth * 0.6f;

#ifdef GRAPH_LINES_SIMPLE
    // In simple mode, just draw crossing lines without annotation
    graph->add_y_crossing_lines(x_coords, y_values, 7.0, primary_style);
#else
    // Compute exact x-coordinates where curve crosses y=7
    sm::vvec<double> crossing_points = graph->add_y_crossing_lines(
        x_coords, y_values, 7.0, primary_style, cross_line_style
    );

    // Build human-readable string listing crossing points
    std::ostringstream oss;
    const size_t count = crossing_points.size();
    if (count > 0) {
        for (size_t idx = 0; idx < count; ++idx) {
            if (idx == 0 || idx == count - 1) {
                oss << std::format("{:.2f}", crossing_points[idx]);
            } else {
                oss << std::format(", {:.2f}", crossing_points[idx]);
            }
        }
        // Replace final comma+space with " and " before last item
        std::string temp = oss.str();
        size_t last_comma = temp.rfind(", ");
        if (last_comma != std::string::npos && last_comma + 2 < temp.length()) {
            temp.replace(last_comma, 2, " and ");
            oss.str("");
            oss << temp;
        }
    } else {
        oss << "[no values]";
    }

    // Add descriptive label at bottom-left corner
    graph->addLabel(
        std::format("y=7 at x = {}", oss.str()),
        {0.05f, 0.05f, 0.0f},
        mplot::TextFeatures{0.03f}
    );
#endif

    // Finalize geometry generation for rendering
    graph->finalize();

    // Transfer ownership of graph model into the scene
    scene.addVisualModel(std::move(graph));

    // Launch interactive display loop
    scene.keepOpen();

    // Memory cleanup handled automatically via RAII (unique_ptr in Visual)
    return 0;
}

#include <iostream>
#include <vector>
#include <string>
#include <algorithm>
#include <cmath>

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(NULL);

    unsigned int input_val;
    std::cin >> input_val;

    // Handle base case for k=1
    if (input_val == 1) {
        std::cout << 1 << std::endl;
        std::cout << "HALT PUSH 1 GOTO 1" << std::endl;
        return 0;
    }

    // Calculate q = (k-1)/2
    unsigned int half_diff = (input_val - 1) / 2;
    std::vector<int> binary_digits;

    // Convert q to binary (least significant bit first)
    unsigned int current_val = half_diff;
    if (current_val > 0) {
        while (current_val != 0) {
            binary_digits.push_back(current_val % 2);
            current_val /= 2;
        }
    }

    // Ensure we have bits for non-zero q
    if (binary_digits.empty() && half_diff > 0) {
        binary_digits.push_back(1);
    }

    // Reverse to get most-significant-bit first order
    std::reverse(binary_digits.begin(), binary_digits.end());

    // Determine number of bits needed
    int bit_count = static_cast<int>(binary_digits.size());
    if (half_diff == 0) bit_count = 0;

    // Total instructions count
    int total_instructions = bit_count + 3;
    std::cout << total_instructions << std::endl;

    // First instruction: entry point
    std::cout << "POP 1 GOTO 2 PUSH 1 GOTO 2" << std::endl;

    // Process each bit to generate middle instructions
    for (int pos = 0; pos < bit_count; ++pos) {
        int instruction_number = pos + 2;
        if (binary_digits[pos] == 1) {
            std::cout << "HALT PUSH 1 GOTO " << (instruction_number + 1) << std::endl;
        } else {
            std::cout << "POP 1 GOTO " << (bit_count + 2) 
                      << " PUSH 2 GOTO " << (instruction_number + 1) << std::endl;
        }
    }

    // Return mechanism instruction
    std::cout << "POP 1 GOTO 2 PUSH 2 GOTO " << (bit_count + 2) << std::endl;

    // Final halt instruction
    std::cout << "HALT PUSH 99 GOTO " << (bit_count + 2) << std::endl;

    return 0;
}

#include "server.hpp"
#include <boost/bind.hpp>
#include <signal.h>

namespace http {
namespace server {

// Constructor initializes the HTTP server with given address, port, and document root
server::server(const std::string& addr, const std::string& port_num,
    const std::string& doc_root)
  : service_context_(),
    termination_signals_(service_context_),
    listener_(service_context_),
    active_connections_(),
    incoming_connection_(),
    request_processor_(doc_root)
{
  // Set up signal handlers for graceful shutdown (e.g., Ctrl+C or kill command)
  termination_signals_.add(SIGINT);
  termination_signals_.add(SIGTERM);
#if defined(SIGQUIT)
  termination_signals_.add(SIGQUIT);
#endif // defined(SIGQUIT)

  // Start asynchronous wait for termination signals
  termination_signals_.async_wait(boost::bind(&server::on_shutdown_signal, this));

  // Prepare network endpoint using resolver
  asio::ip::tcp::resolver resolver(service_context_);
  auto endpoints = resolver.resolve(addr, port_num);
  auto ep = *endpoints.begin();

  // Configure acceptor to bind and listen on the resolved endpoint
  listener_.open(ep.protocol());
  listener_.set_option(asio::ip::tcp::acceptor::reuse_address(true));
  listener_.bind(ep);
  listener_.listen();

  // Begin accepting incoming connections
  initiate_accept();
}

// Main execution loop — blocks until all async operations complete
void server::run()
{
  service_context_.run();
}

// Initiate an asynchronous accept operation for a new connection
void server::initiate_accept()
{
  incoming_connection_.reset(new connection(service_context_,
        active_connections_, request_processor_));
  listener_.async_accept(incoming_connection_->socket(),
      boost::bind(&server::on_connection_accepted, this,
        asio::placeholders::error));
}

// Handle completion of an accept operation
void server::on_connection_accepted(const asio::error_code& ec)
{
  // Ignore if acceptor was closed (e.g., during shutdown)
  if (!listener_.is_open())
  {
    return;
  }

  // If no error occurred, start handling the new connection
  if (!ec)
  {
    active_connections_.start(incoming_connection_);
  }

  // Continue accepting more connections
  initiate_accept();
}

// Signal handler invoked when shutdown signal is received
void server::on_shutdown_signal()
{
  // Close acceptor to stop new connections
  listener_.close();

  // Terminate all currently active connections
  active_connections_.stop_all();
}

} // namespace server
} // namespace http

