// Test that invalid gzip data is properly rejected
TEST(PProfParserTest, RejectsInvalidGzipData) {
    // Gzip header bytes followed by non-compressed garbage content
    const char invalidGzip[] = "\x1f\x8b\x08\x00\x00\x00\x00\x00\x00\x03invalid_data";
    TStringBuf input(invalidGzip, sizeof(invalidGzip) - 1);
    NPerforator::NProto::NProfile::Profile profile;

    // Expect exception during decompression of malformed gzip stream
    EXPECT_THROW(
        NPerforator::NProfile::ConvertFromPProf(input, &profile),
        yexception
    );
}

// Test rejection of completely random binary data
TEST(PProfParserTest, RejectsRandomGarbage) {
    // Arbitrary byte sequence with no semantic meaning
    const char nonsense[] = "\xde\xad\xbe\xef\xca\xfe\xba\xbe";
    TStringBuf input(nonsense, sizeof(nonsense) - 1);
    NPerforator::NProto::NProfile::Profile profile;

    // Verify error message contains expected substring
    EXPECT_THROW_MESSAGE_HAS_SUBSTR(
        NPerforator::NProfile::ConvertFromPProf(input, &profile),
        yexception,
        "not a valid protobuf"
    );
}

// Test that empty input (empty protobuf) is accepted
TEST(PProfParserTest, AcceptsEmptyProfile) {
    // Empty buffer represents an empty but syntactically valid protobuf
    TStringBuf input;
    NPerforator::NProto::NProfile::Profile profile;

    // Should parse successfully without throwing
    EXPECT_NO_THROW(NPerforator::NProfile::ConvertFromPProf(input, &profile));
}

// Test handling of gzip-compressed empty protobuf
TEST(PProfParserTest, AcceptsGzipCompressedEmptyProfile) {
    // Build a valid gzip stream containing an empty protobuf
    TString compressedStream;
    {
        TStringOutput out(compressedStream);
        TZLibCompress compressor(&out, ZLib::GZip);
        // Write nothing; finish creates a valid gzip with empty payload
        compressor.Finish();
    }

    NPerforator::NProto::NProfile::Profile profile;

    // Ensure decompression and parsing succeeds for valid gzip + empty protobuf
    EXPECT_NO_THROW(NPerforator::NProfile::ConvertFromPProf(compressedStream, &profile));
}

