#include <vector>
#include <stack>
#include <unordered_map>
using namespace std;

// LeetCode 496: Next Greater Element I - Type III Clone
class Solution {
public:
    vector<int> nextGreaterElement(vector<int>& nums1, vector<int>& nums2) {
        vector<int> result;
        stack<int> decreasingStack;
        unordered_map<int, int> greaterValueMap; // maps each number to its next greater element

        // Traverse nums2 from right to left to compute next greater elements
        for (int idx = nums2.size() - 1; idx >= 0; --idx) {
            int current = nums2[idx];

            // Pop elements from stack that are less than or equal to current
            while (!decreasingStack.empty() && decreasingStack.top() <= current) {
                decreasingStack.pop();
            }

            // Determine the next greater element for current
            if (decreasingStack.empty()) {
                greaterValueMap[current] = -1;
            } else {
                greaterValueMap[current] = decreasingStack.top();
            }

            // Push current element onto the stack
            decreasingStack.push(current);
        }

        // Build the final answer by looking up values for nums1 elements
        for (int val : nums1) {
            result.push_back(greaterValueMap[val]);
        }

        return result;
    }
};

