#ifndef __has_feature
#define __has_feature(x) 0
#endif

#if __has_feature(memory_sanitizer)
#include <sanitizer/msan_interface.h>
#endif

// Invokes the user-provided traceback handler and then transfers control to sigtramp.
// This approach ensures proper stack unwinding by having a C function handle the call.
void x_cgo_callers(uintptr_t signal, void *siginfo, void *ctx, 
                   void (*userTraceback)(struct cgoTracebackArg*), 
                   uintptr_t *buffer, 
                   void (*signalHandler)(uintptr_t, void*, void*)) {
    struct cgoTracebackArg args;
    args.Context = 0;
    args.SigContext = reinterpret_cast<uintptr_t>(ctx);
    args.Buf = buffer;
    args.Max = 32; // Must correspond to the length of runtime.cgoCallers

#if __has_feature(memory_sanitizer)
    // This function is invoked directly from the signal handler.
    // Since arguments are passed via registers, memory sanitizer might not recognize
    // 'buffer' as initialized, potentially leading to false positives.
    // To prevent this, explicitly mark the memory region as initialized.
    // Refer to issue #47543 for further context.
    __msan_unpoison(&args, sizeof(args));
#endif

    _cgo_tsan_acquire();
    userTraceback(&args);
    _cgo_tsan_release();

    signalHandler(signal, siginfo, ctx);
}

