#include <mutex>
#include <queue>
#include <unordered_map>

namespace torch::comms {

// Helper alias for clarity
using StreamWorkQueue = std::queue<c10::intrusive_ptr<TorchWorkXCCL>>;

class TorchWorkXCCLQueue {
public:
    // Garbage-collect completed work items from internal queues
    // Returns final status observed during collection
    TorchWorkXCCL::WorkStatus garbageCollectLocked();

    // Thread-safe wrapper around garbageCollectLocked()
    TorchWorkXCCL::WorkStatus garbageCollect();

    // Finalize: drain all remaining work and return last status
    TorchWorkXCCL::WorkStatus finalize();

    // Add new work item to queue associated with given stream
    void enqueueWork(c10::intrusive_ptr<TorchWorkXCCL> work, xpuStream_t stream);

private:
    std::mutex work_queues_mutex_;
    std::unordered_map<xpuStream_t, StreamWorkQueue> stream_work_queues_;
};

TorchWorkXCCL::WorkStatus TorchWorkXCCLQueue::garbageCollectLocked() {
    TorchWorkXCCL::WorkStatus latest_result = TorchWorkXCCL::WorkStatus::COMPLETED;

    auto iter = stream_work_queues_.begin();
    while (iter != stream_work_queues_.end()) {
        auto& pending_tasks = iter->second;

        bool should_continue_queue = true;
        while (should_continue_queue && !pending_tasks.empty()) {
            auto current_task = pending_tasks.front();
            auto task_state = current_task->checkStatus();

            latest_result = task_state;

            switch (task_state) {
                case TorchWorkXCCL::WorkStatus::COMPLETED:
                    pending_tasks.pop();
                    break;

                case TorchWorkXCCL::WorkStatus::TIMEDOUT:
                case TorchWorkXCCL::WorkStatus::ERROR:
                    return task_state;

                default:
                    // NOT_STARTED or INPROGRESS — stop processing this stream’s queue
                    should_continue_queue = false;
                    break;
            }
        }

        if (pending_tasks.empty()) {
            iter = stream_work_queues_.erase(iter);
        } else {
            ++iter;
        }
    }

    return latest_result;
}

TorchWorkXCCL::WorkStatus TorchWorkXCCLQueue::garbageCollect() {
    std::lock_guard<std::mutex> guard(work_queues_mutex_);
    return garbageCollectLocked();
}

TorchWorkXCCL::WorkStatus TorchWorkXCCLQueue::finalize() {
    std::lock_guard<std::mutex> guard(work_queues_mutex_);

    TorchWorkXCCL::WorkStatus outcome = TorchWorkXCCL::WorkStatus::COMPLETED;

    // Drain all streams' queues until one returns terminal status
    while (!stream_work_queues_.empty()) {
        outcome = garbageCollectLocked();
        if (outcome == TorchWorkXCCL::WorkStatus::ERROR ||
            outcome == TorchWorkXCCL::WorkStatus::TIMEDOUT ||
            outcome == TorchWorkXCCL::WorkStatus::COMPLETED) {
            break;
        }
    }

    // Ensure no dangling references remain after finalization
    stream_work_queues_.clear();
    return outcome;
}

void TorchWorkXCCLQueue::enqueueWork(
    c10::intrusive_ptr<TorchWorkXCCL> task,
    xpuStream_t stream_id) {
    std::lock_guard<std::mutex> guard(work_queues_mutex_);
    stream_work_queues_[stream_id].push(std::move(task));
}

