#define TOPIC_JOYSTICK "rt/wirelesscontroller"

using namespace unitree::common;
using namespace unitree::robot;

class WirelessGamepadHandler
{
public:
    WirelessGamepadHandler() : running(true) {}

    // Initialize DDS communication layer
    void SetupDds(const std::string& iface = "")
    {
        ChannelFactory::Instance()->Init(0, iface);
        sub.reset(new ChannelSubscriber<unitree_go::msg::dds_::WirelessController_>(TOPIC_JOYSTICK));
        sub->InitChannel([this](const void* msg) { OnJoystickMsg(msg); }, 1);
    }

    // Configure smoothing factor for analog inputs
    void SetSmoothing(float value)
    {
        controller.smooth_factor = value;
    }

    // Configure dead zone for analog sticks
    void SetDeadZone(float zone)
    {
        controller.dead_zone_radius = zone;
    }

    // Thread-safe message handler
    void OnJoystickMsg(const void* raw_msg)
    {
        std::lock_guard<std::mutex> guard(data_mutex);
        last_msg = *static_cast<const unitree_go::msg::dds_::WirelessController_*>(raw_msg);
    }

    // Process one control cycle
    void Tick()
    {
        unitree_go::msg::dds_::WirelessController_ current;
        {
            std::lock_guard<std::mutex> guard(data_mutex);
            current = last_msg;
        }

        controller.Process(current);

        if (controller.btn_a.just_pressed())
        {
            button_presses++;
        }

        // Output debug info
        std::cout << "Left Stick X: " << controller.stick_x << "\n"
                  << "Button A - Pressed: " << controller.btn_a.is_down
                  << ", Just Pressed: " << controller.btn_a.just_pressed()
                  << ", Just Released: " << controller.btn_a.just_released()
                  << "\nPress count: " << button_presses
                  << "\n---------------------------\n";
    }

    // Launch background processing thread
    void Run()
    {
        worker = CreateRecurrentThreadEx("gamepad_worker", UT_CPU_ID_NONE, 40000,
                                         &WirelessGamepadHandler::Tick, this);
    }

    // Graceful shutdown helper
    void Stop()
    {
        running = false;
        if (worker && worker->IsRunning())
        {
            worker->Stop();
        }
    }

private:
    bool running;
    ChannelSubscriberPtr<unitree_go::msg::dds_::WirelessController_> sub;
    unitree_go::msg::dds_::WirelessController_ last_msg;
    Gamepad controller;
    std::mutex data_mutex;
    int button_presses = 0;
    ThreadPtr worker;
};

int main()
{
    WirelessGamepadHandler handler;

    // Configure sensitivity parameters
    handler.SetSmoothing(0.2f);
    handler.SetDeadZone(0.5f);

    // Start communication and processing
    handler.SetupDds();
    handler.Run();

    // Main loop with timeout-friendly exit condition
    auto start = std::chrono::steady_clock::now();
    while (handler.running && 
           std::chrono::duration_cast<std::chrono::seconds>(
               std::chrono::steady_clock::now() - start).count() < 60)
    {
        std::this_thread::sleep_for(std::chrono::milliseconds(20));
    }

    handler.Stop();
    return 0;
}

#include <iostream>
#include <vector>
#include <list>

// Function to perform a query
int query(const std::vector<int>& participants) {
    std::cout << "?";
    for (int p : participants) {
        std::cout << " " << p;
    }
    std::cout << std::endl;
    int result;
    std::cin >> result;
    if (result == -1) {
        exit(0); // Exit on error signal from interactor
    }
    return result;
}

void solve() {
    int n;
    std::cin >> n;

    // Create initial list of all elements
    std::list<int> available;
    for (int i = 1; i <= n * n; ++i) {
        available.push_back(i);
    }

    std::vector<int> sorted_result;
    int needed_count = n * n - n + 1;

    // Find required number of fastest elements
    for (int step = 0; step < needed_count; ++step) {
        // Use vector for easier indexing during races
        std::vector<int> current_list(available.begin(), available.end());

        // Continue until only one candidate remains
        while (current_list.size() > 1) {
            std::vector<int> race_entries;

            // Take up to n elements for this race
            for (int idx = 0; idx < n && idx < current_list.size(); ++idx) {
                race_entries.push_back(current_list[idx]);
            }

            int winner = query(race_entries);

            // Keep only the winner in next round
            current_list.clear();
            current_list.push_back(winner);
        }

        // The remaining element is the next fastest
        int found_element = current_list[0];
        sorted_result.push_back(found_element);
        available.remove(found_element);
    }

    // Output final sorted sequence
    std::cout << "!";
    for (size_t i = 0; i < sorted_result.size(); ++i) {
        std::cout << " " << sorted_result[i];
    }
    std::cout << std::endl;
}

int main() {
    // Fast I/O
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int test_cases;
    std::cin >> test_cases;
    while (test_cases--) {
        solve();
    }
    return 0;
}

#include <dolphin.h>
