// Initialize performance monitoring counters
void PMBegin(void) {
    // Clear all performance monitor control registers
    PPCMtmmcr0(0);
    PPCMtmmcr1(0);
    PPCMtpmc1(0);
    PPCMtpmc2(0);
    PPCMtpmc3(0);
    PPCMtpmc4(0);

    // Configure performance monitor for cycle counting and instruction metrics
    PPCMtmmcr0(0x4F);
    PPCMtmmcr1(0x78800000);
}

// Disable performance monitoring by resetting control registers
void PMEnd(void) {
    PPCMtmmcr0(0);
    PPCMtmmcr1(0);
}

// Read the cycle counter (PMC1)
u32 PMCycles(void) {
    return PPCMfpmc1();
}

// Read L1 instruction fetch misses (PMC2)
u32 PML1FetchMisses(void) {
    return PPCMfpmc2();
}

// Read cycles with L1 miss (PMC3)
u32 PML1MissCycles(void) {
    return PPCMfpmc3();
}

// Read total instructions retired (PMC4)
u32 PMInstructions(void) {
    return PPCMfpmc4();
}

