#include "Optimization/ModuleOptimizer.h"
#include <stdexcept>
#include <llvm/Analysis/CGSCCPassManager.h>
#include <llvm/Analysis/LoopAnalysisManager.h>
#include <llvm/IR/Module.h>
#include <llvm/IR/PassManager.h>
#include <llvm/Passes/PassBuilder.h>

namespace llvm_utils {
using namespace llvm;

/// @brief Apply LLVM's standard optimization pipeline to the provided module.
///
/// This function executes a sequence of transformation passes determined by
/// the requested optimization level. It sets up analysis managers for loops,
/// functions, call-graph SCCs, and modules, then runs the appropriate default
/// pipeline.
///
/// @param module Pointer to the LLVM module to be optimized (must not be null)
/// @param level The desired optimization level:
///   - OptimizationLevel::O0: Skip optimizations (ideal for debugging)
///   - OptimizationLevel::O1: Minimal transformations
///   - OptimizationLevel::O2: Balanced optimizations (typical release setting)
///   - OptimizationLevel::O3: Maximum aggressiveness (may expand binary size)
///
/// @return PreservedAnalyses indicating which analyses remained valid after
///         the optimization process
///
/// @throws std::invalid_argument if module is nullptr
auto optimiseModule(Module *module, OptimizationLevel level)
    -> PreservedAnalyses {
  if (!module)
    throw std::invalid_argument("Null pointer argument!");

  LoopAnalysisManager loopAM;
  FunctionAnalysisManager funcAM;
  CGSCCAnalysisManager cgsccAM;
  ModuleAnalysisManager modAM;

  PassBuilder pb;
  pb.registerModuleAnalyses(modAM);
  pb.registerCGSCCAnalyses(cgsccAM);
  pb.registerFunctionAnalyses(funcAM);
  pb.registerLoopAnalyses(loopAM);
  pb.crossRegisterProxies(loopAM, funcAM, cgsccAM, modAM);

  return pb.buildPerModuleDefaultPipeline(level).run(*module, modAM);
}
} // namespace llvm_utils

#include "ReduceInstructions.h"
#include "Utils.h"
#include "llvm/IR/Constants.h"
#include <vector>
#include <unordered_set>
using namespace llvm;

// Helper: determines if an instruction must never be removed
static bool mustPreserve(const Instruction &I) {
  // Preserve EH pads, token-typed instructions, and Swift error instructions
  return I.isEHPad() || I.getType()->isTokenTy() || I.isSwiftError();
}

// Extracts non-essential instructions from the module for deletion
static void stripUnusedInstructions(Oracle &O, ReducerWorkItem &WorkItem) {
  Module &M = WorkItem.getModule();
  std::vector<Instruction *> keepList;

  // First pass: collect instructions that must be retained
  for (Function &F : M) {
    for (BasicBlock &BB : F) {
      // Always keep the terminator — removing it would break CFG structure
      keepList.push_back(BB.getTerminator());

      // Iterate over non-terminator instructions
      auto endIt = std::prev(BB.end());
      for (auto I = BB.begin(); I != endIt; ++I) {
        const Instruction &inst = *I;
        if (mustPreserve(inst) || O.shouldKeep()) {
          keepList.push_back(&inst);
        }
      }
    }
  }

  // Convert vector to unordered_set for efficient lookup
  std::unordered_set<Instruction *> keepSet{keepList.begin(), keepList.end()};

  // Second pass: identify deletable instructions
  std::vector<Instruction *> toDelete;
  for (Function &F : M) {
    for (BasicBlock &BB : F) {
      for (Instruction &inst : BB) {
        if (!keepSet.count(&inst)) {
          // Replace all uses before deletion to avoid IR invalidity
          inst.replaceAllUsesWith(getDefaultValue(inst.getType()));
          toDelete.push_back(&inst);
        }
      }
    }
  }

  // Final pass: erase collected instructions
  for (Instruction *inst : toDelete) {
    inst->eraseFromParent();
  }
}

// Expose delta pass entry point
void llvm::reduceInstructionsDeltaPass(TestRunner &Test) {
  runDeltaPass(Test, stripUnusedInstructions, "Reducing Instructions");
}

#include <iostream>
#include <cmath>

// Recursive function to solve Tower of Hanoi
// Parameters: count (number of disks), start (source peg), end (target peg), temp (auxiliary peg)
void hanoi_solver(int count, int start, int end, int temp) {
    if (count <= 0) {
        return;
    }

    // Move top (count-1) disks from start to temp using end as auxiliary
    hanoi_solver(count - 1, start, temp, end);

    // Move the largest disk from start to end
    std::cout << start << " " << end << "\n";

    // Move the (count-1) disks from temp to end using start as auxiliary
    hanoi_solver(count - 1, temp, end, start);
}

int main() {
    // Optimize I/O operations
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int disk_count;
    std::cin >> disk_count;

    // Calculate total moves: 2^disk_count - 1
    long long total_moves = (1LL << disk_count) - 1;
    std::cout << total_moves << "\n";

    // Only print actual moves if there are disks to move
    if (disk_count > 0) {
        hanoi_solver(disk_count, 1, 3, 2);
    }

    return 0;
}

