int APIENTRY wWinMain(_In_ HINSTANCE instance, _In_opt_ HINSTANCE prev,
                      _In_ wchar_t *command_line, _In_ int show_command) {
  // Attach to existing console (if available) or create a new one for debugging
  if (!::AttachConsole(ATTACH_PARENT_PROCESS) && ::IsDebuggerPresent()) {
    CreateAndAttachConsole();
  }

  // Initialize COM library for thread-safe operations
  ::CoInitializeEx(nullptr, COINIT_APARTMENTTHREADED);

  // Setup Flutter project with Dart entrypoint
  flutter::DartProject project(L"data");
  std::vector<std::string> args = GetCommandLineArguments();
  project.set_dart_entrypoint_arguments(std::move(args));

  // Configure window dimensions and position
  flutter::FlutterWindow flutter_window(project);
  Win32Window::Point top_left(10, 10);
  Win32Window::Size dimensions(1280, 720);

  // Attempt to create the Flutter window
  if (!flutter_window.Create(L"flutter_engine_bridge_example", top_left, dimensions)) {
    return EXIT_FAILURE;
  }

  // Ensure application exits when window is closed
  flutter_window.SetQuitOnClose(true);

  // Main message loop for Windows messages
  ::MSG message;
  while (::GetMessage(&message, nullptr, 0, 0)) {
    ::TranslateMessage(&message);
    ::DispatchMessage(&message);
  }

  // Cleanup COM resources
  ::CoUninitialize();
  return EXIT_SUCCESS;
}

