#include <vector>
using namespace std;

class Solution {
public:
    int maxFrequencyElements(vector<int>& nums) {
        int frequencyCount[101] = {0};
        int highestFrequency = 0;
        int countOfMaxFreqElements = 0;

        // First pass: find the maximum frequency
        for (int value : nums) {
            frequencyCount[value]++;
            if (frequencyCount[value] > highestFrequency) {
                highestFrequency = frequencyCount[value];
            }
        }

        // Second pass: count how many elements have this maximum frequency
        for (int i = 1; i <= 100; i++) {
            if (frequencyCount[i] == highestFrequency) {
                countOfMaxFreqElements++;
            }
        }

        return countOfMaxFreqElements * highestFrequency;
    }
};

#include <iostream>
#include <string>
#include "asio.hpp"
#include "boost/bind.hpp"

const short mcast_port = 30001;

class udp_listener
{
public:
  udp_listener(asio::io_context& context,
      const asio::ip::address& bind_addr,
      const asio::ip::address& group_addr)
    : sock_(context)
  {
    // Configure socket for reuse and binding
    asio::ip::udp::endpoint ep(bind_addr, mcast_port);
    sock_.open(ep.protocol());
    sock_.set_option(asio::ip::udp::socket::reuse_address(true));
    sock_.bind(ep);

    // Subscribe to the multicast group
    sock_.set_option(asio::ip::multicast::join_group(group_addr));

    // Start asynchronous receive operation
    sock_.async_receive_from(
        asio::buffer(buffer_, capacity),
        remote_,
        boost::bind(&udp_listener::on_data_arrival, this,
          asio::placeholders::error,
          asio::placeholders::bytes_transferred));
  }

  void on_data_arrival(const asio::error_code& ec, size_t length)
  {
    if (!ec)
    {
      std::cout.write(buffer_, length);
      std::cout << std::endl;

      // Continue listening for more messages
      sock_.async_receive_from(
          asio::buffer(buffer_, capacity), remote_,
          boost::bind(&udp_listener::on_data_arrival, this,
            asio::placeholders::error,
            asio::placeholders::bytes_transferred));
    }
  }

private:
  asio::ip::udp::socket sock_;
  asio::ip::udp::endpoint remote_;
  static const size_t capacity = 1024;
  char buffer_[capacity];
};

int main(int argc, char* argv[])
{
  try
  {
    if (argc != 3)
    {
      std::cerr << "Usage: receiver <listen_address> <multicast_address>\n";
      std::cerr << "  For IPv4, try:\n";
      std::cerr << "    receiver 0.0.0.0 239.255.0.1\n";
      std::cerr << "  For IPv6, try:\n";
      std::cerr << "    receiver 0::0 ff31::8000:1234\n";
      return 1;
    }

    asio::io_context io_ctx;
    udp_listener listener(io_ctx,
        asio::ip::make_address(argv[1]),
        asio::ip::make_address(argv[2]));

    io_ctx.run();
  }
  catch (const std::exception& ex)
  {
    std::cerr << "Error: " << ex.what() << "\n";
    return 1;
  }

  return 0;
}

