namespace engine::store::filter::parse::Tika {
namespace {
//-----------------------------------------------------------------
/// @details
///		Flag to indicate we have already initialized the tika
///		side of the engine
//-----------------------------------------------------------------
bool s_engineInitialized = false;
}  // namespace

//-----------------------------------------------------------------
/// @details
///		This function will initialize the global java environment
///		for use with Tika
//-----------------------------------------------------------------
Error TikaGlobal::begin(IServiceConfig &config) noexcept {
    const auto _initialize = localfcn()->Error {
        // Skip if already initialized
        if (s_engineInitialized) return {};

        // Initialize the Java runtime
        if (auto err = java::init()) return err;

        // Acquire JNI interface pointer
        GET_JAVA_JNI(jni);

        // Load Tika API bindings
        auto apiMethods = TikaApi(jni);

        // Determine configuration directory
        auto configRoot = java::rootDir();

        // Log initialization start
        LOGT("Starting parsing engine setup...");

        // Register native method callbacks
        registerTikaCallbacks();

        // Configure root path in Java static field
        apiMethods.m_jni.setStaticField(apiMethods.m_class,
                                        apiMethods.m_rootPathFieldId,
                                        _ts(configRoot.plat(false)));

        // Trigger Java-side initialization
        apiMethods.m_jni.invokeStaticMethod(apiMethods.m_class,
                                            apiMethods.m_initMethodId);

        // Schedule cleanup callback for JVM shutdown
        java::addDeinitCallback([](java::Jni &jniRef) noexcept(false) {
            // Ensure proper shutdown to avoid hanging due to pending tasks
            LOG(Parse, "Shutting down parsing engine");

            auto methods = TikaApi(jniRef);
            jniRef.invokeStaticMethod(methods.m_class,
                                      methods.m_deinitMethodId);
        });

        // Mark as successfully initialized
        s_engineInitialized = true;
        return {};
    };

    // Execute initialization logic
    if (auto result = _callChk(_initialize)) {
        LOGT("Initialization of parsing engine failed");
        return result;
    } else {
        LOGT("Parsing engine initialized successfully");
        return {};
    }
}

//-----------------------------------------------------------------
/// @details
///		This function will deinit and unload the java engine
///	@returns
///		Error
//-----------------------------------------------------------------
Error TikaGlobal::end() noexcept {
    // Deinitialization is handled automatically via registered callbacks
    return {};
}
