#include <Application.h>
#include <Entry.h>
#include <Directory.h>
#include <FindDirectory.h>
#include <Path.h>
#include <Volume.h>
#include <Query.h>
#include <stdio.h>
#include <string.h>

class CommentFileFinder : public BApplication
{
public:
    CommentFileFinder()
        : BApplication("application/x-vnd.kitlab-commentfilefinder")
    {
        ExecuteSearch();
        Quit();
    }

private:
    void ExecuteSearch()
    {
        // --- Identify the user's home directory ---
        BPath userHome;
        if (find_directory(B_USER_DIRECTORY, &userHome) != B_OK) {
            fprintf(stderr, "Error: Could not locate user home directory.\n");
            return;
        }

        BDirectory dir(userHome.Path());
        BVolume vol;
        if (dir.GetVolume(&vol) != B_OK) {
            fprintf(stderr, "Error: Unable to retrieve volume for home directory.\n");
            return;
        }

        // --- Output search context ---
        printf("Scanning location: %s\n", userHome.Path());
        printf("Targeting files with 'Comment' metadata.\n\n");

        const char* targetMimeType = "text/plain";

        // --- Build and execute the query ---
        BQuery searchQuery;
        searchQuery.SetVolume(&vol);

        // Condition 1: MIME type must be text/plain
        searchQuery.PushAttr("BEOS:TYPE");
        searchQuery.PushString(targetMimeType);
        searchQuery.PushOp(B_EQ);

        // Condition 2: Must have a non-empty 'Comment' attribute
        searchQuery.PushAttr("Comment");
        searchQuery.PushString("*");
        searchQuery.PushOp(B_EQ);

        // Combine both conditions with logical AND
        searchQuery.PushOp(B_AND);

        if (searchQuery.Fetch() != B_OK) {
            fprintf(stderr, "Error: Query execution failed.\n");
            return;
        }

        // --- Process matching entries ---
        entry_ref reference;
        int foundCount = 0;

        while (searchQuery.GetNextRef(&reference) == B_OK) {
            BEntry item(&reference);
            BPath fullPath(&item);

            // Ensure the result is within the user's home directory
            if (strncmp(fullPath.Path(), userHome.Path(), strlen(userHome.Path())) == 0) {
                printf("Match: %s\n", fullPath.Path());
                foundCount++;
            }
        }

        // --- Report no matches found ---
        if (foundCount == 0)
            printf("No files containing a 'Comment' attribute were found.\n");
    }
};

int main(int argc, char** argv)
{
    CommentFileFinder finder;
    finder.Run();
    return 0;
}

